-- 自动生成：仅含中文译文与匹配指纹。来源见 SOURCES.md。
local D = LegionChineseDB
D.Strings[78292]="不投降就得死！"
D.Strings[78293]="燃烧军团是永恒不灭的。"
D.Strings[78294]="你迟早会……倒下的……"
D.Strings[78295]="列阵！"
D.Strings[78296]="击退袭击者！"
D.Strings[78297]="我的恨意……熊熊燃烧……"
D.Strings[78298]="你的下场将和我们一样！"
D.Strings[78299]="后退，否则就死！"
D.Strings[78300]="保护要塞！"
D.Strings[78301]="奇怪。我没有感到疼……"
D.Strings[78302]="我的灵魂……自由了……"
D.Strings[78303]="我可以……安息了……"
D.Strings[78304]="这是我们的屠宰房！"
D.Strings[78305]="但愿你比那些鸟人能打一些！"
D.Strings[78306]="你的皮可以做一条不错的腰带。"
D.Strings[78307]="终于有一个挑战者了！"
D.Strings[78308]="继续，求饶吧！"
D.Strings[78309]="我会给你留下一道足以自豪的疤痕的！"
D.Strings[78310]="算你走运，杂种！"
D.Strings[78311]="让我痛苦吧！"
D.Strings[78312]="卡加斯会生气的……"
D.Strings[78313]="如此……荣耀的……痛苦……"
D.Strings[78314]="我给你准备了一个空钩子。"
D.Strings[78315]="你一定觉得自己很走运。"
D.Strings[78316]="你想跟这些野兽关在一起吗？"
D.Strings[78317]="很好。又有皮可以剥了！"
D.Strings[78318]="让我听听你的尖叫声！"
D.Strings[78319]="这……才是真正的痛苦……"
D.Strings[78320]="你别想活着离开这里。"
D.Strings[78321]="我的精神从没……这么好过……"
D.Strings[78322]="把我挂在钩子上……"
D.Strings[78323]="就像在竞技场里一样！"
D.Strings[78324]="我要放干你的血！"
D.Strings[78325]="你一定会喜欢痛苦的滋味的。"
D.Strings[78326]="去死吧，小崽子！"
D.Strings[78327]="小身材，大天赋！"
D.Strings[78328]="我的力量是无穷的！"
D.Strings[78329]="剑、剑、剑、剑刃风暴！"
D.Strings[78330]="这是我的地盘！"
D.Strings[78331]="别浪费时间去跟祖格比试了，他是个输不起的小气鬼。$B$B别告诉他这是我说的。"
D.Strings[78332]="命令就是命令。"
D.Strings[78333]="要是麦克斯在就好了。"
D.Strings[78334]="我跟玛儿·野蹄说，我愿意去探索除祭坛外的任何地方。我能对付食人魔，可幽灵食人魔要怎么对付？抱歉，但它们真的吓到我了。"
D.Strings[78335]="我都不知道你怎么能跟那个畜生祖格搭上话。哪怕是对兽人来说，他也太野蛮了。"
D.Strings[78336]="你就是个累赘！"
D.Strings[78337]="至于你，你太差劲了。"
D.Strings[78338]="我原本正背着满满一袋子神器返回战争之矛，结果被几个联盟的渣滓抢走了。在外面一定要小心点，$n。"
D.Strings[78339]="你拖慢了我的脚步，我只能把你放倒了。"
D.Strings[78340]="我就是闪电！"
D.Strings[78341]="你不是闪电！你是雷霆！自然与能量之力！"
D.Strings[78342]="噢！对。我是雷霆，自然的。"
D.Strings[78343]="对，它自然会找上你的。"
D.Strings[78344]="但你是闪电，我们一起……电花四射！"
D.Strings[78345]="去死！！"
D.Strings[78346]="死吧！！！"
D.Strings[78347]="测试，失败！"
D.Strings[78348]="你的技术不过关。"
D.Strings[78349]="我认为你的努力还不够。"
D.Strings[78350]="你失败了。"
D.Strings[78351]="被暗影淹没吧！"
D.Strings[78352]="你好，指挥官。还有一些志愿者想要加入我们的要塞。我会帮你整理好合同，以便你在闲暇时查阅。"
D.Strings[78353]="我没时间闲聊，大元帅泰布雷德急需坦克帮忙对付部落。$B$B我把扳手放哪儿了……"
D.Strings[78354]="如果你在外面碰上部落的人，就用比克茜·火槽的求援信号弹吧。附近的联盟成员肯定会来帮助你的。"
D.Strings[78355]="我们还有很多需要训练的坐骑。但它们不如你的坐骑那么吃苦耐劳，经过几场战斗之后就会精疲力尽了。"
D.Strings[78356]="你还有需要训练的坐骑吗？"
D.Strings[78357]="我想要训练中的塔布羊。"
D.Strings[78358]="我想要训练中的裂蹄牛。"
D.Strings[78359]="我想要训练中的野猪。"
D.Strings[78360]="我想要训练中的雷象。"
D.Strings[78361]="我想要训练中的狼。"
D.Strings[78362]="我想要训练中的淡水兽。"
D.Strings[78363]="哈里森·琼斯相信神器就在矿井里。如果这是真的，那么下一阶段的战斗就将在地下展开。$B$B那里会有什么新危险等着我们呢？这就是我想要知道的。"
D.Strings[78364]="虽然和部落的战斗都发生在荣耀之路上，但我们也要集中力量找到神器。天知道它会在哪儿呢。$B$B不要放过岛上的任何一块石头。我们必须抢在部落前头找到神器。"
D.Strings[78365]="没有攻城器械的话，我们怎么可能战胜部落？"
D.Strings[78366]="要是我们有一艘飞艇就好了。我们可以从空中炸烂战争之矛！"
D.Strings[78367]="我们必须将所有人手都集中到矿井里。我同意琼斯博士的看法，神器肯定就在那里！肯定的！"
D.Strings[78368]="和之前担心的一样，我们必须进入矿井了。天知道里面有什么古老的威胁呢……"
D.Strings[78369]="停战？和联盟？想都别想。"
D.Strings[78370]="潜行者间谍发回消息说联盟正在建造钻石头的机器。你说这会是为矿井准备的吗？"
D.Strings[78371]="你看见我们的部队里有多少死亡骑士了吗？那我们为什么还是无法攻进暴风之盾呢？他们都不使用死疽的吗？"
D.Strings[78372]="要是我们能把地精飞艇运过传送门就好了。那我们就能从空中炸烂暴风之盾了！"
D.Strings[78373]="奥格瑞姆的征途到此为止了。我会让我的老朋友得到他应有的下场的。"
D.Strings[78374]="沙塔斯绝不会再次陷落。让我们彻底埋葬这些钢铁部落的走狗吧。"
D.Strings[78375]="玛尔拉德所做的一切……都是为了保护我们的人民。"
D.Strings[78376]="他为我们的自由付出了最终的代价。我们决不能忘了他的牺牲。"
D.Strings[78377]="谢谢你所做的一切，$n。如果没有你……我们都会葬身于此。"
D.Strings[78378]="奥格瑞姆做了他认为对的事。他不知道自己走上了一条什么样的道路。"
D.Strings[78379]="我不会忘记你的……老朋友。"
D.Strings[78380]="我不会忘记你的帮助的，$n。如果没有你，我们都会死在黑手的手中。"
D.Strings[78381]="谢谢你！我们绝不可能独自打败那头魔像。"
D.Strings[78382]="你不配踏入竞技场！"
D.Strings[78383]="哈！你根本算不上什么角斗士！"
D.Strings[78384]="你来错地方了，小崽子！"
D.Strings[78385]="你也会死在竞技场里……"
D.Strings[78386]="我很强……可你更强……"
D.Strings[78387]="我要……碾碎……你……"
D.Strings[78388]="圣光赐予我们力量！"
D.Strings[78389]="英灵在注视着我们！"
D.Strings[78390]="我们与黑暗势不两立。"
D.Strings[78391]="前进。为了奥金顿！"
D.Strings[78392]="奥金顿在欢迎我……"
D.Strings[78393]="黑暗降临到了我们头上……"
D.Strings[78394]="想看个戏法吗？"
D.Strings[78395]="这应该会有趣的。"
D.Strings[78396]="但愿你穿的是火抗护甲。"
D.Strings[78397]="你可能会觉得有点烫。"
D.Strings[78398]="我只是想让你暖和一下。"
D.Strings[78399]="这儿是不是有点热？还是我的错觉？"
D.Strings[78400]="好了好了，别把什么烧焦了的事都怪到我头上。"
D.Strings[78401]="这是难免的，真的。"
D.Strings[78402]="你需要施放什么法术吗，指挥官？你要开传送门吗？你有什么恶魔计划需要执行吗？"
D.Strings[78403]="今天真是个好日子，最适合在要塞里走走了，指挥官。"
D.Strings[78404]="这不……酷……"
D.Strings[78405]="我的火焰熄灭了……"
D.Strings[78406]="你想跟我斗，嗯？"
D.Strings[78407]="我发现一个。在这儿！"
D.Strings[78408]="你这是罪有应得。"
D.Strings[78409]="你也不怎么厉害嘛。"
D.Strings[78410]="或许下次你该三思而行！等等……"
D.Strings[78411]="我成功了！我干掉一个了！"
D.Strings[78412]="嘿，指挥官！有适合我的任务吗？我已经准备好了！"
D.Strings[78413]="很高兴见到你！"
D.Strings[78414]="我能为你做什么吗，指挥官？"
D.Strings[78415]="指挥官！这是我的荣幸。"
D.Strings[78416]="这里是不是有点热？还是我的错觉……"
D.Strings[78417]="我……尽力了……"
D.Strings[78418]="我很抱歉，指挥官……"
D.Strings[78419]="（野兽控制）把暗影莓给戈拉看。"
D.Strings[78420]="<戈拉嗅了嗅暗影莓，然后充满期待地看着你。>"
D.Strings[78421]="我的灵魂……可以安息了……谢谢你。"
D.Strings[78422]="（野兽控制）我跟影月氏族没有关系，我想帮助这头狼！"
D.Strings[78423]="在我们抛弃萨满教，转投这些……黑暗魔法之前，戈拉曾是我的狼。在我被虚空腐蚀之后，她甚至不愿意再看我一眼。"
D.Strings[78424]="你竟敢让她的灵魂安息！奥姆拉的灵魂是属于虚空的！"
D.Strings[78425]="我带走这头狼作为补偿！"
D.Strings[78426]="你的灵魂将喂饱虚空！"
D.Strings[78427]="你休想逃出虚空的掌心！你的灵魂将被它吞噬！"
D.Strings[78428]="她正在被虚空吞噬！你必须帮帮她！这只有一个办法，驯服她，快！或许你能找出逆转这个过程的方法，并让她的灵魂安息，就像你对我所做的一样！"
D.Strings[78429]="你成功了……谢谢你。再见，戈拉，我的灵魂已经安息了。我希望……有一天你也能这样安息。我很抱歉，亲爱的戈拉。"
D.Strings[78430]="你本能地使用威慑躲开了攻击！"
D.Strings[78431]="你的追踪技巧让你能够继续停留在这个领域！"
D.Strings[78432]="你被拉入了虚空领域！"
D.Strings[78433]="我要吞噬一切！"
D.Strings[78434]="对抗战歌氏族的战斗是高尚的，可我觉得赫米特并不太适应自己在纳格兰的角色变化。"
D.Strings[78435]="蠢货！你竟敢挑战怨叶的力量？去死吧！"
D.Strings[78436]="寒冬……降临了……"
D.Strings[78437]="主人……会烧尽你的灵魂！"
D.Strings[78438]="快了 ……你马上就要死了……"
D.Strings[78439]="我们的主人将吞噬你的灵魂……"
D.Strings[78440]="你无法阻止毁灭……"
D.Strings[78441]="不……该死的人是你！"
D.Strings[78442]="不！不……不……黑暗……"
D.Strings[78443]="虚空降临了……它将毁灭你们所有人！"
D.Strings[78444]="你这蠢货……我们已经……赢了……"
D.Strings[78445]="嘿……你以为会是什么？霜之哀伤还是别的什么吗？"
D.Strings[78446]="让你有点自知之明。"
D.Strings[78447]="我连发型都没乱。"
D.Strings[78448]="这就是我来此的原因。"
D.Strings[78449]="我想返回鸦巢。"
D.Strings[78450]="呃，我在渴望鲜血！"
D.Strings[78451]="喔唷！我错了！"
D.Strings[78452]="全球化！"
D.Strings[78453]="玩死你！"
D.Strings[78454]="我想订购一批皮革。"
D.Strings[78455]="我想订购一大批皮革。"
D.Strings[78456]="我想订购一批肉类。"
D.Strings[78457]="我想订购一大批肉类。"
D.Strings[78458]="我想订购一批毛皮。"
D.Strings[78459]="我想订购一大批毛皮。"
D.Strings[78460]="<这位好医生散发着旅店地板的味道，脸上的表情好像刚刚经历了五英里的颠簸。他的脸上没有一丝血色，而且正极力不吐在你的脚上。>$b$b嘿，指——挥官！<呕>我昨天晚上跟宾奇维斯喝得太凶了。不过我还是赶回来报到了！长官！ <呕吐>伙计，你从昨天起为这座要塞干了不少事儿啊。用尖刺、毛皮，还有……雪？这是你干的吗？我得坐下了。"
D.Strings[78461]="联盟击杀了加隆·落烬！"
D.Strings[78462]="部落击杀了瑞莱·克雷斯弗！"
D.Strings[78463]="你需要分析报告吗？我可以在周末的时候做好。"
D.Strings[78464]="等这里的事都搞定之后，我们去海滩上喝一杯怎么样？"
D.Strings[78465]="如果你要去黑森林，请留意一下盛开的欢歌花。它们有强大的魔法成分。$B$B但你可能得击败一些鸦人才能得到它们。"
D.Strings[78466]="给我介绍一下训练中的坐骑吧。"
D.Strings[78467]="暗夜精灵正试图用阿什兰找到的神器力量来复活一棵古树，并用来对付我们。$B$B如果你在外面遇见联盟的人，务必不择手段地抢走他们身上的碎片。"
D.Strings[78468]="我们根据你的指示，一直在捕捉并训练坐骑以供要塞里的其他人使用。你每天也可以选一头坐骑。只要你开口，我就把哨子给你。$B$B但记住，它们不像你自己的坐骑那么训练有素，几场战斗就能让它们精疲力尽了。"
D.Strings[78469]="我们根据你的指示，一直在捕捉并训练坐骑以供要塞使用。当然，你每天也可以选一头坐骑。只要你开口，我就会把你想要的哨子给你。$B$B记住，它们不像你自己的坐骑那么训练有素，几场战斗就能让它们精疲力尽了。"
D.Strings[78470]="乍看之下，征服竞技场附近的火盆中冒出的火焰似乎很平常。可我相信它们都是被施展过古代悬槌魔法的。$B$B我总是很诡异地被它们所吸引。只要碰一碰那些火盆，我的体内就会突然充满了魔力。"
D.Strings[78471]="如果你在荣耀之路看到我们的牧师遭到攻击，请保护他们。$B$B他们都是我一手训练出来的，有着黑暗之门这一边最出色的治疗技术。"
D.Strings[78472]="我对今天能来到这里感到超级激动！"
D.Strings[78473]="|TInterface\\Icons\\spell_sandexplosion.blp:20|t你身上有一颗|cFFFF0000|Hspell:155187|h[炸弹]|h|r！"
D.Strings[78474]="|TInterface\\Icons\\Spell_Fire_LavaSpawn.blp:20|t你受到了召火者的|cFFFF0000|Hspell:176121|h[不稳定的火焰]|h|r的影响！"
D.Strings[78475]="|TInterface\\Icons\\ability_rhyolith_magmaflow_whole.blp:20|t监工长石即将在你的脚下制造一次|cFFFF0000|Hspell:156934|h[崩裂]|h|r！"
D.Strings[78476]="|TInterface\\Icons\\ability_foundryraid_melt.blp:20|t山脉之心即将|cFFFF0000|Hspell:155225|h[熔化]|h|r你脚下的地面！"
D.Strings[78477]="|TInterface\\Icons\\ability_garrosh_hellscreams_warsong.blp:20|t%s开始施放|cFFF00000|Hspell:160838|h[干扰怒吼]|h|r！"
D.Strings[78478]="|TInterface\\Icons\\ability_warrior_dragonroar.blp:20|t%s开始施放|cFFFF0000|Hspell:177477|h[巨龙怒吼]|h|r！"
D.Strings[78479]="如果你想了解宠物对战的信息，就去找蜜丝蒂·缠网吧。\n\n我想她应该就在旅店的地窖里。但愿她的宠物不会跑得太远。"
D.Strings[78480]="一群虚灵在安多玛斯高塔的下层开设了商店。 \n\n如果你想使用他们的幻化或虚空仓库服务，就去那里找他们吧。"
D.Strings[78481]="不管是你想赚钱还是花钱，泰隆一家和他们的伙伴应该可以帮你。\n\n他们的商店就开在市政厅门口那条的路的边上，紧邻着鸦人难民的住处。"
D.Strings[78482]="探险者协会的矮人们已经允许冒险者们使用铜须的仓库在储存自己的多余的物品了。\n\n那座顶上架着大炮的巨型金属建筑就在镇中心。你不会认错的。"
D.Strings[78483]="如果你想骑着狮鹫旅行，可以去和我们的狮鹫管理员恩斯特·坦恩·博世谈谈。 \n\n他就在山顶上，走过餐厅就到了。"
D.Strings[78484]="如果你想放松 一下，或许可以去英雄之眠旅店。加西亚会为你准备一间房间和一杯啤酒的。\n\n你只要沿着穿过石墙的路往西走，就能找到它了。"
D.Strings[78485]="我们有好几个邮箱。你具体想找哪一个呢？"
D.Strings[78486]="那个邮箱就在镇中央的铜须的仓库外面。\n\n那是一座顶上架着火炮的巨型金属建筑。"
D.Strings[78487]="那个邮箱就在英雄之眠旅店的边上。\n\n你只要沿着穿过石墙的路往西走，就能在山脚下找到那座旅店了。"
D.Strings[78488]="议政厅"
D.Strings[78489]="你可以在市政厅外面找到另一个邮箱。\n\n议政厅就在镇子的南部，走过中央纪念碑就到了。"
D.Strings[78490]="我们的法师在定居点各处开设了好几座通往不同地方的传送门。\n\n你想去哪里呢？"
D.Strings[78491]="通往达纳苏斯的传送门就在暴风之盾东部的暗夜精灵月亮井附近。\n\n沿着拍卖行门口的大路走，你就能找到它了。"
D.Strings[78492]="通往铁炉堡的传送门自然就在铜须的仓库外面。你可以在那幢建筑的南边找到它。\n\n铜须的仓库就是镇中央那座顶上架着火炮的巨型金属建筑。"
D.Strings[78493]="通往暴风城的传送门就在安多玛斯高塔外面。\n\n只要沿着铜须的仓库门口的路走，你就能看见那座塔了。"
D.Strings[78494]="你想学习哪种专业技能呢？"
D.Strings[78495]="看来钢铁部落已经行动了。士兵们！把镇民们送到安全的地方去！"
D.Strings[78496]="我们的常驻炼金师贾登·塔斯克非常了解德拉诺炼金术的秘诀。 \n\n你可以在镇子南部的英雄之眠旅店外找到他。"
D.Strings[78497]="我们的常驻考古学家，曼达·达洛维在暴风之盾中央的兵营外面开了一家商店。\n\n她有一个古怪的鸦人伙伴，她或许可以帮助你。"
D.Strings[78498]="我也是！"
D.Strings[78499]="艾米·金炉是本地的锻造专家。\n\n你可以在暴风之盾中央的铜须的仓库外的露天熔炉那里找到她和她的员工。"
D.Strings[78500]="如果你想找镇上最好的厨师，那就去英雄之眠旅店找埃尔顿·布莱克。\n\n他身上那些零碎的小玩意儿看起来可能有点蠢，但他很擅长烹调美食。"
D.Strings[78501]="祝你今天交好运！"
D.Strings[78502]="如果你想学习附魔，比尔·星酒就是暴风之盾最渊博的附魔师，只是要小心他推销的那些“打折”商品。\n\n你可以在拍卖行后面找到他和他的助手鲍勃。他们就在那里叫卖自己的商品。"
D.Strings[78503]="|TInterface\\Icons\\Spell_Shadow_SoulLeech_2.blp:20|t%s开始施放|cFFF00000|Hspell:153477|h[灵魂容器]|h|r！"
D.Strings[78504]="希尔达·铜丝是暴风之盾的首席工程师。\n\n你可以在镇中心的工坊里找到她。"
D.Strings[78505]="|TInterface\\Icons\\inv_elemental_crystal_fire.blp:20|t你已经成为了|cFFFF0000|Hspell:160282|h[日光爆炸]|h|r的目标！快远离你的盟友！"
D.Strings[78506]="$n制造了一件旋风法器！"
D.Strings[78507]="一辆烈焰坦克正在接近！"
D.Strings[78508]="墓地争夺战将在3分钟开始！"
D.Strings[78509]="我终于……可以安息了……"
D.Strings[78510]="折磨结束了……"
D.Strings[78511]="感谢你的仁慈……"
D.Strings[78512]="请……别让我们被遗忘……"
D.Strings[78513]="刃牙虎人的攻击结束了。去吧，安息吧。"
D.Strings[78514]="请一定要救救我们！刃牙虎人来了，我们的生命危在旦夕！"
D.Strings[78515]="|TInterface\\Icons\\spell_shaman_earthquake.blp:20|t%s开始施放|cFFFF0000|Hspell:170905|h[震地]|h|r！"
D.Strings[78516]="你没有在队伍中。"
D.Strings[78517]="如果你和附近的联盟发生摩擦，就使用弗里兹·火箭的信号弹吧。$B$B如果我们都不知道你在哪儿，又怎么帮得了你呢。"
D.Strings[78518]="<戈拉的耳朵竖了起来，可她的眼睛依然盯着坟墓。>"
D.Strings[78519]="琉璃领主，一位自称艾克西安的虚空伪神将我的灵魂囚禁在虚空领域。它的碎片则被……撕扯下来……供墓地中的影月兽人使用。"
D.Strings[78520]="可戈拉她是不会离开我的，直到我的灵魂雕像被烧毁，我的灵魂得到安息。"
D.Strings[78521]="谢谢你解救了我们俩。"
D.Strings[78522]="请送我去阿兰卡峰林。"
D.Strings[78523]="%s开始引导|cFFFF0404|Hspell:159996|h[感染孢子]|h|r！"
D.Strings[78524]="特丽丝·护藤是我们的常驻急救专家。\n\n她和她的学徒正在兵营里照料伤员，你可以去那里找她。"
D.Strings[78525]="奥斯汀·温德米尔是暴风之盾里最会玩鱼竿的人。如果你需要钓鱼，可以去找他。\n\n你通常能在他海滩上的房子外面找到他，就在市政厅和拍卖行的后面。"
D.Strings[78526]="暴风之盾的首席草药学家，洁·野花从潘达利亚赶来研究德拉诺的本地植被。\n\n如果你需要学习草药学方面的知识，可以在英雄之眠旅店外找到她。"
D.Strings[78527]="你可以在法师塔里找到铭文师芝源。\n\n她是全阿什兰最棒的铭文师，可以教你任何铭文学的知识。"
D.Strings[78528]="德莱尼技师们也来助暴风之盾一臂之力了。\n\n如果你想学习珠宝加工，就去德莱尼的营地找技师妮希亚吧。那地方就在暴风之盾中心区的西边。"
D.Strings[78529]="吉斯顿·锐羽是本地的制皮专家。\n\n你可以在镇中央的铜须的仓库外面找到他的摊位。"
D.Strings[78530]="如果你需要学习采矿，我建议你去找乔纳斯·链拳。他是这方面的专家。\n\n你可以在镇中央的工坊外找到他。"
D.Strings[78531]="游侠兰顿正在暴风之盾用自己专业的剥皮知识帮助我们的部队。\n\n他就在镇中央铜须的仓库外的制皮摊位上。\n\n"
D.Strings[78532]="约书亚·福斯汀是全德拉诺最好的裁缝。没有比他更适合教你针线活的人了。\n\n你可以在镇子的商业中心找到他的摊位。你只要找那些时髦的模特就对了，他们很容易看见的。"
D.Strings[78533]="觉醒教派在拍卖行外面开了一家商店，就在暴风之盾的南部。\n\n我听说他们会为那些帮他们研究埃匹希斯遗物的人提供丰厚的报酬。"
D.Strings[78534]="德拉诺的各大阵营正齐聚市政厅，协助我们在阿什兰的行动。\n\n他们还会向那些声望足够的人出售一些有用的物品。"
D.Strings[78535]="肯尼斯·诺尔斯在暴风之盾的中心开了一家商店，就在我们的许多专业技能训练师附近。\n\n如果你需要制造材料，就去找他吧。"
D.Strings[78536]="商人塞雷尔会向你这样的冒险者提供各种商品。\n\n你可以在市政厅外面找到他的货车，就在中央纪念碑旁。"
D.Strings[78537]="如果你想将自己的动物寄养在兽栏里，就去暴风之盾南部的旅店外找奥维尔·曼弗雷德吧。\n\n虽然他的长相凶恶，但我听说他很会照料动物。"
D.Strings[78538]="许多商人都在暴风之盾开设了商店。你想找哪一位？"
D.Strings[78539]="埃匹希斯碎片商人"
D.Strings[78540]="声望商人"
D.Strings[78541]="拉响警报！这肯定是原兽入侵了。"
D.Strings[78542]="正在拓印"
D.Strings[78543]="枯木对你施放了|TInterface\\Icons\\Spell_Nature_ElementalShields.blp:20|t |cFFFF0404|Hspell:164294|h[失控蔓生]|h|r！"
D.Strings[78544]="%s开始喷吐|cFFFF0404|Hspell:155031|h[噬体火焰]|h|r！"
D.Strings[78545]="宠物对战？你该去跟扎格·碎骨谈谈。他就是那个养了很多猫咪的兽人，就在大图腾的北边。 \n\n对，你没听错，一个养了很多猫咪的兽人。"
D.Strings[78546]="一群虚灵在元素高塔开了一家商店。 \n\n我不知道他们在阿什兰有什么图谋，但他们能提供一些很有用的服务。"
D.Strings[78547]="如果你想在市场上试试手，可以去拍卖行。\n\n拍卖行就在战争之矛北部的牛头人区里。"
D.Strings[78548]="你可以将备用的装备存放在战争之矛堡垒的银行里。没有人会疯狂到去那里偷东西的！\n\n那座巨型建筑就在图腾的南边，你不会错过的。"
D.Strings[78549]="如果你需要快速旅行的话，战争之矛正好有一批训练有素的双足飞龙。\n\n如果你需要用到它们，就去旅店后面的山上找伊拉鲁吧。\n"
D.Strings[78550]="如果你需要休息，碎矛旅店就是你的首选。\n\n你只要沿着大图腾北边的路走就能找到它。"
D.Strings[78551]="我们有很多邮箱。你想找哪一个？"
D.Strings[78552]="碎矛旅店外就有一个邮箱。\n\n你可以在在大图腾北边的路旁找到它。"
D.Strings[78553]="我们在牛头人区的拍卖行外面也设了一个邮箱。\n\n它就在大篝火的北边。"
D.Strings[78554]="银行在战矛堡垒外设置了一个邮箱，欢迎你去使用。\n\n战争之矛堡垒就是图腾南边的那座巨型建筑。"
D.Strings[78555]="地精在加里维克斯的车库外面开设了一个邮箱。\n\n那是地精区最大的建筑，就在镇子的东部。"
D.Strings[78556]="法师们架设了一些通往不同地方的传送门。你想找哪一个？"
D.Strings[78557]="你可以在元素高塔里找到通往奥格瑞玛的传送门。\n\n从大图腾往东边走就是了。"
D.Strings[78558]="通往雷霆崖的传送门在牛头人区里。\n\n它应该就在拍卖行边上。"
D.Strings[78559]="被遗忘者在他们那一区架设了一座通向幽暗城的传送门。\n\n你可以在他们的炼金小屋后面找到它。"
D.Strings[78560]="你需要哪种专业技能方面的帮助呢？"
D.Strings[78561]="如果你想创造一种新的瘟疫，那没有比被遗忘者更擅长的人选了。\n\n去亡灵区的炼金小屋里找克里斯托弗·柯西吧。"
D.Strings[78562]="热砂保护协会是这一带最好的考古学组织。\n\n你可以在地精区的小车库里找到他们。你只要找丽娜·碎轮就可以了。"
D.Strings[78563]="马兹顿·商齿是这一带最好的铁匠。\n\n你可以在地精区的加里维克斯的车库后面找到他。"
D.Strings[78564]="毫无疑问，盖伊·火眼就是战争之矛最棒的厨师。碎矛旅店的所有美食都是他一手烹制的。\n\n你通常可以在旅店下面的厨房里找到他。"
D.Strings[78565]="巨魔们提供了战争之矛所需的所有附魔。\n\n去巨魔区的附魔研究室找哈尼克吧。他应该可以帮到你。"
D.Strings[78566]="熊猫人威恩·妙手一直在照料我们的士兵。他或许就是你要找的急救训练师的最佳人选。\n\n你可以在兵营里找到他，只要跟着训练中的兽人的吼叫声走就是了。"
D.Strings[78567]="布里克斯·箭投是这一带最会钓鱼的地精。\n\n你可以在地精区北边海滩附近的小岛上找到他。"
D.Strings[78568]="如果你需要学习草药学知识，那就去亡灵区吧。\n\n安东尼·阿里安就在炼金小屋旁边。他或许能教你一两手绝活。\n"
D.Strings[78569]="全战争之矛最好的铭文师就是巨魔区的乔鲁曼。\n\n为了你好，但愿他的文笔不像他的口语那么滑稽。"
D.Strings[78570]="有一小批血精灵在牛头人区的对面安营扎寨了。\n\n你可以在那里找到一个名叫亚历山大·迅钢的珠宝加工师。"
D.Strings[78571]="跟我们一起来到这里的牛头人似乎掌握了这一带最高超的制皮技术。\n\n去牛头人区找布尔加·硬皮接受制皮方面的训练吧。"
D.Strings[78572]="如果你想找个好矿工，那就去找姆格·石裂吧。他特别擅长干这个，还靠着这门手艺从一个苦力爬到了战争之矛矿业负责人的位置。\n\n我最后一次看见他时，他正在地精区的东边挖石头呢。"
D.Strings[78573]="猎誓一家剥制过德拉诺几乎所有野兽的毛皮，所以如果你需要剥皮训练，就去找他们吧。\n\n你可在牛头人区找到正在摆弄皮革的孔达尔。"
D.Strings[78574]="我个人更喜欢皮草，但如果你喜欢精美的布料，那就去找血精灵塞莎·银血吧。\n\n她和她的族人们住在一起，就在牛头人区的对面。"
D.Strings[78575]="那些鸟人就住在镇子南边的训练场边上。\n\n他们说自己正在寻找古代遗物，而且愿意出高价来收购它们。"
D.Strings[78576]="我们的战争之矛堡垒里汇聚了许多不同阵营的使者。\n\n我听说他们那儿还有一些特产出售，但只卖给自己看得上眼的人。"
D.Strings[78577]="牛头人区的贝伦·净日就是我们的供应商。\n\n如果你需要制造材料，就去找他吧。"
D.Strings[78578]="你可以在碎矛旅店外面找到贾沙的商店。\n\n你可以在那里买到冒险所需的一切补给。"
D.Strings[78579]="乌佳照料着这里大部分人的动物。但如果我是你的话，一定会小心她的迅猛龙。\n\n你可以在巨魔区的山洞外面找到她。"
D.Strings[78580]="要买东西？说具体点，你到底想买啥？"
D.Strings[78581]="加里维克斯的车库"
D.Strings[78582]="将卡加斯·刃拳引到激活的烈焰之柱旁可以抵消他的狂暴冲锋。"
D.Strings[78583]="|TInterface\\Icons\\ability_mage_livingbomb.blp:20|t你身上有一颗|cFFFF0000|Hspell:176670|h[活动炸弹]|h|r！"
D.Strings[78584]="|TInterface\\Icons\\spell_shaman_improvedfirenova.blp:20|t山脉之心即将使用热能进行|cFFFF0000|Hspell:155209|h[冲击]|h|r！"
D.Strings[78585]="别让黑沉沉的天空给骗了。今天可是个好日子。"
D.Strings[78586]="让那些被恶魔腐蚀的暗影议会看看自由的力量吧！"
D.Strings[78587]="格莱布林·迅爆最后一次现身是在破碎悬崖。快飞去救他吧，否则就迟了。"
D.Strings[78588]="就是它了，战士们。让我们看看这头戈隆有多厉害吧。"
D.Strings[78589]="真够顽强的。就是这样，士兵们。为了部落！"
D.Strings[78590]="求求你！饶了我！噢，真丢人……"
D.Strings[78591]="我还得在附近继续挖掘遗物。再次感谢你的帮助。"
D.Strings[78592]="你真是我的大救星，$n。现在我明白为什么大家都愿意追随你。你果然是盛名之下无虚士。"
D.Strings[78593]="对一群废物来说还算不错！等你们准备好送死，就来面对克鲁德吧！"
D.Strings[78594]="这个箱子放哪儿？"
D.Strings[78595]="这些箱子怎么都要我搬？"
D.Strings[78596]="放那儿。你怎么老问？你不是一直把箱子从这儿搬到那儿吗？"
D.Strings[78597]="别问了，快回去干活。"
D.Strings[78598]="一朵孢子花堵住了你的去路！"
D.Strings[78599]="这可真不错！"
D.Strings[78600]="还不赖！"
D.Strings[78601]="好东西！"
D.Strings[78602]="啊。真是不虚此行！"
D.Strings[78603]="嘿！这是熊猫人的酒吗？！"
D.Strings[78604]="熔岩采石场的|c00FFFF00|Hspell:178019|h[事件：收集强化矿石]|h|r将在3分钟后开始。"
D.Strings[78605]="毁灭斗兽场的|c00FFFF00|Hspell:178022|h[事件：斗兽场角力]|h|r将在3分钟后开始。"
D.Strings[78606]="灰槌墓地的|c00FFFF00|Hspell:178020|h[事件：复活的游魂]|h|r将在3分钟后开始。"
D.Strings[78607]="蛮兵高地的|c00FFFF00|Hspell:178021|h[事件：食人魔火焰]|h|r将在3分钟后开始。"
D.Strings[78608]="如果让阿祖卡拿到高格里克之心，谁知道她会对我们的人民犯下怎样的恶行。"
D.Strings[78609]="要是你见到那个没用的步兵，能不能告诉他一声，就说我正在找他？"
D.Strings[78610]="我们的人都被抓了，$r。请帮忙把他们救出来吧。进入废墟，将我们的兄弟从压迫者手中救出来。如果他们能够参战，将对我们的事业有很大帮助。但你必须将他们安全地送到某位黑暗占卜师那里！"
D.Strings[78611]="我已经救出了这些流亡者，并将他们送到了安全的地方。"
D.Strings[78612]="是的，很好！你从我们那些残酷的兄弟手中救出了更多的流亡者。快，我们必须把他们送到安全的地方。"
D.Strings[78613]="救出那些流亡者，带领他们杀出重围，护送他们抵达黑暗占卜师那里，别让他们死掉。我明白了。"
D.Strings[78614]="救命！我是活人！"
D.Strings[78615]="为了杜隆塔尔！"
D.Strings[78616]="把他们都干掉！"
D.Strings[78617]="干得不错，联盟的士兵们！如果能占领落烬塔楼，我们就可以让我们的哨兵去消灭那些|c00FFFF00|Hspell:178362|h[战争之矛角斗士]|h|r了。胜利已经近在眼前了！"
D.Strings[78618]="Lok'tar ogar！我们必须占领这最后一个岗哨，好让我们猎头者去消灭那些|c00FFFF00|Hspell:178363|h[暴风之盾角斗士]|h|r。然后，我们就能横扫暴风之盾堡垒。泰布雷德今天死定了！"
D.Strings[78619]="|TInterface\\Icons\\ability_warrior_rampage.blp:20|t%s开始施放|cFFFF0000|Hspell:164426|h[无畏挑战]|h|r！"
D.Strings[78620]="可惜今天我们略逊一筹。撤退！"
D.Strings[78621]="谨慎才是真正的勇气。快撤退吧！"
D.Strings[78622]="|TInterface\\Icons\\ability_deathwing_bloodcorruption_earth.blp:20|t%s开始施放|cFFFF0000|Hspell:163689|h[血红之球]|h|r！"
D.Strings[78623]="我今天失去了两个儿子。我比氏族中那些沦为钢铁部落牺牲品的兄弟姐妹们更早得看清了战争的结局。$b$b我选择的是治疗者的道路。我的天赋在于帮助那些在生活和战斗中受伤的人。$b$b如果你愿意带上我，我可以用我的治疗天赋帮助你的军队。"
D.Strings[78624]="盖亚安祖母，我选择你！"
D.Strings[78625]="你已经在战场上不止一次超越我了，这可不简单。$b$b但我还有许多你没看到的才能。元素赋予了我最冷酷严苛的力量。元素是我的盟友，也是我们敌人的灾难。$b$b能为你效劳是我的荣幸。"
D.Strings[78626]="可敬的卡尔戈，我选择你！"
D.Strings[78627]="洛卡拉，我选择你！"
D.Strings[78628]="你已经见过了我最落魄时的模样，$n。我的丈夫被抓走……我的狼被那个懦夫芬里斯杀害。我非常了解战争的代价。$B$B我们必须推翻钢铁部落。让我和你并肩作战吧，我会携元素之力向我们的敌人复仇。$b$b只要你愿意接受我的战斧，我就会追随于你。"
D.Strings[78629]="跟随玛尔拉德"
D.Strings[78630]="指挥官，猛禽德鲁伊莫希斯·轻翼正在找你。他就在南边的那棵大树底下。"
D.Strings[78631]="啊！你来带路去大厅？"
D.Strings[78632]="把他们赶出去！不要退缩！"
D.Strings[78633]="不要动摇！"
D.Strings[78634]="继续进攻！前进！"
D.Strings[78635]="联盟突袭了铁匠铺！"
D.Strings[78636]="部落突袭了铁匠铺！"
D.Strings[78637]="部落守住了铁匠铺！"
D.Strings[78638]="联盟守住了铁匠铺！"
D.Strings[78639]="联盟突袭了农场！"
D.Strings[78640]="部落突袭了农场！"
D.Strings[78641]="联盟守住了农场！"
D.Strings[78642]="部落守住了农场！"
D.Strings[78643]="联盟突袭了矿井！"
D.Strings[78644]="部落突袭了矿井！"
D.Strings[78645]="联盟守住了矿井！"
D.Strings[78646]="部落守住了矿井！"
D.Strings[78647]="联盟突袭了伐木场！"
D.Strings[78648]="部落突袭了伐木场！"
D.Strings[78649]="联盟守住了伐木场！"
D.Strings[78650]="部落守住了伐木场！"
D.Strings[78651]="联盟突袭了兽栏！"
D.Strings[78652]="部落突袭了兽栏！"
D.Strings[78653]="部落守住了兽栏！"
D.Strings[78654]="联盟守住了兽栏！"
D.Strings[78655]="呼，老天保佑，总算及时赶上你了！我知道你的时间紧张，英雄，但我们得在面对塔纳安丛林的危险之前增强我们的实力。"
D.Strings[78656]="一个联盟间谍趁乱混了进来！"
D.Strings[78657]="让我们开始战斗吧！"
D.Strings[78658]="一个……光荣的……结局。"
D.Strings[78659]="愿万灵宽恕你。"
D.Strings[78660]="让万灵碾碎你！"
D.Strings[78661]="愿万灵带给你胜利。"
D.Strings[78662]="你有我儿子杜隆坦的消息吗？"
D.Strings[78663]="这场战争还会结束吗？"
D.Strings[78664]="我儿子杜隆坦怎么样了？"
D.Strings[78665]="我们本不必如此。"
D.Strings[78666]="这些人是受我们保护的。"
D.Strings[78667]="你再也别想伤害我们的人民了。"
D.Strings[78668]="我对这个结局表示遗憾。"
D.Strings[78669]="加拉达……我来了……"
D.Strings[78670]="你休想伤害我们的人民。"
D.Strings[78671]="部落夺取了德莱尼废墟的控制权！"
D.Strings[78672]="一个野火元素被召唤到了前门！"
D.Strings[78673]="一个鬣蜥人地洞打开了！"
D.Strings[78674]="我的生命属于利爪女王。"
D.Strings[78675]="比起战斗，这些垃圾更擅长送死。"
D.Strings[78676]="哈！分成两半之后，这家伙比原来丑了一倍！"
D.Strings[78677]="观察"
D.Strings[78678]="我们走！指挥官，我们在塔楼哪儿见。"
D.Strings[78679]="一名高里亚战争召唤者加入战斗，提升了士气！"
D.Strings[78680]="通向虚空的裂隙开启了！"
D.Strings[78681]="一名阵亡的守卫被转化成了枯骨！"
D.Strings[78682]="大主教哈塔鲁，你打算在议会上投什么票？"
D.Strings[78683]="你这是要拿我们的一切去冒险。我不同意。"
D.Strings[78684]="擅用我们的优势来战斗才是最明智的。"
D.Strings[78685]="我对来自另一个世界的联盟很感兴趣。我会全力支持他们。"
D.Strings[78686]="大主教阿卡玛，你打算投什么票？我猜你宁愿躲在沙塔斯和卡拉波的防御工事后面等待。"
D.Strings[78687]="但是如果我们一直不走出城墙，就永远无法称这个世界为我们的家园。"
D.Strings[78688]="联盟失去了血精灵塔的控制权！"
D.Strings[78689]="部落失去了血精灵塔的控制权！"
D.Strings[78690]="联盟失去了德莱尼废墟的控制权！"
D.Strings[78691]="部落失去了德莱尼废墟的控制权！"
D.Strings[78692]="联盟失去了魔能机甲废墟的控制权！"
D.Strings[78693]="部落失去了魔能机甲废墟的控制权！"
D.Strings[78694]="联盟失去了法师塔的控制权！"
D.Strings[78695]="部落失去了法师塔的控制权！"
D.Strings[78696]="一头虚空狼母吓坏了你的守卫！"
D.Strings[78697]="啊！那个老家伙。我在制作这根法杖时，真是太年轻、太天真了。看看那些头发！还有那个鼻子！$b$b我都不敢相信，我会带着这么恶心的帽子招摇过市。$b$b你就留着这根旧法杖吧。这个影像已经是几年前的了，和我现在的模样已经不太一样了。希望你会喜欢我年轻的模样。"
D.Strings[78698]="这根|Hitem:118191|h|cff0070dd[大法师瓦格斯的备用法杖]|r|h是你的吗？"
D.Strings[78699]="一只大地之怒在你的要塞制造了一场地震！"
D.Strings[78700]="一名高里亚战斗法师加入了战斗！"
D.Strings[78701]="战斗引发的骚乱引来了一头双头飞龙！"
D.Strings[78702]="一名高里亚缚法者赶来拖住了你的部队！"
D.Strings[78703]="一名刺客正在猎杀你的守卫！"
D.Strings[78704]="我要关闭这座传送门。"
D.Strings[78705]="我要关闭这座传送门。 |cFFFF2222 [需要10个食人魔道标石]|r |TInterface\\Icons\\INV_RELICS_RUNESTONE.BLP:##|t"
D.Strings[78706]="你在这里做什么，凡人？\n\n我把毕生的精力都用来守护这些古代传送门了。如果你想激活它们，就需要获得一些名为食人魔道标石的古代神器。"
D.Strings[78707]="确定要关闭这座食人魔传送门吗？\n\n|TInterface\\Icons\\INV_RELICS_RUNESTONE.BLP:24|t 需要10个食人魔道标石"
D.Strings[78708]="我听说你这里有精品戒指卖？"
D.Strings[78709]="一架攻城火炮正在靠近！"
D.Strings[78710]="一名蛮兵吓坏了你的部队！"
D.Strings[78711]="一名狙击手正在射杀你的守卫！"
D.Strings[78712]="一群女妖现身了！"
D.Strings[78713]="黑手"
D.Strings[78714]="古尔丹"
D.Strings[78715]="卡加斯"
D.Strings[78716]="基尔罗格"
D.Strings[78717]="耐奥祖"
D.Strings[78718]="一大波地狱火出现了！"
D.Strings[78719]="部落突袭了血精灵塔！"
D.Strings[78720]="联盟突袭了血精灵塔！"
D.Strings[78721]="部落突袭了魔能机甲废墟！"
D.Strings[78722]="部落突袭了法师塔！"
