D.Strings[78810]="|TInterface\\Icons\\inv_bannerpvp_02.blp:20|t一名联盟旗手抵达了你的议政厅！|TInterface\\Icons\\inv_bannerpvp_02.blp:20|t"
D.Strings[78811]="|TInterface\\Icons\\inv_bannerpvp_01.blp:20|t一名部落旗手抵达了你的大厅！|TInterface\\Icons\\inv_bannerpvp_01.blp:20|t"
D.Strings[78812]="一波暴怒掠食者正在接近！"
D.Strings[78813]="我没有旗帜了，指挥官！我该走了。"
D.Strings[78814]="孢子射手正在攻击你的守卫！"
D.Strings[78815]="一名恶毒扈从正在袭击你的部队！"
D.Strings[78816]="一名邪能军团士兵正在靠近！"
D.Strings[78817]="陪伴先知维伦前往坠落之月。"
D.Strings[78818]="我们必须尽快赶去坠落之月。"
D.Strings[78819]="护送先知维伦前往坠落之月。"
D.Strings[78820]="训练得不错，现在让你的塔布羊休息一晚吧。"
D.Strings[78821]="你的裂蹄牛确实很坚韧，但它还是需要休息一会儿的。"
D.Strings[78822]="你的野猪看起来需要好好洗刷一番，再吃点东西。明天再来看它吧。"
D.Strings[78823]="你今天打得很好，我们会让你的淡水兽好好睡一晚的。"
D.Strings[78824]="这头雷象都快睡着了，先让它休息一会儿再训练吧。"
D.Strings[78825]="这头狼非常暴躁，可经过一天的训练之后，它已经完全蔫了，明天再继续训练吧。"
D.Strings[78826]="这头狼是凶猛的掠食者，但它必须休息一天才能继续接受训练了。"
D.Strings[78827]="这头塔布羊的训练进度很不错，它需要休息一晚了。"
D.Strings[78828]="这头淡水兽还不习惯陆地作战，今天我们得让它好好休息一下。"
D.Strings[78829]="经过一天的训练，这头雷象都快睡着了，今晚我们要让它好好休息一下。"
D.Strings[78830]="这头裂蹄牛需要好好洗刷一下再喝点水，明天再回来继续训练吧。"
D.Strings[78831]="你的野猪看起来很疲惫，但还算健康。今晚就把它交给我们吧，我们会照顾好它的。"
D.Strings[78832]="真是有趣的想法！再让我们看看吧，$r。杀掉这里的其他人！让我们好好享用这些敌人，利用他们的机械来发现我们的家园中隐藏的奇迹！"
D.Strings[78833]="该进餐了……杀光他们！"
D.Strings[78834]="我们饿了……再多杀几个！我们要吃掉他们的尸体！"
D.Strings[78835]="这是什么？我们还需要多了解一点。靠近些！"
D.Strings[78836]="有意思，我们得记住这一点。"
D.Strings[78837]="我们的力量正在滋长……"
D.Strings[78838]="我们正在学习！我们已经看清生命历程的下一个阶段了。"
D.Strings[78839]="我们的力量已经准备好了，可以进化了！"
D.Strings[78840]="一种古怪的寄生生物钻进了你的脑袋，你感觉有东西侵入了你的思维。"
D.Strings[78841]="无形寄生蟹因为激动而产生了波动，它显然对你的行为感到非常满意。"
D.Strings[78842]="无形寄生蟹对你的头脑控制加强了，它正变得更加强大。"
D.Strings[78843]="随着无形寄生蟹的进化，你感觉自己正在脱离大地。你和它一起进化了！"
D.Strings[78844]="我们不能离开自己的家园，$r。即使没有你，我们的生命也能够延续。"
D.Strings[78845]="一种古怪的寄生生物离开了你的脑袋，消失在远方。"
D.Strings[78846]="我们感觉到一些兄弟死亡了。这很好，他们显然不适应进化。"
D.Strings[78847]="多么美味的进化。我们还要更多。"
D.Strings[78848]="无形寄生蟹对你的头脑控制再次加强了，它的声音在你的脑海中轰鸣。"
D.Strings[78849]="|TInterface\\Icons\\Ability_Racial_Cannibalize:20|t拾取战利品后，右键点击尸体来|cFFFF0000|Hspell:174133|h[吞噬]|h|r它们。"
D.Strings[78850]="让我看看你的货物吧！"
D.Strings[78851]="这些大家伙很古怪。他们虽然很大很迟钝，但也可能是因为拥有高度智慧的个体都逃跑了。"
D.Strings[78852]="我们也不知道为什么，但这些长羽毛的家伙和他们的洞穴都让我们非常不安。"
D.Strings[78853]="这些小东西的好奇心最强，总是急于探索、实验和学习。跟我们很像。"
D.Strings[78854]="这些样子恶心的生物……比其他生物更加软弱。他们会将自己完全交给我们的兄弟们。"
D.Strings[78855]="这家伙已经被我们的同类寄生了。他们选错了宿主。"
D.Strings[78856]="我们兄弟真是不幸。进化的轮回是非常野蛮的，毫无仁慈可言。"
D.Strings[78857]="要没有这些苔藓，我们的头脑早就生锈了，我们真正的潜力也就只剩下一个空壳了。"
D.Strings[78858]="真有意思，我们从没尝过这个洞穴里的果子。"
D.Strings[78859]="这是什么……东西？里面藏着什么？"
D.Strings[78860]="真奇怪，我们不记得这些玩意儿是怎么跑到这里来的了。"
D.Strings[78861]="太神奇了，我们能感觉到能量在你体内流淌。它究竟有什么效果？"
D.Strings[78862]="这下我们认出来了！这个该死的装置杀害了我们许多的同胞！我们的兄弟们很快就会灭亡，让我们在没有他们的世界里继续繁衍吧。"
D.Strings[78863]="这玩意儿为什么这么吵？这东西有什么作用？"
D.Strings[78864]="无形寄生蟹的进化消退了。你感觉这个寄生生物又回到了你头顶的危险位置。"
D.Strings[78865]="我们已经看过你能展示的一切了，我们要去找其他能够展示更多知识的宿主了。"
D.Strings[78866]="我们选……错了人。我们得再找一个宿主。"
D.Strings[78867]="将构造体带回这里。"
D.Strings[78868]="要召唤构造体吗？"
D.Strings[78869]="大地的赠礼"
D.Strings[78870]="雅格-367型系统启动。需要副驾驶以启动该程序。"
D.Strings[78871]="任务启动。获取目的地坐标。"
D.Strings[78872]="程序启动。进入自动漂浮模式。"
D.Strings[78873]="前方1000米处侦测到裂隙。启动手动驾驶模式。"
D.Strings[78874]="需要同步驾驶。正在等待移动指令。"
D.Strings[78875]="侦测到敌对目标。"
D.Strings[78876]="新任务：消灭敌人。"
D.Strings[78877]="任务成功。启动回归序列。"
D.Strings[78878]="启动关闭并返回序列。"
D.Strings[78879]="我这里有你尝过的最好的美酒。"
D.Strings[78880]="噢，看呐，“不对”和“没门”正好在你脚下重叠了。"
D.Strings[78881]="警告：飞行员已弹出。关闭序列已启动。"
D.Strings[78882]="警告：未侦测到输入信息。自动关闭序列已启动。"
D.Strings[78883]="看来这里就是瓦尔·金铲寻找古特里克的杀生刀的最后一站了。"
D.Strings[78884]="在兽人身上寻找线索。"
D.Strings[78885]="送我去钢铁码头。"
D.Strings[78886]="加热"
D.Strings[78887]="锻造"
D.Strings[78888]="淬火"
D.Strings[78889]="来吧，我的小宝贝们，喂食时间到！"
D.Strings[78890]="我的宠物们都饿坏了。"
D.Strings[78891]="你会成为绝佳的零食。"
D.Strings[78892]="你休想夺走我的宠物！"
D.Strings[78893]="尽量不要尖叫，我的宠物们在睡觉呢。"
D.Strings[78894]="嘘，睡吧，小宝贝。"
D.Strings[78895]="你睡觉的样子真是可爱。"
D.Strings[78896]="我不会再让你出事了，小家伙。"
D.Strings[78897]="返回起点！"
D.Strings[78898]="你想要我的刀吗，小$c？"
D.Strings[78899]="我把它插在你的小脑瓜上怎么样？"
D.Strings[78900]="这本书分门别类地记载了你过去搜寻遗物的经历。\n\n万一你迷了路，可以查看这些笔记了解自己是在哪里中断的。"
D.Strings[78901]="我在这儿！噢，这是什么？"
D.Strings[78902]="托格，你下次用熔炉的时候，记得要乘热打铁。\n\n如果你在锤打之前就把刀剑放进水里，它只会再次折断。"
D.Strings[78903]="这么说，那些地表居民妄想在鲁克玛的金色羽翼上飞翔？"
D.Strings[78904]="可惜你来的太晚了。现在你必须为自己的傲慢付出代价！"
D.Strings[78905]="鲁克玛的恩赐只属于鸦人！"
D.Strings[78906]="送我回要塞。"
D.Strings[78907]="钢铁军工厂。我们可以从那里偷一些火炮来。"
D.Strings[78908]="钢铁部落都缩在他们的高墙后面。"
D.Strings[78909]="这里有一座港口。我们能控制几艘船吗？"
D.Strings[78910]="钢铁码头……对，你之前的突袭已经令它瘫痪了。"
D.Strings[78911]="%s摆脱了缠在身上的网兜！"
D.Strings[78912]="炸弹已经放好了。快让开！"
D.Strings[78913]="你没有游戏代币。等你至少弄到1个代币之后再来找我吧。"
D.Strings[78914]="看来你已经准备好要参加比赛了！那就快站出来吧，我们这就送你上路。"
D.Strings[78915]="只有齐心协力，才能得到真正的智慧。\n\n然后，前行的道路才会开启。"
D.Strings[78916]="指挥官，你有什么建议？"
D.Strings[78917]="如果正面强攻的话，伤亡会非常惨重。"
D.Strings[78918]="看来你有别的想法了，指挥官。是打算佯攻吗？"
D.Strings[78919]="水里布满了水雷，而且那里的士兵比补给品还多。"
D.Strings[78920]="对，但没有造船的材料。我想指挥官是考虑到了海军战略。"
D.Strings[78921]="一个船坞。我们可以利用那里的废弃设备。"
D.Strings[78922]="你真是个天才，指挥官！我们可以从海上驶向塔纳安，从他们最想不到的海上打击钢铁部落。"
D.Strings[78923]="这似乎是食人魔用来为上古双头飞龙献上祭品的祭坛。吃剩下的骨头散落得到处都是。\n\n如果你能找到合适的祭品，或许你就能引来一条双头飞龙。\n\n这些骨头或许能告诉我们，它们喜欢吃什么……"
D.Strings[78924]="摆上生裂蹄牛肉。"
D.Strings[78925]="铁人拉力赛每15分钟开启一次。做好准备！"
D.Strings[78926]="铁人拉力赛将在1分钟后开始！"
D.Strings[78927]="铁人拉力赛即将开始！祝你好运！"
D.Strings[78928]="你就像风一样！"
D.Strings[78929]="玛尔拉德肯定会赞成强攻正门。可我们怎么可能成功？"
D.Strings[78930]="游侠报告说，那里已经没剩多少可以拿走的设备了。"
D.Strings[78931]="兽人留了一些攻城设备在钢铁军工厂里。"
D.Strings[78932]="但剩下的设备都很沉重。足以帮我们夺取一艘战舰了！"
D.Strings[78933]="钢铁部落已经在堡垒的高墙后面重整旗鼓了。"
D.Strings[78934]="雷神贤者没能深入玛戈纳洛克。但愿他还掌握着一些有用的信息……"
D.Strings[78935]="那是一座守卫森严的堡垒。只有蠢货才会孤身闯入那里。$b$b我是说……祝你好运，勇士。$b$b<卡德加安慰性地拍了拍你的肩膀。>"
D.Strings[78936]="%s拉响了警报！"
D.Strings[78937]="警报响了！你被发现了！"
D.Strings[78938]="你安全了。我把你救出来了。"
D.Strings[78939]="好险呐。你得再小心点。"
D.Strings[78940]="哇！我差点没救到你。"
D.Strings[78941]="<当你接近这个掠食者时，一个尖锐的啾啾声在你脑海中响起。>\n\n你喝下了真视之水，现在你能说话了！你肯定是那个骷髅脑袋的朋友。\n\n你也是来找脑袋的吗？"
D.Strings[78942]="你能带我去见割颅者吗？"
D.Strings[78943]="躲开黑暗，朋友。你的精神非常脆弱。"
D.Strings[78944]="你有脑袋吗？古拉克能背上所有的脑袋！"
D.Strings[78945]="朋友需要的话，古拉克可以送你去高处。"
D.Strings[78946]="跟我们走。我们来带路！"
D.Strings[78947]="走错了，两条腿的家伙！快转身！"
D.Strings[78948]="朋友又带脑袋来给我们啃了吗？"
D.Strings[78949]="别迷路了，朋友。他们会给你带路的。"
D.Strings[78950]="古拉克就快到了！拿上所有的脑袋！"
D.Strings[78951]="那么，这个家伙想找割颅者？"
D.Strings[78952]="很好，我会带你去见他。"
D.Strings[78953]="小心点，$C，别让你自己的脑袋被割了。"
D.Strings[78954]="让我看看所有可用的合约。"
D.Strings[78955]="我要挑战寻魔者。"
D.Strings[78956]="来啊，都来啊，快来见证正在发生的历史吧！今天，我们将在德拉诺最血腥的地方——鲜血竞技场送上一场表演赛！今天的比赛将是一场真正的视觉盛宴。$n和他的朋友们将挑战穆戈尔最新的独家王牌：来自悬槌堡的流亡者，双眼失明却有着独特的魔法嗅觉的，独一无二的，废灵者达库尔！"
D.Strings[78957]="表演赛现在开始！"
D.Strings[78958]="你叫我什么？！"
D.Strings[78959]="唔，还不错。到我的金库里去挑选你的奖励吧。你的命……暂时保住了。"
D.Strings[78960]="熬煮药剂"
D.Strings[78961]="解开流亡者的镣铐，那些工头身上肯定有钥匙。"
D.Strings[78962]="带领获救的流亡者安全抵达黑暗占卜师处。他们的士气会加快你的进度。"
D.Strings[78963]="和跟随你的鸦人流亡者一起击杀敌人可以提高他们的士气。当你将获救的鸦人流亡者送到安全的地方之后，士气能加快你的进度。"
D.Strings[78964]="如果获救的鸦人流亡者在到达安全地点前就消失了，那么他们的士气也将随之流失。"
D.Strings[78965]="当鸦人流亡者被送至安全地点时，其高昂的士气能大大加快你的进度。"
D.Strings[78966]="跟紧迦罗娜，别被敌人发现了！"
D.Strings[78967]="如果你遇到麻烦，我会把你传送出来。"
D.Strings[78968]="纪律很松散。你发动的战役把钢铁部落拖垮了。"
D.Strings[78969]="呃！我们差点就成功了。"
D.Strings[78970]="唉！我们能做得更好。"
D.Strings[78971]="躲藏"
D.Strings[78972]="真走运！钢铁部落的计划和文件……"
D.Strings[78973]="格罗玛什下令全线撤退到塔纳安的高墙后面。"
D.Strings[78974]="嗯，有意思。血环氏族出现了反叛的迹象。或许钢铁部落正在分崩离析？"
D.Strings[78975]="酋长不想见你。"
D.Strings[78976]="来吧，术士。让我们看看你的本事。"
D.Strings[78977]="他别无选择。"
D.Strings[78978]="自从上次一战之后，古尔丹的力量反而增强了。他肯定还和燃烧军团有联系。我们的当务之急就是阻止他。"
D.Strings[78979]="你需要一枚暗月游戏代币才能开始比赛！"
D.Strings[78980]="-1 暗月游戏代币"
D.Strings[78981]="迅捷如风，寂静无声……"
D.Strings[78982]="我爱狩猎！"
D.Strings[78983]="狩猎开始！"
D.Strings[78984]="把这家伙交给我。"
D.Strings[78985]="你来错地方了，小崽子。"
D.Strings[78986]="听候你的吩咐，指挥官。"
D.Strings[78987]="下一个是谁……？"
D.Strings[78988]="给我一个目标，指挥官。我已经准备就绪了。"
D.Strings[78989]="谁都不是我们的对手！无论是古尔丹，还是暗影议会，甚至是燃烧军团，都不值一提。"
D.Strings[78990]="对你和卡德加为我所做的一切，我都感激不尽。听凭你的吩咐。"
D.Strings[78991]="我们必须想办法再次进入塔纳安！"
D.Strings[78992]="我渴望敌人的鲜血，但在必要时，我也有足够的耐心。"
D.Strings[78993]="看那些城墙，头儿……还有路上那些兽人……我的老天爷！"
D.Strings[78994]="要是还有人能啃下这块硬骨头，那一定就是你了，指挥官。"
D.Strings[78995]="他们把这东西随意摆放？真有趣！"
D.Strings[78996]="我马上就把这玩意儿搬走，头儿！"
D.Strings[78997]="这里不欢迎拾荒者！这是钢铁部落的财产！"
D.Strings[78998]="这……毫无……意义……"
D.Strings[78999]="这是钢铁部落的财产！你会为这种行为付出代价的！"
D.Strings[79000]="我恨你……恨你们所有人……"
D.Strings[79001]="这真是一场大战呐，指挥官！"
D.Strings[79002]="我们准备好结束这一切了，指挥官，而且是不惜一切代价。"
D.Strings[79003]="我理解击败敌人的必要性，但我依然为可能牺牲的同胞感到心痛。"
D.Strings[79004]="我更喜欢绕过这类问题，我想你也是一样，指挥官。"
D.Strings[79005]="我还是不太适应这样的战略，这么大规模的部队。我们必须尽力减少伤亡，我们的战士应该有更好的结局。"
D.Strings[79006]="这些会有很大帮助的，指挥官。"
D.Strings[79007]="这真是一个伟大的发现，指挥官！"
D.Strings[79008]="我想和嚼颅者战斗。"
D.Strings[79009]="我想和弗拉克图斯战斗。"
D.Strings[79010]="我想和腐藤战斗。"
D.Strings[79011]="我想和德里夏克斯战斗。"
D.Strings[79012]="我想和冠军一决高下。"
D.Strings[79013]="你得先等一分钟，伙计。在这个家伙结束之前，我没法开启下一场战斗。$B$B虽然我是一个唯利是图的煽动者，将不计其数的无辜者送上绝路，可我一定要对得起自己的每一分钱。"
D.Strings[79014]="这是你的那份奖金，勇士！"
D.Strings[79015]="哼，你以为你是谁？"
D.Strings[79016]="投入阴影的怀抱吧。主人是不可抗拒的。"
D.Strings[79017]="不臣服的都得死。"
D.Strings[79018]="你休想活着离开这座洞穴！"
D.Strings[79019]="把尸体丢给地狱犬，哈哈哈！"
D.Strings[79020]="小心点，勇士。暗影议会会利用你的犹疑和弱点。"
D.Strings[79021]="演奏“铁炉堡”"
D.Strings[79022]="演奏“冷山”"
D.Strings[79023]="演奏“夜歌森林的轻语”"
D.Strings[79024]="我能感到你周围的黑暗能量。那是什么？"
D.Strings[79025]="演奏“诺莫瑞根”"
D.Strings[79026]="演奏“工匠镇”"
D.Strings[79027]="演奏“埃索达”"
D.Strings[79028]="演奏“狼人的诅咒”"
D.Strings[79029]="演奏“武僧之道”"
D.Strings[79030]="演奏“刘浪之歌”"
D.Strings[79031]="演奏“天使之歌”"
D.Strings[79032]="演奏“幽魂的低语”"
D.Strings[79033]="演奏“丛林”。"
D.Strings[79034]="演奏“魔法”"
D.Strings[79035]="演奏“黑暗神殿”"
D.Strings[79036]="演奏“无敌”"
D.Strings[79037]="演奏“青铜的困境”。"
D.Strings[79038]="找齐需要的东西，到入口外跟我汇合。"
D.Strings[79039]="跟我来。它能帮助我解除古尔丹对迦罗娜的精神控制。"
D.Strings[79040]="这是用敌人的武器来对付他们自己！"
D.Strings[79041]="除非我死。我会结束你的痛苦，迦罗娜。"
D.Strings[79042]="赶快，摧毁那玩意儿！"
D.Strings[79043]="醒醒，迦罗娜。你自由了。"
D.Strings[79044]="来吧，迦罗娜。我们研究一下怎么打倒古尔丹。"
D.Strings[79045]="大法师。你摆弄的是黑暗魔法。"
D.Strings[79046]="你使用的是敌人的武器！"
D.Strings[79047]="我不喜欢这样。"
D.Strings[79048]="把那颗珠子给我，卡德加。我来摧毁这件邪物。"
D.Strings[79049]="你还没有放弃吗，法师？"
D.Strings[79050]="%s痛苦的喘息着。"
D.Strings[79051]="古尔丹……从我的脑海中消失了……"
D.Strings[79052]="你是我的大恩人！你们俩都是！"
D.Strings[79053]="我会不惜一切阻止古尔丹。你的命令就是我的意愿……指挥官。"
D.Strings[79054]="让我们再试一次。为了迦罗娜！"
D.Strings[79055]="想学点东西吗？"
D.Strings[79056]="你的灵魂必将臣服！"
D.Strings[79057]="死亡也无法……主宰它……"
D.Strings[79058]="让影月碾碎你！"
D.Strings[79059]="这水晶……是我的……"
D.Strings[79060]="我将回归虚空……"
D.Strings[79061]="我要把你炸成碎片！"
D.Strings[79062]="应该……多带点……火箭的……"
D.Strings[79063]="没人能击败古特里克……没人……"
D.Strings[79064]="我跟丢了迦罗娜。"
D.Strings[79065]="演奏默认要塞音乐"
D.Strings[79066]="演奏“雷霆之山”"
D.Strings[79067]="我把塞拉摩战袍弄丢了。"
D.Strings[79068]="演奏“卡拉赞歌剧院”"
D.Strings[79069]="演奏“银色锦标赛”"
D.Strings[79070]="演奏“上层精灵的挽歌”"
D.Strings[79071]="演奏“精灵龙”"
D.Strings[79072]="演奏“灰喉图腾”"
D.Strings[79073]="演奏“暗月旋转木马”"
D.Strings[79074]="演奏“沙兰蒂斯岛”"
D.Strings[79075]="$B***** 游戏规则 *****\n$B发起游戏的人将成为|cFF990000寻找者|r并获得|cFF2959D3标记|r队友的技能。其他所有队员都将获得|cFF2959D3躲藏|r技能。\n$B游戏开始后，|cFF990000寻找者|r有60秒时间来寻找并|cFF2959D3标记|r队友。\n$B躲藏起来的队员一旦移动，或者被|cFF990000寻找者|r接近，就会暴露。能在不被|cFF2959D3标记|r的情况下抵达大本营的玩家获胜！"
D.Strings[79076]="财富与荣耀，孩子。财富与荣耀。"
D.Strings[79077]="我这个不速之客总是不请自来。"
D.Strings[79078]="不管结局会如何，我都要全力以赴！"
D.Strings[79079]="我要提醒你一句，孩子。“X”记号从来都标不出正确地点。"
D.Strings[79080]="幸好我留了一手。那肯定是蛇！"
D.Strings[79081]="这真是好得让人……难以置信。"
D.Strings[79082]="回头见……孩子……"
D.Strings[79083]="财富与……荣耀……"
D.Strings[79084]="他选……错了。"
D.Strings[79085]="我恨蛇，孩子。我恨它们！"
D.Strings[79086]="这看起来很危险。你先上！"
D.Strings[79087]="把这家伙交给我！"
D.Strings[79088]="你管这叫考古？"
D.Strings[79089]="没什么能吓得住我，指挥官。我可是科学家。"
D.Strings[79090]="你找到什么遗物了吗，指挥官？"
D.Strings[79091]="今天你需要我帮忙吗，指挥官？"
D.Strings[79092]="这可真烦人。"
D.Strings[79093]="我们准备好了，开始吧！"
D.Strings[79094]="你的小队准备好了吗？"
D.Strings[79095]="准备好了吗？我来了！"
D.Strings[79096]="%s开始倒数。快躲起来！"
D.Strings[79097]="%s没能标记到任何玩家！躲藏者获胜！"
D.Strings[79098]="%s标记了$n，寻找者获胜！"
D.Strings[79099]="%s抵达了大本营！$G他:她;安全了！"
D.Strings[79100]="演奏“远山”"
D.Strings[79101]="演奏“奥格瑞玛”"
D.Strings[79102]="演奏“战争步伐”"
D.Strings[79103]="演奏“雷霆崖”"
D.Strings[79104]="演奏“莫高雷平原”"
D.Strings[79105]="演奏“幽暗城”"
D.Strings[79106]="演奏“祖尔格拉布的巫术”"
D.Strings[79107]="演奏“赞达拉”"
D.Strings[79108]="演奏“银月城”"
D.Strings[79109]="演奏“拯救酋长”"
D.Strings[79110]="我正忙着呢，$n。有话就说，说完快走。"
D.Strings[79111]="|TInterface\\Icons\\Ability_Warlock_FireandBrimstone:20|t你成为了|cFFFF0000|Hspell:180776|h[致命烈焰]|h|r的目标！快远离你的同伴！"
D.Strings[79112]="改造建筑将花费500金币。\n\n确定要改造吗？"
D.Strings[79113]="在你踏上某片土地寻找商机时，你永远不会知道自己会遇到些什么。但愿我遇到了个好主顾？"
D.Strings[79114]="准备去死吧，蛆虫！"
D.Strings[79115]="你休想逃脱惩罚！"
D.Strings[79116]="哈！无耻的懦夫！"
D.Strings[79117]="格罗玛什，我……失败了……"
D.Strings[79118]="你们找错对手了，废物。"
D.Strings[79119]="见证你的毁灭吧！"
D.Strings[79120]="夹着尾巴逃跑吧，你们这群丧家犬！"
D.Strings[79121]="我怎么可能……失败？！"
D.Strings[79122]="噢，有新玩具了？！"
D.Strings[79123]="跳起来吧，小鬼！"
D.Strings[79124]="真无聊……我玩够了。"
D.Strings[79125]="我又赢了。"
D.Strings[79126]="这真是出人意料。"
D.Strings[79127]="你的宠物会慢慢恢复的。"
D.Strings[79128]="让我们看看你是怎么应对其它威胁的吧。"
D.Strings[79129]="请不要在阿莱克斯的周围做出任何过激举动，否则你可能会丢掉一根手指，甚至更糟。"
D.Strings[79130]="噢，你好啊。我这儿的客人可不多。\n\n你可能不知道，我就是《清心书卷》的作者。那可是畅销书。我是来这里寻找灵感的，打算写一点技术性没那么强的东西。"
D.Strings[79131]="那你目前找到什么灵感了吗？"
D.Strings[79132]="我还是暂时保密的好。上次我说漏了嘴，结果另一个作者剽窃了我的创意，写出了一本恶心的言情小说。"
D.Strings[79133]="每个要塞都需要来点儿重低音，你不觉得吗，指挥官？"
D.Strings[79134]="你来保护要塞安全，我来负责放音乐。"
D.Strings[79135]="哪儿能找到点唱机的零件？"
D.Strings[79136]="我对这片土地非常陌生。到处都是冲突、愤怒和仇恨。"
D.Strings[79137]="你愿意加入我们的事业吗？"
D.Strings[79138]="确定邀请范涛加入我们的事业吗？"
D.Strings[79139]="我听说过你在潘达利亚的光辉事迹！很荣幸见到你本人！"
D.Strings[79140]="这可不太明智，小东西！"
D.Strings[79141]="我们的拳头绝对比那个低音炮更带劲儿！"
D.Strings[79142]="扫兴的家伙，尝尝这个！"
D.Strings[79143]="嘿……我想……那是我的！"
D.Strings[79144]="我叫范涛，来自潘达利亚。我已经在这里旅行了很久了。你问这个干什么？\n\n我们都是乐于助人的人，你看起来需要一些帮助。如果你需要帮助，就请告诉我一声。"
D.Strings[79145]="<这头精灵龙看起来很忧伤。>"
D.Strings[79146]="噢，今晚可真不怎么样……我花了几个月的时间做出来的漂亮附魔居然无人问津！\n\n嘿，你想看看吗？"
D.Strings[79147]="看！我的杰作！很迷人，对吧？"
D.Strings[79148]="感谢你抽空来欣赏我的作品。我太开心了！"
D.Strings[79149]="我能买一本吗？"
D.Strings[79150]="<幽灵悲伤地哭泣着。>"
D.Strings[79151]="我想听听你的音乐。"
D.Strings[79152]="<幽灵看起来高兴了些。>"
D.Strings[79153]="要我帮你开一份购物清单吗？\n\n低音炮很好弄。鲜血竞技场的食人魔最喜欢在战斗时播放劲爆的音乐。那些观众可不是去打架的，尽管放心大胆地拿走他们的音箱就是了！\n\n至于镭射读碟器，我在宾奇维斯拓殖点开演唱会时，好像看到过一个还不错的。\n\n真正的音效增幅器恐怕很难搞，所以你就从鸦人的那些炎阳构装体身上扒一大块金属下来吧，那个应该能用。\n\n至于电容器么，你可能得去砸开钢铁部落切割者寻找了。这个活儿好像还挺适合你的。\n\n噢，还有，我需要的木头必须非常古老才行。永茂丛林应该是你在德拉诺的最佳选择。"
D.Strings[79154]="我该去哪儿找乐谱？"
D.Strings[79155]="在黑石山的深处藏着一份传奇乐谱，有两条龙在守护着它。"
D.Strings[79156]="去黑暗神殿逛逛怎么样？那首超重低音的曲子绝对能震得你说不出话来。"
D.Strings[79157]="去那座严寒刺骨的飞行堡垒面对他的怒火？就为了一首新曲子？你真是疯了！"
D.Strings[79158]="收集经典乐曲是很辛苦的，有时你不得不为此飞到一头巨大的灾祸之龙背上。那可不容易。"
D.Strings[79159]="战胜恐惧，你才能有勇气直面潘达利亚之心。当然，这是从音乐的角度而言。"
D.Strings[79160]="既然你已经开始率领部队和钢铁部落斗争，不如就顺手拿走黑手的乐谱吧。"
D.Strings[79161]="雄狮港那里有一份像大海一样清新的乐谱。但要小心鲨鱼！"
D.Strings[79162]="你手头有鱼竿和鱼线吗？我听说有一位音乐家将她的作品藏在铁炉堡某个很有创意的地方。"
D.Strings[79163]="工匠镇是个好地方，非常好玩，音乐也很不错！"
D.Strings[79164]="急着寻找新曲子吗？我听说暮色森林的幽灵们收藏着一份乐谱。"
D.Strings[79165]="我曾经和一位音乐家去冬泉谷野营，他很喜欢那里寒冷清冽的天气。我想再听听他的作品。"
D.Strings[79166]="灰谷是个神奇的地方。音乐家们都喜欢去那里找个荫凉的地方，花上几周时间谱写乐曲。"
D.Strings[79167]="黑暗神殿的挽歌曾响彻守望者的监狱。不知道我还能不能再次听到那些曲子。"
D.Strings[79168]="哪怕对于一首曲子来说，无敌都是一个出格的名字，更别说是一匹马了。"
D.Strings[79169]="歌剧院里有一份伟大的乐谱，如果你敢深入那里寻找它的话。"
D.Strings[79170]="要想鼓舞部队的士气，诺森德的勇气之歌是个好选择。"
D.Strings[79171]="精灵龙以创造迷人的音乐而著称，只要你能在正确的林地里找到它们。"
D.Strings[79172]="你愿意为新曲子拼命吗？我听说荆棘竞技场最近的奖品相当悦耳。"
D.Strings[79173]="我曾在诺森德的群山中遇见过一位头发花白的音乐家，非常有天赋。你应该去找他。"
D.Strings[79174]="如今，奥杜尔的泰坦之歌已经很难听到了。"
D.Strings[79175]="每次听到旋转木马的音乐总能让我回忆起童年。暗月马戏团那里或许会有乐谱？"
D.Strings[79176]="希尔瓦娜斯的传奇挽歌曾经被记录下来过。传说它被收藏在了一个非常安全的地方。"
D.Strings[79177]="泰兰德非常喜爱沙兰蒂斯岛的神秘音乐。我只在她那里见过这首曲子的乐谱。"
D.Strings[79178]="游学者对音乐的热爱，完全不亚于他们对美食和美酒的热爱。"
D.Strings[79179]="你喜欢美丽的大自然吗？去吧，去呼吸一下山间清新的空气！"
D.Strings[79180]="真清新！"
D.Strings[79181]="我早就说了。"
D.Strings[79182]="<深呼吸。>"
D.Strings[79183]="哈哈！快过来！是什么风把你给吹来了，朋友？"
D.Strings[79184]="我宁愿在旅店里呆着。"
D.Strings[79185]="要是那里在举行炉石比赛的话，你没准还能见到我父亲。"
D.Strings[79186]="我在寻找一首歌……"
D.Strings[79187]="没什么特别的。"
D.Strings[79188]="哈！那我就祝你一路顺风了。"
D.Strings[79189]="山间的……空气？"
D.Strings[79190]="你真的很喜欢谈论空气啊！说来说去就这么一个话题。\n\n要我说，这真是太乏味了。"
D.Strings[79191]="一首歌？毫无疑问，再也没有比伐木时唱首歌更快活的事了！\n\n你想找什么样的曲子？"
D.Strings[79192]="关于伐木的歌？"
D.Strings[79193]="关于冒险的歌！"
D.Strings[79194]="关于旷野的歌。"
D.Strings[79195]="我们可不唱关于伐木的歌。那简直是发疯。"
D.Strings[79196]="我对冒险恐怕没什么认识，我在这里生活了大半辈子。"
D.Strings[79197]="哈，那你就问对人了！旷野中既宁静又狂野，是完美的歌曲主题。\n\n我正好知道一首伐木工的老歌。你想要一张乐谱吗？"
D.Strings[79198]="是的，谢谢。"
D.Strings[79199]="好的，跟你聊天很愉快。"
D.Strings[79200]="给你！"
D.Strings[79201]="希望这首歌能让你想起诺森德的旷野。"
D.Strings[79202]="想要一首战歌吗？潘达利亚的统御岗哨曾终日回荡着低沉的鼓声。"
D.Strings[79203]="去雷霆崖钓钓鱼怎么样？众所周知，有位古怪的音乐家经常将自己的乐谱扔在那里。"
D.Strings[79204]="巨魔的音乐……非常有趣。他们最优秀的作品就藏在祖尔格拉布里。"
D.Strings[79205]="我该去哪里找乐谱？"
D.Strings[79206]="我需要更多的乐谱！我该去哪里充实我的收藏？"
D.Strings[79207]="真是个欣赏音乐的好日子，是吧，指挥官？"
D.Strings[79208]="寂静的要塞总是让人感到悲伤。音乐可以治愈一切！"
D.Strings[79209]="要我帮你开一份购物清单吗？\n\n我不鼓励犯罪，但鲜血竞技场的食人魔最喜欢低音炮。我觉得他们应该不会跟你死磕，但你拿了东西之后，最好还是赶紧跑路。\n\n我的镭射读碟器几周之前被偷了，而床上的地精臭气足足过了一周时间才散去。去宾奇维斯拓殖点看看吧。\n\n音效增幅器比较难搞，从鸦人的构装体身上扒一块金属应该就行了。\n\n如果你要去对付钢铁部落，那么他们在塔拉多的切割者身上应该会有我要的电容器。\n\n而最后的点睛之笔，则是取自戈尔隆德古树的木头。但愿树木终结者还给我们留了几棵。"
D.Strings[79210]="你想要什么鱼饵？"
D.Strings[79211]="深渊大嘴鳗"
D.Strings[79212]="海蝎子"
D.Strings[79213]="盲眼湖鲟"
D.Strings[79214]="黑水鞭尾鱼"
D.Strings[79215]="熔火鱿鱼"
D.Strings[79216]="无颚潜鱼"
D.Strings[79217]="塘鲈"
D.Strings[79218]="你有什么常用鱼饵吗？"
D.Strings[79219]="嘿，$c。我正想做点皮货买卖，你有兴趣吗？"
D.Strings[79220]="我们需要你潜入那座基地。潜入！潜行！别像癫狂的地精似的坐着火箭到处招摇。说实话，我们真不该给你造要塞。"
D.Strings[79221]="你不能同时拥有超过10个印记！过分扭曲命运会造成灾难性的后果。"
D.Strings[79222]="<拉安达上下打量了你几眼，压低了声音仓惶地说道。>$B$B你在做什么，$c？要是不想在执行要塞任务时被抓住，你就得穿上伪装。$B$B等你穿上萨格雷伪装再来找我吧。$B$B如果有必要，你可以干掉附近的萨格雷成员，拿走他们的衣物。不要暴露了我的伪装。"
D.Strings[79223]="我不能再给你既定命运印记了。下次再来吧。要么等你变得更加强大，足够驾驭这么多印记，否则还是老老实实等一段时间吧。"
D.Strings[79224]="%s施放了|cFFFF0000|Hspell:156446|h[冲击波]|h|r！快躲开！"
D.Strings[79225]="你疯了吗，把自己那样发射到天上！？你怎么不直接给古尔丹发个电报呢？要么领上美酒节的铜管乐队大摇大摆的走进去？这是潜行任务，$n！潜行！"
D.Strings[79226]="为了古尔丹！为了燃烧军团！"
D.Strings[79227]="为了……古尔丹……"
D.Strings[79228]="我们是钢铁部落！我们是不可战胜的！"
D.Strings[79229]="杀光他们，不留活口！"
D.Strings[79230]="我们的意志坚如钢铁！"
D.Strings[79231]="你们竟敢闯入我的港口，杀害我的士兵？来啊，面对我，来见识一下钢铁部落的实力吧！"
D.Strings[79232]="你们这些家伙还有没有点骨气？好好训练，否则我就把你们这些废物扔进海里去！"
D.Strings[79233]="古尔丹绝不容忍弱者！"
D.Strings[79234]="我发誓，你们要再不卖力点，我就让你们这些苦力全都得不到古尔丹的祝福！"
D.Strings[79235]="还不够。在你们打起精神来之前，口粮全部减半！"
D.Strings[79236]="我会率军佯攻西门，吸引钢铁部落的军力，好为你和德拉卡争取足够的时间，在他们的侧翼建立一个行动基地。"
D.Strings[79237]="让我们开始进攻吧。"
D.Strings[79238]="好了，小子们，码头是不会自己清空的！开始干活吧！"
D.Strings[79239]="不，不！我再也不能接受失败了！"
D.Strings[79240]="血环的掠夺者。我们得干掉他们，以免威胁到我们的补给线。"
D.Strings[79241]="古尔丹的走狗有阴谋。我不知道他们在黑暗之门附近搞些什么，但他们已经行动了。"
D.Strings[79242]="呸，这些火炮都是废物！来看看我们最新的造物，邪兽人吧！"
D.Strings[79243]="这边，指挥官！"
D.Strings[79244]="这里是最理想的位置，几英里外就能看见。插下你的旗帜吧，指挥官。"
D.Strings[79245]="我们该出发了！"
D.Strings[79246]="|TInterface\\Icons\\inv_blacksmithdye_black.blp:20|t%s掉落了|cFFFF0000|Hspell:180147|h[邪火弹药]|h|r。"
D.Strings[79247]="奇怪，古尔丹的部落几乎彻底放弃了这一地区。我以为会有一场激战的。"
D.Strings[79248]="血环氏族正在这一带肆虐。他们的首领在哪儿？"
D.Strings[79249]="那个术士又耍了什么邪恶魔法？我宁可跟钢铁部落的火炮作战！"
D.Strings[79250]="我收回刚才的话。我们得想办法杀过去。"
D.Strings[79251]="我的烈焰将吞噬一切！"
D.Strings[79252]="送我去钢铁前线。"
D.Strings[79253]="这些新来的邪兽人很拼命。我们不可能速战速决……"
D.Strings[79254]="你一登船，我们就开始了进攻。我们开始打得很保守，直到钢铁部落派出大队人马去对付你时，我们才开始了强攻！$b$b你们的加兹鲁维制造了一个恐怖的装置，它摧毁了大门，我们也随之冲了进去……结果却遇到了这些新对手……邪兽人。他们挡住了我们前进的步伐，把我们拖在这里。希望你在东边能比我们走运一些。"
D.Strings[79255]="进食"
D.Strings[79256]="卡兹说我可以帮忙！这地方太酷了！$b$b我可以给你介绍一下西北边的泽斯高，南边的沙纳尔神殿和东南边的佐拉姆沼泽。"
D.Strings[79257]="呃，好吧……你有什么新消息吗，斥候快刀？"
D.Strings[79258]="有！这些血环兽人都快跟嘲颅兽人一样危险了，可他们将太多时间都浪费在了抬头望天上。他们设置了大量的陷阱，能像迅猛龙一样在雨林中狩猎。眼下，他们正在镇子深处搞鬼，好像跟鲜血还有魔法有关。$b$b我想派一头玛戈隆直接踏平村子肯定会很不错！"
D.Strings[79259]="小心，指挥官！这里有萨格雷的人！"
D.Strings[79260]="萨格雷？上面出什么事了？"
D.Strings[79261]="不久之前，他们屠杀了那里的平民。我不敢靠得太近，但他们正在用邪能腐化野生动物并召唤恶魔。$b$b我们得把这个堕落的村子夷为平地，指挥官。"
D.Strings[79262]="嘿，指挥官。阿卡塔的岗哨里有鸦人。我还侦察了那条通往东南方的大隧道。"
D.Strings[79263]="鸦人在这里做什么？这又是谁？"
D.Strings[79264]="这就是阿卡塔。他是塞泰的信徒。暗影议会正在这附近的废墟中集结，他是来监视他们的。还有，一群会飞的鸦人正在这里制造麻烦。$b$b如果你要去东边的话，这里有一条通往东南方的大隧道，可以让你直达铁城港，但里面可能会有危险。"
D.Strings[79265]="现在，该展示一下我们的学习成果了！"
D.Strings[79266]="你竟敢打断我上课！"
D.Strings[79267]="啊……你的灵魂可以成为下一课的教具！"
D.Strings[79268]="指挥官！最新消息！有关铁城港，邪能熔炉和基尔加丹王座的。"
D.Strings[79269]="跟我说说铁城港的情况。"
D.Strings[79270]="古尔丹似乎正在召集德拉诺各地的钢铁部落成员。他们坐着船抵达港口……然后往东走……抵达矿坑。$b$b在那里，他们会被……转化成……邪兽人。这太可怕了。我们必须立刻摧毁这个地方！"
D.Strings[79271]="这是你的朋友？他死得很英勇……救了我……"
D.Strings[79272]="你的战士想要救我，可抓我的人追了上来。对于你的朋友，我非常抱歉。$b$b格罗玛什在山顶上杀死了一个强大的恶魔。它消停了一段时间，可现在钢铁部落又有了新主子……和新的目标。古尔丹的爪牙们正在召唤恶魔，并传播被邪能腐化的水。$b$b上面非常危险，你不能一个人上去。"
D.Strings[79273]="你就是智者拉戈？我带来了你的一位教友萨满的口信。他说……古尔丹知道了。我能问问这是什么意思吗？"
D.Strings[79274]="谢谢你，朋友。这意味着一个古老的秘密已经被史上最大的恶棍发现了。$b$b我要召集教派中剩下的同伴来一起保护它。$b$b你率领的部队也在对抗古尔丹？欢迎，我们会尽力协助你的。我们人数虽少，但很受德拉诺的元素之力尊重。$b$b我们可以稍后再来谈这个秘密。保重。"
D.Strings[79275]="非常好，你已经有进步了！很快你就能召唤出第一只小鬼了！"
D.Strings[79276]="集中精神，让混沌服从你的意志。"
D.Strings[79277]="你的意志必须坚强，就像食人魔一样！一旦露出疲软之态，你就死定了。我们的道路就是那么简单。"
D.Strings[79278]="我……觉醒了！"
D.Strings[79279]="很好，你很快就能学习下一课了。"
D.Strings[79280]="让黑暗能量在你体内流淌。集中精神！"
D.Strings[79281]="仪式能量变弱了，加把劲儿！"
D.Strings[79282]="我要把你的灵魂献给古尔丹，他一定会很高兴的！"
D.Strings[79283]="主人降临了！"
D.Strings[79284]="塞泰克必将再次崛起！"
D.Strings[79285]="我们已经看到了获取真正力量的道路！"
D.Strings[79286]="现在，我们又有了新的主人！"
D.Strings[79287]="主人需要祭品！"
D.Strings[79288]="来看看我学到的东西吧。"
D.Strings[79289]="好……多……鲜血！去死吧，血环的敌人！"
D.Strings[79290]="我要杀光干扰仪式的家伙！准备受死吧！"
D.Strings[79291]="你们太脆弱、太虚弱了。"
D.Strings[79292]="执行者，实现我的意志！"
D.Strings[79293]="<这个古怪的侏儒机器人一只眼睛挂在眼眶外面。它的胸口有一块硬纸板，上面写着“测试版”。它的大部分电线都是用胶带固定的。突然，它用电子音开口说道：>$b$b你好，冒险者、者、者*咔咔*！输入、入、入*叮*测试参数重启001011010。你好，冒险者！"
D.Strings[79294]="保护瑞沙德。"
D.Strings[79295]="来吧，兄弟们！把握你们的命运！"
D.Strings[79296]="站起来，多格！起来为你死去的同胞们复仇！"
D.Strings[79297]="猎血者祖尔克！中断的仪式太多了，干掉这些入侵者！"
D.Strings[79298]="鲜血之月升起，它将让我们的酋长变得更强大！欢呼吧，血环兽人们，他很快就将所向披靡！"
D.Strings[79299]="鲜血之月枯竭了！快，激活它的残片，收回残留的力量！"
D.Strings[79300]="你们这些该死的入侵者！鲜血之月必将再次升起！"
D.Strings[79301]="主人需要更多的灵魂！"
D.Strings[79302]="我将畅饮你的鲜血！"
D.Strings[79303]="呱！你竟敢伤害我的信徒？准备见识塞泰的复仇吧！"
D.Strings[79304]="送我去阿卡塔的岗哨。"
D.Strings[79305]="我和珀西先走。你准备好之后，就让飞行管理员送你过来吧。"
D.Strings[79306]="哈哈！滚回虚空去吧！"
D.Strings[79307]="他们将血流成河。我要让他们尝尝流血的滋味。"
D.Strings[79308]="我等不及了——跟上！"
D.Strings[79309]="这座祭坛已经严重损毁了。"
D.Strings[79310]="嗯？我还是新手。我在组建套牌时，有什么要注意的吗？"
D.Strings[79311]="我靠着这套新战术连战连捷。我管这套牌叫“动物园”。"
D.Strings[79312]="又被精神控制了？不——！"
D.Strings[79313]="什么？！？伐木机里怎么会蹦出龙来？\n"
D.Strings[79314]="鱼人？不——！为什么会是鱼人？"
D.Strings[79315]="你刚才对我放狗了吗？"
D.Strings[79316]="看来我又赢了。但你也打得不错。"
D.Strings[79317]="这个雕文表面布满精美的未知文字，但一大半似乎都不见了。"
D.Strings[79318]="古尔丹的大军正在地狱火堡垒的高墙后等着我们。但那里究竟有多恐怖，我们还不得而知。$B$B我们在雄狮岗哨的部队会挡住恶魔的威胁，不死不休。"
D.Strings[79319]="这个卷轴是送给艾斯卡的。你赶紧把它拿给瑞沙德看。"
D.Strings[79320]="啊，有意思……“到塔纳安来。协助我，我会让你重返天空。”"
D.Strings[79321]="<这个死亡的兽人手里抓着一封未发出的信。>$B$B亲爱的妈妈，我决定离开钢铁部落的军队。$B$B蛆虫已经不够吃了，我想念你做的饭了。$B$B爱你的，儿子。"
D.Strings[79322]="唔……你看起来很好吃！"
D.Strings[79323]="|cFFFF0000%s|r即将发动猛烈的攻击！"
D.Strings[79324]="这是谁写的？来，我们得继续搜索。"
D.Strings[79325]="泰罗克的祭坛！塞泰克们尊崇利爪之王，他们为何要亵渎自己的祭坛？唔……我们得继续调查。"
D.Strings[79326]="我们知道你和你的怪物为何来此。"
D.Strings[79327]="不要攻击。这是什么地方？"
D.Strings[79328]="血环氏族的历代酋长都会在这个洞穴里举行一个预见未来的仪式，见证自己的死亡。而其他酋长……他们只是盲从基尔罗格而已……但我们不会。格罗玛什还算有能耐，而古尔丹……\n\n我们感觉到了德拉诺深处的躁动。我们认为古尔丹会对德拉诺造成严重的伤害，我们的部族会因此而遭受重创。"
D.Strings[79329]="啊，这是埃匹希斯语。“……埋葬……邪恶……禁忌……”没有另一半碎片，我就只能认出这些词了。我们继续。"
D.Strings[79330]="那我们就有共同的麻烦了。你愿意帮我们吗？"
D.Strings[79331]="……可以。我可以让你……看到……基尔罗格的部分未来……还有你自己的未来。"
D.Strings[79332]="这是什么？这本书……很眼熟。"
D.Strings[79333]="很高兴你们能从上次突袭中活下来，但只要燃烧军团发动总攻，我们就死定了。"
D.Strings[79334]="能与你们并肩作战是我的荣幸，但我们的力量还不足以拯救艾泽拉斯。在死神到来前，我们只能尽力多赶些恶魔返回扭曲虚空！"
D.Strings[79335]="把它们聚集起来，勇士们！让我用魔法搞定它们！"
D.Strings[79336]="代我向萨格拉斯问好！"
D.Strings[79337]="你别想轻易击败我们！"
D.Strings[79338]="我们要抽出你们的灵魂。"
D.Strings[79339]="必须保护我们的圣地……"
D.Strings[79340]="我不会让你抢走它的！"
D.Strings[79341]="去死吧，亵渎者！"
D.Strings[79342]="这里的幽灵非常焦躁。我们的存在激怒了它们。但它们休想阻止我们。"
D.Strings[79343]="我们走。帮我找到基尔罗格。"
D.Strings[79344]="这里不欢迎你，外来者，但我们必须谈谈。"
D.Strings[79345]="他们正在猛攻泽斯高。我们得撤退，保护家——"
D.Strings[79346]="耐心点，基尔罗格。你的战士们得继续寻找秘文。"
D.Strings[79347]="只要我得到秘文，敌人就将无立锥之地……等等——你感觉到了吗？我们被监视了。别动。"
D.Strings[79348]="你们的圣地被亵渎了，基尔罗格。别担心——我已经解决了。"
D.Strings[79349]="我们要找索洛格·拉克！"
D.Strings[79350]="我们不要你的命。我们需要一名造船师。"
D.Strings[79351]="我就是。如果你们想要我的命，就让我们真刀真枪地干上一场。"
D.Strings[79352]="哈！那我可是最棒的。"
D.Strings[79353]="快使用那个眼睛！我来阻止幽灵攻击你。"
D.Strings[79354]="基尔罗格……在堡垒里。必须杀了他……在我……彻底迷失之前……"
D.Strings[79355]="你的血环走狗失败了，古尔丹。他们还是那么蠢笨。"
D.Strings[79356]="傲慢可不好，艾斯卡。你的秘文研究得怎么样了？莫非你也是个……失败者？"
D.Strings[79357]="我在废墟中发现了线索，提到隐藏在大地中的黑暗力量。这碎片能带你去封印之地。"
D.Strings[79358]="干得好，艾斯卡！成功者将得到奖励。"
D.Strings[79359]="喝了它，你就能再次飞翔了。"
D.Strings[79360]="这……我的翅膀又充满了力量！我誓死效忠你，主人！"
D.Strings[79361]="去吧，组建一支鸦人大军。他们也将效忠军团。"
D.Strings[79362]="基尔罗格和其他人……在此自残。这是……献祭？"
D.Strings[79363]="是基尔罗格的眼睛，我能闻出来。快走，幽灵被激怒了。"
D.Strings[79364]="看看我们能发现什么。哦，小心点，这可能会引来别人的注意。"
D.Strings[79365]="我看够了。艾斯卡背弃了我们，他用一个诅咒换来了另一个诅咒。"
D.Strings[79366]="这力量——在我体内流淌！这是前所未有的体验。"
D.Strings[79367]="古尔丹会救我们的。他是我们最后的希望。他就是真理！"
D.Strings[79368]="燃烧军团的力量无穷无尽。你们将不再恐惧，不再犹疑，一切都是如此清晰！"
D.Strings[79369]="你们的命运就在塔纳安。来吧！饮下邪能的恩赐，你们就将成为战争的化身。"
D.Strings[79370]="你们的领袖辜负了你们！只有古尔丹能拯救我们的民族。加入我们，否则败亡就在眼前。"
D.Strings[79371]="这不是你们的命运。古尔丹会带领我们走向胜利。现在还不迟！"
D.Strings[79372]="消灭他们——以古尔丹的名义！"
D.Strings[79373]="没人能阻挡我们。"
D.Strings[79374]="如果你有本事，尽管杀了我吧——可没有人能阻挡我所侍奉的燃烧军团！"
D.Strings[79375]="以古尔丹之名，又一场胜利！"
D.Strings[79376]="这力量——这是你从未体验过的感受。"
D.Strings[79377]="信仰古尔丹吧，他掌握着真理。"
D.Strings[79378]="我们时代已经降临了。古尔丹会拯救我们。我们的力量将无穷无尽！"
D.Strings[79379]="邪能不是诅咒，而是恩赐。一份奇迹般的恩赐！"
D.Strings[79380]="<瑞沙德扫视着书页。>$B$B看来，他其实是来这里藏匿他关于这个”秘文“的研究的。这可真是伤脑筋，我们还有许多未解之谜。$b$b我这儿有一小瓶魔法沙子，配合这本书，我们就能看到这本书最后在艾斯卡手中时的情形。$b$b你准备好之后，我们就来看看到底发生了什么事。"
D.Strings[79381]="为了古尔丹！"
D.Strings[79382]="你休想击败我们。我们是燃烧军团！"
D.Strings[79383]="为了古尔丹的荣耀！"
D.Strings[79384]="都动起来！我们得把这些补给品运去塔纳安。"
D.Strings[79385]="我们要出发了。快快快！"
D.Strings[79386]="快点，你们这些苦力，否则就把你们丢下。"
D.Strings[79387]="古尔丹让我们去塔纳安。这是我们最后的机会了。把那些箱子拖走！"
D.Strings[79388]="快点，再快点。快把这件设备搬上去塔纳安的船。今天之内搞定它，你们这些懒虫！"
D.Strings[79389]="这里不宜久留。我要回阿卡塔的营地去了。"
D.Strings[79390]="要是还有人能阻止艾斯卡，那就是你了。"
D.Strings[79391]="我刚跟阿卡塔谈过。你知道他在被信徒们放逐之前，曾是一位空军上将吗？"
D.Strings[79392]="保护好阿卡塔，珀西。我很快就回来。"
D.Strings[79393]="信徒们！你们的使命尚未完成！"
D.Strings[79394]="我……又一次……"
D.Strings[79395]="回到突破口了！"
D.Strings[79396]="我是执行者的意志……也是你的末日。"
D.Strings[79397]="你休想再前进一步！"
D.Strings[79398]="我是……永恒不灭的……"
D.Strings[79399]="先驱，为我疗伤！"
D.Strings[79400]="统御者掩护我！"
D.Strings[79401]="艾瑞达很了解战争。你们就这么急着送死吗？"
D.Strings[79402]="够了！这里就是你们的葬身之地！"
D.Strings[79403]="真是个……悲剧……"
D.Strings[79404]="正义的烈焰风暴！"
D.Strings[79405]="爬虫只配被碾死！"
D.Strings[79406]="你们可悲的失败……是不可避免的。"
D.Strings[79407]="你们的努力是徒劳的。"
D.Strings[79408]="你们的存在毫无意义。"
D.Strings[79409]="你们的失败早已注定。"
D.Strings[79410]="你们的想法无关紧要。"
D.Strings[79411]="快点干，我绝不允许继续延误下去！"
D.Strings[79412]="如果这具机甲不能按时完成，我就吞掉你们的灵魂！"
D.Strings[79413]="对！努力挣扎吧，凡人！我正需要来点乐子。"
D.Strings[79414]="我要吃掉你的心脏！"
D.Strings[79415]="你要为这次捣乱付出代价！"
D.Strings[79416]="还……没完呢！"
D.Strings[79417]="我还会回来的……我会……为自己复仇……"
D.Strings[79418]="蠢货！暗影背叛了你！"
D.Strings[79419]="我的项链上又可以多一只耳朵了！"
D.Strings[79420]="我在钢铁码头见过你！这次你输定了！"
D.Strings[79421]="准备交战！"
D.Strings[79422]="压制那个目标！"
D.Strings[79423]="感谢你们省了我剔除弱者的麻烦。来吧，我来让你们见识一下真正的战斗！"
D.Strings[79424]="很快，你就会跪地求死了！"
D.Strings[79425]="你怕疼吗？"
D.Strings[79426]="不想试试吗？"
D.Strings[79427]="啊，你一定是喜极而泣了。"
D.Strings[79428]="我已经厌倦了整天期待真正挑战的生活了。"
D.Strings[79429]="我早知道你不是我的对手！"
D.Strings[79430]="去见你的上帝去吧！"
D.Strings[79431]="这么急着去见你的先祖吗？"
D.Strings[79432]="很遗憾，你的灵魂再也见不到奥金顿了！"
D.Strings[79433]="纳鲁的许诺都是空头支票。新主人却赐予了我们真正的力量！"
D.Strings[79434]="在燃烧军团赐予的强大力量面前，信仰又有什么意义？"
D.Strings[79435]="蠢货！你选择了错误的道路！"
D.Strings[79436]="燃烧军团就是真理。燃烧军团就是力量！"
D.Strings[79437]="在圣光中，我只看到了一片虚无。"
D.Strings[79438]="是谁竟敢打扰我？"
D.Strings[79439]="真是麻烦。我就先解决了你！"
D.Strings[79440]="Katra zil shukil！去死吧，傲慢的家伙！"
D.Strings[79441]="把我们的秘密带进坟墓里去吧！"
D.Strings[79442]="燃烧军团的力量在我体内流淌！"
D.Strings[79443]="他们来了，塔隆！我们得走了。"
D.Strings[79444]="不！这么多灵魂……这么强大的力量……"
D.Strings[79445]="你休想打断我的盛宴！"
D.Strings[79446]="你的灵魂也将属于我。"
D.Strings[79447]="我必须得到它！"
D.Strings[79448]="我要让你看看我的新力量！"
D.Strings[79449]="住手，不准再亵渎我们的先祖！"
D.Strings[79450]="去死吧，邪恶的畜生！"
D.Strings[79451]="呸！等古尔丹解决了你们，我还会回来的。"
D.Strings[79452]="卑贱的$c，让新世界的烈焰净化你吧！"
D.Strings[79453]="你们被召集到这里，因为你们都是弱者。我们已经全线溃败。此时此刻，敌人正在步步进逼。"
D.Strings[79454]="我们为什么会落得如此下场？因为傲慢。地狱咆哮愚蠢的傲慢让我们失去了发挥真正潜力的机会。"
D.Strings[79455]="但仁慈的古尔丹又给了你们一次超越凡人极限的机会！分享这份恩赐，抓紧你们曾失之交臂的力量吧！"
D.Strings[79456]="你们被选中了来分享主人的恩赐。上前一步，喝下它，获取你们曾错失的力量吧！"
D.Strings[79457]="我们必须在他们完成任务前干掉他们。"
D.Strings[79458]="这个血魔吞噬的万千灵魂令我恐惧。我们必须消灭他！"
D.Strings[79459]="挡住他们，玛诺洛斯。我就快成功了。主人降临了……"
D.Strings[79460]="|TInterface\\Icons\\warlock_summon_doomguard.blp:20|t|cFFFF0000$n|r 受到了|cFFFF0000|Hspell:181275|h[军团诅咒]|h|r的影响!"
D.Strings[79461]="|cFFFF0000%s|r出现并开始强化邪能尖塔！"
D.Strings[79462]="啊！！！！！"
D.Strings[79463]="嗷！！！！！"
D.Strings[79464]="|cFFFF0000%s|r开始强化邪能尖塔！"
D.Strings[79465]="去死！去死！去死！"
D.Strings[79466]="我是不朽的！"
D.Strings[79467]="血……鲜血！不行了……必须——杀！"
D.Strings[79468]="如此……黑暗……"
D.Strings[79469]="我死而无憾……"
D.Strings[79470]="再来……一下……"
D.Strings[79471]="我……终于自由了……"
D.Strings[79472]="我……真不该……喝……"
D.Strings[79473]="你让一切都变得简单了。"
D.Strings[79474]="这很残忍……但也很必要。"
D.Strings[79475]="跟他们一起回到阴影中去吧。"
D.Strings[79476]="没想到这么快就结束了。"
D.Strings[79477]="|cFFFF0000%s|r开始对你施放|cFFFF0000|Hspell:182178|h[邪能飞轮]|h|r！"
D.Strings[79478]="我会率军佯攻西门，吸引钢铁部落的军力，好为你和伊瑞尔争取足够的时间，在他们的侧翼建立一个行动基地。"
D.Strings[79479]="钢铁部落几乎放弃了这一区域。我以为码头上会有激战的。"
D.Strings[79480]="血环的掠夺者。我们必须解决他们的首领，把他们撵回丛林里去！"
D.Strings[79481]="又一条献给燃烧军团的灵魂。"
D.Strings[79482]="我们要把你们的灵魂劈成两半。"
D.Strings[79483]="我们是毁灭的先锋。"
D.Strings[79484]="腐化的灵魂总是手到擒来。"
D.Strings[79485]="你休想压制我们的力量！"
D.Strings[79486]="我们播种死亡。"
D.Strings[79487]="见证燃烧军团的力量吧。"
D.Strings[79488]="烈焰！死亡！毁灭！"
D.Strings[79489]="我们万众一心。"
D.Strings[79490]="我们势不可挡！"
D.Strings[79491]="威力全开！"
D.Strings[79492]="我们要吞噬这个渺小的世界。"
D.Strings[79493]="我们被……击败了。"
D.Strings[79494]="既然这些掠夺者还在到处晃悠，那古尔丹的其他手下呢？他们可能在前头等着我们。"
D.Strings[79495]="术士的肮脏魔法！要是让古尔丹得逞，整个世界都会化为火海。"
D.Strings[79496]="这里只剩下掠夺者和术士了。古尔丹的爪牙在这么靠近黑暗之门废墟的地方做什么？"
D.Strings[79497]="古尔丹的邪能魔法甚至腐蚀了钢铁部落的军械！我们必须打垮这个铁壳子……"
D.Strings[79498]="|TInterface\\Icons\\Spell_Shadow_GatherShadows.blp:20|t你被|cFFFF0000|Hspell:179711|h[玷污]|h|r了，快远离你的盟友！"
D.Strings[79499]="|TInterface\\Icons\\spell_fel_elementaldevastation.blp:20|t一股|cFFFF0000|Hspell:181498|h[毁灭之力]|h|r击中了一颗|cFFFF0000|Hspell:179620|h[邪能水晶]|h|r！"
D.Strings[79500]="|TInterface\\Icons\\spell_fel_elementaldevastation.blp:20|t$n的|cFFFF0000|Hspell:182008|h[潜伏能量]|h|r在进入|cFFFF0000|Hspell:179582|h[轰鸣的裂隙]|h|r后发生了剧烈反应！"
D.Strings[79501]="|TInterface\\Icons\\spell_fel_elementaldevastation.blp:20|t$n的|cFFFF0000|Hspell:182008|h[潜伏能量]|h|r被 |cFFFF0000|Hspell:181498|h[毁灭之力]|h|r击中后发生了剧烈反应！"
D.Strings[79502]="它归我们了，滚回海里去！"
D.Strings[79503]="基尔罗格会……为我复仇……"
D.Strings[79504]="|TInterface\\Icons\\Spell_Shadow_ChillTouch.blp:20|t|cFFFF0000|Hspell:182008|h[潜伏能量]|h|r腐蚀了你！"
D.Strings[79505]="|TInterface\\Icons\\Spell_Shadow_SeedOfDestruction.blp:20|t你的|cFFFF0000|Hspell:181508|h[毁灭之种]|h|r将施放出|cFFFF0000|Hspell:181498|h[毁灭之力]|h|r。"
D.Strings[79506]="|TInterface\\Icons\\ability_deathwing_grasping_tendrilsgreen.blp:20|t|cFFFF0000|Hspell:179582|h[轰鸣的裂隙]|h|r凝结成了|cFFFF0000|Hspell:179620|h[邪能水晶]|h|r！"
D.Strings[79507]="|TInterface\\Icons\\ability_warlock_moltencoregreen.blp:20|t邪能领主扎昆的战斧开始施放|cFFFF0000|Hspell:179622|h[邪能爆破]|h|r！"
D.Strings[79508]="|TInterface\\Icons\\inv_axe_2h_pvphorde_a_01blackhigh.blp:20|t邪能领主扎昆重新拿起战斧，再次|cFFFF0000|Hspell:179670|h[武装]|h|r了自己。"
D.Strings[79509]="|TInterface\\Icons\\inv_axe_2h_orgrimmarraid_d_01.blp:20|t邪能领主扎昆陷入疯狂，进入|cFFFF0000|Hspell:179671|h[全副武装]|h|r状态！"
D.Strings[79510]="|TInterface\\Icons\\warrior_talent_icon_mastercleaver.blp:20|t邪能领主扎昆的战斧释放出了|cFFFF0000|Hspell:181498|h[毁灭之力]|h|r！"
D.Strings[79511]="总算可以暂时摆脱这些无聊的“准备工作”了！"
D.Strings[79512]="他会复活我的……他离不开……我们……"
D.Strings[79513]="快，你一定要看看这个地方！"
D.Strings[79514]="好地方……射程合适……适合侦察。我建议你把旗帜插在这里，指挥官。"
D.Strings[79515]="我们的损失几乎无法承受……但我们挺过来了。胜利！"
D.Strings[79516]="你一登船，我们就开始了进攻。起先这看似将是一场持久战，但中途他们突然有大队人马离开，可能就是你从东面发动攻击的时候。$b$b我们立刻开始不惜代价的攻击。塞林制造了一个强力攻城槌，它迅速摧毁了大门。然后我们就遇到了这些新对手……邪兽人。他们迎头痛击了我们，令我们无法再进一步。希望你在东边能比我们走运一些。"
D.Strings[79517]="我们又见面了，朋友。这里不是戈尔隆德，但我也不怀念那些震天动地的巨兽！$b$b我这里有关于泽斯高、沙纳尔神殿和佐拉姆沼泽的报告。"
D.Strings[79518]="跟我说说泽斯高。"
D.Strings[79519]="这些血环兽人是可怕的猎人和陷阱大师，在这片丛林里可谓是如鱼得水。眼下，他们正在村子深处施展黑暗的血魔法。那肯定不是什么好东西，所以我建议我们要尽快将这座村子化为灰烬！"
D.Strings[79520]="这个可怜的村子……被萨格雷踏平了……"
D.Strings[79521]="沙纳尔神殿出了什么事？"
D.Strings[79522]="他们不久前摧毁了这个村子，将它变成了训练场，在此召唤恶魔，并将野生动物腐化成邪能武器。$b$b我们必须为那些无辜丧生的人们复仇，指挥官！"
D.Strings[79523]="狩猎还在继续，指挥官。我有关于西北边阿卡塔的岗哨以及那条通向东南方铁皇堡的大隧道的报告。"
D.Strings[79524]="塔纳安出现了鸦人？跟我说说这个阿卡塔的岗哨。"
D.Strings[79525]="流亡者很担心他们的同胞。一些迷失的灵魂接受了暗影议会的邪能魔法以及恶魔召唤训练。尽管他们招揽了一些高阶鸦人，但那个地方还是非常危险，你得找些盟友一起去扫荡那里。我们得尽快清除这个毒瘤。"
D.Strings[79526]="我好像从来没见过比这里更要命的地方！$b$b话虽如此，但我还是有一些关于西北边的铁城港、东南边的邪能熔炉以及山顶的基尔加丹王座的早期情报。"
D.Strings[79527]="我看见不少船只驶入了那座港口，那里出什么事了？"
D.Strings[79528]="钢铁部落似乎将所有的远征部队都召集了回来。大部分的部队刚登上码头就被转化了。剩余的则留下来为部队运送弹药和其他物资。$b$b如果让古尔丹将整个钢铁部落都成功转化，他就将拥有一支无法战胜的大军！"
D.Strings[79529]="不要抗拒了，阿里乌克。释放你的怒火吧。"
D.Strings[79530]="放开我，我会让你看看我的怒火，基尔罗格。"
D.Strings[79531]="你只有两个选择，阿里乌克。服从，或死亡。"
D.Strings[79532]="我一直在等这一天！"
D.Strings[79533]="看看我在倒下前能干掉几个！"
D.Strings[79534]="看着我的眼睛，见证你的末日吧！"
D.Strings[79535]="我要宰了你！"
D.Strings[79536]="这是你想要的死法吗？"
D.Strings[79537]="你真的以为你能杀得了我吗？"
D.Strings[79538]="你们不是我等的人。"
D.Strings[79539]="终于，这正是我预见到的末日！"
D.Strings[79540]="你们很快就将和艾泽拉斯一起燃烧！"
D.Strings[79541]="消灭弱者！"
D.Strings[79542]="|TInterface\\Icons\\Ability_GolemThunderClap.blp:20|t考莫克开始|cFFFF0000|Hspell:180244|h[重击]|h|r地面！"
D.Strings[79543]="|TInterface\\Icons\\Spell_Shaman_TidalWaves.blp:20|t暗影之池开始生成|cFFFF0000|Hspell:181292|h[邪能暗流]|h|r!"
D.Strings[79544]="|TInterface\\Icons\\Spell_Shaman_TidalWaves.blp:20|t所有三个暗影之池都开始生成|cFFFF0000|Hspell:181293|h[邪能暗流]|h|r!"
D.Strings[79545]="|TInterface\\Icons\\spell_fire_rune.blp:20|t地面上出现了|cFFFF0000|Hspell:181296|h[爆炸符文]|h|r！"
D.Strings[79546]="|TInterface\\Icons\\spell_fire_rune.blp:20|t地面上出现了|cFFFF0000|Hspell:181297|h[强化爆炸符文]|h|r！"
D.Strings[79547]="|TInterface\\Icons\\Spell_Shadow_Requiem.blp:20|t考莫克从地下召唤出了|cFFFF0000|Hspell:181299|h[攫取之手]|h|r！"
D.Strings[79548]="|TInterface\\Icons\\Spell_Shadow_Requiem.blp:20|t考莫克从地下召唤出了|cFFFF0000|Hspell:181300|h[牵引之手]|h|r！"
D.Strings[79549]="|TInterface\\Icons\\inv_offhand_stratholme_a_02.blp:20|t$n被|cFFFF0000|Hspell:181305|h[重击]|h|r击飞！"
D.Strings[79550]="|TInterface\\Icons\\spell_arcane_teleportdalarancrater.blp:20|t由于无人为其吸收|cFFFF0000|Hspell:182427|h[冲击]|h|r，$n死亡。"
D.Strings[79551]="|TInterface\\Icons\\Ability_Mage_LivingBomb.blp:20|t$n即将|cFFFF0000|Hspell:181324|h[爆炸]|h|r！"
D.Strings[79552]="|TInterface\\Icons\\Spell_DeathKnight_Strangulate.blp:20|t一只邪能之手开始|cFFFF0000|Hspell:181345|h[碾压]|h|r$n！"
D.Strings[79553]="|TInterface\\Icons\\INV_Bijou_Purple.blp:20|t考莫克跳入暗影之池，获得了|cFFFF0000|Hspell:181293|h[强化邪能暗流]|h|r技能。"
D.Strings[79554]="|TInterface\\Icons\\INV_Bijou_Orange.blp:20|t考莫克跳入火焰之池，获得了|cFFFF0000|Hspell:181297|h[强化爆炸符文]|h|r技能。"
D.Strings[79555]="|TInterface\\Icons\\INV_Bijou_Green.blp:20|t考莫克跳入邪污之池，获得了|cFFFF0000|Hspell:181300|h[强化邪能之握]|h|r技能。"
D.Strings[79556]="|TInterface\\Icons\\INV_Bijou_Purple.blp:20|t考莫克跳入暗影之池，获得了|cFFFF0000|Hspell:181292|h[邪能暗流]|h|r技能。"
D.Strings[79557]="|TInterface\\Icons\\INV_Bijou_Orange.blp:20|t考莫克跳入火焰之池，获得了|cFFFF0000|Hspell:181296|h[爆炸符文]|h|r技能。"
D.Strings[79558]="|TInterface\\Icons\\INV_Bijou_Green.blp:20|t考莫克跳入邪污之池，获得了|cFFFF0000|Hspell:181299|h[邪能之握]|h|r技能。"
D.Strings[79559]="|TInterface\\Icons\\INV_Bijou_purple.blp:20|t考莫克跳入暗影之池，造成了一次|cFFFF0000|Hspell:181365|h[剧烈反应]|h|r！"
D.Strings[79560]="|TInterface\\Icons\\INV_Bijou_orange.blp:20|t考莫克跳入火焰之池，造成了一次|cFFFF0000|Hspell:181370|h[剧烈反应]|h|r！"
D.Strings[79561]="|TInterface\\Icons\\INV_Bijou_green.blp:20|t考莫克跳入邪污之池，造成了一次|cFFFF0000|Hspell:181371|h[剧烈反应]|h|r！"
D.Strings[79562]="|TInterface\\Icons\\spell_fire_rune.blp:20|t$n触发了一个|cFFFF0000|Hspell:180370|h[爆炸符文]|h|r。"
D.Strings[79563]="|TInterface\\Icons\\spell_fire_rune.blp:20|t一个|cFFFF0000|Hspell:180370|h[爆炸符文]|h|r自行爆炸了。"
D.Strings[79564]="|TInterface\\Icons\\Trade_Engineering.blp:20|t|cFFFF0000|Hspell:181300|h[强化邪能之手]|h|r |cFFFF0000|Hspell:180442|h[释放]|h|r出了一股致命的邪能！"
D.Strings[79565]="%s将你选为|cFFFF0404|Hspell:180372|h[剖心飞刀]|h|r的目标！"
D.Strings[79566]="血魔即将|TInterface\\Icons\\Spell_Shadow_DeathCoil:20|t|cFFFF0404|Hspell:181295|h[消化]|h|r你！"
D.Strings[79567]="这是你的朋友吗，阿里乌克？不，等等……你们有点眼熟。"
D.Strings[79568]="多谢了，英雄们。我愿意加入你们。"
D.Strings[79569]="我死也不投靠燃烧军团！"
D.Strings[79570]="你无法反抗命运，阿里乌克！你只能接受它！"
D.Strings[79571]="你是指挥官？拜托，你一定要听我说，德拉诺已经命悬一线！古尔丹已经发现了！他发现了秘文！"
D.Strings[79572]="有话快说，术士。"
D.Strings[79573]="古尔丹想用诅咒密码腐化德拉诺的元素。他会将这座雨林化为地狱火海的。$b$b直到此刻，我才看清了他的疯狂和恨意。$b$b快！古尔丹已经知道了有萨满守护者在保护着秘文。他已经前去攻打他们的要塞了。必须有人去保护他们。"
D.Strings[79574]="我这就去。"
D.Strings[79575]="救命！古尔丹……他在里面！"
D.Strings[79576]="终于！有了它，我就能让地狱火肆虐大地。元素将在我面前颤栗。"
D.Strings[79577]="你太迟了，英雄。秘文归我了。你的大军将燃烧殆尽！"
D.Strings[79578]="不值一提。"
D.Strings[79579]="搞清你的身份，废物！"
D.Strings[79580]="噢，那家伙死了吗？"
D.Strings[79581]="如此软弱，这一定很痛苦吧？"
D.Strings[79582]="准备好，勇士，我不知道这道屏障后面有什么，但肯定不会是什么好东西。"
D.Strings[79583]="快好了……"
D.Strings[79584]="完成了……去吧。阻止古尔丹！"
D.Strings[79585]="我一定要拿到那些图纸。那是我毕生的结晶。"
D.Strings[79586]="%s从阵亡的敌人尸体上拾取了一把火枪。"
D.Strings[79587]="我们走，拉克！"
D.Strings[79588]="我们行动吧。这儿都被古尔丹变成新兵营了。"
D.Strings[79589]="森卢肯！你不再是萨满的仆人了。断开跟他们的联系，毁灭这片土地！"
D.Strings[79590]="不！他怎么会被击败？！"
D.Strings[79591]="黑手下令造了一座巨型火炮。于是我就造了一艘巨舰来搭载它。但有时船并不是越大越好——我们的战术在沙塔斯外的水域彻底失败了。"
D.Strings[79592]="我们都使用这些爪钩将战舰拖进港口……"
D.Strings[79593]="所以你必须在建筑上布满尖刺！"
D.Strings[79594]="我来望风。你去拿图纸。"
D.Strings[79595]="这个渣滓在我的码头上做什么！？"
D.Strings[79596]="古尔丹……会解决这个……"
D.Strings[79597]="和基尔罗格作对的人都得死！"
D.Strings[79598]="你的尸体将成为我们的仪式材料！"
D.Strings[79599]="我要活剥了你的皮！"
D.Strings[79600]="荣耀属于血环！"
D.Strings[79601]="你的血会很有用的！"
D.Strings[79602]="基尔罗格……我辜负了你……"
D.Strings[79603]="杀了你……杀了……你……"
D.Strings[79604]="我的兄弟们会让你付出代价的。"
D.Strings[79605]="基尔罗格必胜……"
D.Strings[79606]="统统扫平踏碎！"
D.Strings[79607]="基尔罗格有新鲜血液用了！"
D.Strings[79608]="碾碎……你……"
D.Strings[79609]="终于能……安息了……"
D.Strings[79610]="不……基尔罗格……"
D.Strings[79611]="试试躲开我的标枪吧，蠢货！"
D.Strings[79612]="标枪……你们辜负了我……"
D.Strings[79613]="如果你敢逃，我一定会追杀你到天涯海角！"
D.Strings[79614]="无论你逃到哪里……我的猎人们都会找到你……"
D.Strings[79615]="鲜血之月有新鲜血液用了！"
D.Strings[79616]="我的鲜血……属于基尔罗格……"
D.Strings[79617]="你阻止不了仪式，你只能成为其中的一员！"
D.Strings[79618]="我的鲜血……和别人的一起……"
D.Strings[79619]="我会抽干你的鲜血，这就是捣乱的代价！"
D.Strings[79620]="我不是最后一个……"
D.Strings[79621]="我们曾救过德拉诺，我会帮你再拯救它一次的。"
D.Strings[79622]="这些新火炮……是另外一种东西……"
D.Strings[79623]="可怜的人。古尔丹会不惜一切夺取他想要的东西。"
D.Strings[79624]="黑烛是什么？"
D.Strings[79625]="黑烛……我不知道古尔丹是从哪儿弄到的。它永燃不尽，而且被它的邪恶火焰点燃的东西会散发出腐化的浓烟。\n\n我的指尖还残留着它那油腻的触感。"
D.Strings[79626]="防御宝典是什么？"
D.Strings[79627]="这本书是从元首马尔高克那里偷来的，但他将此归咎于霜狼氏族了。它在本质上更偏向奥术魔法，但术士们也可以使用。\n\n这本书中记载的魔法是屏障法术的核心要素。别担心，我可以驱散它，但代价可能会很大。"
D.Strings[79628]="这个……麦古芬是什么？"
D.Strings[79629]="这是一个谜。古尔丹费尽千辛万苦才弄到这把匕首。他说那是一段非常危险的冒险。\n\n他再三跟我强调，这把匕首是法术中最重要的部分。老实说，我握着它时，一点感觉都没有。我不是很确定它究竟有没有用，但我们最好还是拿上它，以防万一。否则古尔丹也不会把它给我……对吧？"
D.Strings[79630]="你闯入了神圣的土地！"
D.Strings[79631]="我会用我不朽的灵魂保卫这些眼球！"
D.Strings[79632]="你以为自己能抢走血环最珍贵的遗物吗？！"
D.Strings[79633]="其他人会继承我的遗志，继续保卫这些研究的……"
D.Strings[79634]="你总有一天会付出代价的……无信者……"
D.Strings[79635]="基尔罗格……他们来找眼球了……"
D.Strings[79636]="我辜负了酋长……"
D.Strings[79637]="你会付出代价的……亵渎者……"
D.Strings[79638]="那个人类国王相当精通军事战略，可就算是他也没法创造奇迹。$b$b要是我们想攻破塔纳安丛林，就需要分散对方的军力。"
D.Strings[79639]="古尔丹的部落正在等着我们。正面强攻肯定会伤亡惨重，无异于自杀。$b$b我们得另想一个方法……"
D.Strings[79640]="我听到基尔罗格的声音了，怎么了？"
D.Strings[79641]="你已经拿到了你想要的。现在快走吧，别再回来了……"
D.Strings[79642]="每一次死亡都带给我无穷的力量。现在，我要用它来对付你！"
D.Strings[79643]="他们需要我的血，蠢货！他们不会让我受伤的。"
D.Strings[79644]="我已经吞噬了一千条灵魂。你就是下一个！"
D.Strings[79645]="放弃吧！"
D.Strings[79646]="凋零消亡！"
D.Strings[79647]="别担心……更糟的还在后头呢。"
D.Strings[79648]="我需要更多的灵魂！"
D.Strings[79649]="不够！还不够！"
D.Strings[79650]="我必须补充灵魂！"
D.Strings[79651]="我会好好品尝你的灵魂的。"
D.Strings[79652]="死亡会让我更加强大！"
D.Strings[79653]="可是……我的力量……"
D.Strings[79654]="啊……又一个等着我们来征服的美妙世界！"
D.Strings[79655]="别做梦了，古尔丹！快，去拿秘文！"
D.Strings[79656]="这不可能！这说明不了什么。这个世界迟早会化为火海。"
D.Strings[79657]="计划成功了。登陆非常顺利。我们有如神兵天降！"
D.Strings[79658]="计划成功了，指挥官。登陆行动几乎没有遇到抵抗。"
D.Strings[79659]="一定要在他们得逞之前阻止他们。"
D.Strings[79660]="我稍后再来哀悼牺牲者，我们得先守住这个突破口。"
D.Strings[79661]="|cFFFF0000%s|r激活了一个|cFFFF0000|Hspell:181718|h[抑制光环]|h|r！"
D.Strings[79662]="|cFFFF0000%s|r激活了一个|cFFFF0000|Hspell:179986|h[蔑视光环]|h|r!"
D.Strings[79663]="|cFFFF0000%s|r激活了一个|cFFFF0000|Hspell:179991|h[怨恨光环]|h|r！"
D.Strings[79664]="|cFFFF0000%s|r将对你施放|cFFFF0000|Hspell:180260|h[毁灭打击]|h|r！"
D.Strings[79665]="|cFFFF0000%s|r开始引导|cFFFF0000|Hspell:180312|h[地火风暴]|h|r！"
D.Strings[79666]="|cFFFF0000%s|r正准备施放|cFFFF0000|Hspell:180608|h[暴君之槌]|h|r！"
D.Strings[79667]="|cFFFF0000%s|r即将对你施放|cFFFF0000|Hspell:182459|h[谴责法令]|h|r！"
D.Strings[79668]="|cFFFF0000%s|r试图治疗它的主人！"
D.Strings[79669]="|cFFFF0000%s|r使用|cFFFF0000|Hspell:180040|h[统御者壁垒]|h|r保护它的主人！"
D.Strings[79670]="|cFFFF0000%s|r的化身加入了战斗！"
D.Strings[79671]="呵呵，厉害，真厉害。"
D.Strings[79672]="一切都靠你了，指挥官。帮我们建立一支海军，以便全方位地打击古尔丹。祝你好运！"
D.Strings[79673]="不，朋友。我们有共同的敌人，这就需要你的技术。"
D.Strings[79674]="说清楚点儿……"
D.Strings[79675]="你竟敢闯入我的营地？我要把你一片片撕碎……这一定很有趣。"
D.Strings[79676]="这家伙就是你们部落的酋长吗，$n？我喜欢。他坚决果敢，又懂得在行动前征求同伴的意见，从而达成一致。$b$b如果要突袭塔纳安丛林，我们就需要大胆的战略。你的酋长很走运，能有你这样的帮手。"
D.Strings[79677]="这个世界将化为灰烬！"
D.Strings[79678]="乖乖受死吧！"
D.Strings[79679]="你不明白……自己将要面对什么……"
D.Strings[79680]="你阻止不了我们的大军。"
D.Strings[79681]="燃烧军团是不朽的！"
D.Strings[79682]="你……死……定了……"
D.Strings[79683]="部落就靠你了，指挥官。找个造船师来，我们要包围塔纳安！"
D.Strings[79684]="嘿，指挥官。小伙子们干得不错，我们的防御固若金汤！"
D.Strings[79685]="嘿，指挥官！这地方没暴风之盾那么舒坦，但一切都在好转。$b$b你说呢？"
D.Strings[79686]="战士们，把那些白鬼渣滓赶回去！"
D.Strings[79687]="我们得保证隧道畅通！战斗！"
D.Strings[79688]="再给我弄点儿人来！这些白鬼简直无穷无尽！"
D.Strings[79689]="收好补给品！别让白鬼抢走了！"
D.Strings[79690]="<这台机器看来已经老朽不堪了，但它还是能带着你飞起来。>"
D.Strings[79691]="让我们飞去基尔加丹王座吧。"
D.Strings[79692]="一侧的铭牌上写着：$B$B感谢购买B-2人力转运器系统。请注意，使用本系统的风险将由您本人承担，对于因使用而导致的死亡或伤残，沃玛尔工程公司不承担任何法律责任。$b$b人力转运器功能：$B$B*微缩座舱，$b*重心调节器，$b*导航系统$b—— G-X3信标需另行购买。$b*充足的燃料。"
D.Strings[79693]="我美丽的叶子！你们这些血肉之躯会付出代价的！"
D.Strings[79694]="翠绿之火永不熄灭！它就在我心中燃烧！"
D.Strings[79695]="这真是太堕落了！所有人都将为此付出代价！"
D.Strings[79696]="你竟敢藐视燃烧军团？"
D.Strings[79697]="秘文必将属于我们！"
D.Strings[79698]="我们会找到秘文的！"
D.Strings[79699]="啊，总算有人来给我解解闷了！"
D.Strings[79700]="配方……错误……"
D.Strings[79701]="我的狼今晚又能吃顿好的了！"
D.Strings[79702]="你的脑袋将成为献给古尔丹的礼物！"
D.Strings[79703]="我们是强大的燃烧军团！"
D.Strings[79704]="哈！比我想象的还要致命！"
D.Strings[79705]="这会让他们的血液沸腾。"
D.Strings[79706]="基尔罗格一定会满意的。"
D.Strings[79707]="好痛！我也要让你痛一下！"
D.Strings[79708]="我的鲜血在沸腾！"
D.Strings[79709]="恐惧的香气！"
D.Strings[79710]="碾碎你的骨头。"
D.Strings[79711]="从没见过这么糟的钓鱼点。"
D.Strings[79712]="它们怎么跑的那么快？！"
D.Strings[79713]="我上次差点就抓住它了！"
D.Strings[79714]="它们在嘲讽我！"
D.Strings[79715]="你能别再谈鱼了吗？！"
D.Strings[79716]="或许你该动点真家伙了。"
D.Strings[79717]="你别逼我过去。"
D.Strings[79718]="没用的废物。祝你淹死。"
D.Strings[79719]="要想见血魔，你得先过我这一关！"
D.Strings[79720]="你阻止不了他……你也阻止不了燃烧军团……"
D.Strings[79721]="又一个送上门的！新鲜的血液来了！"
D.Strings[79722]="巨型恐魔愤怒地咆哮了起来！"
D.Strings[79723]="我们可以从这里观察到泽斯高。随着首领们一个接一个的接受了古尔丹的黑暗恩赐，血环氏族已经一片混乱了。这是出击的好机会。"
D.Strings[79724]="快点干活！要是我不满意的话，你们就有得受了！"
D.Strings[79725]="好……吃。"
D.Strings[79726]="噢，菜单上又有肉了。"
D.Strings[79727]="吃。"
D.Strings[79728]="他们在炮击大门！注意隐蔽！"
D.Strings[79729]="有人在竞技场挑战了阿基罗！"
D.Strings[79730]="颤抖吧，绝望吧，凡人！毁灭降临了。"
D.Strings[79731]="古尔丹，看好黑暗之门。这些渣滓阻挡不了我。我要亲手掐灭最后的光明。"
D.Strings[79732]="我的到来昭示着世界的末日，爬虫们。你们的废物军团将成为燃烧军团的第一批祭品！"
D.Strings[79733]="让毁灭的丧钟响彻这可悲的世界吧，所有的生灵都将陷入绝望。"
D.Strings[79734]="这愚蠢的远征到此为止了，凡人。燃烧军团降临了，世界也将随之断气！"
D.Strings[79735]="爬虫！"
D.Strings[79736]="看吧，这烈焰将吞没万千世界！"
D.Strings[79737]="军团之火将焚尽一切。"
D.Strings[79738]="接受你可悲的命运吧。"
D.Strings[79739]="你太容易堕落了。"
D.Strings[79740]="屈服在军团的威能之下吧！"
D.Strings[79741]="你那可笑的决心不堪一击。"
D.Strings[79742]="面对我永恒的怒火吧！"
D.Strings[79743]="你的灵魂将经历无尽的折磨！"
D.Strings[79744]="这无尽的虚空将是你永恒的牢笼！"
D.Strings[79745]="让无尽的黑暗吞噬你！"
D.Strings[79746]="你阻挡不了我！"
D.Strings[79747]="烧吧！在我的怒火中燃烧吧！"
D.Strings[79748]="燃烧军团是不可阻挡的！"
D.Strings[79749]="杜隆坦派我来帮助嘲颅氏族的幸存者与德莱尼和平共处。$b$b<弗甘不自在地看了看嘲颅兽人肮脏的营地。>$b$b其实我宁可上战场。"
D.Strings[79750]="一切都将沦为废墟！"
D.Strings[79751]="这无聊的小世界已经被我腐蚀了。燃烧军团的烙印将令大地沸腾燃烧！"
D.Strings[79752]="你召唤的可悲圣光对我来说不值一提，孩子。别犯傻了！"
D.Strings[79753]="你太不自量力了！燃烧军团将吞噬一切！"
D.Strings[79754]="够了！该结束这无谓的挣扎了！"
D.Strings[79755]="面对现实吧，愚蠢的凡人。你们无法抵抗燃烧军团的无穷大军。"
D.Strings[79756]="毁灭降临了！Lok thorje sorankar！"
D.Strings[79757]="没用的杂种！你那些下贱的同胞将因你的背叛而永世沉沦。"
D.Strings[79758]="我受够这无聊的游戏了。你们将面对曾横行诸界的永生军团。"
D.Strings[79759]="我要撕碎这可悲的世界！它的碎片将在扭曲虚空的不断撕扯下分崩离析！"
D.Strings[79760]="末日来了，法师！放弃吧！"
D.Strings[79761]="我，污染者，燃烧军团之主！世界将在我的怒火中燃烧！"
D.Strings[79762]="你死得太快了！"
D.Strings[79763]="可悲的蝼蚁。"
D.Strings[79764]="你们辜负了这个世界！"
D.Strings[79765]="炮弹打过来了！当心！"
D.Strings[79766]="东南方就是法瑞拉。你最好带几个朋友一起去，黑齿是我见过的最强大的刃牙虎人氏族。 \n\n把它们的爪子带回来，我没准还会给你点奖励……"
D.Strings[79767]="你卖的这些挑战图腾有什么用？"
D.Strings[79768]="那群大猫里有几个见多识广，经验丰富的家伙，只有在被挑战时才会出现。\n\n快去干掉几只猫人吧。\n\n我可以把你带来的爪子做成挑战图腾。你去法瑞拉的竞技场插下它，肯定就能激怒一些大人物。记得带上你的朋友，这群大猫可不是开玩笑的！"
D.Strings[79769]="圣光保佑我们远离这暴行！赐予我们驱逐邪恶的力量吧！"
D.Strings[79770]="不！我绝不屈服于黑暗。燃烧军团必败！"
D.Strings[79771]="圣光不灭……"
D.Strings[79772]="谢谢你……我这就回后方去。"
D.Strings[79773]="这群畜生！古尔丹都干了什么？"
D.Strings[79774]="我会尽量注意安全的。谢谢你。"
D.Strings[79775]="简直是屠杀……！"
D.Strings[79776]="你救了我的命。我这就回营地去。"
D.Strings[79777]="我欠你一条命。我这就回营地！"
D.Strings[79778]="这些畜生战斗时毫无荣誉可言——我们的同胞怎么会这么野蛮？"
D.Strings[79779]="谢谢你……我会回营地重整旗鼓的。"
D.Strings[79780]="古尔丹正在将兽人变成野兽！"
D.Strings[79781]="得……再……弄一把武器……"
D.Strings[79782]="你对佐拉姆沼泽知道多少？"
D.Strings[79783]="这片沼泽不属于任何人，那里完全就是一个死亡陷阱：迅猛龙、巨型蝙蝠、巨蟒……诸如此类的。有个巨大的阴影盘踞在那里。我在查看几具尸体时，感受到了它的目光。$b$b不用说，我拔腿就跑了。"
D.Strings[79784]="钢铁部落的那条隧道守卫力量如何？"
D.Strings[79785]="占领方的部队仍然驻扎在那里，但根据我们最近从堡垒上看到的“光景”来看，他们显然遭到了白鬼的猛攻。$b$b我们可以不去理会，让钢铁部落和白鬼打个头破血流，但我怀疑那里可能会有一些有用的“油水”可捞。"
D.Strings[79786]="邪能熔炉似乎已经彻底腐化了，他们在那里造什么呢？"
D.Strings[79787]="把一些典型的钢铁部落大型武器和邪能腐蚀结合起来，就是你在下面看到的那些玩意儿了。$b$b他们在那里制造各种灌注了邪能的坦克、火炮以及单兵武器。在更深处还有一些大家伙，我们决不能让它们建造完成。"
D.Strings[79788]="我看到被邪能腐蚀的水不停从山上留下来。基尔加丹王座出什么事了？"
D.Strings[79789]="我没认真去查，但也没必要，那上面就是燃烧军团的天堂。巨大的恶魔被一个个召唤出来，地狱火从天而降，邪教徒不断搅动被腐蚀的水流……$b$b你要上去的话一定要小心，那里全是一些邪恶的大家伙。我强烈建议你带上朋友一起去。"
D.Strings[79790]="那上面的情况很糟糕。散发着邪恶灵光的德莱尼在那里驯养恶狼、召唤恶魔。我猜那些正常的德莱尼肯定都被他们杀了。$b$b你能不能砸一块大石头下来，把他们都砸死？"
D.Strings[79791]="刚开始很平常……迅猛龙、毒蛇、大蝙蝠，没什么特别的。$b$b可那里有个东西……一个非常吓人的东西在害人。后来，我就飞快地跑掉了。我再也不回去了。"
D.Strings[79792]="那里的钢铁部落有麻烦了。那些邪能机器震裂了大地，这激怒了那些白鬼。他们正在隧道里狗咬狗呢。$b$b我们不用太关注那条隧道，但那里可能有些有用的东西。"
D.Strings[79793]="守住阵地！"
D.Strings[79794]="他们正在建造战争机器，但这次用的是古尔丹的邪能力量。很快，我们就要面对各种邪能火炮、坦克和小型武器了。$b$b不过，那里还有一些……非常非常大的东西。"
D.Strings[79795]="我不能靠得太近，可我看到的情况非常恐怖！$b$b恶魔！地狱火！邪教徒腐蚀着不断流淌下来的水流。指挥官，你要想上去的话，一定要非常小心，带上盟友。那里的敌人非常恐怖。"
D.Strings[79796]="把那些畜生们放出来！"
D.Strings[79797]="很快，我也会畅饮古尔丹的力量之泉。我们将百战百胜！"
D.Strings[79798]="没人能……阻挡我们……"
D.Strings[79799]="|TInterface\\Icons\\Spell_Frost_WindWalkOn:20|t%s施展|cFFFF0404|Hspell:183480|h[疾风步]|h|r，留下一串残影！"
D.Strings[79800]="我的力量不及古尔丹的……万分之一……"
D.Strings[79801]="他们在推进！魔誓兽人们，突击！让他们见识一下你们的新力量。"
D.Strings[79802]="他们还在反抗。火炮！轰击他们的阵地。把他们炸成肉泥！"
D.Strings[79803]="对……对……把大地烧焦！"
D.Strings[79804]="魔誓兽人们，主人在召唤我们行动！夺回属于我们的……"
D.Strings[79805]="很好，我得亲自下场了。"
D.Strings[79806]="又一场胜利。古尔丹一定会高兴的。"
D.Strings[79807]="鲜血与荣耀，指挥官。"
D.Strings[79808]="为了正义！"
D.Strings[79809]="这就将是你的谢幕之战！"
D.Strings[79810]="胜利！英雄们正顶着古尔丹的大军节节推进。"
D.Strings[79811]="荣耀属于古尔丹！"
D.Strings[79812]="来吧！我的热血在为战斗而沸腾！"
D.Strings[79813]="我渴望杀戮……"
D.Strings[79814]="古尔丹带给了我们力量！"
D.Strings[79815]="一定要……杀！"
D.Strings[79816]="古尔丹会杀光你们的。"
D.Strings[79817]="我看见一个了。"
D.Strings[79818]="别让他们靠近机器……"
D.Strings[79819]="不，滚开！"
D.Strings[79820]="我们的军力正在增长。你们输定了！"
D.Strings[79821]="古尔丹给我们指明了道路。很快，我们都将获得邪能的恩赐！"
D.Strings[79822]="我们的机械与术士之力将成为你们的末日。"
D.Strings[79823]="你们根本比不上古尔丹的魔法！"
D.Strings[79824]="邪能之血在我的血管中沸腾！它带给了我力量！"
D.Strings[79825]="我要把你撕成碎片！！"
D.Strings[79826]="古尔丹让我看到了通向无尽力量的道路。"
D.Strings[79827]="可悲的小东西。你们对我们所掌握的力量毫无概念。"
D.Strings[79828]="这只勇敢的动物坚守在主人身旁，直至痛苦地死去。"
D.Strings[79829]="为我们……复仇……"
D.Strings[79830]="他抢走了一切！我的船员……我的身份……我的船！"
D.Strings[79831]="死亡也熄灭不了我的怒火。我才是真正的铁须！"
D.Strings[79832]="哈哈，我的船员们可以背叛我，可他们得不到我的宝藏！他们好像都忘了怎么游泳了！"
D.Strings[79833]="我要诅咒那个冒牌货！但愿他的船撞上水雷！"
D.Strings[79834]="他们杀了我……可至少我还拉了几个背叛者当垫背的！"
D.Strings[79835]="和古尔丹作对的人都要死！"
D.Strings[79836]="为了古尔丹！为了胜利！"
D.Strings[79837]="别让他们靠近设备！"
D.Strings[79838]="看我用锤子打得你满脸开花！"
D.Strings[79839]="嗯？这不是你该来的地方！"
D.Strings[79840]="别烦我，我在工作！"
D.Strings[79841]="以古尔丹的名义！"
D.Strings[79842]="你竟敢攻击我们？蠢货！燃烧军团是无所不能的！"
D.Strings[79843]="让他们看看古尔丹教给我们的力量！"
D.Strings[79844]="什么也阻止不了我们！"
D.Strings[79845]="把你的脑袋伸出来吧……一秒钟就行……"
D.Strings[79846]="呵呵……别担心……一点都不会疼的……"
D.Strings[79847]="他们怎么老从一个地方冒出来？！这也太简单了！"
D.Strings[79848]="哈！我打死了一个编队！"
D.Strings[79849]="噢，那是个邪兽人……都怪他在最后一刻进入了我的视线。"
D.Strings[79850]="死亡才刚刚开始！"
D.Strings[79851]="听到了没。这些入侵者造成的麻烦已经够多了！"
D.Strings[79852]="终于……和主人……融为一体了……"
D.Strings[79853]="这具尸体上有几处烧焦的痕迹。"
D.Strings[79854]="我的魔法可以修好你的装备，只收一点手工费。"
D.Strings[79855]="有人在竞技场挑战了伦达尔！"
D.Strings[79856]="有人在竞技场挑战了艾匹萨！"
D.Strings[79857]="太迟了——他们来了！"
D.Strings[79858]="我本可以登上下一班船的！"
D.Strings[79859]="守好舰船。我们得去塔纳安。"
D.Strings[79860]="我来挡住他们。快上船！"
D.Strings[79861]="你们不可能拦下所有人。"
D.Strings[79862]="战争还没有结束。"
D.Strings[79863]="守住海岸线。他们想拦住我们！"
D.Strings[79864]="别让他们毁了船！"
D.Strings[79865]="你们以为这些大厅无人看守，可以随便进出吗？"
D.Strings[79866]="那就来吧。这次旅途将成为你们的试炼……以及末日。"
D.Strings[79867]="战斗还在继续，指挥官。我们该将力量集中在哪儿呢？"
D.Strings[79868]="我们如今是四面楚歌，指挥官。今天我们该去哪里杀敌呢？"
D.Strings[79869]="今天，群山都在泣血，指挥官。来吧，让我们再多撑一天吧！"
D.Strings[79870]="我们的斥候回来报告了，指挥官。四面八方的敌人兵力都远超我们。今天是个光荣的战斗日！"
D.Strings[79871]="这么多敌人……这么短的时间……今天又会有哪些人死去呢？"
D.Strings[79872]="丛林里危机四伏，继续进攻才是明智的选择。"
D.Strings[79873]="如果世界末日真的降临了，那就让我们战死沙场吧！"
D.Strings[79874]="古尔丹还没有击败我们，指挥官。今天我们该进攻哪里？"
D.Strings[79875]="你竟敢打断我的消遣！"
D.Strings[79876]="我怎么……会……输……"
D.Strings[79877]="营地里有敌人！消灭他们——以古尔丹的名义！"
D.Strings[79878]="尝尝古尔丹的力量吧！"
D.Strings[79879]="我要把你开膛破肚！"
D.Strings[79880]="剔肉拆骨！"
D.Strings[79881]="不！我的力量！"
D.Strings[79882]="真不该来这儿！他迷路了！"
D.Strings[79883]="滚出去！不准打扰圣武士！"
D.Strings[79884]="构装体准备对你施放|cFFFF0000|Hspell:184247|h[邪炽冲锋]|h|r！"
D.Strings[79885]="走开！走开！我来帮你一把！"
D.Strings[79886]="我将征服这片丛林！我将给它带来光明！你阻止不了我！"
D.Strings[79887]="我终于明白了……我早就失败了……"
D.Strings[79888]="构装体面向你，准备施放|cFFFF0000|Hspell:180221|h[易爆的邪能宝珠]|h|r！"
D.Strings[79889]="我们的力量不容置疑！"
D.Strings[79890]="你是……怎么……？"
D.Strings[79891]="|cFFFF0000|Hspell:182582|h[邪能焚化]|h|r正在追踪你！"
D.Strings[79892]="干得好，卫士！有人逃跑吗？"
D.Strings[79893]="没有，长官，只有这两个。"
D.Strings[79894]="遵命，执行者！"
D.Strings[79895]="我们这就出发！"
D.Strings[79896]="工程师！全力攻击他们！"
D.Strings[79897]="别担心，奈尔。我们很快就会找到猎物的。"
D.Strings[79898]="找到后，我就给你两块多汁的裂蹄牛排！"
D.Strings[79899]="他们是冲我来的。阻止他们，萨格雷！"
D.Strings[79900]="你们在沙塔斯没能阻止我，这次同样不行，蠢货。"
D.Strings[79901]="再坚持一会儿，融合就要完成了……"
D.Strings[79902]="战斗吧，蠢货！阻止他们！"
D.Strings[79903]="没关系，我早就想到了。"
D.Strings[79904]="构装体已充能完毕……最终的融合还得等一会儿。现在，现在，该来算算账了，爬虫们。"
D.Strings[79905]="现在，该来算算账了，爬虫们。"
D.Strings[79906]="死亡都阻止不了我——你们又能怎样？"
D.Strings[79907]="你们杀死过我一次，凡人。这不会再发生了。"
D.Strings[79908]="时光服从于我的意志！"
D.Strings[79909]="不！我无法控制……融合……"
D.Strings[79910]="我光靠灵魂就能打倒你们！"
D.Strings[79911]="萨格雷！靠近我！"
D.Strings[79912]="加入亡魂的行列吧！"
D.Strings[79913]="幻灭吧，蠢货！"
D.Strings[79914]="这里就是你的葬身之地！"
D.Strings[79915]="你休想控制它……它是我的！"
D.Strings[79916]="滚出去！你配不上它，你这卑微的灵魂！"
D.Strings[79917]="不！虚空！它吞噬了……我……"
D.Strings[79918]="这下你没法再背后下黑手了，托格罗克！我已经死了！"
D.Strings[79919]="真应该死在……我自己的船上……"
D.Strings[79920]="我贴身近战的身手也一样快！"
D.Strings[79921]="照顾好我的枪……"
D.Strings[79922]="这是神圣的土地！准备受死吧！"
D.Strings[79923]="我会永远……纠缠着你……"
D.Strings[79924]="还没……结束……"
D.Strings[79925]="千刀万剐！"
D.Strings[79926]="必须……休息了……"
D.Strings[79927]="真不错……又一个麻烦！"
D.Strings[79928]="那你去对付白鬼吧……"
D.Strings[79929]="我老远就看到你过来了！"
D.Strings[79930]="你别想走出这个陷阱……"
D.Strings[79931]="$n被生命渴望吞噬了。"
D.Strings[79932]="站直了，战士们。我们的敌人已经兵临城下。保持警惕。"
D.Strings[79933]="报告情况，士兵！"
D.Strings[79934]="你这边情况如何，战士？"
D.Strings[79935]="你，去检查一下堡垒的工事。"
D.Strings[79936]="快去检查工事，立刻就去！"
D.Strings[79937]="有客人来了。拿起武器！"
D.Strings[79938]="看来，你们想试试邪能部落的实力？来吧，战士们，让他们看看我们是怎么招呼不速之客的。"
D.Strings[79939]="哈哈！狠狠践踏他们的尸体吧！"
D.Strings[79940]="如果你想做好某件事，就得亲自上阵……"
D.Strings[79941]="火炮出击。"
D.Strings[79942]="打得他们找不到北……"
D.Strings[79943]="让碎石机上场！"
D.Strings[79944]="碎石机，进场！"
D.Strings[79945]="把他们烧成灰。"
D.Strings[79946]="见证邪能部落的力量吧……地狱火之怒！"
D.Strings[79947]="能量全满！"
D.Strings[79948]="哈哈，这真有意思。"
D.Strings[79949]="弹射！弹射！"
D.Strings[79950]="嘀嗒嘀嗒，时间到！"
D.Strings[79951]="碾碎了。"
D.Strings[79952]="大地在震颤！"
D.Strings[79953]="烧吧烧吧烧吧！"
D.Strings[79954]="嘀嗒嘀嗒，时间在流逝！"
D.Strings[79955]="|TInterface\\Icons\\inv_misc_boilingblood.blp:20|t%s开始使用|cFFFF0404|Hspell:184357|h[污血]|h|r！"
D.Strings[79956]="%s给一半敌人打上了|cFFFF0404|Hspell:184449|h[死灵印记]|h|r！"
D.Strings[79957]="%s从|cFFFF0404|Hspell:184681|h[黑暗]|h|r中召唤出了恐魔！"
D.Strings[79958]="|TInterface\\Icons\\spell_nature_mirrorimage.blp:20|t%s开始复制出|cFFFF0404|Hspell:183734|h[镜像]|h|r！"
D.Strings[79959]="|TInterface\\Icons\\ability_foundryraid_demolition.blp:20|t%s开始使用|cFFFF0404|Hspell:184366|h[毁灭飞跃]|h|r四处横冲直撞！"
D.Strings[79960]="准备好，勇士，我不知道这道屏障后面有什么。"
D.Strings[79961]="啊……完成了。去吧。阻止古尔丹！"
D.Strings[79962]="摧毁这道屏障会极大地消耗我的力量。恐怕我在摧毁它之后，就帮不上你什么忙了。"
D.Strings[79963]="请开始仪式吧。"
D.Strings[79964]="准备好。古尔丹的力量已达巅峰。"
D.Strings[79965]="以先知与圣光之名，我要净化这片土地！"
D.Strings[79966]="那儿……快！阻止古尔丹！"
D.Strings[79967]="别想逃！"
D.Strings[79968]="粉碎！"
D.Strings[79969]="消亡！"
D.Strings[79970]="弱者！"
D.Strings[79971]="崩溃！"
D.Strings[79972]="我……消亡了……"
D.Strings[79973]="一名萨格雷统御者正在使用|cFFFF0000|Hspell:184053|h[邪能屏障]|h|r保护索克雷萨！"
D.Strings[79974]="%s对所有被标记的敌人使用了|cFFFF0404|Hspell:184476|h[暗影收割]|h|r！"
D.Strings[79975]="你这……*咳嗽*肮脏的蠢猪！"
D.Strings[79976]="*咳嗽*你会为此付出代价的！"
D.Strings[79977]="*咳嗽*噢，我的眼睛！"
D.Strings[79978]="嗷！好烫！"
D.Strings[79979]="我喜欢看你挣扎扭动。你会成为很好的祭品。"
D.Strings[79980]="德拉诺已臣服于军团。看元素如何屈服于我的意志吧！"
D.Strings[79981]="森卢肯，你在干什么。你的对手不过是血肉之躯！"
D.Strings[79982]="还心存侥幸吗，地狱咆哮？你的宝贝部落已经投靠燃烧军团了。"
D.Strings[79983]="我们……永不……为奴！"
D.Strings[79984]="看他们多卖力，可就算他们联起手来，也救不了你。"
D.Strings[79985]="再让我看到你那邪恶的军团，我就把你的脑袋做成头盔。"
D.Strings[79986]="没关系，我们会杀光你们。"
D.Strings[79987]="呵呵呵，你的恶魔正在节节败退。"
D.Strings[79988]="干掉他，英雄们，我要用那该死的斧子把他斩首剜心。"
D.Strings[79989]="谢谢你们，剩下的交给我吧，该收取战利品了。"
D.Strings[79990]="|TInterface\\Icons\\spell_shadow_auraofdarkness:20|t你获得了|cFFFF0000|Hspell:181099|h[末日印记]|h|r！"
D.Strings[79991]="|TInterface\\Icons\\ability_ironmaidens_convulsiveshadows:20|t你受到了|cFFFF0000|Hspell:181799|h[暗影之力]|h|r的影响！"
D.Strings[79992]="|TInterface\\Icons\\ability_ironmaidens_convulsiveshadows:20|t%s开始施放|cFFFF0000|Hspell:182084|h[强化暗影之力]|h|r！"
D.Strings[79993]="$n准备了一桌焦糖鱼宴！"
D.Strings[79994]="$n准备了一桌暗月豪华大餐！"
D.Strings[79995]="我想建造一艘航母。"
D.Strings[79996]="开始建造我们的第一艘驱逐舰。"
D.Strings[79997]="我想建造一艘潜水艇。"
D.Strings[79998]="|cFFFF0000%s|r即将完成|cFFFF0000|Hspell:181912|h[聚焦冲击]|h|r的施放！"
D.Strings[79999]="快来用你的暗月刃喉鱼换取精美奖品吧！"
D.Strings[80000]="钓鱼奖品，老少咸宜！"
D.Strings[80001]="快来试试你的手气，跟狡猾的暗月刃喉鱼斗智斗勇吧！"
D.Strings[80002]="鱼竿在手，奖品我有！"
D.Strings[80003]="需要给你的舰船追加装备吗？找我就对了！"
D.Strings[80004]="你有哪些海军装备？"
D.Strings[80005]="你真要买我的装备吗？斯勒格那里有最新最好的装备哦。"
D.Strings[80006]="我想买你的过时装备。"
D.Strings[80007]="你真要买我的装备吗？开碑掌那边的货色才是最新最好的。\n\n我跟你说啊，我听说她那个外号可不是跟部落战斗得来的。\n\n你可别告诉她是我说的。\n\n其实吧，我希望你最好啥也别说。我们最近关系可不怎么样。"
D.Strings[80008]="传说任务：古尔丹崛起"
D.Strings[80009]="运输船准备好了。可以进攻塔纳安了。"
D.Strings[80010]="杜隆坦——霜狼氏族准备好了吗？"
D.Strings[80011]="是的。我们会佯攻正门，而你的舰队就趁机绕到东海岸去。"
D.Strings[80012]="我们就指望你了，指挥官。为部落带来胜利吧！"
D.Strings[80013]="杜隆坦跟我说了。我会参加你的海上突击行动，并在建立塔纳安丛林据点时保护你。$b$b我准备好了。你呢？"
D.Strings[80014]="我跟其他大主教谈过了，一切都准备就绪了。我会参加你的海军行动，并在建立后方基地时保护你。玛拉达尔自告奋勇率领佯攻部队去攻打正门了。$b$b我准备好了。你呢？"
D.Strings[80015]="伊瑞尔——你的人准备好了吗？"
D.Strings[80016]="是的。德莱尼会带头强攻正门，而你的海军就绕到后方去偷袭。"
D.Strings[80017]="祝你成功，指挥官！"
D.Strings[80018]="我……呃……好吧，这真是尴尬，我把诺达希尔的分枝弄丢了。"
D.Strings[80019]="|cFFFF0000%s|r开始对你施放|cFFFF0000|Hspell:186045|h[炽阳飞轮]|h|r！"
D.Strings[80020]="如果你想去对付部落，阿米莉亚那儿的装备比我的强多了。"
D.Strings[80021]="如果你想对付部落的顶尖好手，就得去跟霍莉·麦提拉谈谈。顺便再帮我问问她的头发是在哪儿做的，好吗？"
D.Strings[80022]="雄狮岗哨"
D.Strings[80023]="沃玛尔"
D.Strings[80024]="我这儿的装备不如弗洛比·冲补的。我建议你优先选用她的装备。"
D.Strings[80025]="如果你想买到市面上最好的装备，还是去跟玛露卡·轻歌谈谈吧。"
D.Strings[80026]="如果你用战场上挣来的荣誉换取最好的奖励，那应该去找克拉德·晨行者。"
D.Strings[80027]="如果你用战场上挣来的荣誉换取最好的奖励，那应该去找泰洛克斯·枯魂。"
D.Strings[80028]="对对，我知道，我的货色不如泰洛克斯的好。可你知道的，我的货更漂亮，对吧？什么，你觉得看起来都一样？这叫什么话！明显不一样嘛！你这个讨厌鬼！算你走运，多亏我的合同还没到期。"
D.Strings[80029]="我的货物质量不如玛露卡·轻歌的。如果你想去对付联盟的话，还是去跟她谈谈吧。"
D.Strings[80030]="我的货物质量不如美丽的玛露卡·轻歌的。如果你想买市面上最好的装备，还是去跟她谈谈吧。"
D.Strings[80031]="我得很遗憾的告诉你，目前战场最好的装备是由开碑掌女士提供的。别担心，我正在努力改进我的产品。我现在在考虑……多加几条胳膊！你可以用意念操控它们！"
D.Strings[80032]="我想建造一艘战列舰。"
D.Strings[80033]="我想建造一艘运输舰。"
D.Strings[80034]="难以置信，最好的武器和护甲居然都交给了霍莉·麦提拉那个乡巴佬。一个矮人！老实说，难怪我们还没拿下这座岛呢。"
D.Strings[80035]="船坞已经在满负荷运转了，等眼下这艘船造好再回来看看吧。"
D.Strings[80036]="阿什兰挖掘场的|c00FFFF00|Hspell:186255|h[事件：埃匹希斯印记]|h|r将于3分钟后开始。"
D.Strings[80037]="毁灭斗兽场的|c00FFFF00|Hspell:178022|h[事件：斗兽场角力]|h|r已经开始！"
D.Strings[80038]="阿什兰挖掘场的|c00FFFF00|Hspell:186255|h[事件：埃匹希斯印记]|h|r已经开始！"
D.Strings[80039]="熔岩采石场的|c00FFFF00|Hspell:178019|h[事件：收集强化矿石]|h|r已经开始！"
D.Strings[80040]="蛮兵高地的|c00FFFF00|Hspell:178021|h[事件：食人魔火焰]|h|r已经开始！"
D.Strings[80041]="灰槌墓地的|c00FFFF00|Hspell:178020|h[事件：复活的游魂]|h|r已经开始！"
D.Strings[80042]="小心，$n。科达娜已经将卡德加的法师塔戒严了。她最近的举动很古怪。"
D.Strings[80043]="我们要把古尔丹的爪牙送回海底！"
D.Strings[80044]="法兰伦很神秘。还是派你最信赖……或者可有可无的人去吧。"
D.Strings[80045]="协助我，勇士们！我们还没完！我们一定要活下去！"
D.Strings[80046]="休想！我们会反抗到底并获得胜利！"
D.Strings[80047]="堡垒失守了！古尔丹在里面。我会在这里建一个据点——前进！"
D.Strings[80048]="我们要揭开德拉诺所有的秘密！"
D.Strings[80049]="想不到古尔丹会如此疯狂……我们得继续前进。废墟里有一座传送门，能让我们深入堡垒。"
D.Strings[80050]="传送门好了，勇士们。打起精神来，我不知道古尔丹在这里还干过哪些暴行。"
D.Strings[80051]="整座堡垒都充斥着古尔丹的腐蚀！第二座传送门就在附近。挡住他的恶魔，我来破除封印，将传送门对准他的位置。"
D.Strings[80052]="第一个封印解开了，我们很快就能找到古尔丹了。"
D.Strings[80053]="帮我向科达娜问好。她最近很冷淡。"
D.Strings[80054]="又解开一个！噢，我真是厉害。"
D.Strings[80055]="传送门就快好了，又搞定了一个。"
D.Strings[80056]="最后一个也好了！我就快完成了。"
D.Strings[80057]="传送门开启了！我们将直面古尔丹，让他为他的罪行付出代价。"
D.Strings[80058]="古尔丹逃去黑暗之门那里了！快，勇士们！他无路可逃了——让我们结束这一切！"
D.Strings[80059]="把他的脑袋留下。我……有用。"
D.Strings[80060]="书。对了，是古尔丹的书。你确定卡德加没有试图使用它们吗？"
D.Strings[80061]="力量之书……知识之书……以混沌的语言写成的书……不用担心，勇士，它们都将被摧毁。"
D.Strings[80062]="现在，把你的戒指给我。我需要它。就放在这儿吧！"
D.Strings[80063]="现在，它归我了！为了古尔丹的荣耀！"
D.Strings[80064]="主宰宝珠对我低语。我看到了真理。"
D.Strings[80065]="卡德加只是个孩子，到处耀武扬威，折磨俘虏，游戏人生，不懂装懂地卖弄着魔法。"
D.Strings[80066]="这就是燃烧军团的力量！"
D.Strings[80067]="很好，走吧。没人能阻止古尔丹，他的靠山是燃烧军团。记住：你们的领袖会背叛你们。艾泽拉斯将化为火海。"
D.Strings[80068]="燃烧军团来了！"
D.Strings[80069]="快去卡拉波，联盟的勇士！"
D.Strings[80070]="你将面对燃烧军团的力量！"
D.Strings[80071]="德拉诺的元素之灵在等着你，部落的勇士！"
D.Strings[80072]="我的力量在增长！"
D.Strings[80073]="感受燃烧军团的力量吧！"
D.Strings[80074]="所有生命都将消亡！"
D.Strings[80075]="毁灭……降临……"
D.Strings[80076]="欢迎，指挥官！卡德加说你已经完成了许多壮举……"
D.Strings[80077]="跪下吧，指挥官。接受来自纳鲁的祝福可是一个罕有的特权。"
D.Strings[80078]="先行的人有福了，因他们让光明照入黑暗。"
D.Strings[80079]="勇敢的人有福了，因他们在不义的世界中坚如磐石。"
D.Strings[80080]="勇士。黑暗之种已在德拉诺生根发芽。"
D.Strings[80081]="义人们必将汇聚于你的旗帜下。不要动摇。"
D.Strings[80082]="去吧，带着圣光的祝福，战胜我们的敌人。"
D.Strings[80083]="两个世界正命悬一线……"
D.Strings[80084]="你听到什么声音了吗？是纳鲁在对你说话吗？"
D.Strings[80085]="指挥官，无论你打算做什么，德莱尼都会全力支持你的。"
D.Strings[80086]="我们与你同在！"
D.Strings[80087]="指挥官，是你吗？你的气场又变强了。"
D.Strings[80088]="德拉诺的元素正在颤抖，朋友。你听到了吗？听呐……听……"
D.Strings[80089]="岩石之灵，将你们的力量赐予我们的勇士吧。"
D.Strings[80090]="大气之灵，请赋予我们的勇士敏捷的头脑和身躯。"
D.Strings[80091]="流水之灵，请将你的智慧赐予我们的英雄。"
D.Strings[80092]="烈焰之灵，将你的怒火赐予我们，让我们赶走面前的敌人！"
D.Strings[80093]="站起来吧，勇士。记住，德拉诺的原始之心在你胸中燃烧。"
D.Strings[80094]="古尔丹会拼命切断我们与元素的联系，剥夺我们的元素之力。你必须阻止他。"
D.Strings[80095]="世界的命运掌握在你的手中，指挥官。Lok'tar ogar。"
D.Strings[80096]="向我证明你配得上这份力量！将我同胞的灵魂从幽禁中解放出来，然后带着他们的印记来见我。"
D.Strings[80097]="……你拿着主宰宝珠做什么，科达娜？"
D.Strings[80098]="卡德加想让你销毁这些书。"
D.Strings[80099]="没什么。$b$b你不用操心。$b$b一切都在我的控制之下。"
D.Strings[80100]="对了，你的戒指。戒指！我们来到德拉诺后，卡德加帮你做的那个。$b$b把它放在这儿。我需要……借用一下。"
D.Strings[80101]="噢，那可不行！"
D.Strings[80102]="摧毁混沌魔典，打破科达娜的护盾。"
D.Strings[80103]="指挥官，援军每天都在赶来。你可以使用这座传送门在此地与我们在阿什兰的堡垒间快速往返。"
D.Strings[80104]="继续跑吧，我才不要缩在帐篷里！就算被下次攻击打中，我也认了。"
D.Strings[80105]="你们这是自寻死路。黑暗之门完成了！"
D.Strings[80106]="见证军团的力量吧！"
D.Strings[80107]="能与你并肩作战是我的荣幸，$n。从我在黑暗之门后面那条恐怖隧道里遇见你开始，你的事迹就一直鼓舞着我。$b$b卡拉也看出了你内心的力量。你准备好与纳鲁对话了吗？"
D.Strings[80108]="我准备好了，伊瑞尔。"
D.Strings[80109]="你们这些该死的畜生！等我重返天空，我一定要灭绝你们这些卑贱的种族！"
D.Strings[80110]="艾斯卡大人……我辜负了你……"
D.Strings[80111]="|TInterface\\Icons\\Spell_DeathKnight_AntiMagicZone:20|t附近的一条恐惧猎犬开始施放|cFFF00000|Hspell:186562|h[吞噬魔法]|h|r！"
D.Strings[80112]="我希望有一天能亲眼看看你们的“艾泽拉斯”，那一定是一个神奇的世界。"
D.Strings[80113]="|TInterface\\Icons\\spell_fire_ragnaros_lavaboltgreen.blp:20|t %s将你选为了|cFFF00000|Hspell:182108|h[炮击]|h|r目标！"
D.Strings[80114]="感受我的愤怒吧！"
D.Strings[80115]="归来吧，玛诺洛斯……对，对！你的主人召唤你再次降临这个世界！"
D.Strings[80116]="怎、怎么了？你干了什么，古尔丹？我为何……如此虚弱……"
D.Strings[80117]="畏惧军团的力量吧！"
D.Strings[80118]="别怕，玛诺洛斯。让邪能的恩赐强化你……好好教训他们吧！"
D.Strings[80119]="我的力量恢复了！我解放了！"
D.Strings[80120]="这些凡人为何如此强大。古尔丹，做点什么！"
D.Strings[80121]="让能量在你体内流淌。你是血肉的毁灭者、鞭笞者！"
D.Strings[80122]="我……是……不可阻挡的……"
D.Strings[80123]="无信的蠢货。燃烧军团的意志必将实现。"
D.Strings[80124]="在军团的力量面前颤栗吧！"
D.Strings[80125]="你竟敢挑战燃烧军团？"
D.Strings[80126]="我不会再倒下了。"
D.Strings[80127]="去死吧，杂种。"
D.Strings[80128]="主人的熔火之掌将净化这个世界！"
D.Strings[80129]="军团将一如既往地烧尽这个世界！"
D.Strings[80130]="你的血肉将熊熊燃烧。"
D.Strings[80131]="你的末日到了。"
D.Strings[80132]="你很努力……但毫无意义。"
D.Strings[80133]="挣扎吧……尖叫吧。"
D.Strings[80134]="我是毁灭者！"
D.Strings[80135]="军团会找到你们……无论你们逃往何处……"
D.Strings[80136]="没人能反抗我们！"
D.Strings[80137]="<虽然贾纳尔在生前满腔愤怒，勇猛无畏——但他的灵魂已经安息了。他亲切地对你说道：>$b$b让他们统统去死，$n。"
D.Strings[80138]="指挥官，就是你了。你的事迹已经广为流传，连微风都在呢喃着你的名字。$b$b来吧，是时候了。作为这个世界的守护者，你应该接受德拉诺的元素赐予的力量。你准备好了吗？"
D.Strings[80139]="<德雷克塔尔深深鞠躬。>$b$b勇士，记住，活在悔恨中的人都是过往的奴隶。只有那些满怀希望的人才能迎接未来。"
D.Strings[80140]="我准备好了，先知。"
D.Strings[80141]="送我去塔纳安丛林。"
D.Strings[80142]="|TInterface\\Icons\\achievement_boss_hellfire_felmagnaron.blp:20|t考莫克被|cFFFF0000|Hspell:186882|h[激怒]|h|r了！"
D.Strings[80143]="古尔丹就在附近！我会送你深入堡垒。我们必须在腐蚀进一步扩散前阻止他。"
D.Strings[80144]="送我去地狱火前厅。"
D.Strings[80145]="送我去鲜血庭院。"
D.Strings[80146]="送我去灵魂之喉。"
D.Strings[80147]="送我去永恒竞技场。"
D.Strings[80148]="送我去黑暗之门。"
D.Strings[80149]="既然你的基地已经竣工，部队也已经整装待发，我们终于可以结束这场战役了。现在，横亘在我们面前的只剩下地狱火堡垒的高墙坚城了……"
D.Strings[80150]="%s从阴影中现身了！"
D.Strings[80151]="|TInterface\\Icons\\spell_fire_ragnaros_molteninferno.blp:20|t$n|cFFFF0000|Hspell:185828|h[复燃]|h|r了一个邪能烧灼者！"
D.Strings[80152]="|TInterface\\Icons\\spell_fire_ragnaros_molteninferno.blp:20|t$n|cFFFF0000|Hspell:185835|h[点燃]|h|r了附近所有的邪能烧灼者！"
D.Strings[80153]="暗影将吞噬你们！"
D.Strings[80154]="在彼岸，你能找到的只有死亡！"
D.Strings[80155]="你将陷入永恒的黑暗！"
D.Strings[80156]="死亡是唯一的真理！"
D.Strings[80157]="泰罗克的谎言已经被揭穿了！"
D.Strings[80158]="夜幕降下，覆盖万物。"
D.Strings[80159]="你们以为自己赢了？太无知了！"
D.Strings[80160]="夜幕挡不住我的力量！"
D.Strings[80161]="泰罗克保护不了你们！"
D.Strings[80162]="你最好学学飞行！"
D.Strings[80163]="狂风会惩罚你们的。"
D.Strings[80164]="这段路长着呢！"
D.Strings[80165]="你漫长的英雄生涯即将断送在一个鬼焰小鬼手里。"
D.Strings[80166]="落在鬼焰魔手中的人都会死得痛苦不堪。"
D.Strings[80167]="在临死之前，你只会看到鬼焰魔女嘲笑着你的尸体。"
D.Strings[80168]="我们情况如何，兽人？"
D.Strings[80169]="在临终前，卡德加引发了法力爆炸，干掉了所有人。"
D.Strings[80170]="欢迎，指挥官。在让这个船坞运转起来之前，我们还有很多工作要做！"
D.Strings[80171]="跟我说说海军行动吧。"
D.Strings[80172]="指挥舰队可不简单，指挥官。"
D.Strings[80173]="这边，指挥官！我们就从这些海军行动开始吧！"
D.Strings[80174]="只要再等几分钟……她很快就会成为一艘好船了！"
D.Strings[80175]="他们是冲我们来的，但他们休想找到想要的东西。"
D.Strings[80176]="古尔图格！打发这些敌人……"
D.Strings[80177]="甜蜜而仁慈的……死亡。"
D.Strings[80178]="多么激烈的垂死挣扎。"
D.Strings[80179]="它倒下了。它是我的了。"
D.Strings[80180]="他们已经被标记了。"
D.Strings[80181]="黑暗将纠缠着他们。"
D.Strings[80182]="它撕扯割裂，无边无际，亘古不变……"
D.Strings[80183]="虚空，它饿了。"
D.Strings[80184]="然后，亡者将再次崛起。"
D.Strings[80185]="嗷啊啊……"
D.Strings[80186]="好的，黑暗女王。"
D.Strings[80187]="进餐时间！"
D.Strings[80188]="我要喝你的血！吃你的肉！"
D.Strings[80189]="化为灰烬……"
D.Strings[80190]="灰飞烟灭！"
D.Strings[80191]="我在暗影中穿行。"
D.Strings[80192]="你好，感谢你参加6.2补丁的测试活动！ \n\n我可以将你直接传送到地狱火堡垒或塔纳安丛林。这是单纯的传送，不包括配对服务，所以请事先组织好队伍以应对副本内的挑战。如果你没有队伍，请使用我们最新的队伍查找器功能寻找盟友。\n\n请在传送前选择好你想要测试的难度，因为要想离开副本以变更难度将会比较困难！"
D.Strings[80193]="我想去地狱火堡垒（团队副本）。"
D.Strings[80194]="我想去塔纳安丛林。"
D.Strings[80195]="塔纳安丛林那儿有什么关于宠物的消息吗？"
D.Strings[80196]="我听说有不少于15只的强大宠物被古尔丹放出的邪能腐蚀了。只要找到并击败它们，你肯定能有不菲的收获。"
D.Strings[80197]="<构装体一动不动地坐在地上。>"
D.Strings[80198]="<放入1000个埃匹希斯水晶。>"
D.Strings[80199]="修复这个构装体需要消耗1000个埃匹希斯水晶。确定要修复吗？"
D.Strings[80200]="它似乎已经可以运转了。何不去看看它能干点什么呢？"
D.Strings[80201]="|TInterface\\Icons\\spell_fire_rune.blp:20|t|cFFFF0000|Hspell:187658|h[强化爆炸符文]|h|r最后爆炸了一次。"
D.Strings[80202]="|TInterface\\Icons\\spell_shadow_auraofdarkness:20|t%s开始施放|cFFFF0000|Hspell:187466|h[超级毁灭]|h|r！"
D.Strings[80203]="|TInterface\\Icons\\spell_nature_astralrecalgroup:20|t%s施放了|cFFFF0000|Hspell:187702|h[扭曲的映像]|h|r！"
D.Strings[80204]="运输舰"
D.Strings[80205]="航母"
D.Strings[80206]="驱逐舰"
D.Strings[80207]="战列舰"
D.Strings[80208]="潜水艇"
D.Strings[80209]="祖霍拉克将你选为了|cFFFF0000|Hspell:186407|h[邪能喷涌]|h|r的目标！"
D.Strings[80210]="祖霍拉克将你选为了|cFFFF0000|Hspell:186333|h[灵能涌动]|h|r的目标！"
D.Strings[80211]="$n引发了|cFFFF0000|Hspell:186407|h[邪影屠戮]|h|r！"
D.Strings[80212]="<尽管眼睛上蒙着一块厚厚的布，干瘦的先知仍然在仰望天空时露出了沉思的表情。>$B$B星辰决定了我们的命运，孩子。它们会祝福强者，摈弃弱者。"
D.Strings[80213]="你已赢得了军团的赐福！"
D.Strings[80214]="邪能的祝福就在你的手中！"
D.Strings[80215]="哈哈哈哈......迅捷如风！"
D.Strings[80216]="黑暗在我体内燃烧。"
D.Strings[80217]="我的烈焰永不熄灭！"
D.Strings[80218]="别担心我们，指挥官。我们虽然以寡敌众，但他们缺乏斗志。LOK'TAR！"
D.Strings[80219]="去吧，指挥官。我们会继续保持前线的压力的。"
D.Strings[80220]="投掷"
D.Strings[80221]="你们太迟了！腐化就快完成了！"
D.Strings[80222]="|TINTERFACE\\ICONS\\spell_fire_felflamestrike.blp:20|t 阿克蒙德开始施放|cFFF00000|Hspell:183254|h[烈焰滔天]|h|r！"
D.Strings[80223]="一头巨型小戈隆正冲向游侠避难所！我们需要援助！"
D.Strings[80224]="又坏了一个钻头？你是从哪儿进的货，风险投资公司吗？！"
D.Strings[80225]="戴好你的头盔……我们就要搞定了。只要踢它几脚，我们就可以坐等收钱了！"
D.Strings[80226]="我让你明天就请病假！"
D.Strings[80227]="真不该来这个臭烘烘的世界……"
D.Strings[80228]="别耍花招！我最讨厌耍花招了！"
D.Strings[80229]="不准耍花招！我说了不准！"
D.Strings[80230]="说真的，这儿没有适合你的东西，伙计！"
D.Strings[80231]="不……我的工资……"
D.Strings[80232]="稍等，我这就教你怎么做人。"
D.Strings[80233]="啊，伙计，我要死了！"
D.Strings[80234]="|TINTERFACE\\ICONS\\ability_fixated_state_red.blp:20|t一个魔火之魂|cFFF00000|Hspell:182879|h[锁定]|h|r了你！"
D.Strings[80235]="啊，到我身后去！"
D.Strings[80236]="我在飞翔！"
D.Strings[80237]="谁说了炸弹吗？！"
D.Strings[80238]="特快专递！"
D.Strings[80239]="你无权命令我！"
D.Strings[80240]="嘿，指挥官，我们可以把你附近任意岗哨的物资都转运到塔纳安来。你就说想要什么吧！"
D.Strings[80241]="战斗的召唤。"
D.Strings[80242]="守护宝珠。"
D.Strings[80243]="火炮轰击。"
D.Strings[80244]="勇士之耀。"
D.Strings[80245]="机械切割者。"
D.Strings[80246]="嘿，指挥官，如果你有空的话，我想跟你谈谈关于增派援军来塔纳安的事。"
D.Strings[80247]="嘿，指挥官。只要你一声令下，我就可以把备用的补给品投放到这里。"
D.Strings[80248]="既然这里已经成为战事的中心，我们可以从附近的岗哨调用一些补给品。你想要哪种补给？"
D.Strings[80249]="你今天就打算穿着这套恶心的衣服出去？"
D.Strings[80250]="你就非得把这些玩意儿都带上吗？"
D.Strings[80251]="你该给你妈妈写信了。她担心死你了。"
D.Strings[80252]="我就不明白了，你干嘛非要派些小动物上阵厮杀呢，明明你自己可以做得更好。"
D.Strings[80253]="如果我把你送到目的地，你能让我一个人呆会儿吗？"
D.Strings[80254]="你想离开这儿？我可以送你出去，可究竟会送到哪儿我就不敢保证了。"
D.Strings[80255]="是的，我相信作为一只恶魔，你一定能把我送到安全的地方。"
D.Strings[80256]="|TInterface\\Icons\\ability_vehicle_siegeenginecannon.blp:20|t一台%s轻微受损！"
D.Strings[80257]="|TInterface\\Icons\\ability_vehicle_siegeenginecannon.blp:20|t一台%s严重受损！"
D.Strings[80258]="|TInterface\\Icons\\ability_vehicle_siegeenginecannon.blp:20|t一台%s几近报废！"
D.Strings[80259]="血魔开始施放|TInterface\\Icons\\spell_misc_zandalari_council_soulswap:20|t |cFFFF0404|Hspell:181973|h[灵魂盛宴]|h|r！"
D.Strings[80260]="练习时间！"
D.Strings[80261]="有人想参加写生组吗？"
D.Strings[80262]="欢迎加入写生组！去找个画架，然后放轻松。我们这里不搞评审那一套——当然，除非你是个圣骑士。$b$b今天，我们将去魔枢上课。如此美丽！如此混乱！如此……湛蓝。"
D.Strings[80263]="嘿哈！"
D.Strings[80264]="这么多世界……这么多位面……"
D.Strings[80265]="最终，它们都将化为虚无……或者，或许……"
D.Strings[80266]="它们将燃烧！死亡！这是主人的意志！"
D.Strings[80267]="无论它结局如何，你们都得死在这里。"
D.Strings[80268]="我有很多东西要给你们看……"
D.Strings[80269]="虚空的仆从们！吞噬这个世界！"
D.Strings[80270]="所有的生命必须消亡。"
D.Strings[80271]="腐蚀！烈焰！灰烬！"
D.Strings[80272]="燃烧军团！消灭前方所有敌人！"
D.Strings[80273]="我被撕裂了！你也将随我一同死去！"
D.Strings[80274]="这些裂隙……得把它们撕得更大些！"
D.Strings[80275]="一切都将被吞噬！一个不留！"
D.Strings[80276]="我坚持不住了……我要变成……万事万物！空无一物！"
D.Strings[80277]="撕碎你！"
D.Strings[80278]="我控制……不了……"
D.Strings[80279]="它压制了我！"
D.Strings[80280]="对！对！我看见了！我看见……末日……"
D.Strings[80281]="这个世界不会轻易陷落的，恶魔。它的人民不会束手就擒。我们的意志坚如钢铁！为了德拉诺！"
D.Strings[80282]="Lok'tar ogar！他们撤退了！去传送门！古尔丹是我的！"
D.Strings[80283]="最后关头到了，主人即将降临！这是你们的功劳，召唤者。玛诺洛斯即将复生！"
D.Strings[80284]="让燃烧军团的怒火毁灭你们！"
D.Strings[80285]="你们的失败将取悦主人！"
D.Strings[80286]="我想购买钢化命运印记。"
D.Strings[80287]="快去西边找玛拉达尔吧。我担心他遭遇了古尔丹的主力部队。"
D.Strings[80288]="快去西边的战场找我丈夫！但愿我们的伤亡不会太大。"
D.Strings[80289]="这儿！这儿就是天然良港。"
D.Strings[80290]="每个死亡幻象符文中都必须有人进入，以避免全团伤害！"
D.Strings[80291]="导致鸦人分裂数年的分歧如今看来似乎已变得微不足道了。在通天峰生死攸关之际，我们却把力气浪费在彼此恐惧与猜忌上。往事不可追，但请记住，还有一些人不希望我们的人民成为对古尔丹罪行的注解。\n\n我愿意帮助你，$c。当前，我们必须互相帮助，否则这个世界就完了。"
D.Strings[80292]="|TINTERFACE\\ICONS\\ability_warlock_moltencoregreen.blp:20|t$n被打上了|cFFF00000|Hspell:186961|h[虚空放逐]|h|r的印记！"
D.Strings[80293]="|TINTERFACE\\ICONS\\spell_misc_zandalari_council_soulswap.blp:20|t你被打上了|cFFF00000|Hspell:186123|h[精炼混乱]|h|r的印记！"
D.Strings[80294]="|TINTERFACE\\ICONS\\spell_shadow_soulleech_1.blp:20|t你被打上了|cFFF00000|Hspell:185014|h[聚焦混乱]|h|r的印记！"
D.Strings[80295]="死亡……也没那么糟。"
D.Strings[80296]="你的死亡将令我更加强大。"
D.Strings[80297]="塔纳安已经遍地狼烟了，指挥官。今天我们该集中进攻哪里呢？"
D.Strings[80298]="古尔丹正在组建属于他的狂信徒大军。我们该从哪里开始反击呢？"
D.Strings[80299]="古尔丹打不垮我们。燃烧军团从未打垮过我们！今天，我们将发起反击。"
D.Strings[80300]="这座丛林里隐藏着未知的危机。但只要我们够聪明，就可以利用它来掩护下一次进攻。"
D.Strings[80301]="我收到了本地游侠送来的最新报告，指挥官。我们该进攻哪里呢？"
D.Strings[80302]="古尔丹的邪能爪牙正在包围我们。我们必须主动出击，指挥官！"
D.Strings[80303]="我们的战士都受过圣光的祝福，意志坚定且身经百战。他们正在等待你的指令。"
D.Strings[80304]="就算这真的是世界末日，可至少我会起来战斗。为了萨玛拉，为了玛尔拉德，为了所有为我们的今天而牺牲的人们！"
D.Strings[80305]="你竟敢这样跟我说话！"
D.Strings[80306]="你们凡人的坚持只会让我嗤之以鼻。主人早就连这一天都料到了。"
D.Strings[80307]="可怜虫。滚出我的视线……我最讨厌摇尾乞怜的家伙。"
D.Strings[80308]="你被|cFFFF0000|Hspell:181295|h[消化]|h|r了。在倒计时结束前跑到中央可以免于一死！"
D.Strings[80309]="啊——呃，指挥官！遵命，指挥官！哼哼！"
D.Strings[80310]="<这个步兵对你的到来浑然不觉，依然靠在墙上打着瞌睡。>"
D.Strings[80311]="醒醒！不然我就派你去扫厕所，“准备工作”这种鬼话就不用说了！"
D.Strings[80312]="<斯考勒往你的脸上扔了几个坚果，然后才反应过来你并不是松鼠。>$b$b噢，你好啊，朋友。即使是在这片战火纷飞的丛林里，我们也不能忘了照顾那些小动物。"
D.Strings[80313]="<斯考勒往你的脸上扔了几个坚果，然后才反应过来你并不是松鼠。>$b$b噢，你好啊，朋友。即使是在这片战火纷飞的丛林里，我们也不能忘了照顾那些小动物。$b$b嘿……快过来。看在你特意过来打招呼的份上……你想不想要一份礼物？"
D.Strings[80314]="当然想！先生，你真是个绅士，真不愧是……斯考勒。"
D.Strings[80315]="要塞：船坞建设"
D.Strings[80316]="塔纳安丛林：开始进攻"
D.Strings[80317]="塔纳安丛林：建造雄狮岗哨"
D.Strings[80318]="塔纳安丛林：建造沃玛尔"
D.Strings[80319]="地狱火堡垒：古尔丹的计划"
D.Strings[80320]="地狱火堡垒：德拉诺的胜利！"
D.Strings[80321]="传送门上闪烁着堡垒的影像。"
D.Strings[80322]="传送到地狱火前厅。"
D.Strings[80323]="传送到鲜血庭院。"
D.Strings[80324]="传送到地狱火堡上层。"
D.Strings[80325]="送我去毁灭者高台。"
D.Strings[80326]="传送到毁灭者高台。"
D.Strings[80327]="传送到黑暗之门。"
D.Strings[80328]="我想返回钢铁壁垒。"
D.Strings[80329]="目标锁定！"
D.Strings[80330]="盯住你了！"
D.Strings[80331]="|TInterface\\Icons\\warlock_curse_shadow_aura:20|t%s开始施放|cFFFF0000|Hspell:186348|h[古尔丹之怒]|h|r！"
D.Strings[80332]="|TINTERFACE\\ICONS\\inv_enchant_voidsphere.blp:20|t一颗虚空之星|cFFF00000|Hspell:189894|h[锁定]|h|r了你！"
D.Strings[80333]="你不是还有建筑要造吗？"
D.Strings[80334]="指挥官，如果你愿意继续战斗，征服塔纳安其他战场的时机已经成熟了。"
D.Strings[80335]="我们现在士气正盛，指挥官。你应该一鼓作气，冲向丛林中的其他战场。"
D.Strings[80336]="又一场辉煌的胜利！如果你依然热血沸腾的话，那么塔纳安的其他战场也在等着你……"
D.Strings[80337]="我们得继续向敌人施加压力，指挥官。攻击塔纳安其他战场的时机已经成熟了。"
D.Strings[80338]="联盟又迎来了一场大胜！你应该乘胜追击，攻击塔纳安的其他战场。"
D.Strings[80339]="干得好，指挥官。游侠斥候报告说塔纳安的其他战场也可以开战了。"
D.Strings[80340]="你已经把古尔丹的爪牙打得落花流水了，指挥官。趁他们忙着逃跑之际，你可以考虑攻击塔纳安的其他战场。"
D.Strings[80341]="继续努力，指挥官！攻击塔纳安其他战场的时机已经成熟了。"
D.Strings[80342]="我需要一套新的驱逐舰图纸。"
D.Strings[80343]="你好像弄丢了一张海军图纸？我可以帮你！"
D.Strings[80344]="我需要一套新的高能炉图纸。"
D.Strings[80345]="你好像弄丢了一张海军装备图纸？我可以帮你！"
D.Strings[80346]="将|cFFFF0000|Hspell:179202|h[安苏之眼]|h|r丢给一个治疗者，以驱散|cFFFF0000|Hspell:181753|h[邪能炸弹]|h|r。"
D.Strings[80347]="将|cFFFF0000|Hspell:179202|h[安苏之眼]|h|r丢给某个受|cFFFF0000|Hspell:181957|h[幻影之风]|h|r影响的目标。"
D.Strings[80348]="将|cFFFF0000|Hspell:179202|h[安苏之眼]|h|r丢给受|cFFFF0000|Hspell:181824|h[幻影腐蚀]|h|r影响的坦克。"
D.Strings[80349]="古尔丹既然要战，我们就奉陪到底！"
D.Strings[80350]="指挥官，沃金派我来支援你的塔纳安战役。暗影猎手愿为你效劳。"
D.Strings[80351]="我们竭尽全力，指挥官。在塔纳安每消灭一个恶魔，艾泽拉斯就会多一分安宁。"
D.Strings[80352]="唔，我觉得……那个……位置感觉不错……"
D.Strings[80353]="钻头，可爱的钻头！"
D.Strings[80354]="嘿，指挥官，有兴趣听我介绍一个投资项目吗？它可以将你的一部分资产离岸转移。这是真正的离岸，我认识一个朋友想建一个油井。"
D.Strings[80355]="我只想对你说一个词。就一个词。你有没有在听啊？我想说的是：原油。"
D.Strings[80356]="指挥官！最近有什么好消息吗？"
D.Strings[80357]="噢，伙计，我敢肯定，我们下次就要交好运了！"
D.Strings[80358]="你觉得钢铁部落用的那些用邪能驱动的机器还需要润滑油吗？"
D.Strings[80359]="|TInterface\\Icons\\Spell_Fire_FelRainOfFire.blp:20|t%s开始施放|cFFF00000|Hspell:185284|h[弹幕射击]|h|r！"
D.Strings[80360]="以先知之名，我们必须净化这片土地。"
D.Strings[80361]="时间紧迫，我们还有许多事情要做。远古的宿敌已经发现了我们。如果不能夺回塔纳安……我们就全完了。"
D.Strings[80362]="我们已经逃避得太久了。无止境的逃亡该结束了！这个世界已经成为了我们的家园，我们要誓死保卫它。"
D.Strings[80363]="这颗水晶微微闪烁着，但未能在附近发现任何猎物……"
D.Strings[80364]="你以为拿着个小玩具四处钻营就算是猎人了？我来让你看看什么才是真正的力量吧……"
D.Strings[80365]="暗影……无处不在……"
D.Strings[80366]="索克雷萨从房间周围的传送门中召唤出了援军！"
D.Strings[80367]="指挥官，这边！我这里有你需要的图纸。"
D.Strings[80368]="我可以提供你所需要的战列舰图纸，但首先，你要向塔纳安丛林的先知之手证明自己的价值。"
D.Strings[80369]="我可以提供你所需要的战列舰图纸，但首先，你要向塔纳安丛林的沃金之锋证明自己的价值。"
D.Strings[80370]="我想再建一艘驱逐舰。"
D.Strings[80371]="我想建造一艘驱逐舰。"
D.Strings[80372]="开始建造我们的第一艘运输舰。"
D.Strings[80373]="我听说你是海军装备方面的专家。有空帮我个忙吗？"
D.Strings[80374]="我可以帮你，$c。我记得在码头深处看见过一些文件。快过去看看吧。"
D.Strings[80375]="想要让你的公会扬威寒霜晶壁吗？"
D.Strings[80376]="让这里更加喜庆一点怎么样，指挥官？"
D.Strings[80377]="你肯定已经厌倦了战争。来场派对怎么样？"
D.Strings[80378]="难道你不喜欢节日吗？我喜欢！"
D.Strings[80379]="让我的要塞为万圣节派对做好准备。"
D.Strings[80380]="让我的要塞为冬幕节派对做好准备。"
D.Strings[80381]="派对结束了。清除掉这些装饰吧，伊兹。"
D.Strings[80382]="这真是一年中最美好的时光！"
D.Strings[80383]="想要了解你的未来吗？比如你是怎么死的？"
D.Strings[80384]="时间就像新换的羽毛一样从我们身上剥离。你还能换几次毛呢？艾卡利或许能告诉你。"
D.Strings[80385]="说说我的未来吧，艾卡利。"
D.Strings[80386]="告诉我，$R，你的心里住着德拉诺的哪一种野兽呢？"
D.Strings[80387]="每年的这个时候，我通常都会特别亢奋，可是有格噜普斯在附近时，你就很难高兴得起来。"
D.Strings[80388]="这片土地充斥着生离死别。我的魔法可以让这里变得更加友好一些。"
D.Strings[80389]="我已经迫不及待想要回家了！"
D.Strings[80390]="这些格噜噜闻上去真古怪。"
D.Strings[80391]="这里真冷啊！"
D.Strings[80392]="你与这个世界间的羁绊只是几条线而已。想要试试割断几根吗？"
D.Strings[80393]="别害怕。我的啤酒只会向你展现已经发生的景象。"
D.Strings[80394]="无论准备了多少，礼物总是多多益善！"
D.Strings[80395]="冬天来了！"
D.Strings[80396]="让我们渡过一个空前绝后的精彩节日吧！"
D.Strings[80397]="没有热吻还叫什么节日？"
D.Strings[80398]="我就要熬出头了！$B$B如果你不介意的话，我还有一些非常重要的事务需要处理。"
D.Strings[80399]="四、五……六……"
D.Strings[80400]="唔……八？噢，不是吧，又错了……"
D.Strings[80401]="一、二……"
D.Strings[80402]="嘿，该回去干活儿了。这些礼物可不会自己数好的。"
D.Strings[80403]="每个灯泡都检查过了，对吧？$B$B最好还是再检查一遍。"
D.Strings[80404]="这地方的节日气氛永远都不嫌少！"
D.Strings[80405]="又是老套的节日福利。还有谁会想要什么烟林牧场的终生会员资格？"
D.Strings[80406]="你有没有恰巧看见一只松鼠跑过？那个讨厌鬼是混在圣诞树里溜进来的……"
D.Strings[80407]="这里还需要一些装饰。你肯定不想眼巴巴地看着我们的邻居向我们炫耀他们今年的装饰，对吧？"
D.Strings[80408]="跑了一个！"
D.Strings[80409]="喔唷！那一定很疼。"
D.Strings[80410]="哇，真冷！"
D.Strings[80411]="哈哈，这真是太棒了！"
D.Strings[80412]="接下来换我来打你了！"
D.Strings[80413]="这是我最喜欢的节日！"
D.Strings[80414]="人人都得挨雪球！"
D.Strings[80415]="雪球来啦！"
D.Strings[80416]="我该怎么获得恐怖补给品和欢乐补给品？"
D.Strings[80417]="在万圣节和冬幕节期间，本地居民可能会前来拜访，并请求你帮忙对付某些德拉诺的住民。他们肯定很乐意赠送一些节日补给品给你的！"
D.Strings[80418]="你看起来很渴望战斗的样子。如果你有兴趣的话，部落正需要更多的部队。"
D.Strings[80419]="我将暂时在战场上与部落并肩战斗。"
D.Strings[80420]="你被沙塔斯内的一股神秘力量击退了！"
D.Strings[80421]="是的，我愿意在阿什兰为部落而战。现在就送我过去吧！"
D.Strings[80422]="我正好有一只靴子，而且我知道该用它来踹谁！"
D.Strings[80423]="噢，你什么时候过来的，$c？"
D.Strings[80424]="这里有一股强大的魔力流干扰着镜子。"
D.Strings[80425]="你已经等了很久了吗，$r？"
D.Strings[80426]="嘿，我，听好了。我要警告你！不对，是我们！我有危险。我是说，我们有危险。也不对……是我曾遇到过危险，而你将要遇到危险。该死的时空旅行……"
D.Strings[80427]="嘿，$n。这次不是警告。我就是来打个招呼。"
D.Strings[80428]="$n，你怎么还不给那件装备附魔。相信我，我们没那么快换掉它的。"
D.Strings[80429]="哇，$n，那套幻化真的很棒！简直棒极了，我也想穿。"
D.Strings[80430]="你每次花钱修装备，都会让我购买无主的黑市宝箱变得更加困难。注意点安全吧！"
D.Strings[80431]="回头见，$n！记住，我过去就是你。我现在还是，但我过去也是。"
D.Strings[80432]="我们下次再去奥特兰克山谷时，不管你做什么，都记住：别！点！传！送！门！"
D.Strings[80433]="我得走了，你千万别忘了——"
D.Strings[80434]="很高兴见到你，$n！你说，青铜龙们到底有没有空闲时间？明白我的意思吗？空闲时间！他们能够时空旅行！一群讨厌鬼。"
D.Strings[80435]="再见，$n！但愿我能回到正确的时间流。克罗米向我解释了远离，可我们总是搞错。"
D.Strings[80436]="嘿，$n！啊噢……这是不是我们去旅店，然后你帮忙代打炉石的那次？我们太可耻了！"
D.Strings[80437]="嗷呜！我是未来的冬幕节幽灵！如果你能够公平公正地游戏，我们就能给自己买身新护甲穿！不要皱眉，不要烦恼，如果我们不想要护甲，也可以弄只战斗宠物玩！"
D.Strings[80438]="再见，$n！如果你的坐骑飞得够快，下次你就能来拜访我了。你应该给它装个邪能闪电电容器（超级不稳定）。那玩意儿发明出来了没？"
D.Strings[80439]="再见，$n。临别提问：青铜龙会购买分时度假产品吗？规划假期对他们来说一定是个噩梦。"
D.Strings[80440]="最近怎么样，$n？你不用回答，我已经知道了。呃，是知道了。我想你一定会知道最近怎么样的。好吧，是我们想。你已经这么想了？时态真是太烦人了。"
D.Strings[80441]="你看起来很渴望战斗的样子。如果你有兴趣的话，联盟正需要更多的部队。"
D.Strings[80442]="是的，我愿意在阿什兰为联盟而战。现在就送我过去吧！"
D.Strings[80443]="我将暂时在战场上与联盟并肩战斗。"
D.Strings[80444]="就算是死在战场上，也好过一辈子累死累活地制造武器和护甲给……古尔丹就是这么对待我的兄弟姐妹们的。"
D.Strings[80445]="那个绿皮跛子对这片丛林所做的一切太可怕了。连食人魔都没有对世界造成过这么严重的破坏！"
D.Strings[80446]="看来你没有完成在阿什兰的上一次兵役。几分钟后再来找我吧。"
D.Strings[80447]="我准备好飞向艾格文高塔了。"
D.Strings[80448]="我们必须重新激活这些结界。否则，燃烧军团肯定会淹没我们的岗哨，涌入艾泽拉斯的。"
D.Strings[80449]="你们的军团正在瓦解。背叛者就在你们中间……你们将永远背负这个诅咒。"
D.Strings[80450]="肯定有办法通过这些雕像。$b$b我想回到我的大厅中，可每次我走到那些猫头鹰面前，都会被它们赶跑。我已经很累了……"
D.Strings[80451]="呃，我想要是你能|cFF0000FF[隐形]|r，应该就能过去了……"
D.Strings[80452]="我会想办法通过那些猫头鹰的。"
D.Strings[80453]="我需要帮助！你是怎么通过那些猫头鹰的？"
D.Strings[80454]="一年又一年过去了，我的肚子都越来越饿。我真的需要吃点东西了。$b$b要是你能帮我填饱肚子，我甚至可以把我的卷轴给你。"
D.Strings[80455]="唔……你看着像是某种魔法师。你肯定可以施展|cFF0000FF[造食术]|r吧……"
D.Strings[80456]="我可以帮你弄点吃的。"
D.Strings[80457]="我需要帮助！我该怎么喂饱饥饿的小伙伴？"
D.Strings[80458]="我真的要去哄我女儿睡觉了。离她睡觉的时间都过去几百年了。$b$b可我好像穿不过这些墙。作为家长我该怎么办？"
D.Strings[80459]="孩子长得太快了。|cFF0000FF[闪现]|r几次的功夫他们就长大了……"
D.Strings[80460]="我会想办法穿过这些墙的。"
D.Strings[80461]="我需要帮助！我该怎么穿过这些墙？"
D.Strings[80462]="主人让我清除演讲厅里的害虫。可这只老鼠真是让我伤透了脑筋。"
D.Strings[80463]="这个该死的家伙身上有一个强大的法术。当然，一个强大的法师或许可以用|cFF0000FF[法术偷取]|r之类的法术解决它，可我只是个扫地的……"
D.Strings[80464]="我会帮你打败它的。"
D.Strings[80465]="我需要帮助！我该怎么才能打败那只怪物？"
D.Strings[80466]="我们要团结起来，一同封印萨格拉斯之墓并击败燃烧军团。"
D.Strings[80467]="我准备好去寻找我的神器了！"
D.Strings[80468]="食物！请收下我的法术卷轴吧，我已经用不着它了。"
D.Strings[80469]="<这本书里收录了各种法术——有些很陌生，但大部分很熟悉。其中有一个法术特别有趣。>"
D.Strings[80470]="<施放法术，召唤艾露尼斯。>"
D.Strings[80471]="“强大的法杖艾露尼斯存在于一个难以捉摸的位面，只有最老练的法师才能接触到它。大法师伦塔里克是第一个召唤它的人。我是最后一个。”$b$b ——护法者艾格文"
D.Strings[80472]="“强大的法杖艾露尼斯存在于一个难以捉摸的位面，只有最老练的法师才能接触到它。大法师伦塔里克是第一个召唤她的人，而我是最后一个。”$b$b ——护法者艾格文"
D.Strings[80473]="“艾露尼斯会反抗那些试图掌握它的人。我们必须首先击溃这把法杖任性的灵魂。”$b$b——护法者艾格文"
D.Strings[80474]="“艾露尼斯会反抗那些试图掌握她的人。我们必须首先击溃这把法杖任性的灵魂。”$b$b——护法者艾格文"
D.Strings[80475]="“艾露尼斯任性且反复无常。它的召唤者必须尽快束缚住它，以免它因好奇而误入歧途。”$b$b——护法者艾格文"
D.Strings[80476]="“艾露尼斯任性且反复无常。她的召唤者必须尽快束缚住她，以免她因好奇而误入歧途。”$b$b——护法者艾格文"
D.Strings[80477]="“艾露尼斯的力量会立即在持有者身上体现出来。但更精妙的控制手法，则需要时间的磨砺。”$b$b——护法者艾格文"
D.Strings[80478]="“在不用时，艾露尼斯必须回到它自己的位面中。”$b$b——护法者艾格文"
D.Strings[80479]="“在不用时，艾露尼斯必须回到她自己的位面中。”$b$b——护法者艾格文"
D.Strings[80480]="啊……艾露尼斯。你提到了护法者的法杖。$b$b我早知道这不是一把普通的武器。我的女主人总是一伸手，凭空将它抓出来，挥舞几下然后……再把它凭空放回去。$b$b这可不是什么障眼法或者江湖骗子的隐形伎俩。那根法杖来自另一个世界。护法者知道如何进入那个位面并将它拿出来。"
D.Strings[80481]="我曾在女主人的图书馆里见过这把强大的武器，只有一次，当时它正在一堆堆书籍之间跑来跑去！$b$b我假装没有看见它，但它恐怕已经发现我在瞪着它了。"
D.Strings[80482]="你是说护法者的武器？我可以把我知道的都告诉你。$b$b在我很小很小的时候，有一次我的女主人将它靠在房门上，我就伸手想摸摸它。结果它放出了粉色触须和紫色闪电来抗拒我的触摸，可疼了。$b$b没过一秒钟，护法者就出现了，将它从我身边拖走了。$b$b她和那根法杖之间有着深厚的羁绊——我始终没能彻底搞懂这种羁绊。"
D.Strings[80483]="那把武器……我以前从没见过这样的东西。$b$b我的女主人会跟它说话，好像它是活的一样。她会跟它谈法术、仪式，还有其他高深莫测的东西……反正都超出了我的理解能力。$b$b我的女主人虽然有点蛮横，不过从来没有狠狠打过我。但不管怎样，跟一根法杖说话还是太奇怪了。"
D.Strings[80484]="关于艾露尼斯，你知道多少？"
D.Strings[80485]="拿上这个。还有这个。你把那个也搬回去，该死的$r！"
D.Strings[80486]="我诅咒你，$g混蛋:女人;。我诅咒你。"
D.Strings[80487]="没毛的蠢蛋。这个武僧打了我的脸！现在，给我斗士大餐！"
D.Strings[80488]="你比我还像个猢狲，坏家伙。给，你的大餐。这是自己挣来的。"
D.Strings[80489]="又怎么了？你这个该死的、狡猾的、凶残的家伙？"
D.Strings[80490]="要不是需要海巨人的支持，我肯定当场就宰了你。"
D.Strings[80491]="你今天没饭吃，奴隶。"
D.Strings[80492]="说，恶魔！燃烧军团把伊利丹的尸体藏在哪里？"
D.Strings[80493]="我……是不会……告诉你的！"
D.Strings[80494]="那就尝尝夺魂之镰的滋味吧……"
D.Strings[80495]="我说了，我把你兄弟揍得鼻青脸肿后，他提着裤子跑了。现在，给我大餐！"
D.Strings[80496]="嘿，乌卡，你的表情都已经说了。那玩意儿很难吃，而且一点也不卫生。"
D.Strings[80497]="呸。"
D.Strings[80498]="好烫……好烫啊！"
D.Strings[80499]="去搞一个光板儿吧。其实，同时搞两个比较好，前后各一个。"
D.Strings[80500]="我的脑袋？你这个头上没毛的蠢蛋！"
D.Strings[80501]="不准碰我的兄弟，你这个坏蠢蛋！"
D.Strings[80502]="我想看看你这里的美酒。"
D.Strings[80503]="我妈妈？我妈妈！你这混蛋！"
D.Strings[80504]="我们得集中力量为其他囚犯弄到武器，并让你成为尾锚的角斗士冠军。\n\n然后，我们就能去干掉欧逊努斯王子了。"
D.Strings[80505]="燃烧军团将奴役众生！"
D.Strings[80506]="怎么？啥？这种斗士大餐是祖传秘方。\n\n你休想搞到它，$r。"
D.Strings[80507]="……法罗迪斯……...高戈奈斯潮汐之石……我们最后的希望……"
D.Strings[80508]="我只能想起这么多。帮我找回记忆，我或许就能帮你了。"
D.Strings[80509]="法罗迪斯，是时候行动了。"
D.Strings[80510]="你们的艾萨拉女王滥用魔法的行为引来了燃烧军团的恶魔觊觎。我们已经没有多少时间了"
D.Strings[80511]="我同意……可我们一定要用潮汐之石吗？这手段太激烈了。"
D.Strings[80512]="我就知道你靠得住，法罗迪斯。"
D.Strings[80513]="伊利丹，我对塞纳留斯的计划有些疑虑。"
D.Strings[80514]="他想使用高戈奈斯潮汐之石！摧毁永恒之井！"
D.Strings[80515]="这是能毁灭世界的东西！"
D.Strings[80516]="我知道。可你没有足够的力量阻止塞纳留斯靠近潮汐之石……哪怕再加上我也不行。"
D.Strings[80517]="那我们怎么办？"
D.Strings[80518]="只有艾萨拉女王亲自出手，才有可能对付他那样的半神。"
D.Strings[80519]="我很抱歉，塞纳留斯。我相信你是出于正义的目的，可我没法说服自己去反对……"
D.Strings[80520]="你今天帮了我一个大忙，法罗迪斯。"
D.Strings[80521]="可惜你不能活着接受我的褒奖了。"
D.Strings[80522]="……什么？！"
D.Strings[80523]="这座山谷中充斥着阴谋家和背叛者。"
D.Strings[80524]="背着我跟塞纳留斯眉来眼去？我绝不容忍任何有异心的家伙！"
D.Strings[80525]="看好了。我会召唤出我对这个……潮汐之石的记忆影像。"
D.Strings[80526]="高戈奈斯潮汐之石恐怕就是我们最后的希望了。"
D.Strings[80527]="就是它了，王子殿下：高戈奈斯潮汐之石，七大创世之柱之一，卡多雷的珍贵圣物。"
D.Strings[80528]="很好，你退下吧。"
D.Strings[80529]="什么人？把你的手和武器都放在我看得见的地方。"
D.Strings[80530]="向我证明你不是敌人。"
D.Strings[80531]="原谅我，父亲。"
D.Strings[80532]="你的嘴巴还挺厉害的，乌卡。或许我应该用你那该死的武僧大餐塞上它。"
D.Strings[80533]="啊，有客人来。自从马顿一战之后，我们好久没见了，阿莱利。"
D.Strings[80534]="都听好了！找到潮汐之石，将它交还给艾萨拉女王！"
D.Strings[80535]="这些家伙只是在不懂装懂。潮汐之石属于荣耀的海底之光艾萨拉！"
D.Strings[80536]="翻开每一粒沙子！"
D.Strings[80537]="搜查废墟！"
D.Strings[80538]="杀光所有挡路的家伙！"
D.Strings[80539]="找到潮汐之石！"
D.Strings[80540]="艾萨拉女王需要它，她的愿望必将实现！\n"
D.Strings[80541]="你想跟我谈谈？"
D.Strings[80542]="你的同胞都很鄙视你。为什么？你干了什么？"
D.Strings[80543]="这都是你干的？你怎么做到的？为什么要这么做？"
D.Strings[80544]="该死的混账蠢蛋！"
D.Strings[80545]="莽撞的混账蠢蛋，你最好把它还回来！"
D.Strings[80546]="想去竞技场？不想？那就好好干活！"
D.Strings[80547]="没毛的臭娘们！没错，我就说。没毛的臭娘们。"
D.Strings[80548]="我该走了，守夜人……我想你们也不会想我的。"
D.Strings[80549]="唔。这条路已经被淹了多久了？我得找园丁来处理一下。"
D.Strings[80550]="啊！小心！"
D.Strings[80551]="萨德斯，我最信赖的队长。"
D.Strings[80552]="知道吗，乌卡？你的脑袋进水了！"
D.Strings[80553]="要不是海巨人要你们活着参赛，你早就死了。"
D.Strings[80554]="我们去找那块潮汐之石吧。"
D.Strings[80555]="你把他放出来干嘛？他是伊利丹大人的对头！"
D.Strings[80556]="你来帮助伊利达雷抵抗恶魔，我来研究一下我们在阿苏纳的下一步行动。\n\n我们必须找到创世之柱。我知道它就在这里的某个地方。"
D.Strings[80557]="卡德加，我们走。"
D.Strings[80558]="我记起来了——我把潮汐之石藏在纳萨拉斯学院里了。"
D.Strings[80559]="那已经是很久以前了。"
D.Strings[80560]="这一带的精灵不像我这么好客，小心点。"
D.Strings[80561]="法罗迪斯！你这个叛徒！这都是你造的孽！"
D.Strings[80562]="去死吧……法罗迪斯……"
D.Strings[80563]="这儿，就是纳萨拉斯学院，一切开始的地方。"
D.Strings[80564]="请带我去找潮汐之石。"
D.Strings[80565]="Fum fee fo fie！快回去干活，否则就死！"
D.Strings[80566]="鲸腹会加重我们的工作量的。你最好别冒犯他。"
D.Strings[80567]="像你这么弱小的$r来这里做什么？\n\n噢，把你切碎做成鱼饵一定会很有趣的。"
D.Strings[80568]="鲸腹老板，很高兴见到你。你记住了，就在今天，我一定会成为竞技场冠军的。"
D.Strings[80569]="我早就看穿你和你那个小伙伴了。你以为你能在我这里横插一杠子？\n\n想都别想。\n\n我可以跟你保证，等今天结束后，我就会踩着你的脖子，让你趴在竞技场的地板上，$r。"
D.Strings[80570]="这就是你犯的错误，鱼饵。致命的错误。"
D.Strings[80571]="看到这把剑了吗？我要把它插进你……"
D.Strings[80572]="等等……什么？"
D.Strings[80573]="鲸腹，这都是怎么了？"
D.Strings[80574]="我早就说了，别跟角斗士对手说那么多废话！"
D.Strings[80575]="别啰嗦了，你的战斗就要开始了。"
D.Strings[80576]="战胜我，否则你也就不用费心该怎么爬回去了，小螃蟹。"
D.Strings[80577]="我喜欢你的勇气，小东西。我很乐意当着整个营的面剖开你的肚子。"
D.Strings[80578]="我的女主人，阿茜萨！我……让你失望了……"
D.Strings[80579]="下面发生什么事了？"
D.Strings[80580]="侍从们！干掉这些入侵者！"
D.Strings[80581]="这是我的荣幸，女主人……"
D.Strings[80582]="进去，干掉敌人。其它事都不用管。"
D.Strings[80583]="拿出背水一战的气势去战斗吧，它将决定你的生死。"
D.Strings[80584]="我就剩下你了吗？"
D.Strings[80585]="不择手段去赢得胜利吧。我不管你是作弊还是往他的眼睛里洒沙子，只要你能赢！"
D.Strings[80586]="我得再去弄沉一艘船，抓些更好的角斗士回来。"
D.Strings[80587]="刺穿他的肝脏，把他的脾脏扯出来！"
D.Strings[80588]="我要看到鲜血染红黄沙，而且最好不是你的血！"
D.Strings[80589]="我选你。"
D.Strings[80590]="我对你有信心，小家伙。"
D.Strings[80591]="走进去，全力应战吧。"
D.Strings[80592]="无论是输是赢，你都是我眼中的赢家。"
D.Strings[80593]="不要害怕，你能做到的。"
D.Strings[80594]="别听老锈舵的。他是因为没人爱所以发疯了。"
D.Strings[80595]="只要有端正的态度，你就能做到任何事。"
D.Strings[80596]="去让我为你骄傲吧，我的小朋友。"
D.Strings[80597]="如果一场都赢不了的话，我就杀光你们所有人！"
D.Strings[80598]="没用的小废物！"
D.Strings[80599]="你的宠物作弊了，尾锚。你要为此付出代价。"
D.Strings[80600]="我真想过去打烂你那张傻笑的丑脸。"
D.Strings[80601]="清理掉几个弱者也是好事。我还没有派出我最强的角斗士呢。"
D.Strings[80602]="如果你知道好歹的话，最好还是待着别动。"
D.Strings[80603]="你们统统都是废物。听到没有？废物！"
D.Strings[80604]="这只能证明小个子的种族是多么弱小。我们真该把他们都碾碎。"
D.Strings[80605]="如果你知道好歹的话，就一直赢下去把，小螃蟹。"
D.Strings[80606]="哈！显然是我赢了。谁还有什么怀疑吗？"
D.Strings[80607]="放弃吧，尾锚。你的那些小可怜毫无胜算。"
D.Strings[80608]="你要继续打下去，直到死亡，或者他没有宠物可派了为止。"
D.Strings[80609]="下次再打好点，否则我就把你踩扁。"
D.Strings[80610]="我又赢了一场！你什么都不是，只是一个虚弱过时的老家伙，尾锚。"
D.Strings[80611]="这就是取胜的诀窍。你们都给我看着点！"
D.Strings[80612]="大获全胜！大获全胜！大获全胜！"
D.Strings[80613]="噢不，你不能这样，我的小朋友。"
D.Strings[80614]="安息吧，伙计。这是你应得的。"
D.Strings[80615]="锈舵，你这个坏蛋。你的斗士作弊！"
D.Strings[80616]="你打得很英勇，身手也很出色，小家伙。"
D.Strings[80617]="别担心，我的朋友们。下次我们会赢的。"
D.Strings[80618]="让我们为倒下的战友干一杯吧。"
D.Strings[80619]="大家都打起精神来。锈舵的人更有经验，但我们有勇气！"
D.Strings[80620]="为好人们记上一分！"
D.Strings[80621]="太棒了！精彩的战斗，我的小朋友。"
D.Strings[80622]="你真是百战百胜，小家伙。"
D.Strings[80623]="这下我们可有好戏看了！"
D.Strings[80624]="精彩的表现，不过下次我们最好不要杀掉对手？"
D.Strings[80625]="祝你好运，锈舵。"
D.Strings[80626]="尾锚队又胜利了。万岁！"
D.Strings[80627]="干得好，伙计们。让我们安全地离开这里。"
D.Strings[80628]="祝你顺利找到潮汐之石，$n。"
D.Strings[80629]="我不敢进入那座学院，但我发誓会尽力帮助你的。"
D.Strings[80630]="好的好的，那是啥？$b$b如果是有关塑能系的期末考试的话，那么答案就是不，你休想再得到它了。"
D.Strings[80631]="你——噗——什么！？$b$b你是知道的吧？在法罗迪斯王子背叛之后，潮汐之石大厅就被封锁了！"
D.Strings[80632]="你还知道，违反封锁禁令的人都将被处以死刑甚至拘留的吧？"
D.Strings[80633]="不！必须……保护……潮汐之石……"
D.Strings[80634]="你身上有那个叛徒法罗迪斯的味道……"
D.Strings[80635]="蠢货！你打扰了我的研究！"
D.Strings[80636]="大厅里有入侵者！快去通知院长！"
D.Strings[80637]="滚……开……"
D.Strings[80638]="法罗迪斯在哪儿……？"
D.Strings[80639]="杀掉外来者……"
D.Strings[80640]="必须保护潮汐之石……"
D.Strings[80641]="真顺利……这个白痴$r把我们送到了潮汐之石面前。"
D.Strings[80642]="我们的海底女王能修复这些碎片。"
D.Strings[80643]="至于你……会是个不错的奴隶。"
D.Strings[80644]="嘿，你！你以为你是要去哪儿？"
D.Strings[80645]="出去。"
D.Strings[80646]="小心点，$n。桅船是很警觉的。"
D.Strings[80647]="在你行动的同时，我就先赶去欧逊努斯海窟。"
D.Strings[80648]="我会救出那里的角斗士，并将他们都武装起来。他们可以帮我们对付那些巨人。"
D.Strings[80649]="别再让我看见你溜回来。"
D.Strings[80650]="我正想睡觉呢！"
D.Strings[80651]="你以为你能从我身边溜过去？"
D.Strings[80652]="那东西可不是给你的。"
D.Strings[80653]="再有下一次，我一定压扁你！"
D.Strings[80654]="别让我再看见你的脸。"
D.Strings[80655]="来吧，让我们来做个了断！"
D.Strings[80656]="好吧，菲尔古斯，你上。给我杀了他们。"
D.Strings[80657]="祝你好运，我的小朋友。"
D.Strings[80658]="别让我失望，渔夫，否则我就把你穿在鱼钩上当鱼饵用。"
D.Strings[80659]="青龙的祝福与你同在。"
D.Strings[80660]="你还是会输的。"
D.Strings[80661]="去搞定他，鲸腹！"
D.Strings[80662]="来吧，锈舵。让我进去！"
D.Strings[80663]="现在我就要动手了！"
D.Strings[80664]="愚蠢的海象人！"
D.Strings[80665]="这次算你赢了，尾锚，但不会再有下一次了。"
D.Strings[80666]="准备好进入竞技场了吗？"
D.Strings[80667]="我这辈子最大的梦想就是在真正的挑战赛中击败锈舵的三位勇士。他们实在太优秀了！\n\n或许你能帮我实现梦想，$n？"
D.Strings[80668]="$n！能见到你真是太好了。\n\n你随时都能回来帮我战斗。"
D.Strings[80669]="他们准备好了，尾锚。让我上战场吧。"
D.Strings[80670]="让尾锚队为你骄傲吧。"
D.Strings[80671]="呃！你该死！"
D.Strings[80672]="我要离开这里。"
D.Strings[80673]="怎么回事？这是违规的！"
D.Strings[80674]="该死的蠢蛋！像你兄弟一样滚开吧。"
D.Strings[80675]="帕杰什！赶快召集剩余的部队。我要尽快解决这个小麻烦。"
D.Strings[80676]="遵命，潮汐主母。"
D.Strings[80677]="发生了什么事，法罗迪斯？"
D.Strings[80678]="我很内疚。我不能坐视你去为我拼命。"
D.Strings[80679]="于是我决定跟着你进入学院。"
D.Strings[80680]="别让那个囚犯醒过来，帕杰什。"
D.Strings[80681]="遵命，夫人。"
D.Strings[80682]="我鼓起勇气跟紧了他们。"
D.Strings[80683]="在混乱中，我看到那个女巫，她丢下了潮汐之石。"
D.Strings[80684]="阿茜萨，你来招待一下客人。我把囚犯带去奴隶围栏。"
D.Strings[80685]="我诅咒你们，精灵。我要上报给女王陛下！"
D.Strings[80686]="阿茜萨带着潮汐之石跑了。但我没去追她，而是选择来救你，我的勇士。"
D.Strings[80687]="可我在洞穴的入口处遇到了一个老熟人。"
D.Strings[80688]="我最终找到了奴隶围栏。"
D.Strings[80689]="滚开，幽灵！潮汐之石是我们的！"
D.Strings[80690]="之后的事你应该都知道了，$n。"
D.Strings[80691]="<欧库纳·长牙的包裹就扔在地上。上面的一条带子已经断了，还有打斗的痕迹。但里面的东西却一样都没有少。>\n\n<欧库纳可能已经被抓去了欧逊努斯王子那里。看来要撇下他独自前进了。>"
D.Strings[80692]="啊啊！这下你死定了，混蛋。"
D.Strings[80693]="这不是我的武器，但用起来很顺手。"
D.Strings[80694]="付出铁的代价吧，海巨人们。"
D.Strings[80695]="站起来，让我们杀光他们。"
D.Strings[80696]="都是一死，做个自由人总比当奴隶强。"
D.Strings[80697]="去死吧，巨人们。去死吧，欧逊努斯王子！"
D.Strings[80698]="杀光他们。让耐普图隆收拾他们。"
D.Strings[80699]="我的英雄！话说，你有没有找回我的武器？"
D.Strings[80700]="太棒了！让我们动手吧。"
D.Strings[80701]="你来挑起事端，我负责暗中行事。"
D.Strings[80702]="我们越快解决掉欧逊努斯，就能越快离开这里。"
D.Strings[80703]="我们真的成功了。我们干掉了欧逊努斯！\n\n现在，我们自由了。"
D.Strings[80704]="你死定了，欧逊努斯！"
D.Strings[80705]="你想要观众？这儿就有一个！"
D.Strings[80706]="太棒了！我们到下面见。"
D.Strings[80707]="我不知道出了什么事。我听到了巨大的撞击声，然后就发现自己被压在了这根木头下面，之后，我就一直在等待救援。"
D.Strings[80708]="那么，那个可爱的姑娘跑到哪儿去啦？"
D.Strings[80709]="燃烧军团已经攻占了宝库，我的大部分守望者都战死了。所以我才会把你放出来。没有人比你更擅长杀恶魔了，$n。\n\n他们冲着伊利丹的墓穴去了。我们必须合作以阻止燃烧军团。"
D.Strings[80710]="我建议跟我们的狱卒合作……暂时合作。"
D.Strings[80711]="继续逗留在这座监狱里只是浪费时间。我们得尽快离开这里。"
D.Strings[80712]="我们很久不见了，凯恩。虽然我相信我们的事业，可是我不会盲从任何人……包括伊利丹。"
D.Strings[80713]="<打鼾>"
D.Strings[80714]="搜刮"
D.Strings[80715]="不！这不是给你的。这是给欧逊努斯王子的！"
D.Strings[80716]="醒醒。我要见欧逊努斯王子，马上！"
D.Strings[80717]="你这个睡不醒的白痴。我不可能在这儿等上一整天。我现在就要见你们的王子！"
D.Strings[80718]="如果你的王子不想要他的宝藏了，我会很高兴地带着它离开。"
D.Strings[80719]="如果他对宝藏也不感兴趣的话，那或许他需要一些其它形式的刺激？"
D.Strings[80720]="滚开，小东西，否则我将把你当下酒菜吃了。"
D.Strings[80721]="$n，这边。放我出去。"
D.Strings[80722]="搜寻线索"
D.Strings[80723]="当时我们在驶向……风暴峡湾。"
D.Strings[80724]="船搁浅了……海地精包围了我们。"
D.Strings[80725]="龙虾人女王……恶魔……"
D.Strings[80726]="风暴……搁浅了。"
D.Strings[80727]="船长……被抓了……"
D.Strings[80728]="我们当时……正从破碎海滩……驶向风暴峡湾……"
D.Strings[80729]="这里有……恶魔……"
D.Strings[80730]="我听说……船长被……龙虾人吃了！"
D.Strings[80731]="女王……"
D.Strings[80732]="一个$r，真稀奇。过来点，孩子。"
D.Strings[80733]="我能有什么想法？这完全是你的战斗，女王陛下。"
D.Strings[80734]="没用的废物，就跟她的其他同类一样。让我来亲手解决你吧！"
D.Strings[80735]="嘿！不准碰它。"
D.Strings[80736]="别把我们当成走私者。你应该把我们看做专业的救捞队。\n\n我们可是打捞专家，擅长回收各种海上漂浮物、废弃物、船难货物，当然，还有珍稀的考古发现。\n\n噢，还有，你最好避开南边的神殿一带。我派人去那里进行商业调查了，我可不希望你被当成来抢饭碗的。"
D.Strings[80737]="%s召唤水手前进。"
D.Strings[80738]="陌生人，快，来这边。"
D.Strings[80739]="我听凭你的吩咐，$g阁下:女士;。"
D.Strings[80740]="考瓦斯，你和赛娅娜从里面出击。然后，我们再合力扫平他们。"
D.Strings[80741]="我一定要给你点教训。"
D.Strings[80742]="燃烧军团用某种方法抵消了我的恶魔结界。如果我们不能让这些防御装置重新运转起来的话，那我们就输定了，我也会辜负你们所有人。"
D.Strings[80743]="欢迎来到我们简陋的小店，旅行者。"
D.Strings[80744]="我抓住机会，攻击了纳迦的首领，将你救了出来。"
D.Strings[80745]="“出去散个步。”哈！他肯定是出去见他喜欢的那个平民女孩了。"
D.Strings[80746]="艾德斯。你不是出去跟那个女仆鬼混了吧？"
D.Strings[80747]="什么？没有，当然没有！"
D.Strings[80748]="我去见了另一个女孩。"
D.Strings[80749]="我们该拿这家伙怎么办呢？"
D.Strings[80750]="严刑拷打？罚做苦力？还是杀了它？"
D.Strings[80751]="我建议杀了它。"
D.Strings[80752]="好主意，那我们就杀了它吧。"
D.Strings[80753]="一万年前，我跟一群反抗军同盟走到了一起。"
D.Strings[80754]="那时艾萨拉女王的权势在精灵中达到了顶峰。她滥用魔法的行为也越来越肆无忌惮。"
D.Strings[80755]="我们密谋使用高戈奈斯潮汐之石对付女王。"
D.Strings[80756]="塞纳留斯，我可以操纵潮汐之石，但我必须警告你：我们可能会摧毁整个永恒之井！"
D.Strings[80757]="我的朋友，这正是我们的计划。"
D.Strings[80758]="不行！我们只要推翻艾萨拉女王就行了，不需要摧毁我们人民的力量之源。"
D.Strings[80759]="我同意。我们有点小题大做了。"
D.Strings[80760]="我们正在对抗这个世界前所未有的巨大威胁！"
D.Strings[80761]="此时此刻，艾萨拉女王已经与恶魔勾结了起来。她将我们的世界置于了危险之中。"
D.Strings[80762]="很好。法罗迪斯王子，你能拿到高戈奈斯潮汐之石吗？"
D.Strings[80763]="我会安排好的，塞纳留斯。"
D.Strings[80764]="你！站住！"
D.Strings[80765]="我们要一起放出宝石中的恶魔之魂，并用这把镰刀迫使他们交代。\n\n你准备好之后就告诉我一声吧。"
D.Strings[80766]="你别想从我这里知道任何消息，食魂者！"
D.Strings[80767]="经过破碎海滩之战后，我也该交出权力，让卡德加来领导肯瑞托了。"
D.Strings[80768]="是时候搁置我们之间那些微不足道的争议了。团结起来的达拉然足以碾压燃烧军团！"
D.Strings[80769]="乌卡，我能尝尝你那美味的斗士大餐吗？我听说这是最美味的佳肴。"
D.Strings[80770]="燃烧军团把伊利丹的遗体藏在哪儿了？告诉我，否则你就会尝到只在传说中出现过的痛苦了。"
D.Strings[80771]="我准备好了，阿莱利。我们开始吧。"
D.Strings[80772]="他们做了什么？那些恶魔给了你什么？"
D.Strings[80773]="这是谁干的？"
D.Strings[80774]="有人投降了吗？"
D.Strings[80775]="我们将携手从内部摧垮燃烧军团。"
D.Strings[80776]="他们都受了许多折磨。"
D.Strings[80777]="我想我明白这为什么不起作用了。"
D.Strings[80778]="我关在宝石里的一个强大恶魔在帮他们负隅顽抗。"
D.Strings[80779]="我们团结起来的意志比你的镰刀更强大。我是不会告诉你的。"
D.Strings[80780]="伊利达雷，这里怎么了？"
D.Strings[80781]="拿上钥匙，我们去把那条幼龙放出来。"
D.Strings[80782]="你是谁？你不是奴隶！"
D.Strings[80783]="你要去哪儿？"
D.Strings[80784]="你好，$c。\n\n燃烧军团已经占领了法罗纳尔。我有一个计划，可以在他们占领整个阿苏纳之前拦截并击溃他们。\n\n但这需要你的帮助。"
D.Strings[80785]="燃烧军团已经像燎原的野火一样在破碎群岛蔓延开来。\n\n我们必须到处追杀他们，将他们彻底打压下去。\n\n你一定要再次封印萨格拉斯之墓。"
D.Strings[80786]="来吧，朋友，我们一起去见见这位塞纳苟斯。"
D.Strings[80787]="糟了，他的情况不妙啊。"
D.Strings[80788]="大法师卡德加？$C？这可真让人意外。"
D.Strings[80789]="潮汐之石召唤着他们……"
D.Strings[80790]="女王陛下。"
D.Strings[80791]="但愿这能够阻止他们。我们去向王子殿下报告吧。"
D.Strings[80792]="%s开心地大笑起来。"
D.Strings[80793]="对，好想法。或许一些相关得物品能帮助我找回淡忘的记忆。"
D.Strings[80794]="够了！潮汐之石是我们的！"
D.Strings[80795]="把你知道的一切都告诉我们，肮脏的家伙！"
D.Strings[80796]="来吧，$c，我们必须迫使这些恶魔之魂屈服。"
D.Strings[80797]="你尽管骂好了，乌卡。我就要拿走大餐，而你什么都做不了，你这个猢奸。"
D.Strings[80798]="你到底在说啥？！"
D.Strings[80799]="有陌生人过来了！"
D.Strings[80800]="这里就是王子殿下的宫殿。在回去之前，先让我们解决那些纳迦。"
D.Strings[80801]="跟紧了，$n，不要离开我的身边。"
D.Strings[80802]="我一个人应付不了。跟紧我。"
D.Strings[80803]="你在哪儿？"
D.Strings[80804]="我真的很抱歉。"
D.Strings[80805]="潮汐之石在哪儿？！"
D.Strings[80806]="把潮汐之石交给我们！"
D.Strings[80807]="伊利达雷是对抗燃烧军团的第一道、也是最后一道防线。"
D.Strings[80808]="我本该在外面战斗才对。我的双手最擅长的就是掐住恶魔的脖子。"
D.Strings[80809]="束缚我吧。我可能会在这里待一段时间。"
D.Strings[80810]="滚出去。我不想再看见你！"
D.Strings[80811]="你要是够聪明，就立刻交出斗士大餐。"
D.Strings[80812]="那些蛋可以为我的鸡尾酒提供最平衡的结构和奥术能量。"
D.Strings[80813]="他们会因此而记住我的。"
D.Strings[80814]="现在只剩最后的润色工作了。"
D.Strings[80815]="你的导师应该在西边的斜坡下。你最好快一点，抢在第二声钟声敲响前赶过去。"
D.Strings[80816]="干杯。"
D.Strings[80817]="加鲁霍德？他爆炸了！"
D.Strings[80818]="首先，来画一个简单的奥术符文。按照步骤描出它的轮廓。记住它，把它复杂的结构都记在心里。"
D.Strings[80819]="干得好。现在，我们来描一个火焰符文。小心点：要是画错的话，这个符文就会直接炸死你。"
D.Strings[80820]="非常好！最后，是冰霜符文。别忘了第五个环！几乎所有人都会忘掉第五个环。"
D.Strings[80821]="今天就到此为止了。"
D.Strings[80822]="准备……发射！"
D.Strings[80823]="瞄准，发射！"
D.Strings[80824]="举起你们的魔杖，发射！"
D.Strings[80825]="你准备好之后就可以发射了。"
D.Strings[80826]="准备、瞄准、发射！"
D.Strings[80827]="太好了。"
D.Strings[80828]="我看出来了，你一直在努力学习。"
D.Strings[80829]="瞄得很准，和以前一样。"
D.Strings[80830]="非常好。"
D.Strings[80831]="姿势很标准。"
D.Strings[80832]="不，不，不！你没有瞄准！"
D.Strings[80833]="来吧，集中精神！"
D.Strings[80834]="嗨……集中注意力！"
D.Strings[80835]="<唉……>"
D.Strings[80836]="你可以做得更好。"
D.Strings[80837]="不行，让我们再来一次。"
D.Strings[80838]="还需要练习。"
D.Strings[80839]="不可接受。"
D.Strings[80840]="你来。"
D.Strings[80841]="现在该你了。"
D.Strings[80842]="下一个。"
D.Strings[80843]="Zzz……不，院长！别用船桨……zzzz……"
D.Strings[80844]="再睡五分钟……"
D.Strings[80845]="防护系，咒法系，预言系，死灵系……"
D.Strings[80846]="<叹气>……我感觉自己看着这张卷轴已经过了快一万年了，可我还是看不懂它。"
D.Strings[80847]="但愿那里一切安好。"
D.Strings[80848]="仔细找！把这片废墟翻个底朝天！"
D.Strings[80849]="潮汐之石是我们的！"
D.Strings[80850]="凡人，你们敢闯进这里，真是愚不可及。你们所有的成就……你们打倒过的所有敌人……在这里都毫无意义。"
D.Strings[80851]="吃吧，我的爪牙们。把灰烬使者给我拿来。"
D.Strings[80852]="你的阴谋已经败露了，恶魔。我们是来彻底消灭你的。"
D.Strings[80853]="我受够你们这些多管闲事的家伙了，一切到此为止吧。"
D.Strings[80854]="让我们并肩战斗，勇士。"
D.Strings[80855]="<巨龙喷出微弱的龙息。他很痛苦。>"
D.Strings[80856]="英雄……灰烬使者……是唯一的办法……拿上它！"
D.Strings[80857]="是那条苟延残喘的大蜥蜴和他的子嗣派你来的吗？我不会再被束缚住的！"
D.Strings[80858]="你就是这么用三叉戟的吗？"
D.Strings[80859]="学学怎么战斗吧，你们这些没用的水蛭。"
D.Strings[80860]="把三叉戟举起来，你们这些懒鬼海蛇。"
D.Strings[80861]="你还真有胆子，敢在这里露面。"
D.Strings[80862]="为了女王！"
D.Strings[80863]="我们会拿到潮汐之石的，你们阻止不了我们！"
D.Strings[80864]="让艾萨拉的怒火淹没你。"
D.Strings[80865]="你来跳海送死吗？"
D.Strings[80866]="为了纳沙塔尔！"
D.Strings[80867]="我要拿你的骨头磨三叉戟。"
D.Strings[80868]="你竟敢跟我们作对？"
D.Strings[80869]="这是叛乱！"
D.Strings[80870]="圣光注视着我们所有人，朋友。"
D.Strings[80871]="你先走，$n。你的出现才是最重要的。"
D.Strings[80872]="安息吧，兄弟……我们永远不会忘记破碎海滩所发生的一切。"
D.Strings[80873]="在玛里苟斯的领导下，这些长着蓝色鳞片的畜生杀害了我的朋友、我的家人和我的妻子。$b$b随便你怎么处置我，但你记住，我绝对不会放弃追杀他们，直到他们尝到我所承受的痛苦。"
D.Strings[80874]="我……我记得你。在诺森德。你帮我拷问过这些蓝鳞畜生的邪恶爪牙。$b$b在玛里苟斯的领导下，这些长着蓝色鳞片的畜生杀害了我的朋友、我的家人和我的妻子，就因为他们不愿意让我们使用魔法。$b$b随便你怎么处置我，但你记住，我绝对不会放弃追杀他们，直到他们尝到我所承受的痛苦。"
D.Strings[80875]="饶他一命。"
D.Strings[80876]="不！我一定要了结这些畜生！我要报仇！"
D.Strings[80877]="我要让你们为自己在诺森德的所作所为付出代价！"
D.Strings[80878]="你们这些蓝鳞蜥蜴在诺森德杀害了我那么多的朋友！"
D.Strings[80879]="怜悯？我早就没有那种东西了。我会记住你的，$r。"
D.Strings[80880]="提里奥说你会来的。到时候了吗？"
D.Strings[80881]="对，是时候了。我们这就走。"
D.Strings[80882]="我跟你一起去，$n。((莉亚德琳跑了出去))"
D.Strings[80883]="让那个年轻人过来吧。我还没死呢。"
D.Strings[80884]="请原谅我的孙女们。她们认为必须要保护我不受任何一个进入池塘的$r$c的伤害。$b$b请继续吧。"
D.Strings[80885]="<将你的手放在塞纳苟斯的角上。>"
D.Strings[80886]="休息一下吧，祖父！你得节省体力。"
D.Strings[80887]="别急着伤心，小星星。让我最后冒一次险吧。"
D.Strings[80888]="我们该回去找祖父了。"
D.Strings[80889]="我们回蓝翼栖地吧！"
D.Strings[80890]="<你面前站着的……不是塞纳苟斯本人，而是他的一个魔法投影。他看起来强大、自信、心情愉快。他和你看到的那条在池塘中苟延残喘的衰老巨龙完全不同。>"
D.Strings[80891]="你准备好之后，我们就可以走了，$n。"
D.Strings[80892]="那就让我们赶快行动吧。"
D.Strings[80893]="很好，我们在大领主那儿见。((格里安跑了出去))"
D.Strings[80894]="我到外面去等你，顺便备好我们的坐骑。我成立白银之手骑士团就是为了击败燃烧军团——这就是骑士团的首要任务。((提里奥走了出去))"
D.Strings[80895]="你准备好之后就告诉我们一声吧，大领主。"
D.Strings[80896]="只要你一声令下，我们就可以出发了，朋友。"
D.Strings[80897]="燃烧军团以为我们已经完了。我们要让他们看看自己错得有多离谱。"
D.Strings[80898]="进入"
D.Strings[80899]="啊，我的朋友。我最亲爱、最可靠的朋友$n。$b$b你身边有没有带着法力水晶？$b$b听着，我的朋友。如果你有任何需要——我要强调一下，是“任何”需要——只要告诉你忠实的朋友鲁纳斯就行了。我可以解决你的任何烦恼。我绝对靠得住。$b$b当然，如果我有什么需要，我相信你也会帮我的，对吧？比如，如果我需要法力水晶或者类似的东西，你会给我一块的，对吧？"
D.Strings[80900]="直接……带路吧，鲁纳斯。"
D.Strings[80901]="解锁奖励目标！\n|TINTERFACE\\GLUES\\CREDITS\\CrystalSong1TGA1.blp:64|t|TINTERFACE\\GLUES\\CREDITS\\CrystalSong1TGA2.blp:64|t|TINTERFACE\\GLUES\\CREDITS\\CrystalSong1TGA3.blp:64|t\n|TINTERFACE\\GLUES\\CREDITS\\CrystalSong1TGA5.blp:64|t|TINTERFACE\\GLUES\\CREDITS\\CrystalSong1TGA6.blp:64|t|TINTERFACE\\GLUES\\CREDITS\\CrystalSong1TGA7.blp:64|t\n|cFFFFFFFF扎赫纳尔魔网废墟|r"
D.Strings[80902]="你到底在干什么？"
D.Strings[80903]="你不知道我是谁吗？"
D.Strings[80904]="我投降。拜托，朋友，原谅我。我真的，真的很抱歉。"
D.Strings[80905]="吸食这种原始能量……干扰了我的判断力。"
D.Strings[80906]="希望你不要只盯着我破烂的长袍和极端的行为，我不是怪物。"
D.Strings[80907]="你继续走吧，我的朋友。我会留在这里的。"
D.Strings[80908]="谢谢你，朋友，让我在临终前做了件有意义的事。"
D.Strings[80909]="看着，我会证明自己。我可不像那些被法力烧坏脑子的怪胎。"
D.Strings[80910]="噢，看！法力水晶！让我尝一口吧。"
D.Strings[80911]="我想……是时候说再见了。"
D.Strings[80912]="真是了不起的武器，朋友！"
D.Strings[80913]="我……我看不见你了。"
D.Strings[80914]="这是谁？"
D.Strings[80915]="我是伊达利尔之子鲁纳斯，前苏拉玛公民。很高兴认识你。"
D.Strings[80916]="堕夜精灵。我不相信你们。"
D.Strings[80917]="我理解，尊敬的巨龙。你有理由不相信我们，请让我补偿你。"
D.Strings[80918]="很好！那就去扎赫纳尔，去见见我的朋友、家人和爱人吧。"
D.Strings[80919]="……当然是杀了他们，他们伤害了你的龙。"
D.Strings[80920]="一群魔瘾患者，哈！我可不是。我的意志坚如钢铁。"
D.Strings[80921]="噢！法力水晶。稍等。"
D.Strings[80922]="那么……你来阿苏纳干嘛，朋友？是观光，还是……什么？"
D.Strings[80923]="这家伙就不能安静一会儿吗？"
D.Strings[80924]="抱歉，尊敬的巨龙。啊，看！我们到了。"
D.Strings[80925]="饥渴正在侵蚀我的理智。我需要用尽每一分力量来……来……"
D.Strings[80926]="$C，燃烧军团派出了手下最强大的恶魔来对付我们。他们肯定不想输掉这场第三次大战，不将我们彻底从艾泽拉斯抹去，他们是不会罢手的。\n\n我们也要好好“报答”他们的这番“深情厚谊”。"
D.Strings[80927]="给我一点时间……"
D.Strings[80928]="抽取能量"
D.Strings[80929]="他们……折磨……我。"
D.Strings[80930]="我没有屈服。"
D.Strings[80931]="有个守望者想劝我们叛变。我听到了尖叫声。"
D.Strings[80932]="赛娅娜·夜刃叛变了。她加入了军团。"
D.Strings[80933]="丝黛拉苟萨，不……回来。该死！"
D.Strings[80934]="这一下真疼啊。"
D.Strings[80935]="你……你要惹火我了！！"
D.Strings[80936]="<巨龙对你感激地一笑。>"
D.Strings[80937]="有紧急口信给塞纳苟斯！"
D.Strings[80938]="堕夜精灵突袭了繁育地。"
D.Strings[80939]="这四头雏龙急需接受魔网水晶的治疗。"
D.Strings[80940]="噢，你真是个善良的小家伙，$n。"
D.Strings[80941]="赛娅娜·夜刃去哪儿了？我得找到她！"
D.Strings[80942]="等等……等等……你拿的是什么？"
D.Strings[80943]="我要杀了你，挖出你的心脏！"
D.Strings[80944]="你是来解救那条可怜的幼龙吗，恶魔猎手？"
D.Strings[80945]="感受这流淌的邪能……"
D.Strings[80946]="我们给了他们一个下马威。但此刻，燃烧军团仍在不断召唤出强大的恶魔。"
D.Strings[80947]="魔誓者夜刃，去证明你自己吧。我还有其他事要处理。"
D.Strings[80948]="遵命，女主人……"
D.Strings[80949]="我们绝不能让他们重整旗鼓，否则破碎群岛就完了。"
D.Strings[80950]="他在说什么？到宝石外头来见我吧。"
D.Strings[80951]="你会开口的，肮脏的恶魔！"
D.Strings[80952]="你不是恶魔。那你是敌是友？"
D.Strings[80953]="我比你们都要强大！"
D.Strings[80954]="赛娅娜。别放弃！"
D.Strings[80955]="我得找到丝黛拉苟萨和赛娅娜·夜刃。"
D.Strings[80956]="到岗哨来见我。让我们一起解决这件事。"
D.Strings[80957]="效忠燃烧军团的守望者？我想要杀了她。"
D.Strings[80958]="你站在这世界上最伟大奇迹之一中。$b$b我们的酒是用最好的水果酿成的。我们的油也是用最好的橄榄搾成的。$b$b我敢跟任何夸自己产品更好的人比试一番。"
D.Strings[80959]="你很快就自由了，幼龙。"
D.Strings[80960]="你没有资格品尝我们的酒！"
D.Strings[80961]="我的酒是女王陛下专享的。"
D.Strings[80962]="滚出这里。我们产品不是给你们这些下等人生产的。"
D.Strings[80963]="你不该来这里。"
D.Strings[80964]="你不属于这个地方。"
D.Strings[80965]="我们怀念女王。"
D.Strings[80966]="为了艾萨拉！"
D.Strings[80967]="重新激活"
D.Strings[80968]="稍等一会儿，我来解除封印。"
D.Strings[80969]="啊哈！我们到了。"
D.Strings[80970]="跟我来，$n。在我努力学习，争取加入肯瑞托的时候，我已经把这里都逛遍了。我带你四处看看。"
D.Strings[80971]="这是画像室。每张肖像都是一座传送门。"
D.Strings[80972]="我们可以将它们定位到艾泽拉斯的几乎任何地点。我们可以用它们来收集击败燃烧军团所需的资源。"
D.Strings[80973]="现在，让我们来讨论一下从何处着手最好吧。"
D.Strings[80974]="你受伤了吗？"
D.Strings[80975]="感谢圣光，我总算找到你了！请稍等一下，勇士！"
D.Strings[80976]="是大领主提里奥派我来找你的。他要立刻见你！"
D.Strings[80977]="肯瑞托是来帮忙的！等我完全实体化之后，就会帮你关闭裂隙。如果我能活下来，还会给你一些好东西！"
D.Strings[80978]="萨格拉斯派人来对付你了！"
D.Strings[80979]="我高估了自己的力量。死亡之翼陨落后，所有的龙——包括守护巨龙——都衰弱了许多。"
D.Strings[80980]="祖父是我们当中唯一保留了魔力的巨龙。你真要让他把力量都用在这个潮汐之石上吗？"
D.Strings[80981]="我的守护者被击溃了。我们需要援助。"
D.Strings[80982]="丝黛拉苟萨，帮我最后一次吧。你的弟弟妹妹们需要你的帮助。"
D.Strings[80983]="再见，祖父。"
D.Strings[80984]="回头见，小星星。"
D.Strings[80985]="啊，就是那个玩意儿！"
D.Strings[80986]="谢谢——自从坠毁之后，我的背就一直疼得要命。"
D.Strings[80987]="这玩意儿不会成瘾吧？"
D.Strings[80988]="我欠你一条命——米希卡也是！"
D.Strings[80989]="嗷，我讨厌打针！可……这感觉真不错。"
D.Strings[80990]="我又可以打上一整天了，放马过来吧！"
D.Strings[80991]="他们又进攻了？请把我的孩子带回来，年轻人。"
D.Strings[80992]="我可怜的孩子们呐。你们一个都不能死。"
D.Strings[80993]="永夜降临了……"
D.Strings[80994]="我们会再次崛起的。"
D.Strings[80995]="我死也要拖着你一起死！"
D.Strings[80996]="我会让你臣服的。"
D.Strings[80997]="这是我先找到的！"
D.Strings[80998]="回来！它是我的……我的！"
D.Strings[80999]="别看我！"
D.Strings[81000]="不……不！我还是渴。我还要更多！"
D.Strings[81001]="跪下，贱民！"
D.Strings[81002]="这不可能！我有……"
D.Strings[81003]="这算什么？农夫来跪拜他们的王子吗？"
D.Strings[81004]="你们这群老鼠不配碰我的长袍！"
D.Strings[81005]="我需要……更多……力量！"
D.Strings[81006]="对……对！！！"
D.Strings[81007]="让我们看看你是不是真的有这个资格。来吧，证明你是圣光的勇士。"
D.Strings[81008]="我斩杀过数千邪魔。没有哪个黑暗生物能够抵挡灰烬使者。"
D.Strings[81009]="不……我被我自己的儿子……背叛……谋杀。"
D.Strings[81010]="啊……我们恐怕要失去他了。我找到他时，他已经非常虚弱了。抱上他，带他去见塞纳苟斯吧。"
D.Strings[81011]="谢谢你，$c。我会好起来的。"
D.Strings[81012]="你先走吧，剩下的路我一个人就行。"
D.Strings[81013]="<咳咳>我很好。"
D.Strings[81014]="勇士，追随大领主的精神！我们要守住这个地方！"
D.Strings[81015]="我们得在更多恶魔涌来之前离开这里。快，大领主就在神殿外面。"
D.Strings[81016]="雷诺！我的儿子……看在圣光份上……扶我起来！"
D.Strings[81017]="圣光已死。"
D.Strings[81018]="你比我想象的还要强大。来吧。"
D.Strings[81019]="起来吧，兄弟。醒醒。"
D.Strings[81020]="不！你不能也……"
D.Strings[81021]="你只是个胆小鬼罢了。"
D.Strings[81022]="要是了解军团的力量，你也会的。加入我们。"
D.Strings[81023]="休想！你和你的新主子都要死在我的战刃下。"
D.Strings[81024]="我的酒只会供给艾萨拉女王！"
D.Strings[81025]="陌生人！你能帮帮我们吗？这些蠢货都不肯相信我。"
D.Strings[81026]="正在脱离"
D.Strings[81027]="可是，她保证过……"
D.Strings[81028]="我说我能酿出比他们更好的酒，可他们都嘲笑我。我告诉他们我可以酿出让查丽妮夫人赞不绝口的酒，没准还能获得女王陛下的青睐。"
D.Strings[81029]="吃了它！"
D.Strings[81030]="好极了！让他们来吧！"
D.Strings[81031]="你真的认为自己有这个资格？"
D.Strings[81032]="只有纯洁的人才能拿起灰烬使者。你这是在浪费时间！"
D.Strings[81033]="行了行了，瑟里耶克。或许这就是灰烬使者所提到的天命之人？"
D.Strings[81034]="别再胡扯了。让我们来战斗吧！"
D.Strings[81035]="够了。如果你真的配得上灰烬使者……"
D.Strings[81036]="那就证明给我看。"
D.Strings[81037]="女王和她的主人要有新奴隶了。"
D.Strings[81038]="你，你看着不像水手，但也凑合了。"
D.Strings[81039]="我要用法术奴役你。"
D.Strings[81040]="你不该来的，为了女王，去死吧。"
D.Strings[81041]="尝了我的毒液，你就将属于我。"
D.Strings[81042]="女王和她恶魔朋友的新祭品。"
D.Strings[81043]="我的毒药见效快，时效长。"
D.Strings[81044]="别怕，我稀释了毒液，乖乖地跟我合作吧。"
D.Strings[81045]="只要我扭曲的灵魂还盘踞在灰烬使者中，你就休想得到它！"
D.Strings[81046]="我要敲碎你的骨头，吸干你的法力！！"
D.Strings[81047]="我……我……"
D.Strings[81048]="圣光在上……真的是你。"
D.Strings[81049]="什么？这不是你该来的地方！"
D.Strings[81050]="你有着纯洁的心灵和高贵的灵魂。你就是灰烬使者要找的那个人。"
D.Strings[81051]="跟我来。灰烬使者在等着你。"
D.Strings[81052]="我要踩扁你，小鱼。"
D.Strings[81053]="为了欧逊努斯王子！"
D.Strings[81054]="我要淹死你。"
D.Strings[81055]="拿起这把剑，迎接你的命运吧，勇士。你就是……灰烬使者。"
D.Strings[81056]="我不相信堕夜精灵……"
D.Strings[81057]="但似乎别无选择了。"
D.Strings[81058]="我只是想帮忙，尊敬的巨龙。"
D.Strings[81059]="好好使用这些雏龙。但你要敢骗我，就等着承受巨龙的怒火吧。"
D.Strings[81060]="我曾是个精灵贵族，尊敬的巨龙。我是有廉耻的。"
D.Strings[81061]="你总是这么淘气。是时候给你点教训了。"
D.Strings[81062]="为我报仇，孩子们！"
D.Strings[81063]="我知道你的来意，小家伙……"
D.Strings[81064]="不……你休想……得到它。"
D.Strings[81065]="请……帮帮……"
D.Strings[81066]="你们这些傲慢的凡人，在我的烈焰中燃烧吧！"
D.Strings[81067]="我还会回来的！"
D.Strings[81068]="啊，圣光最伟大的勇士来寻找神圣的灰烬使者，顺便消灭我们恶魔了。"
D.Strings[81069]="我一直在等你，圣骑士。认命吧，我要抽出你的灵魂，占据你的躯体。"
D.Strings[81070]="我们掩护你，勇士！"
D.Strings[81071]="圣光总能战胜黑暗。"
D.Strings[81072]="宠物们，焚灭万物，只留灰烬。"
D.Strings[81073]="可以……吗？"
D.Strings[81074]="你的懦弱已经暴露无遗了，马瑞斯。要想打败敌人，我们就得先了解他们的极限在哪里。"
D.Strings[81075]="就算你不召唤，这里的恶魔也够我们杀的了。"
D.Strings[81076]="太大了！太大了！杀了它！"
D.Strings[81077]="下一次，我得记得准备好一块灵魂石。"
D.Strings[81078]="时机未到，我的朋友。时机未到。"
D.Strings[81079]="激活"
D.Strings[81080]="军团已经选出了他们的勇士！"
D.Strings[81081]="这里不欢迎你！"
D.Strings[81082]="为了神王！"
D.Strings[81083]="阿格拉玛之盾属于神王！"
D.Strings[81084]="神王要你死！"
D.Strings[81085]="你没有资格参加试炼！神王万岁！"
D.Strings[81086]="谁都没资格挑战神王！"
D.Strings[81087]="$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TINTERFACE\\ENCOUNTERJOURNAL\\UI-EJ-BOSS-Balnazzar.blp:50:80|t$b[巴纳扎尔]你们真以为自己是我的对手？我无穷无尽的恶魔卫士都能杀光你们。"
D.Strings[81088]="$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TINTERFACE\\ENCOUNTERJOURNAL\\UI-EJ-BOSS-Balnazzar.blp:50:80|t$b[巴纳扎尔]表现不错……但还不够。地狱火，碾碎他们。"
D.Strings[81089]="够了。那把该死的剑别想再逞威风了！你……死……定了！"
D.Strings[81090]="哈哈！！我已经吸收了兄弟们的鲜血，现在我有足够的力量摧毁你和神王了！"
D.Strings[81091]="$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TINTERFACE\\ENCOUNTERJOURNAL\\UI-EJ-BOSS-COMMANDER SARANNIS.blp:50:80|t$b[女伯爵莉亚德琳]英雄，我们就在你身后的悬崖上！"
D.Strings[81092]="祈祷"
D.Strings[81093]="你在破碎海滩的事迹已经传开了。灰烬使者……燃烧军团必将望风而逃。"
D.Strings[81094]="燃烧的军团的兵力无穷无尽。如果我们要阻止他们的进攻，就得从源头——萨格拉斯之墓掐断他们的兵力。"
D.Strings[81095]="很久之前，泰坦使用名为创世之柱的强大工具创造了艾泽拉斯。要想永久封印燃烧军团的进入我们世界的传送门，这些创世之柱就是关键。"
D.Strings[81096]="我们已经确定了其中一根创世之柱——高戈奈斯潮汐之石的位置。它就位于古老岛屿阿苏纳的某处。我要你不择手段去得到它。"
D.Strings[81097]="艾格文秘密建造了这座大厅，作为抵御燃烧军团的某种手段。我们必须发掘出它的秘密，才能将它利用起来。"
D.Strings[81098]="你召唤我来这里做什么，小鬼？"
D.Strings[81099]="我的仆从！很高兴你能成功。是时候让我的老主人为破坏契约而付出代价了。你做好面对他的准备了吗？"
D.Strings[81100]="啊……我的“前”主人。仆从！杀了它！"
D.Strings[81101]="你输了，“主人”！现在，该谁说了算？"
D.Strings[81102]="你要为你的背叛付出代价！"
D.Strings[81103]="当然。如果提里奥在召唤我们，那一定很重要。"
D.Strings[81104]="跟我来，勇士。让我带你前往圣光之愿大殿，引荐你加入白银之手骑士团。"
D.Strings[81105]="对！对！黑色的羽毛，用来做见不得光的事！"
D.Strings[81106]="你好，$c。欢迎你前来帮忙。"
D.Strings[81107]="对！对！很好！这些角中流淌的诅咒能量对一切邪恶……呃……不那么道德的仪式都极为珍贵。"
D.Strings[81108]="干得好，我的仆从！每找到一根手指，我就给你一个橄榄。"
D.Strings[81109]="请跟我来。我准备好继续我们的任务了。"
D.Strings[81110]="给这个小家伙让条路出来！"
D.Strings[81111]="到仪式现场来拿你的奖赏吧。"
D.Strings[81112]="大法师卡德加，你能将其中一座传送门定位到圣光之愿礼拜堂吗？"
D.Strings[81113]="我以前听说过玛法里奥的名字。他是塞纳留斯的“alora thero-shan”，即最受钟爱的首徒。"
D.Strings[81114]="我明白你很着急。只要你肯帮我们，我们也会帮助你的。"
D.Strings[81115]="我们中的许多人都在兽穴中沉睡，守护着翡翠梦境。$B$B大德鲁伊也是其中之一。我只能祈祷我们的营救还不算太迟。"
D.Strings[81116]="熊怪是残暴又强大的生物。除了暴力，没有什么能阻止他们。"
D.Strings[81117]="你好，旅行者！$B$B通常，我都会邀请你到这片洒满阳光的林地里坐坐，并用熟透的浆果和被月光照耀过的清澈溪水待客。不幸的是，眼下我们遭到了袭击！"
D.Strings[81118]="只要你相信，你就能成功！"
D.Strings[81119]="坚持住，特诺。嘘，省点力气。别死在我面前！"
D.Strings[81120]="利爪德鲁伊们，不要动摇！我们必须夺回兽穴！"
D.Strings[81121]="我不像你，我没有接受过任何了不起的德鲁伊训练，但我会用友谊的力量治好特诺！"
D.Strings[81122]="塞纳留斯，我的导师……$b$b什么样的邪恶力量能支配得了他？"
D.Strings[81123]="翡翠梦境中弥漫着黑暗……"
D.Strings[81124]="如果你愿意的话，我可以带你飞回圣光之愿大殿，英雄。"
D.Strings[81125]="我想要返回圣光之愿大殿。"
D.Strings[81126]="我醒了，我醒了……"
D.Strings[81127]="这个世界是真实的吗？或者说梦境才是真实的？"
D.Strings[81128]="我睡得很好，但我的梦境却很可怕。"
D.Strings[81129]="我的梦境感觉很奇怪。我担心翡翠梦境出了什么问题。"
D.Strings[81130]="我在梦境中游历到了远方。非常非常遥远的地方……"
D.Strings[81131]="我在梦境中感觉到了某种黑暗的存在。"
D.Strings[81132]="我的德鲁伊们还被困在翡翠梦境中无法醒来。"
D.Strings[81133]="干掉这些恶魔就能夺回灰烬使者了。无论结果如何，我们的家人都会记住，我们曾为世界的自由与安全而浴血奋战过。"
D.Strings[81134]="我的梦境被阴影占领了。当我醒来时，却发现那些阴影已经蔓延到了我们的世界。"
D.Strings[81135]="来吧，勇士，别让那些恶魔打垮我们！"
D.Strings[81136]="你必须快一点……我、我们没有多少时间了！"
D.Strings[81137]="这都是你害的，法罗迪斯。"
D.Strings[81138]="他……他……来、来了……"
D.Strings[81139]="我们真不该抛弃艾露恩的怀抱，寻求虚荣的魔法！"
D.Strings[81140]="去解决这个……"
D.Strings[81141]="保持警惕。那头龙的一举一动我都要知道。"
D.Strings[81142]="呆在这儿。鉴于上次发生的事，我们不会再让你进入纳萨拉斯了。"
D.Strings[81143]="请你们原谅我，萨德斯。"
D.Strings[81144]="你撕裂了我们的家园，害得我们无法安息。"
D.Strings[81145]="一万个精灵就这样被诅咒了一万年。这都是因为你那愚蠢的盟约和拙劣的政治游戏。"
D.Strings[81146]="我该怎么补偿你们呢？"
D.Strings[81147]="我觉得你什么也做不了，殿下。"
D.Strings[81148]="失败者。"
D.Strings[81149]="谋杀犯。"
D.Strings[81150]="屠夫。"
D.Strings[81151]="住手！别说了，求求你！"
D.Strings[81152]="如果你真想见法罗迪斯王子的话，我可以送你去。"
D.Strings[81153]="如果有机会的话，帮我啐他一口。"
D.Strings[81154]="传承大德鲁伊派我来找你。你愿意帮我救治石化的助祭吗？"
D.Strings[81155]="我来帮你开路，但小心点，我感到下方有股强大的魔力。"
D.Strings[81156]="这只是个……开始。"
D.Strings[81157]="我们不再是德鲁伊的囚犯了。这世界即将属于我们！"
D.Strings[81158]="请原谅我的侍从。他们的无礼并不是针对你的……而是针对我。"
D.Strings[81159]="阿苏纳曾是精灵文明的中心之一。我的人民欣欣向荣。而现在，他们都受到了诅咒。$b$b大部分人都不愿意看我一眼。$b$b他们都是我旧日的伤疤。是我可耻的印记。"
D.Strings[81160]="这太困难了。我无法直视子民的眼睛，向他们解释我的行为。$b$b我应该回到我那孤零零的宫殿去。至少我的卫兵们都会忽视我的存在。"
D.Strings[81161]="我马上就去塞纳留斯林地，英雄。感谢你的帮助。"
D.Strings[81162]="小心点。$n来了。"
D.Strings[81163]="杀了他们，马力诺斯！"
D.Strings[81164]="我诅咒了我的子民。我给我们世代安居的家园带来了灭顶之灾。$b$b是我害死了他们。$b$b因为我干的蠢事，我的人民在死后也不得安息。我的失败让他们变成这种不人不鬼的模样。"
D.Strings[81165]="等你死后，我要吞掉你的灵魂！"
D.Strings[81166]="我是个糟糕的领袖。我有眼无珠，为我的人民选择了错误的道路。我……$b$b……我没法说得更详细了。给我一点时间，$n。我相信等到合适的时机，一切都会真相大白的。"
D.Strings[81167]="让潮水冲走你……"
D.Strings[81168]="你根本不是我们的对手！"
D.Strings[81169]="没有尤特纳的祝福，谁都别想进去。"
D.Strings[81170]="要是没有尤特纳祝福就进入阿格拉玛的宝库，你肯定会死的。"
D.Strings[81171]="我刚抵达学院入口，就看到那两个纳迦，还有你。"
D.Strings[81172]="为了阿苏纳！"
D.Strings[81173]="法罗迪斯！我的大忠臣。真是好久不见。"
D.Strings[81174]="那个声音……"
D.Strings[81175]="抱歉，你肯定认不出我了。"
D.Strings[81176]="我们已经吞噬了无数世界。你们的世界也不会例外。"
D.Strings[81177]="这样好些了吗？"
D.Strings[81178]="艾萨拉女王……你……你是纳迦的首领？"
D.Strings[81179]="可怜、愚蠢的法罗迪斯。你忘了吗？一万年前，我就粉碎过你的叛乱。还记得那时你是多么无力吗？"
D.Strings[81180]="为了解除人民的诅咒……获得救赎、保护传承……"
D.Strings[81181]="阿苏纳的人民是骄傲的人民，我们永远不会跪拜你的恶魔盟友，巫婆。"
D.Strings[81182]="哈哈哈哈哈……我的怒火即将降临。"
D.Strings[81183]="伊利丹的灵魂就在扭曲虚空中。我们必须回到他身边。"
D.Strings[81184]="我有很多事情要告诉你，但时间有限。我能说多少是多少，剩下的你得在回去之后再想办法打听。"
D.Strings[81185]="我准备好了，伊利丹。"
D.Strings[81186]="你有什么酒要请我尝吗？"
D.Strings[81187]="播种"
D.Strings[81188]="看看周围，你看到了什么？足以覆盖整个天空的无数世界。"
D.Strings[81189]="这就是数千年前，燃烧军团尚未在宇宙中肆虐时的景象。"
D.Strings[81190]="你手中的神器非常强大，足以毁灭燃烧军团。"
D.Strings[81191]="你和伊利达雷必须去黑鸦堡垒抢回我的尸体，否则就来不及了。"
D.Strings[81192]="我们没时间了。你以后一定要想办法再来一次。但现在，趁燃烧军团还没发现我们在这里之前，快走吧。"
D.Strings[81193]="我……我很抱歉。"
D.Strings[81194]="我们无处不在……你躲不掉的！"
D.Strings[81195]="我们又见面了，$n。"
D.Strings[81196]="你需要什么，尊敬的大领主阁下？是哪位少女身陷困境了吗？"
D.Strings[81197]="你带来了什么货物？"
D.Strings[81198]="我要转达任务指令。"
D.Strings[81199]="为什么，萨德斯？你们为什么要来帮我？"
D.Strings[81200]="我以为你们都看不起我。"
D.Strings[81201]="我们都知道了。"
D.Strings[81202]="任何有勇气反抗女王的精灵都值得追随。"
D.Strings[81203]="守夜人决定重归你的麾下，王子殿下。"
D.Strings[81204]="已经那么久了，你能回来真好，萨德斯。"
D.Strings[81205]="对。督军帕杰什带着它逃进了前方的传送门。"
D.Strings[81206]="一个陌生人？但愿$g他:她;是个刺客，总算有人来干掉那个王子了！"
D.Strings[81207]="希望如此。"
D.Strings[81208]="沦为黑暗的猎物吧！"
D.Strings[81209]="你的痛苦永无止境！"
D.Strings[81210]="让梦魇吞噬你！"
D.Strings[81211]="欢迎来到洛拉希尔，这里是德鲁伊的圣地。虽然这片森林已经非常古老，但它的灵魂还记得我。"
D.Strings[81212]="如果你想离开，只要告诉我一声就行。我对这片森林的了解无人能及。"
D.Strings[81213]="这森林里的每一步都会唤醒珍贵的记忆。"
D.Strings[81214]="几百年前，初代德鲁伊将这里塑造成了翡翠梦境的翻版。"
D.Strings[81215]="这只是个回响，但瓦尔莎拉是世界上最接近梦境的地方。"
D.Strings[81216]="做好准备，英雄。我们已经靠近了塞纳留斯林地。"
D.Strings[81217]="我们应该在这位森林之神面前恭谨肃立。"
D.Strings[81218]="他会带我们找艾露恩之泪。"
D.Strings[81219]="然后，你就能去收集艾格文的其他圣物了。"
D.Strings[81220]="玛法里奥！谢天谢地，你来了！"
D.Strings[81221]="很高兴再次见到——"
D.Strings[81222]="快跟我来，出事了！"
D.Strings[81223]="他在梦境中，但醒不过来。我们叫不醒他。"
D.Strings[81224]="这是什么……腐蚀？"
D.Strings[81225]="我们——我们不知道。这是才出现的。"
D.Strings[81226]="听好了，$n。"
D.Strings[81227]="我们的任务就快完成了。$b$b我必须谢谢你让我参与你的冒险，$n。我虽然帮你找到了潮汐之石，可我觉得你为我和我的人民做的更多。"
D.Strings[81228]="我准备好了，玛法里奥。"
D.Strings[81229]="积怨纳迦！抓住他们！"
D.Strings[81230]="高戈奈斯潮汐之石……"
D.Strings[81231]="它这种四分五裂的样子恐怕对你没什么用处。"
D.Strings[81232]="我可以修复它，作为我给你的最后礼物。"
D.Strings[81233]="为了保卫家园而光荣战死……这是每一个真正的战士都渴望的命运。"
D.Strings[81234]="都集合，你们这些狗杂种。你们想让这个魁梧的巨人把你们的财富都拖进海底里去吗？"
D.Strings[81235]="来吧，小伙子们！杀了那个大家伙，我们就能离开了。"
D.Strings[81236]="都加把劲儿！我可不想被吃掉。"
D.Strings[81237]="就这样！再来一轮齐射，打烂那个家伙的下巴。"
D.Strings[81238]="坚持住，干掉那个家伙，否则它会把你们都给吃了的。"
D.Strings[81239]="干得好，伙计们！你们救了你们亲爱的船长并且——等等……你们要去哪儿？"
D.Strings[81240]="鲜血与雷鸣，你总算来了！我们必须立刻谈谈，勇士。"
D.Strings[81241]="萨鲁法尔要立刻见你。"
D.Strings[81242]="卡德加，你能将这座传送门定位到奥格瑞玛吗？"
D.Strings[81243]="我跟你走，勇士，别让萨鲁法尔久等了。"
D.Strings[81244]="卡德加，老朋友！我不想打扰你，可我必须立刻和$n谈谈。"
D.Strings[81245]="铁炉堡的麦格尼国王要立刻见你。"
D.Strings[81246]="卡德加，你能将这座传送门定位到暴风城吗？"
D.Strings[81247]="我跟你走，勇士，别让麦格尼国王久等了。"
D.Strings[81248]="摧毁武器"
D.Strings[81249]="冥狱深渊……我们要尽快找到出路。"
D.Strings[81250]="海草伪装"
D.Strings[81251]="你不知道自己在做什么，愚蠢的凡人。"
D.Strings[81252]="你、你在……做什么？！"
D.Strings[81253]="你……你竟敢打扰我的工作？！"
D.Strings[81254]="凡人，你竟敢嘲笑死亡？"
D.Strings[81255]="我就指望你和我的幼龙来保护我了，$n。$b$b我将要举行的仪式很复杂，需要一些时间。它肯定会引起阿苏纳最讨厌的居民们的注意。"
D.Strings[81256]="我会保护你的，塞纳苟斯。"
D.Strings[81257]="这都是法罗迪斯害的！"
D.Strings[81258]="女王为什么要抛弃我们？"
D.Strings[81259]="加入我们，直到永远……"
D.Strings[81260]="愿艾萨拉宽恕我！"
D.Strings[81261]="我们准备好了。让它来吧！"
D.Strings[81262]="马瑞斯，你这个傲慢的饭桶，你差点害死我。"
D.Strings[81263]="我……快要……坚持……不住了。"
D.Strings[81264]="这个……恶魔……太强大了。我关不住它多久，我们……的力量还不足以……单独击败它。"
D.Strings[81265]="目前一切顺利。报告一下情况吧。"
D.Strings[81266]="乌瑞恩国王和舰队几小时前就到了。报告说有激烈的战斗。"
D.Strings[81267]="我们是这片神圣森林与想要将其夷为平地的恶魔军团之前唯一的防线了。"
D.Strings[81268]="要不是大德鲁伊瑟法瑞斯·夜鬃，我们恐怕就都没命了。$b$b我们的人数大大少于敌人，而且还有许多伤员，是瑟法瑞斯不顾自身安危地奋勇拼杀，才保住了我们的性命。$b$b大德鲁伊在战斗中受了伤，尽管我们想要为他包扎伤口，可他却坚持说来不及了。$b$b我最后一次看见他时，他是往悬崖上的升月洞穴去了。"
D.Strings[81269]="玛法里奥·怒风已经派我去找过游荡大德鲁伊了。"
D.Strings[81270]="敌人……太多了……"
D.Strings[81271]="有敌人从礁湖那边过来！"
D.Strings[81272]="他们不是敌人，小星星。"
D.Strings[81273]="法罗迪斯，老朋友。是你吗？"
D.Strings[81274]="我们是来帮忙的。纳迦跟踪了我们。"
D.Strings[81275]="潮汐之石在召唤他们，别让他们靠近。"
D.Strings[81276]="英雄们！有东西从身后袭击我！"
D.Strings[81277]="有人吗，快来人啊，保护塞纳苟斯！"
D.Strings[81278]="潮汐之石……如此强大……"
D.Strings[81279]="你……鲁纳斯！你在这儿做什么？"
D.Strings[81280]="抱歉，朋友们。我只是情不自禁。"
D.Strings[81281]="兄弟姐妹们！我说的巨型法力水晶就在上面的池塘里！"
D.Strings[81282]="他们攻过来了，东北部需要援军。"
D.Strings[81283]="|TInterface\\Icons\\achievement_boss_princesstheradras.blp:40|t我主人的主人已经洞悉了你的计划，巨龙。你别想拿到潮汐之石。"
D.Strings[81284]="恶魔们回来了。"
D.Strings[81285]="埃迪，不惜一切代价保护那头巨龙。"
D.Strings[81286]="遵命，王子殿下。"
D.Strings[81287]="别管潮汐之石了，兄弟们。让他们留着那块水晶吧。"
D.Strings[81288]="我们将享用这些巨龙！"
D.Strings[81289]="大德鲁伊跟随塞纳留斯本人学习了数千年。"
D.Strings[81290]="森林已经悄悄将你的到来告诉了我，年轻人。$b$b很少有外来者能进入我珍爱的林地。在此期间，请你保持敬意。"
D.Strings[81291]="这些鹰身人已经与我们和平共处了几个世纪。$b$b是什么让他们变得如此具有攻击性？"
D.Strings[81292]="蠢货！这森林死定了……你们也一样！哈哈哈哈！"
D.Strings[81293]="可怜虫！你们……<咳嗽>……很快就会给我陪葬的！"
D.Strings[81294]="捅它！捅它！哈哈哈！"
D.Strings[81295]="别想抢走我们的龙！"
D.Strings[81296]="杀了它吧！"
D.Strings[81297]="看不见了……好疼……"
D.Strings[81298]="我只想……开个玩笑……"
D.Strings[81299]="梦魇将吞噬我们所有人！"
D.Strings[81300]="只剩下……痛苦……疯狂！"
D.Strings[81301]="<这头母夜刃豹的尸体刚死不久。它似乎是经过了艰苦的战斗后才伤重而死的。>"
D.Strings[81302]="让血肉化为尘土！"
D.Strings[81303]="见证我的诅咒吧！"
D.Strings[81304]="蠢货！去死吧！"
D.Strings[81305]="这是巫母的命令！"
D.Strings[81306]="拆骨剔肉！"
D.Strings[81307]="不……这不可能！"
D.Strings[81308]="这片土地……是……我们的……"
D.Strings[81309]="啊……我诅咒你！"
D.Strings[81310]="你休想……逃脱……诅咒！"
D.Strings[81311]="啊，又能呼吸了！"
D.Strings[81312]="祝福你，陌生人！"
D.Strings[81313]="你……你救了我！"
D.Strings[81314]="那些受到诅咒的人已经没时间了……我们必须尽快行动！"
D.Strings[81315]="我们已经救出了所有的人，$n。我在林地里等这你。Elen'elora-ethil。"
D.Strings[81316]="恐惧……到处都是恐惧！"
D.Strings[81317]="不……我的意志！住手！"
D.Strings[81318]="梦魇降临了！"
D.Strings[81319]="救救我！你为什么不救我？！"
D.Strings[81320]="他们在追我……他们……拦住他们！"
D.Strings[81321]="哇哈哈……哈哈哈！"
D.Strings[81322]="欢迎光临你的梦魇！"
D.Strings[81323]="很快，你就会拥抱死亡了！"
D.Strings[81324]="这片土地必将被吞噬！"
D.Strings[81325]="你休想阻止我们。我们是军团！"
D.Strings[81326]="我们的主人将吞噬……你的……灵魂……"
D.Strings[81327]="梦魇……在欢迎我……"
D.Strings[81328]="你休想……逃出……你的梦境……"
D.Strings[81329]="蠢货……这片土地已经完了……"
D.Strings[81330]="是谁竟敢打扰巴纳扎尔大人的工作？"
D.Strings[81331]="你逃不过我们的眼睛。"
D.Strings[81332]="大人还需要一点时间。以燃烧军团的名义，杀光他们！"
D.Strings[81333]="灰烬使者属于燃烧军团。所有螳臂当车的人都将葬身火海！"
D.Strings[81334]="泽鲁斯……会……阻止……你的……"
D.Strings[81335]="你要生生世世痛苦下去。"
D.Strings[81336]="不！灰烬使者……不能……"
D.Strings[81337]="$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TINTERFACE\\ENCOUNTERJOURNAL\\UI-EJ-BOSS-COMMANDER SARANNIS.blp:50:80|t$b[女伯爵莉亚德琳]圣光在上，提里奥还活着！"
D.Strings[81338]="$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TINTERFACE\\ENCOUNTERJOURNAL\\UI-EJ-BOSS-COMMANDER SARANNIS.blp:50:80|t$b[女伯爵莉亚德琳]我们得到前面去侦察一下，看看能不能找到提里奥的踪迹。我们一起去！"
D.Strings[81339]="$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TINTERFACE\\ENCOUNTERJOURNAL\\UI-EJ-BOSS-GRAND CHAMPIONS-ALLIANCE.blp:50:80|t$b[玛克斯韦尔·泰罗索斯男爵]我们找到他了，勇士！提里奥还活着！"
D.Strings[81340]="$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TINTERFACE\\ENCOUNTERJOURNAL\\UI-EJ-BOSS-COMMANDER SARANNIS.blp:50:80|t$b[女伯爵莉亚德琳]我们找到他了，勇士！提里奥还活着！"
D.Strings[81341]="提里奥有话对你说，勇士。灰烬使者不见了！"
D.Strings[81342]="$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TINTERFACE\\ENCOUNTERJOURNAL\\UI-EJ-BOSS-COMMANDER SARANNIS.blp:50:80|t$b[女伯爵莉亚德琳]勇士，到前面去找找提里奥。我们掩护你前进！"
D.Strings[81343]="$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TINTERFACE\\ENCOUNTERJOURNAL\\UI-EJ-BOSS-COMMANDER SARANNIS.blp:50:80|t$b[女伯爵莉亚德琳]灰烬使者就在前面的裂隙里——我们得挡住这些恶魔一段时间，好让人穿过他们的防线！"
D.Strings[81344]="战斗任务来了，让我们证明勇者号不是浪得虚名。"
D.Strings[81345]="这么久了，连只海鸥都没看到。"
D.Strings[81346]="空气中弥漫着邪气，但我们要迎难而上。"
D.Strings[81347]="面对我的怒火吧。"
D.Strings[81348]="永恒的痛苦。"
D.Strings[81349]="你可以在东南边找到那些巨人。那里有几条路可以进入他们的竞技场。祝你好运。"
D.Strings[81350]="该死，帮帮我，不能让他们打扰大人！"
D.Strings[81351]="谢天谢地……你成功了。灰烬使者回来了！"
D.Strings[81352]="这把剑是如此闪耀……即使在冰冠堡垒顶层时，我也没见过它如此强大。那就这样吧。"
D.Strings[81353]="所有的圣骑士们，听我说。灰烬使者已经选定了它的继任者。"
D.Strings[81354]="我准备好了。送我去诺达尼尔圣泉吧。"
D.Strings[81355]="我感觉已经有能力完成这个任务了，$n，但我们在这里是无法完成它的。我必须先将潮汐之石的碎片带去西边的诺达尼尔圣泉。$b$b当然，我的幼龙会保护我的……可如果你能随我一起去的话就更好了。跳到我背上来吧，我来带你过去。这可比你用那小短腿跑要快多了。"
D.Strings[81356]="这些纳迦是最近才侵入阿苏纳的。他们想要解放法罗迪斯王子。\n\n毫无疑问，和你一样，他们和艾萨拉女王也在寻找高戈奈斯潮汐之石。只有王子知道它的下落。"
D.Strings[81357]="不，求求你！住手！"
D.Strings[81358]="你做好与德克加尔作战的准备了吗？"
D.Strings[81359]="让我们炸翻这些维库人吧！"
D.Strings[81360]="萨格拉斯赐予我们力量。"
D.Strings[81361]="感受邪能与烈焰之神的怒火吧！"
D.Strings[81362]="诸界的毁灭者赐予我力量。你死到临头了，凡人！"
D.Strings[81363]="你的靴子！对……我们拿到了！"
D.Strings[81364]="打他的脚！脚！"
D.Strings[81365]="请原谅，尊敬的议会和各位来宾。我得立刻跟$n谈谈。"
D.Strings[81366]="跟我来，朋友。这不会耽误你太多时间的，我保证。"
D.Strings[81367]="这个装置里充满了强大的魔力。或许它是通过大厅的墙壁与这些画像联系在一起的？"
D.Strings[81368]="圣光在上，那是什么？"
D.Strings[81369]="似乎是一个巨型邪能源头。我从没见过类似的东西。"
D.Strings[81370]="我们得处理好提里奥的伤势，才能带他离开这里。大领主，你必须前进，夺回灰烬使者！"
D.Strings[81371]="我们是风暴的主宰！"
D.Strings[81372]="你失败了。托林尼尔完了！"
D.Strings[81373]="你不配得到托林尼尔的力量！"
D.Strings[81374]="这些龙属于斯科瓦尔德，爬虫！"
D.Strings[81375]="跪下求饶吧！"
D.Strings[81376]="匍匐在神王脚下吧！"
D.Strings[81377]="我没有时间闲聊了。超乎想象的灭顶之灾正在逼近，而我们是唯一能够阻挡它的人。"
D.Strings[81378]="您有什么吩咐，大德鲁伊？我们周围充斥着死亡和恐怖……"
D.Strings[81379]="你将灰烬使者从地下拔了出来，高高举起。过了一会儿，巴纳扎尔出现在了你面前。"
D.Strings[81380]="别让他们再拿我去喂狗了……"
D.Strings[81381]="我生前是个英勇的战士……我不属于这里。"
D.Strings[81382]="赫利拉！听我说！请……给我自由。"
D.Strings[81383]="完了……我们都完了。"
D.Strings[81384]="赫利拉，送我前往永恒战场吧。我有这个资格！"
D.Strings[81385]="如果我们不能赶快行动，这座山谷就会被攻破。德鲁伊们，亮出你们的利爪吧！"
D.Strings[81386]="你休想赢得这场战斗！"
D.Strings[81387]="我要晋升了！"
D.Strings[81388]="海拉，看看我的力量。我有这资格！"
D.Strings[81389]="难以置信。有了灰烬使者和你的力量带领，我们或许有机会击退燃烧军团。"
D.Strings[81390]="我们的人就在外面，等着将我们送回达拉然。我们得赶快回达拉然，否则就迟了！"
D.Strings[81391]="[纳萨诺斯和他的游侠们走开了。]"
D.Strings[81392]="联盟舰队，直线前进！到海滩上去！大家坚持住，艰苦的战斗还在后头呢！"
D.Strings[81393]="小偷小摸是不可容忍的行为，奴隶。"
D.Strings[81394]="[纳萨诺斯跳下悬崖，走了过来。]"
D.Strings[81395]="山里没有女王的踪迹。这里有什么呢？"
D.Strings[81396]="这是她的……"
D.Strings[81397]="快吃！我们还要去杀那个巫婆呢！"
D.Strings[81398]="你休想阻止我狩猎！"
D.Strings[81399]="白痴矮人。把他的脑袋送去营地！"
D.Strings[81400]="他不是……大德鲁伊已经……快逃命吧……快跑！"
D.Strings[81401]="我们将女王送上了小艇，可她不要人护送，却让我们留下战斗。"
D.Strings[81402]="我猜？她应该登上了海滩，然后步行了吧。"
D.Strings[81403]="[塔特赛尔将她所知道的都告诉了你，然后逃跑了。]"
D.Strings[81404]="我再也不会引颈待戮了！"
D.Strings[81405]="这次你们别想再拿我去喂狗了！"
D.Strings[81406]="赫利拉！你休想永远关住我！我会获得自由的！"
D.Strings[81407]="这美妙的疯狂……我为什么要抗拒它呢？"
D.Strings[81408]="你无处可藏了。"
D.Strings[81409]="有东西将这些熊怪都逼疯了。在我的记忆中，他们从来没有这样疯狂进攻过。"
D.Strings[81410]="利爪德鲁伊的内心从不动摇。我们是最坚忍的人。"
D.Strings[81411]="大德鲁伊钢爪仍然在下面的兽穴里，和其他人在一起。我们必须尽快救出他们。"
D.Strings[81412]="我们必须坚持住，我知道我们一定可以熬过去的。"
D.Strings[81413]="只要再来……一场……战斗……"
D.Strings[81414]="伪装被拆穿了。现在你去死吧！"
D.Strings[81415]="我们注定要永远留在这里了。"
D.Strings[81416]="已经没有光明了……只有黑暗。"
D.Strings[81417]="我们是燃烧军团。"
D.Strings[81418]="你不知道吗？这里是冥狱深渊，$r……现在，你的灵魂已经属于赫利拉。没有这位女神的同意，谁都别想离开这里。$b$b我听到传言说，在永恒战场上向赫利拉证明了自己力量的亡者才可以离开。$b$b但那头畜生高姆把守着道路，所以没有人能见到赫利拉。$b$b我无数次想要从它身边溜过去，可结局都是一样……被撕碎然后丢去喂狗。"
D.Strings[81419]="一定有办法的。"
D.Strings[81420]="感受你们体内流淌的力量吧，仆人们！"
D.Strings[81421]="我们必须重新集结，赶到我们的女王身边去。寻找阿格拉玛之盾的任务就交给你了。"
D.Strings[81422]="灰烬使者显然已经声名远播。我们在这里都能听到恶魔痛苦的哀嚎。"
D.Strings[81423]="我们在伊利达雷哨所汇合。"
D.Strings[81424]="哈哈哈……看来我们有新的挑战者了。已经有几百年没有灵魂来到我的王座前了。"
D.Strings[81425]="巴尔迪尔，去看看$n的灵魂想要什么。我正想找点乐子呢。"
D.Strings[81426]="穿过迷雾，走入黑暗，我将我的灵魂永远交给赫利拉。$b$b在你的女神面前跪下吧。"
D.Strings[81427]="我会召集剩下的血骑士，等待你的召唤。"
D.Strings[81428]="我的人正在蓝翼栖地与巨龙的子嗣商量借道的事。"
D.Strings[81429]="血须是谁？"
D.Strings[81430]="血须是赫利拉的勇士。$b$b他在战场上百战百胜，所向披靡……$b$b你是赢不了的。"
D.Strings[81431]="我们走着瞧。"
D.Strings[81432]="血……血须……血须必须……死……"
D.Strings[81433]="血须是赫利拉的勇士。$b$b他在战场上百战百胜，所向披靡……$b$b我很乐意看着他死在我的剑下。"
D.Strings[81434]="他们的灵魂是如此软弱，根本不值得我出剑。我渴望回到英灵殿。"
D.Strings[81435]="我在那里等你。"
D.Strings[81436]="我同意。"
D.Strings[81437]="杀掉马力诺斯的英雄回来了。血骑士们，致敬！"
D.Strings[81438]="这边！救命啊！"
D.Strings[81439]="一个圣骑士？在这儿？我们必须调查一下。"
D.Strings[81440]="我已经在海滩上了。"
D.Strings[81441]="别再浪费时间了，恶魔猎手。我们还有急事要处理。"
D.Strings[81442]="放弃吧！这里就是你的葬身之地。"
D.Strings[81443]="这毫无意义，为什么还要去尝试呢？"
D.Strings[81444]="这世上没有什么幸福，只有黑暗。"
D.Strings[81445]="别傻了，你是不会成功的。"
D.Strings[81446]="等待你的只有永恒的悲伤。"
D.Strings[81447]="我，伪善者、暴虐者、至邪者达格洛普，前来订约！"
D.Strings[81448]="阅读契约。"
D.Strings[81449]="用鲜血签署契约。"
D.Strings[81450]="契约开头的几行字写得巨大，运笔流畅，邪气十足，但每一句的字体都变得越来越小。上面这样写道：$b$b第一页：$b“我，签署者，以下简称为‘乙方’，在此郑重承诺，接受达格洛普·拉瓦利什·迪斯考尔·布拉特，以下简称为‘达格洛普’，所提出之条款。”"
D.Strings[81451]="翻到第二页。"
D.Strings[81452]="翻到第三页。"
D.Strings[81453]="翻到第一页。"
D.Strings[81454]="契约继续用越来越小的字体写道：$b$b第二页：$b“这些条款包括获取沙拉扎恩仪式所需的材料，以下简称为‘义务’，以及消灭、屠杀、暗杀或谋杀所有妨害履行义务及达格洛普要求的主体，不论死活。”"
D.Strings[81455]="上面字体已经几乎看不清了：$b$b第三页：$b“作为交换，达格洛普同意向乙方提供大量不具实体的邪能能源，供乙方为其所拥有的一件神器充能，以下简称为‘报酬’。\""
D.Strings[81456]="翻到第四页。"
D.Strings[81457]="第四页：$b”在完成义务之后，应当支付给乙方的上述报酬将通过第三方直接抽取的方式支付，该角色的承担者为——“$b$b下面的字体实在太小了，肉眼已经无法辨认。"
D.Strings[81458]="在赫利拉面前跪下。"
D.Strings[81459]="扎里萨尔倒下了！这怎么可能？！"
D.Strings[81460]="德鲁伊怎么会有这么强大的力量？！加瑟纳克也被杀了！"
D.Strings[81461]="谁有本事杀掉扎里萨尔？！"
D.Strings[81462]="他们杀了加瑟纳克！"
D.Strings[81463]="这个世界陷入了前所未有的黑暗。我们要努力带来新的黎明。"
D.Strings[81464]="闻闻这海风！再次出海的感觉可真好。"
D.Strings[81465]="在女神海拉面前跪下吧。"
D.Strings[81466]="我来切断与扭曲虚空的联结，保护我！"
D.Strings[81467]="我来干扰传送门。在我工作的时候，拦住那些恶魔！"
D.Strings[81468]="感谢你允许我们的加入，$n。只要是你的召唤，烈日行者一定会积极响应。"
D.Strings[81469]="我会召集剩下的烈日行者——他们肯定不会错过与你一起行动的机会的。愿圣光与你同在。"
D.Strings[81470]="$G他:她;是来找它的！"
D.Strings[81471]="你以为会这么容易吗？"
D.Strings[81472]="那是我们的宝贝，丑陋的$r！"
D.Strings[81473]="哈！抓住你了！"
D.Strings[81474]="我相信从奥格瑞玛送来的报酬跟它一点关系都没有。"
D.Strings[81475]="有个老地精说的好，\"最适合打赌的钱，就是别人的钱。”"
D.Strings[81476]="如果我们能活着回来的话。"
D.Strings[81477]="有奥格瑞玛的消息吗？"
D.Strings[81478]="这片林地里的猫头鹰正受到一只名叫血喙的凶残秃鹫的威胁。$B$B提瑞斯和我打算将那只畜生从它的巢穴里引出来。$B$B我们必须杀了它，才能恢复森林的平衡，但我们需要一切可能的帮助。"
D.Strings[81479]="你准备好了吗，提瑞斯？"
D.Strings[81480]="必须阻止那只秃鹫，劳瑞。是时候恢复这片林地的平衡了。"
D.Strings[81481]="这些小鸟是多么的珍贵啊！如果我们不帮忙的话，它们就有灭绝的危险。"
D.Strings[81482]="我会帮你击败血喙的。"
D.Strings[81483]="希尔瓦娜斯和主力舰队几个小时前就抵达了。恶魔已经淹没了整座群岛。"
D.Strings[81484]="来了？他们那么多人，怎么会这么快？"
D.Strings[81485]="我感觉我们很快就会知道了。"
D.Strings[81486]="黑水舰队，前进！我们是海盗，是大海的主人！稳住！"
D.Strings[81487]="前面是什么？"
D.Strings[81488]="看来我们有麻烦了。大麻烦。"
D.Strings[81489]="好了，部落的战士们，你们到站了，这海滩挤满了恶魔！进港，快！"
D.Strings[81490]="第三支援舰队！"
D.Strings[81491]="来的正是时候。我们本来没法打破他们的阵线，现在我们有机会了。"
D.Strings[81492]="抓住时机，吉恩！"
D.Strings[81493]="看，有人来了！"
D.Strings[81494]="噢，感谢女神！请帮帮我！$B$B我正在试验一个生长法术，结果捅出了大篓子。$B$B其中有一朵花不停生长，现在还有了自己的意志。$B$B求求你，一定要在它伤人之前阻止它！"
D.Strings[81495]="不，不，快停下！不应该是这样的！别长了！"
D.Strings[81496]="你成功了！自己去选一朵花吧，冒险者。艾露恩之吻有着非常强大的功效。"
D.Strings[81497]="冒险者，这边！"
D.Strings[81498]="陌生人，看到生长在湖岸边的那些花了吗？$B$B我们称它们为艾露恩之吻。我找遍了整座森林才找到这么一片，可它却被那个邪恶的怪物霸占了。$B$B拜托了，冒险者。我需要那些花。"
D.Strings[81499]="呸！你太丑了，根本不配成为我的藏品。还是杀了你比较好！"
D.Strings[81500]="我的藏品……它们是我的……全部……"
D.Strings[81501]="拜托，拜托……快住手！"
D.Strings[81502]="蠢货！你将倒在燃烧军团的威能之下！"
D.Strings[81503]="干得好，英雄们！继续战斗！"
D.Strings[81504]="一条裂隙已经关闭了，可还是不断有恶魔涌来。没完了吗？"
D.Strings[81505]="有我在你们身边，我们一定能打败燃烧军团。没有什么能阻挡我们！"
D.Strings[81506]="在我们说话的时候，神王的大军已经在赫达沙尔集结了。我们必须以雷霆之力，全力打击他们。\n\n你准备好离开这个地方了吗，$C？"
D.Strings[81507]="送我离开洞穴。"
D.Strings[81508]="看，兄弟。有新的挑战者过来了。"
D.Strings[81509]="让我们看看你的本事吧，勇士！做好准备！"
D.Strings[81510]="坚持住，橡叶。我知道你很疼，可求你了，一定要坚持住！"
D.Strings[81511]="困难还在前头呢，老朋友。我们开始吧！"
D.Strings[81512]="我的朋友遇到了点麻烦。一股黑暗力量深植在他体内，令他恐惧得无法动弹。$B$B我认为唯一的解决方法就是净化他的头脑，可这么做的话，我们就要直面他的梦魇。$B$B我没法独自击败这股邪恶力量。你愿意帮我吗？"
D.Strings[81513]="我愿意帮忙。让我们开始吧。"
D.Strings[81514]="黑暗，来吧！"
D.Strings[81515]="这就对了，橡叶。谢谢你，冒险者。他的自制力看来已经恢复了。"
D.Strings[81516]="我们成功了！你感觉如何，老朋友？"
D.Strings[81517]="啊，为什么没有效果？我的友谊之力应该能治好一切创伤的！"
D.Strings[81518]="噢，你好啊！$B$B我这位可怜的朋友被狼袭击了，我正想帮他恢复健康！$B$B我的这个法术出了点小问题，所以可能还需要几分钟才能生效。$B$B我想那些可恶的掠食者或许还在附近。在我的法术完成之前，能请你帮忙挡住它们吗？"
D.Strings[81519]="好的，我会保护你的。"
D.Strings[81520]="呃！小心！保护我，英雄！"
D.Strings[81521]="看，我亲爱的森林朋友得救了！"
D.Strings[81522]="勇士，看来他想让我们跟他走！"
D.Strings[81523]="%s对你鞠了一躬。"
D.Strings[81524]="%s指了指巢穴里的箱子，似乎是想让你收下它。"
D.Strings[81525]="多么可爱的小房子！我要住下来，直到他彻底痊愈为止。谢谢你，英雄。"
D.Strings[81526]="别担心，布里姆比尔。每一棵年轻的小树苗都必须踏入真正的世界。你会没事的！"
D.Strings[81527]="啊，你好啊，旅行者！$B$B有时候，年轻的小树苗需要有人推一把才能获得信心，你明白吧？$B$B年轻的布里姆比尔已经做好了首次横穿森林的一切准备，但他可能还需要一点指导。$B$B你能护送他到河对岸的守护者法萨罗斯那里去吗？$B$B只要跟着布里姆比尔走就行了。他应该认识路。"
D.Strings[81528]="我会陪着布里姆比尔的。"
D.Strings[81529]="好好照顾他，冒险者！"
D.Strings[81530]="爬到墙头上，观察附近锚点的情况。"
D.Strings[81531]="点击附近的锚点，将你自己送上墙头。范围内的锚点会亮起。"
D.Strings[81532]="午安，大领主$n。我能帮你什么忙吗？"
D.Strings[81533]="你要找什么特别的东西吗，大领主？"
D.Strings[81534]="祖祖辈辈的智慧就这样展现在我们眼前。多么难得的机会！"
D.Strings[81535]="每当你取得一个重大成就，我都会记录在你的圣契上，供后人瞻仰！"
D.Strings[81536]="让我看看阿苏纳发生了什么事。"
D.Strings[81537]="为了圣光的荣耀，大领主。"
D.Strings[81538]="只要你一声令下，我就能为你召来最优秀的骑士，$n$G大人:女士;。"
D.Strings[81539]="我们先对付哪个威胁？只要你说一声，我就能帮你搞定它。"
D.Strings[81540]="我们的敌人正日益猖狂。感谢圣光，我们还有你这个领袖。"
D.Strings[81541]="你好！$b$b我是一位财宝猎人。我到处找人想告诉他们财宝的藏匿地点，因为一些“原因”我自己拿不到那些财宝。一旦我下定决心，我最终可能会出现在奇特或者平常的地方。$b$b你想要寻宝吗？"
D.Strings[81542]="我正在寻找宝藏。"
D.Strings[81543]="英雄们，快上来！这座传送门太强大了，我的魔法没法关闭它。"
D.Strings[81544]="快，激活神殿的防御来增强我的魔法！"
D.Strings[81545]="在纳萨诺斯还没回来前，快把那些火扑灭了！我可不想被他拿去喂狗。"
D.Strings[81546]="快点！趁那些该死的虾兵蟹将还没注意到我们，快把船开起来。"
D.Strings[81547]="用力锤，你们这些蠢货！我们必须按时到港。"
D.Strings[81548]="你们愿意让联盟打沉你们的船吗？快点让这艘破船开起来，这样才能证明他们的武器是多么软弱无力。"
D.Strings[81549]="纳萨诺斯委托我们将他的船修好。$b$b可这些懒骨头的动作太……等等……你听到了吗？"
D.Strings[81550]="听到什么？"
D.Strings[81551]="滚开，你这只臭螃蟹！"
D.Strings[81552]="抛光"
D.Strings[81553]="|TINTERFACE\\ICONS\\ACHIEVEMENT_CHARACTER_HUMAN_MALE.BLP:40|t我已经看出来了，我们需要先把它淬个火。把矿石放进熔炉里去。"
D.Strings[81554]="|TINTERFACE\\ICONS\\ACHIEVEMENT_CHARACTER_HUMAN_MALE.BLP:40|t现在，快，把它放到水槽里冷却。"
D.Strings[81555]="|TINTERFACE\\ICONS\\ACHIEVEMENT_CHARACTER_HUMAN_MALE.BLP:40|t看到了吗？它看起来已经好多了。再加热并冷却一次。"
D.Strings[81556]="|TINTERFACE\\ICONS\\ACHIEVEMENT_CHARACTER_HUMAN_MALE.BLP:40|t现在，把金属夹起来，放到熔炉里吸收热量。"
D.Strings[81557]="|TINTERFACE\\ICONS\\ACHIEVEMENT_CHARACTER_HUMAN_MALE.BLP:40|t现在应该够热了。接下来，我们要把金属熔炼成金属锭。"
D.Strings[81558]="|TINTERFACE\\ICONS\\ACHIEVEMENT_CHARACTER_HUMAN_MALE.BLP:40|t接下来你也知道该怎么做了吧？加热金属锭，然后将其锤打成型。"
D.Strings[81559]="|TINTERFACE\\ICONS\\ACHIEVEMENT_CHARACTER_HUMAN_MALE.BLP:40|t非常好，现在该准备焊接了。从我的工作台上拿点助熔剂。"
D.Strings[81560]="英雄，快！绝不能让埃洛苏斯进入厄运之槌！"
D.Strings[81561]="我已经来了，小崽子们。来面对我，让我们做个了断吧！"
D.Strings[81562]="锻打金属可不是什么轻松的活儿，再用点力。"
D.Strings[81563]="艾泽拉斯的圣骑士们，你们来此悼念大领主提里奥·弗丁的逝世。你们大多都视他为偶像和学习的榜样。"
D.Strings[81564]="今天，白银之手骑士团重生了！只要团结一心，我们足以击溃萨格拉斯！"
D.Strings[81565]="|TINTERFACE\\ICONS\\ACHIEVEMENT_CHARACTER_HUMAN_MALE.BLP:40|t好了，看来那块魔石已经和助熔剂发生了剧烈的反应。我们可以停手了。"
D.Strings[81566]="快来，英雄们！到我身边来，释放你们的力量！"
D.Strings[81567]="我是暗影中的猎手……"
D.Strings[81568]="狩猎仍在继续……"
D.Strings[81569]="邪恶将在我的爪下颤抖……"
D.Strings[81570]="在黑夜面前瑟瑟发抖吧！"
D.Strings[81571]="我的利爪渴望复仇！"
D.Strings[81572]="就连恶棍都会害怕潜伏在阴影中的猎手……"
D.Strings[81573]="向你致敬，大领主。"
D.Strings[81574]="你知道吗，大领主曾经一剑斩杀了五百头恶魔！"
D.Strings[81575]="我听勇士巴卡希说大领主能够死而复生。"
D.Strings[81576]="你说我能不能被选去参加下一次的外勤任务？我听说大领主会让你们留下一部分战利品！"
D.Strings[81577]="全世界的圣骑士都团结在一个屋檐下……燃烧军团毫无机会。"
D.Strings[81578]="大领主来了。敬礼！"
D.Strings[81579]="|TINTERFACE\\ICONS\\ACHIEVEMENT_CHARACTER_HUMAN_MALE.BLP:40|t我们动手吧！和以前一样，把魔石放到熔炉里去加热。"
D.Strings[81580]="|TINTERFACE\\ICONS\\ACHIEVEMENT_CHARACTER_HUMAN_MALE.BLP:40|t现在，让我们请一位肯瑞托的法师来完全冷却金属。到我店外的蛋糕架那里去看看。"
D.Strings[81581]="你们铁匠铺需要我帮忙？好吧，但每个法师都有自己的价码……而我的价码刚好是糖果。"
D.Strings[81582]="|TINTERFACE\\ICONS\\ACHIEVEMENT_CHARACTER_HUMAN_MALE.BLP:40|t快回来！我们还需要再加热并冷却金属一次。"
D.Strings[81583]="我接受你们的雇佣了。我们店里见！"
D.Strings[81584]="|TINTERFACE\\ICONS\\ACHIEVEMENT_CHARACTER_HUMAN_MALE.BLP:40|t非常好，现在让我们看看你还记不记得剩下的步骤。"
D.Strings[81585]="我会不断思考怎么改进我们的魔石锻造技术的，$n。你的训练还没有结束。"
D.Strings[81586]="我从小就住在这座山谷里……与谷地徘徊者一起狩猎，守护这座神圣的森林。$b$b看着这片我所深爱的土地……我的心中充满了悲伤。这片森林还会恢复昔日的美丽吗？"
D.Strings[81587]="看到了没有？我的蹄子轻而易举地跺碎了你的手甲！这简直不可接受。"
D.Strings[81588]="他们简直是无穷无尽……我们怎么可能打败这些萨特？"
D.Strings[81589]="让混沌降临到你们头上。"
D.Strings[81590]="摧毁邪能导管"
D.Strings[81591]="大德鲁伊月爪和他的同胞象征着最狂野的自然。在他们的地盘上，最好规矩一点，$n。"
D.Strings[81592]="这片土地的植被与我家乡的完全不同。它们中的某些与其说是植物，不如说更像是动物。"
D.Strings[81593]="只要你愿意聆听，就能从鲜花身上学到许多。"
D.Strings[81594]="放轻你的蹄子。你脚下的青草还在呼吸。"
D.Strings[81595]="铁匠铺的奥拉尔德需要定期供应的狐尾花。你这里有吗？"
D.Strings[81596]="铁匠铺的奥拉尔德需要定期供应的狐尾花熔剂。你这里有吗？"
D.Strings[81597]="圣光失败了……他们已经赢了。"
D.Strings[81598]="圣光与你同在，蒂萨。看看你的内心。"
D.Strings[81599]="你是个圣骑士——你必须坚守自己对抗黑暗的誓言。"
D.Strings[81600]="我不会放弃你的。你会逃出这里的。"
D.Strings[81601]="已经没有意义了。看看你的周围……都结束了。"
D.Strings[81602]="不，看看周围。这就是你想看到的艾泽拉斯吗？"
D.Strings[81603]="你的死神从天而降了！"
D.Strings[81604]="圣光从未放弃过你，萨缪尔。你也不应该放弃圣光。"
D.Strings[81605]="坚强点，兄弟，还没有结束。"
D.Strings[81606]="我……我能感觉到内心深处的圣光。"
D.Strings[81607]="燃烧军团休想打败我们！一有机会，我就回到营地去！"
D.Strings[81608]="你说得对。我曾发誓守卫圣光，而现在我却想要抛弃它。"
D.Strings[81609]="祝福你，英雄。我还以为自己死定了呢！"
D.Strings[81610]="我不会忘记你的恩情的！我们营地见。"
D.Strings[81611]="我就知道会有人来救我的。燃烧军团还没赢呢！"
D.Strings[81612]="我要跟燃烧军团血战到底！我们营地见。"
D.Strings[81613]="我不能，也不会那么做的。我要坚强起来！我们营地见。"
D.Strings[81614]="或许我们还有希望……"
D.Strings[81615]="我不会就这么放弃的。我们可以做到！我们营地见。"
D.Strings[81616]="没时间了，$n。塞纳留斯林地需要你……我们得尽快行动。"
D.Strings[81617]="要用你全身的力气来挥舞铁锤，而不是只靠胳膊。"
D.Strings[81618]="你的进步相当喜人。"
D.Strings[81619]="当然了。我们的草药师带来了许多狐尾花。我可以拨一点给你用于锻造。"
D.Strings[81620]="哇！不错的配方。只要草药师能一直提供新鲜的狐尾花，我肯定能帮你准备好助熔剂，绝对没问题。"
D.Strings[81621]="稍后再来吧，$n。我要给你看点有趣的东西。"
D.Strings[81622]="我的能量用完了。坚持住，等我恢复力量。"
D.Strings[81623]="不臣服的巨龙都得死！"
D.Strings[81624]="托林尼尔完了。该你了！"
D.Strings[81625]="阿格拉玛之盾属于斯科瓦尔德。你别想染指！"
D.Strings[81626]="傲慢的蝼蚁……你休想阻止神王……"
D.Strings[81627]="你太迟了，蝼蚁！现在，巨龙已经臣服于我们了！"
D.Strings[81628]="只有我能拥有托林尼尔的力量！圣盾必将属于我！"
D.Strings[81629]="放弃吧，外来者。你不配进入英灵殿！"
D.Strings[81630]="你要给坐骑装蹄铁？让我看看这些蹄铁合不合脚……"
D.Strings[81631]="搞定了！你要好好照顾这头坐骑。它可真漂亮。"
D.Strings[81632]="你能给我的坐骑装上这些蹄铁吗？"
D.Strings[81633]="当然可以！快让它站上来，我来看看。"
D.Strings[81634]="不要见外，铁匠。"
D.Strings[81635]="我还有更多的技巧要教给你，但你现在还没法学。等你熟练一些了再回来找我吧，$c。"
D.Strings[81636]="真可惜。你必须先证明自己的实力才能获得挑战我的资格。"
D.Strings[81637]="厄林，让这个入侵者懂点礼貌。"
D.Strings[81638]="一个小麻烦。艾思格，把这蠢货送进冥狱深渊去！"
D.Strings[81639]="呸！她对我毫无价值。凯勒，为你死去的战友们复仇。"
D.Strings[81640]="好吧，或许我可以拿你来热热身。"
D.Strings[81641]="我还以为自己死定了呢。我欠你一条命！"
D.Strings[81642]="我想我可以自己返回营地的。速战速决吧，勇士！"
D.Strings[81643]="恶魔，暴风城必胜！"
D.Strings[81644]="瞄准了，伙计们。让这些恶魔尝尝我们的怒火吧！"
D.Strings[81645]="英雄们，去控制火炮！摧毁那颗水晶！"
D.Strings[81646]="我可以将我们精心研发出来的邪钢护臂图纸免费送给你。"
D.Strings[81647]="如果你想学习更多的邪钢图纸，就跟乌拉尔谈谈吧。"
D.Strings[81648]="这我可不能白送给你。我们正需要一些原材料。"
D.Strings[81649]="南面来了一位骑手！"
D.Strings[81650]="老天保佑。小伙子们，骑兵队来了！"
D.Strings[81651]="北面来了一位骑手！"
D.Strings[81652]="我得走了。好好利用我给你的力量。"
D.Strings[81653]="德克加尔在攻击你的龙！快释放风暴之怒击退他们！"
D.Strings[81654]="我们已经为你将一张画像定位到了幽暗城，$n。请跟我来。"
D.Strings[81655]="你准备好之后，就穿过画像，传送去幽暗城吧。"
D.Strings[81656]="各位，我们要立刻赶往圣光之愿。"
D.Strings[81657]="我居然要听你的！你会控制这玩意儿吗？！"
D.Strings[81658]="小心！来了一头大家伙！"
D.Strings[81659]="我当然会了！等等……哇！哇！"
D.Strings[81660]="好了，让我们放下船，然后——啊！！"
D.Strings[81661]="返回勇者之门"
D.Strings[81662]="过来，$n。我有东西要给你看。"
D.Strings[81663]="我可以教你怎么提高生产效率。"
D.Strings[81664]="请等一等，铁匠。我有东西要教你。"
D.Strings[81665]="让我来教你一些新知识吧，$n。"
D.Strings[81666]="不错，但我可以教你怎么做得更好。"
D.Strings[81667]="有人呼叫了空中支援吗？"
D.Strings[81668]="目标正在撤退。确保上将的安全。"
D.Strings[81669]="蝙蝠骑手朝你那儿去了！别动，我和上将正想办法突围！"
D.Strings[81670]="许多艾泽拉斯最伟大的圣骑士都长眠在这片神圣的土地下。其他人就在下面的圣殿里等你，$n。"
D.Strings[81671]="愿圣光保佑你，$n。要不是你的话，艾泽拉斯可能已经落入燃烧军团的手中了。"
D.Strings[81672]="你应该去引出那个维库人，而不是他的宠物蜥蜴。"
D.Strings[81673]="胜利属于希尔瓦娜斯！"
D.Strings[81674]="英雄，我们掩护你！为了暴风城！"
D.Strings[81675]="我们要誓死保卫家园！"
D.Strings[81676]="广播信号"
D.Strings[81677]="你会为你的傲慢付出代价，凡人！"
D.Strings[81678]="要想离开这里只有一个办法，联盟，穿过那条恶魔的防线！火力掩护！所有部队！全力出击！"
D.Strings[81679]="一切都……变暗了……"
D.Strings[81680]="已经……坚持不住了……"
D.Strings[81681]="都靠近了，不要让他们击穿防线！"
D.Strings[81682]="放暴风雪！"
D.Strings[81683]="把这个家伙冻住！"
D.Strings[81684]="我的魔法会撕碎你！"
D.Strings[81685]="不能让他们抵达尖塔！"
D.Strings[81686]="我知道……我迟到了一点点。我的女儿并不乐意让我在这么多年后重返战场。“没人需要你这种老兵”，她说。"
D.Strings[81687]="让我们动手吧！"
D.Strings[81688]="我带着我的剑和盾前来听从你的调遣，指挥官！"
D.Strings[81689]="举起盾牌！不要放弃！"
D.Strings[81690]="你救了我！我……我还能听到那些声音。求求你，阻止他们，不要让他们再害死更多的人了。"
D.Strings[81691]="我感觉不太好。我是怎么到这儿来的？那……那是什么东西？"
D.Strings[81692]="神王已经进入了英灵殿。是时候完成你的试炼，击败守门者了。"
D.Strings[81693]="带我飞过风暴吧。我准备好与守门者战斗了。"
D.Strings[81694]="嘿嘿，我好像成功了！"
D.Strings[81695]="我已经帮那个恶棍脱离苦海了。"
D.Strings[81696]="他不邪恶！只是……有点误解。"
D.Strings[81697]="别让我的头盔给骗了。这只是我的战利品而已，我是你这边的！"
D.Strings[81698]="我们在预定地点堵截到了被遗忘者的舰队——他们就像瓮中之鳖一样被困在那个海湾里。$B$B没有时间等待援军了。$B$B我们只有一次机会，所以我下达了指令。$B$B我对此并不后悔。"
D.Strings[81699]="我们的船员将和联盟海军汇合并继续追杀希尔瓦娜斯。$B$B而你，则有更重要的任务。"
D.Strings[81700]="光靠力量是不行的。"
D.Strings[81701]="$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TINTERFACE\\ENCOUNTERJOURNAL\\UI-EJ-BOSS-GRAND CHAMPIONS-ALLIANCE.blp:50:80|t$b[格里安·斯托曼]你们的入侵到此为止了，恶魔。"
D.Strings[81702]="但它是你的第一步。到阿格拉玛的宝库附近来找我，我要考验你的力量。"
D.Strings[81703]="$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TINTERFACE\\ENCOUNTERJOURNAL\\UI-EJ-BOSS-ARGALOTH.blp:50:80|t$b[马加洛]我要把你们和创世之柱一起碾碎。"
D.Strings[81704]="$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TINTERFACE\\ENCOUNTERJOURNAL\\UI-EJ-BOSS-ARGALOTH.blp:50:80|t$b[马加洛]你们这是在浪费时间，凡人。"
D.Strings[81705]="快去拿几块炉石吧，英雄们！"
D.Strings[81706]="$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TINTERFACE\\ENCOUNTERJOURNAL\\UI-EJ-BOSS-ARGALOTH.blp:50:80|t$b[马加洛]你们这些可怜的武器连我的护甲都打不穿。"
D.Strings[81707]="你成功了！我这就带你飞回传送门。"
D.Strings[81708]="带我飞过风暴吧。我准备好进入英灵殿了。"
D.Strings[81709]="$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TINTERFACE\\ENCOUNTERJOURNAL\\UI-EJ-BOSS-ARGALOTH.blp:50:80|t$b[马加洛]这个世界将化为火海。好好听着你的盟友们的尖叫吧，”勇士“。"
D.Strings[81710]="那些水晶似乎在将建筑定位到我们的位面。毁掉它们，就一定能让整座建筑崩溃！"
D.Strings[81711]="但愿你是对的。"
D.Strings[81712]="干掉一个了，还剩两个。"
D.Strings[81713]="你会因此付出代价。军团是无穷无尽的！地狱火！"
D.Strings[81714]="再干掉一个，这片海滩就属于我们了！"
D.Strings[81715]="你们想见识一下燃烧军团的力量？哈，很好。主人会因为你们的灵魂而嘉奖我的。"
D.Strings[81716]="终于结束了，别再废话了。"
D.Strings[81717]="能将这些一盘散沙的部队整合起来可真是了不起，但你还需要进一步证明自己的能力。我恳请你不要辜负灰烬使者的遗志，大领主。如果你有需要，就请召唤我吧。"
D.Strings[81718]="你们还在等什么？冲锋！"
D.Strings[81719]="你，凡人，只是在拖延注定的……"
D.Strings[81720]="你的伪装毫无意义！我们可以看穿外表感觉到你的存在。"
D.Strings[81721]="你闯入了暗影之中……可你还能逃出去吗？"
D.Strings[81722]="你的安全只是一种幻想。"
D.Strings[81723]="最终，没有人能……"
D.Strings[81724]="暗影保护不了你。"
D.Strings[81725]="在你东躲西藏的时候，这股力量只会更加强大。"
D.Strings[81726]="他们来得太快了！我们寡不敌众！"
D.Strings[81727]="你以为这就完了吗，圣骑士？我们这才刚刚开始呢……"
D.Strings[81728]="维库人把大门包围了。但对你这样的勇士来说，这显然只是小菜一碟。$b$b相信你在穿过冥狱深渊后已经很累了吧？$b$b如果你想要击败守门人，就必须养足力气。$b$b如果我能有幸送你前往英灵殿，那就再好不过了。$b$b你打算怎么做，勇士？"
D.Strings[81729]="请送我一程。"
D.Strings[81730]="荣耀属于斯科瓦尔德！"
D.Strings[81731]="英灵殿！"
D.Strings[81732]="你击败了我，勇士。你可以进入英灵殿继续你的试炼了。"
D.Strings[81733]="放弃吧，不然有你受的。"
D.Strings[81734]="这位勇士有这个资格！让他过去。"
D.Strings[81735]="啊！总算有一场像样的战斗了！"
D.Strings[81736]="圣光在上……灰烬使者……"
D.Strings[81737]="难以言喻的……圣洁……"
D.Strings[81738]="$n……过来……"
D.Strings[81739]="你要……举起那把剑……阻止军团……"
D.Strings[81740]="他们需要……你……"
D.Strings[81741]="发射完毕！重新装弹！"
D.Strings[81742]="轰！打得好！"
D.Strings[81743]="继续射击，我来帮你装弹！"
D.Strings[81744]="没有这种粮食的话，我们的村民就死定了。但不要担心，亲爱的，我已经把这片区域封锁了！"
D.Strings[81745]="这边！我的迫击炮已经可以开火了！"
D.Strings[81746]="我也很想解释到底发生了什么，但就是死者好像都复活了。"
D.Strings[81747]="呃！啊……<喘气>这下好多了……"
D.Strings[81748]="救命……救命！"
D.Strings[81749]="有人吗？救命……"
D.Strings[81750]="救命！他们不让我走！"
D.Strings[81751]="上将还好吗？"
D.Strings[81752]="嘿，现在居然需要别人来救我们了。我可不想这种事经常发生。"
D.Strings[81753]="$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TINTERFACE\\ENCOUNTERJOURNAL\\UI-EJ-BOSS-GRAND CHAMPIONS-ALLIANCE.blp:50:80|t$b[格里安·斯托曼]你成功了！快回营地！"
D.Strings[81754]="谢谢你，$G先生:女士;！我不敢一个人回去，可我知道一条近路！"
D.Strings[81755]="我绝对不能半途而废。我的人民正处在危险之中。"
D.Strings[81756]="村民中一直流传着林中之民的故事，可直到今天，我连一个……德鲁伊都没见过。$B$B他们的魔法超出了我的理解能力。就好像他们能指挥森林一样。"
D.Strings[81757]="这是个孤注一掷的计划，有人可能觉得这很愚蠢。请求德鲁伊的援助无异于赌博。$B$B他们对我很好，但他们似乎有自己的战争要打。"
D.Strings[81758]="别犹豫了，$r。我们不能再浪费时间了。"
D.Strings[81759]="我准备好了，伊瑟拉。我们去寻找玛法里奥吧！"
D.Strings[81760]="我准备好了，伊瑟拉。我们必须找到玛法里奥！"
D.Strings[81761]="我看出来了，我是在跟一位身经百战的老兵说话。"
D.Strings[81762]="小心点，你要是敢轻举妄动的话，我们就用铁链把你锁起来。"
D.Strings[81763]="自由了！我终于摆脱那该死的躯壳了！"
D.Strings[81764]="在击败我，并将我的躯体摧毁后，你终于解除了那些秘法师施加给我的邪恶诅咒。"
D.Strings[81765]="现在，我要前往英灵殿了。我永远都会铭记你的恩情，勇士。愿你有一天也能光荣地战死。"
D.Strings[81766]="我接受你的挑战。"
D.Strings[81767]="不！圣光在我心中燃烧……我绝不投降！"
D.Strings[81768]="干得好！快到下一个阵地去，否则就迟了！"
D.Strings[81769]="该轮到我行动了！这股邪恶势力看来要被遏制了！"
D.Strings[81770]="好吧，这样也不错。现在，我们快走吧。"
D.Strings[81771]="$n！你必须……灰烬使者。别管我了……已经……没时间了……"
D.Strings[81772]="玛法里奥被怒火蒙蔽了。他和萨维斯早有宿怨。"
D.Strings[81773]="嘉文·月爪长眠于此，他是一位慈爱的父亲和忠诚的士兵。他在林努因之战中死于一头恶魔刀下。他将被我们永远铭记。"
D.Strings[81774]="完成你在这儿的任务，然后去堡垒见我。"
D.Strings[81775]="几百年前，黑鸦堡垒在卡多雷中大名鼎鼎。民众恐惧它所代表的严酷公正，贵族敬畏它强大的力量。"
D.Strings[81776]="拉文凯斯大人过世后，我领导起了他的军队。指挥官的重任让我迅速成长。"
D.Strings[81777]="拉文凯斯大人是他那个时代最伟大的指挥官。只有极少数人能与他相提并论。"
D.Strings[81778]="黑鸦堡垒领主，库塔洛斯·拉文凯斯，让许多人又敬又怕。"
D.Strings[81779]="我上一次踏上这片土地，已经是几千年前的事了，但往日记忆却像潮水般涌来。$B$B我们曾在这里集结大军，击退了恶魔的入侵。"
D.Strings[81780]="来吧！生长吧！占领这片森林！"
D.Strings[81781]="我的生命属于萨维斯。"
D.Strings[81782]="没有人能抵挡萨维斯的力量。"
D.Strings[81783]="我要将梦魇散播到每一座高山与山谷！"
D.Strings[81784]="我要去暴风城核实一下最新的消息了。"
D.Strings[81785]="我很快就来跟你汇合。我得去休整一下。"
D.Strings[81786]="使命在召唤着我！"
D.Strings[81787]="哈哈哈……你别想阻止我。"
D.Strings[81788]="就算死了，我也会重生！"
D.Strings[81789]="我受够你了。"
D.Strings[81790]="你们的灵魂将品尝万千世界所受的痛苦！"
D.Strings[81791]="我会把你变成燃烧军团的利器。等你死后，这个世界的最后一线希望也将熄灭。"
D.Strings[81792]="我就怕会这样。拉文凯斯大人的遗体不见了。"
D.Strings[81793]="加入我们亡者的行列吧，高塔之主将赋予你永恒的荣耀！"
D.Strings[81794]="蝼蚁们！我就是萨格拉斯的意志在这个世界的化身。在我面前，暴风城不堪一击。"
D.Strings[81795]="玩得开心点！小心第二个齿轮有点卡。"
D.Strings[81796]="准备，伙计们！破碎海滩等待着我们。$n一下令，就出发。"
D.Strings[81797]="作为被选中的勇士，你们将直捣地狱深渊，救出大领主提里奥。这是你们反悔的最后机会。"
D.Strings[81798]="真不知道该怎么感谢你！你救了我的命！"
D.Strings[81799]="我欠你一条命，可我必须赶快去警告其他人了！"
D.Strings[81800]="这片土地已经不再安全了……"
D.Strings[81801]="我已经飞了10个小时，该休息一下了！如果你有本事的话，就上去转转吧。"
D.Strings[81802]="我正在休息呢。"
D.Strings[81803]="嘿！别把它刮花了！"
D.Strings[81804]="告诉我希尔瓦娜斯在哪儿，我能让你死得痛快点。"
D.Strings[81805]="把你知道的都告诉我。我的猎犬都……饿了。"
D.Strings[81806]="希尔瓦娜斯在哪儿？如果有必要的话，我们不介意搜遍整座树林。"
D.Strings[81807]="何不把希尔瓦娜斯的下落告诉我，让自己少吃点苦头呢？如果你肯老实交代的话，我们两个就能省点事了。"
D.Strings[81808]="啊！太好了！一个新线索。你们的女妖之王在哪儿呢？"
D.Strings[81809]="下来下来，骨瘦如柴的小朋友。如果你把我想知道的告诉我，我们或许会让你活下去。"
D.Strings[81810]="我很怀疑奥图里斯的动机，但眼下我们的目标是一致的，那就是离开这座监狱。"
D.Strings[81811]="虽然我是个恶魔猎手，但我并不是伊利达雷的成员。我不会像你们一样盲目遵从伊利丹的教诲。"
D.Strings[81812]="你必须成为……灰烬使者……"
D.Strings[81813]="最终，我也无法再追随伊利丹的脚步。他已经被恶魔腐蚀了，变成了曾与他势不两立的敌人。"
D.Strings[81814]="我们被……"
D.Strings[81815]="再坚持一会儿，伙计们！援军已经到了！"
D.Strings[81816]="守住阵线！那些炸弹很快就能攻破大门了！"
D.Strings[81817]="哈！你们就这点能耐吗，恶魔？你们绝对想不到我们准备了些什么来招呼你们！"
D.Strings[81818]="尝尝我的锤子吧！"
D.Strings[81819]="这下是给你的！"
D.Strings[81820]="保持机动！附近还有！"
D.Strings[81821]="啊哈哈哈哈哈哈哈！我要砍死你。"
D.Strings[81822]="$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TINTERFACE\\ENCOUNTERJOURNAL\\UI-EJ-BOSS-ARGALOTH.blp:50:80|t$b[马加洛]这是什么意思？！我的护甲！"
D.Strings[81823]="$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TINTERFACE\\ENCOUNTERJOURNAL\\UI-EJ-BOSS-ARGALOTH.blp:50:80|t$b[马加洛]这……不……可能！"
D.Strings[81824]="谢谢你放我出来！我得赶紧跑了！"
D.Strings[81825]="我们进去！"
D.Strings[81826]="<这个伊利达雷囚犯脸色像鬼一样苍白。>$B$B我……冲了出来……逃跑了……$B$B我……差点就成功了……$B$B请救救……我的同伴……"
D.Strings[81827]="决不能让古尔丹成功。只要我还活着，就要跟燃烧军团抗争到底。"
D.Strings[81828]="他也无法独自击败萨维斯。我们得立刻找到他。"
D.Strings[81829]="欢迎来到铁角飞地。"
D.Strings[81830]="我能看穿你的秘密……"
D.Strings[81831]="高姆在你谁走过时嗅了嗅你的气味。"
D.Strings[81832]="入侵者！快去警告蛛后！"
D.Strings[81833]="恶魔猎手？你们怎么进来的？"
D.Strings[81834]="我要把你大卸八块。"
D.Strings[81835]="死吧，愚蠢的伊利达雷。"
D.Strings[81836]="啊……你不是矿工，对吧？好吧，我相信你一定能在拍卖行里找到一些矿石的。或者也可以直接从其他冒险者那里收购。"
D.Strings[81837]="$n，我们必须在火山这里与燃烧军团作战。我们必须在飞上蛛后的指挥舰邪能之槌号之前消灭他们。\n\n然后，我们再干掉她，拿走萨格里特钥石，返回黑暗神殿消灭入侵者。\n\n这可不是什么小打小闹，但我相信我们能做到。"
D.Strings[81838]="前进！我们必须在他们派出援军之前阻止他们！"
D.Strings[81839]="这里的战斗永不停止！"
D.Strings[81840]="我得去奥格瑞玛核实一下情况了。"
D.Strings[81841]="$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TInterface\\Icons\\achievement_character_bloodelf_female.blp:40|t$B[女伯爵莉亚德琳]嘿。在这边！"
D.Strings[81842]="拉文凯斯大人必胜！我军必胜！"
D.Strings[81843]="拉文凯斯的大军会驱逐所有的入侵者。你们的入侵到此为止了！"
D.Strings[81844]="停止轰炸！"
D.Strings[81845]="用甲板炮！所有人，准备迎敌！"
D.Strings[81846]="狮鹫骑士，一队，准备下降！二队，原地待命！"
D.Strings[81847]="敌方空军来了！所有火炮，全力开火！"
D.Strings[81848]="面对现实吧……我们迷路了。"
D.Strings[81849]="要是我们总在原地转圈的话，是不可能找到海滩的。都是你害我们迷路的！"
D.Strings[81850]="这里没有好吃的农夫。你说那里有农夫的！"
D.Strings[81851]="我牙口不好，嚼不动那些维库人。我们应该回至高岭去。"
D.Strings[81852]="你说我们现在应该已经到了。我没看出来。"
D.Strings[81853]="这都是你的错。我们迷路了。"
D.Strings[81854]="这里除了绵羊就是维库人。我记得你说我们能在这里找到一群美味的侏儒的。"
D.Strings[81855]="这里也没有可以烤来吃的牛头人。你说过我们能在这里找到更多的烤牛头人的。"
D.Strings[81856]="敌人上甲板了！"
D.Strings[81857]="你们休想活着离开炼狱峰……"
D.Strings[81858]="前进吧，萨格拉斯的仆从们。我们的时代到了！"
D.Strings[81859]="一个不留。"
D.Strings[81860]="消灭所有的生灵。所到之处，寸草不留！"
D.Strings[81861]="黑林逃到了附近的洞穴里。追上他，结束这一切。"
D.Strings[81862]="反抗萨维斯的大战爆发了。伊瑟拉就此陨落并惨遭腐蚀。而受了重伤的玛法里奥则继续追击萨维斯。"
D.Strings[81863]="阿古斯之手响应你的召唤前来报到。"
D.Strings[81864]="你知道该怎么做，铁匠：回火、加热、锻打并焊接。这店里的所有设备你都可以用。"
D.Strings[81865]="去看看能不能找个冰霜法师来帮我们，$n。如果我们的淬火水槽温度够低的话，就可以实现这项魔石锻造技术了。"
D.Strings[81866]="一个负责任的铁匠是不会浪费原材料的。我们营地里的金属都随便你用。"
D.Strings[81867]="动作快点。你只有一小段时间来将那些红热的魔石锭锻打成你需要的零件。"
D.Strings[81868]="你们软弱的心智将成为我的囊中之物！"
D.Strings[81869]="没人能抗拒燃烧军团。万物迟早都将臣服于它。"
D.Strings[81870]="苍穹石是我们教派的圣物。$b$b之前并非没有外来者寻找过我们的铁砧……但要真正得到它就不容易了。"
D.Strings[81871]="燃烧军团来了。我们最好做好迎接他们的准备。"
D.Strings[81872]="要我说的话，就让他们放马过来吧。我们将携手打败他们……或者一同战死沙场。"
D.Strings[81873]="这座神殿作为给月神艾露恩的献礼，已经矗立了几百年了。$b$b这不是燃烧军团第一次试图摧毁它了……他们也会和前几次一样失败的。"
D.Strings[81874]="来尝尝这个吧，恶魔们！我为你们每人都准备了一个炸弹！"
D.Strings[81875]="守住阵线！让他们集中到我的炸弹爆破范围里来！"
D.Strings[81876]="这一定很疼！"
D.Strings[81877]="翡翠梦魇的危险如同势不可挡的风暴，已经出现在了地平线上……可我们宁可战死，也不会让它夺走我们所珍视的一切。"
D.Strings[81878]="先是塞纳留斯……现在……又轮到了伊瑟拉？$b$b萨维斯必须为他的所作所为付出代价……我们要为他们复仇！"
D.Strings[81879]="找到他了！集火他们的指挥官！"
D.Strings[81880]="军团将碾碎你们！地狱火！"
D.Strings[81881]="萨维斯……$b$b一定要阻止他……"
D.Strings[81882]="小心，地狱火！"
D.Strings[81883]="你们的灵魂将成为灵魂熔炉的燃料！"
D.Strings[81884]="梦魇的力量已经征服了这片森林……包括伟大的世界之树莎拉达希尔。$b$b恐怕我们将要面对瓦尔莎拉有史以来最可怕的威胁了……"
D.Strings[81885]="<生命之种长出的幼苗青翠茂盛，与周围扭曲的毁灭景象形成了鲜明对比。小树发光的叶片中，传出了轻柔的低语……>"
D.Strings[81886]="你就这点本事吗？你得再加把劲儿才行。"
D.Strings[81887]="来吧，铁匠！用力砸它！！！"
D.Strings[81888]="你……必须到神殿去……"
D.Strings[81889]="我的力量将毁灭这片可悲的土地！"
D.Strings[81890]="你们以为自己能对抗萨维斯的力量？"
D.Strings[81891]="梦魇将吞噬你们所有人！"
D.Strings[81892]="$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TINTERFACE\\ENCOUNTERJOURNAL\\UI-EJ-BOSS-ARGALOTH.blp:50:80|t$b[马加洛]你们都得死！"
D.Strings[81893]="阿苏纳必将陷落！"
D.Strings[81894]="交出潮汐之石，凡人。"
D.Strings[81895]="你阻止不了我们。我们是无穷无尽的。"
D.Strings[81896]="阿苏纳只是一个开始。"
D.Strings[81897]="快。伊利达雷就快被击溃了。"
D.Strings[81898]="真是太可怕了。我们必须摧毁这些恐怖的怪物。"
D.Strings[81899]="召唤我的怒火去净化这些扭曲的怪物吧。"
D.Strings[81900]="这片森林恐怕已经完了。我们必须快一点行动。"
D.Strings[81901]="我们得下去，$n。伊利达雷需要我们帮忙消灭燃烧军团。\n\n解决了恶魔之后，我们就可以着手寻找阿苏纳的创世之柱了。"
D.Strings[81902]="我不会再回到牢房了。绝不会！"
D.Strings[81903]="我们听从萨维斯的命令。"
D.Strings[81904]="你的鲜血将染红这条河流。"
D.Strings[81905]="臣服于梦魇吧，否则就得死。"
D.Strings[81906]="这条河是我们的！"
D.Strings[81907]="凯恩，别在这里耽误太久，燃烧军团已经全线出击了。"
D.Strings[81908]="$n，我到那里跟你汇合。沿着路往东北走就能抵达栖地了。"
D.Strings[81909]="卡德加对丝黛拉苟萨点了点头。"
D.Strings[81910]="接下来的事就交给你了！我们得去别的营地击退他们！"
D.Strings[81911]="继续推进！我们得去帮助其他人。"
D.Strings[81912]="我们只能冲到这里了。我们会守住这片阵地的，稍后就来跟你汇合。"
D.Strings[81913]="真见鬼！通往安戈洛环形的道路已经一团乱了！我怀疑是巨龙干的！"
D.Strings[81914]="我们已经在南方小径两旁的悬崖上布置了人手！我们会尽可能拖住他们的……"
D.Strings[81915]="我们的大厅不欢迎你们！你们永远别想获得流淌在这些符文中的知识！"
D.Strings[81916]="我才懒得管你们这群乌合之众呢。我会让我的学生来解决你们的。"
D.Strings[81917]="很好，看来我要亲自出手了。"
D.Strings[81918]="哈哈哈！血须，看来你的挑战者已经来了。"
D.Strings[81919]="$n，过来。我们一起走。"
D.Strings[81920]="末日再次降临了，$n。$b$b你愿意站出来迎接挑战吗？"
D.Strings[81921]="你！对——！有了我手中的力量，我就能让他复活了。"
D.Strings[81922]="<库尔迪拉漠然地看了你一眼。>"
D.Strings[81923]="<库尔迪拉瞪着你。>$b$b走开……我跟你无话可说。"
D.Strings[81924]="在阿彻鲁斯霉烂的大厅里你吸入了第一口罪恶的空气。$b$b而在这里，我们必须搁置争议，将黑锋骑士团团结起来，才有可能击败恶魔。"
D.Strings[81925]="已经开始的一切必将实现。"
D.Strings[81926]="黑暗中没有光明，也没有希望。"
D.Strings[81927]="符文先知将你放逐到了冥狱深渊！"
D.Strings[81928]="阿兹塔尔在召唤它的仆从！"
D.Strings[81929]="小$r$n是文雅的洛什的朋友。\n\n你要待上一会儿吗？"
D.Strings[81930]="对，我想我需要停留一会儿。"
D.Strings[81931]="多谢你的帮忙，$g帅哥:美女;。"
D.Strings[81932]="我得抓紧机会离开了。我会告诉沙考尔先生等着你的。"
D.Strings[81933]="嘿！你……你！我欠你一份人情。我最好赶快离开这儿了。"
D.Strings[81934]="他们看见了你的灵魂。他们了解你的恐惧。"
D.Strings[81935]="潮流不会被扭转。它只会不断涨落。"
D.Strings[81936]="给你一个！这个给你！轰隆！哈哈哈哈！"
D.Strings[81937]="我这儿有的是黑火药，恶魔渣滓！尽管放马过来吧！"
D.Strings[81938]="你，绿衣服那个！攻击他们的左侧！不对，是他们的左边！"
D.Strings[81939]="文雅的洛什喜欢你，我的小$r。现在文雅的洛什要走了。"
D.Strings[81940]="你们惹错人了！干掉他们，小伙子们！"
D.Strings[81941]="稳住！保持队形！让这只恶魔杂种看看地精的战斗力！"
D.Strings[81942]="你，飞行员小子，气球上那个！再来点炸弹！"
D.Strings[81943]="我已经被关了好几天了。谢谢你，$c。你懂的，我得走了！"
D.Strings[81944]="能跻身这神圣的殿堂就是所有勇士最大的荣耀。"
D.Strings[81945]="你一直坚定不移地遵守着圣光的教诲。我很钦佩你的热情，$n。我愿意给你我的祝福。"
D.Strings[81946]="我将你给我的祝福。"
D.Strings[81947]="可惜你永远别想跨入它的大门！"
D.Strings[81948]="这不可能！从来没有外来者能在战斗中击败我！"
D.Strings[81949]="我判定你有这个资格，$c。"
D.Strings[81950]="什么？一个想接受审判的外来者？"
D.Strings[81951]="傲慢的爬虫！你的存在只会让英灵殿蒙羞！"
D.Strings[81952]="我错了。你的实力不容置疑。"
D.Strings[81953]="你想成为英灵殿的选民？"
D.Strings[81954]="那就来吧，让我见识一下你的怒火！"
D.Strings[81955]="我从没见识过如此凶猛的攻势。你的体内流淌着巨龙的鲜血，外来者。"
D.Strings[81956]="嘿……嘿，$g先生:女士;。你一定要放我出去。"
D.Strings[81957]="我在这儿呢。小心那个巨人！"
D.Strings[81958]="你来开门。文雅的洛什不会打你的。"
D.Strings[81959]="你是万灵派来的人，$c。"
D.Strings[81960]="你听到了吗？元素在哭泣。"
D.Strings[81961]="我的人民对你没有恶意。"
D.Strings[81962]="抓紧机会休息吧，英雄。我来警戒。"
D.Strings[81963]="骑士们，立正！"
D.Strings[81964]="我们进入了敌人的地盘。因此，我们要改变巡逻计划，保证随时都能有至少一个可用的飞行点。我可不想再遭遇类似于破碎海滩那样的突然袭击了。"
D.Strings[81965]="什么是自然的召唤？"
D.Strings[81966]="有什么麻烦吗？"
D.Strings[81967]="当自然开口时，我们必须仔细聆听并迅速行动。"
D.Strings[81968]="我，提尔，将万神殿赋予我的所有力量赐予这个圣骑士。"
D.Strings[81969]="我们的敌人已经集结，末日的利剑再次悬在了我们的头顶。他们会用地狱之火的浪潮毁灭我们的世界。我们决不能容许这种事情发生！"
D.Strings[81970]="好好使用我的礼物吧，$n。你现在手持的武器就是圣光的移动堡垒。"
D.Strings[81971]="去吧，向奥莉丝塔夫人汇报你们的任务。接受痛苦的试炼吧，骑士们。"
D.Strings[81972]="接受痛苦的试炼，长官！"
D.Strings[81973]="掠夺"
D.Strings[81974]="走开！别打扰我的研究。"
D.Strings[81975]="这份新工作好、好多了……没有娘、娘儿们对我指手画脚的。"
D.Strings[81976]="又、又要大、大扫除了！"
D.Strings[81977]="哦，我漏、漏掉了一点……"
D.Strings[81978]="啊，又、又脏了。这是我灵魂的映、映照。"
D.Strings[81979]="萨特们要为此付出代价！"
D.Strings[81980]="萨特……他们突然冒了出来！"
D.Strings[81981]="要不是你帮忙，我就死定了！"
D.Strings[81982]="请你……一定要救救瓦尔莎拉！"
D.Strings[81983]="这才刚刚开始呢！小伙子们，让他们排成直线！"
D.Strings[81984]="我去召集部队！你们挺住，能坚持多久就坚持多久！"
D.Strings[81985]="又来了一波！"
D.Strings[81986]="武器不错啊，$c。想帮忙的话，就去跟杰斯和阿莱利谈谈吧。"
D.Strings[81987]="做好准备，英雄。我们很快就要见到森林之神了。"
D.Strings[81988]="我要谢谢你，陌生人。能在这样的绝境中获得帮助真是太好了。"
D.Strings[81989]="夜鬃派我来找你。你还能走吗？"
D.Strings[81990]="如果你能通过那头野兽，就去找巴尔迪尔。通过巴尔迪尔那一关，你就能跟赫利拉对话了。祝你好运，$c。"
D.Strings[81991]="你太迟了……黑暗女王已经走了……"
D.Strings[81992]="<这个小生物恐惧地颤抖，似乎因为心烦意乱而不能和你说话。>"
D.Strings[81993]="艾希迪尔女王在永恒战场上。我建议你尽快赶去，以免赫利拉让她改变了主意。"
D.Strings[81994]="我们留下来照料伤员。你快走吧，去唤醒大德鲁伊。"
D.Strings[81995]="<这头幼龙用阴险的目光死死地盯着你。>"
D.Strings[81996]="前进。消灭伊利达雷，占领阿苏纳。"
D.Strings[81997]="我们是军团。你们赢不了的。"
D.Strings[81998]="太迟了，“英雄们”。这个世界完了。"
D.Strings[81999]="跪下，求饶吧！"
D.Strings[82000]="你和你的世界即将毁灭。"
D.Strings[82001]="你们的泰坦之神抛弃了你们。放下武器吧，你们没希望了。"
D.Strings[82002]="那把武器也救不了你。如此渺小的存在怎么可能战胜军团的力量？"
D.Strings[82003]="碱化大地。煮干海洋。让他们四散奔逃！"
D.Strings[82004]="你应该加入我们的！"
D.Strings[82005]="回到扭曲虚空……"
D.Strings[82006]="控制台显示出了一个数字1。"
D.Strings[82007]="够了，你们这些寄生虫！现在，来面对我的怒火吧。"
D.Strings[82008]="我应该和其他人一起上战场。"
D.Strings[82009]="等我出去之后，一定要干掉我看见的第一个克瓦迪尔分子。"
D.Strings[82010]="我是有资格的。我知道我是有资格的……"
D.Strings[82011]="高姆感应到了什么。"
D.Strings[82012]="祝福你，年轻人。"
D.Strings[82013]="艾希迪尔和我们在一起？我们很快就能自由了。"
D.Strings[82014]="你带来了希望。赫利拉再也别想关住我了。"
D.Strings[82015]="我要让血须尝尝我的怒火。"
D.Strings[82016]="我的女王回来了。那些秘法师将为他们的诡计付出代价。"
D.Strings[82017]="我……我又可以清醒地思考了。"
D.Strings[82018]="女神赫利拉已经说了。你休想打败我。"
D.Strings[82019]="不……不可能。赫利拉，宽恕我！"
D.Strings[82020]="血须，你太让我失望了。你的惩罚马上就要降临了。"
D.Strings[82021]="你可以走了，勇士。在我改变主意之前，快滚吧。"
D.Strings[82022]="谢谢你，旅行者。我们还有希望。"
D.Strings[82023]="埃洛瑟尔与你同在，森林之友。"
D.Strings[82024]="我……没有摔死。"
D.Strings[82025]="迅翅！迅翅呢？"
D.Strings[82026]="你的灵魂重新变得完整了。你从赫利拉的指缝间溜了出来。"
D.Strings[82027]="哦，不！他们对你做了什么！？"
D.Strings[82028]="我们自由了！后会有期，勇士。"
D.Strings[82029]="我已经飞了四个小时了……该休息一下了。"
D.Strings[82030]="狠狠教训他们吧，长官！"
D.Strings[82031]="我相信，新来的飞行员一定会表现得很好的！"
D.Strings[82032]="军团士兵，出击！攻击那些船，找到希尔瓦娜斯！"
D.Strings[82033]="我只是做了我应该做的事。"
D.Strings[82034]="如果我们不能尽快解决那些萨特，整座山谷就全完了。我们没有时间了……"
D.Strings[82035]="我们要杀出一条血路，深入腐蚀区域，才能直捣这次威胁的心脏！"
D.Strings[82036]="有人看见萨特的首领在刀齿洞穴附近出没。我要去对付他。"
D.Strings[82037]="等你完成你的任务后，来刀齿洞穴找我！我们必须立刻制止这种腐蚀！"
D.Strings[82038]="看来林精已经杀害了这只小熊的家人。$b$b这只熊崽用绝望的眼睛仰视着你，显然是在发抖。$b$b你听到附近的树林里传来沙沙的声响：林精们快要回来了。$b$b这是小熊是不可能靠自己活下来的。你愿意救它吗？"
D.Strings[82039]="图腾的力量属于我。你休想得到它。"
D.Strings[82040]="快点，蠢猪！再快点！你现在是萨格拉斯的仆从了！"
D.Strings[82041]="所有的战利品都是属于燃烧军团的！一样都别落下。"
D.Strings[82042]="我需要点时间来研究一下，$g小子:丫头;。我可能还要去咨询一下我的…….同龄人。稍后再回来吧，我会把我了解到的情况都告诉你的。"
D.Strings[82043]="很高兴你成功了，勇士！你最好做好行动的准备。燃烧军团似乎在安戈洛发现了一种能源。我们必须阻止他们！"
D.Strings[82044]="等等……等等我们……"
D.Strings[82045]="他们伤害了我们的朋友莉克希，她还在那儿躺着呢。是时候以牙还牙了！"
D.Strings[82046]="嘿，波尔莎！快走吧，姐妹！"
D.Strings[82047]="谢谢你——谢谢你们所有人。大家做好准备。这不会这么容易的。"
D.Strings[82048]="我会救你的，可怜的小东西。"
D.Strings[82049]="跟紧了！我们走！"
D.Strings[82050]="我要刺穿你的膝盖！"
D.Strings[82051]="你的块头越大，破绽就越多！"
D.Strings[82052]="我们绝不会放弃这片丛林的！"
D.Strings[82053]="熊又不喜欢你！干嘛还要保护它们？"
D.Strings[82054]="只想找点小乐子。这一点都……不好玩……"
D.Strings[82055]="我看见你了，$n。你有什么打算？"
D.Strings[82056]="你跪了下来，伸出一只手。小熊跑过来嗅着你的手指。"
D.Strings[82057]="我会收养你的，小家伙。"
D.Strings[82058]="你好，矿工。你需要训练吗？"
D.Strings[82059]="我们所有人记忆中的始祖是瑞苏。\n\n瑞苏·铁角是我们中第一个踏上这座山的人。他在这片高原定居下来，在这里抚养他的孩子。有人说这片营地就是他从山体中开凿出来的。\n\n他是个铁匠，也是个父亲，但首先……他是个矿工。"
D.Strings[82060]="所有的故事都提到了他的耐心，大部分还提到了他的智慧。他或许是我们民族有史以来最伟大的矿工，但他从不吝于与族人分享知识。\n\n他教导了他的儿女，当然，他也收学徒。绿蹄家族为了寻求他的指导，也特意来到了至高岭。\n\n我们只知道，我们欠他许多。"
D.Strings[82061]="年轻时，他走过许多地方。他凿开洞穴与峡谷。他与岩石对话。有些故事说这种岩石的语言就是他原本的部族驱逐他的原因。\n\n他对魔石的了解是个传奇。他生活在艾泽拉斯的时代，和我们一样，也受到了恶魔的侵害，他对邪能页岩等矿石的加工技术也因此流传到了今天。\n\n他是先驱，$n。他的余荫至今仍庇佑着我们。"
D.Strings[82062]="没有人知道。他在人们熟睡时离开了飞地，再也没有回来。有人说他去追寻新的挑战了。还有人说他挖掘得太深，发现了某些禁忌的秘密。\n\n无论如何，他的遗产一直传承至今。他留给了我们这片土地，和他的知识。他还留下了一支血脉——我们中的一些人，包括我自己，都继承了他的姓氏。"
D.Strings[82063]="说说你的故事吧。"
D.Strings[82064]="他人怎么样？"
D.Strings[82065]="和我说说瑞苏的采矿技术吧。"
D.Strings[82066]="瑞苏出了什么事？"
D.Strings[82067]="尝尝我的剑吧，这是钢铁的正义之击！"
D.Strings[82068]="我说！你知不知道什么叫荣耀，巨龙？"
D.Strings[82069]="汝只有这点本事乎？"
D.Strings[82070]="巨龙！别让我揪住你们的尾巴，否则我就把它们割下来！"
D.Strings[82071]="这里有痕迹。迅翅肯定走了这条路！"
D.Strings[82072]="你的宝贝迅翅死了！你居然没有摔死，暗夜精灵。但你下次不会再这么走运了。"
D.Strings[82073]="英雄！为迅翅复仇！"
D.Strings[82074]="捅死它！"
D.Strings[82075]="魔力是我们的，小偷！"
D.Strings[82076]="让我的箭刺穿你！"
D.Strings[82077]="我要在你身上戳几个洞！"
D.Strings[82078]="滚开，梦境的怪物！"
D.Strings[82079]="你竟敢打扰我们的仪式？"
D.Strings[82080]="梦境生物，滚开！"
D.Strings[82081]="嗷！梦境生物，滚开！"
D.Strings[82082]="小熊蹲在你的脚边，信赖地仰望着你。"
D.Strings[82083]="谢谢，头儿……可怎么才两百金？这是剥削！"
D.Strings[82084]="哎哟！这一定会留下疤痕的！"
D.Strings[82085]="谢谢你，英雄。我一个人是不可能成功的。"
D.Strings[82086]="这是什么魔法？！你会为此付出代价的！"
D.Strings[82087]="什么？！我的力量！"
D.Strings[82088]="正义已经得到伸张，英勇的义举已被传扬。现在，我必须关注骑士的信仰！"
D.Strings[82089]="一个高贵的英雄从不会忘记他为之奋战的姑娘。"
D.Strings[82090]="别忘了，我的大人：我今天差点死亡。但我的死绝不会是因任何巨龙留下的伤。"
D.Strings[82091]="不！我差点死亡，只是因为那喧嚣的战场，无法满足我的渴望！"
D.Strings[82092]="当巨龙的鲜血满地流淌，我心却在为你而哀伤！"
D.Strings[82093]="能请您用一个微笑，或者，一次招手来传递我们之间秘密的情意吗？"
D.Strings[82094]="沙沙声越来越响。林精们正在接近洞穴入口！准备迎接他们的攻击！$b$b这只小熊看起来又无助又害怕。"
D.Strings[82095]="侍从们，英雄们，少女们！快来接受我的保护吧！"
D.Strings[82096]="你们这些凡人竟敢反抗燃烧军团的力量？"
D.Strings[82097]="你们已经死到临头了——现在该结束了。"
D.Strings[82098]="<这个德鲁伊在睡梦中喃喃自语。>$B$B他们永远别想找到我的宝藏。我已经把它藏好了。$B$B<然后，他的声音又低沉了下去，几乎听不清楚。>"
D.Strings[82099]="中央控制区已激活！"
D.Strings[82100]="联盟占领了中央控制区！"
D.Strings[82101]="部落占领了中央控制区！"
D.Strings[82102]="<轻轻推搡沉睡的德鲁伊。>"
D.Strings[82103]="外面在打仗呢。这就意味着有生命需要我们去挽救，有金钱等着我们去赚取，$n！\n\n你要不要拿上我的硝基电能起搏器，去前线援救那些昏迷不醒的卫兵呢？别忘了把账单留给他们！"
D.Strings[82104]="他们还没死呢，$n。这就意味着他们都是潜在的客户！\n\n很简单。你拿上我的硝基电能起搏器，对那些看起来精疲力竭的卫兵们使用。然后，他们就得付我钱了！我要发财了！"
D.Strings[82105]="我需要一个硝基电能起搏器，护士。"
D.Strings[82106]="勇士们！决不能让他们进入洞穴！"
D.Strings[82107]="做好准备。我的力量只能挡住他们这么点时间。"
D.Strings[82108]="就算是最伟大的英雄也得时不时休息一下。"
D.Strings[82109]="没有人会想到去查看餐具后面的。"
D.Strings[82110]="蠢货！你们挑起了被遗忘者的怒火！"
D.Strings[82111]="燃烧吧！哈哈哈！"
D.Strings[82112]="<这个德鲁伊继续在睡梦中自言自语，偶尔翻个身。>"
D.Strings[82113]="乌索尔的化身"
D.Strings[82114]="$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TINTERFACE\\ICONS\\ACHIEVEMENT_CHARACTER_ORC_MALE.BLP:40|t[萨鲁法尔大王]你的入侵到此为止了，恶魔。"
D.Strings[82115]="沙卡玛的化身"
D.Strings[82116]="月亮的化身"
D.Strings[82117]="英勇的牺牲！但是现在还不是时候……"
D.Strings[82118]="盯着天上。地狱火随时可能落下。"
D.Strings[82119]="我要在你采矿的那只胳膊里嵌入三块邪能页岩碎片：一块嵌入肩膀，一块在肘部，一块在手腕。都是很小但参差不齐的石头碎片。$b$b这可能会有一点疼。"
D.Strings[82120]="你适应得非常好。$b$b下一块将嵌入你的肘部。准备好了吗？"
D.Strings[82121]="我们就快完成了。通常来说，三是有魔力的数字。你的身体里的邪能页岩不能少于这个数字……当然也不能更多。$b$b最后一块将直接嵌入你的手腕。准备好了吗？"
D.Strings[82122]="可以理解。风险是很高……但如果你想要提高你的采矿技巧，就没有其他办法了。"
D.Strings[82123]="那就不要浪费我的时间了。回去挖魔石吧。"
D.Strings[82124]="我们马上就要大功告成了。现在放弃没有任何意义。"
D.Strings[82125]="我们恶魔猎人就像是在走钢丝。只有你才能决定底线在哪儿。"
D.Strings[82126]="我准备好了，将邪能页岩碎片嵌入我的肩头吧。"
D.Strings[82127]="事实上，我改主意了。我还是不要这么做了。"
D.Strings[82128]="是的。把邪能页岩嵌入我的手肘吧。"
D.Strings[82129]="我不想这么做了。"
D.Strings[82130]="准备好了。将邪能页岩嵌入我的手腕吧。"
D.Strings[82131]="这太过分了。我跟你不一样，我又不是恶魔猎手——我可受不了这种魔化改造。"
D.Strings[82132]="这太危险了。我是恶魔猎手，娜瑞莎……我的血管里已经流淌着恶魔的鲜血了。我可能会失控的。"
D.Strings[82133]="咔咔！发现威胁！启动消灭程序。"
D.Strings[82134]="允许硬件超频。咯……咯……发生故障！"
D.Strings[82135]="进入战斗。目标类型：未知。"
D.Strings[82136]="哈！这家伙还挺有精神的！"
D.Strings[82137]="这家伙太迟钝了！把匕首给我！"
D.Strings[82138]="你休想轻易摆脱我！"
D.Strings[82139]="拜托！你哪有那么累！"
D.Strings[82140]="我的堂兄葛诺极其渴望力量。现在，整个部族都跟着他走向了疯狂。"
D.Strings[82141]="一名冰缚勇士将火炮冻成了冰块！"
D.Strings[82142]="请在我侄子和其他人一样发疯之前找到他！"
D.Strings[82143]="火箭，呃……运输系统准备发射！"
D.Strings[82144]="下一个牺牲品！哈！嘿，我只是在开玩笑……"
D.Strings[82145]="这里没有希尔瓦娜斯的踪影。让我们把这里清理干净——然后想办法去下一艘船！"
D.Strings[82146]="剩下的事就交给我们吧。继续去找风行者号！"
D.Strings[82147]="我去找我叔叔了。谢谢你，好心的陌生人！"
D.Strings[82148]="|TInterface\\Icons\\ACHIEVEMENT_CHARACTER_NIGHTELF_MALE.BLP:50|t很好，$n。利爪德鲁伊会支持我们了，可这还不够。"
D.Strings[82149]="<这块石头散发着恶魔能量。念出它主人的名字，她就会出现。>"
D.Strings[82150]="琳蒂萨。"
D.Strings[82151]="莱瑞勒。"
D.Strings[82152]="昂德里。"
D.Strings[82153]="我能请你帮一个忙吗，陌生人？$B$B我的部族名为燃皮。最近，我的兄弟们发现了一种邪恶的魔法。他们都发了疯，满腔怒火，开始攻击我们的德鲁伊朋友了。"
D.Strings[82154]="谢谢你救了我的侄子。但愿我们能重建我们的村子。"
D.Strings[82155]="降落伞就在楼下，$G先生:女士;。"
D.Strings[82156]="我要谢谢你，$c。要不是你救了我，我可能已经发疯了……就像其他人一样。"
D.Strings[82157]="军团士兵们就在后甲板上。他们一定很乐意与你并肩战斗！"
D.Strings[82158]="<这个德鲁伊的手臂和脸上布满了深深的伤痕。不幸的是，你已经帮不了她了。>"
D.Strings[82159]="安息吧。我会告诉大德鲁伊，你英勇地战斗到了最后一刻。"
D.Strings[82160]="我被敌人压制了。我肯定自己会死在这里……但我决不会坐以待毙！"
D.Strings[82161]="夜鬃派我来找你。你受伤了吗？"
D.Strings[82162]="告诉夜鬃，多亏了你的帮忙，我还活着。"
D.Strings[82163]="等恢复了力气，我就立刻返回安全地带。谢谢你。"
D.Strings[82164]="让我看看你准备了哪些任务？"
D.Strings[82165]="你准备好分派后就告诉我一声。"
D.Strings[82166]="杀了这些堕落的生物！为了联盟！"
D.Strings[82167]="小心点——那些锅里炖着的可不像是西部荒野杂味炖肉……"
D.Strings[82168]="皇家卫兵——这是风行者号！抓住船长！"
D.Strings[82169]="你们的船已经完了！"
D.Strings[82170]="啊，瓦尔莎拉……"
D.Strings[82171]="等等！她可能知道一些消息！"
D.Strings[82172]="好多蝙蝠……"
D.Strings[82173]="你们可悲的垂死挣扎毫无意义，凡人！我们的堡垒将指引萨格拉斯降临这个世界。你们的末日早已注定！"
D.Strings[82174]="你总是这么软弱，埃洛苏斯！你这个杀千刀的竟敢让萨格拉斯失望！"
D.Strings[82175]="你们竟敢抵制萨格拉斯的意志降临这个卑贱的世界？我要亲手把你们送入地狱，凡人！"
D.Strings[82176]="我们会找到了解创世之柱的人的。我向你保证。"
D.Strings[82177]="我们的房间永远欢迎你，$c。"
D.Strings[82178]="你应该在家呆着！"
D.Strings[82179]="拜托。至少告诉我你是怎么想的吧。"
D.Strings[82180]="这句话你在过去两小时内已经说了二十七次了。"
D.Strings[82181]="该死，道格，看着我。我们不能留在这里！"
D.Strings[82182]="只要我们做好本分，就一定可以撑过去的。快回去干活吧。"
D.Strings[82183]="|cFFFF0000%s|r试图移除她身上的所有有害效果！"
D.Strings[82184]="废墟里有一只骑着大猫的幽灵。"
D.Strings[82185]="北边有一条古老的蓝龙。如果说还有人了解创世之柱的话，那肯定就是他了。"
D.Strings[82186]="我还感觉到那个方向有一股强大的魔力——那可能就是你找到的那头龙。我们得立刻调查一番。"
D.Strings[82187]="我昨天去找了棺材铺老板。太有意思了！"
D.Strings[82188]="昨晚城堡里有灯光。你们看见了吗？"
D.Strings[82189]="你们见过死尸吗？我见过。"
D.Strings[82190]="前几天，爸爸抓到了一条双头鱼。它全身都是紫色的，还软塌塌的。"
D.Strings[82191]="姐姐不让我再晚上出去钓鱼了。我一点乐趣都没有了。"
D.Strings[82192]="是的，大君。在我们说话的时候，营地已经准备好了。"
D.Strings[82193]="你可以同时去解决你和凯恩的事。"
D.Strings[82194]="我们的力量无可匹敌。这些生灵无法抵抗我们的猛攻。"
D.Strings[82195]="我们控制的土地日益扩大。那个秘密很快就将属于我们。"
D.Strings[82196]="真是个精致的星球。这里的居民也很……脆弱。"
D.Strings[82197]="纳萨诺斯的游侠们发射了|TInterface\\Icons\\inv_ammo_arrow_04:20|t |cFFFF0404|Hspell:182466|h[瘟疫箭]|h|r。将蛮天领主引到他们附近去！"
D.Strings[82198]="纳萨诺斯的游侠们发射了|TInterface\\Icons\\inv_ammo_arrow_04:20|t%s |cFFFF0404|Hspell:182466|h[瘟疫箭]|h|r。将蛮天领主引到他们附近去！"
D.Strings[82199]="啊！去死吧，恶魔！"
D.Strings[82200]="无论你是谁，帮帮我，求你了！"
D.Strings[82201]="这边！求你救救我！"
D.Strings[82202]="以艾露恩的名义！救救我！"
D.Strings[82203]="所有主炮，等我们突破云层后进行第二轮齐射。"
D.Strings[82204]="烟雾阻止不了我，可怜虫！"
D.Strings[82205]="老太婆吓唬不了我！"
D.Strings[82206]="哈！那个婆婆瞎得像只蝙蝠！"
D.Strings[82207]="这应该很疼吗？"
D.Strings[82208]="%s解决了受害者，然后又去寻找新的猎物了。"
D.Strings[82209]="是那个叛徒王子派你来的吗？随便吧，我不会手下留情的！"
D.Strings[82210]="我……我干了什么？"
D.Strings[82211]="%s扑向新猎物。"
D.Strings[82212]="我不会对这些平民动手的。他们不知道我是谁，对我也没有威胁。"
D.Strings[82213]="我必须让他们听从我的劝解，而不是我的剑。新手常常会诉诸武力，但劝说才是高手的武器。"
D.Strings[82214]="|cFFFF0000%s|r正在制造能量，强化他的盟友！"
D.Strings[82215]="|cFFFF0000%s|r的能量正在被吸干！"
D.Strings[82216]="迄今为止，你的领导一直很出色，$n——我看不出有转变方向的必要。"
D.Strings[82217]="我要去达拉然寻找有资格加入我们事业的圣骑士。骑士们，留在这里，以防$n在我离开时有什么需要。"
D.Strings[82218]="他们应该已经到——啊，他们在那儿呢。"
D.Strings[82219]="愿艾露恩祝福我，让我百发百中！"
D.Strings[82220]="入侵者，世界不会毁在你们手里的！"
D.Strings[82221]="入侵者！这是卡多雷的土地。"
D.Strings[82222]="你们摧毁了无数世界，但我们不会轻易倒下。"
D.Strings[82223]="以艾萨拉的名义，滚出这里！"
D.Strings[82224]="我们刀剑锋锐，箭矢劲疾。我们可不是软柿子。"
D.Strings[82225]="吃我一刀。"
D.Strings[82226]="谁都别想阻拦我们前进的步伐。"
D.Strings[82227]="以主人的名义！"
D.Strings[82228]="你休想再看见明天的月亮。"
D.Strings[82229]="埃德尔鲁！你看这件衣服怎么样？"
D.Strings[82230]="看来像是暗夜精灵的服装……等等……"
D.Strings[82231]="不对……那是古代上层精灵的款式！"
D.Strings[82232]="虽然我和堕夜精灵看起来很相似，但他们是卑鄙扭曲的魔瘾患者，会为了一口魔力而在背后捅你刀子。而我是一个友好的裁缝，只是因为世道艰难所以堕落了而已。注意其中的差别！"
D.Strings[82233]="我们是不会坐视燃烧军团威胁我们的家园的。我们的剑任你调遣。"
D.Strings[82234]="来吧，尹西丢斯！让这些蠢货看看燃烧军团的力量！"
D.Strings[82235]="我们随时听从圣光的召唤。需要我们时，请告诉我们一声。"
D.Strings[82236]="汪汪！"
D.Strings[82237]="%s可怜巴巴地哀鸣着。"
D.Strings[82238]="赶快行动吧。我们必须在燃烧军团再次发动攻击前找到他们。"
D.Strings[82239]="我们得快一点了。燃烧军团随时可能发动攻击。"
D.Strings[82240]="请随便挑。"
D.Strings[82241]="我会在这里耐心地等待，直到收到达拉然的召唤。"
D.Strings[82242]="不要忘了我，还有我的贡献！"
D.Strings[82243]="不能再浪费时间了。我们走！"
D.Strings[82244]="我需要召唤一个人到达拉然。你愿意帮我吗？"
D.Strings[82245]="召唤？当然！你说他在哪儿来着？"
D.Strings[82246]="稍等……在那儿！我找到他了！"
D.Strings[82247]="$n！很高兴再次见到你！"
D.Strings[82248]="所以……这就是达拉然。"
D.Strings[82249]="你这家裁缝店真棒。介意我四处看看吗？"
D.Strings[82250]="当然不介意。请随意。"
D.Strings[82251]="我相信我们有很多可以互相学习的地方。"
D.Strings[82252]="谢谢你，$n。在进一步训练你之前，我得先……熟悉一下这家店。"
D.Strings[82253]="欢迎来到卡蒂亚精品珠宝店，$c。我看得出来，你是个有品味的客人。$b$b今天你想看点什么呢？"
D.Strings[82254]="我想看看贵重点的首饰，谢谢。"
D.Strings[82255]="我听说你可以帮我把这些针磨尖。"
D.Strings[82256]="搞定！告诉坦妮瑟娅，她又欠我一个丝绸枕头了。"
D.Strings[82257]="小事一桩……"
D.Strings[82258]="目前这样应该就可以了。我想我应该……再多了解一下你们的城市。"
D.Strings[82259]="你觉得你能挑战我了吗，小鬼？真是个可悲的决定。"
D.Strings[82260]="狮鹫骑士，支援他们！"
D.Strings[82261]="<咳>英雄！<咳咳>把那些化学信号弹弄走！"
D.Strings[82262]="接受你的死亡吧。它是苦涩的，可比起即将降临的灾难，还是要好多了。"
D.Strings[82263]="上一个反抗我的英雄最后死在了我的脚下。去跟她做伴儿去吧。"
D.Strings[82264]="你侵犯了我们的领土。你将为此付出沉重的代价。"
D.Strings[82265]="月神宽恕我，让我安息吧。"
D.Strings[82266]="你……赢得了这场战斗，但你在我眼里还是……一个可怜虫。"
D.Strings[82267]="那些该死的织魔者没有权力把我赶出来。我说了，完全没有！"
D.Strings[82268]="林达斯，你在这里做什么？"
D.Strings[82269]="我的主人会了解到今天所发生的一切并且明白……你不过是……一点小麻烦。"
D.Strings[82270]="我欢迎黑暗。我总是……喜欢……黑夜。"
D.Strings[82271]="灰烬使者闪耀着明亮的光芒，用|cFFFF0000|Hspell:642|h[圣盾术]|h|r保护了你！"
D.Strings[82272]="呃……我只是在……寻找新染料。对，就是这样，新染料。我马上就回店里去。"
D.Strings[82273]="命运在召唤你，$n。"
D.Strings[82274]="我发誓，我绝对不乱走。我不会再去城里转悠了。呆在裁缝店里我就已经很开心了。"
D.Strings[82275]="林达斯，拜托，快住手！控制下情绪，伙计！"
D.Strings[82276]="一个来自银色北伐军的侍从？在这儿？"
D.Strings[82277]="父亲，住手！陌生人，请原谅我们。这年头，我们对陌生人都有点过于紧张了。"
D.Strings[82278]="荆棘是绿叶的防御手段：否则娇美的红花就会变得无助。$B$B不要诅咒荆棘。你应该感激它们保住了美丽的花朵。"
D.Strings[82279]="当内心动摇时，我们就不会再敬畏周围的世界。$B$B自然就是映照出我们灵魂的镜子。"
D.Strings[82280]="你将和其他人一样化为枯骨！"
D.Strings[82281]="分享我们的诅咒吧！"
D.Strings[82282]="你永远都别想打败血须！"
D.Strings[82283]="我们很幸运。要是地底之王解开了圣锤的全部秘密，我们就没法站在这里说话了。$b$b他现在就像一个得到了新玩具的孩子，虽然危险，但只要持有圣锤的时间不长，就不算致命。"
D.Strings[82284]="快点挖！我们必须在其他挑战者抵达前埋掉这个大家伙。"
D.Strings[82285]="和月光林地一样，这个村子和它的村民都是受我保护的。我只希望我能庇护更多的野生生物以及荒野的守护者们。$B$B真希望我能足够强大到保护你们所有人。"
D.Strings[82286]="我从未见过这些元素之灵如此狂躁。"
D.Strings[82287]="关于这些蓟叶林精，你能告诉我点什么？"
D.Strings[82288]="愿奥丁的祝福指引你的道路。"
D.Strings[82289]="你可以在这里休息一下，不必担心梦魇的侵扰。"
D.Strings[82290]="蓟叶林精一直都是个小麻烦，但是他们最近的行为已经从轻率幼稚发展到了恶意破坏。$B$B我不知道是什么导致了这种变化，但我们必须做点什么来保护这些精灵龙。"
D.Strings[82291]="奥丁？我不跪拜任何神灵。"
D.Strings[82292]="我会尽力的。"
D.Strings[82293]="如果你还知道好歹的话，就离紫罗兰监狱远点，$r。被关在里面的某些生物让我感觉很不安。"
D.Strings[82294]="你看见林达斯了吗？"
D.Strings[82295]="他就是那只堕夜老鼠吗？我们发现他在镇子外围探头探脑的，看起来很可疑。他已经被扔进紫罗兰监狱去接受审问了。"
D.Strings[82296]="只要我拿到阿格拉玛之盾——诸神都将跪倒在我的脚下。"
D.Strings[82297]="我们古枝部族对我们土地知之甚少。$B$B你真是太好了，竟然大老远赶来帮助我们。"
D.Strings[82298]="就是现在，我的战士们！英灵殿就在前方！"
D.Strings[82299]="你们的军力太单薄了，凡人。而我们的大军则无穷无尽！放下武器，臣服于萨格拉斯吧！"
D.Strings[82300]="死亡毫无荣耀可言！你们的城市将化为火海，你们的大军将四分五裂。这是早已注定的命运！"
D.Strings[82301]="从缺口那里冲进去！让这些蝼蚁看看受萨格拉斯的力量加持的军队有多么势不可挡！"
D.Strings[82302]="我知道你的目的，女妖之王！你最好立刻离开，否则就将引来我的怒火！"
D.Strings[82303]="若敢拒绝，我便强行拿走你的力量。"
D.Strings[82304]="愚蠢的丫头！你正试图染指你无法想象的力量。"
D.Strings[82305]="你这份傲慢会将你葬送，正如那个创造了你的人一样。"
D.Strings[82306]="我们会及时拿到阿格拉玛之盾的——我们决不能错过这个消灭希尔瓦娜斯的机会！"
D.Strings[82307]="吉尔尼斯要伸张正义！"
D.Strings[82308]="希尔瓦娜斯将为她的罪行付出代价……"
D.Strings[82309]="你联络上舰队了吗？"
D.Strings[82310]="没用——风暴峡湾外围的气候带太强了。我的信号没法穿透。"
D.Strings[82311]="你不应该在这儿的，$n。"
D.Strings[82312]="其他人都在谈论一个擅长缝纫的$r$c。我猜你就是那个$c。$b$b如果泰塔洛认为你已经准备好了。那我可以让你看看女王的优雅织布机。"
D.Strings[82313]="这——这是什么力量？！这……不可能……"
D.Strings[82314]="给我介绍一下这台织布机吧。"
D.Strings[82315]="老实说，织布机本身没什么特别的。$b$b当然，它很漂亮。它已经非常古老了，但它的核心也不过是赤杨木和几根钉子而已。我们已经在尽全力保护它了。$b$b但织布机本身对我们工艺并无帮助。"
D.Strings[82316]="你可真细心。是的，我们的组织与一位大人物达成的协议，以便通过交易获得更多的技术。$b$b我已经准备好向你展示我们的秘密了。看吧，这就是织魔者的力量！"
D.Strings[82317]="泰塔洛还提到了某种献祭。"
D.Strings[82318]="让我看看你的秘诀吧。"
D.Strings[82319]="我和他可不一样！看吧！"
D.Strings[82320]="快点干！决不能让一件圣物落入凡人之手！"
D.Strings[82321]="把这个世界的秘密从地下挖出来！燃烧军团要榨干这里的每一分力量。"
D.Strings[82322]="这是你的姐姐海拉的礼物。现在……跪下！"
D.Strings[82323]="我们去兜兜风吧！"
D.Strings[82324]="我们和古尔丹达成的协议。我们为他和他的部队提供补给，作为回报，他会派几个更加强大的审判官给我们。"
D.Strings[82325]="当然，我还是倾向于织魔者独立运作，不要任何人的协助，但这种灌注了恶魔力量的布料已经超出了我们的能力范畴。"
D.Strings[82326]="我们是裁缝，$n，你也是。如果能做出更好的长袍，那就应该不惜一切代价去争取。不是吗？"
D.Strings[82327]="我已经告诉了你灌魔丝纹布是怎么织成的，我也给了你灌魔丝纹护腕的图样。"
D.Strings[82328]="爱诺达和我可以帮忙，但我们不可能把你需要的所有图样都教给你。你得自己挣，或者从其他人那里买。"
D.Strings[82329]="这个世界上还有许多其他的织魔者。我可以把他们的下落告诉你。"
D.Strings[82330]="我的亮眼睛！我的！我的！我的！我的！"
D.Strings[82331]="在外面的时候小心点！"
D.Strings[82332]="我该去哪里学习灌魔丝纹长袍的制作方法？"
D.Strings[82333]="我该去哪里学习灌魔丝纹兜帽的制作方法？"
D.Strings[82334]="我该去哪里学习灌魔丝纹腰带的制作方法？"
D.Strings[82335]="我该去哪里学习灌魔丝纹便鞋的制作方法？"
D.Strings[82336]="我该去哪里学习灌魔丝纹手套的制作方法？"
D.Strings[82337]="我该去哪里学习灌魔丝纹马裤的制作方法？"
D.Strings[82338]="我该去哪里学习灌魔丝纹肩饰的制作方法？"
D.Strings[82339]="我该去哪里学习灌魔丝纹斗篷的制作方法？"
D.Strings[82340]="织魔者米索贾尼就在这座大厅外面，他手里有这个图样。"
D.Strings[82341]="你应该去跟苏拉玛南部码头区的织魔者乔佳娜谈谈。我来帮你把她的位置标记在地图上。"
D.Strings[82342]="去找织魔者爱伦伊吧。她现在正在瓦尔莎拉研究德鲁伊的服装式样。我来帮你把她的位置标记在地图上。"
D.Strings[82343]="去跟织魔者亚菲斯泰娅谈谈吧。她正在至高岭的山路上徘徊。我来帮你把她的位置标记在地图上。"
D.Strings[82344]="我相信织魔者阿西斯托手里有这个图样。你可以在这里的西边，俯瞰邪魂堡垒的地方找到他。我来帮你把他的位置标记在地图上。"
D.Strings[82345]="正在风暴峡湾旅行的织魔者特鲁米是负责维护这个图样的行会成员。我来帮你把她的位置标记在地图上。"
D.Strings[82346]="肩甲是织魔者法索杜斯最擅长的领域。他喜欢在阿苏纳暴露的魔网附近消磨时光。我来帮你把他的位置标记在地图上。"
D.Strings[82347]="算你走运，我就可以教你这些图样。$b$b但这可不是免费的。由于客户的要求很高，所以我们店里的布料消耗很大。"
D.Strings[82348]="好的，多少钱？"
D.Strings[82349]="我对你不感兴趣。我来自苏拉玛的一个声名远播的裁缝世家。而你显然不是。"
D.Strings[82350]="真是意外！一个裁缝同行！$b$b欢迎来到苏拉玛的织魔者行会。你可能已经听说过我们了？"
D.Strings[82351]="你好，织魔者。我能为你做点什么吗？"
D.Strings[82352]="过场动画"
D.Strings[82353]="笨龙！你会付出代价的。"
D.Strings[82354]="我都焦了，但还活着。我们损失了不少人。"
D.Strings[82355]="稳住！守住阵线，否则米奈希尔就会陷落！"
D.Strings[82356]="前线崩溃了！守住，我相信援军马上就会到了！"
D.Strings[82357]="稍后再为他们哭泣吧，我们得在更多恶魔抵达之前离开这儿。"
D.Strings[82358]="瓦里安的部队应该已经在这座丘陵附近登陆了，但愿他们能走运一些。"
D.Strings[82359]="我从没见过恶魔扩张得这么快。"
D.Strings[82360]="我也没见过。情况有变，这支燃烧军团不再是我们曾经击败过的那一支了。"
D.Strings[82361]="真是……奇特。"
D.Strings[82362]="很简洁，但有一种典雅的魅力。"
D.Strings[82363]="嘿，看看这个！"
D.Strings[82364]="我比较喜欢深V字型的领口。"
D.Strings[82365]="你这个褶边的设计让人眼前一亮。但这张图样嘛……一口价，不要就算了。"
D.Strings[82366]="这一定很好玩！"
D.Strings[82367]="我真的很喜欢这个图样，$n。虽然只是沿用了经典款式，但上面的刺绣真是太独特，太迷人了。"
D.Strings[82368]="$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TINTERFACE\\ICONS\\ACHIEVEMENT_BOSS_ILLIDAN.blp:40|t$b你是最忠诚的伊利达雷成员。你要充当我的耳目，直到事件解决。"
D.Strings[82369]="让我们去追风吧！"
D.Strings[82370]="快点！再快点！"
D.Strings[82371]="龙，你要付出代价！"
D.Strings[82372]="紧急迫降！"
D.Strings[82373]="好了好了，费隆纳斯。基尔加丹战刃就是为了消灭恶魔而铸造的。你没有机会的。"
D.Strings[82374]="你只是第一个。你其他的同胞很快也会步上你的后尘。我，瓦雷迪斯·邪魂，将成为你们的终结者。"
D.Strings[82375]="你好，旅行者。我们的林地曾经是个宁静的地方，但利爪德鲁伊们已经尽力保护这里了。"
D.Strings[82376]="这不可能。他们人太多了。"
D.Strings[82377]="达拉然的街道非常安全，我向你保证。所以不必惊讶会有人攻击这些……东西。"
D.Strings[82378]="噢！那一定很疼！"
D.Strings[82379]="扔得好！"
D.Strings[82380]="你逃不掉的！"
D.Strings[82381]="恶魔！让我看看你的本事吧！"
D.Strings[82382]="燃烧军团万岁！去死吧，没用的$r！"
D.Strings[82383]="我们好像也没那么强大，不是吗？"
D.Strings[82384]="是时候解决瓦雷迪斯了。我已经安排了一只魔蝠在克拉苏斯平台等着你，它会送你去邪魂堡垒的。"
D.Strings[82385]="你们太迟了！主人的计划早就启动了。"
D.Strings[82386]="对！对！我要品尝你的恐惧，将它扭曲成活生生的噩梦！"
D.Strings[82387]="我……看不见了！"
D.Strings[82388]="守住，联盟！今天我们绝不会倒下！把他们赶回传送门里去！"
D.Strings[82389]="瓦里安！"
D.Strings[82390]="来，试试这个图样吧。你可以用我们的材料！在店里找找就有。"
D.Strings[82391]="既然你已经找齐了所需的材料，就到我的精加工台上制作吧。"
D.Strings[82392]="那是什么？你的线是怎么回事？长袍怎么冒烟了？"
D.Strings[82393]="真是场灾难。看，线从布料里跑出来了，我从没见过这种情况。"
D.Strings[82394]="做好准备，英雄。那个畜生下来了！"
D.Strings[82395]="我们成功了！这片林地里的迷你猫头鹰安全了，谢谢你。"
D.Strings[82396]="我们欠你一份大人情！要不是你，刚才那最后一下就会把我们赶进水里去了。"
D.Strings[82397]="这些箱子里都装满了补给品。看来你或许能比我们更好地利用它们。"
D.Strings[82398]="救命！我们要被赶进海里去了！"
D.Strings[82399]="噢，感谢圣光！我们一直就守在这里，和米奈希尔失去了联系！"
D.Strings[82400]="他们又来了！拿起武器！帮我们击退他们！"
D.Strings[82401]="不……又来了！"
D.Strings[82402]="这简直是没完没了……他们人太多了！"
D.Strings[82403]="瓦雷迪斯身边守卫森严。我们得破坏那道屏障的结界。"
D.Strings[82404]="你被发现了。冲过去！快！"
D.Strings[82405]="没有时间降落了。你得直接潜入战场。去吧！"
D.Strings[82406]="阿格拉玛之盾是属于我的！"
D.Strings[82407]="你们竟敢来打扰我，废物？别用你们那贫乏的脑瓜臆测燃烧军团的力量！"
D.Strings[82408]="这不……可能……"
D.Strings[82409]="你想挑战我？我要像碾碎虫子一样碾碎你！"
D.Strings[82410]="我要杀……了你……呃！"
D.Strings[82411]="不是只有你在找阿格拉玛之盾。我建议你快点行动。"
D.Strings[82412]="没用的，弹药着火了！快，上楼！"
D.Strings[82413]="让我来处置他们，主人。"
D.Strings[82414]="恶魔猎手闯入了我的地盘，指挥官。这是不可容忍的。"
D.Strings[82415]="击败其他挑战者，我才会考虑让你接受试炼。"
D.Strings[82416]="把我死去兄弟的遗骸带回来给我，我就让你进去地窟。"
D.Strings[82417]="奥丁，请赐予我力量完成你的旨意吧。"
D.Strings[82418]="我的蜘蛛将吸食你的骨髓。"
D.Strings[82419]="|TInterface\\Icons\\achievement_character_human_female.blp:40|t列队射击……"
D.Strings[82420]="哈哈哈……你的战斗意志很顽强。那个废物兽人永远别想加入我们的行列。"
D.Strings[82421]="你太迟了。英灵殿很快就将属于燃烧军团。"
D.Strings[82422]="我很乐意把你们这些废物赶出我们的新家园。"
D.Strings[82423]="|TInterface\\Icons\\achievement_character_human_female.blp:40|t这下是为了吉尔尼斯！"
D.Strings[82424]="|TInterface\\Icons\\achievement_character_human_female.blp:40|t打倒他……"
D.Strings[82425]="啊……这下好多了。关于你，奥丁已经有计划了，我的朋友。"
D.Strings[82426]="到宝库里来见我。你的试炼即将开始。"
D.Strings[82427]="快一点！我要坚持不住了。"
D.Strings[82428]="快行动！这只能坚持一小会儿！"
D.Strings[82429]="你的第一个试炼现在开始。保护好你自己！"
D.Strings[82430]="我认输……我现在明白为什么奥丁会垂青你，而不是神王了。你可以继续你的试炼了。"
D.Strings[82431]="我不是你的敌人，镇长。我是来黑鸦堡垒找人的。"
D.Strings[82432]="别再花言巧语了，暗夜精灵。你必须呆在我们眼皮底下，我们会盯着你的。"
D.Strings[82433]="<长剑在你头顶盘旋。>"
D.Strings[82434]="吉恩，吉安娜，你们没事，太好了。"
D.Strings[82435]="别让他们进入火山。通向军团诸界的钥匙决不能落入他们手中，贝尔艾什。"
D.Strings[82436]="你们很清楚自己应该呆在里面。都过来！"
D.Strings[82437]="继续。这一次，呆在这里。"
D.Strings[82438]="大人们太笨了。"
D.Strings[82439]="真是淘气鬼。别担心：我会盯着他们的。"
D.Strings[82440]="你真刻薄！"
D.Strings[82441]="好了好了。他们就是安静不下来。"
D.Strings[82442]="接受祝福"
D.Strings[82443]="我的利刃在渴望燃烧军团的鲜血。你明白这种饥渴的感觉吗？你是否想要使出浑身的力气去消灭燃烧军团呢？\n\n别浪费你我的时间了。燃烧军团每多存在一秒钟都显得多余。"
D.Strings[82444]="<将水晶丢入池塘。>"
D.Strings[82445]="我很高兴你能来，$n。\n\n现在，来解决我们的问题吧。"
D.Strings[82446]="我的艾瑞达正在召唤更多恶魔抄他们的后路，陛下。"
D.Strings[82447]="解决这些蝼蚁，贝尔艾什。"
D.Strings[82448]="这是一个泰坦构造体！它肯定是在守护希尔瓦娜斯想找的东西。"
D.Strings[82449]="看来我们又落后了一步。我们必须尽快行动！"
D.Strings[82450]="这个世界充满了导火索……烈焰的风暴降临了，凡人！"
D.Strings[82451]="希尔瓦娜斯勉强脱身，让她最新招募的黑暗瓦格里来和你战斗！"
D.Strings[82452]="该死！让那个女妖巫婆跑了！格雷迈恩不会高兴的……"
D.Strings[82453]="我们拆掉这个可怕的机器吧。至少我们可以防止希尔瓦娜斯再造出一支瓦格里大军……"
D.Strings[82454]="克罗雷将炸药装在机器上。"
D.Strings[82455]="简报"
D.Strings[82456]="我这就回营地去。你去把我们的发现告诉格雷迈恩。快，$c，这个地方马上就要塌了！"
D.Strings[82457]="我在天上被迎头痛击了……幸好我的鸟没事。帮我去狠狠干掉几只恶魔，好吗？"
D.Strings[82458]="我已经瞄准敌人！"
D.Strings[82459]="我看见了。那些眩晕手雷扔得好，$G小子:丫头;！"
D.Strings[82460]="我不可能打偏的！"
D.Strings[82461]="打中一个，它太招摇了。"
D.Strings[82462]="啪！正中面部！"
D.Strings[82463]="有谁想吃一箭吗？"
D.Strings[82464]="一箭爆头，小菜一碟。"
D.Strings[82465]="手到擒来。"
D.Strings[82466]="过来，靠近点，让我好好看看你。$B$B啊！一个$c，千里迢迢跑来这里？我的女神！"
D.Strings[82467]="我们得立刻前往圣光之愿礼拜堂。大领主弗丁完全有资格与那里的古代圣光勇士一同长眠。"
D.Strings[82468]="<这个桶很适合用来给织物染色。>"
D.Strings[82469]="将琥珀染料倒入染料桶。"
D.Strings[82470]="给丝纹布染色。"
D.Strings[82471]="<这个桶很适合用来给织物染色。你要制作的图样需要混合绿色染料和硫磺屑。>"
D.Strings[82472]="将绿色染料和硫磺屑倒入燃料桶。"
D.Strings[82473]="裁缝店的坦妮瑟娅需要一些硫磺屑来制作图样。"
D.Strings[82474]="硫磺？她要这种东西做什么？嘁，裁缝的怪癖。来，拿着。"
D.Strings[82475]="你要开始准备染料桶了。绿色染料就在架子上，但你得去铁匠铺的奥拉尔德·施米尔那里要点硫磺屑。"
D.Strings[82476]="暂时就要这些了。我们继续下一步吧。"
D.Strings[82477]="我们会想你的，兄弟。"
D.Strings[82478]="大领主提里奥·弗丁咽下了最后一口气。"
D.Strings[82479]="我差点就被体内的邪能控制了。"
D.Strings[82480]="与艾希迪尔沟通"
D.Strings[82481]="你面前的雕像属于斯考德-艾希尔的女武神领袖。\n\n她的脸看起来有些眼熟……"
D.Strings[82482]="尝试与雕像沟通。"
D.Strings[82483]="萨维斯的力量太强大了。我不知道我们该怎么对抗他的梦魇。"
D.Strings[82484]="梦魇的腐蚀已经渗入了河水中。$B$B站好了，$c，我要召唤艾露恩的力量来净化这条河。"
D.Strings[82485]="但愿这能有用，德鲁伊。"
D.Strings[82486]="传送领主倒下了，它的传送门暴露了出来！（点击传送们，发光表示已损坏）"
D.Strings[82487]="燃烧军团入侵了研究站！英雄们，到我身边来。我们必须不惜一切代价保护肯瑞托！"
D.Strings[82488]="邪能领主倒下了，燃烧军团撤退了！我们暂时击退了他们，但还是得保持警惕。"
D.Strings[82489]="艾希迪尔告诉了你有关瓦格里的情况。"
D.Strings[82490]="佩妮洛普？感谢月神，你没事！我担心死了！"
D.Strings[82491]="我们几小时前就该离开了……但至少我们还有这些酒，不是吗？"
D.Strings[82492]="再来上几杯，我没准都敢上战场了。"
D.Strings[82493]="你们的搅局到此为止了，凡人。交出圣物，否则燃烧军团就把你们烧成灰烬，从你们的骨灰里找出来！"
D.Strings[82494]="我真的希望他们还活着。如果我们找不到他的小女儿，镇长肯定会心碎的。"
D.Strings[82495]="你用信号枪打晕那些鸟，我就能干掉它们了。"
D.Strings[82496]="我们的大军无穷无尽！"
D.Strings[82497]="圣物属于我们！"
D.Strings[82498]="我们可以在这里处理研究站的防务。英雄们，关闭传送门，切断他们的攻击线！"
D.Strings[82499]="面对审判吧！"
D.Strings[82500]="圣光是永远不会抛弃你的。"
D.Strings[82501]="沐浴在圣光的荣耀中吧。"
D.Strings[82502]="我们万众一心！"
D.Strings[82503]="要是它还有气，就让它解脱吧。"
D.Strings[82504]="这些土地必将落入我们的掌心。"
D.Strings[82505]="废物！这里就不能有点挑战性吗？"
D.Strings[82506]="这个世界将在燃烧军团的脚下四分五裂！"
D.Strings[82507]="脆弱的生物满足不了燃烧军团的要求！"
D.Strings[82508]="希望才是你唯一的敌人。"
D.Strings[82509]="没有比祂更伟大的存在了，凡人。你们迟早会明白的……"
D.Strings[82510]="几百年来，你们一直在我们的世界中扮演着不速之客的角色。"
D.Strings[82511]="联盟很快就会追上我们，而我们无路可退。"
D.Strings[82512]="别质疑我，纳萨诺斯。去吧——带上这位英雄，到永恒号上去。"
D.Strings[82513]="把你们的计划告诉我，小鬼！"
D.Strings[82514]="女王陛下，我们得优先考虑您的安全。我们应该留下几艘船——"
D.Strings[82515]="好，遵命。来吧……“英雄”。"
D.Strings[82516]="我要把你撕成碎片！"
D.Strings[82517]="把我们的守军组织起来殿后。蝙蝠骑手升空，投石车准备！"
D.Strings[82518]="我们知道你在找什么东西。快老实交代！"
D.Strings[82519]="一张显示你目前军力状况的破碎群岛地图。"
D.Strings[82520]="查看地图。"
D.Strings[82521]="不……萨维斯的污染太强了。"
D.Strings[82522]="你是谁？后退——我要用生命来保护女王陛下！"
D.Strings[82523]="艾萨拉女王……背叛了我们……"
D.Strings[82524]="我被引回这个地方，并一度误以为你是敌人。小心，英雄。这个地方充斥着躁动的幽灵。"
D.Strings[82525]="肮脏的恶魔！你们不是部落的对手！"
D.Strings[82526]="试试我的迫击炮吧。我来为你们指出目标！"
D.Strings[82527]="主人，我以你的名义而战！"
D.Strings[82528]="拉文凯斯大人早已过世，可我始终视他为导师。"
D.Strings[82529]="我们俩似乎都闲逛了一段时间了。你想要个伴儿吗？"
D.Strings[82530]="很高兴在这里见到你，$n。要搭车吗？"
D.Strings[82531]="这里可不是单独闲逛的好去处，$n。让我护送你一程吧。"
D.Strings[82532]="拉文凯斯大人指定我担任艾萨拉女王的私人保镖。"
D.Strings[82533]="高塔在召唤，但我害怕它的声音。快，解放我们，否则就迟了！"
D.Strings[82534]="[向前走。]等等，这是什么？他的墓穴被人动过！他的骨灰不见了！"
D.Strings[82535]="孩子们，抓住他们。"
D.Strings[82536]="激活全部三座传送门，召唤剩余的部队。"
D.Strings[82537]="跟我来，大领主。从现在起，你要使用指挥地图来调遣你的部队。"
D.Strings[82538]="嗯？我能帮你什么忙吗，$n？"
D.Strings[82539]="灰烬使者……我已经好久没见过那把剑了。你要代表圣光保护我们的世界，$n。"
D.Strings[82540]="这片土地上有许多力量祭坛，它们可以让灰烬使者变得更加强大。在你的旅途中顺便找出它们，你就将真正成为一股举足轻重的力量。"
D.Strings[82541]="大领主，不要偏离圣光的道路，它就不会抛弃你。带上我的祝福吧，你永远都不会孤军奋斗。再见。"
D.Strings[82542]="你竟敢进入我的圣殿！来面对我吧！"
D.Strings[82543]="傲慢！燃烧军团绝不容忍这种挑衅！"
D.Strings[82544]="滚开，爬虫们！你们的死期到了！"
D.Strings[82545]="你好，<artifact>的持有者。我是天角部族的代表。$b$b"
D.Strings[82546]="天角部族愿意加入梅拉·高岭的队伍吗？"
D.Strings[82547]="是时候夺回属于我们的土地了！"
D.Strings[82548]="“多亏”了高岭部族的惨败，鹰身人现在开始攻击我的族人了。天角部族不可能两线作战。"
D.Strings[82549]="他们的盾牌太坚固了！守卫者们，自由攻击！"
D.Strings[82550]="这么说你就是<artifact>的主人。我还以为你会再高一点呢。$b$b在你面前的是大使怒牛。$b$b我是伟大的鲜血图腾部族的喉舌，我们掌握着大地的力量，是至高岭有史以来最强大的战士。"
D.Strings[82551]="鲜血图腾部族愿意加入梅拉·高岭的队伍吗？"
D.Strings[82552]="哈！高岭部族连自己的酋长都保不住，还想让我加入他们？鲜血图腾崇尚的是实力，不是牺牲。"
D.Strings[82553]="<artifact>的持有者？这真是莫大的荣幸。$b$b我是白水部族的代表。"
D.Strings[82554]="河鬃部族愿意加入梅拉·高岭的队伍吗？"
D.Strings[82555]="我不得不怀着沉重的心情拒绝你的提议。卓格巴尔正在攻打我们的家园。我是来求援的，可梅拉帮不了我们。"
D.Strings[82556]="$r发出咯吱咯吱的呻吟，为了准备战斗而积聚力量。"
D.Strings[82557]="%s捡起怨灵脉冲器，检查它的能量储备。完好无损！"
D.Strings[82558]="干得好，英雄。现在，让我们赶在敌人之前重整队伍吧。"
D.Strings[82559]="<显然这个勇敢的灵魂是因为捕捉某种危险的存在而死的。>$B$B<她的枪就躺在边上。你敢捡起它然后继续调查吗？>"
D.Strings[82560]="这些鸟都是从黑鸦堡垒那儿来的。这已经是我今天打下来的第四只了。"
D.Strings[82561]="这到底是什么野兽？"
D.Strings[82562]="哨兵们，让我们掩护他们！"
D.Strings[82563]="血风！攻击这个异教徒！"
D.Strings[82564]="我要这些牛头人滚出我的山脉。"
D.Strings[82565]="在做出决定之前，先仔细查看一下铁砧吧。不要着急，不要仓促地做出决定！"
D.Strings[82566]="你知道吗，他们以前叫我“坏脾气的玛莱恩”。我能在一百步外打掉钉子的头。"
D.Strings[82567]="我的女儿就是我的一切。多亏你将她安全地带回家来，我真不知道该怎么感谢你了。"
D.Strings[82568]="擦亮你们的剑，战士们！不要让一头恶魔跨过大门。"
D.Strings[82569]="主人命令我们……"
D.Strings[82570]="滚回你的墓穴里去！"
D.Strings[82571]="永远加入我们吧……"
D.Strings[82572]="堡垒绝不会陷落……"
D.Strings[82573]="见鬼！又卡住了！"
D.Strings[82574]="这绝对能让恶魔们大吃一惊！"
D.Strings[82575]="你以为你能夺回这片土地吗？我们能抢到它，就一定能守住它。"
D.Strings[82576]="要我说的话，这绝对是个明智的选择。现在我们需要一个更加强大的铁砧来进一步升级这把武器了，不过我会找到的。我向你保证！"
D.Strings[82577]="恶魔……哈！恶魔可吓不住我！"
D.Strings[82578]="我虽然个子小，但我无所畏惧！"
D.Strings[82579]="来尝尝我的厉害吧，恶魔！"
D.Strings[82580]="离开山顶时你会丢掉怨灵脉冲器。"
D.Strings[82581]="这山上的情况相当糟糕！我会尽可能保住制空权的。"
D.Strings[82582]="别担心，朋友们。我已经掌握了哨兵岭上空的制空权！"
D.Strings[82583]="抱歉了，恶魔们！哨兵岭的天空属于我们！"
D.Strings[82584]="哨兵岭上空的恶魔似乎越来越稀疏了。我会继续巡逻，直到我们彻底安全为止！"
D.Strings[82585]="看来一切都结束了，朋友们！我会再守护哨兵岭一段时间的。"
D.Strings[82586]="射击的时候不要眨眼！"
D.Strings[82587]="我们与鹰身人的战争还在继续，但你的行动让盆地的局势稍微平衡了一点。\n\n随着莫拉舒的灵魂重生，他将再次引导其他动物回归大自然。"
D.Strings[82588]="看，这就是霜之哀伤的剑柄。你可以用它制造出天下无双的神剑！去吧，灌入你的力量，制造属于你的武器吧。"
D.Strings[82589]="拿起武器，伙计们！"
D.Strings[82590]="进入阵地！"
D.Strings[82591]="求求你……还有其他人！我们失散了……你一定要救出他们！"
D.Strings[82592]="噢，谢谢你。谢谢，英雄！"
D.Strings[82593]="我们为什么会遇到这种事？这都是什么东西？"
D.Strings[82594]="各位，请保持冷静。援兵已经到了。我们会保护你们的！"
D.Strings[82595]="我们不会让他们通过的！只要留在这里，你们就是安全的！"
D.Strings[82596]="我们感觉很不安全！外面出什么事了？"
D.Strings[82597]="一切都完了……就这样了。你还指望能阻止他们吗？"
D.Strings[82598]="我是听到救援了吗？进来，请快进来！"
D.Strings[82599]="如此软弱，如此美味！我吃饱了！"
D.Strings[82600]="噢，感谢圣光！拜托了，你一定要留下来保护我们！"
D.Strings[82601]="我跟你去，还能多杀几个恶魔。"
D.Strings[82602]="我是……不会……屈服的！"
D.Strings[82603]="够了！我要亲手抽出你们的灵魂！"
D.Strings[82604]="太虚弱了……快控制不住……我的力量了。"
D.Strings[82605]="我要杀光你们。"
D.Strings[82606]="我要听到你骨头碎裂的声音！"
D.Strings[82607]="这座山脉属于我们！"
D.Strings[82608]="这是卓格巴尔的岩石！卓格巴尔的！"
D.Strings[82609]="救援总算到了！赞美艾露恩！"
D.Strings[82610]="在燃烧军团的力量面前颤抖吧！"
D.Strings[82611]="及时行乐吧，凡人……你们死到临头了！"
D.Strings[82612]="终于……这个可悲世界的末日降临了！"
D.Strings[82613]="对……挣扎吧……你们卑微的挣扎只会逗乐我！"
D.Strings[82614]="没有人能从梦魇中醒来！"
D.Strings[82615]="把他们碎尸万段……榨干这些凡人的生命力！"
D.Strings[82616]="祈祷吧……让那可悲的女神听到你们的哀嚎吧！"
D.Strings[82617]="莎拉达希尔……这不可能……这不是真的！"
D.Strings[82618]="我感觉你力量更强大了，$n。你窃取了恶魔的精华吗？"
D.Strings[82619]="好像整座森林都在跟我们作对……"
D.Strings[82620]="只要我还有一口气在，就要保护好这座森林！"
D.Strings[82621]="已经没希望了……但我要战斗到底！"
D.Strings[82622]="你真好。"
D.Strings[82623]="太感谢了。"
D.Strings[82624]="但愿我将来能报答你的恩情！"
D.Strings[82625]="你真是帮了我大忙了，$n。谢谢你。"
D.Strings[82626]="小心，兄弟们！我们被发现了！"
D.Strings[82627]="我要亲自对付这个跳梁小丑。"
D.Strings[82628]="这……毫无意义。你……微不足道。"
D.Strings[82629]="我们会再次崛起……我们的大军将比繁星更多。"
D.Strings[82630]="你们是在为一个……已经注定失败的世界……而战。"
D.Strings[82631]="梦魇不仅仅是幻象。它源自……你们最黑暗的……真相。"
D.Strings[82632]="懦夫，蝼蚁！你们应该被烧死！"
D.Strings[82633]="呃！他们抢走了蜡烛！"
D.Strings[82634]="我的蜡烛！为什么要抢？"
D.Strings[82635]="冷静点，蠢货！别再亵渎圣殿了！"
D.Strings[82636]="拾取"
D.Strings[82637]="嘘……安静，别把他们引过来了！"
D.Strings[82638]="你自己去找个地方躲起来！"
D.Strings[82639]="等结束之后再来找我吧！"
D.Strings[82640]="别吵了！你会吸引他们注意的！"
D.Strings[82641]="这里已经有人了！如果你不介意的话……不要把我的行踪泄露出去！"
D.Strings[82642]="终于来了一堆有资格上柴堆的鲜肉了！"
D.Strings[82643]="协议：灵魂收割已激活！"
D.Strings[82644]="侦测到灵魂。正在收割中。"
D.Strings[82645]="收割……失败。"
D.Strings[82646]="$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TINTERFACE\\ENCOUNTERJOURNAL\\UI-EJ-BOSS-King Ymiron.blp:50:80|t$b你有足够的力量来拿起马格纳·破冰者的武器吗？让我们拭目以待……"
D.Strings[82647]="$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TINTERFACE\\ENCOUNTERJOURNAL\\UI-EJ-BOSS-King Ymiron.blp:50:80|t$b有资格继承马格纳·破冰者遗产的人终于出现了。$b如果你想获得他的传奇武器，就跟我来……并且活下去……"
D.Strings[82648]="一名第七军团战斗法师将投石车冻成了冰块！"
D.Strings[82649]="你看起来不太对劲啊，$n……你还好吗？"
D.Strings[82650]="$n，谢谢你能来……"
D.Strings[82651]="我准备好前往马格纳的岛屿了。"
D.Strings[82652]="总算有人来帮我们了，如果你们愿意暂时搁置往日的分歧的话。"
D.Strings[82653]="让我们联手吧。如果我们在这时候争斗，只会便宜了恶魔。"
D.Strings[82654]="我不跟杀人犯合作。不管在什么时候，迪菲亚兄弟会都不值得信赖！"
D.Strings[82655]="你们这些高高在上的家伙比恶魔还不如！"
D.Strings[82656]="那么……凶手是谁？"
D.Strings[82657]="怎么？冥狱深渊的英雄想进入地窟？"
D.Strings[82658]="我承认你的实力。我允许你觐见艾尔。"
D.Strings[82659]="你可以进去了，但记住，艾尔可能另有想法。"
D.Strings[82660]="去拥抱命运吧，$n。愿艾尔赐予你双翼。"
D.Strings[82661]="$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TINTERFACE\\ICONS\\Ability_Warlock_EmpoweredImp.blp:50:80|t我闻到了这扇门背后的力量！我们把它挖开吧！"
D.Strings[82662]="$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TINTERFACE\\ICONS\\Ability_Warlock_EmpoweredImp.blp:50:80|t哎哟，好痛！我需要帮助！"
D.Strings[82663]="女士们先生们，拜托！拜托！我们正在尽一切努力处理目前的情况。"
D.Strings[82664]="大家尽管放心，哨兵岭的防御固若金汤！"
D.Strings[82665]="燃烧军团绝对攻不破我们的防线。我向大家保证！"
D.Strings[82666]="请听我说。眼下，恶魔正在我们的攻势下节节败退！"
D.Strings[82667]="女士们先生们，我们在城墙内非常安全，完全没有必要恐慌。"
D.Strings[82668]="这些蠢货竟敢登上我的船。上！"
D.Strings[82669]="让艾尔制裁你！"
D.Strings[82670]="艾尔，指引我的长矛！"
D.Strings[82671]="你不配获得晋升！"
D.Strings[82672]="我的盾绝不动摇！"
D.Strings[82673]="你只是我的又一次试炼！"
D.Strings[82674]="艾尔，赐予我双翼……"
D.Strings[82675]="英灵殿在等待……"
D.Strings[82676]="这是……光荣的死亡……"
D.Strings[82677]="我的盾没有……碎……"
D.Strings[82678]="战斗开始了，姐妹们！"
D.Strings[82679]="保护神殿！"
D.Strings[82680]="撞个头破血流吧！"
D.Strings[82681]="决不能让神殿陷落……"
D.Strings[82682]="艾尔……我失败了……"
D.Strings[82683]="我们得开战。可不带礼物就贸然上门是不礼貌的……药剂师那里有我们要的东西。"
D.Strings[82684]="是时候将我遗产交给某个有能力拿起它们的人了。在我的试炼中活下来，你就将获得这个世界上最强大剑和盾……"
D.Strings[82685]="黑龙的守护是什么？"
D.Strings[82686]="你知道大地守护者奈萨里奥吗？他曾是一头威严的野兽……直到迎来他的堕落。在那个年代，除了诸神，没有人能伤到他。马格纳年轻时很崇拜他。\n\n尽管马格纳希望成为和他一样无敌且值得尊敬的战士，马格纳还是想出了一个傲慢的计划。他要突袭奈萨里奥的巢穴，从他的传奇宝藏中捞一票。\n\n马格纳和他的军团与奈萨里奥的幼龙们激战了一番。当他们进入巢穴时，正遇上了归来的巨龙。巨龙瞬间横扫了整支大军。马格纳抢到一片他蜕下的鳞片，用它护住了自己，然后滚到了山脚。"
D.Strings[82687]="所以除了一片龙鳞，他什么都没留下？"
D.Strings[82688]="只是一片龙鳞？哈！那可是这个世界最难被杀掉的巨龙的鳞片！\n\n马格纳意识到了自己的丰厚收获。他花了几年时间向泰坦族裔和维库人中的大师学习锻造。当他终于有了足够高超的技艺之后，他将这枚鳞片打造成了一对无与伦比的盾牌和长剑。这就是黑龙的守护。在正确的人手中，它们就能发挥出大地守护者本人的力量和无懈可击的防御能力。\n\n直到今天，我仍然无法确定，他究竟是足够幸运，才从那一战中活了下来，还是黑龙觉得他有资格活下来。"
D.Strings[82689]="肮脏的狼人……野兽就是野兽。"
D.Strings[82690]="亡灵骑兵们，多拿几瓶，然后向我靠拢！我们要击落那艘飞艇！"
D.Strings[82691]="我准备好接受试炼了。"
D.Strings[82692]="多刺激的狩猎，它将是我下一部小说里的精彩篇章。"
D.Strings[82693]="$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TINTERFACE\\ENCOUNTERJOURNAL\\UI-EJ-BOSS-King Ymiron.blp:50:80|t$b你就是那个人，让它们因你而荣耀，你也因它们而荣耀。我终于可以前往英灵殿了。在那里，将有无尽的战斗等待着勇敢的战士。"
D.Strings[82694]="新指令：追随燃烧军团。摧毁所有资产。"
D.Strings[82695]="劈砍，燃烧，收割！"
D.Strings[82696]="虽然我拿着的是书而不是步枪，但我向你保证，$n，我是天生的猎手。"
D.Strings[82697]="$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TINTERFACE\\ENCOUNTERJOURNAL\\UI-EJ-BOSS-Selin Fireheart.blp:50:80|t$b[凯恩·日怒]不要退缩，$n，让他看看你的怒火。"
D.Strings[82698]="$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TINTERFACE\\ICONS\\Warlock_Summon_DoomGuard.blp:50:80|t$b我在这儿，匹利克！是什么虫子把你吓跑啦？！？滚出来，爬虫，否则我就踩扁你！"
D.Strings[82699]="$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TINTERFACE\\ICONS\\Warlock_Summon_DoomGuard.blp:50:80|t$b我们在破碎海滩还没把你们彻底消灭吗？我这就来纠正这个错误！"
D.Strings[82700]="$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TINTERFACE\\ENCOUNTERJOURNAL\\UI-EJ-BOSS-ARCHIMONDEWOD.blp:50:80|t$B[毁灭者塔尔达斯]傲慢的废物！立刻放了我，我或许还能饶你们一命。"
D.Strings[82701]="蠢货！你竟敢独自面对我？！"
D.Strings[82702]="瓦雷迪斯会杀光你那些恶心的同类。可惜你已经看不到那一天了。"
D.Strings[82703]="双刃……会毁了你的……"
D.Strings[82704]="蝼蚁！主人掌握着超出你想象的力量！他会杀了你的！"
D.Strings[82705]="只要稍微动一下就够了。"
D.Strings[82706]="肉眼可见的一点点材料……"
D.Strings[82707]="制作药水需要非常精细的操作。"
D.Strings[82708]="白天做药水，晚上也做药水。"
D.Strings[82709]="如果是小病的话，只需要一点点这个……剂量翻倍的话……恐怕就只能用于歪门邪道了。"
D.Strings[82710]="唔……多么美妙的香气。"
D.Strings[82711]="守住阵地！让他们看看，这点小巫术是打不垮我们的。"
D.Strings[82712]="这家伙死得真惨。玛维也不在这里。"
D.Strings[82713]="“虽然我们努力尝试榨取情报，但这个守望者仍在顽固抵抗。”他们说的是玛维吗？"
D.Strings[82714]="那是玛维的武器！她来过这儿！"
D.Strings[82715]="瓦格里之母艾尔，我给你一个自愿投降的机会。"
D.Strings[82716]="上古之战初期，我们损失惨重，无数城市化为火海。"
D.Strings[82717]="拉文凯斯大人让我们的人民和这个世界逃过一劫。"
D.Strings[82718]="他的逝世是个悲剧。我们欠他的……太多了。"
D.Strings[82719]="你们要找那守望者？太迟了！"
D.Strings[82720]="拉文凯斯大人，我誓死效忠你。"
D.Strings[82721]="我对拉文凯斯大人的忠诚绝不动摇！"
D.Strings[82722]="我临死才看清真相。你不是敌人。"
D.Strings[82723]="你休想进入拉文凯斯大人的塔楼！"
D.Strings[82724]="你将和其他人一样被投入监狱。"
D.Strings[82725]="亡灵们过来了！拿起武器！"
D.Strings[82726]="你和你的姐姐是怎么失散的？"
D.Strings[82727]="她干了什么？"
D.Strings[82728]="那你为什么还想要救她？"
D.Strings[82729]="我和玛维选择了完全不同的人生道路。$B$B燃烧军团首次败走艾泽拉斯之后不久，她就决定终生追求正义的事业。$B$B有时，人们会觉得她对于正义过于偏执了。"
D.Strings[82730]="为了断绝我们的人民与联盟的关系，她谋杀了无辜者。$B$B可是，我仍然无法说服自己去杀害她。$B$B一开始，我觉得这是因为软弱——这份感情让我没法去做我应该做的事。"
D.Strings[82731]="我了解我的姐姐。她不可能犯下这种罪行，除非是受到了某种邪恶的影响。$B$B即便如此，我还是在没有彻底调查清楚的情况下就做出了最坏的推断。$B$B我是个糟糕的弟弟，但现在还来得及纠正我的错误。"
D.Strings[82732]="我会帮你找到玛维。"
D.Strings[82733]="白女士，请将你的光辉赐予我，让我净化萨维斯留在这些水中的邪恶腐蚀。"
D.Strings[82734]="弟弟。你来救我了。即使我想要杀了——"
D.Strings[82735]="愚蠢的德鲁伊。你那位女神的力量是如此可怜。看看萨维斯的力量吧！"
D.Strings[82736]="我们过不去的！你疯了吗？你看到那些东西没有？"
D.Strings[82737]="普莱奥姆说得对。那些东西会碾碎我们的！我们只有五个人！"
D.Strings[82738]="我们被彻底孤立了。我们得等待援军！"
D.Strings[82739]="够了！我可忍受不了这种懦夫的行径。"
D.Strings[82740]="如果我们在这里待得太久，就死定了。艾伦，睁大你的眼睛，寻找救援！只要一看到援军，我们就立刻行动！"
D.Strings[82741]="中士！我听到外面有动静。可能是我们的援军到了！"
D.Strings[82742]="太好了！所有人，举盾！我们冲出去！列队！"
D.Strings[82743]="我们不能……让萨维斯……逍遥法外！我们必须前往莎拉达希尔……彻底了结这个恶魔！"
D.Strings[82744]="我到前面去等你……我们必须尽快行动！"
D.Strings[82745]="不！我们必须继续前进……这个世界已经危在旦夕！"
D.Strings[82746]="下面的，打得好！空中支援来啦！"
D.Strings[82747]="肃清战场上的恶魔，我们就会向你提供攻击堡垒所需的狮鹫！"
D.Strings[82748]="那座堡垒是不会自己毁灭的！在农场上清理出一块降落场来，我们这就给你弄几头突袭所需的狮鹫过来！"
D.Strings[82749]="如果我没记错的话……离这里附近就有一座岗哨。"
D.Strings[82750]="烂喙就在西北边，过了码头就是。把它的脑袋带来给我！"
D.Strings[82751]="我会搜遍这座岛屿，找到了解创世之柱的人，以我的荣誉起誓。"
D.Strings[82752]="你应该集中精神完成主人交给你的任务。"
D.Strings[82753]="燃烧军团必将失败。"
D.Strings[82754]="我已经跟对方谈妥了，我们可以进入那头老龙的巢穴了。"
D.Strings[82755]="我在那儿等你。"
D.Strings[82756]="北边盘踞着一头上古蓝龙。他是最有可能知道创世之柱消息的人。"
D.Strings[82757]="我要杀掉所有挡路的恶魔。"
D.Strings[82758]="一次小挫折而已。我保证不会再有下一次了。"
D.Strings[82759]="毁灭！"
D.Strings[82760]="入侵者，你死到临头了。"
D.Strings[82761]="军团征服一切。"
D.Strings[82762]="你犯了大忌，凡人。"
D.Strings[82763]="多汁的骨髓，酥脆的骨头。"
D.Strings[82764]="抽出你灵魂中的邪能。"
D.Strings[82765]="快，抓住他们！"
D.Strings[82766]="又是一顿送上门来的美餐。"
D.Strings[82767]="救命！这里有坏人！"
D.Strings[82768]="我们将啃食你的血肉，吞噬你的灵魂。"
D.Strings[82769]="嘿！这不是你该来的地方。"
D.Strings[82770]="又有美味的肉吃了。"
D.Strings[82771]="快去警告蛛后！"
D.Strings[82772]="我要烧穿你的膝盖。"
D.Strings[82773]="你掌握的邪能还不够。"
D.Strings[82774]="你竟敢在这里袭击我们？！"
D.Strings[82775]="为了蛛后泰兰娜。为了军团！"
D.Strings[82776]="站着别动，让我一枪打死你！"
D.Strings[82777]="让我们看看你的盾牌能不能挡住子弹吧！"
D.Strings[82778]="你为什么总是这么模糊呢？"
D.Strings[82779]="萨维斯已经主宰了这片森林，$c。走进它的人都将臣服于梦魇。"
D.Strings[82780]="抱歉……"
D.Strings[82781]="<这个恶魔猎手的脸色像鬼魂一样苍白，身体无法控制的颤抖着。>"
D.Strings[82782]="是奥顿派我来的。你自由了。"
D.Strings[82783]="当时我们正在追踪一个恐惧魔王。不幸的是，他将我们引入了陷阱。"
D.Strings[82784]="<这名伊利达雷的尸体已经几乎面目全非了。他受到了严刑拷打，最终伤重而死。>"
D.Strings[82785]="祝你好运，等解决了这个恶魔，我就去据点。"
D.Strings[82786]="奈瑟兰达姆斯，飞到天上去。如果有敌人接近就警告我们。"
D.Strings[82787]="快！大德鲁伊的情况已经很严重了……"
D.Strings[82788]="完成仪式"
D.Strings[82789]="快用坩埚完成仪式吧。"
D.Strings[82790]="送我去最近的登陆场！"
D.Strings[82791]="我觉得我们可以提供一些帮助。"
D.Strings[82792]="我们当中只有少数同胞有这个能力，但我没有空手而归。"
D.Strings[82793]="即使像我们这么强大，从法罗纳尔的表现来看，我们也无法独自阻止那些恶魔。"
D.Strings[82794]="我会召集所有勇敢的同胞追随你进入战场，做我们应该做的事。"
D.Strings[82795]="在我们最困难的时刻来了一个勇士。欢迎你。"
D.Strings[82796]="那些哀伤尖塔保护着贝尔艾什。你得先关闭它们。"
D.Strings[82797]="这混蛋将守卫引入了牢笼。他必须为此付出代价！"
D.Strings[82798]="你们竟敢袭击卡多雷贵族？就算求饶我也不会放过你们。"
D.Strings[82799]="你总是自视太高。既然你坚持，那我也不介意再死一个蠢货。"
D.Strings[82800]="这仅仅是个开始。"
D.Strings[82801]="都搞定了，伙计们！这里还多出来几头狮鹫。休息一下，然后准备突袭堡垒！"
D.Strings[82802]="指挥官已经下令了！让我们清理出一片降落场来！"
D.Strings[82803]="星眼，想让我求饶是不可能的。你现在该明白了吧。"
D.Strings[82804]="拉文凯斯大人让我守住这里。我不会把它让给你们恶魔的！"
D.Strings[82805]="拉文凯斯？这不可能！我们不是恶魔。你不认识我了？"
D.Strings[82806]="没用的，弟弟。和其他亡灵一样，他已经认不出我们了。"
D.Strings[82807]="别在意，我听说了守望者地窟的事。好在我已经债多不愁了。"
D.Strings[82808]="你干嘛非要独自追杀古尔丹？感谢艾露恩你还活着。"
D.Strings[82809]="说得好，弟弟，我们还有正事呢。走吧。星眼会付出代价的。"
D.Strings[82810]="快，完成召唤仪式。"
D.Strings[82811]="军团的意志必将实现。"
D.Strings[82812]="干掉那个伊利达雷。"
D.Strings[82813]="为了蛛后。"
D.Strings[82814]="我们的仪式被打断了。"
D.Strings[82815]="保护传送门。"
D.Strings[82816]="以萨格拉斯之名。"
D.Strings[82817]="狩猎小队是来帮着射杀那只该死的鸟的！"
D.Strings[82818]="你休想阻止梦魇的蔓延！"
D.Strings[82819]="奥图里斯说你只要最精锐的部队，所以我们来了。"
D.Strings[82820]="盾牌上雕刻了一位女武神的女神，在战场上守护着她们。\n\n在她的头上刻着一个名字“艾尔”。"
D.Strings[82821]="这片盾牌似乎描绘了斯考德-艾希尔的战士们需要经历的各种试炼。\n\n而盾牌中间则是附近的神殿。"
D.Strings[82822]="这块盾牌上刻了一位女武神，跪在一根精美的长矛前。\n\n神殿的女祭司就站在不远处，默默观察着整个仪式。"
D.Strings[82823]="这面盾牌上的场景是一位女武神在一位古代斯考德-艾希尔勇士的雕像上方盘旋。\n\n这位女武神光环缠身，背后还有金色的双翼。"
D.Strings[82824]="在这面盾牌上，刻着艾尔站在一个泰坦宝库的入口处。\n\n她似乎正在迎接一名背生双翼的女武神勇士进入宝库。"
D.Strings[82825]="这片盾牌描绘了一个背生双翼的女武神托起了一个倒在战场上的维库人的尸体。\n\n而这位女武神的形象却和瓦格里出奇的相似。"
D.Strings[82826]="我们一定会找到燃烧军团的传送门，哪怕要为此付出生命。"
D.Strings[82827]="别再做戏了，行吗，奥图里斯？"
D.Strings[82828]="恶魔，你们惹错侏儒了！"
D.Strings[82829]="我们的剑已经打磨了数千年。这个世界必将陷落！"
D.Strings[82830]="别让他们进入塔楼！"
D.Strings[82831]="将他们赶出这里！"
D.Strings[82832]="要是让那些恶魔攻占塔楼，那我就太该死了！"
D.Strings[82833]="这个构造体在压力作用下嘎吱作响，最终爆炸并将大量邪能喷上天空。"
D.Strings[82834]="我曾经站出来尽了我的一份力！啊，但那有什么用呢？"
D.Strings[82835]="这是个好地方，风景不错——让我可以独自等待世界末日的到来！"
D.Strings[82836]="我们完了！末日已经到了！我们都很清楚，这个世界完了！"
D.Strings[82837]="你找到它了！谢谢你，旅行者。$B$B<辛德瑞拉顿了一顿。>$B$B经过再三的考虑，我希望你能留下它，让它成为我们这段新友谊的见证。"
D.Strings[82838]="你好，旅行者。我最喜欢的护符掉在了这附近。你能不能帮我找到它？"
D.Strings[82839]="我很乐意帮忙。"
D.Strings[82840]="你必须继续前进——奈瑟兰达姆斯在其他人那儿，我只会拖你的后腿。快走！"
D.Strings[82841]="这真是太刺激了！"
D.Strings[82842]="别担心，我可以一边说话一边开枪！"
D.Strings[82843]="步枪的后坐力总是这么大吗？"
D.Strings[82844]="你让这看起来很简单！"
D.Strings[82845]="这真是个打猎的好日子。"
D.Strings[82846]="再也没有比这更美妙的体验了：微风送来松树的清香，还有一大堆猎物可供我们狩猎。"
D.Strings[82847]="$n来了。为了伊利达雷！"
D.Strings[82848]="救命！求求你！"
D.Strings[82849]="求你，救救我！"
D.Strings[82850]="他们不会放过我的……"
D.Strings[82851]="如果你救我出去，我愿意为你效劳！"
D.Strings[82852]="我真不该一个人跑出来！"
D.Strings[82853]="我不想就这么死掉……"
D.Strings[82854]="燃烧军团必败。"
D.Strings[82855]="我的战刃在渴望燃烧军团的鲜血！"
D.Strings[82856]="你前进得太莽撞了。"
D.Strings[82857]="很快你就会求我能给你一个痛快！"
D.Strings[82858]="我可不相信拿着枪的侏儒。\n\n相比她的目标，艾迪更有可能打中你。"
D.Strings[82859]="它……它肯定就在这附近！"
D.Strings[82860]="可能是被水冲走了……"
D.Strings[82861]="掉到哪儿去了呢？"
D.Strings[82862]="塞纳留斯的角在上！它跑哪儿去了？"
D.Strings[82863]="你从来都不听长老的话吗，$c？但没关系，至少你救了我的命。$B$B让我歇一会儿。我会好起来，等一会儿就行。"
D.Strings[82864]="我会没事的，$c。回去吧。这笔账必须我亲自来算。"
D.Strings[82865]="算账？别傻了。你伤得很严重。"
D.Strings[82866]="噢呵呵。看上去真棒。我找到了一些新的猎物。"
D.Strings[82867]="原来你在临死前跑到这头……这头野兽这儿来了。"
D.Strings[82868]="能亲手杀了你会让我很愉快的。"
D.Strings[82869]="你真应该听他的……小心，$c。"
D.Strings[82870]="这口古代月亮井已经风光不再了，但它的水依然散发着艾露恩的月光。"
D.Strings[82871]="后退。我不用你帮忙。"
D.Strings[82872]="即使这片林地已经被莎拉达希尔给腐蚀了，它仍然是我们的家园。$b$b我们要和它同呼吸共命运。"
D.Strings[82873]="其实你没必要这么做，但我还是要谢谢你。"
D.Strings[82874]="拿起这把剑，阿尔萨斯。拥抱你的命运！"
D.Strings[82875]="对……没错……为了复仇，我愿意背负任何诅咒……"
D.Strings[82876]="无礼的狗畜生！"
D.Strings[82877]="你会为此付出代价的！把他的脑袋带来给我！"
D.Strings[82878]="什么？一个入侵者！你休想阻止我，霜之哀伤是我的！"
D.Strings[82879]="拿起武器！邪魂大人不能被打扰。"
D.Strings[82880]="面对我，女妖之王。为你的罪行负责吧！"
D.Strings[82881]="恶魔低估了你。狠狠教训这些狂妄的家伙吧！"
D.Strings[82882]="多管闲事！他的灵魂是我的！"
D.Strings[82883]="啊！这黑暗……我不能……我……"
D.Strings[82884]="施放地狱之火！阻止他们前进！"
D.Strings[82885]="我这就亲手了结你，格雷迈恩！"
D.Strings[82886]="艾萨拉一直小心保守着她的秘密。当我亲眼看到恶魔时，一切都已经太迟了。"
D.Strings[82887]="女王对力量的渴望毁了我们所有人。"
D.Strings[82888]="Ishnu-dal-dieb，旅行者。"
D.Strings[82889]="死亡在等待着……"
D.Strings[82890]="该死，快搞定传送门！保护好结界！"
D.Strings[82891]="谢谢！让我们开始干活儿吧。过来，小猫猫……"
D.Strings[82892]="让黑暗吞噬你！享用被诅咒的灵魂吧！"
D.Strings[82893]="霜之哀伤被摧毁后，逸出的大量灵魂在冰冠堡垒的大厅内游荡，终日痛苦哀嚎。"
D.Strings[82894]="|TInterface\\Icons\\spell_shadow_deadofnight.blp:20|t消灭天灾军团，别让他们被献祭了！"
D.Strings[82895]="使用|TInterface\\Icons\\spell_shadow_antimagicshell.blp:20|t |cFF2959D3|Hspell:184366|h[反魔法护罩]|h|r躲避有害法术！"
D.Strings[82896]="展示"
D.Strings[82897]="人民需要我们。让这些肮脏的怪物为入侵这个世界而懊悔吧！"
D.Strings[82898]="恶魔以为我们是软柿子。今天就让他们看看，卡多雷将抵抗到底。"
D.Strings[82899]="诸位，你们曾宣誓效忠拉文凯斯家族。现在，让我们拿起武器，战斗到底！"
D.Strings[82900]="过来，士兵们！无论面对何种敌人，黑鸦堡垒都不会陷落！"
D.Strings[82901]="坚持住，勇士们！虽然遭遇挑战，但我们不会输的！"
D.Strings[82902]="你已经闹得够久了，凡人。到此为止吧。"
D.Strings[82903]="又来了一个囚犯？看来我得先打垮你！"
D.Strings[82904]="有入侵者！快敲响警钟！"
D.Strings[82905]="终于等到这一刻了！"
D.Strings[82906]="到此为止了，入侵者！"
D.Strings[82907]="这世界不适合你，恶魔！"
D.Strings[82908]="你的鲜血也将染红我的长剑！"
D.Strings[82909]="我已杀敌数百。你也只能给我再添一笔战绩而已。"
D.Strings[82910]="我会给你一个痛快的，入侵者。"
D.Strings[82911]="箭无虚发！"
D.Strings[82912]="站住，入侵者。让我先杀了你！"
D.Strings[82913]="我的箭又快又准！"
D.Strings[82914]="再不滚回你们的世界，我就把你碎尸万段！"
D.Strings[82915]="及时行乐吧。你死到临头了！"
D.Strings[82916]="长官已下令处决你。"
D.Strings[82917]="$n……好久不见。你现在该学会别跟我作对了吧？"
D.Strings[82918]="主人赐予了我许多能力。见证欺诈者的力量吧！"
D.Strings[82919]="这边，$c！这里需要你的帮助！"
D.Strings[82920]="我会亲自解决他们的首领，陛下。"
D.Strings[82921]="我差点……就……成功了……"
D.Strings[82922]="欢迎来到铭文师的殿堂！"
D.Strings[82923]="德崔斯说你欠他一个人情。我有一本书需要翻译一下。"
D.Strings[82924]="天角部族，来！"
D.Strings[82925]="哈！这才叫战斗。"
D.Strings[82926]="我想我确实欠那个吹牛大王一个人情。算你走运，我的特长正是翻译！"
D.Strings[82927]="这是一份古代维库人手稿，属于一个名叫“萨维娜”的人。这真是个罕见又有趣的发现。告诉德崔斯，现在是他欠我人情了！"
D.Strings[82928]="我很遗憾奥顿没能挺过来。我一定会让恶魔为他的死付出代价的。"
D.Strings[82929]="谁敢对抗燃烧军团的力量？"
D.Strings[82930]="来吧，勇士。让我们推翻这个巫后。"
D.Strings[82931]="你去对付巫后。我们来解决她的子嗣。"
D.Strings[82932]="我终于能安息了。"
D.Strings[82933]="那就看你的了。"
D.Strings[82934]="奎尔萨拉斯绝不会陷落！"
D.Strings[82935]="国王虽然已经倒下，但我绝不会抛弃洛丹伦！"
D.Strings[82936]="你们和你们那个王子必须为他对穆拉丁所做的一切付出代价！"
D.Strings[82937]="圣光……不……"
D.Strings[82938]="邪恶的怪物！让圣光的正义怒火撕碎你吧！"
D.Strings[82939]="终……于……安息了……"
D.Strings[82940]="白银之手会将你们的污染从这个世界上抹去！"
D.Strings[82941]="痛苦……结束了……"
D.Strings[82942]="奎尔萨拉斯的士兵们，拿起武器！敌人已经打上门来了！"
D.Strings[82943]="啊，$n。所以巫妖王选择了你？我毫不意外。我们都听过你的事迹。"
D.Strings[82944]="我们的部队已经从诺森德各地赶来。只要一接到命令……相信命令很快就会到……黑锋骑士团就能做好准备。"
D.Strings[82945]="别搞错了，我们跟这个新晋巫妖王毫无瓜葛。但他或许是对抗军团的宝贵盟友。"
D.Strings[82946]="冰冠堡垒的大门就在北边，别让盟友久等！"
D.Strings[82947]="目前，我们和他的目标是一致的。而且，为了我们的利益，要让天灾军团保持……克制。"
D.Strings[82948]="再死一次吧，亡灵渣滓！"
D.Strings[82949]="守望者正在破碎群岛挖地三尺寻找古尔丹。$B$B他们有理由相信，那个术士在黑鸦堡垒里藏了什么秘密。如果他在这里的话，那我的姐姐玛维可能也在。"
D.Strings[82950]="真奇怪……拉文凯斯的大军把我们视为了入侵者。他们就好像被困在了自己的记忆里一样。"
D.Strings[82951]="赛拉和其他守望者正在尽一切努力寻找玛维。$B$B对守望者地窟的袭击是毁灭性的。数百名守望者中，只有少数人活了下来。$B$B但守望者的意志坚如钢铁。他们会坚持下来的。"
D.Strings[82952]="我不信。拉文凯斯大人不可能跟古尔丹合作。"
D.Strings[82953]="我们必须夺回它。他仍然是我的囚犯。我们得攻入塔楼，但这不容易。"
D.Strings[82954]="勇士，先回去处理你的其他事务吧。我们很快就要面对拉文凯斯大人了。"
D.Strings[82955]="杀光他们！为了黑暗女王！"
D.Strings[82956]="交出女妖之王！"
D.Strings[82957]="希尔瓦娜斯！来面对你的送葬者吧！"
D.Strings[82958]="如果有必要，我不惜夷平这座营地！"
D.Strings[82959]="谢谢你，英雄。我没想到会在这里得到救赎。我弟弟呢？"
D.Strings[82960]="滚出来，希尔瓦娜斯！"
D.Strings[82961]="你说我们是怪物？真可笑。"
D.Strings[82962]="怪物！这个世界没有你们的位置！"
D.Strings[82963]="别放水，老家伙！拿出真本事来。"
D.Strings[82964]="我去解决监狱里的卫兵。你去拿钥匙，然后到牢房来见我。"
D.Strings[82965]="啊啊啊……够了！"
D.Strings[82966]="我得留下送他一程。这花不了多少时间。你继续去找玛维吧。"
D.Strings[82967]="送我去鬼雾峰！"
D.Strings[82968]="星眼长官有令，消灭所有入侵者！"
D.Strings[82969]="我们已经守住了城墙，恶魔！你插翅难飞了。"
D.Strings[82970]="我的战锤一定会让你粉身碎骨！"
D.Strings[82971]="啊，你在这儿！"
D.Strings[82972]="到此为止了，恶魔！"
D.Strings[82973]="莫尔葛，上！闹剧该结束了。"
D.Strings[82974]="这里！这里可以出去。我们得在敌人重新集结之前离开这里。"
D.Strings[82975]="真是个悲剧。即使在死后，他也只想保护我们的人民。"
D.Strings[82976]="我的部队就是你的部队。"
D.Strings[82977]="我们会帮忙建造火山要塞的。"
D.Strings[82978]="灰舌死誓，前进！"
D.Strings[82979]="亲爱的$g先生:女士;，今天我能为你做点什么吗？"
D.Strings[82980]="哪里能弄到魔火喷灯？"
D.Strings[82981]="哪里能弄到高级木塞？"
D.Strings[82982]="哪里能弄到双胆混合烧瓶？"
D.Strings[82983]="哪里能弄到沉淀粉末？"
D.Strings[82984]="哪里能弄到夏多雷丝绸滤网？"
D.Strings[82985]="哪里能弄到魔息坩埚？"
D.Strings[82986]="哪里能弄到柔韧玻璃软管？"
D.Strings[82987]="哪里能弄到玛洛瑞滴定管？"
D.Strings[82988]="哪里能弄到大容量药剂器皿？"
D.Strings[82989]="我需要人帮忙找一些新的炼金设备来。"
D.Strings[82990]="遗憾的是，我们的炼金台还是很不完善。$b$b我会用我丰富的知识来指点你该替换掉哪些设备，但你恐怕也得做一些跑腿的工作。"
D.Strings[82991]="我听说工程学商店里有人在出售一个喷灯，可能会用得上。你或许能谈出一个比我更合算的价钱！$b$b那家店就在街对面，我可以帮你在地图上标记出来。"
D.Strings[82992]="纳迦以喜欢囤积各种药水而著称，他们那里或许有我们需要的木塞，而最佳搜索地点就是艾萨拉之眼！"
D.Strings[82993]="我们需要一个能够混合更多物质，而不仅仅是试剂的烧瓶。思想、概念、梦想……$b$b你可能得去翡翠梦魇里找这样的烧瓶！"
D.Strings[82994]="据说古代维库人从龙息残渣中收集到了一种粉尘。如果这是真的，那你在位于我们脚下某处的奈萨里奥的巢穴或许会有所发现。"
D.Strings[82995]="这种程度的过滤需要轻巧而有弹性的织物，只有在庄严而强大的地方才有可能找到。当地人提到过一个叫英灵殿的地方……你或许该去调查一下。"
D.Strings[82996]="如此强大的神器应该都收藏在守望者地窟里。据说那里最近出了点麻烦，你要小心点！"
D.Strings[82997]="古代炼金师们都喜欢用自己的炼金器具陪葬。去苏拉玛墓窖里搜索一下或许会有所收获。"
D.Strings[82998]="这种特制的滴定管是由暴风城的炼金师玛洛瑞发明的。我听说紫罗兰监狱里或许收藏着同样珍贵的设备。"
D.Strings[82999]="稀有的收获通常都来自最黑暗、最危险的地方，$n。这样大声说出那个名字真的好吗？到冥狱深渊去吧……如果你敢的话！"
D.Strings[83000]="排队等待地下城"
D.Strings[83001]="排队等待地下城（英雄难度）"
D.Strings[83002]="干得好！帕蒂卡有一个新配方要交给你，$n。"
D.Strings[83003]="主人……我辜负了……你……"
D.Strings[83004]="这真是我经历过的最愉快的一天！"
D.Strings[83005]="该死的海拉！该死的走狗！我要看着她死！"
D.Strings[83006]="猎杀体型十倍于你的猎物时，这感觉超棒的！"
D.Strings[83007]="我们要不要来张自拍？"
D.Strings[83008]="好了，下一个！"
D.Strings[83009]="我现在用起这把步枪来，感觉顺手多了。"
D.Strings[83010]="我也曾是伊利达雷……被丢在黑暗神殿等死。现在，见证我新主人的力量吧！"
D.Strings[83011]="我们不会真的要进去吧？"
D.Strings[83012]="所以，你想要我的脑袋，伊利达雷，是为了夺取双刃？那就让我亲自为你演示……它们的力量吧。"
D.Strings[83013]="加入我！释放你真正的力量。别让弱者拖了后腿！"
D.Strings[83014]="见证欺诈者的力量，见证恶魔的全部实力吧！"
D.Strings[83015]="我是真神！给我跪下！"
D.Strings[83016]="船上挤满了狼人！干掉他们！"
D.Strings[83017]="感受死亡的寒意吧！"
D.Strings[83018]="炸药已经放好了！退到安全距离外引爆它们吧！"
D.Strings[83019]="该死的闯入者！我的计划……全毁了！"
D.Strings[83020]="$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TINTERFACE\\ENCOUNTERJOURNAL\\UI-EJ-BOSS-King Ymiron.blp:50:80|t$b你准备好了吗？让我们看看你的本事吧！"
D.Strings[83021]="我很荣幸，主人！"
D.Strings[83022]="你胜利了！卡德加在监视着这座岛，可恶魔通过某种手段耽搁了我们的传送。我早就该想到，你根本就不需要帮助嘛。"
D.Strings[83023]="只有一艘飞艇？他们疯了吗？"
D.Strings[83024]="他挣扎了一番，但你的大德鲁伊现在归我了……"
D.Strings[83025]="另一个可是激烈地挣扎了一番。"
D.Strings[83026]="也不会是最后一个。连老鼠都知道逃离沉船呢。"
D.Strings[83027]="在把你们的脑袋挂上他的王座之前，瓦雷迪斯大人是不会罢休的！"
D.Strings[83028]="狮鹫来了！快用投石车！"
D.Strings[83029]="很遗憾，这家伙又回过劲儿来了。做好准备。"
D.Strings[83030]="这些瓶子里的混合物极不稳定。只要拔掉塞子，它们就会爆炸。"
D.Strings[83031]="在弹药库附近放上几瓶——这艘船很快就会被炸得四分五裂了。"
D.Strings[83032]="我们会复仇的，但我对那头恶魔口中提到的利刃更感兴趣。"
D.Strings[83033]="都放好之后，到甲板上来见我。我得亲手去杀一个人……"
D.Strings[83034]="想象一下它们具有的力量……这力量足以摧毁燃烧军团。"
D.Strings[83035]="我们在克拉苏斯平台等你。狩猎开始了。"
D.Strings[83036]="打架时间到。"
D.Strings[83037]="让我先喘口气，英雄。多年的警戒已经让我不堪重负了。"
D.Strings[83038]="梦境猎犬转化成了实体！"
D.Strings[83039]="该死！我们成活靶子了！"
D.Strings[83040]="出来，你们这群懦夫……"
D.Strings[83041]="又有外来者闯入了我的领空？！去死吧！"
D.Strings[83042]="我会想办法报答你的，我发誓！"
D.Strings[83043]="无偿营救？你真是个英雄！"
D.Strings[83044]="都结束了吗？我可以回家了吗？"
D.Strings[83045]="见证这对双刃无穷的力量吧！"
D.Strings[83046]="萨德里斯已经看不到明天的月亮了！"
D.Strings[83047]="上古之战后，幸存的萨特被集中到了一起。我据理力争，想要根据他们的罪行处死他们，但我们仁慈的大自然占了上风，我的提议被否决了。$b$b最终，那些萨特被囚禁在莎拉达希尔根须之下，陷入永恒的沉睡。而现在，他们被某种力量唤醒了。$B$B我们不能再犯同样的错误了，如果有必要的话，我会亲手杀了他们！"
D.Strings[83048]="<绍恩咆哮了一声>我们真不该饶了这些萨特的性命。"
D.Strings[83049]="因为议会的短视，我的土地在忍受苦难……"
D.Strings[83050]="我们真不该饶了这些萨特。恶魔都是无可救药的怪物。"
D.Strings[83051]="议会愚蠢地决定将这些萨特放逐到世界之树的根须之下。"
D.Strings[83052]="现在，几千年过去了，某种邪恶的力量接触了他们的束缚，煽动这些恶魔再次跟我们作对。"
D.Strings[83053]="我是不会袖手旁观，看着他们腐蚀我的家园的！"
D.Strings[83054]="我们要纠正过去的错误，杀光这些萨特。我要让他们血债血偿！"
D.Strings[83055]="只要我们齐心协力，就能彻底摧毁这些恶魔。他们绝对没有还手之力。"
D.Strings[83056]="为了世界之树！为了瓦尔莎拉！"
D.Strings[83057]="当天灾军团被献祭给霜之哀伤后，阿尔拉斯就痊愈了！"
D.Strings[83058]="看到我的同胞们安然无恙，我真是松了一口气。那头萨特已经被击败了，但恐怕战斗才刚刚开始。$B$B如果他们说的是真的，那么我们对翡翠梦境的监视依然不能放松，甚至应该比以前更加严密。"
D.Strings[83059]="我早就发现了一些蛛丝马迹，可我被困在了梦境中。要是我能早点警告他们就好了！"
D.Strings[83060]="滚出这里，外来者！"
D.Strings[83061]="过来，勇士！玛洛恩曾亲自祝福过这个凉亭里的火焰。"
D.Strings[83062]="只要摸一下火盆，你的实力就会得到增强，以更好地面对未来的战斗。"
D.Strings[83063]="我敢拿一大笔金币出来，赌她在射中目标之前，肯定会先射中$n！"
D.Strings[83064]="$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TINTERFACE\\LFGFRAME\\LFGICON-SUNWELL.BLP:50:80|t$b你这只傲慢的爬虫，你以为你那可怜的剑刃能伤害得了我吗？"
D.Strings[83065]="$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TINTERFACE\\LFGFRAME\\LFGICON-SUNWELL.BLP:50:80|t$b我没时间来分心处理这只苍蝇。恶魔卫士们，干掉这个家伙！"
D.Strings[83066]="$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TINTERFACE\\LFGFRAME\\LFGICON-SUNWELL.BLP:50:80|t$b够了！你这是在螳臂当车！"
D.Strings[83067]="蝙蝠管理员阿尔泽克召唤了一只尖啸魔蝠去召集附近的燃烧军团部队！"
D.Strings[83068]="多管闲事的狼人，你怎么还不去死。"
D.Strings[83069]="|TINTERFACE\\ICONS\\TRADE_ENGINEERING.BLP:50|t这是玛法里奥外套上的羽毛……他或许就在附近。接着找！"
D.Strings[83070]="|TINTERFACE\\ICONS\\TRADE_ENGINEERING.BLP:50|t又是羽毛……还有打斗的痕迹。必须尽快找到他，不然就迟了！"
D.Strings[83071]="|TINTERFACE\\ICONS\\TRADE_ENGINEERING.BLP:50|t这里有明显的战斗痕迹……可玛法里奥还是不见踪影……"
D.Strings[83072]="好好享受你最后的时光吧，我的毒液会侵蚀你内脏。一想到你将要遭受的痛苦，就让我感到无比的愉悦。"
D.Strings[83073]="让我们离开这里吧，$c。"
D.Strings[83074]="这片土地是不会屈服于你们这种人的。"
D.Strings[83075]="我们的土地不欢迎你们！"
D.Strings[83076]="他们别想抢走我们的土地。我是说真的，伙计。"
D.Strings[83077]="虽然他们有船，可我们有土地、有武器，还有兄弟姐妹。"
D.Strings[83078]="伊瑟拉在攻击月神殿！$b$b我们必须在神殿被彻底摧毁前阻止她……我们没有多少时间了！"
D.Strings[83079]="我准备好保卫神殿了！"
D.Strings[83080]="没有人会害怕燃烧军团。"
D.Strings[83081]="如果他们要战争，我们就给他们战争。"
D.Strings[83082]="这年头，没有人会躲在家里。所有人都会走上战场。"
D.Strings[83083]="我知道，考鲁。我也感应到他们了，但只有弱者才会担忧。燃烧军团是不会成功的。"
D.Strings[83084]="我们早已熟悉了这片土地……"
D.Strings[83085]="感谢你能第一时间赶来。我们的外墙已经承受不了格雷迈恩的下一次炮击了。"
D.Strings[83086]="考鲁，你一定要保持冷静。这是我们的土地。我们的人民……我们是不会失败的。"
D.Strings[83087]="太好了！只要炮击停止，我们就能继续前进了。\n\n现在，我们只需要想办法彻底摧毁他的船……"
D.Strings[83088]="我在这里都能感觉到那剧烈的爆炸！\n\n那个吉尔尼斯混蛋永远都别想搞明白自己是被什么袭击了！"
D.Strings[83089]="被惊扰的坟墓、黑鸦堡垒里的恶魔、还有充满敌意的暗夜精灵，这绝不是巧合。$B$B燃烧军团已经复活了拉文凯斯大人。我曾经的导师又活过来了。"
D.Strings[83090]="压扁这些小人最好玩了。"
D.Strings[83091]="草原猎豹凶猛地保护着它的同胞。"
D.Strings[83092]="真是块美味的鱼排。"
D.Strings[83093]="又可以多一块小鱼饵了。"
D.Strings[83094]="让我们来尝试一下“狂野魔法饮剂”配方，好吗？"
D.Strings[83095]="快过来，$n。这个架子上应该有一些原料。"
D.Strings[83096]="是谁竟敢动我的书？"
D.Strings[83097]="你们休想偷走它的秘密，凡人！"
D.Strings[83098]="你们要为自己的傲慢付出代价！这座城市将化为火海！"
D.Strings[83099]="达拉然在我的保护之下，维库人！滚开！"
D.Strings[83100]="我们会好起来的，大法师，可……看看那个卑鄙的家伙都对我的炼金台做了什么！"
D.Strings[83101]="我们的朋友$n会帮你修好你的宝贝炼金台的，德崔斯。噢，还有，下次摆弄古代遗物时小心点！"
D.Strings[83102]="你又来窃取维库人的秘密了，外来者！"
D.Strings[83103]="我的书里收藏着上千代人流传下来的智慧！"
D.Strings[83104]="为你的罪行忏悔吧！把书还给我的族人！"
D.Strings[83105]="再敢窃取它的秘密，你就要没命了！"
D.Strings[83106]="让诸海之主踩扁你！"
D.Strings[83107]="所以你想告诉我，你不但不能守住地窟，连那个村子都没办法攻克？"
D.Strings[83108]="黑暗女王陛下，这里的维库人比我们预料的要强大得多。"
D.Strings[83109]="对你来说或许算是强大。让我们来看看，他们面对女妖之王时，还能不能这么威风！"
D.Strings[83110]="当然，黑暗女王陛下。"
D.Strings[83111]="海浪和沙砾！"
D.Strings[83112]="你手里是什么？好闪亮的武器。"
D.Strings[83113]="把你做成鲜美的肉排。"
D.Strings[83114]="大海怪来抓你啦！"
D.Strings[83115]="给潮汐的祭品。"
D.Strings[83116]="你不是船上的人！"
D.Strings[83117]="来这边！有入侵者！"
D.Strings[83118]="我建议你给那个可怜的狼人格雷迈恩一个痛快。\n\n可惜我没法亲眼欣赏他临终前的痛苦挣扎了。"
D.Strings[83119]="幸好我在她造成太大的破坏之前就感应到了她的存在。有人受伤吗？"
D.Strings[83120]="把女妖之王交出来！"
D.Strings[83121]="我们要伸张正义！"
D.Strings[83122]="你休想逃脱制裁……"
D.Strings[83123]="格雷迈恩……为我复仇……"
D.Strings[83124]="吉尔尼斯……必将崛起……"
D.Strings[83125]="希尔瓦娜斯休想逃走……"
D.Strings[83126]="长鬃草原狮凶猛地咆哮着，舔着伤口表示臣服。"
D.Strings[83127]="很高兴见到你，$n。愿护路者指引你的道路。"
D.Strings[83128]="我今天还有更重要的事，那就是把货都卖出去，伙计。"
D.Strings[83129]="我们来调配这种药水吧！"
D.Strings[83130]="啊啊啊！为我们的姐妹们报仇！"
D.Strings[83131]="哟！如果你觉得安全的话，我应该可以把外面那台攻城车修好！"
D.Strings[83132]="我来保护你，托丽克斯。让那辆投石车动起来！"
D.Strings[83133]="好的，头儿，但你最好掩护我一下！"
D.Strings[83134]="测探"
D.Strings[83135]="我在这儿呢！祝你顺利拯救世界，头儿！"
D.Strings[83136]="$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TINTERFACE\\ENCOUNTERJOURNAL\\UI-EJ-BOSS-Selin Fireheart.blp:50:80|t$b[凯恩·日怒]快说，恶魔。是谁竟敢猎杀伊利达雷？"
D.Strings[83137]="如果你想出手的话，我可以守在一边，不让任何人打扰。"
D.Strings[83138]="来见见塔尔达斯——史上最强大的艾瑞达之一。你们两个肯定会一见如故的。"
D.Strings[83139]="我们得到想要的东西了。杀了他！"
D.Strings[83140]="$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TINTERFACE\\ENCOUNTERJOURNAL\\UI-EJ-BOSS-Selin Fireheart.blp:50:80|t$b[凯恩·日怒]你的主人是谁？他躲在哪儿？快说，你这该死的家伙！"
D.Strings[83141]="$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TINTERFACE\\ENCOUNTERJOURNAL\\UI-EJ-BOSS-Selin Fireheart.blp:50:80|t$b[凯恩·日怒]干得好。那个蠢货什么都交代了。"
D.Strings[83142]="救命！快去敲响警钟！淤泥沼泽的油井遭到袭击了！"
D.Strings[83143]="我们决不能失去那个油井，伙计们！把炸弹都搬出来！"
D.Strings[83144]="他们在靠近！如果让他们摧毁了压力控制阀，那我们就有大麻烦了！"
D.Strings[83145]="快上来，否则这口油井就完了！炸弹，炸弹，我要炸弹！"
D.Strings[83146]="就差一点了！我这里有东西可以帮你把它粘在油井顶端那些恶魔身上！"
D.Strings[83147]="这可是地精科技的最高杰作。你随便拿，只要能保住我的油井！"
D.Strings[83148]="要爆炸了！快退到安全的地方去！"
D.Strings[83149]="无能者！退下，否则就来尝尝瓦拉加尔的力量吧！"
D.Strings[83150]="可像我这么仁慈的人……一定会让你亲眼看着你的宝贝神殿被摧毁的。"
D.Strings[83151]="<这头白鹿回望着你，明亮的眼睛里透露出赞许。他闪闪发光的白色毛皮是如此耀眼，让你忍不住眨眼。>$b$b<在历史上，很少有人能见到玛洛恩的身影，而且大多是惊鸿一瞥。显然你的英勇事迹赢得了他的青睐。>"
D.Strings[83152]="让我的烈焰吞噬你！"
D.Strings[83153]="$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TINTERFACE\\ENCOUNTERJOURNAL\\UI-EJ-BOSS-King Ymiron.blp:50:80|t$b你已经比大部分人坚持得都要久了。"
D.Strings[83154]="我相信你完全能够胜任这个任务，$n。"
D.Strings[83155]="梦魇入侵了。"
D.Strings[83156]="为了月爪谷！"
D.Strings[83157]="击败了威胁英灵殿和奥丁的恶魔后，你显然已经完成了阿格拉玛之盾的最后试炼。"
D.Strings[83158]="我都告诉过你了，阿历斯泰，我一点都不喜欢这样。你忘了吉尔尼斯的天灾军团暴乱了吗？"
D.Strings[83159]="我从未忘记那场噩梦。如果局势发展到了那一步，我们会再造一艘船。我们有过一次东山再起的经历，再来一次也没什么大不了的。"
D.Strings[83160]="我叫伊崔格别担心了，但我还是觉得很震惊。你就这样拿到了一件强大的神器，还干掉了一个厉害的恶魔领主！"
D.Strings[83161]="蠢货。这座山岭是属于我们的！"
D.Strings[83162]="为了紫喉女王！"
D.Strings[83163]="你不是巫环的对手。"
D.Strings[83164]="我要拿你的尸体去喂我的雏鸟。"
D.Strings[83165]="我要用你的骨头施展出可爱的法术。"
D.Strings[83166]="紫喉会杀光你们所有人的！"
D.Strings[83167]="我刚好为你准备了一个新法术。"
D.Strings[83168]="天空属于紫喉部族！"
D.Strings[83169]="泽菲鲁斯是一个伟大的元素之灵，不是那么容易降服的。即使我们今天赢了，我的人民也还需要更多的理由才会追随你，而不仅仅是因为某件漂洋过海而来的神器。这或许能作为一个象征，让他们视你为领袖的象征。"
D.Strings[83170]="剩下的路必须由你独自走完了。沿着这条路向上，你就能找到苍穹之角。如果你能活下来，我就带着至高岭的天空一起加入你们！"
D.Strings[83171]="是谁在召唤我？"
D.Strings[83172]="来吧，凡人，让我们看看你有什么本事。"
D.Strings[83173]="天角部族不是鹰身人的唯一受害者。\n\n这座山脉里的野生动物都深受这些残酷混乱的女巫之害，没有了莫拉舒引导它们的灵魂，它们将永远无法安息。"
D.Strings[83174]="再跟我说说有关莫拉舒的故事吧。"
D.Strings[83175]="它的尸体上值钱的东西就都归你了，尽管拿。"
D.Strings[83176]="谢谢你！我从没想过会在瓦尔莎拉看见一头恶魔。"
D.Strings[83177]="莫拉舒在这座山脉中活动的历史不亚于任何一个部族。他的存在确保了生死轮回的延续，保证了自然的平衡。\n\n据说莫拉舒会在动物死后引导它们的灵魂。当它们的眼睛失去光彩，莫拉舒就会来到它们身边，引导它们回归大自然的怀抱。"
D.Strings[83178]="吉恩正在休息。$B$B我们得集中精力与舰队取得联系，并前往能够固守的位置。"
D.Strings[83179]="我们以前是不是见过，英雄？$B$B一万年前，我曾经指挥暗夜精灵部队保护这片土地，抗击燃烧军团。$B$B我的姐姐是个守望者，她叫玛维。我是因为她才会来到这里的。"
D.Strings[83180]="我的人民经历过太多的苦难。许多年前，天灾军团的暴动让我们逃离了吉尔尼斯。$B$B现在，亡灵生物又出现在了北边的要塞中。$B$B我要保卫这座村子，直到生命的最后一刻。"
D.Strings[83181]="看，是$n！我早就告诉过你了，$G他:她;肯定会被选中的。现在怎么样？快付钱！"
D.Strings[83182]="快，米妮瓦！我们得撤了。再耽搁下去，莫格莱尼会杀了我们的！"
D.Strings[83183]="阿曼萨加德的学生？呸！好吧，拿走你的金币。"
D.Strings[83184]="啊，一个矿工同行！肯定是妈妈派你来协助我研究这片森林的吧？如果是来通知我断绝母子关系的，那就太棒了！"
D.Strings[83185]="好的好的，迪亚马德，巨龙们都很和蔼可亲，只是暂时不要去打扰他们和我……"
D.Strings[83186]="迪格丝大妈派我来拿你的矿物分析报告。"
D.Strings[83187]="我们已经死了，笨蛋！"
D.Strings[83188]="看来我们没有被通缉，米妮瓦。我猜我们应该继续守住入口。"
D.Strings[83189]="狮鹫骑士们！靠近我！"
D.Strings[83190]="骑士们！去兜一圈。把这艘船炸成碎片！"
D.Strings[83191]="集中攻击凋零使徒号！"
D.Strings[83192]="影歌大人，我错怪你了。大家放下武器！"
D.Strings[83193]="啊，这是给你的，$G小子:丫头;！如果你再见到我妈妈，能不能跟她说一声，就说我的矿镐已经没剩多少了？"
D.Strings[83194]="$n，谢谢你找到我的女儿。请吧，你就是我们的贵客。"
D.Strings[83195]="我真的已经没有什么能教这个小伙子的了。但愿妈妈能派人来接他回去。"
D.Strings[83196]="|TINTERFACE\\ICONS\\inv_ammo_bullet_04:20|t |cFFFF0404|Hspell:190249|h[爆裂弹]|h|r瞄准了你。进入女猎手的近战范围以打断她。"
D.Strings[83197]="$G他:她;醒了！"
D.Strings[83198]="你是个真正的$c，$n。我欣赏你的勇敢。你可不要小看我。在和平年代，我也是很勇敢的。"
D.Strings[83199]="谢谢你的安慰，$n。我很想留下来，但我恐怕要等这里安全一些才会回来了。"
D.Strings[83200]="很抱歉，$n。我可不是害怕。我只是不擅长战斗而已。"
D.Strings[83201]="很好。$G他:她;能战斗吗？"
D.Strings[83202]="等一切都结束之后，我会回来的。"
D.Strings[83203]="我明白你的意思，但我没有战斗的天分，$n。"
D.Strings[83204]="找死吗，精灵？你敢单独面对主人的怒火吗？"
D.Strings[83205]="如果你要走，阿维亚什能送你回雷霆图腾。"
D.Strings[83206]="猜谜结束了！你的灵魂将成为双刃的食物。"
D.Strings[83207]="迪格丝大妈派我来拿你的黑曜石分析报告。"
D.Strings[83208]="大、大、大——大家都去哪儿了？"
D.Strings[83209]="现在安全了。"
D.Strings[83210]="这种油很有前景！把所有的鱼都收集起来，你能拿多少拿多少！熔掉它们的骨头！"
D.Strings[83211]="我都要了！一条鱼都别留下！"
D.Strings[83212]="地精懦夫！滚开！"
D.Strings[83213]="我能从黑曜石里收集到的东西都在这儿了。但愿里面有对你的冒险有帮助的东西。"
D.Strings[83214]="如果你不介意的话，我现在很忙。"
D.Strings[83215]="这块石头的矿物成分真是奇妙……呃……你是谁？"
D.Strings[83216]="矿镐有消息了吗？我这儿只剩最后一把了。"
D.Strings[83217]="在战斗结束前，燃烧军团的鲜血就将染红我的剑。"
D.Strings[83218]="无论如何，他们需要帮助。只要我们保住农场，就能打消他们的疑虑了。"
D.Strings[83219]="时间真的就是金钱吗？还是某种更抽象的概念呢？"
D.Strings[83220]="噢，我的天！这儿还有一个，而且比上一个更大！"
D.Strings[83221]="罗尔！看！看看这些！罗尔？罗尔？罗尔？！"
D.Strings[83222]="这是我体验过的最棒的旅行！我再也不走了！"
D.Strings[83223]="这些孩子……无辜者不应该死在战场上。$B$B如果你有足够的勇气的话，我正需要人护送他们到安全的地方去。"
D.Strings[83224]="我会护送孩子们到安全的地方去！"
D.Strings[83225]="我要把你这些可怜虫狼人撕成碎片，格雷迈恩！"
D.Strings[83226]="很好。跟紧我。"
D.Strings[83227]="死亡在等待着你们所有人！"
D.Strings[83228]="你的生命已经走到尽头了，走狗！"
D.Strings[83229]="保持警惕，$n！燃烧军团正在持续攻击我们的防线。$B$B你可以留下来，看看还剩下什么东西可以慰藉你的痛苦——但记住，如果你要战斗，就得以酋长的名义战斗。"
D.Strings[83230]="冲进宝库去！为了吉尔尼斯！"
D.Strings[83231]="控制……不住了……"
D.Strings[83232]="来吧，希尔瓦娜斯！面对你自己放出的野兽吧！"
D.Strings[83233]="我的笼子还空着呢，完全能装下你们的灵魂。"
D.Strings[83234]="你不是我们的对手，旱鸭子。"
D.Strings[83235]="去死吧，旱鸭子！"
D.Strings[83236]="大海将吞噬你的尸体。"
D.Strings[83237]="这是你死前听到最后的声音了。"
D.Strings[83238]="别把我当成那些头脑简单的白痴。这里可是我说了算的。"
D.Strings[83239]="迪格丝大妈派我来拿你的萨隆邪铁分析报告。"
D.Strings[83240]="潮流变了。"
D.Strings[83241]="你想干嘛？谁派你来的？！你就是那个一直对我窃窃私语的家伙吗？"
D.Strings[83242]="哦，对。这些就是我目前全部的研究成果了。矿石里有……某种……某种东西在对你说话。"
D.Strings[83243]="我得赶快离开这里，免得像这些可怜虫一样变成无脑的奴隶。"
D.Strings[83244]="|TINTERFACE\\ICONS\\TRADE_ENGINEERING.BLP:50|t只要世界之种的树苗能存活下来，我就能帮你去找玛法里奥了。"
D.Strings[83245]="调试完成了，头儿！"
D.Strings[83246]="给她加点油！"
D.Strings[83247]="我来帮你修好这个故障。"
D.Strings[83248]="唔……啊。对了！这样就行了。搞定了。"
D.Strings[83249]="加格，谢谢你来看我，你真是太好了。可今天真不是时候，亲爱的，我们还有一堆恶魔要处理呢！"
D.Strings[83250]="进来，$n，我们还有得忙呢。"
D.Strings[83251]="嘿，莉芙。你在这儿还好吗？"
D.Strings[83252]="如果有什么需要，你知道去哪儿找我的。"
D.Strings[83253]="银色北伐军——冲锋！"
D.Strings[83254]="如此傲慢……一定要教训一下。"
D.Strings[83255]="我明白，可我并不擅长战斗。"
D.Strings[83256]="这里都搞定啦，加兹！"
D.Strings[83257]="都上来，伙计们！让我们骑着这玩意儿离开这儿！"
D.Strings[83258]="这台切割者已经彻底报废了。我需要一台更加迷人的新机器！"
D.Strings[83259]="他们干嘛老是打我？我只是一个地精，驾驶着一台装有火箭的巨型金属机甲而已。"
D.Strings[83260]="巴尔古的灵魂受到了诅咒。他会不断回到死前的那一刻，并将你视为敌人。消灭他。"
D.Strings[83261]="哈拉克的灵魂在霜之哀伤中饱受折磨，最终他诅咒了圣光。去杀了这个家伙。"
D.Strings[83262]="即使被霜之哀伤吞噬，玛古洛斯的灵魂也不肯抛弃圣光。去让他低头认错吧。"
D.Strings[83263]="坚壁清野。我得先解决我们的……客人。"
D.Strings[83264]="作为阿尔萨斯昔日的兄弟，格文拉德最终也被霜之哀伤所吞噬。去让他安息吧。"
D.Strings[83265]="这里的卓格巴尔向来与我们和平共处，某些人甚至还很友好。他们的地底之王究竟做了些什么，使得他们开始针对起我们来了？我也不知道。"
D.Strings[83266]="没有了河鬃部族供应的水产，我们的大山很快就会遭遇饥荒的。"
D.Strings[83267]="虽然至高岭的有些部族看不起我们和平的生活方式，但他们大部分的食物都是我们提供的，我们还能治愈战斗带来的创伤。\n\n那些小崽子们应该学会尊重长者。"
D.Strings[83268]="他们拿不走宝贝。我看着。我等着。我看到他们来了。"
D.Strings[83269]="地狱火！碾碎他们！"
D.Strings[83270]="你别想抢走宝贝！"
D.Strings[83271]="送我去北边的伊利达雷营地！"
D.Strings[83272]="送我去伊利达雷的主营地！"
D.Strings[83273]="冒险者，这个地方能在这个兵荒马乱的时代庇护你。B$B不要害怕天上的那些骑手。他们只是在保护我们，不会伤害你的。当然，如果你先挑衅的话就是另外一回事了。"
D.Strings[83274]="送我去东边的伊利达雷营地！"
D.Strings[83275]="勇士，我们必须坚持住！"
D.Strings[83276]="勇士，我们听从你的命令。"
D.Strings[83277]="恶魔抓走了提里奥！我们得赶快行动。"
D.Strings[83278]="勇士，我会让角鹰兽骑士将阵亡的人送去圣光之愿礼拜堂。你必须继续前行，找到大领主！"
D.Strings[83279]="送我去南边的伊利达雷营地！"
D.Strings[83280]="一只渡鸦飞了过来，在你头顶来回盘旋。它带着一封信！"
D.Strings[83281]="灰色哨所需要你，$G先生:女士;。$B$B你准备好之后就动身吧。"
D.Strings[83282]="送我去灰色哨所。"
D.Strings[83283]="纳萨诺斯要你去惊魂港见他。$B$B可以出发了吗？"
D.Strings[83284]="送我去惊魂港。"
D.Strings[83285]="$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TINTERFACE\\ENCOUNTERJOURNAL\\UI-EJ-BOSS-King Ymiron.blp:50:80|t$b你的耐力很惊人……可我才刚刚开始呢！"
D.Strings[83286]="$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TINTERFACE\\ENCOUNTERJOURNAL\\UI-EJ-BOSS-King Ymiron.blp:50:80|t$b看来你确实比那些二流战士要强一些。是时候来见识一下真正的敌人了！"
D.Strings[83287]="哦不……它上哪儿去了？起疱药水！……不会是被你给喝了吧？"
D.Strings[83288]="它还没有彻底完成呢，如果你觉得头晕的话，注意深呼吸。你没准还会突然晕倒。"
D.Strings[83289]="谁都不是梦魇之王的对手！"
D.Strings[83290]="可怜虫！这诅咒让我比上古半神更加强大！"
D.Strings[83291]="先生，很抱歉，在事情结束之前，我得暂时离开一段时间了。"
D.Strings[83292]="我……我来迟了……"
D.Strings[83293]="月爪……不……"
D.Strings[83294]="没有绍恩，我们就输定了。"
D.Strings[83295]="<艾丽娅忍不住抽泣了起来。>$B$B没有了绍恩·月爪，我都不知道该怎么办才好。"
D.Strings[83296]="好吧，这可真是出人意料。"
D.Strings[83297]="你休想再逃出我的掌心，叛徒！"
D.Strings[83298]="干掉康格拉克斯，再来找我吧！我感觉这儿有个更黑暗的存在……"
D.Strings[83299]="我要用生命保护瓦尔莎拉！"
D.Strings[83300]="滚出我的土地！"
D.Strings[83301]="对……收割它们，一点儿都别留下。"
D.Strings[83302]="轮到我们了！但愿我们这次不会再迷路了。"
D.Strings[83303]="该看看美人了，小东西！"
D.Strings[83304]="你觉得你能抢走我们的金腰带？我们才是冠军！"
D.Strings[83305]="为肩甲附魔。"
D.Strings[83306]="为手套附魔。"
D.Strings[83307]="为靴子附魔。"
D.Strings[83308]="让我们试着调配一个恶魔附魔吧。"
D.Strings[83309]="在死后，一个维库人的价值要由他们伟大的王者来决定。"
D.Strings[83310]="如果你想要圣盾，就去找这些先君，证明你的价值吧。"
D.Strings[83311]="只有被认可的人才能通过勇气试炼。"
D.Strings[83312]="小心点。我看见有虫语者在附近出没。"
D.Strings[83313]="燃烧军团来了！快跑啊！"
D.Strings[83314]="我不记得发生什么事了，可燃烧军团……"
D.Strings[83315]="那些蜘蛛以前就很邪恶，可现在……呃，你马上就会看到了。"
D.Strings[83316]="它们都被燃烧军团控制了！那些蜘蛛……快把我救出去！"
D.Strings[83317]="|cFFFF0000%s|r开始施放|cFFFF0000|Hspell:192754|h[梦魇之息]|h|r！"
D.Strings[83318]="英雄，帮我们解除诅咒吧！"
D.Strings[83319]="完成了。霜之哀伤的碎片铸成的双剑！很快，它们就将畅享敌人的灵魂！"
D.Strings[83320]="我感觉到这两把剑里残留着强大的灵魂。进入幽灵的国度，净化那些胆敢反抗你统御的灵魂！"
D.Strings[83321]="你做得不错。到我的王座前接受任命吧。"
D.Strings[83322]="在弱者施舍怜悯时，你却能杀伐果断。在懦夫一败涂地时，你却能征服一切。"
D.Strings[83323]="此刻，黑锋骑士团已赶往破碎群岛，去追杀那些恐惧魔王了。"
D.Strings[83324]="访问记录"
D.Strings[83325]="谁都别想阻止我复仇！"
D.Strings[83326]="我的眼前……只有……黑暗。"
D.Strings[83327]="存档装置正在充能……"
D.Strings[83328]="存档装置激活，允许读取记录。"
D.Strings[83329]="你赢不了的，凡人。"
D.Strings[83330]="斯科瓦尔德品尝过了军团的力量。他会拿到圣盾并将它交给我们！"
D.Strings[83331]="这里属于我们！"
D.Strings[83332]="我低估了你的力量……"
D.Strings[83333]="原谅我，拉文凯斯领主。我……让你失望了……"
D.Strings[83334]="我必须……警告……其他人……"
D.Strings[83335]="绝不能让外来者知道试炼的事情！"
D.Strings[83336]="你没资格踏上这片土地！"
D.Strings[83337]="神王会砍下你的脑袋！"
D.Strings[83338]="托林尼尔是风暴峡湾最古老、睿智的巨龙。"
D.Strings[83339]="与他们一起飞翔，就等于和诸神飞翔。"
D.Strings[83340]="寻求他们的祝福，通过意志试炼吧。"
D.Strings[83341]="你已经证明了自己可以成为我宝贵的盟友，$n。我能帮你什么忙吗？"
D.Strings[83342]="指挥官萨拉诺尔，巡逻队前来报到！"
D.Strings[83343]="我已经……热血沸腾！这邪能……要……控制不住了……啊啊啊！"
D.Strings[83344]="恶魔控制了黑鸦堡垒。你必须……阻止他们……"
D.Strings[83345]="唉，你们凡人真是自负……傲慢。你们要为自己的无礼付出代价。"
D.Strings[83346]="什么？怎么可能？一直都是？！"
D.Strings[83347]="为打垮这家伙的灵魂，我……费尽了心机。但是他很快就会属于我们了。"
D.Strings[83348]="说实话，战况不太顺利。虽然我们的部队很强大，而且训练有素，但他们并不熟悉战争。"
D.Strings[83349]="我的时间有限，灵魂行者。快说吧，你叫我来做什么。"
D.Strings[83350]="存档装置充能进度50%%……"
D.Strings[83351]="存档装置充能进度75%%……"
D.Strings[83352]="别管我……快，趁恶魔还没来……"
D.Strings[83353]="伊瑟拉，非常感谢你能来。我们遭遇了严重的危——"
D.Strings[83354]="不用解释了，玛法里奥。我早有预感。"
D.Strings[83355]="翡翠梦境被梦魇占领了。燃烧军团和萨特萨维斯就是罪魁祸首。"
D.Strings[83356]="世界之树莎拉达希尔已经被梦魇腐化，正在我们宝贵的土地上散播诅咒。"
D.Strings[83357]="我们得打败梦魇之王，否则瓦尔莎拉就完了。可我们也不能低估他……"
D.Strings[83358]="萨维斯偷走了艾露恩之泪！那我们的勇士白忙一场了吗？"
D.Strings[83359]="正相反，神殿得救了，我们还来得及夺回艾露恩之泪。"
D.Strings[83360]="没时间了。神殿虽然得救了，可塞纳留斯迷失在了梦魇中。"
D.Strings[83361]="冷静点，玛法里奥。你还不明白萨维斯如今有多可怕。"
D.Strings[83362]="我已经浪费了不少时间。我受够了！"
D.Strings[83363]="失去塞纳留斯让玛法里奥丧失理智了。"
D.Strings[83364]="快去世界之树。他可能去那儿了，我们不能冒这个险。"
D.Strings[83365]="同时，我们要跟着玛法里奥，找到他，绝不能让他也倒下。"
D.Strings[83366]="卑微的爬虫。我很乐意来碾碎你。"
D.Strings[83367]="重返战场，感觉真不错。"
D.Strings[83368]="激活序列：力量试炼……"
D.Strings[83369]="但愿你准备好面对第一个试炼了，外来者。"
D.Strings[83370]="作为宝库的守护者，想要前进的勇士必须接受我的考验。"
D.Strings[83371]="弱者能留给世界的，只有死亡。"
D.Strings[83372]="我的双刃需要更多能量。"
D.Strings[83373]="我要把你们都干掉……"
D.Strings[83374]="……我的怒火会降临到你们所有人的头上！"
D.Strings[83375]="仇恨在我的体内燃烧。"
D.Strings[83376]="玩火者必自焚。"
D.Strings[83377]="我不用刀剑都能击败你们。"
D.Strings[83378]="我变虚弱了，我需要更多的力量！"
D.Strings[83379]="愤怒、憎恨、狂暴！这些情绪只会让我更加强大！"
D.Strings[83380]="我的力量……还不够吗？"
D.Strings[83381]="我是不可阻挡的。"
D.Strings[83382]="如此……漫长……炎魔之王呢？他为何不回应我的呼唤？"
D.Strings[83383]="烈焰将吞噬一切。"
D.Strings[83384]="烈焰需要更多燃料。"
D.Strings[83385]="肉体凡胎，尝尝烈焰的爱抚吧。"
D.Strings[83386]="灰飞烟灭，魂飞魄散吧。"
D.Strings[83387]="我们点燃了烈焰。"
D.Strings[83388]="火焰是有生命的。"
D.Strings[83389]="我们要烧死你们！"
D.Strings[83390]="烈焰！死亡！"
D.Strings[83391]="好……冷啊。"
D.Strings[83392]="你们休想控制烈焰！"
D.Strings[83393]="火……熄灭了。"
D.Strings[83394]="我要把这座监狱烧成废墟！"
D.Strings[83395]="有客人？太好了！"
D.Strings[83396]="出乎意料，对吧？"
D.Strings[83397]="你可以躺着看戏了。"
D.Strings[83398]="跟着弹球走。"
D.Strings[83399]="该集中精神了。"
D.Strings[83400]="看着我的眼睛。"
D.Strings[83401]="该死的守望者和镜子。"
D.Strings[83402]="看起来有点远……"
D.Strings[83403]="如果我能看见未来就……"
D.Strings[83404]="我期待着下一批客人。"
D.Strings[83405]="那好吧。我要杀光你们。"
D.Strings[83406]="你不该来挑战一位守望者的。"
D.Strings[83407]="去死吧，这已经不是第一次了吧？"
D.Strings[83408]="最好的牢笼不需要高墙。"
D.Strings[83409]="守望者的战刃能刺穿最坚固的铠甲。"
D.Strings[83410]="你们死定了。"
D.Strings[83411]="小心脚下！这里很高的。"
D.Strings[83412]="暗夜精灵都该学会热爱黑暗。"
D.Strings[83413]="加入军团令我的力量暴涨。让我来展示一下吧。"
D.Strings[83414]="我是不可阻挡的！我奋斗多年，承受无数痛苦。胜利必将属于我！"
D.Strings[83415]="我输了？怎么可能！你……一无是处……"
D.Strings[83416]="我早就猜到了！玛维就是那么固执。"
D.Strings[83417]="我知道她在黑暗神殿那一战之后，就把那件神器藏了起来。"
D.Strings[83418]="而你们这些蠢货带来了钥匙。我要说声谢谢……无论你们是否情愿。"
D.Strings[83419]="噢……新的审判对象。"
D.Strings[83420]="看看门牌号背后是什么……"
D.Strings[83421]="真让人失望。"
D.Strings[83422]="游戏结束了。"
D.Strings[83423]="你带来了我的护甲和战刃……"
D.Strings[83424]="力量试炼序列推算完毕。"
D.Strings[83425]="这就够了，外来者……"
D.Strings[83426]="难以置信！我已有多年没遇到有资格的挑战者了，今天却连败了两次！"
D.Strings[83427]="你通过了力量试炼，外来者。到宝库的入口来，我会给予你守护者的祝福。"
D.Strings[83428]="那个凡人正在接近灰烬使者。拿起武器！"
D.Strings[83429]="我们辜负了……巴纳……"
D.Strings[83430]="投刃车无法适应渡鸦庭院外的地形。立刻返回，否则你将被弹射出去。"
D.Strings[83431]="干掉他们！把他们挫骨扬灰！"
D.Strings[83432]="呱呱！我要撕碎你！"
D.Strings[83433]="把它碎尸万段！"
D.Strings[83434]="我要把你献给巫母！"
D.Strings[83435]="呱呱！你会后悔的！"
D.Strings[83436]="把它大卸八块！呱呱！"
D.Strings[83437]="我很乐意杀了你！"
D.Strings[83438]="呱呱！让它血流成河！"
D.Strings[83439]="姐妹们！为我报仇……"
D.Strings[83440]="不……呱！"
D.Strings[83441]="我诅咒你！"
D.Strings[83442]="懦夫！你会付出代价的……"
D.Strings[83443]="不！不！呱……"
D.Strings[83444]="噢，天呐，那是什么东西？！来人啊，救命吧！快来人啊！我的房间快要被它给毁了！"
D.Strings[83445]="它就在这里！我知道的！"
D.Strings[83446]="这个该死的柜子怎么打不开！！"
D.Strings[83447]="就尝一口，我就尝一口！真的，就……一……小口！"
D.Strings[83448]="谁都别想把你从我们主人的手中救出去！"
D.Strings[83449]="我将唤醒你内心的黑暗！"
D.Strings[83450]="等尝过我的手段之后，你就会只求速死了！"
D.Strings[83451]="让我看看你的肠子吧！"
D.Strings[83452]="这些药水真是迷人……"
D.Strings[83453]="你们的月神在这里发挥不出任何力量！"
D.Strings[83454]="蠢货！这片土地已经属于我们了！"
D.Strings[83455]="你太迟了……这片土地是我们的了！"
D.Strings[83456]="主人将焚毁这个世界……还有你！"
D.Strings[83457]="等着你的只有……恐惧……"
D.Strings[83458]="满手血腥的人……不止我一个……"
D.Strings[83459]="放弃吧！这个世界没希望了……"
D.Strings[83460]="伊利达雷$n，这就是库斯卡的大军。"
D.Strings[83461]="伊利丹大人希望能速战速决。"
D.Strings[83462]="我猜堡垒已经建好了吧？"
D.Strings[83463]="真走运……又一座邪能火山。"
D.Strings[83464]="主人……"
D.Strings[83465]="我真蠢，居然抗拒萨维斯……见证我的力量吧！"
D.Strings[83466]="哈哈哈！瓦尔莎拉必将……毁灭！"
D.Strings[83467]="蝼蚁！我要踩扁你们！"
D.Strings[83468]="啊……叶子……都掉光了……"
D.Strings[83469]="什么？！噢，是你啊，$n。我正在找东西呢。抱歉，我马上就回店里去。"
D.Strings[83470]="很抱歉我用了些小手段，但我可不想在一个出了名的屠龙部落面前表露身份。$b$b他们肯定不会接受我来此的真正理由。$b$b勇士，你准备好协助我了吗？我不会让你白干的。"
D.Strings[83471]="很好，勇士。跟紧我。"
D.Strings[83472]="小心点。我毫不怀疑，死亡之翼肯定留下了大量陷阱来守护这些宝藏。"
D.Strings[83473]="啊，你来了。伊利丹大人让你来指挥我的破坏魔。"
D.Strings[83474]="一支小型部队潜入了黑暗神殿，可沙塔尔的部队仍在节节败退。"
D.Strings[83475]="我们得以最快的速度拿到萨格里特钥石，然后回防黑暗神殿。"
D.Strings[83476]="我们该告退了。来吧，宝贝们，到火山上的堡垒去。"
D.Strings[83477]="这些蛋不可能都活下来。但活下来的应该就能摆脱死亡之翼的腐蚀了。"
D.Strings[83478]="再挡他们一会儿。有一颗蛋开始孵化了。"
D.Strings[83479]="看！还活了一个。这小东西……还长着黑色的角。"
D.Strings[83480]="我就叫你黑角吧。"
D.Strings[83481]="我到前面去找宝藏。你去找你想要的东西吧，可别让我久等了。这地方很危险。"
D.Strings[83482]="很好。你准备好了就来克拉苏斯平台。我召集了银色北伐军的精英一起去拯救大领主。"
D.Strings[83483]="那个维库勇士彻底失踪了。噢，好吧，其他勇士的脑袋应该够用了。"
D.Strings[83484]="你展现出了真正的勇气，我要奖励你。"
D.Strings[83485]="举起你的武器，外来者，接受这泰坦的礼物吧！"
D.Strings[83486]="好了，愿这力量能在紧急关头帮助你。"
D.Strings[83487]="继续前进吧，宝库的勇士！"
D.Strings[83488]="你已经证明了自己确实有资格挑战试炼。能够考验你是我的荣幸。"
D.Strings[83489]="你的面前还有一个试炼。然后，我们再来谈谈鲜血图腾加入梅拉的远征军的事。"
D.Strings[83490]="把这个卓格巴尔带到下面的洞穴里去，杀掉那个双头怪。如果你能活下来，我们就谈谈。如果他活下来，我就放过他的那群卓格巴尔。怎么都行。"
D.Strings[83491]="我准备好接受你的恩赐了，尤特纳。"
D.Strings[83492]="记住，我叫巴纳扎尔。你大概还不明白，你不过是一颗小小的棋子而已。"
D.Strings[83493]="你没有理由相信我，但我们必须合作，才能活着离开这个洞穴。"
D.Strings[83494]="这头双头怪很强大。小心它的大棍子。"
D.Strings[83495]="我会把你变成燃烧军团的武器。我要用你的躯壳将你所珍视的一切一一腐化并摧毁。"
D.Strings[83496]="有意思。没想到你这么快就能适应灰烬使者。没关系，我会亲自解决你的。"
D.Strings[83497]="我听说你可能见过林达斯？"
D.Strings[83498]="哈哈！真有意思！"
D.Strings[83499]="我可以把我们弄出去。我知道一条密道。"
D.Strings[83500]="鲜血图腾部族残忍而嗜血。我不相信他们会让我们中的任何一个人活着离开这里。"
D.Strings[83501]="森林必胜！"
D.Strings[83502]="自然长存！"
D.Strings[83503]="我的树枝会弯曲……但不会折断！"
D.Strings[83504]="让自然之怒吞噬你们，恶魔！"
D.Strings[83505]="可怜虫。"
D.Strings[83506]="你的女神在哪儿呢？"
D.Strings[83507]="下水道的井盖周围都是爪痕，一条魔尘轨迹一直指向了紫罗兰监狱。"
D.Strings[83508]="看看是谁走进了我的巢穴。"
D.Strings[83509]="看，拉佐克，又能做瞄准练习了！"
D.Strings[83510]="我要把你的尸体扔进死人堆里去！"
D.Strings[83511]="万物都将臣服于萨维斯。"
D.Strings[83512]="你以为你赢了？"
D.Strings[83513]="归于黑暗……"
D.Strings[83514]="对，我看见他了。你那个该死的精灵朋友溜进来偷了我的一盏魔火喷灯！我在下水道里追着他跑了好久，还是被他溜走了。\n\n如果你找到他，一定要让他把喷灯还给我，这种灯现在很少见了。"
D.Strings[83515]="外来者，你休想染指卡兹格罗斯之锤！它注定是属于我的，而不是你。"
D.Strings[83516]="至于你，卓格巴尔……等我们把你的尸体扔下悬崖，就去荡平你那个小小的洞穴。"
D.Strings[83517]="鲜血图腾，让我们了结这一切吧。"
D.Strings[83518]="你的礼物很珍贵，$r。现在，让我看看你想要修补的那块布吧。"
D.Strings[83519]="愚蠢的凡人！艾露恩之泪归我了！"
D.Strings[83520]="如果玛法里奥这么想要回它们，就让他来吧。我等着。"
D.Strings[83521]="你可以进去，但是我不会让我的卫兵为你们的“任务”去冒险。明白吗？"
D.Strings[83522]="很好。别让我后悔相信你们。"
D.Strings[83523]="完全明白，典狱官。"
D.Strings[83524]="关闭屏障，退出监狱。这些伊利达雷想要……跟那个艾瑞达……谈谈。"
D.Strings[83525]="肯瑞托保卫者微微点头表示允许。"
D.Strings[83526]="你的传统和仪式对我毫无意义，尤特纳！"
D.Strings[83527]="我会征服你的试炼，将圣盾据为己有！"
D.Strings[83528]="缩回你的地洞吧，趁它还没塌！"
D.Strings[83529]="众神不会容忍你的行径，维库人！你将为此付出代价！"
D.Strings[83530]="记住，恶魔猎手……你没来过这儿。"
D.Strings[83531]="敌人靠近了！我们走，小伙子们，为洛丹伦而战！"
D.Strings[83532]="跟我来。我来帮你打开牢房。"
D.Strings[83533]="这应该能让你看得更清楚一些。"
D.Strings[83534]="扯破的部分已经补好了。希望你能好好使用这块夏多雷丝绸。一路小心。"
D.Strings[83535]="嗨，又见面了。我的护符肯定就在这个池塘附近。$B$B我留在你肩膀上的印记能帮你找到它。"
D.Strings[83536]="我就知道鲜血图腾不会放过我们的！"
D.Strings[83537]="你在找那个精灵疯子？对，我见过他。他在这里惹出了大乱子，还想吞食某种魔法尘或类似的东西。$b$b可我把他赶走了，我可不能让这种家伙在商店附近晃悠。"
D.Strings[83538]="他跑到哪儿去了？"
D.Strings[83539]="呃，我追了他一段路，最后他爬进了一条通向紫罗兰监狱前门的管道。你可以去那里看看。"
D.Strings[83540]="让我最后品一口红酒……"
D.Strings[83541]="$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TINTERFACE\\ENCOUNTERJOURNAL\\UI-EJ-BOSS-ARCHIMONDEWOD.blp:50:80|t$B[毁灭者塔尔达斯]欺诈者的双刃……只会毁了你……"
D.Strings[83542]="他呢？！瓦雷迪斯呢？说！不然就死。"
D.Strings[83543]="欺诈者的双刃正是我们所需要的。它可以打倒最强大的燃烧军团领主。"
D.Strings[83544]="伊利丹教导我们以毒攻毒，用敌人的力量对付敌人。看来我们找到了这股力量。"
D.Strings[83545]="我们今天损失惨重，没想到还有勇士能活下来。来吧，还有一场艰苦的战斗在等着我们。你准备好了吗？"
D.Strings[83546]="死亡快降临了！"
D.Strings[83547]="杀！ "
D.Strings[83548]="光荣地战死吧！"
D.Strings[83549]="为了泰兰娜！"
D.Strings[83550]="我要毁了你，小恶魔猎手。"
D.Strings[83551]="你的灵魂必将属于我。"
D.Strings[83552]="又能抓到新囚犯了。"
D.Strings[83553]="你的大军不值一提，恶魔猎手。"
D.Strings[83554]="我要撕开你的血肉，品尝你的灵魂。"
D.Strings[83555]="你们走进了我的牢笼。"
D.Strings[83556]="这么急着来当奴隶吗？"
D.Strings[83557]="在这里，你才是猎物。"
D.Strings[83558]="我就是你的法官，你的陪审员，你的侩子手。"
D.Strings[83559]="月爪大师！你的林地出什么事了？"
D.Strings[83560]="看着吧，愚蠢的精灵。我要碾碎这个勇士。"
D.Strings[83561]="不！这……怎么可能？"
D.Strings[83562]="这些德鲁伊太弱了……但愿你比他们能打一点！"
D.Strings[83563]="箭快用完了！"
D.Strings[83564]="滚回去，混蛋！"
D.Strings[83565]="击落那只蝙蝠！"
D.Strings[83566]="左边！"
D.Strings[83567]="撕碎他们，姐妹们！"
D.Strings[83568]="以艾露恩的名义！"
D.Strings[83569]="哦呵！这是谁呀？"
D.Strings[83570]="月神在上！"
D.Strings[83571]="堵住那个缺口！"
D.Strings[83572]="欢迎来到梦魇的国度！"
D.Strings[83573]="今天，你的大胆也救不了你了！"
D.Strings[83574]="绍恩你这个蠢货！你失败了……"
D.Strings[83575]="让这个梦魇吞噬你！"
D.Strings[83576]="我低估了你。"
D.Strings[83577]="你休想阻止梦魇！"
D.Strings[83578]="你已经进入了梦魇的国度！你出不去了！"
D.Strings[83579]="在梦魇中瑟瑟发抖吧！"
D.Strings[83580]="你休想从这个梦魇中醒来！"
D.Strings[83581]="你这蠢货，居然敢到这里来。"
D.Strings[83582]="黑暗……会击垮你的……"
D.Strings[83583]="你休想击败我们所有人……"
D.Strings[83584]="很快，黑暗就将笼罩这可悲的森林！"
D.Strings[83585]="艾泽拉斯无法抗拒它的命运！"
D.Strings[83586]="该死的幽灵视觉！"
D.Strings[83587]="这将是一场光荣的战斗！"
D.Strings[83588]="我要砍断你的骨头！"
D.Strings[83589]="万灵……辜负了我……"
D.Strings[83590]="先祖，请赐予我力量！"
D.Strings[83591]="我掌握着众神的力量！"
D.Strings[83592]="冥狱深渊在等着你，外来者！"
D.Strings[83593]="先祖，带我走……"
D.Strings[83594]="我还会复活的……"
D.Strings[83595]="众神……帮帮我……"
D.Strings[83596]="你救不了托林尼尔的！"
D.Strings[83597]="我要用你的骨头来装饰我的龙！"
D.Strings[83598]="我将成为不朽的龙骑士！"
D.Strings[83599]="下一次飞行……在等着我……"
D.Strings[83600]="蔑潮会将你从这里冲走的！"
D.Strings[83601]="你的死亡是最好的奖赏！"
D.Strings[83602]="我将在英灵殿享用盛宴！"
D.Strings[83603]="我虽死……犹荣……"
D.Strings[83604]="众神……认可了我……"
D.Strings[83605]="我将……前往下一个战场……"
D.Strings[83606]="可惜你的盟友必须死。别担心……我会好好利用他们的灵魂。"
D.Strings[83607]="你永远都没有这个资格！"
D.Strings[83608]="诸王会唾弃你的，爬虫！"
D.Strings[83609]="神王已经胜利了！"
D.Strings[83610]="你休想抵抗命运！"
D.Strings[83611]="让这些符文击溃你！"
D.Strings[83612]="就连……岩石……也会腐朽……"
D.Strings[83613]="你休想获胜……"
D.Strings[83614]="圣殿是不会……为你开启的……"
D.Strings[83615]="你会和托林尼尔一个下场！"
D.Strings[83616]="你不是……我们的对手……"
D.Strings[83617]="我要用你的鲜血涂成战纹！"
D.Strings[83618]="今晚，让乌鸦吃了你！"
D.Strings[83619]="我还没有……输……"
D.Strings[83620]="死亡也平复不了我嗜血的渴望……"
D.Strings[83621]="一个光荣的……结局……"
D.Strings[83622]="这座地窟属于蔑潮部族！"
D.Strings[83623]="你太迟了，外来者！"
D.Strings[83624]="你不是神王的对手！"
D.Strings[83625]="大门不会向你敞开，外来者！"
D.Strings[83626]="我要把你送回冥狱去！"
D.Strings[83627]="我们要拿你去喂燃烧军团！"
D.Strings[83628]="你逃不出梦魇之王的掌心！"
D.Strings[83629]="我将在圣殿享用盛宴！"
D.Strings[83630]="光荣地去死吧，外来者！"
D.Strings[83631]="死亡也是一种胜利……"
D.Strings[83632]="奥丁，开启你的殿堂……"
D.Strings[83633]="这片土地已经完了！"
D.Strings[83634]="你的反抗是徒劳的！"
D.Strings[83635]="你还不明白，但你会明白的。"
D.Strings[83636]="你休想离开！"
D.Strings[83637]="想打架？让我来……"
D.Strings[83638]="你的尸体将成为献给海拉的礼物！"
D.Strings[83639]="可怜虫。你本可以加入我们……"
D.Strings[83640]="你想给这片可悲的土地陪葬吗？"
D.Strings[83641]="我要你的骨头！"
D.Strings[83642]="让痛苦淹没你！"
D.Strings[83643]="让迷雾吞噬你！"
D.Strings[83644]="我将回归迷雾……"
D.Strings[83645]="海拉，带我走……"
D.Strings[83646]="诅咒……解除了？"
D.Strings[83647]="我的战争……永不停歇……"
D.Strings[83648]="不臣服，就只能做奴隶！"
D.Strings[83649]="烧掉众神的殿堂！"
D.Strings[83650]="我要让你撞死在大门上！"
D.Strings[83651]="你还没见识过真正的毁灭呢！"
D.Strings[83652]="大地将在军团的脚下碎裂！"
D.Strings[83653]="我们代表着绝对的毁灭！"
D.Strings[83654]="你休想逃过一劫！"
D.Strings[83655]="我们所向披靡……"
D.Strings[83656]="别以为……你赢了……"
D.Strings[83657]="你是在对抗命运……"
D.Strings[83658]="我们不怕死亡……"
D.Strings[83659]="连巨龙都服从我的意志！"
D.Strings[83660]="你那可悲的试炼也救不了你！"
D.Strings[83661]="你的未来只有绝望！"
D.Strings[83662]="我感觉你的意志……在崩溃……"
D.Strings[83663]="你的命运只有死亡！"
D.Strings[83664]="我要粉碎你的灵魂！"
D.Strings[83665]="死亡只是暂时的……"
D.Strings[83666]="你逃不过我们的眼睛……"
D.Strings[83667]="让你看看英雄们的下场吧。"
D.Strings[83668]="如果不能击溃你的意志，我就毁灭你的躯壳。"
D.Strings[83669]="我只看见黑暗……"
D.Strings[83670]="让黑暗吞噬……"
D.Strings[83671]="我的生命……属于主人……"
D.Strings[83672]="黑暗的彼岸……等待着我。"
D.Strings[83673]="主人将毁灭……你的灵魂！"
D.Strings[83674]="愚蠢的凡人！你赢不了的……"
D.Strings[83675]="没有希望，就没有绝望。"
D.Strings[83676]="它汹涌激荡、不可名状、遗世独立……不死不灭。"
D.Strings[83677]="深渊呢喃着你的名字。"
D.Strings[83678]="抗争是徒劳的，英雄，没人能抵抗主人。"
D.Strings[83679]="出击！集火暗夜精灵的勇士！"
D.Strings[83680]="前进，恶魔！摧毁神殿！"
D.Strings[83681]="杀了暗夜精灵和那个勇士！用鲜血浇灌大地！"
D.Strings[83682]="杀了这些入侵者，孩子们。这是女王的命令！"
D.Strings[83683]="绿龙们，过来！消灭这些蝼蚁！"
D.Strings[83684]="深呼吸，英雄。尝尝翡翠梦魇的精华吧！"
D.Strings[83685]="我要用恐惧淹没你，让你哭着逃离这个地方。"
D.Strings[83686]="跑吧，小东西。跑到你们的双脚流血，无法呼吸。"
D.Strings[83687]="呼出最后的希望，吸入恐惧和毁灭吧。"
D.Strings[83688]="我竟然相信你，还为你而战！我真蠢！"
D.Strings[83689]="结束这痛苦！杀了我，不然我就会杀了你！"
D.Strings[83690]="信仰，责任，全是空话！毫无意义！"
D.Strings[83691]="我在做梦？为什么我醒不过来？为什么？！"
D.Strings[83692]="我看不到你的未来了，勇士。我想你是要死了。"
D.Strings[83693]="原谅我。它太……真实了……"
D.Strings[83694]="胜利了！从此之后，绝望将在艾泽拉斯扎根！"
D.Strings[83695]="干掉他们，把剑刃碎片收集起来。它们对你的新武器至关重要。"
D.Strings[83696]="现在，我赐予你我的印记，让人们知道，你代表着我的意志。"
D.Strings[83697]="去吧，任何恶魔都休想逃过我的怒火！碾碎所有妨碍你的对手！"
D.Strings[83698]="你想要圣盾……你会得到它吗？还是会死？你没有第三种选择。"
D.Strings[83699]="你有没有资格？只有诸神才能决定。"
D.Strings[83700]="噢，从亡者的国度归来了？了不起，太了不起了！"
D.Strings[83701]="来吧，锈水老鼠！我要让你们葬身大海！"
D.Strings[83702]="可悲的凡人——你的灵魂是属于我的！"
D.Strings[83703]="什么？！不可能……你到底是什么东西？！"
D.Strings[83704]="记住我们的交易，女妖。别妄想欺骗我……"
D.Strings[83705]="纳萨诺斯有令，一个不留！"
D.Strings[83706]="这样就行了。快到甲板上去。"
D.Strings[83707]="忍住，尽量别尖叫——公爵夫人的耳朵灵着呢。"
D.Strings[83708]="为了黑暗女王！为了希尔瓦娜斯！"
D.Strings[83709]="胜利了！你救了这只小熊。$b$b%s用爪子扒着你，希望能引起你的注意。"
D.Strings[83710]="敌袭！击败来袭的林精。"
D.Strings[83711]="%s看起来非常惊恐。$b$b再次点击小熊以提供帮助。"
D.Strings[83712]="$n，用你的幽灵视觉看一下洞口好吗？有点不对劲。"
D.Strings[83713]="别让他们过桥，否则扒了你们的皮！"
D.Strings[83714]="外来者休想拿走卡兹格罗斯之锤！活剥了他们！"
D.Strings[83715]="把他们大卸八块！血流成河！"
D.Strings[83716]="干得好，去找帕蒂卡聊聊新配方的事吧。"
D.Strings[83717]="你应该去跟帕蒂卡谈谈，她应该会给你一张新配方。"
D.Strings[83718]="我听一个过路的冒险者提起过有个裁缝在阿苏纳的翠绿走廊里开了一家店铺。"
D.Strings[83719]="我们是鲜血图腾！你们要让弱者耀武扬威？！"
D.Strings[83720]="我们得找回圣锤。传统什么的可以等等再说。"
D.Strings[83721]="让我们看看，我记得林精棘针应该是在……"
D.Strings[83722]="噢，该死！我把顶针忘在房间里了！"
D.Strings[83723]="一……二……三，四……没错，都在这儿了。"
D.Strings[83724]="他们是怎么看见我们的？"
D.Strings[83725]="他们有幽灵视觉！"
D.Strings[83726]="干掉他们。重新施放遮蔽法术。"
D.Strings[83727]="这里绝对不行。我必须找个好点的住处。"
D.Strings[83728]="以前住在这里的那个家伙是很可怜，但你也是不得已的，林达斯，这都是为了生存。"
D.Strings[83729]="如果我解释一下我只是暂借，他们或许会让我回去的。不，不，不！泰塔洛是绝对不会接受的。"
D.Strings[83730]="胡恩之路就是他最后一次伟大狩猎时所走的路线。"
D.Strings[83731]="请使用房间中央的工作台来完成你的任务吧。你还可以在桌子上找到一些符文肠线。"
D.Strings[83732]="图鲁克不能再骚扰黯石部族了。我们回去见见我的族人吧。"
D.Strings[83733]="我刚刚进了一批符文肠线，$n。如果你的肠线不够用的话，可以向我买一些。"
D.Strings[83734]="准备好继续前进就告诉我一声，勇士。"
D.Strings[83735]="别着急，勇士。我们只是在双头怪的地盘里而已。我相信我们不会有麻烦的。"
D.Strings[83736]="我们真的该走了。"
D.Strings[83737]="在双头怪的地盘里等着，这明智吗？"
D.Strings[83738]="你证明了自己是艾泽拉斯在世的最伟大的战士。因此我救了你。"
D.Strings[83739]="你带我来这里干什么？"
D.Strings[83740]="好了，伙计们，动手吧！"
D.Strings[83741]="我预见到会有一个强大的英雄来到这片海滩。这个英雄将斩杀无数敌人，不断证明自己的勇气。这个英雄将带领我的大军战胜想要吞噬这个世界的可怕黑暗！"
D.Strings[83742]="你有什么建议？"
D.Strings[83743]="我赐你瓦拉加尔之名！乘着瓦格里的双翼，为英灵殿带来荣耀吧！"
D.Strings[83744]="哦，$n，如果你的背包图样需要林精棘针的话，我可以卖给你一些。"
D.Strings[83745]="我要嚼碎你的骨头！"
D.Strings[83746]="加入我们亡者的行列吧！"
D.Strings[83747]="放弃希望吧！"
D.Strings[83748]="你将像我们一样痛苦！"
D.Strings[83749]="为了黑暗女王！"
D.Strings[83750]="噢……别再来了……"
D.Strings[83751]="啊……终于……"
D.Strings[83752]="黑暗女王……"
D.Strings[83753]="他们逃不掉的。伊利达雷，进攻！"
D.Strings[83754]="邪能领主就在前面。"
D.Strings[83755]="我们还不能进攻，得先保证侧翼的安全。"
D.Strings[83756]="我早就该击溃你的大军……"
D.Strings[83757]="我们在菲拉斯的工作非常重要。"
D.Strings[83758]="好的，让我们来解决它吧。"
D.Strings[83759]="是德崔斯派我来的。他说你能帮我校正这个滴定管。"
D.Strings[83760]="我们不会让你白白帮助托林尼尔的，外来者。$B$B如果你真的想获得我们族群的祝福，就帮我们把这群祸害赶出我们的家园吧。"
D.Strings[83761]="你所做的一切非常了不起，但我们的任务还没有完成。$B$B准备好之后就跟我说一声吧，我们得到山顶上去。"
D.Strings[83762]="等你处理完这里的事务，就来跟我谈谈，我会送你飞上山顶。$B$B一旦出发，我们可能就回不来了。"
D.Strings[83763]="神王斯科瓦尔德召唤出了一队蔑魔维库人！"
D.Strings[83764]="带我飞去山顶，维瑟尔。"
D.Strings[83765]="神王斯科瓦尔德召唤出了一个邪焰蛮兵！"
D.Strings[83766]="神王斯科瓦尔德召唤出了一群魔犬！"
D.Strings[83767]="奥丁认为你有资格拿起黑龙的守护。而我是来找马格纳·破冰者的。但愿我们都能成功，好吗？"
D.Strings[83768]="马格纳·破冰者是谁？"
D.Strings[83769]="朋友们，欢迎来到奈萨里奥的宝库。世人或许更熟悉他的另一个名字：死亡之翼。"
D.Strings[83770]="马格纳·破冰者是我们那个时代最伟大的英雄之一。他百战百胜，最终登上王位并铸造了我所见过的最强大的武器，包括黑龙的守护。\n\n他只输掉过一场战斗，也就是他的最后一场战斗。我们被赫利拉邪教所领导的、满心嫉妒的战士所背叛。那个该死而阴险的女巫！他们在我们反应过来之前先杀害了我，让马格纳无人可用。\n\n他们满怀敬畏地为他建造了陵墓，但他没有进入英灵殿。希望他没有被自己的怒火逼疯。他完全有资格跻身此间。"
D.Strings[83771]="我们，尤其是你……为灰烬使者牺牲了一切，$n。如果提里奥看到这一幕，他会骄傲的。 "
D.Strings[83772]="我们去陵墓吧。"
D.Strings[83773]="来吧，勇士，在我刚刚撕开时空的疤痕时，我会需要你的帮助的。"
D.Strings[83774]="欢迎，我的朋友们，欢迎来到奈萨里奥的宝库。"
D.Strings[83775]="这段旅途很短。我们能直接从苍穹要塞跳进艾泽拉斯。跟我来！"
D.Strings[83776]="拉希奥？！"
D.Strings[83777]="不，但如果这真的是奈萨里奥的宝库，那他应该会有用的。"
D.Strings[83778]="这个家伙可信吗？"
D.Strings[83779]="如果你们这些地老鼠敢碰穆兹一根头发，就再也别想活着离开那个地洞了！"
D.Strings[83780]="交出穆兹！他人呢？！"
D.Strings[83781]="我叫克里姆佩尔，我喜欢一切精确的东西！"
D.Strings[83782]="其他人应该都在圣光之愿礼拜堂下的秘殿里等着你，$n。你得快一点了。"
D.Strings[83783]="我不知道你听说过些什么，但我的数据都是最精确的。最精确的，明白吗？！"
D.Strings[83784]="生命之泉洞穴在西边。你准备好了就去那里找我吧。"
D.Strings[83785]="精准之中，自有和谐的韵律存在，$r。"
D.Strings[83786]="真是个闪亮的登场！可以去找马格纳了吗？"
D.Strings[83787]="他的墓穴就在附近。"
D.Strings[83788]="在首次战败后，他被葬在这里……"
D.Strings[83789]="亵渎者！我们得干掉这些怪物！"
D.Strings[83790]="打得好！跟我来。我来打开墓穴。"
D.Strings[83791]="守卫们都不听我的了！看来我们得硬闯了。"
D.Strings[83792]="我们应该可以跳过去。"
D.Strings[83793]="勇士，我们得救他！我会努力说服他前往英灵殿的，但他可能会抵触真相，并让他的卫兵攻击我。"
D.Strings[83794]="准备好了就说，我们就动手。"
D.Strings[83795]="父亲，是我……你的儿子。奥丁派我来——"
D.Strings[83796]="我儿子已死在我的眼前。我没能保护他！你休想——"
D.Strings[83797]="那就是我。我死于小径的战斗。我们被背叛了！"
D.Strings[83798]="我死于那场战斗。我们都死了，无人生还，包括你！"
D.Strings[83799]="撒谎！没看见我忠诚的士兵吗？"
D.Strings[83800]="你是光荣战死的！英灵殿在等你。跟我走吧，父亲！"
D.Strings[83801]="你是谁，恶魔？你为什么要折磨我？"
D.Strings[83802]="骗子！你竟敢提他，去死！我要亲手送你下冥狱！"
D.Strings[83803]="你不是我儿子！他……他早已被奥丁召入了英灵殿！"
D.Strings[83804]="我是马格纳大帝之子，瓦拉加尔的勇士。父亲，看着我！我是胡尼尔。我是你儿子！"
D.Strings[83805]="他的武器归你了，勇士。这里的任务已经完成了。让我们回英灵殿享用盛宴吧！"
D.Strings[83806]="如此渺小脆弱，却有如此强大的力量。"
D.Strings[83807]="怎么了？你要知道，只有集中精神才能得到精确的结果。"
D.Strings[83808]="又见面了。真正的朋友总是会对他的朋友伸出援手。"
D.Strings[83809]="$n，你来了！圣光秘殿就在前面。这边走。"
D.Strings[83810]="去吧，伊瑟拉！消灭所有妨碍你的人。"
D.Strings[83811]="德崔斯是个老——呃，朋友。我很乐意帮你校正这个滴定管。"
D.Strings[83812]="我们走，$n。这湿气让我的关节发痛，赶紧吧。"
D.Strings[83813]="我不会死于凡人之手！我是大地的守护者！"
D.Strings[83814]="好了，这下就好多了。帮我向德崔斯问好。"
D.Strings[83815]="德崔斯·瓦德拉？那家伙挺暴躁的，但人品高尚。我很乐意帮你校准它。"
D.Strings[83816]="我已经尽力校准这根滴定管了。代我向德崔斯问好。"
D.Strings[83817]="德崔斯？那个亡灵有点莽撞！他以前还说我是骗子来着……但我想我可以原谅他。让我看看……"
D.Strings[83818]="你身后就是洞彻艾泽拉斯的奥丁之眼！而这边则是熔炉，英灵殿里最伟大的铁匠海尔加在此打造瓦拉加尔最强大的武器。"
D.Strings[83819]="给！告诉德崔斯，我对你可是坦坦荡荡、开诚布公的！"
D.Strings[83820]="奥丁就在前面等你。我先去宣告你的到来。注意保持敬意。"
D.Strings[83821]="德崔斯？我还以为他已经死了！我当然乐意帮助一下老朋友啦。"
D.Strings[83822]="完美的校准！去告诉德崔斯，我很快就会去达拉然拜访他的。"
D.Strings[83823]="数据读取器3000型或许能够解密这个核心。但你最好祈祷它不会在处理过程中爆炸。"
D.Strings[83824]="德崔斯总是把最有挑战性的谜题丢给我！让我看看那个滴定管！"
D.Strings[83825]="这个核心包含了一份用一种古代上层精灵方言写成的手稿，但我看不懂。铭文师的殿堂的帕林教授或许能帮你翻译出来。"
D.Strings[83826]="完美！现在你可以精确地配制药水了！"
D.Strings[83827]="我会给隧道另一头的联络人发信号。等你准备好之后，就立刻到那里来见我。"
D.Strings[83828]="再次感谢你，英雄。你给了黑龙军团第二次机会。"
D.Strings[83829]="我一定要抽空去一趟达拉然。"
D.Strings[83830]="战争领主，你的部队负责突袭东南方的末日堡垒，阻止那里的恶魔大军攻击我们。"
D.Strings[83831]="亡者复活了！有点不对劲……"
D.Strings[83832]="安息吧，兄弟。"
D.Strings[83833]="这些战士很不安！他们受到了某种惊扰……"
D.Strings[83834]="前进！就快到马格纳的陵墓了。"
D.Strings[83835]="你下去后要小心点……那些锅里煮的可不是西部荒野的炖菜。"
D.Strings[83836]="跳上来。如果有必要，我们要检查每艘船！"
D.Strings[83837]="没有她的踪迹。我们继续找。"
D.Strings[83838]="那是皇家卫兵……这肯定是她的旗舰。抓住船长！"
D.Strings[83839]="天火号正在节节败退。快来，我们得去帮忙！"
D.Strings[83840]="谢谢你，伙计！我会永远记住你的。"
D.Strings[83841]="我们自由了？自由了？没有巨龙了？也没有小龙了？"
D.Strings[83842]="胡恩说他会释放我们的。你是胡恩的同伴吗？"
D.Strings[83843]="去死吧，暴君！去死吧，死亡之翼和他的小崽子们！"
D.Strings[83844]="灰舌死誓，跟我上！"
D.Strings[83845]="请原谅我：我必须警告其他人。愿艾露恩与你同在。"
D.Strings[83846]="最伟大的奥丁，请允许我为你介绍$n。他们杀了强大的深渊领主马加洛，展现出了真正的勇气。"
D.Strings[83847]="看呐，我的战士们！看看我最伟大的勇士，天空之王$n！"
D.Strings[83848]="勇士！很高兴见到你。维库人可不是什么热情好客的民族。"
D.Strings[83849]="嘘……这边！"
D.Strings[83850]="勇士，这边！快，别让那头幼龙闻到你的气味！"
D.Strings[83851]="神王还没有赢。让我们把那些龙抢回来！"
D.Strings[83852]="嘿，是你！我快疯了——拜托，说我们可以进攻了！"
D.Strings[83853]="这边，这里有个好位置。"
D.Strings[83854]="嘿，过来！我有个计划！"
D.Strings[83855]="那家伙带着条龙，我感觉不妙。"
D.Strings[83856]="太好了！终于能行动了！"
D.Strings[83857]="放下武器，外来者。我不想伤害你。"
D.Strings[83858]="等等……你和他们不太一样……"
D.Strings[83859]="那个恶魔束缚着我……救我……"
D.Strings[83860]="德克加尔违背了我们的约定。"
D.Strings[83861]="该让他们知道后果了。"
D.Strings[83862]="你不是这里的原住民，却选择了拯救我们。"
D.Strings[83863]="你通过了意志试炼，还赢得了一个盟友。"
D.Strings[83864]="举起你的武器，外来者。为了嘉奖你的善举，接受这风暴与雷霆的力量吧。"
D.Strings[83865]="让维瑟尔载你吧，让这些维库人见识一下真正的风暴之怒！"
D.Strings[83866]="风暴会赶走斯科瓦尔德！"
D.Strings[83867]="那个懦夫将被狂风撕成碎片！"
D.Strings[83868]="承受托林尼尔的怒火吧！"
D.Strings[83869]="托林尼尔欠你一份人情，外来者。"
D.Strings[83870]="试炼还没结束。只要你有需要，我随时待命。"
D.Strings[83871]="看来有位信使在等你。祝你一路顺风，朋友。"
D.Strings[83872]="你通过了两个试炼，还剩一个。"
D.Strings[83873]="你要接受远古列王的审判，但他们是亡者而你不是。"
D.Strings[83874]="只有一个人能架起沟通的桥梁，但你得取悦他。"
D.Strings[83875]="到瓦狄斯丹来见我，我给你讲讲这个传说。"
D.Strings[83876]="霍斯瓦尔德的骨语者守护着死者。他们不会帮你的。"
D.Strings[83877]="他们走上了邪路。他们忘了古老的誓言。"
D.Strings[83878]="但是还有一个人记得，一个严守传统的人。"
D.Strings[83879]="去找维德哈尔！接受审判，通过勇气试炼。"
D.Strings[83880]="枯根……乱叶……符文石……"
D.Strings[83881]="我听到……森林的召唤……"
D.Strings[83882]="得逃出去……我感觉我的叶子……"
D.Strings[83883]="自由了！我的根须要刺穿背叛者的心脏！"
D.Strings[83884]="啊……噢……"
D.Strings[83885]="谁来了？这脚步声像橡实一样清脆。过来，小家伙。"
D.Strings[83886]="你别想压服我，符文先知。这个满身邪气的家伙休想玷污英灵殿！"
D.Strings[83887]="我的耐心已经耗完了，符文先知。解决这一切！"
D.Strings[83888]="投降吧，艾希迪尔。如果你不愿屈服，那就消散吧！"
D.Strings[83889]="勇士！干掉这个僭越者，我就让你通过试炼！"
D.Strings[83890]="你想阻止我？我是复仇的亡者之主！"
D.Strings[83891]="他的力量都来自符文石，勇士。快摧毁它！"
D.Strings[83892]="这只是死亡之翼当年收集的一部分神器。拿上它们，我稍后会安排人好好研究的。"
D.Strings[83893]="多管闲事的蠢货。我的大军是不死的！"
D.Strings[83894]="姐妹们！让这懦夫看看真正的勇气！"
D.Strings[83895]="他又在充能符文石！"
D.Strings[83896]="不！这力量……太强大了！"
D.Strings[83897]="你应该投降的，艾希迪尔。"
D.Strings[83898]="只要你不再是英灵，神王就不需要接受你的审判了。"
D.Strings[83899]="不……你不能……"
D.Strings[83900]="我能。这是你自找的，女武神。你和这个……外来者都得死。"
D.Strings[83901]="享受永恒的诅咒吧。冥狱深渊在等着你们！"
D.Strings[83902]="抱歉，英雄。我害了我们俩。"
D.Strings[83903]="或许这个卑鄙的懦夫还有一些用处。"
D.Strings[83904]="呃！真恶心！但愿这能管用，幽灵。"
D.Strings[83905]="恶心死了！我的盔甲还有海草的臭味！"
D.Strings[83906]="这是谁呀？！又是格雷迈恩的佣兵？"
D.Strings[83907]="没关系。你们即将见证新纪元的诞生。"
D.Strings[83908]="如果你能活着走出去的话。"
D.Strings[83909]="啊，我忠诚的英雄。"
D.Strings[83910]="你不能倒在这里。圣盾不能落入敌人手中！"
D.Strings[83911]="部落的未来就看我们俩的了。想办法回到风暴峡湾——我等着你。"
D.Strings[83912]="废物！你该跪下迎接伟大的海拉！"
D.Strings[83913]="你的灵魂……变弱了。她干了什么？"
D.Strings[83914]="跟我的宠物玩玩。我要看着它撕碎你！"
D.Strings[83915]="敌人很强大，勇士，但我们会胜利的。"
D.Strings[83916]="你很聪明，外来者，可你的努力都是徒劳的。"
D.Strings[83917]="别以为你就要赢了，你这废物。"
D.Strings[83918]="还挺聪明。你或许会是个有趣的玩具。"
D.Strings[83919]="计划完毕，英雄。现在该行动了！"
D.Strings[83920]="不！我可爱的宠物！你会付出代价的！"
D.Strings[83921]="成功了，海拉！我们的交易完成了，我们该收取报酬了！"
D.Strings[83922]="真傲慢！有我在，谁都别想离开冥狱深渊！"
D.Strings[83923]="什么？这不可能！"
D.Strings[83924]="她的力量在衰退。她休想留下我们！"
D.Strings[83925]="别想离开冥狱深渊！谁都别想！"
D.Strings[83926]="我们满足了你的条件，海拉。你也该履行诺言了。"
D.Strings[83927]="这座地窟里没有黄金，但有智慧。"
D.Strings[83928]="尤特纳是锁，而荣耀则是钥匙。"
D.Strings[83929]="用勇士们的鲜血铸成钥匙，或许就能打开这把锁。"
D.Strings[83930]="里面有出路……以及更多的东西。"
D.Strings[83931]="试炼完成了，但你的敌人还在。"
D.Strings[83932]="他的乌合之众堵住了正义的殿堂。"
D.Strings[83933]="为了砍下头颅，你得削弱他的身躯。"
D.Strings[83934]="但首先……风暴峡湾的大救星要去救一个非常重要的人。"
D.Strings[83935]="我……绝不……投降！"
D.Strings[83936]="太好了！我又欠了你一条命，朋友。"
D.Strings[83937]="阻止这股邪恶的浪潮！"
D.Strings[83938]="不要放过玷污这片土地的家伙！"
D.Strings[83939]="恶魔还在涌来！肯定还有其他源头！"
D.Strings[83940]="准备好之后，我就送你去山顶，朋友。"
D.Strings[83941]="让我们彻底扫平斯科瓦尔德的爪牙！"
D.Strings[83942]="蠢货！你休想阻挡我无穷的大军。"
D.Strings[83943]="英雄，那个艾瑞达护住了敌人！"
D.Strings[83944]="我的士兵是无穷无尽的！"
D.Strings[83945]="你不可能永远战斗下去！"
D.Strings[83946]="毁灭的浪潮是永无止境的！"
D.Strings[83947]="不！你休想阻止……无穷的……"
D.Strings[83948]="任务完成了，勇士。我们回去找哈维吧。"
D.Strings[83949]="神王的恶魔盟友别想威胁风暴峡湾了。"
D.Strings[83950]="你该去圣殿追杀斯科瓦尔德了。"
D.Strings[83951]="伟大的战斗，伟大的勇士。是的，你很有实力。"
D.Strings[83952]="进入英灵殿吧，勇士。无上的荣耀在等着你！"
D.Strings[83953]="他们想从内部炸毁那艘船。"
D.Strings[83954]="阿彻鲁斯的死亡骑士们，$n代表了我的意志。他的命令就是我的命令。"
D.Strings[83955]="对胡恩来说，上古之战并没有随永恒之井爆炸而结束。击败了燃烧军团后，他就将精力放在了那个逃跑的怪物身上。"
D.Strings[83956]="小心点，前面的道路相当危险。我只能为你提供指引和治疗，仅此而已。"
D.Strings[83957]="历史都是由英雄的意志铸就的，孩子。这就是你父亲想让你明白的真理。"
D.Strings[83958]="拜托，大酋长。这只是一个双头怪，我相信你不会有事的。"
D.Strings[83959]="灵魂行者，你有什么治疗法术可以帮助我们吗？"
D.Strings[83960]="尹茜迪娅是这座墓穴里仅剩的黑龙军团成员了。我们必须小心点，敢对着死亡之翼的女儿动刀动枪，就得承受后果。"
D.Strings[83961]="如果这能让我的人民获得自由，那无论她想怎么处置我们都行。"
D.Strings[83962]="大酋长要求我跟他一起参加这次谈判。$b$b我们的传说中都提到过高岭部族，言语中总是充满尊敬和缅怀。$b$b我们必须对这个古老的部族保持敬意。"
D.Strings[83963]="我的人民已经宣誓效忠部落许多年了。$b$b部落在我们最需要帮助的时候伸出了援手，我必须在此为那次结盟美言几句。$b$b即使在北方，高岭部族对我们来说也是如雷贯耳，所以我们必须表现出足够的敬意。"
D.Strings[83964]="我来掩护你。快去支援格雷迈恩！"
D.Strings[83965]="我们真是最佳搭档。这个炼金台看起来就像新的一样！$b$b有一天，当我们回想起这次的维库幽灵事故时，一定会哈哈大笑的。谢谢你，$n！"
D.Strings[83966]="你好，勇士。$b$b我们在这片土地上的盟友少得可怜，而高岭部族是牛头人已知的历史上唯一能够和燃烧军团一较高下的部族。$b$b我会尽我所能地帮助他们再次统一到一个图腾之下，与我们一起对抗燃烧军团的。"
D.Strings[83967]="到处都是亡灵！他们肯定还效忠于马格纳。"
D.Strings[83968]="这个任务很适合库斯卡。我同意了。"
D.Strings[83969]="让我们好好招待他们吧，这里不是纳迦该来的地方。"
D.Strings[83970]="女士，请率领你的纳迦前往北方。打断恶魔在灵魂引擎举行的仪式。"
D.Strings[83971]="我早就知道自己总有一天也会走上胡恩之路。我只希望在上路之前可以先解决掉达古尔。$b$b"
D.Strings[83972]="让我们为这位伟大的战士、领袖和朋友默哀。圣光之下，我们团结一心，兄弟。"
D.Strings[83973]="所以这就是奈萨里奥的宝库。$b$b现在我明白拉希奥为什么这么急着来这里了。这里埋藏的秘密足以在任何一场战争中轻松扭转战局。$b$b但这个地方已经被生者遗忘了数千年。$B$b我们得小心点。没人知道这里还留下了怎样的巫术和陷阱。"
D.Strings[83974]="我们要共同迎接迫近的黑暗。我们要抛弃种族和国籍的桎梏。我们要团结一致！"
D.Strings[83975]="我们会完成任务的。我得提醒你，黑暗神殿正在遭受攻击。"
D.Strings[83976]="时间宝贵。来吧，姐妹们，昔日的同胞还等着我们去“照看”呢。"
D.Strings[83977]="主母，我要你带着你的破坏魔穿过腐化熔炉的壕沟，让他们吃点苦头。"
D.Strings[83978]="感谢你的礼物，$r。这些药水会派上大用场的。"
D.Strings[83979]="靠近点，$n。"
D.Strings[83980]="你好，织魔者。我想请你帮我修补一块丝绸，这是我的一点小礼物。"
D.Strings[83981]="这是我的荣幸。"
D.Strings[83982]="好了，让我们看看这块矿石能干什么。首先：我们得加热矿石。"
D.Strings[83983]="现在，我们来看看能用它来做点什么。"
D.Strings[83984]="接下来这个步骤很简单，就是涂抹助熔剂。靠近点，看清楚我的手法。"
D.Strings[83985]="然后转过身，让大家看清你的样子！"
D.Strings[83986]="我欠你一份人情，英雄。来吧，我们一起消灭这些恶魔！"
D.Strings[83987]="勇士：天火号即将出发执行紧急任务。我想请你与他们同行。"
D.Strings[83988]="谢谢，勇士！带路吧。我们去帮助其他守卫！"
D.Strings[83989]="敌方的援军过来了！"
D.Strings[83990]="敌人即将发动新的攻势！"
D.Strings[83991]="请尽快去暴风城港口报到——我已严令他们等你抵达后再出发。"
D.Strings[83992]="有敌人！保护神殿！"
D.Strings[83993]="有什么吩咐吗？在我们出发前，你有什么装备需要修理吗？"
D.Strings[83994]="相信你的勇气和谨慎必将一如既往地帮助联盟。安度因·乌瑞恩国王。"
D.Strings[83995]="好的，谢谢你，夜歌。你能帮我看一下装备吗？"
D.Strings[83996]="又来了一波攻击者！守住阵线！"
D.Strings[83997]="又有敌人过来了！继续战斗！"
D.Strings[83998]="新的敌人过来了！打起精神来！"
D.Strings[83999]="艾露恩在上！伊瑟拉没救了。我们只能终结她的痛苦了。"
D.Strings[84000]="我们别无选择：伊瑟拉必须死。如果她还清醒的话，也会赞同我的。"
D.Strings[84001]="沐浴艾露恩的光辉，让她的祝福强化你们的攻击！"
D.Strings[84002]="洒下您的光辉吧，月神，请赐予我们力量！"
D.Strings[84003]="艾露恩，请您赐予光辉和力量，带领我们走向胜利！"
D.Strings[84004]="让我来承受伊瑟拉的攻击，英雄。相信我，我结实着呢。"
D.Strings[84005]="锻打矿石……"
D.Strings[84006]="看看，它多容易弯曲……"
D.Strings[84007]="圣光赐予我们力量。"
D.Strings[84008]="请帮我向赶来的圣骑士们问好，格里安。"
D.Strings[84009]="过来，小鬼们！我们要吞噬里面的力量！"
D.Strings[84010]="你看着不太正常！"
D.Strings[84011]="但是我很神秘……"
D.Strings[84012]="你很快就能抓住我了，朋友……"
D.Strings[84013]="欢迎来到苍穹要塞！这里是勇士的归宿！"
D.Strings[84014]="我们誓死效忠你，大领主！"
D.Strings[84015]="勇士，请原谅我的冒昧。我带来了国王的急信。"
D.Strings[84016]="创世之柱之一——阿格拉玛之盾就在风暴峡湾。"
D.Strings[84017]="维库人的传说提到了一个试炼——有实力通过试炼的人，就能得到圣盾。"
D.Strings[84018]="我们明着是送你前往风暴峡湾，并确保你通过试炼。"
D.Strings[84019]="非常惊人，对吧？全新的火炮在三百米外打中全速飞行的双头飞龙。过去看看吧。"
D.Strings[84020]="我会待在楼上，以便更好地观察你的动作……当然是在一个安全的距离外。"
D.Strings[84021]="但私底下，我们还有一个任务……"
D.Strings[84022]="第七舰队集中了联盟最优秀的战士。他们也收到了来自国王陛下的直接命令。"
D.Strings[84023]="三天前，被遗忘者的舰队从杜隆塔尔出发，驶向了破碎群岛。我们认为希尔瓦娜斯·风行者可能也在其中。"
D.Strings[84024]="我们要在安全距离上跟踪他们。但如果有必要，也可以动手。"
D.Strings[84025]="我觉得很有可能出现这种情况。"
D.Strings[84026]="但愿如此吧。"
D.Strings[84027]="被我盯上的猎物，我是不会留他性命的。"
D.Strings[84028]="准备工作就快完成了。你就自便吧。"
D.Strings[84029]="蜘蛛堡垒、灵魂引擎和熔炉是他们的首要目标。伊利丹的仆从决不能失败。"
D.Strings[84030]="成功了？！我是说……成功了！我就说会成功的嘛。这真是个好消息。"
D.Strings[84031]="好了，让我看看这个手套。"
D.Strings[84032]="你做好飞行的准备了吗？我们为你准备了最快的坐骑。"
D.Strings[84033]="送我去破碎海滩。"
D.Strings[84034]="我可以帮你前往任何想要去的地方。在你游历破碎群岛的过程中，我也能逐渐为你开启新的目的地！继续探索吧！"
D.Strings[84035]="达拉然。"
D.Strings[84036]="风暴峡湾。"
D.Strings[84037]="阿苏纳。"
D.Strings[84038]="瓦尔莎拉。"
D.Strings[84039]="至高岭。"
D.Strings[84040]="苏拉玛。"
D.Strings[84041]="我这里有很多配方可供选择。"
D.Strings[84042]="你能为我介绍一下这个炼金台吗？"
D.Strings[84043]="勇士：作为新酋长，我请你一同担负维护部落的重任。"
D.Strings[84044]="为此，我的舰队准备驶向破碎群岛。只要你踏足风暴峡湾，被遗忘者就将全力充当你的后盾。"
D.Strings[84045]="与我们同行吧。只要我们携手，部落就将所向披靡！"
D.Strings[84046]="我们的炼金台很棒不是吗？德崔斯花了几年时间来组装它。这可是他的骄傲！"
D.Strings[84047]="这个炼金台的遭遇真是太让人遗憾了。"
D.Strings[84048]="你知道维库人吗？高大、野蛮，有着古老血统的战士。他们从不重视机敏的价值。"
D.Strings[84049]="那个该死的萨维娜把炼金台搞得一团糟。可怜的德崔斯！我知道他在掩饰，他肯定已经心疼死了。$b$b我当然希望你能帮助他修好这个炼金台！"
D.Strings[84050]="他们的传说提到了阿格拉玛之盾。你必须通过某种试炼才能得到它。它只属于……强者。"
D.Strings[84051]="这个炼金台看起来就像新的一样了！"
D.Strings[84052]="这炼金台看起来棒极了！德崔斯一定很欣慰。感谢你为了修复它所做的一切。$b$b但愿店里再也不会出现什么维库人幽灵了！"
D.Strings[84053]="我想跟你买点东西。"
D.Strings[84054]="这种新型投石车的速度更快，火力也更猛。我得谢谢我们的地精盟友。"
D.Strings[84055]="我相信你有足够的能力应对阿格拉玛之盾的任何试炼。"
D.Strings[84056]="事实上，风暴峡湾还有另一件宝物。我会自己想办法得到它。"
D.Strings[84057]="<暂时放松了警惕之后，这个威严的德鲁伊转头看着你。她的黑眼睛在认出你后突然睁大，并闪过一丝暖意。>$b$b<虽然一言不发，但她清晰地表达出了欢迎你的意思。>"
D.Strings[84058]="纳萨诺斯在训练一批新游侠。他们是我们的过去，也是我们的未来。"
D.Strings[84059]="我常思考我们的未来，英雄。我们的人民无法繁衍。难道我们注定要逐渐消亡吗？"
D.Strings[84060]="不。被遗忘者不会停止奋斗。"
D.Strings[84061]="只要有我在，只要还有人能够阻止死亡，就不会。"
D.Strings[84062]="惊魂船长传来了消息，陛下。他们发现神殿了。"
D.Strings[84063]="湮灭号已在附近登陆。他们正在搭建阵地，很快就能发动攻击了。"
D.Strings[84064]="很好。派只蝙蝠去——说我们马上出发。"
D.Strings[84065]="锻打金属的同时也是在锻打你自己。你打算投入多大程度的努力呢，新人？"
D.Strings[84066]="%s警惕地盯着唤风者雷拉。"
D.Strings[84067]="你这里有什么货物？"
D.Strings[84068]="不要光用你的胳膊去挥舞锤子。你还要调动你的躯干，你的双腿，你的精神。"
D.Strings[84069]="不要成为锤子的奴隶。它应该是你的手臂的延伸。你才是它的主人。"
D.Strings[84070]="我这里出售德崔斯和我一起研究出来的配方。每当我们研究出一个新配方，我就会将它加入出售清单。$b$b你一定要时不时回来看看有没有新货色出售！"
D.Strings[84071]="你！我能耽误你一会儿吗？"
D.Strings[84072]="我是艾尔的选民！你以为你会有机会吗？"
D.Strings[84073]="我生，我死，我……"
D.Strings[84074]="要想修复炼金台，我们还有许多工作要做呢！"
D.Strings[84075]="我们成功了！这个炼金台看起来就像新的一样！$b$b这全靠了我的头脑和你的力量，我们真是最佳搭档。谢谢你，$n！"
D.Strings[84076]="沙东布瑞克公爵正在等你，$n。这边走。"
D.Strings[84077]="沙东布瑞克公爵，大领主想了解一下你在破碎群岛搜集到的情报。"
D.Strings[84078]="永不停歇的幽灵之风！走不过去了。"
D.Strings[84079]="%s仔细斟酌着当前的状况。"
D.Strings[84080]="我可以从这里冲锋过去。"
D.Strings[84081]="他的疯狂影响了卫兵，他们都认不出我了。"
D.Strings[84082]="那座门被闪电封闭了。我们得想办法过去！"
D.Strings[84083]="我常说，如果你够不着它，就扔个东西过去。屡试不爽！"
D.Strings[84084]="我们到了……马格纳的墓室！"
D.Strings[84085]="黑锋骑士团，集合！向我们的战友致敬！"
D.Strings[84086]="你们大家都知道，$G他:她;赢得过无数传奇战役，通过了种种考验。"
D.Strings[84087]="他是黑锋骑士团的榜样，是我们中最优秀的一员，完全配得上这份至高的荣誉。"
D.Strings[84088]="以巫妖王的意志以及我作为大领主的权能，我宣布这位勇士，堕落王子之剑的持有者，$n，将从今日起继任黑锋骑士团死亡领主。"
D.Strings[84089]="以巫妖王的意志以及我作为大领主的权能，我宣布这位勇士，诅咒之喉的持有者，$n，将从今日起继任黑锋骑士团死亡领主。"
D.Strings[84090]="以巫妖王的意志以及我作为大领主的权能，我宣布这位勇士，天启的持有者，$n，将从今日起继任黑锋骑士团死亡领主。"
D.Strings[84091]="<随着你的靠近，这个威严的德鲁伊友善而好奇地盯着你。>$b$b<过了一会儿，他赞同地点点头，对你低下了庄严的头颅。>"
D.Strings[84092]="你们要像对我那样对他行礼，在他的指挥下对抗燃烧军团！"
D.Strings[84093]="没时间了！必须阻止萨维斯！"
D.Strings[84094]="放轻松。这种药剂需要过一段时间才能生效。你必须好好休息。"
D.Strings[84095]="救——救救神殿！<窒息的咳嗽声>快！"
D.Strings[84096]="月神殿快要被伊瑟拉摧毁了！"
D.Strings[84097]="守望者需要我们帮忙？看来情况很糟啊。"
D.Strings[84098]="啊，我又能动了，这感觉真好。谢谢你，$n。"
D.Strings[84099]="$n，好久不见啊。我准备好迎接新的战斗了。"
D.Strings[84100]="我们需要武器和补给才能冲出去。我正在准备，$n。"
D.Strings[84101]="年复一年，只有脑海中的低语回荡。我以为我会疯掉。"
D.Strings[84102]="过来，小山羊！"
D.Strings[84103]="别动！我看不住羊群了。"
D.Strings[84104]="你跑太快了，停下！"
D.Strings[84105]="又见面了，林奇，最近有什么新鲜事吗？"
D.Strings[84106]="噢，你知道的，没什么大不了的。我只是帮忙把一整座城市从冰天雪地的北方搬到了一座闹鬼的要塞旁边，然后再搬到一片恶魔横行的群岛上！我想只要一天应该就能搞定了。$b$b我现在已经半退休了，德崔斯是个很不错的接班人。他是个好人……就是对他那个炼金台太上心了点！"
D.Strings[84107]="你想来抢我们的东西吗，恶魔？！你什么都别想抢走！"
D.Strings[84108]="等等！住手！你……你不是恶魔……"
D.Strings[84109]="听起来真刺激！"
D.Strings[84110]="我承认，我从没想到过我的炼金师生涯会这么刺激！$b$b不过看看我是在跟谁说话呀……你的冒险经历可比我多多了！"
D.Strings[84111]="醒醒，恶魔猎手。"
D.Strings[84112]="自从诺森德一别之后，你过得怎么样？"
D.Strings[84113]="我很好，$n。巫妖王的陨落真是个奇迹。要是那次胜利能直接解决诺森德所有的麻烦该多好。$b$b啊，但过去的都过去了。达拉然现在已经在新的前线面对新的战役了，这种感觉真棒！不过我得承认，我很感谢你能挺身而出，而不是让我出去战斗。"
D.Strings[84114]="拿起你的武器，$n。我相信你不会忘记怎么挥刀的。"
D.Strings[84115]="我要用我的怒火焚毁这个世界！"
D.Strings[84116]="我要你帮忙阻止古尔丹。快，把其他伊利达雷都放出来！"
D.Strings[84117]="我还想问问……"
D.Strings[84118]="大领主的意志必将实现。"
D.Strings[84119]="稍后再解释。我们先杀恶魔。"
D.Strings[84120]="恶魔想摧毁世界。我们得把其他战友解救出来。"
D.Strings[84121]="好了，你最近已经让探险者协会里的不少人转变了观念。$b$b这个老黑角似乎认识以前的我，还请我来帮你走完下一段旅程。$b$b我把老塔拉斯又带来了，希望你不会介意。我听说这里有双头怪出没，所以我觉得我们需要一些重火力。"
D.Strings[84122]="它生效了！$G他:她;活过来了！"
D.Strings[84123]="它当然有效了！我用它弄醒过比这家伙死得更久更彻底的人。这只是小意思。"
D.Strings[84124]="我会留在这里等格里安回来的，大领主。"
D.Strings[84125]="祭坛就在你面前，大领主。"
D.Strings[84126]="索克——北边的传送门被摧毁了！我们必须向前推进，经过格罗多姆，到北边去。"
D.Strings[84127]="准备好了就把剑放在祭坛上。圣光就是熔炉。"
D.Strings[84128]="前方的道路已经肃清了！我们到塔顶上去！"
D.Strings[84129]="你继续前进，我得回去向格雷迈恩报告。祝你好运，勇士。"
D.Strings[84130]="机会来了。冲上那座塔！"
D.Strings[84131]="接下来就靠你自己了。祝你好运！"
D.Strings[84132]="我自由了！你是我的救星，外来者。"
D.Strings[84133]="可我们没时间寒暄了，我必须去召集托林尼尔的巨龙！"
D.Strings[84134]="去跟维瑟尔谈谈吧，他会送你去山顶的！"
D.Strings[84135]="但愿玛维的决定是正确的，恶魔猎手。去吧——我来守住阵线。"
D.Strings[84136]="你在白费力气，恶魔猎手。古尔丹大人早有预料。"
D.Strings[84137]="嘿，各位！如果你们需要提提神的话，就来买一瓶河鬃药酒吧！"
D.Strings[84138]="我会把你的礼物告诉其他人的，$n。再次感谢你。"
D.Strings[84139]="所以，他就是毁灭艾泽拉斯的关键。"
D.Strings[84140]="我们为你准备了一头直飞达拉然的坐骑，大领主。"
D.Strings[84141]="我的生命属于燃烧军团。"
D.Strings[84142]="你休想拿到钥石。"
D.Strings[84143]="蛛后泰兰娜要你死。"
D.Strings[84144]="我要将你碎尸万段。"
D.Strings[84145]="一小撮废物而已。"
D.Strings[84146]="我们将用烈焰净化这个宇宙。"
D.Strings[84147]="阿苏纳曾是伟大的纳萨拉斯城的所在地——它是暗夜精灵的文明中心之一。这里很适合作为我们对抗燃烧军团的起点。"
D.Strings[84148]="这座传送门会将我们送去群岛西边的海滩，距离那座城市不远的地方。我们走？"
D.Strings[84149]="小蜡烛烧起来更亮！"
D.Strings[84150]="好烫好烫好烫！！！"
D.Strings[84151]="哎呀呀！"
D.Strings[84152]="你已经证明了自己是一个强大的英雄，外来者。\n\n从今天起，你也将成为托林尼尔之友。"
D.Strings[84153]="蜡烛，烧得太亮了！！！"
D.Strings[84154]="在我们继续前进之前，我想先送给你一份来自托林尼尔的礼物。\n\n举起你的武器，外来者，打起精神来。这份礼物对你们来说，可能有点难受。"
D.Strings[84155]="我准备好接受你的礼物了。"
D.Strings[84156]="在大家面前的，是我们的战友，$n。"
D.Strings[84157]="帕蒂卡！你能行行好，让我们的这位朋友看看我们最新研究出来的配方吗？"
D.Strings[84158]="我很乐意！来看看我的货物吧，$n。"
D.Strings[84159]="可别让$G他:她;弄乱了我的炼金台！"
D.Strings[84160]="知道了，知道了……我们都知道这个炼金台是你的心肝宝贝！"
D.Strings[84161]="嘿，你还活着啊！"
D.Strings[84162]="凯恩和奥图里斯在前面。骑上魔蝠去找他们吧。"
D.Strings[84163]="大领主，我能跟你谈谈吗？"
D.Strings[84164]="战火逼近了，$n。做好准备！"
D.Strings[84165]="这一带很危险。小心点。"
D.Strings[84166]="战场需要更多你这样的英雄，$n。"
D.Strings[84167]="我不记得发生什么事了……"
D.Strings[84168]="谢谢你。我需要一点时间来恢复。"
D.Strings[84169]="你准备好和我一起面对马格纳了吗，$n？"
D.Strings[84170]="我会保护你的，胡尼尔。"
D.Strings[84171]="<希尔格林无法控制地颤抖起来，几乎说不出话来。>"
D.Strings[84172]="是的，你也会的。来吧，我们去英灵殿。这位凡人战士会为你复仇的……"
D.Strings[84173]="这就跟我走吧，今晚我们将与奥丁共进晚餐。"
D.Strings[84174]="我……死了。胡尼尔……你是瓦拉加尔了？"
D.Strings[84175]="我明白了。我的武器归你了，战士。愿它们斩杀海拉的爪牙，为你带来荣耀！"
D.Strings[84176]="够了！卫兵，教训一下这些傲慢的外来者！"
D.Strings[84177]="我一直在努力改进这些熔炉，可有人对我说过一声“谢谢”吗？没有！"
D.Strings[84178]="改进一下这些武器，科弗斯！萨隆邪铁已经过时了，科弗斯！……呸！我要让他们看看我的本事。"
D.Strings[84179]="这里的热带气候太潮湿了，让我觉得骨头上好像又长肉了似的。"
D.Strings[84180]="如果有人肯帮忙的话，我就不用花几年时间来重建熔炉了！"
D.Strings[84181]="科弗斯能为你做点什么吗？"
D.Strings[84182]="守住阵线，恶魔猎手们！为伊利丹大人而战！"
D.Strings[84183]="站稳了。别让他们突破防线！"
D.Strings[84184]="这些日子，恐怕梦境林地正在日渐稀薄。$b$b玛洛恩的庇护所是德鲁伊力量在破碎群岛上的一大重镇。我们决不能让它陷落。"
D.Strings[84185]="萨特已经入侵了我们的林地。他们曾是暗夜精灵，但却投靠了燃烧军团，被恶魔的魔法所扭曲。自然界没有这种怪物的位置。"
D.Strings[84186]="|TInterface\\Icons\\ability_druid_galewinds.blp:20|t |cFFFF0000|Hspell:191797|h[暴虐之风]|h|r从|cFFFF0000北方|r吹来了！"
D.Strings[84187]="|TInterface\\Icons\\ability_druid_galewinds.blp:20|t |cFFFF0000|Hspell:191797|h[暴虐之风]|h|r从|cFFFF0000东方|r吹来了！"
D.Strings[84188]="|TInterface\\Icons\\ability_druid_galewinds.blp:20|t |cFFFF0000|Hspell:191797|h[暴虐之风]|h|r从|cFFFF0000南方|r吹来了！"
D.Strings[84189]="|TInterface\\Icons\\ability_druid_galewinds.blp:20|t |cFFFF0000|Hspell:191797|h[暴虐之风]|h|r从|cFFFF0000西方|r吹来了！"
D.Strings[84190]="查看可接的任务。"
D.Strings[84191]="你听说过白鹿和月神的故事吗？据说牛头人曾猎杀玛洛恩，并差点将他逼入绝境。为了逃跑，玛洛恩跳上了天空，可他的鹿角挂在了星星上。$b$b无论他怎么挣扎都无法摆脱。月神艾露恩见到了他，并愿意让他自由，只要他答应爱她，让她摆脱孤单。$b$b啊，但这只是这个神话的其中一个版本，是由骄傲的猎人们代代相传下来的。"
D.Strings[84192]="谢谢你，$n。我愿意和你并肩战斗。"
D.Strings[84193]="拜托——请让我为你效劳，报答你的恩情吧。"
D.Strings[84194]="能在战场上和你并肩战斗是我的荣幸，$n。"
D.Strings[84195]="让我们一起血战到底，$n。"
D.Strings[84196]="在有些传说里，玛洛恩在世界诞生后的第一个黄昏里爱上了月神。$b$b她的光辉引导他穿越森林，让他知道自己并不孤单。这光辉赶走了恐惧，带来了希望。$b$b许多动物都爱着月亮，并疯狂的追逐她。而月神只遵循自己意志，按她安排的时间播撒光辉，月光是不能被捕捉或占有的。$b$b但白鹿还是夜复一夜的追逐着她横越天空。他变得越来越敏捷强壮，最终终于成功追上了她。$b$b她被他的热情和美丽打动了，接受了他成为她的配偶。直到今天，他仍然最喜爱在她的光辉笼罩下的荒野。"
D.Strings[84197]="跟我说说阿苏纳和瓦尔莎拉。"
D.Strings[84198]="跟我说说风暴峡湾和至高岭。"
D.Strings[84199]="拜托，如果你找到什么能够缓解这种饥渴的东西，请带来给我。"
D.Strings[84200]="我吃饱了，但这只是暂时的。"
D.Strings[84201]="啊，我能感觉到魔力在我体内流淌。我又感觉充实了。"
D.Strings[84202]="能量在我体内涌动！我已经容纳不了更多了。"
D.Strings[84203]="拿起蜡烛"
D.Strings[84204]="谢谢你，外来者。我这就赶去山顶。"
D.Strings[84205]="我不知道你为什么会来，但我要谢谢你。"
D.Strings[84206]="这些肮脏的恶魔要为他们的背叛付出代价！"
D.Strings[84207]="我……差点就崩溃了……谢谢你。"
D.Strings[84208]="太感谢你了，$c！那条狗差点把我吃了！"
D.Strings[84209]="这条路很不安全，冒险者。\n\n狗头人袭击了我们的车队，带着我们送给阿莱利用于审讯的灵魂牢笼逃跑了。"
D.Strings[84210]="为了纪念乌拉，我会按照计划把灵魂牢笼送给阿莱利的。"
D.Strings[84211]="战士们，别管伤口！下一场战斗在等着我们呢！"
D.Strings[84212]="罗萨琳！罗萨琳去哪儿了？！"
D.Strings[84213]="太好了！$n来了！我们有机会了，战士们，再冲一次！LOK'TAR！"
D.Strings[84214]="我好像看到一座传送门激活了？"
D.Strings[84215]="我要完整的报告，快点！"
D.Strings[84216]="我得走了。凯恩要我回去。他大概有个恶魔要我帮忙去杀。"
D.Strings[84217]="恶魔猎手在使用传送门！"
D.Strings[84218]="审判官贝弗尔？那是谁？说！"
D.Strings[84219]="我最后一次看见考瓦斯的时候，她在桥上杀出了一条血路。"
D.Strings[84220]="无论怎么选择，用军团的力量对付他们自己的感觉总是不错的。"
D.Strings[84221]="无论你是谁，都已经是我的囊中之物了。"
D.Strings[84222]="你夺取萨格拉斯大人的钥石的计划必将破产。"
D.Strings[84223]="唔……他们好像冲我们来了，$n。"
D.Strings[84224]="和玛洛恩一样，我们的大部分时间都是在荒野中度过的。$b$b可在这个危难时刻，没有人能独善其身。我们必须团结起来，否则就会一败涂地。"
D.Strings[84225]="瓦尔莎拉已经宁静了几百年，直到最近才有所改变。我们低估了这场危机。不要害怕，勇士。我们不会再被打个措手不及了。"
D.Strings[84226]="那些家伙能喷吐邪能，腐蚀它们接触到的一切。"
D.Strings[84227]="贝尔艾什的艾瑞达正在利用这些传送门召唤恶魔援军。"
D.Strings[84228]="只要它们还在运作，就会威胁到我们。"
D.Strings[84229]="我们占领了阵地，但有一些伤亡。"
D.Strings[84230]="他们正在轰炸通向火山的道路。"
D.Strings[84231]="一万多年前，燃烧军团的恶魔首次入侵艾泽拉斯时，玛洛恩和其他强大的古代生物曾与他们战斗过。$b$b他在战斗中英勇牺牲，为了将他受伤的儿子塞纳留斯送去安全的地方疗伤而献出了生命。$b$b为了保护孩子而死，这是父母们最崇高的牺牲方式。$b$b但我要解释清楚一点：对于玛洛恩这样的古老生物而言，我们都是他的孩子。他能死而复生并回到我们中间，这是我们的幸运。"
D.Strings[84232]="许多个世纪之前，我曾是天角部族的首领。我从没在我们古老的墓地中见过如此严重的亵渎行为！"
D.Strings[84233]="|TInterface\\Icons\\ability_rogue_venomouswounds:20|t你受到了|cFFFF0000|Hspell:191855|h[剧毒创伤]|h|r的影响！"
D.Strings[84234]="我不会让你拿走蜡烛的！"
D.Strings[84235]="不准拿走绿蜡烛！"
D.Strings[84236]="你在这儿做什么？！所有蜡烛都是我的！明白吗，大角牛？！"
D.Strings[84237]="你……别想……拿走……蜡烛……"
D.Strings[84238]="等等，你不是真的狗头人！"
D.Strings[84239]="你打得不错，勇士。现在该轮到我上阵了。"
D.Strings[84240]="我很留恋与你并肩战斗的时光，但我现在必须走了。保重！"
D.Strings[84241]="其他战场在召唤我。我们后会有期，朋友！"
D.Strings[84242]="血战……到底……"
D.Strings[84243]="永不……放弃……"
D.Strings[84244]="我有无穷大军！你们的努力毫无意义！"
D.Strings[84245]="这次我恐怕熬不过去了。"
D.Strings[84246]="这会很有趣的。"
D.Strings[84247]="你很快就会看到你的坟墓了，$n。"
D.Strings[84248]="帮我解决这家伙！"
D.Strings[84249]="我的生命……属于部落。"
D.Strings[84250]="我们可以合作，再次囚禁这些恶魔。"
D.Strings[84251]="选择"
D.Strings[84252]="燃烧军团赐予我力量！"
D.Strings[84253]="邪能图腾……一定会……结果了你的。"
D.Strings[84254]="够了！我要亲手解决你们！"
D.Strings[84255]="让我来给你看看，我的火焰不仅仅能摧毁房屋，还能掠夺生命！"
D.Strings[84256]="我将在死后归于灰烬。"
D.Strings[84257]="这个恶魔已经很虚弱了，我可以开始诵念束缚咒文了。这应该要不了多少时间。"
D.Strings[84258]="有很多人反对他，但伊利丹是对的。我们是注定要摧毁燃烧军团的利刃。"
D.Strings[84259]="他太强了！我们得重新激活那些宝珠，把他关在大厅里！"
D.Strings[84260]="这种对大自然的冒犯行为绝对不能容忍。这是我们的土地！"
D.Strings[84261]="我们正在逼退恶魔，但伤亡惨重！我手下只剩几个恶魔猎手了。我们需要你的帮助。"
D.Strings[84262]="主人，你在这儿呢！让我们将这个邪恶的生物送回扭曲虚空吧。"
D.Strings[84263]="护盾碎了！快，这怪物昏迷了，都撤出去！"
D.Strings[84264]="$n，我被那个怪物的毁灭射线瞄准了。快转动最后一面镜子，打破它的护盾！"
D.Strings[84265]="我们没法突破那头恶魔的防御。我们得重新激活守望者的陷阱来解除它的防御。"
D.Strings[84266]="是时候授予你应得的地位了，$n。"
D.Strings[84267]="击退他们！部落绝不向燃烧军团的臭猪投降！"
D.Strings[84268]="我们会保护好洞窟的。感谢你的帮助，英雄！"
D.Strings[84269]="这张桌子上列出了当前所有你可接的任务。"
D.Strings[84270]="让我看看可接的任务。"
D.Strings[84271]="你们的负隅顽抗只是垂死挣扎。所有人都将死于军团之手！"
D.Strings[84272]="就这点本事吗，废物？这只是点擦伤而已！"
D.Strings[84273]="够了！面对你的末日吧！"
D.Strings[84274]="你……还能站着。这不可能！"
D.Strings[84275]="你们将像蝼蚁一样卑微地死去的！"
D.Strings[84276]="死亡降临了……但你要给我陪葬！"
D.Strings[84277]="你必将属于我，阿鲁！"
D.Strings[84278]="啊，我的弟子凯旋归来了！你做得很好，牢牢记住了我教给你的东西。"
D.Strings[84279]="你已经声名鹊起了，$n。很高兴看到我的教导没有白费。"
D.Strings[84280]="$n！欢迎回来！你不是最喜欢清晨烧红的钢铁的味道吗？"
D.Strings[84281]="如果不摧毁那些灭绝者，我们坚持不了多久！"
D.Strings[84282]="来吧，我们上！"
D.Strings[84283]="你是来给我们治疗的吗，$n？"
D.Strings[84284]="万古之前，萨格拉斯创造了马顿，并将恶魔们囚禁在这里。他还创造了萨格里特钥石来关住他们。\n\n可当这位泰坦决定焚毁所有的造物后，他打碎了马顿，无数碎片划过扭曲虚空。燃烧军团由此诞生了。\n\n萨格拉斯将他的钥匙藏在这个碎片里。这是一把“万能钥匙”，能够接入燃烧军团占领的任何世界。它也是伊利丹大人覆灭燃烧军团的计划中最关键的一环。"
D.Strings[84285]="你可以通过支付金钱来遗忘你的当前职业专精，以选择新的专精。\n\n遗忘职业专精所需金额会随次数的增加而提高。"
D.Strings[84286]="你能送我回堡垒吗？"
D.Strings[84287]="赫娅，我将我的力量献给你！"
D.Strings[84288]="娜玛恩和我会守在这里的。"
D.Strings[84289]="你名字……很耳熟。我想应该就是其他人提到的那位英雄。"
D.Strings[84290]="我……出什么事了？我的补给——都不见了！"
D.Strings[84291]="还是有些晕头转向的娜玛恩环顾着房间，寻找着什么。"
D.Strings[84292]="这个勇敢的冒险者救了我们。"
D.Strings[84293]="我想在阿苏纳驻扎一个追随者。"
D.Strings[84294]="你的意志就是我们的命令。"
D.Strings[84295]="谢谢你。保重，勇敢的冒险者。"
D.Strings[84296]="驻扎玛克斯韦尔·泰罗索斯男爵。"
D.Strings[84297]="安置守备官波鲁斯。"
D.Strings[84298]="安置奥伯妮·亮鬃。"
D.Strings[84299]="安置女伯爵莉亚德琳。"
D.Strings[84300]="什么是灵魂牢笼？"
D.Strings[84301]="大领主，如果你想调用哪位追随者，让他直接协助你战斗，只要告诉我一声就行了。"
D.Strings[84302]="灵魂牢笼是耀眼但脆弱的宝石，可以用来囚禁恶魔。\n\n我和护魂者乌拉原本有一些这种碎片，可是狗头人抢劫了我们的车队。\n\n那些没脑子的恶棍根本不知道他们会释放出怎样的恐怖。"
D.Strings[84303]="麦伯克说得对，智慧都是藏在角里的……可他总是想把迅猛龙的角给掰掉！我们需要完整的迅猛龙，才能用它们来对付燃烧军团。\n\n如果麦伯克的书是对的，那我应该可以将迅猛龙的信息素涂在身上，冒充它们的首领。祝我好运吧！"
D.Strings[84304]="<剧烈的咳嗽声>$b$b呃，这可真是出人意料！你还好吧，$n？"
D.Strings[84305]="死亡领主，我必须跟你谈谈。"
D.Strings[84306]="哦……人类！"
D.Strings[84307]="血……呃！等等……对了——这是我的血。"
D.Strings[84308]="我被他们逮了个正着！我正在迅速衰竭。再见了，世界……"
D.Strings[84309]="我真没想到能在这种地方遇见人。"
D.Strings[84310]="通常我都会拿出点心来招待客人的，可我觉得那些玩意儿恐怕不会很好吃。"
D.Strings[84311]="我很高兴见到你，$n！"
D.Strings[84312]="她都归你了。"
D.Strings[84313]="%s用工作靴轻轻踢了踢尸体。"
D.Strings[84314]="别惹地精和他的扳手！"
D.Strings[84315]="格拉茜拉，我发誓，你的牙齿总有一天会因为偷吃我美味的糖果儿掉光的。"
D.Strings[84316]="他们的数量远超我们。我们真能击败他们吗？"
D.Strings[84317]="你可以在楼上的熔炉那里找到科弗斯大师，$g先生:女士;。"
D.Strings[84318]="我感觉到了足印……但它们很陌生……\n\n陌生人……你必须帮助……"
D.Strings[84319]="我已经沉睡了许多个季节。\n\n能再次闻到符文林地的空气真好。"
D.Strings[84320]="|TInterface\\Icons\\inv_misc_volatilewater:20|t%s开始|cFFFF0000|Hspell:191873|h[下潜]|h|r！"
D.Strings[84321]="我周围都是些废物！看看他们，连一个纸袋都劈不开。除非教他们两手，否则他们在和恶魔的战斗中只会变成累赘。$b$b我们来一场对战怎么样？让他们看看真正的骑士是怎么战斗的！"
D.Strings[84322]="听起来不错，做好准备！"
D.Strings[84323]="萨格拉斯大人，不！！！"
D.Strings[84324]="快，$n。用钥石激活传送门。我们必须返回黑暗神殿参加战斗。"
D.Strings[84325]="这看似只是一个小洞，连一支军队都装不下，但它却通向奈萨里奥的老巢。$b$b进去之后，你就能绕到忠于达古尔的卓格巴尔主力军团背后。$b$b但前进的时候还是要小心点，因为你会见到比目前为止你所遇到的所有卓格巴尔还要强大得多的敌人。祝你好运，伙计。"
D.Strings[84326]="嘘！滚出去！"
D.Strings[84327]="这不是你们的土地！"
D.Strings[84328]="我最喜欢瞄准练习了！"
D.Strings[84329]="谢谢。你也要多保重。"
D.Strings[84330]="$n，我抓到了几头魔蝠。在你决定飞上那艘燃烧军团的指挥舰前，我一定会驯服它们的。"
D.Strings[84331]="白月，我要一只魔蝠。我们要去找此行的目标。"
D.Strings[84332]="伊扎尔，送我回去。"
D.Strings[84333]="事情都结束了吗？"
D.Strings[84334]="外面有人！"
D.Strings[84335]="有人来访！嘿……外面安全了吗？"
D.Strings[84336]="我们在这里很好。请你快走吧……注意安全。"
D.Strings[84337]="我们很感谢你的来访，但现在不是时候。"
D.Strings[84338]="这片土地早已饱经战火，可现在这种情况却是全所未见……"
D.Strings[84339]="我相信战争很快就会结束了。"
D.Strings[84340]="地底之王的部队袭击了雪盲台地。来吧！跟我一起踏上征途，让他们看看至高岭的力量！"
D.Strings[84341]="此时此刻，地底之王的大军正在向雪盲台地进发。让我们正面迎击他们，给他们看看高岭部族的真正力量！"
D.Strings[84342]="跟我一起踏上战争之路，让我们告诉他们，团结的我们……就是……高岭部族！"
D.Strings[84343]="你比我想象中的$r更有本事。"
D.Strings[84344]="虽然输了赌注，但我也无法否认你的打猎技巧。\n\n你和那个侏儒已经成了狩猎小队的有益补充。"
D.Strings[84345]="又来了！作为燃烧军团的一员，你们表现出的战斗力简直是在给萨格拉斯抹黑！"
D.Strings[84346]="你们的剑就像你们的剑术一样迟钝！再加把劲儿，小崽子们！"
D.Strings[84347]="用力挥，再快一点！我们必须击垮这个世界的反抗力量！"
D.Strings[84348]="升降机马上就来。其他人都在上面等你。"
D.Strings[84349]="教野猪飞行都比教侏儒打猎容易。"
D.Strings[84350]="我听凭你的吩咐，啸天者。现在，去探索这片土地吧！"
D.Strings[84351]="我听凭你的吩咐，啸天者。"
D.Strings[84352]="你们不仅仅是证明了自己的实力。能跟你和艾迪一起打猎是我的荣幸。"
D.Strings[84353]="赫米特只会接受那些狩猎技巧高超的人加入他的狩猎小队。"
D.Strings[84354]="这真是一次令人难忘的狩猎！\n\n要是没有你和艾迪，我都不知道我们能不能拿下那只野兽。"
D.Strings[84355]="伙计，你把我们从鲜血图腾手里救了出来，所以我决定支持高岭。$b$b虽然我们黯石部族在战场上打不过达古尔的战士，但我们可以用其他方法帮你打败敌人。"
D.Strings[84356]="没有了雄鹰的天角部族不值一提！"
D.Strings[84357]="为了至高岭！"
D.Strings[84358]="你也会像其他人一样倒下的！"
D.Strings[84359]="去啄掉它们的眼珠子，我的小美人们！"
D.Strings[84360]="你的鲜血将化为血雨从天而降！"
D.Strings[84361]="多么美好的一天！"
D.Strings[84362]="你们竟敢正面袭击萨格拉斯的大军？那就来吧，凡人，来面对我的怒火吧！"
D.Strings[84363]="什么？我们的定位水晶被摧毁了？我要扒了你们的皮，凡人！"
D.Strings[84364]="请一定要让我报答你。"
D.Strings[84365]="这边走……把头低下。如果让那些虫语者闻到一丝我的药剂的味道，他们肯定会趋之若鹜的。这些该死的拾荒者。"
D.Strings[84366]="我让你开个好头，可你的部队却被打的七零八落。"
D.Strings[84367]="我很想见见你，可你是活不到那一刻的。"
D.Strings[84368]="要死的人是你，巫婆！"
D.Strings[84369]="真可笑。我在这里都能感觉到你在颤抖。"
D.Strings[84370]="亲爱的，你愿不愿意加入我们？"
D.Strings[84371]="你休想抢走他们。他们是我的！"
D.Strings[84372]="我要你履行约定，去协助他们。"
D.Strings[84373]="灵魂收割器是军团的邪恶造物。"
D.Strings[84374]="你让那些伊利达雷逃离了更悲惨的命运。"
D.Strings[84375]="你刚才摧毁的那个装置是用来稳定燃烧军团建筑的。"
D.Strings[84376]="看看堡垒附近还有没有。"
D.Strings[84377]="你成功了。我们的部队占据了上风。"
D.Strings[84378]="入侵者上了邪能之槌号！"
D.Strings[84379]="现在，我们要杀掉蛛后，拿到萨格里特钥石。"
D.Strings[84380]="放马过来吧，恶魔猎手。"
D.Strings[84381]="你们会成为可口的小点心。"
D.Strings[84382]="下水道卫兵，休息时间到！"
D.Strings[84383]="下水道卫兵！回你们的岗位上去！"
D.Strings[84384]="上边的城区是卡德加和他的“议会”说了算，可在这下边呢？就是我和我的人说了算了。$b$b我可不想看到你在我的下水道里闹出什么荒唐事来，$r。当然，除非你能说服我换个角度来看问题……"
D.Strings[84385]="莱杉，让你的守卫们退下吧。\n\n[价格：50 |TInterface\\Icons\\achievement_reputation_kirintor_offensive.blp:12|t盲目之眼]"
D.Strings[84386]="图鲁克呢？"
D.Strings[84387]="酋长正在下边的洞里等着你呢，河鬃。"
D.Strings[84388]="塔伦米尔的居民们受到了鼓舞，纷纷加入了对抗燃烧军团的战斗！"
D.Strings[84389]="谢谢你。来吧，兄弟们……回去战斗！"
D.Strings[84390]="$n，我的纳迦被附近一个深渊领主困住了。"
D.Strings[84391]="萨满！我有一个紧急消息。"
D.Strings[84392]="对，我们必须反击。可该怎么做呢？"
D.Strings[84393]="我们需要能战胜燃烧军团的武器。"
D.Strings[84394]="他们会来找我们的。"
D.Strings[84395]="这里有古代防御设施。我们得用上。"
D.Strings[84396]="救救她！她快死了！"
D.Strings[84397]="谢谢你，萨满。"
D.Strings[84398]="整片高地都被占领了。氏族也被打散了。"
D.Strings[84399]="什么萨满连火都生不了啊？"
D.Strings[84400]="你闭嘴！都怪木头太潮，我的手又有点抖。"
D.Strings[84401]="军团在平原上击溃了我们。连雷霆崖都躲不过地狱火的威胁。"
D.Strings[84402]="它已经在这里白坐了一万年了。"
D.Strings[84403]="它需要一点……推动力。萨满，你能帮忙吗？"
D.Strings[84404]="看见了吗？它动了。只要有工具，这世界就会为自己而战。"
D.Strings[84405]="是跟踪我们来的！"
D.Strings[84406]="你那只破鸟飞得太慢了。"
D.Strings[84407]="要不是你，我的鸟还能再快点儿。"
D.Strings[84408]="你们这些爬虫将葬身于此！"
D.Strings[84409]="跪下吧，我的主人或许还会大发慈悲。"
D.Strings[84410]="你的主人还没赢呢。"
D.Strings[84411]="哈哈！！你只是个半吊子罢了！"
D.Strings[84412]="去帮其他人！"
D.Strings[84413]="万灵……听从我的召唤……"
D.Strings[84414]="你就是所谓的“救世萨满”？哈！一只三脚猫而已。"
D.Strings[84415]="我们可以战胜他……但得合作……"
D.Strings[84416]="啊——"
D.Strings[84417]="你太弱了，连锤子都差点举不起来，“萨满”。"
D.Strings[84418]="这边，萨满！拿上我的战矛。愿狂风指引你！"
D.Strings[84419]="动手吧！打倒它！"
D.Strings[84420]="心脏。拿到那颗心脏。"
D.Strings[84421]="好了！各位，将精神集中到柱子上。快！"
D.Strings[84422]="你的宝贝“大地之环”必将崩溃！"
D.Strings[84423]="你的世界终将屈服！！"
D.Strings[84424]="燃烧军团必将——"
D.Strings[84425]="艾泽拉斯的元素，听我说。"
D.Strings[84426]="我们曾经亲密无间，但我为了自己的私仇，滥用了你们的力量。"
D.Strings[84427]="请收回毁灭之锤，将它赐予配得上它的人吧。"
D.Strings[84428]="请指引我的道路，我也将再次成为你们的仆从。"
D.Strings[84429]="河鬃，从侧翼的缺口冲出去，找个安全的地方疗伤。"
D.Strings[84430]="天角，飞上去，肃清我们的北部侧翼。"
D.Strings[84431]="谢谢你，外来者。跟我来，让我跟你说说我的计划！"
D.Strings[84432]="%s小心地将样本放进背包里。"
D.Strings[84433]="%s将样本高高举起，仔细查看着。"
D.Strings[84434]="%s将样本凑到鼻子下方嗅了嗅，然后用舌头快速地舔了一下。"
D.Strings[84435]="%s估算了一下收集来的样本价值，然后将它随意地丢进背包里。"
D.Strings[84436]="%s查看了样本，在手中摇了两下，然后将它丢在了地上。"
D.Strings[84437]="%s测试了一下样本的硬度，然后将其放进背包。"
D.Strings[84438]="愿圣光指引你的长剑，大领主。请多保重。"
D.Strings[84439]="别担心，妈妈来了……噢，我的天，他可真大。"
D.Strings[84440]="我们去打猎吧！"
D.Strings[84441]="对……对！把它们都收集起来，然后带来这里！"
D.Strings[84442]="多么精美！我们全部都要！"
D.Strings[84443]="主人一定会非常满意的！这些发现很有趣！"
D.Strings[84444]="放到锅里去！煮到冒泡！"
D.Strings[84445]="这些生物……唔，太美味了！它们可以做成各种饰品！"
D.Strings[84446]="我来递水桶。你来灭火！"
D.Strings[84447]="啊！我可怜的马车！"
D.Strings[84448]="该死的塔古斯之砧在上！那是……邪能之火吗？"
D.Strings[84449]="今天到底是怎么回事？"
D.Strings[84450]="快阻止他们，你们这些蠢货，否则他们会毁掉我们在虚空中的锚点！"
D.Strings[84451]="我们遭到攻击了！碾碎这些废物，博取萨格拉斯的青睐吧！"
D.Strings[84452]="愚蠢的小东西……"
D.Strings[84453]="其他地方还需要我。"
D.Strings[84454]="做母亲的总是忙个不停。"
D.Strings[84455]="我要锤扁你。"
D.Strings[84456]="$n，我很惭愧……"
D.Strings[84457]="噢，想救回那小德莱尼破碎者？"
D.Strings[84458]="我想在瓦尔莎拉驻扎一个追随者。"
D.Strings[84459]="我们必须摧毁这座传送门！"
D.Strings[84460]="我们上方的定位水晶才是关键，让我们来解决它吧。"
D.Strings[84461]="列队，士兵们！把他们赶回传送门里去！为了艾泽拉斯！"
D.Strings[84462]="集中攻击那些水晶！"
D.Strings[84463]="快去为伤员治疗，时间不多了。"
D.Strings[84464]="一切都那么突然！我们正在海滩上推进，突然轰的一声，周围的邪能爆炸了！然后这些建筑就凭空出现，里面都是恶魔！再这样下去，我真不知该怎么击退它们了！"
D.Strings[84465]="一个个来，跟我上，战士们，让我们一鼓作气夷平这个邪能之城！"
D.Strings[84466]="你是北伐军的人！出什么事了？提里奥呢？"
D.Strings[84467]="不知道……我们被偷袭了……到处都是邪火……"
D.Strings[84468]="省点力气吧，我们会找到他的。"
D.Strings[84469]="注意搜索幸存者！尽可能多救几个人！"
D.Strings[84470]="滚回你们的老窝去！"
D.Strings[84471]="他们被击退了！坚持下去！"
D.Strings[84472]="我们走了一半的路了，打起精神来！"
D.Strings[84473]="尝尝火药吧！哈哈哈哈！"
D.Strings[84474]="为了……联盟……"
D.Strings[84475]="我坚持……不住了……"
D.Strings[84476]="结构完整度降至0%%！"
D.Strings[84477]="我的机器人被打坏了！"
D.Strings[84478]="他们杀了我，女王陛下……"
D.Strings[84479]="对，亮晶晶，快给我！"
D.Strings[84480]="杀了你！抢你的东西！"
D.Strings[84481]="诅咒你的灵魂！"
D.Strings[84482]="他们抓走了提里奥！"
D.Strings[84483]="愿圣光保佑我们……"
D.Strings[84484]="我还能战斗，我跟你去。"
D.Strings[84485]="圣光在上，见到你真好。"
D.Strings[84486]="你看见提里奥了吗？"
D.Strings[84487]="我在这里感应不到圣光……"
D.Strings[84488]="我们挡不住他们……"
D.Strings[84489]="他们在撤退。"
D.Strings[84490]="我有预感，战斗还没有结束。"
D.Strings[84491]="瓦里安，我找到了！看，在裂口那边，提里奥！"
D.Strings[84492]="全力援助吉安娜！"
D.Strings[84493]="我们该怎么过去？"
D.Strings[84494]="古尔丹！你会付出代价的！"
D.Strings[84495]="后退……这是陷阱……圣光会保护我的……"
D.Strings[84496]="哈，蠢货！这可是真神的神殿。在这儿，你那可悲的圣光救不了你。你的朋友真走运，刚好能看着你死。"
D.Strings[84497]="圣光……会……啊！啊啊！！"
D.Strings[84498]="弗丁！"
D.Strings[84499]="你的挣扎和努力，换来的却是看着你的勇士一个个化为灰烬。"
D.Strings[84500]="我们绝不会向绝望屈服！"
D.Strings[84501]="今天，艾泽拉斯联军必胜。"
D.Strings[84502]="团结一致，为了艾泽拉斯！"
D.Strings[84503]="你们会感受到恐惧的。"
D.Strings[84504]="打起精神来，战士们，它冲过来了！"
D.Strings[84505]="来自地狱火的怪物！战士们，做好准备！"
D.Strings[84506]="集中火力，打倒它！"
D.Strings[84507]="他要吐息了，小心！"
D.Strings[84508]="前锋，躲开那些拳头！"
D.Strings[84509]="邪能熔岩来了，小心！"
D.Strings[84510]="我全军覆没了。我辜负了你。"
D.Strings[84511]="熔岩喷发了，小心！"
D.Strings[84512]="又有野兽冲出来了！"
D.Strings[84513]="他们又冲我们来了！"
D.Strings[84514]="如果有需要，我不惜献出生命。"
D.Strings[84515]="他去你那边了，风行者！"
D.Strings[84516]="我们走，让联盟看看我们是怎么杀恶魔的。"
D.Strings[84517]="来自地狱火的野兽出现了，小心！"
D.Strings[84518]="下一波又接近，准备！"
D.Strings[84519]="他们又来了，冻住他们！"
D.Strings[84520]="又有敌人从烈焰中冲出来了！"
D.Strings[84521]="熔岩快要喷发了，准备规避！"
D.Strings[84522]="他又喷出那污秽的吐息了，小心！"
D.Strings[84523]="全体集火我的目标，让我们打倒那个恶魔。"
D.Strings[84524]="那团巨型地狱火过来了！"
D.Strings[84525]="他的拳头比山还重！保持移动！"
D.Strings[84526]="你又抢了我的对手，希尔瓦娜斯！"
D.Strings[84527]="那就当是你杀的好了，乌瑞恩。"
D.Strings[84528]="都归你们了，联盟。"
D.Strings[84529]="这下可算逮住他了！全体，集中火力！"
D.Strings[84530]="哈，中看不中用……"
D.Strings[84531]="别幸灾乐祸了，乌瑞恩。我们得在古尔丹再召唤出一个之前阻止他！"
D.Strings[84532]="所有人，穿过裂口！"
D.Strings[84533]="我们去占领山头，掩护你。"
D.Strings[84534]="希尔瓦娜斯，谢谢你。"
D.Strings[84535]="祝你好运，瓦里安。"
D.Strings[84536]="你已经无路可逃了，古尔丹。投降吧，我会给你个痛快的。"
D.Strings[84537]="跑？哈。你说的对，人类。谁都跑不出主人的掌心。现在，见证萨格拉斯的力量吧！"
D.Strings[84538]="稳住，我们以前突破过他们的阵线，这次也不例外。冲锋！"
D.Strings[84539]="我们身后的山脚下，还有一座传送门！"
D.Strings[84540]="我们必须守住这个山头，不惜一切代价。"
D.Strings[84541]="守好阵地，挡住他们，必须挡住。"
D.Strings[84542]="我恐怕……坚持不了多久……"
D.Strings[84543]="让贝恩撤回来，全体靠拢！"
D.Strings[84544]="我们绝不会输给你的，古尔丹。艾泽拉斯的联军今天必将胜利。"
D.Strings[84545]="别废话了，乌瑞恩。快杀了他！"
D.Strings[84546]="我早知道这个世界的下场。它将和之前的万千世界一样，被地狱火吞没。军团是无穷无尽的。"
D.Strings[84547]="举盾，它们过来了！"
D.Strings[84548]="那个传送门里涌出了更多的恶魔。准备！"
D.Strings[84549]="沃金！让他撤回来！稳住阵脚！必须守住！"
D.Strings[84550]="全体向我靠拢！我们要在此背水一战！"
D.Strings[84551]="无论你派出多少恶魔，我们都会打倒你，怪物。"
D.Strings[84552]="现在，你该死了。"
D.Strings[84553]="坚持住，联盟！"
D.Strings[84554]="我们回来了。"
D.Strings[84555]="来征服这个卑微的世界。"
D.Strings[84556]="并将它化为焦土。"
D.Strings[84557]="你明白了吗，人类？世界的命运早已注定。军团是不可阻挡的。"
D.Strings[84558]="我们会携手打败你，就像过去一样。"
D.Strings[84559]="瓦里安，看身后！部落撤走了！"
D.Strings[84560]="我们失败了！这座山头失守了！战士们，要想活命就往海滩上冲！我们得离开这里，否则就会失去所有的有生力量！"
D.Strings[84561]="看来我们的援军到了。"
D.Strings[84562]="来得正好！我们在这片海滩都快没有立足之地了。"
D.Strings[84563]="现在只有一条出路了，老朋友。"
D.Strings[84564]="听好了！离开这片海滩的唯一办法，就是穿过我们面前的恶魔。但他们不知道自己要面对怎样的敌人。让我们给他们看看部落的实力吧！"
D.Strings[84565]="我将回归……元素的怀抱……"
D.Strings[84566]="我已经……撑不下去了……"
D.Strings[84567]="好痛啊！"
D.Strings[84568]="到此为止了……"
D.Strings[84569]="滚回虚空去！"
D.Strings[84570]="让元素消灭你！"
D.Strings[84571]="这个是我的。"
D.Strings[84572]="哈，蠢货们出击了！"
D.Strings[84573]="别让他们靠近尖塔！"
D.Strings[84574]="那座尖塔周围的水晶有古怪。它们给人的感觉……不对劲……就好像同时位于两个地方一样。唔。"
D.Strings[84575]="战士们，瞄准那些水晶！看看你们的直觉准不准。"
D.Strings[84576]="对……它们将它定位到了这个世界。"
D.Strings[84577]="还剩两个。"
D.Strings[84578]="你们解决的，不过是主人毁灭你的无数手段之一罢了！地狱火！"
D.Strings[84579]="坚持住！我们就快成功了！"
D.Strings[84580]="废物。什么都要我亲力亲为吗？很好，做好准备吧！"
D.Strings[84581]="你也会像其他同伙一样死去的。"
D.Strings[84582]="集火指挥官！"
D.Strings[84583]="地狱火从天而降了！小心！"
D.Strings[84584]="我要拿你们的尸体去喂狗。"
D.Strings[84585]="你们的灵魂将品尝无尽的痛苦。"
D.Strings[84586]="看来你站错队了。"
D.Strings[84587]="能再次与你并肩作战的感觉真好，酋长。"
D.Strings[84588]="听你这么叫我可真不习惯。"
D.Strings[84589]="只有一个办法可以靠近陵墓，你准备好了吗？"
D.Strings[84590]="让我们行动吧。"
D.Strings[84591]="希尔瓦娜斯的船在前面搁浅了。"
D.Strings[84592]="他们的扩张速度比我们以前见过的还要快。"
D.Strings[84593]="对，伙计。这支军团已经不一样了。"
D.Strings[84594]="这不是入侵的小分队，而是一支大军！"
D.Strings[84595]="上弦！开弓！放！"
D.Strings[84596]="他们还活着！"
D.Strings[84597]="你也该出现了！"
D.Strings[84598]="你看起来需要帮忙啊。"
D.Strings[84599]="他们的援军简直无穷无尽！"
D.Strings[84600]="又是那种水晶……如果我们能靠近，就可以将它破坏掉了。"
D.Strings[84601]="听到没有，游侠们，让我们打倒这些恶魔！看我的指向齐射……放！"
D.Strings[84602]="打碎那些水晶！"
D.Strings[84603]="唔，这可真痛快。可他们怎么能那么快就弄来这么多恶魔？"
D.Strings[84604]="这次入侵真是前所未见，我想这恐怕不会是他们带来的最后惊喜。"
D.Strings[84605]="这些建筑是瞬间拔地而起的，眨眼之间就能喷出数百头恶魔。"
D.Strings[84606]="这下我们知道怎么摧毁它们了，快行动吧，否则死的就是我们了。"
D.Strings[84607]="这是银色北伐军的徽章，你还能说话吗？其他人呢？"
D.Strings[84608]="没有提里奥的踪迹。"
D.Strings[84609]="我们会找到他的。部落战士们，注意搜寻幸存者，尽可能多救几个人！"
D.Strings[84610]="已经毁掉半座城市了，比我想的还要顺利。"
D.Strings[84611]="我们绝不向你低头。"
D.Strings[84612]="跟你同归于尽！"
D.Strings[84613]="勇敢点，英雄们！"
D.Strings[84614]="到此……为止了……"
D.Strings[84615]="我将回归……大地……"
D.Strings[84616]="大地母亲……指引着我……"
D.Strings[84617]="我们得找到提里奥。"
D.Strings[84618]="我被烧伤了，但还能战斗。"
D.Strings[84619]="我们毫无防备！"
D.Strings[84620]="总算遇上盟友了。"
D.Strings[84621]="我受伤了，可我还能动。"
D.Strings[84622]="他们的数量太多了。"
D.Strings[84623]="他们撤退了。"
D.Strings[84624]="这太容易了，有些不对劲。"
D.Strings[84625]="那边，裂口那边，是古尔丹！他抓了提里奥！"
D.Strings[84626]="部落成员们，支援萨尔！"
D.Strings[84627]="有人知道我们该怎么过去吗？"
D.Strings[84628]="大地之灵，帮帮我！"
D.Strings[84629]="真方便。"
D.Strings[84630]="我来替你复仇，亲爱的！"
D.Strings[84631]="哟，看看这是谁来了。你可是好久没有踏进过阿彻鲁斯的大厅了。"
D.Strings[84632]="谢谢你，死亡领主。我不会让你失望的。"
D.Strings[84633]="我发誓，我对各种恶魔之火都一无所知！我只是个买卖护甲的，仅此而已！"
D.Strings[84634]="我为什么要相信你？"
D.Strings[84635]="我只是个商人，童叟无欺，我就想到拍卖行里买了货物之后再高价卖回给别人，赚到一千万金币之后就平安回家！这个要求很过分吗？"
D.Strings[84636]="我知道你是什么人。一个卑鄙的拍卖行投机商。"
D.Strings[84637]="很好，我相信你。"
D.Strings[84638]="不……我是个好人！我……我有捐款给慈善基金，捐过一次！我也很少乱丢垃圾！$b$b还有，我从来都没有搞过大减价。"
D.Strings[84639]="事情发生的时候，还有其他目击者在场吗？"
D.Strings[84640]="好吧，我相信你。"
D.Strings[84641]="当然，我的骡子就在那儿。"
D.Strings[84642]="你的骡子？你一定是在逗我。"
D.Strings[84643]="好，我相信你。"
D.Strings[84644]="我不知道你干嘛要不依不饶地盘问我。我可是刚刚才失去了我的马车和所有的财产。"
D.Strings[84645]="我很想相信你，可你的话很没有说服力。"
D.Strings[84646]="只是例行公事。我相信你。"
D.Strings[84647]="等等……你不是想敲诈我吧？"
D.Strings[84648]="对，我就是要敲诈你。"
D.Strings[84649]="当然不了！我相信你的故事。"
D.Strings[84650]="可是……我把最后一个铜板都花在那车装备上了！我是说真的！我没有钱给你了！"
D.Strings[84651]="你的故事越来越说不通了，塞林。"
D.Strings[84652]="我相信你的故事。"
D.Strings[84653]="等等，这儿，看……$b$b<塞林从口袋里拿出了一叠收据。>$b$b看！！我买的东西都在这儿了，都是从达拉然最有名的护甲商人那里买的！"
D.Strings[84654]="这些看起来像是假收据。"
D.Strings[84655]="我觉得这一切都很诚实可信。我相信你。"
D.Strings[84656]="假收据？真的？$b$b请允许我大声说出来，因为我得整理一下思路。$b$b你说我带了恶魔的……玩意儿……进入达拉然，把它点燃，然后又在它们起火的时候在达拉然四处晃荡，最后又弄了一堆假收据以防有人查问？$b$b我说的对吗？对不对？你就是这么想的？"
D.Strings[84657]="对，我就是这个意思。"
D.Strings[84658]="别打了，天角的畜生！"
D.Strings[84659]="唔，你这么说的话，那我相信你。"
D.Strings[84660]="我在过去十一年里窝在一个潮湿的、臭烘烘的、人头攒动的拍卖行里，全指着一箱皮帽子挣几个银币。我不是什么被恶魔腐化的冒险者……我从来没见过恶魔。见鬼，我连我卖的装备都挥不动。$b$b<塞林满眼泪水地瞪着你。从一切外在表现看，他说的是真话。>"
D.Strings[84661]="你马上就会变成一只风鹏了！"
D.Strings[84662]="你是我的了，老鹰！"
D.Strings[84663]="那么，你对这种粉末知道多少？"
D.Strings[84664]="那不是我箱子里的东西。我总是会仔细检查我买的所有东西，我没有看到过任何发光的绿色物体。"
D.Strings[84665]="那不是我箱子里的东西。我总是会仔细检查我买的所有东西，我没有看到过任何发光的绿色物体。这让我想起了附魔用的粉尘。你应该去跟附魔师们谈谈。"
D.Strings[84666]="海拉巨大的身影耸立在平台的远处。\n\n这个祭坛似乎是和她沟通的渠道。"
D.Strings[84667]="我不属于这里！我要离开冥狱深渊！"
D.Strings[84668]="她是一辆漂亮的马车，曾经是。$b$b<塞林把眼泪抹在了他的胡子上。>"
D.Strings[84669]="你知不知道为什么你的车会爆炸并燃起邪能火焰？"
D.Strings[84670]="粉尘这种东西其实不怎么合适我，孩子。我是一个文字工作者，只跟墨水和卷轴打交道。$b$b现在，让我们理性思考一下这个问题吧：$b$b你的这些粉尘……是一种墨水吗？"
D.Strings[84671]="还是某种卷轴？"
D.Strings[84672]="你是在浪费我的时间吗？"
D.Strings[84673]="我能问你几个有关这种粉末的问题吗？"
D.Strings[84674]="带上那些粉尘去找附魔师纳萨尼斯吧。他或许知道该怎么处理它。"
D.Strings[84675]="……不是。"
D.Strings[84676]="再见，教授。"
D.Strings[84677]="我们与鹰身人的战斗仍在持续，但你的行动让盆地的局势稍微恢复了一点平衡。"
D.Strings[84678]="你准备好就说一声，勇士。"
D.Strings[84679]="我们很幸运，武士。你要找的勇士很快就会赶来。"
D.Strings[84680]="来吧，勇士。跟我走，我让你看看至高岭的力量。"
D.Strings[84681]="到下面的洞穴来见我吧，$n。让他们看看那个鹰身人的尸体。"
D.Strings[84682]="这些东西……我必须去警告其他人。"
D.Strings[84683]="让我看看……它闻上去很像恶魔之火，它的颜色也很像恶魔的腐蚀，而在达拉然的街道刚刚发生过爆炸和尖叫后不久，它就出现在了我的店铺里。$b$b你是想杀了我吗，$c？"
D.Strings[84684]="我这么说吧：$b$b这些粉尘和躺在我店门口那具还在闷烧的尸体有什么关系吗？"
D.Strings[84685]="那就快带着它出去！我的处境已经够糟糕的了。"
D.Strings[84686]="那就快带着它出去！把它带去附魔师的店里吧，他们比我更了解粉尘。"
D.Strings[84687]="我正在拼命忍住不杀了你。"
D.Strings[84688]="关于这些粉末，你有什么想说的吗？"
D.Strings[84689]="今天或许是我们的幸运日，$n。"
D.Strings[84690]="玛法里奥·怒风身在瓦尔莎拉，我和他取得了联系。他的人就快完成任务了——但保险起见，他们还需要一些支援。"
D.Strings[84691]="你还在等什么？这种唾手可得的胜利可不多见。好好享受这个过程吧！"
D.Strings[84692]="我们至今仍在传颂许多个世纪前至高岭对抗燃烧军团如潮攻势的传说。$b$b能再次站出来反抗他们是一种荣耀。"
D.Strings[84693]="带我去见你们的大酋长吧。"
D.Strings[84694]="你想要我的锤子！来拿啊！"
D.Strings[84695]="它们在咯吱作响！"
D.Strings[84696]="吱吱吱！啊呵呵呵！"
D.Strings[84697]="被我踩扁了！"
D.Strings[84698]="$n在哪儿？他们总是在我——啊，你来了！"
D.Strings[84699]="祝你们俩好运。你们会需要它的。"
D.Strings[84700]="我真不该到处乱跑。"
D.Strings[84701]="我们走吧。黑暗女王的舰队就快出发了。"
D.Strings[84702]="跟我来，$n。天火号就要出发了。"
D.Strings[84703]="$n是来见图鲁克的。$G他:她;击杀了森林女巫。"
D.Strings[84704]="挑战者？让我们看看这家伙有什么能耐吧！"
D.Strings[84705]="改装"
D.Strings[84706]="实验总能创造奇迹！仆从们，攻击！"
D.Strings[84707]="我负责监视山谷，追踪鹰身人的动向……可我被她们发现了。她们率先袭击了这里，让我无法观察到她们的主攻方向，为村子发出警告。我和我妻子只是平静地生活在这座山上，可她们打伤了我，杀害了我妻子。我担心她们还会去攻击我儿子，而我已经没法保护他了。"
D.Strings[84708]="他们来了，我听见了！"
D.Strings[84709]="不要乱动，$r。"
D.Strings[84710]="嘿！不许动！"
D.Strings[84711]="你可别想糊弄我，人渣。"
D.Strings[84712]="不想受伤的话就后退，$c。"
D.Strings[84713]="我还要更多的灵魂！来接受你的命运吧！"
D.Strings[84714]="你的小崽子会成为美味的点心！"
D.Strings[84715]="谢谢你救了我儿子。我永远不会忘记你的恩情。"
D.Strings[84716]="消灭所有讨厌的人类其实并不难，可这些恶魔……"
D.Strings[84717]="什么？你没看见我正忙着吗？这些恶魔可不会自己死掉！$B$B必须有人想办法解决他们。"
D.Strings[84718]="就算我再怎么喜欢钱，我也不会卖东西给恶魔！"
D.Strings[84719]="好吧，我来了。我知道这可能不是你们所谓的“恰当的时机”，可它们——我是说我的一些货物可以帮你们对付恶魔！"
D.Strings[84720]="我……我成功了！我是有史以来最伟大的术士！"
D.Strings[84721]="我到前面去守住升降机。"
D.Strings[84722]="我感觉附近有恶魔。虽然被禁锢多年，但我还是个好猎手。"
D.Strings[84723]="我的战刃准备好了，$n。我先去前面侦察一下。"
D.Strings[84724]="如果觉得尖塔麻烦，先摧毁稳定器。"
D.Strings[84725]="古尔丹不可能进入这座大厅的。我的守望者中出了叛徒！"
D.Strings[84726]="我也尝过被自己人背叛的苦涩。"
D.Strings[84727]="%s看着受难者奥图里斯。"
D.Strings[84728]="科达娜！高阶议会会惩罚你的罪行的。"
D.Strings[84729]="很快就好。虽然身躯已死，但灵魂还在挣扎。我们得让他做好准备。"
D.Strings[84730]="我们已经击败了你的勇士。现在，让我们离开冥狱深渊！"
D.Strings[84731]="伊利丹·怒风。总算见到伟大的背叛者了。"
D.Strings[84732]="谢谢你，$n。要不是你，我就得去对付那堆邪能死肉了。他肯定是被这里的魔力吸引来的。"
D.Strings[84733]="这是我第一次独自出来打猎！我追着一头野兽从瓦尔莎拉的另一边一直来到这里……他沿途所造成的破坏简直骇人听闻！所有线索都指向了这里。你愿意帮我一起追踪他吗？"
D.Strings[84734]="好吧。脚印往这边走了，一直通向那座雕像。跟我来！"
D.Strings[84735]="又要翻旧账吗，凯恩？"
D.Strings[84736]="看看这个！这块肉上的这种牙印我从来都没见过！等等……它们为什么会发绿光？"
D.Strings[84737]="别跟我说过去，奥图里斯。你背叛了伊利丹。你背叛了我们！"
D.Strings[84738]="在被囚禁了一万年后，伊利丹已被邪能所控制。被释放时，他已经不清醒了。"
D.Strings[84739]="他一直在抗争，我们也是。他需要我们给他信心，奥图里斯。"
D.Strings[84740]="而你却甘做伊利丹的走狗，不顾他已迷失了自我。"
D.Strings[84741]="他做出了艰难的抉择，牺牲了一切。你又付出了什么？"
D.Strings[84742]="那是恶魔？！我可没那个本事！我又不是恶魔猎手！！"
D.Strings[84743]="你也听到守望者的话了，只有我们能打败燃烧军团。我们必须逃出去。"
D.Strings[84744]="真是疯了！守望者的监狱完全失控了。"
D.Strings[84745]="除了我们，这一层原本还关押着一群最强大的囚犯。注意是“原本”！"
D.Strings[84746]="我要把这些护腕放进我们的临时熔炉里。"
D.Strings[84747]="现在，加入一点魔火，然后……"
D.Strings[84748]="万岁！成功了！"
D.Strings[84749]="真是天才，伊尔蒂！我们得到了多少抑魔金？"
D.Strings[84750]="大概有两格令。两格令抑魔金。"
D.Strings[84751]="唔，这只是个开始。"
D.Strings[84752]="我不建议这么做，卡德加。我们对于恶魔之力的了解很有限。这可能会引起燃烧军团的注意，甚至更糟。"
D.Strings[84753]="我同意。我们的工匠没有足够的技术建造这样一座熔炉。玩弄恶魔之力的危险太大了。"
D.Strings[84754]="我同意。你们所有人都应该明白，染指这种力量是非常危险的，恶魔猎手。我不允许我的城市里出现这种东西。"
D.Strings[84755]="我很抱歉，但你的请求被否——"
D.Strings[84756]="事实上，卡德加，我想我认识一个能够建造这种熔炉的人。一位专家。"
D.Strings[84757]="真的？谁？"
D.Strings[84758]="或许你不知道更好，先生。"
D.Strings[84759]="真是神秘。好吧！大法师卡莱会协助你的，$n。"
D.Strings[84760]="石像鬼从压力板上飞起，闸门砰地一声关上了。"
D.Strings[84761]="停止这场愚蠢的争吵吧。没时间吵架了！"
D.Strings[84762]="伊利丹大人教会我们奋斗与坚持。我们消灭了无数恶魔。而你却选择了懦夫的道路。"
D.Strings[84763]="我只相信我的眼睛，兄弟。伊利丹大人不比我们的敌人好多少。"
D.Strings[84764]="你杀害了我们的战友！你践踏了我们的牺牲！"
D.Strings[84765]="我们发现了一种从制造的护甲中抽取恶魔精华的新方法，但要想做到这一点，我们需要你批准建造一座熔炉。"
D.Strings[84766]="够了！我要用巨型地狱火碾碎你们。"
D.Strings[84767]="我可不是让你们来玩儿的。干掉他们！"
D.Strings[84768]="我要从你身上冲过去！"
D.Strings[84769]="你的经验不如我丰富！"
D.Strings[84770]="你以为你的拳头能比我硬吗？"
D.Strings[84771]="你跟我战斗的时候，应该带上头盔的！"
D.Strings[84772]="好了，停手！快停手！小心下巴！你赢了。我从没见过这么快的速度。你是好样的，老兄。保持下去。我过几天来拿我的腰带。"
D.Strings[84773]="燃烧军团的力量？哈！我们走着瞧……"
D.Strings[84774]="这是一个教训，所有想要入侵我们土地的人都得掂量掂量！"
D.Strings[84775]="守住阵线！这些狡猾的家伙根本不知道什么叫战争！"
D.Strings[84776]="希尔瓦娜斯让我取下你们所有人的首级！我一定会照办的。"
D.Strings[84777]="今天唯一会流血的人就是燃烧军团！"
D.Strings[84778]="我可是至高岭的重量级冠军！你以为你会是我的对手吗，小鬼？这可是职业拳赛！让我看看你的本事吧……不过被我打倒之后，你最好别再爬起来了！"
D.Strings[84779]="事情不像表面看起来那么简单，$n。我建议你严密监视你周围的人。"
D.Strings[84780]="你好啊，勇士。$b$b大酋长乌兰派我来找你。"
D.Strings[84781]="他手下留情了，外来者。来吧，说几句。"
D.Strings[84782]="这座洞穴有点不对劲。"
D.Strings[84783]="小心，$n。灵魂引擎里有个恐惧魔王。"
D.Strings[84784]="很好，引擎里又要多一条灵魂了。"
D.Strings[84785]="泰兰娜……救我。"
D.Strings[84786]="至少你的灵魂可以做引擎燃料。"
D.Strings[84787]="至少你的灵魂能作引擎燃料。"
D.Strings[84788]="发信号给蝙蝠骑士！"
D.Strings[84789]="我要谢谢你，外来者。"
D.Strings[84790]="我该回去战斗了！"
D.Strings[84791]="我要让这些废物尝尝瓦尔基拉的怒火！"
D.Strings[84792]="你把我从无法想象的命运中解救了出来。谢谢你。"
D.Strings[84793]="我们绝不会放过海拉！"
D.Strings[84794]="乌拉！我在这儿！你在哪儿？"
D.Strings[84795]="哦，乌拉，你受伤了！"
D.Strings[84796]="$n，我们必须想办法救救他！"
D.Strings[84797]="以圣锤之名，我将统治至高岭！"
D.Strings[84798]="诅咒结束了！我终于可以去英灵殿继续战斗了！"
D.Strings[84799]="我的灵魂属于奥丁。"
D.Strings[84800]="我不会变成克瓦迪尔了！"
D.Strings[84801]="奥丁对我们微笑了。"
D.Strings[84802]="海拉这个蠢货还以为能关住我。"
D.Strings[84803]="去英灵殿！"
D.Strings[84804]="地底之王达古尔！下来面对被你背叛的人们并接受制裁吧。"
D.Strings[84805]="欢迎来到雷霆图腾，勇士。在全盛时期，这里还会有鲜血图腾部族的战士，或是天角部族的雄鹰骑士。可如今，我们连狗头人都难以应付。"
D.Strings[84806]="你一定要把它完整地开回来，好吗？去吧！"
D.Strings[84807]="这辆坦克上的撞角经过了增压，这可是我手工制作的！去为我干掉几只恶魔吧！"
D.Strings[84808]="这可是诺莫瑞根最尖端的反恶魔科技！好好使用它吧。"
D.Strings[84809]="我想这可能也没有那么糟……"
D.Strings[84810]="那我们需要付出什么作为回报呢？"
D.Strings[84811]="一切！"
D.Strings[84812]="装上弹药，好好教训他们一顿吧。一路平安！"
D.Strings[84813]="死从天降什么的最带劲了，你说呢？狠狠教训他们吧！"
D.Strings[84814]="小……心……这是……陷阱……"
D.Strings[84815]="让我们检查一下，然后就点火吧！"
D.Strings[84816]="拜托，击退他们！我来保护我儿子！"
D.Strings[84817]="我已经没救了，罗萨琳。你得集中精神找到从灵魂牢笼里逃出来的恶魔，把他们再次禁锢起来，否则就迟了。"
D.Strings[84818]="护魂者乌拉痛苦而缓慢地吸了一口气。"
D.Strings[84819]="我的时间宝贵。有话快说，不然就走。"
D.Strings[84820]="打开那些井，用灵魂洪流淹没他。"
D.Strings[84821]="杀了他们，不能让他们登上邪能之槌号。"
D.Strings[84822]="保护好灵魂引擎。"
D.Strings[84823]="谢谢你来救我。我来看看有没有其他幸存的武士。"
D.Strings[84824]="噢！你抓到了一些小家伙！我们来战斗吧，如果我赢了，就让我吃一个！"
D.Strings[84825]="哈哈哈！这下他们看到我们真正的实力了。"
D.Strings[84826]="弗鲁莫斯不需要宠物！弗鲁莫斯要吃了它们！"
D.Strings[84827]="我还在进行训练，马克。我一定会把我的腰带赢回来的！"
D.Strings[84828]="这个平台能够带你进入神圣的酋长大殿，梅拉正在那里等着你。"
D.Strings[84829]="可……我不知道该怎么做，乌拉。没有了你，我做不到的！"
D.Strings[84830]="你可以的，罗萨琳，你也一定能做到。你比你自己以为的更有天赋。"
D.Strings[84831]="护魂者乌拉疲惫地呼出一口气，最后的气息就这样离开了他死寂的躯体。"
D.Strings[84832]="用你的拳头去揉，不要用脸！"
D.Strings[84833]="组合拳，组合拳！来啊！"
D.Strings[84834]="胜利也没那么糟糕。你们都应该尝一下那种滋味！"
D.Strings[84835]="谢谢，我还以为自己死定了呢！"
D.Strings[84836]="所以陶森才会是最好的拳手！继续训练！"
D.Strings[84837]="艾露恩之光在上，谢谢！"
D.Strings[84838]="我们得守住神殿！"
D.Strings[84839]="在天上待三个小时也太久了。我们需要更多的飞行员！"
D.Strings[84840]="我一直都渴望能飞行……可我不想在世界末日飞啊。"
D.Strings[84841]="我要累死了……我都不知道我今天还能不能再飞一次了。"
D.Strings[84842]="保持警惕，我们身上的责任太重了。我们很快就要回到天上了。"
D.Strings[84843]="我们患难与共，好吗？你在天上飞得很好！我们会撑过去的。"
D.Strings[84844]="艾泽拉斯的未来就要看我们的空战表现了。坚强点，为了我们大家。"
D.Strings[84845]="去吧，勇士。我会召集所有的部队去突袭南方的卓格巴尔堡垒。等你准备好之后，就到洞口来找我吧。"
D.Strings[84846]="我无法相信他死了……"
D.Strings[84847]="雄鹰在飞走前点了点头，表示感谢。"
D.Strings[84848]="这真是一场灾难……但我们能赢！让坦克继续动起来。让我们的小鸟继续升空。就算这个世界会毁灭，也得在侏儒科技好好发威以后！"
D.Strings[84849]="继续前进吧。其他人就在前面的大厅里。"
D.Strings[84850]="我尊重历史，但我不能原谅伊利丹。伊利达雷需要更好的领袖。"
D.Strings[84851]="看来我们无话可说了。$n，你得解决这个矛盾。"
D.Strings[84852]="<塔莉萨无法控制地颤抖起来，几乎说不出话来。|cFFF92304必须首先满足她的饥渴，然后才能进行其他行动。|r>"
D.Strings[84853]="暗夜井蕴藏着不可思议的庞大力量。我们决不能让燃烧军团染指它。"
D.Strings[84854]="是的！我能感受到能量在我体内流淌！\n\n我又完好如初了。"
D.Strings[84855]="这是什么？海拉肯定会为了这个贡品而奖赏我的。"
D.Strings[84856]="我很惊讶，你们居然能走到这里，恶魔猎手。现在，我要像吹熄烛火一样熄灭你们的灵魂！"
D.Strings[84857]="我是肯瑞托的首领，大法师卡德加。"
D.Strings[84858]="恶魔猎手，艾泽拉斯需要你们。"
D.Strings[84859]="海拉被击败了，是时候召唤瓦格里了！"
D.Strings[84860]="只要击败那个女巫，我就能解放她偷来的瓦尔基拉之魂了。"
D.Strings[84861]="它的手刹有点小毛病，下山的时候小心点儿，头儿。"
D.Strings[84862]="尖刺……大石头……一切看起来都很正常。去狠狠砸死那些恶魔吧！"
D.Strings[84863]="狠狠揍他们！部落的力量能烧死一切恶魔！"
D.Strings[84864]="队长，报告情况！"
D.Strings[84865]="我们在灵魂引擎附近遭遇了激烈抵抗。"
D.Strings[84866]="进攻开始了。我会和你一起攻击那个监督者。"
D.Strings[84867]="加油的时候小心点。这辆坦克有点旧了！"
D.Strings[84868]="……战争领主，报告情况！"
D.Strings[84869]="我给你装了一大堆炸药。你一定要将它们都扔到恶魔头上，行吗？"
D.Strings[84870]="气球已经补好了，可我还是放了一顶降落伞在里面以防万一！至少我记得我放了。"
D.Strings[84871]="我们夺回了南点大门的控制权！我马上派地面巡逻队去塔伦米尔！"
D.Strings[84872]="快保命吧！我要来了！"
D.Strings[84873]="喂食：100份 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:20|t|Hcurrency:1155|h|cFFFFFFFF远古魔力|h|r"
D.Strings[84874]="燃烧军团已经开始入侵我们的世界。从海洋到沙滩，勇敢的联盟和部落保卫者们都在响应战斗的召唤。\n\n但是，如果没有恶魔猎手的帮助，他们还是会失败的。你们经受过专门的训练，是对付燃烧军团的冷酷利器。是时候主动出击了。"
D.Strings[84875]="确认使用|TINTERFACE\\ICONS\\INV_OFFHAND_PVEALLIANCE_D_01.BLP:20|t|Hitem:129094|h|cFF0070DD暗夜井美酒|r|h来强化这个堕夜精灵吗？"
D.Strings[84876]="喂食远古魔力|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:20|t x100"
D.Strings[84877]="谢谢你，勇士。但小心点，卓格巴尔的地底之王拥有一件泰坦的利器。"
D.Strings[84878]="我……我的村子。它完了。"
D.Strings[84879]="以黑暗女王之名！"
D.Strings[84880]="让这个走狗去告诉他们。等我掌握了圣锤，他们就死到临头了。"
D.Strings[84881]="来吧，让你疲惫的灵魂在柔软的床铺上好好休息一下吧。"
D.Strings[84882]="太好了，你成功了！击败海拉，我就能释放这些灵魂了！"
D.Strings[84883]="现在，你的灵魂属于海拉了，爬虫！"
D.Strings[84884]="窒息的潮水将淹没你！"
D.Strings[84885]="来吧，英雄！跟我们走，我们会帮你干掉这些恶魔的！"
D.Strings[84886]="没人能够逃出……海拉的掌心……"
D.Strings[84887]="有人吗？来人啊！救命！！！"
D.Strings[84888]="我看见你了，欧库纳。你以为你杀了我父亲之后还能逍遥法外吗？"
D.Strings[84889]="我想测试一下这种颜料。让我们来看看……"
D.Strings[84890]="它的效果比预期的还要好。对，这种颜料一定会派上大用场的。"
D.Strings[84891]="我丈夫说我参加的战斗太多了。他知道什么？"
D.Strings[84892]="什么？我都躲起来了，难道这还不能让你明白我不想被人打扰吗？$b$b如果你还为自己着想的话，就快滚！"
D.Strings[84893]="恶魔已经杀害了我的两个姐妹。你想搜查那辆马车？随你。"
D.Strings[84894]="别告诉任何人，好吗？"
D.Strings[84895]="拿下！"
D.Strings[84896]="噢，拜托！"
D.Strings[84897]="来真的？！？"
D.Strings[84898]="你到底有什么毛病？！"
D.Strings[84899]="你暂离了吗？"
D.Strings[84900]="你或许该换几个好宠物上来。"
D.Strings[84901]="你到底有没有认真打啊？"
D.Strings[84902]="我们需要达拉然议会的允许才能建造足以批量生产抑魔金的大型熔炉。"
D.Strings[84903]="你似乎和卡德加关系不错——或许你应该去问他，$n。"
D.Strings[84904]="我把抑魔金弄丢了。"
D.Strings[84905]="噢，瓦妮萨！"
D.Strings[84906]="嗯？你想要什么？我正在做生意呢！"
D.Strings[84907]="是伊尔蒂派我来的。你欠她的货呢？"
D.Strings[84908]="去告诉伊尔蒂，我有一个更好的建议。现在，在我发火之前快滚！"
D.Strings[84909]="如果你想要贿赂我，那你最好三思而行。我有责任保障这些下水道的安全！$b$b<莱杉压低了声音悄悄地道：>$b$b你过一会儿再来，我们好好谈谈，$c。"
D.Strings[84910]="对，我知道外面有人在打架。我的卫兵们只是需要……休息一下。$b$b<莱杉压低了声音悄悄地道：>$b$b你想让我们回到岗位上去？那就过一会儿再来，记得带上盲目之眼。"
D.Strings[84911]="给你一个有关贿赂的小提示，$r：提议之前一定要先带够了钱。现在，要是你不想在紫罗兰监狱里开个房间的话，就滚出我的视线！"
D.Strings[84912]="<威胁贝拉米。>"
D.Strings[84913]="好吧，好吧！你把我拆穿了。我可以把你想知道的告诉你，顽固的$G小子:丫头;。$b$b我把附魔补给品卖给了达拉然的一个黑市商人。我忘了是叫格里姆波尔还是博格里姆了……总之是个类似的兽人名字。$b$b现在请你走开，好吗？我有客人上门了。"
D.Strings[84914]="我要告诉伊尔蒂你想要骗她。"
D.Strings[84915]="我有话跟你说，贝拉米。"
D.Strings[84916]="我受够了。只要一有机会，我就回莫亚基港口去。"
D.Strings[84917]="地底之王陛下，这个家伙还活着。"
D.Strings[84918]="这是你要的卡牌。"
D.Strings[84919]="它们早就该丢……呃……我是说，让我看看这些该怎么处理。"
D.Strings[84920]="这种鱼鳞颜料真是神奇，我应该出售它……"
D.Strings[84921]="最后，再来一点魔法和……"
D.Strings[84922]="看呐！完成了。"
D.Strings[84923]="我已经把你想知道的都告诉你了。这还不够吗？$b$b我真的不想引人注目……"
D.Strings[84924]="强化：1x |TINTERFACE\\ICONS\\INV_OFFHAND_PVEALLIANCE_D_01.BLP:20|t|Hitem:129094|h|cFF0070DD暗夜井美酒|r|h"
D.Strings[84925]="是战争领主派我来的。"
D.Strings[84926]="我们会摧毁燃烧军团的。"
D.Strings[84927]="很荣幸能以伊利丹大人的名义杀敌。"
D.Strings[84928]="我听候伊利丹大人的吩咐。"
D.Strings[84929]="这个恶魔死定了。"
D.Strings[84930]="我是来帮你的。"
D.Strings[84931]="灰舌听您差遣。"
D.Strings[84932]="必须阻止燃烧军团。"
D.Strings[84933]="赛丝诺女士让我来加入你的队伍。"
D.Strings[84934]="燃烧军团必将覆灭。"
D.Strings[84935]="燃烧军团的魔法在纳迦眼里不值一提。"
D.Strings[84936]="库斯卡听候伊利丹大人的吩咐。"
D.Strings[84937]="库斯卡向来一诺千金。"
D.Strings[84938]="必须在燃烧军团烧毁我们的世界前阻止他们。"
D.Strings[84939]="主母让我来帮忙。"
D.Strings[84940]="我们帮你消灭燃烧军团。"
D.Strings[84941]="我跟随伊利丹。"
D.Strings[84942]="我一定会把这个恶魔千刀万剐的。"
D.Strings[84943]="我是来大开杀戒的。"
D.Strings[84944]="破坏魔为您效劳。"
D.Strings[84945]="我们一定要阻止燃烧军团征服星球的步伐。"
D.Strings[84946]="凯恩，告诉我有关马顿的情况。"
D.Strings[84947]="如果这场战斗不能速战速决的话，我们就需要更多的补给。"
D.Strings[84948]="拜托。你不能就这样出去！"
D.Strings[84949]="你马上就能重新站起来了。"
D.Strings[84950]="从好的一面来说——你或许会因为那样的英勇壮举而获得晋升！"
D.Strings[84951]="我把附魔补给品卖给了达拉然的一个黑市商人。我忘了是叫格林波尔还是波格林姆了……总之是个类似的兽人名字。$b$b现在请你走开，好吗？我有客人上门了。"
D.Strings[84952]="你们的灵魂将沉沦苦海！"
D.Strings[84953]="没用的下等种族！"
D.Strings[84954]="你们的世界已经完了，凡人！"
D.Strings[84955]="啊，$n，好久不见。人到齐了，我们开始吧。"
D.Strings[84956]="臣服在萨格拉斯的力量之下吧。"
D.Strings[84957]="这个世界的下场早已注定！"
D.Strings[84958]="卑微的凡人。我要亲自解决你们。"
D.Strings[84959]="我要让你搞清楚自己究竟面对的是什么样的对手！"
D.Strings[84960]="别动！我保证不会很疼的！"
D.Strings[84961]="我今天就让你看看自己的肠子长什么样！"
D.Strings[84962]="你好像迷路了，朋友。"
D.Strings[84963]="青龙在上！那是什么？！"
D.Strings[84964]="你惹错矮人了。"
D.Strings[84965]="今天可不是你的幸运日！"
D.Strings[84966]="想想我以前最害怕伊尔蒂回到拉文霍德的日子！她现在已经温柔多了！"
D.Strings[84967]="别客气，愿清风常伴你左右。"
D.Strings[84968]="做好准备！他要下来了！"
D.Strings[84969]="我们可是受过专门训练的！"
D.Strings[84970]="我来拖住他，萨满。去帮别人！"
D.Strings[84971]="训练看来没有白费！干得不错！"
D.Strings[84972]="不管是谁来多管闲事，都要尽快解决掉！"
D.Strings[84973]="这里的服务真是糟糕。太糟糕了！"
D.Strings[84974]="我是来找贝拉米卖给你的附魔补给品的。"
D.Strings[84975]="我这些补给品的来路光明正大！我是一个诚实的商人，就想混口饭吃而已！"
D.Strings[84976]="你这已经构成销赃了。把它们交出来！"
D.Strings[84977]="啊……迷雾散开了，就是有点……"
D.Strings[84978]="谢谢你，我刚才……失控了。"
D.Strings[84979]="呃，我永远都习惯不了那种事。"
D.Strings[84980]="坚持住，多亏了你……"
D.Strings[84981]="我的头……还是很晕……"
D.Strings[84982]="哦，要不是实物的味道……"
D.Strings[84983]="噢，我一直都想要这个！"
D.Strings[84984]="你很及时。我们肃清了达古尔面前的道路。这边……"
D.Strings[84985]="我终于不渴了。"
D.Strings[84986]="啊，我又活力焕发了！"
D.Strings[84987]="我的头脑再次充满了智慧的火花。我恢复了。"
D.Strings[84988]="我体内的力量汹涌澎湃！"
D.Strings[84989]="我是来找附魔补给品的，波格林。它们在哪儿……"
D.Strings[84990]="这种感觉……如潮水般涌来……我又活过来了！"
D.Strings[84991]="听着，我不想惹麻烦。我只想……"
D.Strings[84992]="看来我今天不会再枯竭了……"
D.Strings[84993]="呼。我就快好了……马上就好。"
D.Strings[84994]="呃……还是头晕……"
D.Strings[84995]="我还活着……暂时还活着。"
D.Strings[84996]="哦，它在烧灼我的胃。这感觉真不错！"
D.Strings[84997]="我的力量又回来了！"
D.Strings[84998]="啊，能再次恢复良好状态的感觉真不错。"
D.Strings[84999]="它就像一阵轻风！谢谢你！"
D.Strings[85000]="这种力量……我以前真的体验过这种感觉吗？"
D.Strings[85001]="不！我的钱！我本来还想买游艇的……"
D.Strings[85002]="驻扎大领主达里安·莫格莱尼。"
D.Strings[85003]="驻扎萨萨里安。"
D.Strings[85004]="驻扎库尔迪拉·织亡者。"
D.Strings[85005]="我们会留在这里，以防恶魔再来窃取能量。继续进攻！"
D.Strings[85006]="这么多能量……我们得留在这里，防止恶魔继续从这个火山口汲取能量。继续战斗！"
D.Strings[85007]="|TInterface\\Icons\\spell_frost_summonwaterelemental:20|t%s开始施放|cFFFF0000|Hspell:193051|h[呼潮引浪]|h|r！"
D.Strings[85008]="击退他们！别让他们伤害你们的兄弟姐妹！"
D.Strings[85009]="$n！你们恶魔猎手都不值一提。"
D.Strings[85010]="萨格拉斯亲手将钥石交给了我。你们休想夺走它！"
D.Strings[85011]="这种雾气对我的船员有着不好的影响。他们变得狂暴且难以控制。他们不再关注大海，而更喜欢互相争吵打斗。$B$B港口主管柯吉尔已经命令我们出去尽快寻找新的补给了。我还有一个额外的任务，就是希望工作能够让他们忙碌起来，直到我们的船出发为止。$B$B我只希望海风能让我的船员冷静下来，恢复活力。"
D.Strings[85012]="快。凯恩对泰兰娜已经发动了攻击。"
D.Strings[85013]="我们完成了不可能的任务。我必须承认，我原本对你的领导能力是有所怀疑的，$n。但这种疑虑现在已经打消了。\n\n让我们回去终结黑暗神殿的战斗吧。伊利丹大人还在等着我们。"
D.Strings[85014]="你的邪法没用的，怪物！这些书籍是受我保护的。"
D.Strings[85015]="滚开，怪物！"
D.Strings[85016]="放弃吧！你打不中我的！"
D.Strings[85017]="或许我应该留在据点。我在下头被俘虏时受的伤还没有恢复。\n\n这个世界充斥着恶魔能量。这会让我更加难以控制体内的邪能。"
D.Strings[85018]="将伊利达雷据点设为你的家。"
D.Strings[85019]="$n，你成功了！"
D.Strings[85020]="祝你们好运。我会把其他人送上去的，$n。"
D.Strings[85021]="谢谢，朋友！我的学生为了保护这些卷轴而死。不然，数百年的历史就失传了！"
D.Strings[85022]="我们的港口受到了诅咒。$B$B海鸥像石头一样从天而降。前几天我还看到一只海鸥砸到了一个码头工人的头上，直接把他砸晕了。$B$B大批翻着肚皮的死鱼在浅湾中腐烂。我们的渔夫已经连续几周没有捕到像样的鱼了，而且到处还充满了死鱼的可怕臭气。$B$B我的大部分卫兵都失踪了，我不得不担负起额外的瞭望任务。我只能到这里来喘口气，至少这里的臭味和陈腐的空气没那么严重。$B$B这个港口已经死了。迷雾正在扼杀这里的所有生命。"
D.Strings[85023]="<补给采购单上还附了一张纸条。>$B$B港口主管柯吉尔，$B$B我不知道这些雾气到底携带着什么邪恶的灾祸，可它们才笼罩了港口一天，我们所有的补给品就都坏了。我们需要立即补充补给。$B$B等斯坦船长一恢复，就派他出去搜索补给品，当然，这还得建立在他能制止船员无休止的吵架和打斗的情况下。$B$B与此同时，我们都必须勒紧裤腰带，节省度日了。鉴于大部分镇民都已失踪，我想这应该并不困难。"
D.Strings[85024]="<名单上的大部分条目都空着。其中一张纸的角落里写着几行潦草的字迹。>$B$B让这些该死的迷雾都下冥狱深渊去吧！它们出现后不久，我的大部分工人就都失踪了，剩下的少部分人也都无心工作了。他们看起来就好像一头撞上了桅杆似的。$B$B就凭这一小撮懒鬼，我要怎么才能让斯坦的船做好出航的准备？$B$B我会尽量让船做好准备的，哪怕只剩我一个人干活也不怕，但我的工作队伍急需人员的补充。"
D.Strings[85025]="你在这里很危险。大宗师海特要所有人都去玄牛神龛集合。"
D.Strings[85026]="达古尔偷走卡兹格罗斯之锤时，我和其他酋长就在现场。"
D.Strings[85027]="前任大酋长乌兰想阻止他，却被杀害了。梅拉虽然接掌了她父亲的图腾，但她还不是大酋长。"
D.Strings[85028]="达古尔不仅窃取了圣锤，还分裂了人民，在部族间造成了裂痕。"
D.Strings[85029]="他是我认识的最强大的武僧之一，但他也坚持不了多久。来吧，我们得去救他们！"
D.Strings[85030]="这个邪能祭坛和斯科瓦尔德试图奴役托里姆峰的托林尼尔巨龙时所使用的很相似。$B$B它非常强大，似乎无法用常规手段来摧毁。"
D.Strings[85031]="你晋升的时候已经到了。做好准备，奥丁正在等着你。"
D.Strings[85032]="使用狱卒的碎片打开维瑟尔的牢笼。"
D.Strings[85033]="我们就快出去了，$n。我们马上就要自由了。"
D.Strings[85034]="这些野兽相当暴躁，除非你知道该怎么对付它们。这个应该会听你的命令……至少会听一会儿。"
D.Strings[85035]="你已经毁了我的生意，就不能让我一个人呆会儿吗？"
D.Strings[85036]="这些年来，我们被守望者隔离、放逐到世界最黑暗的深渊。\n\n现在，我们必须站出来面对这个世界前所未有的挑战。现在，我们必须保护艾泽拉斯，抵抗它最强大的敌人。"
D.Strings[85037]="很好，$r，我这就把补给品送到附魔商店去。现在，让我独自安静地喝一杯！"
D.Strings[85038]="虽然很难，我还是设法收集到了一些武器和补给。你需要什么？"
D.Strings[85039]="我会暂时保留我的异议。敌人就快打到我们家门口了，我们只有团结一致，行动效率才会更高。"
D.Strings[85040]="你们的世界是最后的堡垒。而它也将被净化。"
D.Strings[85041]="我看过无数你的同胞走过人生道路，但没有一个能像你这样大踏步地前进。$B$B我期待着能向别人讲起你的故事。"
D.Strings[85042]="我们不过是这场狂潮的先锋。"
D.Strings[85043]="你的末日已经降临了。"
D.Strings[85044]="准备迎接你的末日吧！"
D.Strings[85045]="我就是你的末日！"
D.Strings[85046]="抵抗也只能暂时拖延注定的结局！"
D.Strings[85047]="你们的世界将化为尘土。"
D.Strings[85048]="啊，达拉希尔，我的朋友！快来喝一杯！"
D.Strings[85049]="别让这个$c把你吓跑了，达拉希尔！等等……回来！"
D.Strings[85050]="去死吧！！"
D.Strings[85051]="大宗师海特……<喘气>大宗师海特！天上出现了一个……庞然大物！"
D.Strings[85052]="|TInterface\\Icons\\INV_Spear_07:20|t%s用|cFFFF0000|Hspell:191977|h[穿刺之矛]|h|r瞄准了你！快躲到别人身后去！"
D.Strings[85053]="看看那些渡鸦丢下了什么。"
D.Strings[85054]="呼！！继续，$n，去激活下一个池子。"
D.Strings[85055]="它……想要出来！快，$n，激活最后一个池子！"
D.Strings[85056]="|TInterface\\Icons\\INV_Enchant_EssenceArcaneSmall:20|t%s用一个巨大的|cFFFF0000|Hspell:192708|h[奥术炸弹]|h|r瞄准了|cFFFF0000$n|r！"
D.Strings[85057]="到处都是恶魔——"
D.Strings[85058]="你是在与一片古老土地上的元素之灵同行，$r。"
D.Strings[85059]="完成了。我重新控制住这头恶魔了。"
D.Strings[85060]="|TInterface\\Icons\\Spell_Shadow_ShadeTrueSight:20|t%s开始施放|cFFFF0000|Hspell:197969|h[震耳喧嚣]|h|r！"
D.Strings[85061]="|TInterface\\Icons\\ability_shawaterelemental_swirl:20|t当近战范围内没有敌人时，|cFFFF0000|Hspell:192696|h[狂怒风暴]|h|r就会发动！"
D.Strings[85062]="啊，又是你，废物。现在只剩你我……还有我的卫兵了！"
D.Strings[85063]="嘶！积怨的战士们，碾碎他们！"
D.Strings[85064]="积怨纳迦们，淹死他们！"
D.Strings[85065]="蠢货！滚开！"
D.Strings[85066]="你休想阻挡……风暴……"
D.Strings[85067]="废物。全是废物！"
D.Strings[85068]="一条落网的鱼。"
D.Strings[85069]="这下是为了阿茜萨。"
D.Strings[85070]="哈，无处可藏了吧！"
D.Strings[85071]="尝到厉害了吗？"
D.Strings[85072]="我必须去蔑潮港找回一件神器。"
D.Strings[85073]="糟糕！我们来不及从敌军中杀出去了！"
D.Strings[85074]="你想找什么，$c？"
D.Strings[85075]="我准备好了，开启仪式吧。"
D.Strings[85076]="沼岩鱼人最喜欢用它们的临时灯塔制造海难。鱼人很好，但这群鱼人太残忍了。\n\n我们必须拯救这片海滩！这个年轻的鱼人叫奔波尔霸，他是我一手带大的。我们得帮他变强，这样他就能训练我们的蝌蚪，让他们青出于蓝了。"
D.Strings[85077]="你差点就打中我了，再接再厉！"
D.Strings[85078]="你以为它能打中我吗？"
D.Strings[85079]="快跑！我来挡住这个怪物！"
D.Strings[85080]="不要这么招摇。相比与敌人战斗，静静观察可以了解到更多。"
D.Strings[85081]="“过来，尼古拉。”$b$b“把那个拿给我，尼古拉。”$b$b我跟你说，总有一天，发号施令的人会变成我的。"
D.Strings[85082]="你准备好了就告诉我一声，尼古拉。"
D.Strings[85083]="小心点，$n。"
D.Strings[85084]="做好准备，以防万一，$n。"
D.Strings[85085]="呼，这可比看起来要难多了。"
D.Strings[85086]="目前看来一切顺利。别停下，$n。"
D.Strings[85087]="我就快完成了，我发誓。"
D.Strings[85088]="刀风队长！有一名战士在攻击我们！"
D.Strings[85089]="哟，勇士！我们正在日以继夜地研究整理，以保证这个组织里的所有成员都了解独一无二的刺客大师$n。$B$B你确实只有一个人，是吧？"
D.Strings[85090]="成功了！我们做到了，$n！"
D.Strings[85091]="有人在大门上方看到了神王斯科瓦尔德。\n\n你准备好之后，我们就跟他开战！"
D.Strings[85092]="送我去山顶，维瑟尔！"
D.Strings[85093]="这需要的时间可能比预计的要长。回收必要的零件可是很困难的！"
D.Strings[85094]="毁灭万物！"
D.Strings[85095]="水……永恒……"
D.Strings[85096]="卷走一个。"
D.Strings[85097]="四分五裂。"
D.Strings[85098]="风暴已经苏醒。"
D.Strings[85099]="<这块水晶散发着邪恶的能量。>"
D.Strings[85100]="<将入梦叶放在水晶下。>"
D.Strings[85101]="我看看能不能多找到一些零件！我们需要所有可能的帮助。"
D.Strings[85102]="伊万·班立开始吹起悲伤的调子。"
D.Strings[85103]="你在插手你根本无法理解的事情，侏儒！"
D.Strings[85104]="寻找……魔力……"
D.Strings[85105]="魔法……能量……"
D.Strings[85106]="你休想完成你的工作！"
D.Strings[85107]="在刻下最后一笔之前，你就会送命！"
D.Strings[85108]="你好！有兴趣学习制皮吗？"
D.Strings[85109]="我想找一些皮革封面。"
D.Strings[85110]="哦，对了，我们前几天刚进了一批货物。如果你想看看的话，它们就在楼上。"
D.Strings[85111]="感谢你的协助，朋友！那个恶心的怪物可真能打！"
D.Strings[85112]="孩子们！规矩点儿！"
D.Strings[85113]="我预感还有更多战斗在等着我们。$b$b<蒋震魂看了一眼孩子们。>$b$b我得带他们离开这里！"
D.Strings[85114]="对不起，风暴烈酒师傅。"
D.Strings[85115]="对不起，先生。"
D.Strings[85116]="对不起。"
D.Strings[85117]="再来啊，怪物！"
D.Strings[85118]="你空有力量，却没有速度！"
D.Strings[85119]="走开，$r！我听到美酒在呼唤我的名字。"
D.Strings[85120]="我要挑战你，托尔。"
D.Strings[85121]="我要挑战你，拉努夫。"
D.Strings[85122]="我要挑战你，赫尔多。"
D.Strings[85123]="我要挑战你，布约恩。"
D.Strings[85124]="我们决不能让斯科瓦尔德把这些污秽之物带入英灵殿！"
D.Strings[85125]="<一位早就被人遗忘的维库人的古老墓穴。>"
D.Strings[85126]="<将20份夏斯卡格草放在石冢下。>"
D.Strings[85127]="斯科瓦尔德虽然跑了，但胜利仍然属于我们。多亏了你，他的恶魔再也不能为祸风暴峡湾了。\n\n让我们返回大门吧，朋友。我相信哈维也会想要谢谢你的。"
D.Strings[85128]="送我回勇者之门。"
D.Strings[85129]="我是陛下的利剑。不朽者埃格尔！"
D.Strings[85130]="我将继续坚守岗位，为陛下效命！"
D.Strings[85131]="你休想阻止陛下的归来！"
D.Strings[85132]="原谅我，陛下。我的警戒任务……失败了。"
D.Strings[85133]="我辜负了你们，守望者们。陛下无法归来了。"
D.Strings[85134]="我的视力已经衰退，但我的剑依然锋利！"
D.Strings[85135]="你休想走到不朽者面前，我会先杀了你！"
D.Strings[85136]="我不用眼睛也能打败你！"
D.Strings[85137]="别去打扰……不朽者。"
D.Strings[85138]="我终于看清你了……"
D.Strings[85139]="我的守望终于结束了。"
D.Strings[85140]="如果不阻止那些卓格巴尔，至高岭的巨鹰就要绝种了。"
D.Strings[85141]="<地上有一小堆干草药。这不是自然生成的——是有人……或者什么东西将它们放在这里的。>"
D.Strings[85142]="萨格拉斯的钥石是击败燃烧军团的计划中最关键的一环。"
D.Strings[85143]="“您就像艾泽拉斯的双月一样美丽……”"
D.Strings[85144]="“您可真可爱。”"
D.Strings[85145]="“我正盼着今晚能掉几条史诗裤子呢。”"
D.Strings[85146]="|cFF600000<这个故事已经开了个头，但还没有写完。>|r$b$b向来口若悬河的格雷斯班爵士走进了皇家大厅。他面前站着一位以美丽、优雅和机敏著称的德莱尼公主。$b$b他以最诚挚的赞美欢迎这位珠光宝气的公主。$b$b|cFF600000<下面一行空着。格雷斯班爵士会说些什么呢？>|r"
D.Strings[85147]="该死的外来者！你休想知道夏多雷草药学的秘密！我宁愿把它们带进坟墓里去！"
D.Strings[85148]="“您就像艾泽拉斯的双月一样美丽。”$b$b蓝皮肤的公主唇边浮现出一丝淡得不能再淡的笑意。但她很快就克制住了，不让格雷斯班爵士发现她的真实感受。她很快就答道：$b$b|cFF600000<下一行空着。德莱尼公主会怎么回答呢？>|r"
D.Strings[85149]="“您可真可爱。”$b$b公主仍然望着格雷斯班爵士的嘴，似乎等待着他说出更多的赞美。随着时间的推移，她才渐渐意识到，这句话真的只有短短的五个字。$b$b在她彻底明白轮到自己说话了时，她答道……$b$b|cFF600000<德莱尼公主会怎么回答呢？>|r"
D.Strings[85150]="“您的魅力对我毫无作用，外来者。您奉承人的本事才刚刚入门呢。”"
D.Strings[85151]="“你那把剑可真够大的。你真的知道怎么使用它吗？”"
D.Strings[85152]="“你的护腿里藏了一只侏儒吗？或者是两只？”"
D.Strings[85153]="“这个‘门’是指殿下您的私人卧室门吗？”"
D.Strings[85154]="“好吧，再见。”"
D.Strings[85155]="“当然，我最擅长使剑了。这是一把双手剑，我在兵器铺里买的。”"
D.Strings[85156]="都听到了吧？让我们去找到那块钥石。"
D.Strings[85157]="我会从恶魔中杀出去，到火山跟你汇合的。"
D.Strings[85158]="我们必须扑灭燃烧军团在这座山上的威胁，这样你就能将我们的剩余部队从黑暗神殿调过来了。"
D.Strings[85159]="我认识你吗？你在这里做什么？"
D.Strings[85160]="我之前就觉得跟着弗蕾亚会找到某些绿色的玩意儿，可我真没想到会是这样！$b$b我能为你做点什么吗？"
D.Strings[85161]="你把我的分析报告交给奎茵了吗？她怎么说？"
D.Strings[85162]="奎茵·柔步派我来取你的邪能球茎分析报告。"
D.Strings[85163]="啊，没错，给。那种植物真是太恶心了。"
D.Strings[85164]="嘘！我正在听植物说话呢。"
D.Strings[85165]="不，我没有迷路——我只是在寻找稀有的草药。我……等等，你是不是$n？那个草药师$n？"
D.Strings[85166]="你……不会刚好知道该怎么离开这个火山口吧？"
D.Strings[85167]="是的。奎茵·柔步派我来取你的邪能球茎分析报告。"
D.Strings[85168]="很荣幸见到你，$n。当然，我已经把报告准备好了。"
D.Strings[85169]="作为一名德鲁伊，这里的过度生长现象让我非常忧虑。但作为一名草药师，没什么能比这更让我开心的了。"
D.Strings[85170]="作为一名德鲁伊，这里的过度生长现象让我非常忧虑。但作为一名草药师，没什么能比这更让我开心的了。$b$b草药师$n。你是来拿我的报告的吗？"
D.Strings[85171]="帮我向奎茵问好，草药师。"
D.Strings[85172]="好的，给。抱歉在纸面上留下了破损和爪印。"
D.Strings[85173]="不！仪式还没有完成！"
D.Strings[85174]="束缚之力减弱了……"
D.Strings[85175]="它还在成型！"
D.Strings[85176]="你能相信吗？外面有个矮人在冒领我的作品！还有比这更不尊重人的事吗？"
D.Strings[85177]="我的书已经写完了，弗朗西斯。"
D.Strings[85178]="我们还需要一点时间！"
D.Strings[85179]="涨潮了！"
D.Strings[85180]="常引！"
D.Strings[85181]="一堆随时准备变成文学杰作的书籍。"
D.Strings[85182]="已经写完了？让我们来看看你写了些啥……"
D.Strings[85183]="噢，天呐，这恐怕是……"
D.Strings[85184]="写得最烂、最乏味、最恶心的小说！"
D.Strings[85185]="这其实真的没有那么难，$n。只要发挥一点诗兴，把你那简单的头脑所能想到的所有形容词都堆砌进去就可以了。"
D.Strings[85186]="而现在，我会把我的一些未出版的作品给你看看。作为帮助你起步的范文。"
D.Strings[85187]="常引，你还好吗？说话啊！"
D.Strings[85188]="我做好上课的准备了，弗朗西斯。"
D.Strings[85189]="听从弗朗西斯·赛培根的指导。"
D.Strings[85190]="任何干扰都可能刺激序列。只要，呃，捅它一下就行了。"
D.Strings[85191]="我会尽量跟你保持联系的。"
D.Strings[85192]="小心点，勇士。一万年来，苏拉玛一直都是蛮荒之地。"
D.Strings[85193]="噢……我的头……"
D.Strings[85194]="<咳嗽>那些恶魔……当着我的面屠杀我的学生！<喘气>白鹤洞里……传来了尖叫声……"
D.Strings[85195]="我……感觉不太好……"
D.Strings[85196]="燃烧军团的力量将征服一切！"
D.Strings[85197]="你已经亵渎这片土地太久了！"
D.Strings[85198]="萨格拉斯想要你的灵魂。"
D.Strings[85199]="现在，听好了，这很简单。在设置场景时一定要多用描述性的语言，以便读者在脑海中进行想象。同时还要给角色一些动作，例如："
D.Strings[85200]="今天就是你的死期，$r！"
D.Strings[85201]="“当然，我的公主，它已经带领我找到过无数宝藏了。事实上，我正盼着今晚能掉几条史诗裤子呢。”"
D.Strings[85202]="“唉，殿下，我只藏了一只侏儒——不过他刚好懂一些魔法……”"
D.Strings[85203]="“好吧，被您发现了。我这就把它们放出来。”"
D.Strings[85204]="接着，你要让角色们与彼此进行有趣的交流。不要像你写的那么枯燥。举个例子："
D.Strings[85205]="纳萨尼斯！我跟你说了不要再浪费时间去研究地下的古代魔力了。不要让我再重复第二遍了！"
D.Strings[85206]="最后，要来一个让读者欲罢不能的高潮，让他们有继续翻页的动力！例如："
D.Strings[85207]="“我敢打赌，您对遇见的每个公主都是这么说的。”"
D.Strings[85208]="别再找借口了，纳萨尼斯！按我说的做，否则我就找别人来看店！还有，最后说一遍，穿上我给你选的制服。"
D.Strings[85209]="“只是‘可爱’而已吗？您还得再动动脑筋啊，格雷斯班爵士。”"
D.Strings[85210]="“好吧，我还觉得您很笨！”"
D.Strings[85211]="“那么……您经常来这儿吗？您觉得这儿的天气怎么样？”"
D.Strings[85212]="“有了您这样的美貌，谁还需要智慧呢？”<欠身>"
D.Strings[85213]="可是，大法师，$n的地表探索已经有成果了！"
D.Strings[85214]="“见鬼！我真的想要裤子。”"
D.Strings[85215]="我是夏多雷塔莉萨……也就是夜之子。苏拉玛的首席奥术师。"
D.Strings[85216]="你们的末日到了，凡人！"
D.Strings[85217]="我的人民做了个可怕的交易，用法术毁灭世界。"
D.Strings[85218]="可我……如你所愿，大法师。"
D.Strings[85219]="你可以用那边的本子来写你的故事。"
D.Strings[85220]="时间有限。如果你发现了这段口信，那你就能找到我。"
D.Strings[85221]="我抓住他了。"
D.Strings[85222]="快去苏拉玛。你或许是我们最后的希望了。"
D.Strings[85223]="%s痛苦地抽搐着，抱紧了自己。"
D.Strings[85224]="守住西门！我不想再看到任何意外了。现在，来看看外面的情况。"
D.Strings[85225]="敌人太多了！我们得撤出去！"
D.Strings[85226]="这些野兽都听从我的指挥！你毫无机会。"
D.Strings[85227]="真强！"
D.Strings[85228]="乖乖呆在学校里吧！"
D.Strings[85229]="哈！加油！"
D.Strings[85230]="一点也不精彩。"
D.Strings[85231]="我真该带个野兽来的！"
D.Strings[85232]="不！你怎么做到的？"
D.Strings[85233]="你用了机器吗？"
D.Strings[85234]="这都是计划的一部分。"
D.Strings[85235]="别相信你听到的那些流言。我才是那些小说的唯一作者，而不是那个腐烂的死尸！"
D.Strings[85236]="我的书已经写完了，比尔。"
D.Strings[85237]="我做好上课的准备了，比尔。"
D.Strings[85238]="现在，听好了，这很简单。你在设置场景时一定要多用描述性的语言，以便读者在脑海中进行想象。同时还要给角色一些动作，$g小子:丫头;。例如："
D.Strings[85239]="写得最烂、最乏味、最恶心的小说！我的山羊流出的口水都比这有味道！"
D.Strings[85240]="听好了，这很简单，$g小子:丫头;。你要在文字中加一些诗化的语言，多用形容词。"
D.Strings[85241]="再跟我谈谈，我会给你一些手稿作为参考。"
D.Strings[85242]="去吧，用我身后桌子上的本子去写你的故事吧。"
D.Strings[85243]="你好，指挥官。我能为你做些什么吗？"
D.Strings[85244]="你好像对纳萨尼斯很苛刻。"
D.Strings[85245]="你对我们对抗燃烧军团的战争至关重要，指挥官。$b$b我绝不容许我的手下浪费你宝贵的时间去追查什么古代魔力的流言。$b$b而且，他还拒穿我为他挑选的时髦制服。真是个没品位不听话的家伙！"
D.Strings[85246]="他的消息看来很有价值。我相信这很值得研究一番。"
D.Strings[85247]="哈哈！又有东西可烧了！"
D.Strings[85248]="滚开，恶心的怪物！你休想再损坏我们的神圣典籍！"
D.Strings[85249]="如果你觉得有必要的话，就听从他的领导吧。像我这样的资深大法师本该去前线协助你，而不是窝在这里看一家附魔商店！这简直是浪费我的天赋！"
D.Strings[85250]="真是个有趣的主意……"
D.Strings[85251]="下一波潮水会冲上来什么东西呢？"
D.Strings[85252]="这才是生活！水里的鱼，地上的鱼，天上的鱼，全新的鱼！"
D.Strings[85253]="现在，我看看怎么激活传送门。"
D.Strings[85254]="<将20撮星光玫瑰粉尘放在草药堆上。>"
D.Strings[85255]="<将20瓶星光玫瑰粉尘放在草药堆上。>"
D.Strings[85256]="我必须跟卡德加谈谈，我要在战场上扮演更加积极的角色。祝你好运，指挥官$n。"
D.Strings[85257]="啊……新的食物送上门来了！"
D.Strings[85258]="坚强点！这些恶魔很快就要大难临头了。"
D.Strings[85259]="我们的土地，我们的水源……被你的恶行污染了。我们绝不容忍这种行为！"
D.Strings[85260]="你点燃我们的天空，亵渎我们的土地，献祭无辜的野生动物，但大地母亲的祝福必将胜利。"
D.Strings[85261]="你的脚步玷污了你走过的土地，但今天我们将终结这种腐蚀。"
D.Strings[85262]="我来集中真气，将我们送到敌军后方。快，$n，抓住我的手。"
D.Strings[85263]="日风为死去的幼崽而哀鸣着。"
D.Strings[85264]="复仇者对你抗击燃烧军团的表现印象深刻。"
D.Strings[85265]="你已经获得了召唤他怒火的资格。去吧——消灭威胁这个世界的一切敌人！"
D.Strings[85266]="这比我担心的还要糟。$n！我们得分头行动。寺院里的人需要我。陈的武术班应该在北边，过了桥就是。"
D.Strings[85267]="我准备好了，$n。激活第一个精华池吧。"
D.Strings[85268]="你在看什么呢，$r？"
D.Strings[85269]="我是来取你的脑袋的，伊克罗特！"
D.Strings[85270]="这么说，莱杉是派你来替他干脏活儿的了？"
D.Strings[85271]="真可惜，看来他得把你的尸体从下水道地板上刮干净了！"
D.Strings[85272]="很高兴有你这样的英雄来帮助我们这些小附魔师！我的意思不是说我们个子小。大法师星歌其实挺高的。$b$b我是说……唉，算了！"
D.Strings[85273]="我们一起干掉了我的敌人。我要谢谢你，$c。"
D.Strings[85274]="我是追着我的敌人来到这里的。这个畜生一样的兽人给这片土地造成了严重的破坏。$B$B我本该要求你不要插手的，但我了解你这种人。所以我只想请你不要妨碍我。"
D.Strings[85275]="去消灭你的敌人吧，渡鸦，让我们解决它！"
D.Strings[85276]="血鸦！我穿过层层迷雾、重重山岭找你来了！"
D.Strings[85277]="你留下的鲜血和背叛的痕迹指引我来到这里！"
D.Strings[85278]="我看到你还有同伴。但没关系，我会杀了你们，然后把你们的尸体扔下悬崖！"
D.Strings[85279]="我已经厌倦了不断追踪你的日子！到火堆边来，让我们做个了断吧！"
D.Strings[85280]="结束了。我要跟你告别了，但我知道我们还会再见的。"
D.Strings[85281]="我诅咒你……和你的乌鸦……"
D.Strings[85282]="正在准备"
D.Strings[85283]="$n！贾大师！感谢万灵，你们还活着！这些恶魔简直无穷无尽！"
D.Strings[85284]="过来，英雄！艾露恩保佑着我们！"
D.Strings[85285]="我在想，天上会掉什么宝贝呢……"
D.Strings[85286]="去死吧，畜生！"
D.Strings[85287]="仁慈的艾露恩，大家都没事吧？"
D.Strings[85288]="我依然能感觉到他们的存在……好多声音在我脑海里回荡。"
D.Strings[85289]="我看到的只有死亡……我们怎么可能获胜？"
D.Strings[85290]="等等，老朋友。"
D.Strings[85291]="现在还不是你离开这个世界的时候。"
D.Strings[85292]="愿大地母亲护佑着你。"
D.Strings[85293]="酿酒师的房间完全没有特制酒桶的踪影。"
D.Strings[85294]="你们都知道，我们在破碎海滩遭到惨败。众多英雄的牺牲是个严重的打击。"
D.Strings[85295]="燃烧军团的危害十分严重。我们得设法阻止他们入侵，否则的话，我们珍视的一切就会……"
D.Strings[85296]="奔波尔霸，我们要你变得更强大！这片海滩的命运就取决于你了！"
D.Strings[85297]="愿青龙保佑你，$n。"
D.Strings[85298]="可悲的凡人！让燃烧军团的大军碾碎你们吧！"
D.Strings[85299]="来吧，孩子们，我们到寺院去。$n，我需要你的帮助。这里全是恶魔！"
D.Strings[85300]="燃烧军团！快，快进去！除非把房子都炸了，否则他休想抓到我们！"
D.Strings[85301]="他们想要我们的小房子干什么？"
D.Strings[85302]="燃烧军团无穷无尽，无所不知！"
D.Strings[85303]="大宗师海特，见到你真是太好了！"
D.Strings[85304]="陈，很高兴看到你和孩子们都没事！"
D.Strings[85305]="多亏这位英雄及时赶到，把我们救了出来。"
D.Strings[85306]="打得好，$n，可事情还没完。"
D.Strings[85307]="陈，带着孩子们离开这里，越远越好。$n和我留下来封印传送门。愿白虎保佑你，我的朋友。"
D.Strings[85308]="那些是我的甲壳，凡人！你会为盗窃我的财产而付出代价的！"
D.Strings[85309]="我们不能让燃烧军团在这里站稳脚跟。我们得关闭那座传送门！"
D.Strings[85310]="按照传统，它已经属于胜利者了。斯科瓦尔德，你的抗议来得太迟了。"
D.Strings[85311]="我们得抓住一些恶魔并拷问他们。"
D.Strings[85312]="钥石呢，恶魔？"
D.Strings[85313]="我的镰刀会赶走他们。"
D.Strings[85314]="让夺魂之镰斩杀你们！"
D.Strings[85315]="我们带的人手够吗？"
D.Strings[85316]="伊利丹大人选了你。我听你的。"
D.Strings[85317]="到处都是邪能。这很难抵御。"
D.Strings[85318]="从头目那里收集情报。"
D.Strings[85319]="我们必须找到萨格里特钥石。"
D.Strings[85320]="我去前面去侦察，并寻找钥石。"
D.Strings[85321]="我很高兴有你领导我们，$n。"
D.Strings[85322]="大地母亲保佑着我们。"
D.Strings[85323]="这些入侵者玷污我们的圣地，杀害无辜的平民……$B$B我们决不能容忍这种行为！"
D.Strings[85324]="伊利丹大人非常信赖你。"
D.Strings[85325]="直觉告诉我，钥石就在那座火山上。"
D.Strings[85326]="天空都在为脚下苦难的大地而哭泣。"
D.Strings[85327]="我想好下一步的行动了。"
D.Strings[85328]="听着，这里应该是我说了算。"
D.Strings[85329]="小心点，$n。在这种敏感时期，我们无法保证这一带的安全。"
D.Strings[85330]="哈！干掉他们。"
D.Strings[85331]="开心吗？我很开心！"
D.Strings[85332]="接下来呢，$n？"
D.Strings[85333]="告诉我正确的方向就行。"
D.Strings[85334]="<这个土灵探索者的尸体已经被切开了。他的内脏——看起来就是一堆沙子和石子——洒得地板上到处都是。狰狞的伤口上残留着邪能的痕迹。>"
D.Strings[85335]="继续仪式！我来解决这些蠢货！"
D.Strings[85336]="感觉到凉风了吗？它们来了……"
D.Strings[85337]="手忙脚乱了吗？"
D.Strings[85338]="炸焦你们，旱鸭子！"
D.Strings[85339]="涨潮了……"
D.Strings[85340]="|TInterface\\Icons\\Spell_Frost_SummonWaterElemental:20|t%s开始施放|cFFFF0000|Hspell:193682|h[召唤风暴]|h|r！"
D.Strings[85341]="你听不懂哨兵的歌吗，$r？那或许你该让我来代他说。"
D.Strings[85342]="战利品属于胜利者……阿格拉玛之盾是你们的了。"
D.Strings[85343]="嘿，我要尽快把这个口信送出去！要是我慢了，蒋大师又要罚我粉刷寺院了！"
D.Strings[85344]="|TInterface\\Icons\\Spell_Shaman_StaticShock:20|t%s开始引爆|cFFFF0000|Hspell:193597|h[静电新星]|h|r。快离开水域！"
D.Strings[85345]="给我等着……"
D.Strings[85346]="风暴正在汇聚……"
D.Strings[85347]="嘿，$n！我有海特大师给你的口信！"
D.Strings[85348]="你要去哪儿？嘿，我有给你的口信！"
D.Strings[85349]="拜托！我得把这个口信送到！"
D.Strings[85350]="请给我点时间。要是不能及时把口信送到的话，蒋大师又要罚我粉刷寺院了！"
D.Strings[85351]="你知道寺院有多大吗？全刷一遍至少要几星期！拜托，听我说！"
D.Strings[85352]="一路平安。"
D.Strings[85353]="我亲爱的朋友……他们怎么了？为什么感觉一切都……变了？"
D.Strings[85354]="我把这些好朋友的灵魂都托付给你了。保护好他们，附魔师。"
D.Strings[85355]="我们最优质的美酒很快就会送到艾萨拉女王那里！她一定会喜欢的！"
D.Strings[85356]="好像有点不对劲，可……我看不出来……"
D.Strings[85357]="但愿有人在听……"
D.Strings[85358]="那好吧。如果有必要，我会跟着你跑遍整座城市！"
D.Strings[85359]="嗯……得继续跑。"
D.Strings[85360]="枯法者……我一定很接近了。"
D.Strings[85361]="经过重重考验，你们的力量、技巧和智慧不亚于最伟大的维库王者。现在……你们将在战斗中面对他们。去战胜他们，你们就将得到奖赏！"
D.Strings[85362]="书页已经被撕了下来，散落在房间的各个角落。整座旅店都好像被龙卷风刮过一样……"
D.Strings[85363]="书页已经被撕了下来，散落在房间的各个角落。整座旅店都好像被龙卷风刮过一样……$b$b这里有明显的打斗痕迹，可玛法里奥却不见踪影。"
D.Strings[85364]="这似乎是玛法里奥外套上的羽毛。$b$b仔细搜索了附近之后，你辨认出了一些模糊的脚印，它们沿着小路一直向西南方延伸过去。$b$b这些脚印和萨特的偶蹄印完全不同……"
D.Strings[85365]="<这个受伤的萨特怒视着靠近的你。他已经命不久矣了。>$b$b你是来收拾你们的大德鲁伊留下的烂摊子的吗，$r？你们这些凡人自以为胜利了……可玛法里奥已经落入主人的手里了。$b$b那个蠢货掉进了我们的陷阱……哈哈，哈哈……"
D.Strings[85366]="Narala ith'el! <咳嗽>"
D.Strings[85367]="伊拉穆斯，让开！你看不出艾利桑德已经抛弃我们了吗？！"
D.Strings[85368]="这应该能争取一些时间……"
D.Strings[85369]="记住，你是这套系统中最“智能”的部分，你必须把这玩意儿对准恶魔！"
D.Strings[85370]="快攻击你的目标，这玩意儿经过了压缩，一旦燃烧耗完就会爆炸的！"
D.Strings[85371]="我虽然死了，可我的宠物还能蹦跶呢！"
D.Strings[85372]="我们中只有一个人能活着离开这里……等等……"
D.Strings[85373]="我要亲手抓你去冥狱深渊，艾泽拉斯的“英雄”！"
D.Strings[85374]="游荡者！你是来拯救你的灵魂的吗？\n\n它很快就会降临了！第二次末日！死亡之翼即将归来，艾泽拉斯必将毁灭！我们必须为将要吞噬世界的洪水做好准备！"
D.Strings[85375]="失败会让你更加强大！"
D.Strings[85376]="……死亡之翼？你是说燃烧军团？"
D.Strings[85377]="如果你有胆子话，就再来试试吧！"
D.Strings[85378]="我的攻略上没提到过这个！"
D.Strings[85379]="怎么可能？我看的可是傻瓜攻略！"
D.Strings[85380]="燃烧军团？哈！他们不过是末日的前兆而已。仔细听我的布道吧。"
D.Strings[85381]="……好吗？"
D.Strings[85382]="你还不够强。"
D.Strings[85383]="我的战术是完美的！"
D.Strings[85384]="你赢不了我的宠物！"
D.Strings[85385]="我在此宣告，死亡之翼并未被击败。他蛰伏着，等待艾泽拉斯放松警惕。很快，他就会归来，飞过世界，散播毁灭。"
D.Strings[85386]="当然，你们或许会想，联盟和部落会用他们的大飞艇击落他。但他的身躯将震裂大地，上升的海水会吞噬我们所有人。"
D.Strings[85387]="但备足……我们早有预料！我们已经预见到了未来，并将在洪水到来前做好准备。我们会活下来……不仅如此，我们还将由此兴盛！"
D.Strings[85388]="恶魔！就在矿井里！没错，我知道我们风险投资公司对竞争对手一向不宽容，可这一次，你一定要帮帮我们！"
D.Strings[85389]="这只猎物很凶猛！如果你敢的话……就跟上吧！"
D.Strings[85390]="在开打前，请稍等一会儿，英雄！我为你准备了一个惊喜……"
D.Strings[85391]="胡恩是我们部族的先祖，也是最强大的勇士。"
D.Strings[85392]="在克拉苏斯的召唤下，他勇斗军团，并用雄鹰之矛击败了许多恶魔。"
D.Strings[85393]="胡恩的战斗技巧无人能及。"
D.Strings[85394]="这具阴燃的尸体手中还抓着一根风灵环绕的图腾。"
D.Strings[85395]="我不记得他杀过那么多恶魔。你太夸张了，灵魂行者。"
D.Strings[85396]="好了，奔波尔霸！是时候让你变得更大更强壮了！"
D.Strings[85397]="天角部族！升空，让鹰身人和那些大鹏看看什么叫战斗！"
D.Strings[85398]="你能帮我找到路吗？"
D.Strings[85399]="我听说你有一些有用的货物。"
D.Strings[85400]="他们的看法也不是没有道理，胡恩真的太热爱战斗了。"
D.Strings[85401]="有些人认为胡恩太过嗜血了。"
D.Strings[85402]="传说胡恩渴望让恶魔流尽鲜血。"
D.Strings[85403]="我们是被派来监视鱼人的。他们告诉我们说一周后就派人来接替我们……可我们已经在这儿呆了一个月了，一个新的牛头人都没看见。我已经受够这两个家伙了。他们根本不能呆在一起，否则就会像老两口一样开始拌嘴。"
D.Strings[85404]="我受够斥候傲山了。我只是想去提醒一下雷霆图腾我们在这里呢！可他不让我们任何一个人离开岗位。家里到底发生什么重要事情了，居然会让他们忘了我们？！"
D.Strings[85405]="我们不能离开岗哨。只要我们的眼睛转开一秒钟，那个穿着鱼人服的怪人就可能干出一切疯狂的事情来。如果有必要的话，雷霆图腾会派人来接替的。他们还没忘了我们。"
D.Strings[85406]="污染者阿克蒙德始终致力于发掘魔法技艺中最黑暗的分支。数千年来，无数世界的知识和历史都包含在了这本书里。$B$B现在，我们将宣扬你的传奇，$g大人:女士;。"
D.Strings[85407]="我相信，像你这样的附魔师一定会好好利用哨兵的精华的。"
D.Strings[85408]="这就是喝不到暗夜井水的夜之子的命运。"
D.Strings[85409]="我的力量在衰退……得躲起来……"
D.Strings[85410]="赛娅娜，杰斯，阿莱利……去找钥石。"
D.Strings[85411]="我正在使用夺魂之镰拷问这些恶魔，但他们对萨格里特钥石的下落一无所知。\n\n他们只是保持着对某位女王的忠诚。\n\n赛娅娜和杰斯已经到前面去了。不幸的是，赛娅娜为了营救其他恶魔猎手被俘了。\n\n她有点不对劲。"
D.Strings[85412]="这个任务是为了让奔波尔霸证明自己。用他的蛋与奔波尔霸进行心灵融合吧。"
D.Strings[85413]="你的灵魂一定能让我得到丰厚的赏赐！"
D.Strings[85414]="地狱火来了！小心脑袋！"
D.Strings[85415]="又一个想要成为勇士的……废物。"
D.Strings[85416]="无尽的痛苦在冥狱深渊里等着你呢！"
D.Strings[85417]="我只看到无穷的折磨……"
D.Strings[85418]="你毁了我……"
D.Strings[85419]="毫无荣誉可言的战场在前方等着……"
D.Strings[85420]="你来错地方了，英雄。"
D.Strings[85421]="他们会因此提拔我成为海拉加尔的！"
D.Strings[85422]="和其他幽灵一起堕入冥狱深渊吧，蠢货！"
D.Strings[85423]="不，折磨……"
D.Strings[85424]="我会在冥狱深渊……等着你。"
D.Strings[85425]="那就来受死吧，英雄！"
D.Strings[85426]="海拉的恩赐让我更加强大！我的利刃已经斩杀了数千敌人！"
D.Strings[85427]="我是海拉加尔勇士！接受你的命运，去死吧！"
D.Strings[85428]="你们这些蠢货在干嘛？唔……这是什么？一个强大的灵魂！"
D.Strings[85429]="阿格拉玛之盾超载了！"
D.Strings[85430]="……对，我们的大军——"
D.Strings[85431]="什么？你竟敢打扰我？真是无礼……你会为自己的决定而后悔的。"
D.Strings[85432]="女祭司的房间废弃已久。地板上躺着一本旧日记。"
D.Strings[85433]="恶魔总是幻想自己是这个宇宙的主宰，而我们每天都在束缚强大的恶魔并将他们的知识占为己有。$B$B在掌握萨格拉斯权杖的所有知识前，我是不会罢手的。我向你保证。"
D.Strings[85434]="海拉！帮帮你的勇士！我将以你之名夺取奖赏！"
D.Strings[85435]="不！我不会输给奥丁的走狗！我要毁灭你！"
D.Strings[85436]="我的眼前只有一片黑暗。海拉……不！不！"
D.Strings[85437]="我感觉有个入侵者来寻宝了。你低估了冰冠堡垒的危险性，愚蠢的法师！"
D.Strings[85438]="你的心思昭然若揭，$n。我知道你在找烈焰之击。你想用它对抗军团。有意思。我在想……"
D.Strings[85439]="我们的猎物撤退了！是时候大举进攻了。"
D.Strings[85440]="这些殿堂中收藏了这个世界的许多魔法知识……但还不是全部。$B$B我们更加深入地了解艾露尼斯，才能强化它的力量。我相信它将是击退燃烧军团的唯一希望。"
D.Strings[85441]="这边！那头恶魔肯定往这边跑了。石头上溅到了几滴魔血。"
D.Strings[85442]="风暴比克，你留下守住入口。"
D.Strings[85443]="别啄我了。留下！"
D.Strings[85444]="是小鬼！肯定是格斯逊在召唤这些小爬虫。"
D.Strings[85445]="格斯逊肯定是在召唤这些小虫子腐蚀土地的国度。"
D.Strings[85446]="小心点！又来了小鬼！"
D.Strings[85447]="萨尔，那个恶魔还活着。"
D.Strings[85448]="对，我留了下来，奈辛瓦里独自前进了。你干嘛不去看看那个鱼人？"
D.Strings[85449]="那个疯子……自称姆嘎姆嘎。还说他是诺森德的一位国王。他说的话我一个字都不信。"
D.Strings[85450]="他一直在说自己的孩子，说他叫奔波尔霸。"
D.Strings[85451]="小心！它被邪能腐蚀了。杀了它！"
D.Strings[85452]="我们得快一点了。继续前进！"
D.Strings[85453]="看！他在那儿。"
D.Strings[85454]="萨满，我们不能让那件武器落入恶人之手。我来引开他。你去拿毁灭之锤。别争了！快去！"
D.Strings[85455]="嘿！你！我的狮鹫还对付过更恐怖的恶魔呢！"
D.Strings[85456]="噢，嘿，来啊！"
D.Strings[85457]="你拿到了！噢！"
D.Strings[85458]="……我恐怕不行了，萨满……我已经走到头了……"
D.Strings[85459]="来吧，我们走。有你这样的英雄，我们或许能拯救世界。去大漩涡！"
D.Strings[85460]="呸，这是什么巫术？"
D.Strings[85461]="这把锤子……我要为主人拿到它……"
D.Strings[85462]="<格斯逊咆哮了起来。>"
D.Strings[85463]="可怜的小萨满！那把锤子对它的旧主人毫无帮助。"
D.Strings[85464]="我要将那把锤子作为战利品献给主人……还有你的脑袋！"
D.Strings[85465]="我要震垮整座洞穴！"
D.Strings[85466]="我会从内部腐蚀这可悲的世界。"
D.Strings[85467]="燃烧军团的力量无可匹敌！"
D.Strings[85468]="跪下！我或许可以饶你一命！"
D.Strings[85469]="你将见证这世界的毁灭，萨满。"
D.Strings[85470]="……还有别人……我们是……军团……"
D.Strings[85471]="那些家伙……完全无视宝贵的生命！"
D.Strings[85472]="好了好了。你正在好起来。"
D.Strings[85473]="幸亏你的皮够厚，老朋友。"
D.Strings[85474]="等其他人飞上来，我会守住返回黑暗神殿的传送门。"
D.Strings[85475]="我只是需要一点时间来考虑我的决定。现在我已经准备好了。"
D.Strings[85476]="$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TINTERFACE\\ENCOUNTERJOURNAL\\UI-EJ-BOSS-KERISTRASZA.BLP:50:80|t$b[考雷斯特拉兹]你果然遵守承诺前来了，高岭。不要害怕我的火焰；需要害怕我的烈焰和你的雄鹰之矛的只有恶魔。"
D.Strings[85477]="艾露恩，请最后一次赐予我纯洁的祝福吧。"
D.Strings[85478]="%s不满地叫了起来。"
D.Strings[85479]="成功了！赞美女神！"
D.Strings[85480]="胡恩·高岭……这是艾特洛？它可不一般，它是玛洛恩的眷属。你果然福泽深厚。"
D.Strings[85481]="接受我的祝福吧，胡恩·高岭。你的族人将永远受我的眷顾。"
D.Strings[85482]="就连森林之神塞纳留斯都看出了胡恩的伟大。他赐下了艾特洛之角，这个祝福一直传承到了今天。"
D.Strings[85483]="我找到女祭司德娅娜了。她很安全，想跟你谈谈。"
D.Strings[85484]="我有幸看着你从一个年轻的$r成长为艾泽拉斯最优秀的猎人。$B$B你的故事必将永载史册，让所有人都了解你的事迹，以及你那把伟大武器的历史。"
D.Strings[85485]="我回来了，亲爱的。我终于回到家了。"
D.Strings[85486]="我亲爱的德娅娜……真的是你吗？这里的一切都是如此……古怪……就好像在做梦一样。"
D.Strings[85487]="我知道。但不用害怕。我们又可以在一起了。"
D.Strings[85488]="我太高兴了！待会儿我们去圣泉旁散步吧？那里总是让我觉得心旷神怡。"
D.Strings[85489]="我无法形容我有多么高兴。可现在，我必须先去……休息一下。我们稍后再见。"
D.Strings[85490]="德娅娜？德娅娜？你在哪儿……"
D.Strings[85491]="虽然我的灵魂消散了，但关于萨特阴谋的那一部分记忆可以帮助你。再次感谢你，$n。"
D.Strings[85492]="这些勇敢的冒险者穿过了雷霆崖下方的平原！"
D.Strings[85493]="祝福你，$c！我欠你一条命和一顿大餐。我们最好在他们的首领过来前离开这里，否则我们的下场就——"
D.Strings[85494]="不！快逃命吧！"
D.Strings[85495]="我们要死守阵地，挡住燃烧军团。谁都别想过去！"
D.Strings[85496]="胡恩！很高兴在这里见到你。你好像……长高了？"
D.Strings[85497]="这恶魔交给雄鹰之矛，影歌。跟小鬼玩去，正事交给我。下一个归你。"
D.Strings[85498]="等等，我好像……噢，对了，献给艾萨拉女王的酒。我得去干活了。"
D.Strings[85499]="我就在你身边，$n。"
D.Strings[85500]="很好，$n！那块邪能石在给传送门供能。摧毁它！"
D.Strings[85501]="他们过来了！"
D.Strings[85502]="坚守阵地，武士们！"
D.Strings[85503]="燃烧军团冲过来了！准备战斗！达拉然是拯救我们世界的最后希望。"
D.Strings[85504]="你怎么从笼子里出来了，$c？"
D.Strings[85505]="如果我们分头行动的话，就能覆盖更广大的区域！我去商业区召集商人！"
D.Strings[85506]="商人们、工匠们，我们需要你们帮忙保卫城市！"
D.Strings[85507]="用你们能找到的一切把自己武装起来。燃烧军团已经飞过来了！"
D.Strings[85508]="你们太迟了！艾萨拉之怒已经降临！"
D.Strings[85509]="堵住那扇门！我们决不能让一个恶魔攻进来，对不对？"
D.Strings[85510]="保持警惕，如果谁坚持不住了，就呼叫援兵！"
D.Strings[85511]="冒险者们，把商业区里有助于防守的东西都拿上。我们绝不吝啬！"
D.Strings[85512]="积怨必胜！"
D.Strings[85513]="呸，我们才不会造这种地精垃圾呢。我们只是把它绑在那条龙身上而已。凡人的武器打不穿这些金属板。"
D.Strings[85514]="去别处打猎吧！"
D.Strings[85515]="我们得去找神祇的武器。伊格鲁尔，死亡之翼背着你们藏过武器或饰品吗？他有不准你们接触的东西吗？"
D.Strings[85516]="唔，我好像想起来了……"
D.Strings[85517]="让开！你挡住我的枪口了。"
D.Strings[85518]="闹剧该结束了，我要亲自收割你的灵魂！"
D.Strings[85519]="又来了！"
D.Strings[85520]="你休想！"
D.Strings[85521]="这个世界必将被洪水吞噬……"
D.Strings[85522]="恶心死他们，小伙子们！"
D.Strings[85523]="……再拧一下……哎哟！哼。要是我没法把这玩意儿发动起来，我们又怎么可能及时得到援助呢？"
D.Strings[85524]="如果我能让这玩意儿发动起来，就可以呼叫更多支援了！"
D.Strings[85525]="她很快就会动起来的！然后我们召唤骑兵队！"
D.Strings[85526]="绷带！我需要更多的绷带，安吉莉克！"
D.Strings[85527]="我没法让他们的伤势都稳定下来……补给不要停，我是不会放弃的！"
D.Strings[85528]="别忘了我付了钱是想要保护的。记住这个优先级！首先是我们，然后是钱，最后才是其他东西……如果有时间的话就顺手保护一下。"
D.Strings[85529]="来了！接着！"
D.Strings[85530]="跟我说说胡恩·高岭的故事吧。"
D.Strings[85531]="你们最好做好准备，小子丫头们！快来免费打磨武器啦！"
D.Strings[85532]="你不是贝拉米！但我想我们不应该在这种小事上头纠结……"
D.Strings[85533]="坚持住，伙计！我们会挺过去的。"
D.Strings[85534]="该死的恶魔！总有人会收拾他们的！"
D.Strings[85535]="这看起来不算糟。你会好起来的。我保证。"
D.Strings[85536]="你们可以禁锢我的灵魂，该死的家伙，但你们夺不走我的意志。"
D.Strings[85537]="闭嘴。你的灵魂属于海拉。"
D.Strings[85538]="眼下，燃烧军团在破碎海滩上势如破竹。我们需要你的帮助。"
D.Strings[85539]="$n，我们又在危险地带见面了。再次感谢你在河湾的帮助。但你和鲜血图腾打交道时一定要保持警惕。他们对外来者通常都不怎么友好。"
D.Strings[85540]="%s咳了几声，一边喘气一边组织着语言。"
D.Strings[85541]="好了好了！我不能久留，但你看起来需要帮助。跟我来。"
D.Strings[85542]="你下不去的！亡灵会爬起来阻止你的！"
D.Strings[85543]="试试吧，把他们安全地带回来。"
D.Strings[85544]="我们必须承认：河湾已经完了。总有一天，我们会重建家园。但现在，我们必须先等一等，并尽力帮助雷霆图腾，就像他们帮助我们一样。"
D.Strings[85545]="干得漂亮，欧莉萨拉！"
D.Strings[85546]="月翼浅滩的林精一直是我的眼中钉，但这些鱼人是我不幸遇到过的、最粗鲁的生物。"
D.Strings[85547]="天呐，我的头好痛！谢谢了，$n！在外面小心点。"
D.Strings[85548]="今天真倒霉。我应该在被抓差之前就跑掉！"
D.Strings[85549]="呃！真是一团糟！我要去警告其他人！"
D.Strings[85550]="愿符文诅咒你。我要把你送回海底去，那里才是你该呆的地方！"
D.Strings[85551]="箱子都打包完毕了！我们还不能撤退吗，蒂凡妮？"
D.Strings[85552]="蠢货。我们的诅咒会彻底毁灭你……"
D.Strings[85553]="我们不走！这是我祖传的老店，我们要誓死保卫它！"
D.Strings[85554]="你来鱼人浅滩干什么？"
D.Strings[85555]="在解决掉那些烦人的蓟叶林精后，我决定深入苏拉玛的古老土地。$B$B不幸的是，我在途中遇到了这些鱼人。我决不能任由他们横行。"
D.Strings[85556]="你有着古树一般的耐心。"
D.Strings[85557]="砸开箱子！砸烂它！"
D.Strings[85558]="蠢箱子！把亮晶晶给我！"
D.Strings[85559]="嘿！嘿！你找到什么什么好东西没有？！"
D.Strings[85560]="噢！真漂亮！给我吗？！"
D.Strings[85561]="那是什么？这是魔法吗？是吗？是吗？是吗？"
D.Strings[85562]="我来治疗你，大法师！"
D.Strings[85563]="躲在这里，查尔斯。我们会阻止恶魔的！"
D.Strings[85564]="欢迎来到传说皮甲。我能帮你什么忙吗？"
D.Strings[85565]="不准你说我像我兄弟。我显然比他要高！"
D.Strings[85566]="离它远点儿，外来者！"
D.Strings[85567]="凯丽娅把我丢下等死……蠢货！"
D.Strings[85568]="打开大门，萨鲁法尔大王。我带来了酋长的客人。"
D.Strings[85569]="我不喜欢他们的样子，法师。他们散发着恶魔的臭气。"
D.Strings[85570]="如果让恶魔毁了我的城市，那我也不想活了。小伙子们，拿起武器！"
D.Strings[85571]="怎么了，陌生人？我能帮你什么忙吗？"
D.Strings[85572]="$n！很高兴再次见到你！我能为你做点什么吗？"
D.Strings[85573]="我可是砥角大赛的冠军！你以为像你这样的软蛋会是我的对手吗？哈！别跟贾格开玩笑了！"
D.Strings[85574]="要不是你的臀部这么……<咳咳>丰满的话，根本不会出这种事。"
D.Strings[85575]="屏障的能量正在流失！"
D.Strings[85576]="别让他们靠近屏障！"
D.Strings[85577]="自从我丈夫回来之后，我们的生意就越做越大了。$B$B我们甚至在顶楼开了一个酿酒厂，雇佣了一些来自寺院的武僧！"
D.Strings[85578]="你好啊！我们这里有最好的美食。$b$b酒馆顶楼还有全新的啤酒供应。快来尝尝我们的新品吧！"
D.Strings[85579]="嘿！嘻嘻。你好。嘿，嘻嘻！"
D.Strings[85580]="不需要你说第二遍。"
D.Strings[85581]="我伤得很重。你恐怕得独自前进了。"
D.Strings[85582]="等我恢复就去和你会合。"
D.Strings[85583]="瓦雷迪斯给我指了一条明路。军团能让我们恢复强大！"
D.Strings[85584]="$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TINTERFACE\\ENCOUNTERJOURNAL\\UI-EJ-BOSS-ASIRA DAWNSLAYER.blp:50:80|t$b[考瓦斯·血棘]末日守卫从上面冲下来了！"
D.Strings[85585]="对……你的意志被削弱了。"
D.Strings[85586]="$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TINTERFACE\\ENCOUNTERJOURNAL\\UI-EJ-BOSS-Selin Fireheart.blp:50:80|t$b[凯恩·日怒]伊利达雷们，整队！别让凯丽娅轻易躲过我们的怒火。"
D.Strings[85587]="你好，欢迎光临笑鹤酒馆！"
D.Strings[85588]="你会为赶我走而后悔的！"
D.Strings[85589]="我觉得你才是该滚蛋的那一个！"
D.Strings[85590]="谁都别想对我指手画脚的！"
D.Strings[85591]="我想打猎的时候就打猎，你别想阻止我！"
D.Strings[85592]="我正想走呢。"
D.Strings[85593]="这儿就让给你吧，我再去找个更好的地方。"
D.Strings[85594]="这也是你们唯一的退路。去找到它，然后返回黑暗神殿吧。"
D.Strings[85595]="谢谢，$n。等事情彻底结束后，我还会回来的。"
D.Strings[85596]="感谢你的帮助。我要去躺一会儿了，起码不会这么热。"
D.Strings[85597]="送我去南部营地！"
D.Strings[85598]="送我去悬崖！"
D.Strings[85599]="在即将自爆时，$n疯狂大笑了起来！"
D.Strings[85600]="<咳嗽>我……需要一点时间……"
D.Strings[85601]="奇怪。他们怎么不跟来？"
D.Strings[85602]="<咳嗽>我需要休息……"
D.Strings[85603]="我很好奇，这个池子会向你展现什么秘密，德兰妮。"
D.Strings[85604]="罪行？我们的罪行就是为了拯救这个世界牺牲了一切。"
D.Strings[85605]="我们在为伊利丹而战，而你则将世界上的恶棍永远囚禁在这里。后来，你又囚禁了我们。"
D.Strings[85606]="我们保护生命，这通常都很危险，有时还会付出高昂的代价。"
D.Strings[85607]="你竟然还敢跟我谈牺牲？"
D.Strings[85608]="我说了别再问了！等等，你听到了吗？"
D.Strings[85609]="万灵正在窃窃私语，只要你闭上嘴巴仔细聆听。对……对，我们在这儿！"
D.Strings[85610]="好的，我的儿子。在我们面前的高山环抱之地，我们将建立家园。快去把长老们找来。"
D.Strings[85611]="然后我们就开饭了。"
D.Strings[85612]="妈妈，我们到了吗？"
D.Strings[85613]="我什么都没听见，除了饿得咕咕叫的肚子！"
D.Strings[85614]="这里就是“这里”？你是说我们终于找到新家园了吗？"
D.Strings[85615]="那我们能开饭了吗？"
D.Strings[85616]="鲜血图腾决不跟渔夫和山民并肩战斗！"
D.Strings[85617]="小心点，养鸟的家伙！"
D.Strings[85618]="我们要用魔血淹没这座山！"
D.Strings[85619]="胡恩说的对。我们必须团结起来对抗燃烧军团。这是唯一的办法。"
D.Strings[85620]="够了！你想为了你的骄傲葬送我们的族人吗？燃烧军团所到之处，只会留下老人的枯骨……还有孩子们的。"
D.Strings[85621]="那就让我们团结一致。为了至高岭。"
D.Strings[85622]="团结一致。"
D.Strings[85623]="我的小海勒出去完成晋升萨满的第一个试炼了……我担心死她了！菲拉，图恩出去完成试炼的时候，你是怎么熬过去的？"
D.Strings[85624]="天角才不跟这些野蛮人合作！他们和恶魔一样卑鄙！"
D.Strings[85625]="那是不可能的。"
D.Strings[85626]="团结一致!"
D.Strings[85627]="我不相信他们，葆拉。他们不比野兽好多少！"
D.Strings[85628]="那不是我的……听着，他们很危险，是堕落的仆人！"
D.Strings[85629]="好吧，我是不会放松警惕的。卓格巴尔就会……"
D.Strings[85630]="我想他们的水晶已经被证明是很有用的了。"
D.Strings[85631]="我不相信他们……但我喜欢他们的石头。我是说水晶！"
D.Strings[85632]="别自己吓自己，加拉。海勒和图恩一样，都是天赋出众的年轻人。她赢得了参加试炼的资格，我相信她会成功的。"
D.Strings[85633]="我们可以从兽灵身上学到很多东西，法绍。"
D.Strings[85634]="那是过去。我们必须创建新的未来。"
D.Strings[85635]="好了！新的未来就在眼前了。"
D.Strings[85636]="确实如此。"
D.Strings[85637]="那我们就在交易图腾下说定了。我们用皮革换你们的石头，成交吗？"
D.Strings[85638]="至少这一个好的开始。"
D.Strings[85639]="蠢牛又带皮革来了？"
D.Strings[85640]="我有石头。好石头！好多魔力！"
D.Strings[85641]="这些不是我的宠物！它们都是我的朋友！但是，它们都渴望能击败你。"
D.Strings[85642]="干得好。你和你的小伙伴之间，一定有着深厚的情谊。"
D.Strings[85643]="当你不再将它们当成宠物，而是朋友的时候，你就能击败我了。"
D.Strings[85644]="我一点也不喜欢这样。"
D.Strings[85645]="你应该多关心一下你的朋友。"
D.Strings[85646]="你们的感情还不够深。"
D.Strings[85647]="你还好吗，小家伙？"
D.Strings[85648]="看来这个新人醒了。你躲过了深渊领主的正面攻击。可惜别人……就没这么走运了……"
D.Strings[85649]="我们似乎成了贾格诺斯的囚犯，这是个荒废的军团世界。他肯定没安好心……"
D.Strings[85650]="我个人还是希望能躲过这种折磨。"
D.Strings[85651]="幸好凯恩只需要通过成年仪式……要是我知道他会遇到危险的话，我肯定会担心得喘不过气来的。"
D.Strings[85652]="休息一下吧，我的朋友。"
D.Strings[85653]="姐妹们，我的孩子还小！我根本不愿意想她可能会遇到危险这种事！"
D.Strings[85654]="等战斗结束后，我们就去吃宠物糕点。"
D.Strings[85655]="赫米特让你来教我打猎？\n\n我很高兴你愿意接下这个任务。我还有很多东西要学，但我起码还知道子弹是从枪的哪一头飞出来的……\n\n我已经准备好了，随时都能出发！"
D.Strings[85656]="保护货物！保护……灵魂……"
D.Strings[85657]="我知道，我知道。你一定要坚持住！我保证你的伤会好起来的！"
D.Strings[85658]="躺着别动！马上就有人来救你了！我保证！"
D.Strings[85659]="不是疼，笨蛋——是沙子！它好烫！"
D.Strings[85660]="后退，恶魔！"
D.Strings[85661]="你以为我们个子小就能随便欺负？嗯？"
D.Strings[85662]="你想找碴吗？"
D.Strings[85663]="你能安静一会儿吗？你要把别的恶魔都引来了。"
D.Strings[85664]="噢，没错。你会给他们点颜色看看的！你打算怎么做？揍死他们?"
D.Strings[85665]="你已经转了好几个小时了！你就不能休息一会儿吗？"
D.Strings[85666]="你知道吗，每次你跑来跑去，都会把沙子溅到我身上！现在我不仅仅是受点小伤了，我的头发、眼睛里都是沙子了……呸呸呸！"
D.Strings[85667]="我想我已经掌握窍门了！"
D.Strings[85668]="这就是奥丁的勇士！让他们死在奥丁自己的剑下吧！我以冥狱深渊的怒火祝福这些利刃！去吧，维格弗斯！杀了这个勇士，赢取我永恒的青睐吧！"
D.Strings[85669]="维格弗斯，你这软弱的蠢货！你将受到无尽的折磨！"
D.Strings[85670]="$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TINTERFACE\\ENCOUNTERJOURNAL\\UI-EJ-BOSS-ASIRA DAWNSLAYER.blp:50:80|t$b[考瓦斯·血棘]那些阵亡的士兵……他们的灵魂被拉出了躯壳。 "
D.Strings[85671]="我受够你了！去告诉奥丁，这改变不了什么。他很快就将承受我的怒火！"
D.Strings[85672]="鬼母就在那座洞穴里。"
D.Strings[85673]="尊敬的$g先生:女士;，很抱歉，但我必须请您留在寺中或者绿野村里。"
D.Strings[85674]="啊，我的骆驼！谢谢你，我的朋友！你真是太好了。"
D.Strings[85675]="……出什么事了？我的头——我……"
D.Strings[85676]="恶魔！等我砍掉他们的脑袋，他们的搜索就不会有什么成果了！"
D.Strings[85677]="送我去大裂口！"
D.Strings[85678]="送我去腐化之巢！"
D.Strings[85679]="啊！好疼……很难……集中精神……"
D.Strings[85680]="快！别让狱卒注意到我们。你或许可以控制他一阵……"
D.Strings[85681]="我会……尽力协助你的。"
D.Strings[85682]="$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TINTERFACE\\ENCOUNTERJOURNAL\\UI-EJ-BOSS-Selin Fireheart.blp:50:80|t$b[凯恩·日怒]我们行动吧。"
D.Strings[85683]="命运在召唤你们！"
D.Strings[85684]="这是什么把戏？谁都别想逃出我的牢笼！"
D.Strings[85685]="这伤……比我想的还要严重……我得恢复一下。"
D.Strings[85686]="坑顶传来了一声尖叫。"
D.Strings[85687]="是裘碧卡！其他人可能还活着！"
D.Strings[85688]="我伤得太重……没法跟你走了。去找别人。合作……才有出路。"
D.Strings[85689]="别管我了！雷特森·焰怒从不拖后腿！"
D.Strings[85690]="鲜血图腾是个狡猾的部族，但我从没想过他们会接受恶魔的提议。我们必须在他们摧毁整个至高岭之前阻止他们。"
D.Strings[85691]="我一枪都没打空！"
D.Strings[85692]="你们好，孩子们，今天我们来做一些基础训练。"
D.Strings[85693]="好了好了，你们还没学会走，怎么能立刻跑呢。所有人，摆好姿势。"
D.Strings[85694]="噢，艾莎师父，我们今天能干点别的吗？我想学神鹤引项踢!"
D.Strings[85695]="呃……我不是孩子了。"
D.Strings[85696]="$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TINTERFACE\\ENCOUNTERJOURNAL\\UI-EJ-BOSS-Selin Fireheart.blp:50:80|t$b[凯恩·日怒]那是裂魂者的记号。裂魂者维努斯曾使用双刀将敌人的灵魂从他们的躯体中抽出来，强化自己的力量。"
D.Strings[85697]="是这个培训课程吗？"
D.Strings[85698]="安全机制覆盖……完毕。防御模式启动！"
D.Strings[85699]="我觉得我进错班了……"
D.Strings[85700]="机钳！你要短路了！快回来！"
D.Strings[85701]="没错……我很确定，这肯定不是我的培训课程。"
D.Strings[85702]="你真是个战术大师。"
D.Strings[85703]="狭路相逢勇者胜！"
D.Strings[85704]="没关系，你可以再试一次。"
D.Strings[85705]="或许换个更强壮的宠物会好一些？"
D.Strings[85706]="刚才那只宠物好像有点弱。"
D.Strings[85707]="要想获胜，你还要更加努力。"
D.Strings[85708]="看来我得认真点了！"
D.Strings[85709]="这只是热身。"
D.Strings[85710]="你打得很勇敢，小家伙。"
D.Strings[85711]="你一定走了很远的路，要喝点水吗？噢，宠物对战？如你所愿。"
D.Strings[85712]="上楼去，多利安。我来保护商店。"
D.Strings[85713]="你还觉得我是个老家伙吗，杰迪安？如果这座城市化为火海，那我也要给它陪葬。"
D.Strings[85714]="呃，那我就……我从来没讨厌过你，老朋友。"
D.Strings[85715]="准备尝尝我们的新配方吧。上一个配方太好喝了！所有的酒一个晚上就卖光了！"
D.Strings[85716]="恐怕赫米特也没什么可以教我的了。但愿我的进步能让他大吃一惊。"
D.Strings[85717]="表演结束了，各位。"
D.Strings[85718]="噢，骗子。"
D.Strings[85719]="把你知道的都教给我们吧，$n。"
D.Strings[85720]="太棒了！最近的一批货就在外面。"
D.Strings[85721]="什么味道？是……伊利达雷？"
D.Strings[85722]="拿起武器，战友们！议会需要我们的帮助！"
D.Strings[85723]="霍拉斯，带几个小伙子一起上前线吧。"
D.Strings[85724]="奥兰德，奥拉尔德，你们跟我走。"
D.Strings[85725]="看见了吗？基尔加丹赐下的力量远超伊利丹！"
D.Strings[85726]="等着你的只有死亡！"
D.Strings[85727]="听这位女士的！拿上武器，出门去！"
D.Strings[85728]="我感觉到了……更致命的恶魔能量。"
D.Strings[85729]="玛维还活着。我永远都不会忘记你的恩情的。"
D.Strings[85730]="我们在这里的主要目标就是夺取萨格里特钥石。\n\n我们得先搞定下面的敌人，然后登上泰兰娜的浮空指挥中心。"
D.Strings[85731]="阿莱利，这是我发现的秘密。"
D.Strings[85732]="快，胡恩！那头龙被削弱了。"
D.Strings[85733]="我不知道你怎么想，但为了活下来，我什么都愿意做。\n\n我们需要更多的力量！"
D.Strings[85734]="听好了，赛娅娜。这是我从邪魔之秘魔典中学到的知识。"
D.Strings[85735]="凭借泰坦之力，我要你滚出这片土地，大地守护者！"
D.Strings[85736]="还不够……我还要更多！"
D.Strings[85737]="我听说那位宗师从不睡觉。$g他:她;每晚都会遁入虚空！"
D.Strings[85738]="它在我的血管里流淌，改造着我的身体。"
D.Strings[85739]="凯恩，我要把我了解到的恶魔秘密传授给你。"
D.Strings[85740]="我一个人就能摧毁燃烧军团！"
D.Strings[85741]="要不是黑暗神殿遭到了攻击，我不介意在这里多呆一会儿。\n\n这里有太多恶魔可供我们杀了。"
D.Strings[85742]="你准备好了解燃烧军团的秘密了吗，考瓦斯？"
D.Strings[85743]="胡恩无论面对什么敌人都不会气馁吗？"
D.Strings[85744]="曼瑟瑞尔，做好准备。我要把燃烧军团的秘密力量灌输给你。"
D.Strings[85745]="$n，等等……我控制不了这股力量。"
D.Strings[85746]="天角部族已经追着那头野兽去了附近的一座洞穴。"
D.Strings[85747]="很好。决不能让他在如此靠近我们家园的地方聚集力量。我们必须把他从老巢里赶出来。"
D.Strings[85748]="胡恩之路不仅仅是我们民族的一个传统。它也是任何想要继承大酋长衣钵的人必经的正确道路。$b$b这是一条危险的道路，不是所有想要成为酋长的人都能安然归来的。$b$b你准备好出发后就告诉我一声吧。"
D.Strings[85749]="他们来了……世界末日降临了！"
D.Strings[85750]="别那么激动，帕蒂。议会都在城里呢。我们会没事的！"
D.Strings[85751]="快躲起来，好吗？我来挡住他们，不让他们闯进店里来。"
D.Strings[85752]="我们正处于毁灭的边缘，但我们并不孤单。上前来，萨满。"
D.Strings[85753]="恶魔，服从林奇·黑箭的命令吧！"
D.Strings[85754]="加入议会吧，先知。大地之环已经重生，我们也将以此重新点燃世界的希望。"
D.Strings[85755]="你是我们精心挑选的艾泽拉斯守护者！愿你的智慧引导议会走向胜利，愿你的武器碾碎给这片土地带来混乱的敌人。"
D.Strings[85756]="什么？！你肯定作弊了！"
D.Strings[85757]="这完全是小菜一碟！"
D.Strings[85758]="哈！你还敢自称是驯宠师？"
D.Strings[85759]="我从不失手。"
D.Strings[85760]="熏死你。"
D.Strings[85761]="这个垃圾是谁卖给我的？"
D.Strings[85762]="这不是付了钱就能赢的吗？！"
D.Strings[85763]="我能要求退款吗？"
D.Strings[85764]="看来你已经准备好挨揍了！"
D.Strings[85765]="抱歉，朋友。肯定是曹敖更厉害，看看他那块头！"
D.Strings[85766]="曹敖刚刚入门一年，可他已经可以一个人单挑三个猛虎派的人了！"
D.Strings[85767]="我出十个金币，押曹敖获胜！"
D.Strings[85768]="元素选择了你作为他们的勇士，$n。你手中的神器就是证据。$b$b你的命运就是领导大地之环对抗燃烧军团。我们需要你。你愿意接受这份责任吗？"
D.Strings[85769]="好的，我愿意做你们的先知！"
D.Strings[85770]="听大法师的！防御阵型！"
D.Strings[85771]="肯定是付林赢。他出手的速度只比宗师慢一点儿！"
D.Strings[85772]="如果打不到对手，大块头就毫无意义！付林会把他拖垮的。"
D.Strings[85773]="我醒了？这怎么可能？"
D.Strings[85774]="他的速度就像出击的蛇一样快！我可不想跟他打。"
D.Strings[85775]="我跟你打这个赌，要是输了，我就请你们去笑鹤酒馆喝最新的啤酒。"
D.Strings[85776]="不管有没有受伤，我们都必须战斗！"
D.Strings[85777]="我们绝不投降！"
D.Strings[85778]="欢迎来到黯石岩洞。虽然其貌不扬，但它是我们的家。"
D.Strings[85779]="这里看起来虽然不怎么样，但却是我们的家。"
D.Strings[85780]="我们在这里宁静度日，远离其他卓格巴尔。"
D.Strings[85781]="黯石！我回来了！这位英雄将我们从鲜血图腾手里救了出来。"
D.Strings[85782]="如果有必要，我们会帮助他们的。"
D.Strings[85783]="噢，还有，别杀$G他:她;。"
D.Strings[85784]="等等！请等等，别伤害卡里杜斯！"
D.Strings[85785]="贝莎达已经走了！卡里杜斯看到你的力量了，术士。卡里杜斯想要帮忙！"
D.Strings[85786]="卡里杜斯的主人是最最残酷的贾格诺斯。他总是欺负卡里杜斯。可是你，你能消灭他！"
D.Strings[85787]="卡里杜斯引开哨兵。快去找你的朋友。我们待会儿见！"
D.Strings[85788]="有囚犯逃跑了！"
D.Strings[85789]="啊，你醒了！感觉好些了吧？你已经昏迷了好几天了！"
D.Strings[85790]="欢迎来到神真子的背上！我对于晴日峰的事很抱歉。我们绿野村的村民都很乐意让你们留下。"
D.Strings[85791]="其他幸存者都在寺院里。如果你感觉好些了，就去那儿找他们吧。"
D.Strings[85792]="我们需要一个像胡恩那样的领袖，一个有能力和勇气面对任何困难的人。而你已经证明了自己。"
D.Strings[85793]="我们走，$n。"
D.Strings[85794]="所以你还需要见证最后一段幻境。自从胡恩驱逐了死亡之翼后，这个秘密就在大酋长之间代代相传。"
D.Strings[85795]="这真是一次伟大的狩猎！我们得趁我印象还深刻的时候赶快回营地去。"
D.Strings[85796]="听萨布莉娜的！我们会确保你俩的安全的。"
D.Strings[85797]="快回去！找个地方躲起来。把战斗的事交给我们，好吗？"
D.Strings[85798]="我为守军准备了一些补给品！"
D.Strings[85799]="我献出了我的血肉，我的灵魂；族人却把我视为怪物。"
D.Strings[85800]="我只想服务我的人民，我的女神。我不在乎个人利益或是荣耀。"
D.Strings[85801]="我为人民而战，为那些被放逐和唾弃的人而战。"
D.Strings[85802]="你说决斗？快做好准备！"
D.Strings[85803]="真是个噩梦！这简直又是一次未成年人银色锦标赛！"
D.Strings[85804]="回去再好好训练吧！先做五十个深蹲！"
D.Strings[85805]="看来我要有一个新死敌了！"
D.Strings[85806]="如果你想的话，我可以蒙着眼睛跟你打。"
D.Strings[85807]="一次英勇的尝试。"
D.Strings[85808]="矛尖总是最锋利的。"
D.Strings[85809]="你可以做我的侍从。"
D.Strings[85810]="你准备好了吗，奔波尔斯顿爵士？勇敢地战斗吧！"
D.Strings[85811]="打得不错！打得不错！"
D.Strings[85812]="有把锤子。靠近它的人都会被死亡之翼吃掉。"
D.Strings[85813]="这是泰坦的传送门。里面有什么？"
D.Strings[85814]="这边走，先知。那个牛头人说下面有个密室，可以作为我们的大本营。"
D.Strings[85815]="别犹豫了。我们得干掉那畜生，解放我的族人。"
D.Strings[85816]="这把锤子和死亡之翼都是泰坦的工具。我恐怕杀不了他，但或许能赶走他。"
D.Strings[85817]="我们在牢房里浪费了多少岁月？"
D.Strings[85818]="梅拉，我还是你认识了一辈子的那个灵魂行者。记住，无论发生什么事，我都忠于大酋长。"
D.Strings[85819]="在当时看来，我还是不要告诉屠龙者们我是一条龙比较好。"
D.Strings[85820]="请送我去沉船海湾。"
D.Strings[85821]="$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TINTERFACE\\ENCOUNTERJOURNAL\\UI-EJ-BOSS-Selin Fireheart.blp:50:80|t$b[凯恩·日怒]他是萨格拉斯所摧毁的第一个世界中最伟大的勇士，也是唯一曾在战斗中伤害到他的存在。"
D.Strings[85822]="$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TINTERFACE\\ENCOUNTERJOURNAL\\UI-EJ-BOSS-Selin Fireheart.blp:50:80|t$b[凯恩·日怒]所以我们必须完成追击。这把利刃的意志可以让我们彻底摧毁燃烧军团的邪恶主宰。"
D.Strings[85823]="走开。你别想拿走我的书！"
D.Strings[85824]="他们在窃取我们的机密，女王陛下……"
D.Strings[85825]="仆从们，尽全力找回那本书！"
D.Strings[85826]="好极了！让我们动手吧！"
D.Strings[85827]="你的灵魂是我的了，准备受死吧！"
D.Strings[85828]="我……必将……重生……"
D.Strings[85829]="见证我的力量吧！"
D.Strings[85830]="$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TINTERFACE\\ENCOUNTERJOURNAL\\UI-EJ-BOSS-INSTRUCTOR MALICIA.blp:50:80|t$b[凯丽娅·邪魂]这个可悲世界上所有的灵魂都将属于我。"
D.Strings[85831]="哈！看来阿维亚什没在来的路上把你扔进河里。很好！这说明他开始喜欢你了。$b$b我们可以开始完成仪式了吗？"
D.Strings[85832]="很好！我讨厌繁文缛节，赶快结束吧。"
D.Strings[85833]="我已经让我的巨鹰骑手飞往雷霆图腾了。很快你就会发现天上飘满了羽毛。"
D.Strings[85834]="我，天角部族酋长拉善·天角在此宣誓，再次效忠高岭部族。"
D.Strings[85835]="我们是团结一致的高岭部族。"
D.Strings[85836]="想和海洋作对的人一定会以失败收场。"
D.Strings[85837]="太阳出来啦！宠物们，出击吧！"
D.Strings[85838]="我想我的伙计们应该在水上多呆点时间。"
D.Strings[85839]="风暴来临了！"
D.Strings[85840]="海浪助我碾压敌人！"
D.Strings[85841]="你在出海前应该再多训练训练。"
D.Strings[85842]="并非所有的海浪都是赢家。"
D.Strings[85843]="被淘汰了！"
D.Strings[85844]="抹点沙子。"
D.Strings[85845]="不能冲浪，我们就只能来战斗了。"
D.Strings[85846]="就这点本事吗，恶魔？我还以为你们最擅长酷刑呢。可怜虫！"
D.Strings[85847]="趁你的脑子还清醒就赶紧多说几句吧，蛆虫！"
D.Strings[85848]="谢谢你的帮助，术士。这些恶魔真是太无趣了。"
D.Strings[85849]="你休想一直保持沉默，狼人！"
D.Strings[85850]="对……我能感觉到你的意志正在崩溃。"
D.Strings[85851]="我差点就成为狗粮了。谢谢你。"
D.Strings[85852]="休想！"
D.Strings[85853]="别害怕！这不是塔伦德斯第一次遭到攻击了，而且我向你保证，这也不会是最后一次！"
D.Strings[85854]="我们必须坚持住！决不能让岗哨陷落！"
D.Strings[85855]="我会没事的。去看看其他人吧。"
D.Strings[85856]="守住岗哨！"
D.Strings[85857]="战刃！快用战刃！"
D.Strings[85858]="欧库勒斯！"
D.Strings[85859]="大法师卡德加！我想和你谈谈。我感觉我的贡献……"
D.Strings[85860]="恶魔猎手？怎么——"
D.Strings[85861]="先生，我觉得这个是一个绝妙的——"
D.Strings[85862]="好的，先生！我已经对伊利达雷的制服有一些很好的想法了！"
D.Strings[85863]="他人呢？我刚才还看见他在瞎转悠呢。星歌！"
D.Strings[85864]="好的，好的，我们稍后再来讨论这件事。我收到了一个来自伊利达雷的请求，正好需要你的帮助。"
D.Strings[85865]="你得去阿苏纳找食魂者阿莱利报告。立刻就去。"
D.Strings[85866]="制服？看在圣光的份上……"
D.Strings[85867]="等等……雷特森呢？"
D.Strings[85868]="那个兽人的伤太重，跟不上了。没关系，我们四个足以控制那深渊领主。这仍是我们的目标吧？"
D.Strings[85869]="好吧，固执的狼人！我们逃命要紧。但如果有机会奴役那个恶魔，我们还是该果断出手！"
D.Strings[85870]="那就这么说定了。我们走。"
D.Strings[85871]="$n，来这边。我们已经好久没有认真狩猎了，你觉得呢？"
D.Strings[85872]="我看你还是死了比较好，凡人！"
D.Strings[85873]="等我们干掉这里的入侵者，就可以开始努力将暗夜精灵赶出我们的土地了。"
D.Strings[85874]="你真以为你能跑掉？我要碾碎你！"
D.Strings[85875]="既然事情已经解决了，$n，我还有一些肯瑞托的事务要处理。保重。"
D.Strings[85876]="杰斯、阿莱利、考瓦斯、奥图里斯——我们立刻离开这里。执行者们——给我们断后。"
D.Strings[85877]="这边走！这边！"
D.Strings[85878]="那是什么鬼东西？"
D.Strings[85879]="卡里杜斯是朋友，你会看到的！贾格诺斯在找强大的武器。朋友能用这些武器统治这里！"
D.Strings[85880]="贾格诺斯在寻找强大的、能够危及燃烧军团的武器。如果你们能拿到一件，那就连强大的贾格诺斯也会倒在你们脚下！你们可以统治这个地方，卡杜里斯会辅佐你们的！"
D.Strings[85881]="统治？我喜欢这个词。"
D.Strings[85882]="等等，辛菲儿。天知道这家伙可不可靠？"
D.Strings[85883]="卡杜里斯绝对可靠！快去档案室！就到了！"
D.Strings[85884]="这次狩猎可真刺激！"
D.Strings[85885]="在这幢废弃已久的屋子里，你感觉到了一股微弱的附魔力量。"
D.Strings[85886]="啊！停滞法术……她会付出代价的！"
D.Strings[85887]="过了这么久，是谁唤醒了我？"
D.Strings[85888]="这不关你的事，外来者。塔莉萨背叛了大魔导师，必须让她伏法！"
D.Strings[85889]="见证夜之子的力量吧！"
D.Strings[85890]="你……是谁？"
D.Strings[85891]="$n，我得跟你谈谈。"
D.Strings[85892]="凯恩他们都在克拉苏斯平台。我在那里等你。"
D.Strings[85893]="我们是……什么？！"
D.Strings[85894]="你的死亡早已注定！"
D.Strings[85895]="我们的魔法会粉碎你！"
D.Strings[85896]="你这样的下等人应该学会服从！"
D.Strings[85897]="夏多雷将统治世界！"
D.Strings[85898]="不……曼瑟瑞尔。"
D.Strings[85899]="圣光……救救我……"
D.Strings[85900]="我得集中精神准备献给女王的酒。我为什么会如此……不安？"
D.Strings[85901]="恶魔已经死了！赶快解决剩下的攻击者，我们就可以开始重建了。"
D.Strings[85902]="我们欠你们一份人情，勇士们。"
D.Strings[85903]="这个怪物已经死了！做好准备！战斗还没有结束。"
D.Strings[85904]="好……好饿啊……"
D.Strings[85905]="你！加入我们吧！"
D.Strings[85906]="等这事结束之后，就继续我们的计划。"
D.Strings[85907]="你好，$n。但愿这个投影足够清晰！我是六人议会的大法师茉德拉。我发现了某件武器的线索，它能帮你抗击燃烧军团。"
D.Strings[85908]="我的线人……呃……没法进城来见我们。我想请你到希尔斯布莱德的达拉然巨坑来见我。"
D.Strings[85909]="期待着你的到来。"
D.Strings[85910]="我真是受够了。今天，我是不会死在这里的！"
D.Strings[85911]="这些邪恶的暴徒休想在我的宝贝林地里横行。"
D.Strings[85912]="哇！……嘿，$g先生:女士;！别动手！我这儿有你的快递。"
D.Strings[85913]="感谢使用热砂快递公司！"
D.Strings[85914]="等等，混蛋！"
D.Strings[85915]="恶魔已经被解决了。"
D.Strings[85916]="我的小伙伴怎么样了？"
D.Strings[85917]="消灭！吞噬！"
D.Strings[85918]="不速之客休想闯进我们的家。永远……休想！"
D.Strings[85919]="如果没有弹药了，就把扳手扔出去，小伙子们！"
D.Strings[85920]="加汗大师的女儿，丽约塔追随他父亲的脚步，成为了至高岭最伟大的皮匠之一。而她最伟大的成就则是反对陋习，移风易俗。$b$b加汗过世后，所有人都期待着丽约塔继承父亲的传统。这时她对族中的长老们说：“同胞们，我们世代在这片土地上狩猎，它赐予了我们食物、衣物和住所。”$b$b“可我们太浪费了，”她继续说道，“我们将猎物的牙齿、蹄子和爪子都一起埋进了土里。”"
D.Strings[85921]="“这是我们的风俗，”一位长老回答，“我们将它们的武器留给它们的灵魂，好让它们在冥界继续狩猎。这是为了表达我们的敬意，丽约塔。你应该很清楚这一点。”$b$b“我不这么看，长老。我们表达敬意的方式，难道不应该是保证那些猎物不会白白牺牲吗？”她问道，“我们应该物尽其用不是吗？如果我们可以利用起动物余下的毛发，就可以让我们的护甲结实一倍。”$b$b长老们低声讨论了一会儿，然后看向丽约塔。"
D.Strings[85922]="下面！让他们来吧！"
D.Strings[85923]="“改变风俗，就等于改变我们的生活方式。我们认为在护甲里加上这些东西的话，除了显得我们不尊重那些死去的动物外，对护甲本身不会有什么帮助。”$b$b丽约塔挑了挑眉毛，听长老继续说道：“我们很抱歉，丽约塔，但我们不同意你用这种方法折腾我们的护甲。如果你想要强化我们的护甲，就得想其他办法。”$b$b说完，长老就离开了帐篷，留下沮丧的丽约塔一个人思考。"
D.Strings[85924]="他们有魔法，我们有炸药！"
D.Strings[85925]="啊，火药和爆炸的味道。"
D.Strings[85926]="我不知道。我有种不好的预感。"
D.Strings[85927]="看来这个深渊领主正在策划一场入侵。"
D.Strings[85928]="拿起武器，我的怒火之子们！今晚，我们要直捣那些凡人的要害！"
D.Strings[85929]="加入我们……永远加入吧……"
D.Strings[85930]="噢，不……传送门！"
D.Strings[85931]="第二天，丽约塔穿着一套奇怪的护甲走出了帐篷。人们疑惑地看着她走到营地中央。$b$b“这套护甲是用我前几天打到的一头蓟鬃熊的牙齿和爪子做的。”明白了她的所作所为后，族人们脸上都露出了震惊的表情。$b$b“我要向族中所有的战士发起挑战，看谁能刺穿我的护甲。”族人们面面相觑不知道该怎么对待丽约塔的挑战。"
D.Strings[85932]="他们肯定将他们的通道和我们的召唤传送门连接到了一起。他们打算攻击达拉然！我们得关闭那座传送门！"
D.Strings[85933]="说得好像我们能抵达通道似的……"
D.Strings[85934]="死吧，死吧，死吧。"
D.Strings[85935]="我要吞掉你的灵魂。"
D.Strings[85936]="“丽约塔！”人群中响起了一个声音。一位年轻的勇士手提长矛走了出来：“我接受你的挑战。你所做的一切都践踏了我们的传统。将你灵魂逐出此地将是我的荣幸。”$b$b说完，勇士就冲向了丽约塔，而她则一动不动。矛尖直刺她的心口，勇士的巨力将她推翻在地。但当尘埃落地之后，奇怪的事情发生了。长矛没能刺穿那件护甲。"
D.Strings[85937]="勇士站起身来，手里还抓着长矛。他开始检查自己的矛尖，只见长矛的尖端有一点弯了。$b$b他低头去看丽约塔，她还躺在那里，手按在胸口上，但没有血流出来。过了一会儿，丽约塔也爬了起来，大口的喘着气，但似乎没有受伤。“这就是我想给你们看的！”她大声说道，“我杀掉的动物用它的生命和躯体保护了我，这并不是什么亵渎。”$b$b整个部族都安静了下来，所有人都在全神贯注地看着丽约塔，看她有什么想说的。"
D.Strings[85938]="噢——"
D.Strings[85939]="肉……把你的肉给我。"
D.Strings[85940]="死亡……会吞噬你。"
D.Strings[85941]="死亡只是个开始……"
D.Strings[85942]="“我们猎杀的动物可以这样保护我们所有人，只要你们同意我继续用这种方法制作护甲。”她接着说道。$b$b一位长老分开人群走向丽约塔。他检查了她的护甲，尤其是被长矛刺中的地方。$b$b接着，他点了点头，开口说道：“我现在明白了，丽约塔。这不是什么虚荣，而是力量。”$b$b他转过身来，对族人们说道：“丽约塔给了我们一个壮大的机会。我们的族人不会再轻易倒在猎物或者凶猛的掠食者爪下。而我们也将以我们身上的护甲继续向我们的动物兄弟姐妹们表达敬意。”"
D.Strings[85943]="就这样，加汗之女丽约塔改变了部族的风俗。直到今天，至高岭生产的皮甲，仍然会使用动物的各种有用部件来强化自身的防御力。"
D.Strings[85944]="鉴于此事的敏感性，你要注意，如果你在其他地方跟我提起这件事，我是不会承认送过这个口信的！"
D.Strings[85945]="那就去吧，帮我找些悬崖棘来。"
D.Strings[85946]="我要享用你的精华……"
D.Strings[85947]="离开这个微不足道的躯壳，加入我们的行列……"
D.Strings[85948]="收割时间到！"
D.Strings[85949]="黑鸦堡垒的古代幽灵，来加入合唱吧！"
D.Strings[85950]="这……这力量……太强大了！"
D.Strings[85951]="欢迎，$n。很高兴你收到了口信。"
D.Strings[85952]="自由！我……"
D.Strings[85953]="我们……我们怎么会在这里？！"
D.Strings[85954]="恶魔！这都是你们造的孽！"
D.Strings[85955]="这下……我明白了……"
D.Strings[85956]="黑暗……消失了。"
D.Strings[85957]="你们……这不是你们干的吗？"
D.Strings[85958]="都别碰它！等客人来了再说。"
D.Strings[85959]="我……现在明白了。你……你必须找到库塔洛斯。你必须阻止这一切。"
D.Strings[85960]="就是这儿——这条小路是父亲告诉我的！拿上它，去找他吧！"
D.Strings[85961]="至于我们……我们不属于这里。再见，愿艾露恩之光指引你。"
D.Strings[85962]="感谢两位到这穷乡僻壤来见我。我向你们保证，如果可能的话，我很乐意在达拉然见你们。"
D.Strings[85963]="这正是我来这里的原因。就算我不能恢复过去的席位，那或许议会至少能够考虑让我回到达拉然。为了表达诚意，我有一个消息要告诉你们。"
D.Strings[85964]="我认识安纳斯特里亚国王的一个远房表亲，莉安达·逐日者。她虽然姓逐日者，但她的这一支家族其实是没有王位继承权的。"
D.Strings[85965]="在凯尔萨斯背叛之后，她就沉迷于将烈焰之击据为己有。我告诉过她这是个愚蠢的念头，她永远也别想找到那件圣物。事实上，我也确实有好多年没有听到过她的消息了。"
D.Strings[85966]="这些卓格巴尔是从哪儿冒出来的？！"
D.Strings[85967]="你真强！"
D.Strings[85968]="愿大地母亲护佑着你！"
D.Strings[85969]="穆兹！噢，感谢大地母亲，你没事！祝福你！"
D.Strings[85970]="囚犯逃跑了！快追！"
D.Strings[85971]="没用的废物！让我亲手解决你们！"
D.Strings[85972]="这个传送门可以让你直接进入冰冠堡垒。快，它维持不了多久！我会尽快赶上你的。"
D.Strings[85973]="联盟会最好准备的。我会让警钟响彻银色领地上空。"
D.Strings[85974]="燃烧军团！他们已经来了。散开，掩护领地。把这些恶魔送回地狱老家去！"
D.Strings[85975]="鲁伦，你负责旅店。塞罗妮，你负责上层。其他人，自己找适合防守的位置！"
D.Strings[85976]="斯蒂芬、伊丝拉米，让所有人都躲进地窖！燃烧军团是来阻止大法师卡德加的！"
D.Strings[85977]="又有援军过来了！准备好你们的法术！"
D.Strings[85978]="入侵者闯入了通向墓地的走廊。伊莉萨娜，挡住他们。"
D.Strings[85979]="看看这座城市，$r。它是如此美丽，又是如此悲哀。$b$b我们都是龟缩在那个护盾下的懦夫。我们本该守护艾泽拉斯，可却选择了抛弃她。我们没有履行保护世界的神圣职责，这是我们最大的耻辱。"
D.Strings[85980]="还有一个办法，泰德里斯。我们在不远处有一座避难所。塔莉萨就在那里。"
D.Strings[85981]="所有人，跟我走！快，给守卫腾出点空间！"
D.Strings[85982]="保重，鲁伦。谢谢！"
D.Strings[85983]="塔莉萨逃跑了？她总是那么理智。我很高兴她没有留下来，与大魔导师同流合污。$b$b可是，这也是徒劳的。我们的盟友稀少而分散，我们的敌人却有一个强大的靠山。我们不可能阻止他们的联军。$b$b来吧，如果你想得到我的硬币，就还有许多事要做。"
D.Strings[85984]="我们掩护你，$n。"
D.Strings[85985]="堕落者，快进入那个传送门！贾格诺斯渴望这些凡人的鲜血。"
D.Strings[85986]="别傻了！传送门还不稳定，无法让整支大军通过。你想迷失在扭曲虚空里吗？"
D.Strings[85987]="那把钥匙！他们在用它稳定传送门。"
D.Strings[85988]="那我想我们应该把它抢过来。"
D.Strings[85989]="河鬃部族并不好战，但这种入侵我们神圣洞穴的行为决不能轻易放过。让卓格巴尔看看水系魔法的威力吧。\n\n悠久的历史带来智慧，而智慧则能带来力量！"
D.Strings[85990]="你们还在等什么？碾碎他们！"
D.Strings[85991]="跪下迎接你们的新主人吧！"
D.Strings[85992]="你们休想打败我们！我们是军团！"
D.Strings[85993]="你们别想阻止我！我不会失败的！"
D.Strings[85994]="我们损失惨重——尤其是你父亲的死。"
D.Strings[85995]="哈，干得好！这下他们在捣乱前就会掂量掂量了。"
D.Strings[85996]="呃……你，呃……你感觉到没有？"
D.Strings[85997]="没错！肯定是地面在震动！"
D.Strings[85998]="南墙——来了！"
D.Strings[85999]="你不属于这里，$c。"
D.Strings[86000]="大地母亲将收下你的尸体！"
D.Strings[86001]="让流水淹没你！"
D.Strings[86002]="滚出去！我用一生滋养的魔力，可不是为了给你们这些家伙的！"
D.Strings[86003]="就是它！看看我们能不能让这个传送门变得不那么稳定！"
D.Strings[86004]="滚回深渊去！噢！我的腰！"
D.Strings[86005]="这里会削弱你的魔法！"
D.Strings[86006]="他们想要干扰我们的引导！阻止他们！"
D.Strings[86007]="起作用了，我们还需要一点时间！"
D.Strings[86008]="我们试过了和谈，现在该试试战争了！"
D.Strings[86009]="我这把老骨头已经折腾不起了。"
D.Strings[86010]="为了河鬃！……你说话了吗？大点声！"
D.Strings[86011]="你们就这点本事吗？我的人现在出的这点力气简直对不起他们的工资……"
D.Strings[86012]="把夺日者交给我吧。"
D.Strings[86013]="部落的守护者们，燃烧军团的客人来了。让我们好好招待他们吧！"
D.Strings[86014]="小地精——你的无知将是死亡的先兆。"
D.Strings[86015]="别再犯傻了。"
D.Strings[86016]="……说得太早了。北边！小心！"
D.Strings[86017]="我会在西南边的悬崖岩架上等你。不要再耽误时间了。"
D.Strings[86018]="如果你是来找锁甲的，那就来对地方了！我这里有全城最好的锁甲！"
D.Strings[86019]="你有多余的撬棍吗？"
D.Strings[86020]="这是你要的架子，现在能把撬棍给我了吗？"
D.Strings[86021]="你以为我会白送给你吗？抱歉，$g小子:丫头;，有付出才能有收获。"
D.Strings[86022]="我愿意用一根撬棍来换取几个新的护甲架。坦克用品店的伊曼蒂尔那里就有一些。"
D.Strings[86023]="去帮我弄几个来，我就把撬棍给你。"
D.Strings[86024]="对对，万灵对你们很重要。我明白。"
D.Strings[86025]="老实说，我是因为你提到了卡兹格罗斯才来的。"
D.Strings[86026]="动作可真够慢的，你该不会是在回来的路上先去喝了一杯吧？我们说好的，这是你要的撬棍。"
D.Strings[86027]="姐妹们，这边走！"
D.Strings[86028]="欢迎来到坦克用品店。我们这里有锻造和采矿所需的各种优质物品。"
D.Strings[86029]="如果你真像自己以为的那么强大，那你或许比上次那个来寻找它的法师更有资格得到它。"
D.Strings[86030]="你这儿有多余的护甲架吗？"
D.Strings[86031]="这是你的裙子。现在能把护甲架给我了吗？"
D.Strings[86032]="我是有几个多余的护甲架，可我真的不想把它们送掉。除非……"
D.Strings[86033]="你愿意帮我跑个腿吗？只要你帮我这个忙，我保证给你一些护甲架。"
D.Strings[86034]="我只需要你把我的裙子送到山迪那里去清洗一下，上面沾满了煤灰。"
D.Strings[86035]="那个山迪……那家伙真的可以把血渍清理干净！这是我答应你的护甲架。"
D.Strings[86036]="但我要警告你！无论是你……还是上次来抢夺我圣物的那个法师，不管你们出了什么事，我都不会为此负责。"
D.Strings[86037]="你能帮我清洗一下这条裙子吗，山迪？"
D.Strings[86038]="支付2枚金币。"
D.Strings[86039]="我当然可以帮你清洗。每件衣服两个金币。"
D.Strings[86040]="我马上就帮你洗干净！"
D.Strings[86041]="一条裙子，就像新的一样。感谢你的光顾。"
D.Strings[86042]="我们要赌那个侏儒能坚持多久吗？"
D.Strings[86043]="梅拉，我答应过你父亲一定会为你主持这个仪式的。拜托了，你的人民需要它，你也需要它。"
D.Strings[86044]="我不知道那些牛头人在搞什么，但这些不是万灵。这些是时间的回响。这里一定发生过什么非常可怕的事情。"
D.Strings[86045]="我……遵命……"
D.Strings[86046]="击退他们！我们还得再坚守一会儿！"
D.Strings[86047]="燃料快用完了！"
D.Strings[86048]="我不知道我还能将他们挡在港口外多久！"
D.Strings[86049]="他们一直在破坏我的双翼！我不知道我还能在空中拦她多久。"
D.Strings[86050]="我们必须消灭他们，小伙子们！地面部队正在节节败退！"
D.Strings[86051]="这就是我们受训的目的！"
D.Strings[86052]="天生飞行员！不胜利毋宁死！"
D.Strings[86053]="好吧，阿夸诺斯，你上！"
D.Strings[86054]="脱下靴子休息一会儿吧。没有什么能比在星空下睡觉更舒服的了。"
D.Strings[86055]="港口的威胁已经……至少是被削弱了。从现在开始，都交给我们来搞定吧。"
D.Strings[86056]="你奈何不了这些蠢牛吗，戈尔莫格？"
D.Strings[86057]="或许我低估了你……"
D.Strings[86058]="等你解决了这个麻烦，就来河湾找我。"
D.Strings[86059]="虽然阿卡纳精华可以帮我完成大部分工作，但最后一个单词需要一种更强大的材料。确切的说，我需要一块魔光碎片。$b$b我们把这些又大又吓人的恶魔文字启动起来吧！"
D.Strings[86060]="请尽快到河湾来见我，$n。我就在那里等你——我这把老骨头已经大不如前了。"
D.Strings[86061]="地狱火！"
D.Strings[86062]="让燃烧军团吞噬你！"
D.Strings[86063]="别担心。我不会输的，拉图修斯。"
D.Strings[86064]="愚蠢的凡人！现在你是我的了！"
D.Strings[86065]="好吧，如果不是这里的话，那我真不知道会是哪里了。看来死亡之翼当初搜刮了不少东西。$b$b你准备好之后就告诉我一声，我们来看看那条老龙留下了哪些防御措施。"
D.Strings[86066]="你逃不出燃烧军团的……掌心。"
D.Strings[86067]="燃烧军团……是不朽的！"
D.Strings[86068]="你踏入了亡者的领土，凡人。巫妖王有令，任何生者都不准进入冰冠堡垒！"
D.Strings[86069]="这个世界将……化为火海……"
D.Strings[86070]="诸位！入侵者过来了。别让他们过去！为了卡利姆多！"
D.Strings[86071]="这些凡人在这里做什么？卫兵，抓住他们！"
D.Strings[86072]="你们将葬身此地，蠢货。"
D.Strings[86073]="你可以通过这张地图将大地之环的成员派往破碎群岛各地。带领我们走向胜利吧，先知！"
D.Strings[86074]="这座星界传送门能随时将你送回达拉然，先知。我会让它保持开启，以便你随时回来。"
D.Strings[86075]="等你在破碎群岛的威望更上一层楼之后，记得回来找我，$n。我们还有很多事情要做！"
D.Strings[86076]="它就那样紧紧地抓着我……我从来没有过这样的感受。"
D.Strings[86077]="我会一直坚守在这里，直至结束。"
D.Strings[86078]="有来自其他地方的陌生人慕名前来找我？我很高兴见到你。我要传授给你有关整体的知识。"
D.Strings[86079]="有人认为过程才是最重要的，而有人认为结果才最重要。"
D.Strings[86080]="一个真正的大师应该明白，整体的经验才是最有益的。永远不要因为抵达了终点就把起点给忘了。"
D.Strings[86081]="这座山洞属于奔波儿部族！"
D.Strings[86082]="这是给你的报酬。"
D.Strings[86083]="别忘了代我们问候那些恶魔。"
D.Strings[86084]="你的事迹已经证明了你的荣耀。"
D.Strings[86085]="保持警惕，小心腐蚀。"
D.Strings[86086]="愿你为平衡而战。"
D.Strings[86087]="我祝福你。"
D.Strings[86088]="你可以对拥有该减益效果的目标使用间谍大师杰瑞的瞄准镜。"
D.Strings[86089]="死亡之翼想藏起这把泰坦之锤？或许这就是我们挑战他所需的武器。"
D.Strings[86090]="看来老死亡之翼留下了自动防御装置。掩护我。"
D.Strings[86091]="试试瞄准那些泰坦防御者。他们的宝珠就是维持传送门开启的关键。"
D.Strings[86092]="好了！这样应该就够了。我在这座龙穴的出口附近等你。"
D.Strings[86093]="醒醒，血翼！撕碎我的敌人！"
D.Strings[86094]="你的敬意让我受宠若惊，$r。对那些尊重我的人，我所要传授的智慧就是节俭。"
D.Strings[86095]="不要随意扔掉那些暂时看不出用途的碎片。"
D.Strings[86096]="$n，谢谢你能来。在这座大厅里，你能看到我们民族的历史。近百年来我亲身参与的，最欣欣向荣的一段历史。"
D.Strings[86097]="我们的历史上有丰收也有战争。当所有部族都团结在一起时，就是我们最强大的时候。"
D.Strings[86098]="啊，雷霆图腾。这感觉就对了。我的膝盖？感觉还是不太对劲。"
D.Strings[86099]="在它的见证下，我，河鬃部族酋长洁儿·河鬃宣誓，再次效忠高岭部族。"
D.Strings[86100]="塞兰提娅发出哀嚎，召唤着古代守护者！"
D.Strings[86101]="聚沙也能成塔，集腋亦能成裘。"
D.Strings[86102]="随着卓格巴尔对我人民的威胁降低，我们很乐意重新加入梅拉·高岭的事业。你准备好之后，我就可以开始仪式了。"
D.Strings[86103]="你表示敬意，我传授知识。现在听好了，我的课是有关灵活的。"
D.Strings[86104]="鞣制皮革的方法同样可以用来锤炼灵魂和意志。"
D.Strings[86105]="早点把你干掉，我就可以早点回去睡觉了！"
D.Strings[86106]="相信自己的结论能给你力量，但用灵活的方法达到目的可以给你智慧。"
D.Strings[86107]="总算能……睡觉了……"
D.Strings[86108]="给我一个不让塔拉斯撕掉你的翅膀扔到你脸上的理由。"
D.Strings[86109]="听着，钢铁部落那个插曲完全是个误会。加尔鲁什本来是应该说服他们去抵抗燃烧军团的，而不是入侵艾泽拉斯。"
D.Strings[86110]="呸。我从不相信任何巨龙。但至少他给我们指出了一条明路。等我们把这些圆盘运回铁炉堡，我就能真正开始研究它们了。"
D.Strings[86111]="请找到穆兹。我也会努力恢复过来去找他的。如果你找到他，就将他带去上游他母亲那里吧。"
D.Strings[86112]="$n！总算找到你了。我已经把四风都派出去找你了。快跟我来。"
D.Strings[86113]="%s指了指萨尔。"
D.Strings[86114]="你想要什么，小家伙？你想学习？好，那我就给你上一课。"
D.Strings[86115]="可不是只有你才有仆从，恶魔！"
D.Strings[86116]="一定要好好教训那些恶魔！"
D.Strings[86117]="很高兴你能来。好久没见到援军了。"
D.Strings[86118]="这就像个派对，不是吗？好多不速之客啊。"
D.Strings[86119]="等附近恢复正常之后，记得要保持友好。"
D.Strings[86120]="你说的对，姐妹！"
D.Strings[86121]="死在我手下吧！"
D.Strings[86122]="绝对不要去加工还长在动物身上的皮，尤其是活着的动物身上的皮，相信我。"
D.Strings[86123]="我要教给你的就这些了。"
D.Strings[86124]="来了解一下我们的故事吧，外来者。它们蕴含着深刻的意义。"
D.Strings[86125]="这或许是个好机会，泽宁……"
D.Strings[86126]="你的灵魂将会燃烧！"
D.Strings[86127]="这个世界必将……灭亡……"
D.Strings[86128]="我们……无穷无尽……"
D.Strings[86129]="兄弟姐妹们！神殿——必须保护神殿！"
D.Strings[86130]="他们亵渎了我们的废墟！"
D.Strings[86131]="这座纪念碑不如周围其他纪念碑那么宏伟、那么著名，但这对我来说有着特别重要的意义。这里长眠着拉塔娜夫人，她是一位优秀的女猎手，也是我的妻子。噢，我真想念她。"
D.Strings[86132]="是控心者！不要放弃！"
D.Strings[86133]="辛玛洛是属于我们的！"
D.Strings[86134]="不要害怕，我并不惧怕死亡。我很快就能和挚爱的妻子团聚了。你身边的这些英雄们都是和我一样的人。他们有自己的爱恨情仇，他们也懂得牺牲的意义，而这也将成为我生命的意义。$b$b<泰德里斯叹了口气。>$b$b或许你是对的，$n。我已经受够了族人们背负的耻辱。我曾以为我无路可走，也不会有人来帮助我。的确，我无法补偿我们所做下的一切。不管你怎么想，我并不是英雄。我只是饱经沧桑的老人而已。"
D.Strings[86135]="我们或许有办法缓解这种饥渴——从而争取到足够的时间来彻底治愈它。让我们帮忙吧。"
D.Strings[86136]="你的行动干扰不了我们的研究！这股力量很快就将属于我们！"
D.Strings[86137]="很高兴能再次和你并肩作战。"
D.Strings[86138]="狩猎不会结束……"
D.Strings[86139]="卫兵！挡住他们！"
D.Strings[86140]="我要活活烧死你！"
D.Strings[86141]="啊，魔法回廊……这一带的地下全是这种大厅……包括城里。"
D.Strings[86142]="现在，我们至少知道，枯法者会躲开这个地方。"
D.Strings[86143]="而且王宫里的人也不会想到来这里搜捕我们。"
D.Strings[86144]="我听到的骚动是怎么回事？传送门怎么关闭了？"
D.Strings[86145]="看来我们引起他的注意了。"
D.Strings[86146]="我们得快一点了。如果有可能的话，我还是想避免正面冲突。"
D.Strings[86147]="噢，你可真没劲。"
D.Strings[86148]="让我们找到这个档案室，然后离开这里，否则就迟了。"
D.Strings[86149]="不！我现在明白了……背……叛……"
D.Strings[86150]="最终，你们都将臣服于军团……"
D.Strings[86151]="又一只，马鲁尔！你已经落后啦！"
D.Strings[86152]="仆从们——进攻！"
D.Strings[86153]="又打到一只！你根本不是我的对手！"
D.Strings[86154]="你在浪费时间，马鲁尔！你的准头永远也比不上我！"
D.Strings[86155]="档案室就在前面！泽尔托斯就在前面，一心想把贾格诺斯的知识都占为己有。好好拷问他，你就能找到你的神器了！"
D.Strings[86156]="就算你这次阻止了我们，但我们是永远不会罢休的。"
D.Strings[86157]="哪个凡人竟敢接近档案室？这种无礼的举动决不可容忍！"
D.Strings[86158]="我看他是不打算合作了。让我们看看等他失去力量之后，还能有多少勇气吧。"
D.Strings[86159]="他太强大了！"
D.Strings[86160]="蠢货！你们要为自己的罪行受到惩罚！"
D.Strings[86161]="其他人已经标记了该目标。"
D.Strings[86162]="他被削弱了！快，在他恢复过来之前放逐他！"
D.Strings[86163]="这不可能！快放了我！"
D.Strings[86164]="我们会考虑的，恶魔。但首先，关于贾格诺斯在寻找的这些神器，你有什么可以告诉我们的吗？"
D.Strings[86165]="既然如此，我把你放逐到黑暗虚空怎么样？你可以在那里欣赏一辈子的虚无。"
D.Strings[86166]="你不能这么做！"
D.Strings[86167]="她会的。"
D.Strings[86168]="好吧。如果你们真的想打败贾格诺斯，只有一件神器能符合你们的要求。"
D.Strings[86169]="在卡拉赞城堡的地底深处，藏着致命之镰乌萨勒斯，逆风收割者。"
D.Strings[86170]="在对强大遗物的不断研究中，黑暗骑士将乌萨勒斯从它原本的所在地抢了出来，将它藏在了自己的军械库里。"
D.Strings[86171]="确实如此，我的宠物。确实如此……"
D.Strings[86172]="我知道的都说了。快解开我的束缚！"
D.Strings[86173]="唔，我不记得答应过放你走。"
D.Strings[86174]="傲慢的蛆虫！我要杀了你们！"
D.Strings[86175]="怎么回事？这些傲慢的凡人干扰了我的传送门，还侵入了我的档案室？我要像碾碎那个废物侏儒一样碾碎你们。"
D.Strings[86176]="我们在月神殿见。"
D.Strings[86177]="要想活命的话就赶紧杀了我们吧，贾格诺斯。现在，为泽里法克斯的死付出代价吧！Band'or shorel'aran！"
D.Strings[86178]="辛菲儿！泽宁！"
D.Strings[86179]="他们没法独自面对他。来吧，术士！"
D.Strings[86180]="不！没有武器，好朋友是对付不了贾格诺斯的！好朋友一定会被打败的！"
D.Strings[86181]="可我们不能丢下他们！"
D.Strings[86182]="卡里杜斯去帮好朋友找到武器。然后我们就带着力量回来打败贾格诺斯。我们得快一点！"
D.Strings[86183]="那就去吧，术士，可我不能抛弃议会。但愿我们能活到你回来的那一刻。"
D.Strings[86184]="对，对！使用传送门！快，好朋友！"
D.Strings[86185]="麦克赛尔！主人最讨厌懒汉……你人呢？！"
D.Strings[86186]="卡萨鲁斯！解决这些入侵者！"
D.Strings[86187]="我觉得就算是赫米特亲自来，也不会比你教得更好了。"
D.Strings[86188]="不！你们……你们杀了他！"
D.Strings[86189]="用你们的鲜血染红城堡！"
D.Strings[86190]="纳鲁在上，我又打偏了！"
D.Strings[86191]="别再吹牛了，艾米丽！"
D.Strings[86192]="我打中一个！我的“烂枪法”如何？"
D.Strings[86193]="我们在破碎群岛的失败简直就是一场灾难。联盟和部落的残余部队还在自相残杀。$b$b$C，像你这样的英雄或许就是我们最后的希望了。坚强点，不要放弃。"
D.Strings[86194]="只要燃烧军团还没有打垮我们的意志，他们就休想胜利。"
D.Strings[86195]="在我脚下颤栗吧。"
D.Strings[86196]="别费劲逃跑了，跳蚤……"
D.Strings[86197]="消灭垃圾。"
D.Strings[86198]="干掉了一个。"
D.Strings[86199]="但是……我不可能……输……"
D.Strings[86200]="库塔洛斯……他们去你那边了。"
D.Strings[86201]="没事。我们将一起打败他们，拉图修斯。"
D.Strings[86202]="恶魔，你们休想占据这个世界！"
D.Strings[86203]="休想占领这世界！"
D.Strings[86204]="烧死你！"
D.Strings[86205]="够了！我受够了。"
D.Strings[86206]="拉文凯斯，你这草包。一万年了都没有长进。"
D.Strings[86207]="当唐德开始散播死亡之翼降临的消息，我的家人不愿意追随他。我的心告诉我应该留在他们身边，可我的躯壳却……\n\n我想活下去，$c。这没什么好羞耻的。"
D.Strings[86208]="该你们了。"
D.Strings[86209]="现在，睡吧……"
D.Strings[86210]="你的皮肤在颤栗……"
D.Strings[86211]="我们是军团！"
D.Strings[86212]="你们不明白自己要面对什么，凡人……"
D.Strings[86213]="我怎么了？这……不是……"
D.Strings[86214]="我的先祖……伊莉萨娜！不，原谅我……"
D.Strings[86215]="英雄们！你们必须击败他！"
D.Strings[86216]="你以为这些没用的凡人能反抗军团？"
D.Strings[86217]="为什么……为什么还要无谓挣扎呢？你们输定了——这是迟早的事……"
D.Strings[86218]="先祖的英灵！过来！帮帮这些勇士！"
D.Strings[86219]="对——我们会蛰伏，但不会投降。"
D.Strings[86220]="我……会……回来的！"
D.Strings[86221]="我等着你。只要你敢来，我们就会击败你，保护我们的世界。"
D.Strings[86222]="谢谢你们，英雄。我们终于看清了真相。"
D.Strings[86223]="拉文凯斯家族为守护这片土地牺牲了一切。现在我们终于能安息了，因为我们知道，还有活着的英雄在守护这个世界。"
D.Strings[86224]="祝你好运，$n。我在火山里等你。"
D.Strings[86225]="我也去冰冠堡垒找过烈焰之击。巫妖王给了我这把剑……不仅如此，他还给我了人生目标！"
D.Strings[86226]="看来你需要一点帮助。"
D.Strings[86227]="我们太分散了。重新集合！"
D.Strings[86228]="目前一切顺利，$n。我们马上就能拿下山脊了。"
D.Strings[86229]="你做好插下旗帜的准备了吗？"
D.Strings[86230]="等你杀了那只恶魔，我要拿回我的战刃。"
D.Strings[86231]="等占领了这里，你得用那座巨型军团传送门召唤我们的部队。"
D.Strings[86232]="我现在过不去，但可以投出战刃打击那只恶魔。"
D.Strings[86233]="使用奔波尔霸的蛋与他完成心灵融合，指引他的行动。"
D.Strings[86234]="你把我的族人从邪能图腾以及他们的燃烧军团盟友手中救了出来。现在，我们愿意帮助你和你的高岭部族盟友对抗达古尔以及他的愚蠢追随者。"
D.Strings[86235]="这里让我精神紧张。趁他们还没有改变主意，我们最好赶快完成仪式。"
D.Strings[86236]="我，纳瓦罗格，黯石卓格巴尔的领袖，在此宣誓与高岭部族结盟。"
D.Strings[86237]="看来他们想要包围港口！拖住他们，等待援军抵达！"
D.Strings[86238]="拦住他们，等待支援！"
D.Strings[86239]="这片海滩决不能失守！空中支援马上就到了！"
D.Strings[86240]="如果我们失去这片土地，他们就能直接围攻锈水港了！去他们的！我们绝不放弃锈水港！"
D.Strings[86241]="你的枪法是谁教的？鱼人吗？"
D.Strings[86242]="你的骄傲迟早会毁了你！"
D.Strings[86243]="<这个维库人似乎已经失去了意识。>"
D.Strings[86244]="尝试叫醒这个维库人。"
D.Strings[86245]="用力踢这个维库人。"
D.Strings[86246]="用棍子不断捅这个维库人。"
D.Strings[86247]="<弗里克自言自语着。>$B$B别闹了，阿斯塔。让我睡一会儿。"
D.Strings[86248]="<弗里克自言自语着。>$B$B别这么用力，阿斯塔！"
D.Strings[86249]="<弗里克自言自语着。>$B$B阿斯塔！打仗了吗？"
D.Strings[86250]="请问能给我一片你的鳞片吗？"
D.Strings[86251]="我是来对付伊利达雷的，可要是我把你的尸体也一起带回去，阿佐兰一定会很满意的！"
D.Strings[86252]="抱歉，$n，我不能就这么把鳞片给你。在这个乱世，我们必须保存每一分力量。"
D.Strings[86253]="真是个奇怪的要求，$n，但我相信你一定会把它用于正途的。给，拿着，但愿它能帮助你对抗燃烧军团。"
D.Strings[86254]="吱吱！好烫！我要活剥了你的皮！"
D.Strings[86255]="我要是能多帮塞纳苟斯一点忙就好了。"
D.Strings[86256]="你在这种时候跑来这里提这种要求？让我一个人静静，$c。"
D.Strings[86257]="你要它是有大用处的吧？虽然我帮不了自己的族人，但我想我至少能帮你一个忙。"
D.Strings[86258]="你检查过山顶的仓库了吗？我们正在努力囤积一切能够找到的物资。当然，我是指能够长久存放的物资，比如香蕉、牛奶……之类的东西。\n\n我想我们干得很不错！"
D.Strings[86259]="这些该死的堕夜精灵真是凶残。你是来帮我们对付他们的吗？"
D.Strings[86260]="我的鳞片？堕夜精灵要抢我们的精华，现在你又来要我的鳞片？！快滚开，不然我就把你跟他们一起吞了！"
D.Strings[86261]="你的这个要求太为难我了，$n。给，拿着吧，但愿它能让这场战争早日结束。"
D.Strings[86262]="胡恩用雄鹰之矛将提克迪奥斯逐出了这个世界。"
D.Strings[86263]="上古之战后，他回到了家乡，那里已经因他而改名。"
D.Strings[86264]="唐德很会鼓舞士气。他意志坚定，是个好领袖，也会关心别人。他在预见到死亡之翼归来后没有独自逃生，而是将他窥视到的未来告诉了我们，并号召想要活下去的人跟他走。 \n\n我一生中认识过许多萨满，但唐德……可以说，他是最懂得驾驭闪电的那一个。"
D.Strings[86265]="你的动作让一个冰霜屏障破开了！"
D.Strings[86266]="毁灭之锤就掉在下面。抓紧了！这段航程总是让我肠胃不适！"
D.Strings[86267]="你想找死的话，就尽管过来好了，纳迦！"
D.Strings[86268]="我不认识你，可你最好在被巨人抓住以前离开这里。"
D.Strings[86269]="第5天：结界有效阻挡了枯法者，可对外面小动物和野兽的吼叫声却无能为力。这儿的夜晚太吵了。"
D.Strings[86270]="我努力睡了一会儿。明天，我要开始找研究对象了。"
D.Strings[86271]="我们会永远铭记你为我们的人民作出的巨大贡献……直到我们想不起来为止。"
D.Strings[86272]="你好啊，伙计。$b$b如果你受够了木头的臭气和空无一物的空气，那就跟我，啸石者博格罗格谈谈吧。$b$b我可以用岩石与大地秘术将你送去黯石岩洞。"
D.Strings[86273]="我要去黯石岩洞。"
D.Strings[86274]="这可真是出人意料！我得去警告其他人。"
D.Strings[86275]="我以头上的角发誓，我要杀光这些纳迦！"
D.Strings[86276]="谢谢！那血是我的还是你的？"
D.Strings[86277]="不惜一切代价保护港口！"
D.Strings[86278]="这些家伙别想占领这里。"
D.Strings[86279]="我不是纳迦，斯托卡弗！我是代表布兰多夫来的！"
D.Strings[86280]="幸好有你在。我们需要支援。"
D.Strings[86281]="那个小崽子还活着？太好了！$B$B我跟你走，可你不准碰我的头盔。"
D.Strings[86282]="好了！这座传送门很稳定，应该能送你们去达拉然了。"
D.Strings[86283]="别再磨蹭了，堕落者。贾格诺斯渴望这些凡人的鲜血！"
D.Strings[86284]="如果我们能及时赶到那里，或许就能阻止他们前往达拉然！"
D.Strings[86285]="你们是跑不掉的！"
D.Strings[86286]="来吧，食尸鬼！吃掉入侵者的心脏！"
D.Strings[86287]="塞莉娅派我来救你。来，快穿上这套护甲。"
D.Strings[86288]="如果你愿意的话，就留在雷霆图腾吧，女人。我已经受够这些废物了。鲜血图腾才是我的归宿。"
D.Strings[86289]="离那座传送门远点儿，蛆虫！"
D.Strings[86290]="我能感觉到通道正在崩溃。我们就快成功了！"
D.Strings[86291]="他们短期内是别想再去达拉然了。"
D.Strings[86292]="这片土地不是你的私有物。"
D.Strings[86293]="这太合我的胃口了，$n！这个恶魔的力量归你了。"
D.Strings[86294]="跟我走，恶魔猎手。我能给予你们无穷的力量！"
D.Strings[86295]="勇气……是最强的武器……"
D.Strings[86296]="守望者想让我们彻底烂死在这儿。干嘛还要帮他们呢？"
D.Strings[86297]="发掘你内心的力量……"
D.Strings[86298]="你要相信……圣光……"
D.Strings[86299]="不……不！！蠢货……"
D.Strings[86300]="谁都别想逃过贾格诺斯的怒火！"
D.Strings[86301]="圣光中我们融为一体……"
D.Strings[86302]="保持……警惕……"
D.Strings[86303]="坚不可摧……"
D.Strings[86304]="我们……团结一致……"
D.Strings[86305]="希望……永存……"
D.Strings[86306]="我不会输的！来吧，我的宠物！来品尝生者的血肉！"
D.Strings[86307]="第9天：跟枯法者的沟通依然没有结果。我不能因此怀疑自己的能力，起码还是有进展的。"
D.Strings[86308]="第14天：那个新实验体，16号，很特别。他的法力精华沾了某种神秘力量。我给他起名叫泰林。"
D.Strings[86309]="你准备好之后就告诉我一声，$n。我已经等不及要离开这里了。"
D.Strings[86310]="我准备好了，塔尔达尼斯。我们走。"
D.Strings[86311]="你们的强大让我们都与荣有焉，勇士们。我恳请你们——为我们的事业而浴血战斗！我们绝不会倒在燃烧军团的脚下！"
D.Strings[86312]="鲜血与荣耀，勇士们！让他们看看你们的实力！同心协力，众志成城！"
D.Strings[86313]="第16天：重大突破！以泰林的精华为基础，我研究出了安抚枯法者的法术。有时还是有效的……"
D.Strings[86314]="第24天：醒来时，一个暗夜精灵把刀架在我脖子上。他问我对枯法者做了什么。我回答：“研究解药。”他哼了一声便跑了。"
D.Strings[86315]="辛菲儿和泽宁去攻击贾格诺斯！"
D.Strings[86316]="坚定决心，拿起武器！击退他们！"
D.Strings[86317]="第33天：魔力酒快喝完了。泰林进展良好。沙兰还是很固执。水晶越来越难找了。"
D.Strings[86318]="第50天：天空……变暗了。到处都是……恶魔。这种饥饿……无尽的饥饿……"
D.Strings[86319]="放走实验品……我没法再保护他们了……"
D.Strings[86320]="阿彻鲁斯的死亡骑士们，$n代表了我的意志。她的命令就是我的命令。"
D.Strings[86321]="我的小伙子们为了完成训练，必须从这座桥上跳下去。如果你敢从这里跳下去，就能从你的雄鹰背上跳下去！他们的成长速度远超我们的预料，很快就能成为优秀的战士。我们很高兴能回到雷霆图腾。\n\n如果你愿意的话，也可以试试。"
D.Strings[86322]="你好，萨满！我们在突袭大漩涡的战役后就跟其他人失散了。$b$b来吧，我们还有很多工作要做。风暴比克可以载你飞往深岩之洲。"
D.Strings[86323]="送我飞去深岩之洲，米尔拉！"
D.Strings[86324]="好了，$n，从现在起，我就是你的影子了。你可别害死我们。"
D.Strings[86325]="我们真不该听黑角的，应该趁早拿起锤子对抗燃烧军团和卓格巴尔。"
D.Strings[86326]="把事情告诉河湾难民。"
D.Strings[86327]="接下来的路我自己就能应付了，$n。感谢你的帮助。如果你再见到塞莉娅，告诉她我欠她一个人情。"
D.Strings[86328]="你很清楚，那锤子并不是武器。"
D.Strings[86329]="%s响应战斗的召唤，苏醒了过来。它伸出的枝桠咯吱作响，带起脚下的尘土飞扬。"
D.Strings[86330]="坐下"
D.Strings[86331]="梅拉连卓格巴尔都对付不了。怎么能指望她去对付燃烧军团？"
D.Strings[86332]="我们已经跟高岭部族决裂了。鲜血图腾得寻找新的盟友。"
D.Strings[86333]="不可能！我的仆从会撕碎你的！"
D.Strings[86334]="我听说鹰身人重创了天角部族。拉善已经将所有的部队都撤回去死守老家了。"
D.Strings[86335]="苹果树注意到了加尼尔，扔给你一只新鲜苹果！"
D.Strings[86336]="灰烬使者？！巴纳扎尔大人会取下你脑袋！"
D.Strings[86337]="|TINTERFACE\\ICONS\\trade_archaeology_naarucrystal.blp:20|t$n被囚禁在了|cFFF00000|Hspell:195791|h[隔离区]|h|r内！"
D.Strings[86338]="坚持住，伊利达雷！我们得把他困在大厅里！"
D.Strings[86339]="快，$n！启动房间周围的反制措施！"
D.Strings[86340]="灰烬使者……必须死……"
D.Strings[86341]="我们不可能一直坚持下去。必须控制住他！"
D.Strings[86342]="你想让我找什么？我有铲子！"
D.Strings[86343]="快去找亮晶晶！去挖死人的地盘。"
D.Strings[86344]="干得好！那个怪物被控制住了。我们去找其他人。"
D.Strings[86345]="|TInterface\\Icons\\ability_socererking_arcanewrath:20|t你成为了|cFFF00000|Hspell:196070|h[镇压协议]|h|r的目标！"
D.Strings[86346]="仅仅一击，河湾就被摧毁了。我们拿什么来抵抗这样的力量？"
D.Strings[86347]="我会成为……灰烬使者。他们说麦格尼国王连续花了三天时间才铸造出那把剑。"
D.Strings[86348]="把洞里最大的那只蜥蜴带回来给我！"
D.Strings[86349]="你要杀人吗？我的凿斧最锋利了！"
D.Strings[86350]="这不是大领主吗？我认为哪怕是最坚强的人，也该花点时间时不时反省一下。我最喜欢这么做了。"
D.Strings[86351]="陪我坐一会儿吧，好吗？"
D.Strings[86352]="灰烬使者真是一把奇迹之剑，不是吗？我还记得许多年前在铁炉堡铸造它时的情景——它是我最好的作品。"
D.Strings[86353]="如果你不介意听一个老矮人唠叨的话，我想跟你分享一下我从年轻时就一直信奉的信条。"
D.Strings[86354]="我们都是从同一片土地和岩石中诞生的，无论是联盟还是部落，矮人还是侏儒——作为领袖，你应该搁置分歧，将你的人民团结起来对抗燃烧军团。艾泽拉斯就靠你们了。"
D.Strings[86355]="我会让你单独呆一会儿，思考一下未来的路。"
D.Strings[86356]="我来帮你，英雄！我拖住莉安达。你集中力量消灭她的怪物！"
D.Strings[86357]="你想让我做什么？去掉多余的毛发？准备蜡油浴？还是检查耳朵里的蜡？"
D.Strings[86358]="做大蜡烛！好多蜡！"
D.Strings[86359]="如果你有兴趣的话，就跟我坐坐吧——一会儿就好。"
D.Strings[86360]="提里奥是我的手足兄弟。我们很久之前曾经救过彼此的命。他是个好人……一个可敬的人。"
D.Strings[86361]="他对你的评价一直很高——根据我从别人那里听来的消息，他没有信错人。"
D.Strings[86362]="我见过许多领袖带着他们的人民走上不归路。提里奥总是说圣光会指引他和他的人民——但愿它也会带领着你成为一个伟大的领袖。"
D.Strings[86363]="艾萨斯！你怎么敢？你忘了我是谁吗？"
D.Strings[86364]="等他们来了，我也准备好了。"
D.Strings[86365]="出去小心点。如果你需要什么东西，知道该去哪儿找我。"
D.Strings[86366]="我记得过去的你。可如今站在我眼前的，不过是一具行尸走肉罢了！"
D.Strings[86367]="抱歉，但现在还不到时候。"
D.Strings[86368]="我来采矿！你别拿矿镐！你想去哪儿挖石头？想要金属吗？镐头有点钝了。"
D.Strings[86369]="挖石头，找亮晶晶！越亮越好。"
D.Strings[86370]="这个世界必将崩塌！我们将遮蔽你们的天空，碾碎你们的军队。来吧，废物们！死在我的威能之下吧！"
D.Strings[86371]="她在试图反制我的法术！我挡不住她多久。快！"
D.Strings[86372]="燃烧军团的阴谋一定会破产的。"
D.Strings[86373]="这个地方的入口非常隐秘，只有那些死亡骑士自己才知道。"
D.Strings[86374]="我们对这把古老的武器所知不多，只知道是它的力量导致了那么多人在逆风小径丧生。"
D.Strings[86375]="干得好，$n。我们救了许多优秀的士兵，可我们还没有为所有死难的将士复仇。"
D.Strings[86376]="一位斥候刚才通知我说，东边有一个恶魔狱卒，至少有十个我们的士兵正在他手下受苦。"
D.Strings[86377]="$n，你去东边把剩下的所有幸存者都救出来。我和莱诺尔来带领士兵们撤回西边。"
D.Strings[86378]="我在墓地里找到了亮晶晶的金币！好多，好亮。我该拿他们怎么办？"
D.Strings[86379]="你拿一块，剩下的归我。"
D.Strings[86380]="我在洞里发现了最大的蜥蜴！它现在已经死了！我的奖赏呢？"
D.Strings[86381]="你真是我见过的最利落的杀人机器！要给你最好的奖赏……"
D.Strings[86382]="在痛苦的生命终结后，我才看清真相！那时，我才明白这个计划的伟大！"
D.Strings[86383]="这把剑是我的，这是主人的意志……是血脉的传承！和我作对的人都得死！"
D.Strings[86384]="蜡烛已经准备好了！只要有魔法火把，蜡烛大王就能做出最棒的蜡烛了！"
D.Strings[86385]="我想我们刚好有合用的火把……"
D.Strings[86386]="使用神器"
D.Strings[86387]="你完全打消了我的疑虑！你确实配得上这把剑！带着它离开吧，英雄。生者不应该在我的寒冰牢笼中逗留。"
D.Strings[86388]="既然你这么想要我的剑，那就来尝尝吧！"
D.Strings[86389]="真……冷……"
D.Strings[86390]="为蛛后报仇！"
D.Strings[86391]="一定要保护蛛卵。"
D.Strings[86392]="不……泰兰娜死了！"
D.Strings[86393]="你会成为一顿大餐的。"
D.Strings[86394]="你居然敢来这儿，那你死定了。"
D.Strings[86395]="而这是为了什么呢？"
D.Strings[86396]="这是一个安全地研究猎物的诡计。"
D.Strings[86397]="我又得到了什么？来自我“姐妹”的永恒痛苦。"
D.Strings[86398]="当你站在那里，沉醉于燃烧军团的力量时，你还能这么说吗？"
D.Strings[86399]="我要杀了你和你的同谋，然后实现我导师的梦想。"
D.Strings[86400]="你还没意识到自己是在盲人摸象！烈焰之击落在你手中完全是浪费！"
D.Strings[86401]="只要我还有一口气在，这些恶魔就别想抢走我们的土地！"
D.Strings[86402]="废物……那个可悲的碎片不动了？我保证，它死得绝对不痛快。"
D.Strings[86403]="小心点，$n！我可不想看到你这么好的$c受伤！"
D.Strings[86404]="你击败了最差劲的一批战士……没关系，等魔血彻底融入血脉，就连你的宝贝神器也别想伤害我们了。"
D.Strings[86405]="愚蠢的凡人！现在想逃可太迟了！"
D.Strings[86406]="等我们成功之后，会有许多庆祝活动在等着我们的。为了白银之手！"
D.Strings[86407]="不要害怕，老乡。奇遇降临了！"
D.Strings[86408]="衷心地祝福你，我的大领主。如果你有需要，我就在温馨舒适的闪金镇旅店里等着你。"
D.Strings[86409]="天空看上去很阴沉。出去的时候小心点！"
D.Strings[86410]="<大地在你脚下发出慑人的轰鸣声。或许你该带个萨满来安抚一下这片焦虑的土地？>"
D.Strings[86411]="这个逐日者家族的污点总算被抹掉了。干得好，英雄！"
D.Strings[86412]="在巫妖王下逐客令之前……我们快走吧。我得去向议会提出仲裁申请了。"
D.Strings[86413]="<这片饱受折磨的大地在你脚下发出慑人的轰鸣声。作为萨满，你可以举行一个仪式来召唤并安抚愤怒的大地之灵……但也要做好战斗的准备。>"
D.Strings[86414]="<举行大地仪式。>"
D.Strings[86415]="噢，看看我们抓到了什么样的野兽！"
D.Strings[86416]="攻击我的目标，小伙子们！"
D.Strings[86417]="在这儿要小心点。在事情了结之前，我可不想在这一带晃悠。"
D.Strings[86418]="眼下这个地方不宜久留。我会等安全了之后再回来。"
D.Strings[86419]="伙计们，伙计们——我们要保持冷静。虽然我们不愿意承认，可这些猎人帮我们保住了采石场。"
D.Strings[86420]="我知道共用营地很麻烦，可我们必须合作，否则就会失去一切！"
D.Strings[86421]="我向你们保证——等消灭了恶魔，他们就会离开的。"
D.Strings[86422]="他们越早滚蛋越好！这个营地连我们自己都只是勉强够住！"
D.Strings[86423]="要不是咳得起不了床了，我也会出去战斗的！"
D.Strings[86424]="我们是不会把自己的土地拱手让给恶魔的，绝不！"
D.Strings[86425]="要我说的话，我觉得这里的生面孔太多了。"
D.Strings[86426]="别再发牢骚了。我们需要的是战斗！"
D.Strings[86427]="我……我不记得发生什么事了。"
D.Strings[86428]="一路平安，$n。"
D.Strings[86429]="用我的制皮架和工作台来制作一些吧。你可以在我的工作台上找到制皮的方法。"
D.Strings[86430]="我希望你能留好这些材料，要想做出那些靴子的成品，你会需要它们的。"
D.Strings[86431]="阿佐兰必须死……"
D.Strings[86432]="我要拿你的肉去喂我的宠物！"
D.Strings[86433]="我的战刃已经渴望恶魔鲜血太久了……"
D.Strings[86434]="接受我的祝福，传承古老的智慧。"
D.Strings[86435]="打倒所有妄图毁灭这个世界的敌人。用正义的火焰烧死他们！"
D.Strings[86436]="别担心，我的孩子们。在即将到来的黑暗时代，还有我们与你们同在。"
D.Strings[86437]="让我的力量激励你们吧——一条战线都不要放松！"
D.Strings[86438]="勇于接受试炼的英雄们——我将暂时赋予你们造物的力量！"
D.Strings[86439]="我将庇佑所有敢于保卫艾泽拉斯的人。今天，你们绝不会倒下！"
D.Strings[86440]="梅拉，我的孩子，地底之王摧毁了河湾。"
D.Strings[86441]="谢谢，勇士。这里应该安全了。来吧，我们去见梅拉。"
D.Strings[86442]="绝不能让他们抵达城门！"
D.Strings[86443]="谢谢！你真是个强大的$c，不是吗？"
D.Strings[86444]="我们通常都会邀请客人进来坐坐并奉上一杯啤酒，可对于恶魔，我们只有利刃相送。"
D.Strings[86445]="今天我是不会死的！"
D.Strings[86446]="我之前从没见过这种情况！"
D.Strings[86447]="磨利你的刀剑吧，$n。这场战斗还没有结束。"
D.Strings[86448]="你是来为我们增加储备的吗？如果你手里有肉，请不要将它腌制。唐德说腌肉坏得更快。"
D.Strings[86449]="当然，你可能觉得我们的帽子很滑稽。但它能帮我们迅速适应灭世的洪水！"
D.Strings[86450]="我会保护大家不受任何海底怪兽的伤害！"
D.Strings[86451]="娜穆让我跟你谈谈有关骑甲的事。"
D.Strings[86452]="他们的行为太孩子气了。$B$B但我知道这是必然的。他们最好还是立刻解决他们间的分歧。"
D.Strings[86453]="这座险恶的魔像似乎是关闭的。它背后的一个按钮吸引了你的注意力。你打算按它吗？"
D.Strings[86454]="审判之池能让凯恩和奥图里斯想起过去……由伊利丹大人一手造成的过去。"
D.Strings[86455]="噢！对，你知道，很多冒险者都会来找我，抱怨说自己有时会被敌对生物从坐骑背上打下来。$b$b我告诉他们不要从一群野生动物中间跑过，但显然这“不是旅行的最快捷径”。$b$b于是我就想，如果我没法劝说他们走大路的话，那或许制造一个保护坐骑的装甲会更容易些。$b$b坐骑最需要保护的部位就是头、脖子和躯干。换句话说……就是把它们彻底包起来。"
D.Strings[86456]="我已经把所有的皮革都找来了。接下来怎么办？"
D.Strings[86457]="干得好，$n。这是骑甲各个部件的图样，以及最终骑甲成品的图样。祝你好运！"
D.Strings[86458]="谢谢你，萨满。要是没有你，这个世界恐怕就要陷入混乱了。"
D.Strings[86459]="我还以为自己死定了呢。谢谢你。"
D.Strings[86460]="我必须撤退了！"
D.Strings[86461]="你救了我的命，我是不会忘记这份恩情的。"
D.Strings[86462]="我们必须救出其他人！"
D.Strings[86463]="我的法术石……谁来用它……继续我的研究……"
D.Strings[86464]="你的伤口很多。"
D.Strings[86465]="坚持住，士兵。我们马上就能撤退了。"
D.Strings[86466]="圣钟事件造成的伤痕很深，艾萨斯。议会里的其他人可不像我这么宽容。"
D.Strings[86467]="你的主人呢，恶魔？他在哪儿？"
D.Strings[86468]="但自从燃烧军团降临之后，我自己也决定开始搜索这把剑的下落。我看到了一个幻象，莉安达手中握着这把武器。她周围的土地覆盖着冰雪，一座非常眼熟的堡垒耸立在她身后。"
D.Strings[86469]="冰冠堡垒。你觉得她在那里？"
D.Strings[86470]="是的。而且那座堡垒里所发生的一切无不体现着它主人的意志。我相信他也插手了这件事。"
D.Strings[86471]="终于自由了！我们来击败这魔鬼吧！"
D.Strings[86472]="看来你是铁了心了。很好，我这就走。$n，小心不要变成第二个伊利丹。"
D.Strings[86473]="你要相信叛徒？那我就没办法了。"
D.Strings[86474]="仁慈？军团焚毁了无数世界……你还想要仁慈？"
D.Strings[86475]="你不配这么干脆地死去。"
D.Strings[86476]="我会把你的请求转告议会的……但我不保证你能得到想要的结果。"
D.Strings[86477]="让我帮你一把吧。"
D.Strings[86478]="秘法师，感谢你的帮助。"
D.Strings[86479]="<灰舌秘法师躺在这里，由于为军团传送门提供能量而晕了过去。>"
D.Strings[86480]="蛛后肯定在这个传送门上做了手脚。靠莫尔葛已经没法没法打开它了。\n\n但是，恶魔猎手可以拼尽全力去开启它。你得做出选择了，$n……\n\n……我们谁来？"
D.Strings[86481]="我想让你用我的力量来为传送门供能。"
D.Strings[86482]="这是……我的荣幸。"
D.Strings[86483]="<瑟维斯付出的生命的代价，让你启动了军团传送门，并召唤出破坏魔大军。>\n\n<不要让他白白牺牲。>"
D.Strings[86484]="你不会白白牺牲的！"
D.Strings[86485]="我们做得很好。这里献祭了大量灵魂。激活器有能量了。"
D.Strings[86486]="我到前面去找阿莱利。"
D.Strings[86487]="$n，快！你没有多少时间了。"
D.Strings[86488]="瑟维斯低头看了看秘法师。"
D.Strings[86489]="这个灰舌秘法师愿意帮助你。"
D.Strings[86490]="他很勇敢。"
D.Strings[86491]="我在最后一座传送门那里等你。"
D.Strings[86492]="$n，我们遇到大麻烦了。"
D.Strings[86493]="死到临头的是你，恶魔！"
D.Strings[86494]="我早就在盼着这一天了。"
D.Strings[86495]="为了伊利丹大人！为了伊利达雷！"
D.Strings[86496]="让我们决一死战吧，$n。"
D.Strings[86497]="再次感谢你让我活了下来。我相信你很清楚，我很乐意为执行伊利丹大人的计划而牺牲一切。我们必须不惜一切代价摧毁燃烧军团。\n\n我欠你一条命，$n。\n\n现在，你一定要告诉我你是怎么活过来的。我亲手杀了你！看来有关你的传言是真的……你几乎和伊利丹一样强大。"
D.Strings[86498]="先是穴居人，现在又是恶魔了？没关系。巡山人会战斗到最后一刻的！"
D.Strings[86499]="等战斗结束后，我请大家吃野猪肋排和麦芽啤酒。"
D.Strings[86500]="拿起武器，$n。现在可不是闲逛的时候。如果有需要的话，就躲到里面去吧。"
D.Strings[86501]="抱歉，现在不是时候，$c。"
D.Strings[86502]="我很抱歉，$n，可你来的不是时候。"
D.Strings[86503]="隐蔽！为了保证安全，其他人都进去了！"
D.Strings[86504]="我从没见过这么凶猛的攻势！"
D.Strings[86505]="已经有这么多人受伤了。你愿意帮忙结束这一切吗，$n？"
D.Strings[86506]="看天上……你见过类似的情况吗？"
D.Strings[86507]="小心点，$n。我刚才还看见一个地狱火从天而降呢！"
D.Strings[86508]="你看见了吗，$n？那些恶魔……我刚看到一个店主尖叫着跑掉了！这真是太疯狂了！"
D.Strings[86509]="<这个维库人浑身浴血，几乎断气了。>"
D.Strings[86510]="森林之神塞纳留斯。$b$b我从没见过他这个样子。保持警惕，朋友。我们脆弱的世界已经陷入了深重的危机之中。"
D.Strings[86511]="飞行器机坪遭到攻击！到处都是恶魔。我派出了最好的飞行编队去对付他们。$B$B下面的加把劲儿！你们是我们唯一的希望了！"
D.Strings[86512]="今天不行，朋友。我得帮我的小伙子们强化我们的产品。"
D.Strings[86513]="我欠你一个大人情，$n。再次感谢你。"
D.Strings[86514]="送我去铁炉堡飞行器机坪。"
D.Strings[86515]="让我们继续打猎吧！"
D.Strings[86516]="我只想努力保证每个人都吃饱喝足，直到战争结束。"
D.Strings[86517]="等那些恶魔看见你的时候就晚了。"
D.Strings[86518]="大家冷静下来。我们已经把这一带最好的战士都派出去战斗了。"
D.Strings[86519]="尽量放松点。让我们一起来面对这场战争。"
D.Strings[86520]="激动没有任何帮助。我们一定要想办法冷静下来。"
D.Strings[86521]="当我们躲在地下的时候，这个世界正在四分五裂！"
D.Strings[86522]="你看见那些家伙了吗？我们怎么可能防得住那种东西？"
D.Strings[86523]="你想让我们怎么冷静？我们被袭击了！"
D.Strings[86524]="只要能杀掉马凯斯，布兰多夫愿意牺牲他自己。"
D.Strings[86525]="真讽刺，不是吗？"
D.Strings[86526]="我从来没被打得这么惨过。"
D.Strings[86527]="这肯定要留疤了。"
D.Strings[86528]="我是个厨子，不是急救训练师。"
D.Strings[86529]="在我看来还行，但我还要再强调一遍，我整天都是和生肉打交道的。就我所知，这可能很糟糕。"
D.Strings[86530]="至少你还活着。"
D.Strings[86531]="好冷！冷不好！讨厌讨厌讨厌。"
D.Strings[86532]="尊敬的议会大法师们，请允许我介绍，$n，烈焰之击的持有者。"
D.Strings[86533]="我准备好协助你了，玛法里奥。"
D.Strings[86534]="你们别想逃脱正义的制裁！"
D.Strings[86535]="你们休想亵渎这座堡垒！"
D.Strings[86536]="让你的灵魂尝尝我们所受的痛苦！"
D.Strings[86537]="火好，冷不好！冷最坏了。"
D.Strings[86538]="把你的名字刻在远古列王圣契上，我们就能开始仪式了。"
D.Strings[86539]="布兰多夫！你这机灵鬼！我还以为我要烂死在这个笼子里了。这个$r是谁？"
D.Strings[86540]="你踢我干嘛，你这个狼崽子？"
D.Strings[86541]="布兰多夫？这么说，那个小崽子嗅出了我留在这座洞里的气味，嗯？"
D.Strings[86542]="你这个小崽子！看来你也涨能耐了嘛。"
D.Strings[86543]="娜穆跟我说你有一些关于宠物玩具的新点子？"
D.Strings[86544]="卑微的低等生物。我要把你碾成沙砾！"
D.Strings[86545]="潮汐主母将终结你们可悲的生命。"
D.Strings[86546]="皮革宠物玩具？让我们来看看……一根新缰绳应该不错。还有，宠物们肯定会喜欢一张柔软舒适的床。$b$b我一直梦想做一个圈让他们跳。最好用能够点火的材料来做。这一定会很有趣的！"
D.Strings[86547]="我自由了！一个黑暗的新千年开始了！"
D.Strings[86548]="有意思，你和我一样，有着不朽的恶魔灵魂。"
D.Strings[86549]="你不会真正死亡，你的灵魂会回到扭曲虚空。你将一直在那里徘徊，直到找到合适的寄宿身体。"
D.Strings[86550]="现在，趁还有时间，回你的身体里去吧，把钥石给我带来！"
D.Strings[86551]="你就是靠这么弱的力量来到这里的吗，$n？"
D.Strings[86552]="肮脏的把戏，召唤帮手……你不配统治这座山脉！"
D.Strings[86553]="纳瓦罗格别想靠他的玩具来对付我。"
D.Strings[86554]="以萨吉塔的名义，去死吧！"
D.Strings[86555]="贾德维克必须死！"
D.Strings[86556]="如各位所见，我们的前同僚遵守诺言，帮助了我们。希望你们在考虑他重返达拉然的请求时，能将这一点纳入考量。"
D.Strings[86557]="如果他想独吞这把剑的话，只需要将它交给手下的夺日者就行了。"
D.Strings[86558]="艾萨斯的举动似乎很真诚。我觉得我们应该同意他的请求。"
D.Strings[86559]="我们怎么知道他不会再次背叛肯瑞托？"
D.Strings[86560]="你真的来了，伊墨瑞尔就说你会来的。"
D.Strings[86561]="很好，现在有两人同意艾萨斯回来了。安斯雷姆，你怎么想？"
D.Strings[86562]="我准备好前往蔑潮港了。"
D.Strings[86563]="很高兴见到你。在抵达最终的目的地，风暴峡湾之前，我们得先在至高岭停留一下。"
D.Strings[86564]="好吧，我相信议会的智慧。我赞成。"
D.Strings[86565]="其他人怎么说？"
D.Strings[86566]="我当然赞成。"
D.Strings[86567]="那就这么定了。艾萨斯·夺日者，你可以走了。不要滥用这个机会。"
D.Strings[86568]="你一定要把她完整地带回来！"
D.Strings[86569]="好好照顾它！"
D.Strings[86570]="去搞定他们吧！"
D.Strings[86571]="在外头小心点！"
D.Strings[86572]="让他们看看谁才是老大！"
D.Strings[86573]="全速前进吧！"
D.Strings[86574]="我是不会被关住的！"
D.Strings[86575]="你们的力量阻止不了我！"
D.Strings[86576]="嘘……他们会听见的。"
D.Strings[86577]="他们肯定会大吃一惊。"
D.Strings[86578]="阴影中更加安全，$n。"
D.Strings[86579]="你在这里很安全，只要你别像其他$c那样招摇过市。"
D.Strings[86580]="等他们来了，我们也准备好了。"
D.Strings[86581]="有看见恶魔潜伏在这附近吗？"
D.Strings[86582]="你别想再把我关回那个水晶里去！"
D.Strings[86583]="阿佐兰大人……我能为你做点什么呢？"
D.Strings[86584]="看来我们有客人了，沃格斯……去解决他们。"
D.Strings[86585]="我摧毁那座恶心的浮空城的计划绝对不容有失！"
D.Strings[86586]="如你所愿，主人！"
D.Strings[86587]="别让我失望，沃格斯……你知道那些让我失望的人会是什么下场。"
D.Strings[86588]="这比想象中轻松多了，大部分克瓦迪尔肯定都出去抢劫了。"
D.Strings[86589]="你们两个有什么计划吗？"
D.Strings[86590]="乌霍！你找到那个怪物了吗？"
D.Strings[86591]="还没有，但它就是我们要找的敌人。这里的克瓦迪尔提到了在沼泽深处筑巢的巨猫。他们建造了一个魔法结界来困住它。"
D.Strings[86592]="我们必须想办法通过结界！乌霍，你和我去检查结界，$n去搜索港口。"
D.Strings[86593]="快上坐骑，$n。燃烧军团动真格的了。他们派出了灭绝者。"
D.Strings[86594]="大部分人都勉强冲上来了。但在这里，我们还是会遭到轰炸。"
D.Strings[86595]="你们瞎了吗？干掉他们！"
D.Strings[86596]="他们以为自己随随便便就能攻进来，我们也不会反抗？我和我的机械陆行鸟都看着呢！"
D.Strings[86597]="但愿下一个地狱火掉下来时不要再砸到陆行鸟了。我们的补给已经不够了！"
D.Strings[86598]="今天要再让我看到一头陆行鸟被摧毁，我就……我就……相信我——那样你们就惨了！"
D.Strings[86599]="这些够我修上好几年了！"
D.Strings[86600]="他们以为自己是谁啊，跑来摧毁我们的财产，攻击无辜的人——需要有人好好教训一下那些恶魔……"
D.Strings[86601]="我的陆行鸟被摧毁了，我的头发也被烧焦了——如果再让我看到一只地狱火，我就要踢断它的腿……如果它有腿的话。要是没有的话，我就扔扳手。"
D.Strings[86602]="但愿这场战争能尽快结束。我还有一大堆工作要做呢。"
D.Strings[86603]="鱼进桶了！你们能做出一锅美味的烂鱼汤了！"
D.Strings[86604]="好吃、好吃的矮人……你们的城门支撑不了多久！"
D.Strings[86605]="小矮人太蠢了。你们的门栓和石头保护不了你们。"
D.Strings[86606]="<这个元素生物对你做了个乞求的姿势，又指了指它身旁饥饿的鲨鱼。你听不懂它所说的语言。或许你该找个萨满来帮你翻译一下？>"
D.Strings[86607]="<这个元素生物看了一眼你脚下的水面。>$b$b哦，你好啊，萨满！你可真受元素的眷顾。$b$b来吧，跟我一起在水上走走，进行一次平等的对话。我需要你的帮助。$b$b<元素生物警惕地看了看它身旁的鲨鱼。>"
D.Strings[86608]="<上古海灵热情而尊敬地跟你交谈起来。>$b$b萨满，这片海域发生的骚乱消耗了我的生命精华，它已经流失到了这个海湾的各个角落。它让这些小鲨鱼都发了疯。$b$b使用水上行走穿过海浪，为我收集10滴活水吧。小心那些鲨鱼——要是被它们拖下水的话，你收集到的活水就会流失。"
D.Strings[86609]="<上古海灵对你深深鞠躬。>$b$b谢谢你，萨满。你真是艾泽拉斯所有元素的福音。"
D.Strings[86610]="|TInterface\\Icons\\Spell_Shadow_UnholyFrenzy:20|t督军帕杰什被|cFFFF0000|Hspell:197064|h[激怒]|h|r了！"
D.Strings[86611]="你的地图上已标出了一处宝藏！"
D.Strings[86612]="我会坚持我们的传统，直到有能够替代我的人出现。"
D.Strings[86613]="请强化我的视力吧，我会找回你的精华。"
D.Strings[86614]="给它们装满弹药！除非我死了，否则他们别想过去！"
D.Strings[86615]="我或许是被诅咒了，但我还能把生前的知识传授给别人。"
D.Strings[86616]="装弹装得手都酸了？很好！继续努力。今天不是我们死就是他们亡！"
D.Strings[86617]="继续开火！给我狠狠地打！"
D.Strings[86618]="都别停，除非是你动不了或者是枪出毛病了——那你们也可以用拳头！"
D.Strings[86619]="这间房太差劲了。等旅店老板回来，我一定要跟他谈谈……"
D.Strings[86620]="他是这么跟我说的：“恶魔已经把热裤提上了头号议程！他们都冒烟了！”"
D.Strings[86621]="<斯塔利斯嘟囔着别人听不懂的语言。>"
D.Strings[86622]="引线就快烧完了！"
D.Strings[86623]="迫击炮出击！"
D.Strings[86624]="快去海上收集活水吧！我已经赋予了你魔法视觉，帮助你更好地发现周围的危险。$b$b等你收集到10滴活水再回来找我吧……"
D.Strings[86625]="大家伙来了！堵住你们的耳朵！"
D.Strings[86626]="引线快烧到头了！"
D.Strings[86627]="上一枚炮弹还没落地就炸开了——再来！"
D.Strings[86628]="“我们可以重新得到圣井的惠泽。”"
D.Strings[86629]="谢谢，萨满！我感觉自己的力量又回来了。带上被我祝福过的武器，保卫艾泽拉斯元素的尊严吧！"
D.Strings[86630]="<这个夜之子狐疑地打量着你。>$b$b如果你是来找麻烦的，那你就是个蠢货。快走开，否则我要叫巡逻队了。苏拉玛的力量将让你死无葬身之地！"
D.Strings[86631]="看来我们打疼他们了！只剩那个大家伙了，然后我们就能回——"
D.Strings[86632]="什么……那是什么？"
D.Strings[86633]="小子们，丫头们——都给我站稳了——我们有麻烦了！"
D.Strings[86634]="有东西在隆隆作响，而且肯定不是我的肚子在叫！"
D.Strings[86635]="%s的手慢吞吞地摩挲着肚子。"
D.Strings[86636]="你竟敢干扰燃烧军团的传送？"
D.Strings[86637]="你的地图上已标出了一座能量枯竭的军团传送门！"
D.Strings[86638]="我就知道你们靠得住，勇士们！有空记得来找我。我们的营地里还有一些补给可以给你。"
D.Strings[86639]="你们真是一群好战士，不是吗？现在我们只需要再做一下扫尾工作就行了！"
D.Strings[86640]="浅湾里有东西在动。可能就是那头野兽！激活结界石！"
D.Strings[86641]="你们可真能打！我们都不知道该怎么感谢你们了。最后扫个尾，然后来老克里姆这里领些特别的补给品吧！"
D.Strings[86642]="嗯，别对我指手画脚，老家伙！"
D.Strings[86643]="<这个绝望的土元素疯狂地对你比划着，身上的石块和石子飞得到处都是。它说着一种低沉的、隆隆作响的语言，你完全听不懂。或许你该带个萨满来调查一下？>"
D.Strings[86644]="<这个上古土元素非常痛苦。它对你说道：>$b$b求求你，萨满！他们……想让我沉寂下来……$b$b愤怒的万灵……你看不见他们吗？$b$b我在被……碾碎……"
D.Strings[86645]="把折磨你的人告诉我，我来帮你！"
D.Strings[86646]="你已经被我控制了，恶魔。服从我的命令吧。"
D.Strings[86647]="如果你想买的话，我这儿有一些锁甲图样，$n！"
D.Strings[86648]="你的灵魂将属于我的主人！"
D.Strings[86649]="你站错队了，$r。"
D.Strings[86650]="这个世界注定要毁灭！"
D.Strings[86651]="圣光会指引我们走向胜利。"
D.Strings[86652]="我们正想去找你呢。结界把北边的浅湾完全封锁了。"
D.Strings[86653]="别担心，我有办法。"
D.Strings[86654]="%s怯懦地逃跑了。"
D.Strings[86655]="%s恐慌地跑了。"
D.Strings[86656]="%s跑开了。"
D.Strings[86657]="啊，你在那个地狱般的村子里发现什么了吗？"
D.Strings[86658]="<让阿帕塔看看符文，并告诉她如何过河。>"
D.Strings[86659]="尽管骂吧，姐妹，但你阻止不了我们。"
D.Strings[86660]="太迟了，守望者。这里将是你的坟墓。"
D.Strings[86661]="恶魔猎手，你们要活下去。去找大法师卡德加。他值得信赖。"
D.Strings[86662]="太好了！我可以把它们放在这里，然后……"
D.Strings[86663]="伊利丹还是我的囚犯！"
D.Strings[86664]="好了。我们过去吧！"
D.Strings[86665]="|TINTERFACE\\ICONS\\ability_socererking_arcanereplication.blp:20|t $n被打上了|cFFF00000|Hspell:196562|h[动荡魔法]|h|r的印记！"
D.Strings[86666]="|TInterface\\Icons\\Spell_Shadow_SiphonMana.blp:20|t%s开始从法力之源中|cFFF00000|Hspell:196392|h[汲取魔法]|h|r！"
D.Strings[86667]="那就快点吧。守望者要来了，还有伊利达雷。"
D.Strings[86668]="他们走投无路了。"
D.Strings[86669]="我的长姐，奥蕾莉亚，已失踪多年。我们俘虏的一个恶魔说她被某个审判团关押在一个名叫尼斯卡拉的军团世界里。要能救回她就好了！"
D.Strings[86670]="奥蕾莉亚对军团的了解能帮我们彻底打败他们。我们的目标是找回一份战略资产……仅此而已！"
D.Strings[86671]="承认吧，温蕾萨！这次行动完全是出于你的私心！"
D.Strings[86672]="那边！是俄瑞斯忒斯！"
D.Strings[86673]="我们被发现了。干掉这家伙！"
D.Strings[86674]="我得跟你一起去。万一这是陷阱，我的弓还能掩护你一下！"
D.Strings[86675]="不。在确定奥蕾莉亚的下落前，我不会让任何人冒险。我也不信那个恶魔。但这是唯一救出我……救出一个盟友的机会。"
D.Strings[86676]="我们已经把它逼入死角了，小伙子们！"
D.Strings[86677]="如果我们把这头狮子的脑袋作为战利品送给他们的话，他们一定会让我们进旅店的！"
D.Strings[86678]="拜托，你还没明白……我不是被追杀的猎物！"
D.Strings[86679]="不，不是的！我不是想逃跑！我只是想换个地方挖而已！"
D.Strings[86680]="请别伤害我！"
D.Strings[86681]="拦住他们，别让他们把我抓回去！"
D.Strings[86682]="送我去古博拉采掘场！"
D.Strings[86683]="送我去霜鬃前线！"
D.Strings[86684]="送我去铁炉堡大门！"
D.Strings[86685]="就快到了！继续战斗！"
D.Strings[86686]="这个审判官肯定是去拷问奥蕾莉亚的！我们必须救她！"
D.Strings[86687]="如果奥蕾莉亚在这儿，那一定就在附近！"
D.Strings[86688]="它显然比我以前摆弄过的机器大多了。"
D.Strings[86689]="我应该多要点工资的。这玩意儿也太大了！"
D.Strings[86690]="真不敢相信我居然已经让其中一台运转起来了。这些玩意儿的构造跟我见过的那些完全不同。"
D.Strings[86691]="这个线圈已经没用了。希望你不介意我把它直接扔在地上。"
D.Strings[86692]="啊，对了。这零件也坏了。这可能需要一点时间，先生们。"
D.Strings[86693]="噢……这些恶魔把我的狩猎假期给毁了。或许我也该为他们造成的麻烦而狩猎他们了。"
D.Strings[86694]="跟我们走，我们可以一起夺回飞行器机坪！打手，我们走！"
D.Strings[86695]="不……你们别想拿走这股力量。"
D.Strings[86696]="我们只能到这里了。谢谢你的帮忙。我这个猎人是不会忘记朋友的。"
D.Strings[86697]="有埋伏！你被跟踪了！"
D.Strings[86698]="我总算找到你了，小精灵。你根本不配跟我们平起平坐！"
D.Strings[86699]="后退！它是我的！"
D.Strings[86700]="小偷！法力是我的！"
D.Strings[86701]="不！我不会屈服！"
D.Strings[86702]="离我的法力远点！"
D.Strings[86703]="我是不会被吞噬的！"
D.Strings[86704]="卑鄙的小偷！"
D.Strings[86705]="不……还要……"
D.Strings[86706]="不！我还要……"
D.Strings[86707]="等你获得更多力量之后，再回来见我吧。"
D.Strings[86708]="喔唷，抱歉！"
D.Strings[86709]="噢，对——抱歉。"
D.Strings[86710]="抱歉！我保证没有下一次了！"
D.Strings[86711]="扔一把扳手上来！"
D.Strings[86712]="扳手！"
D.Strings[86713]="奥尼！扳手！"
D.Strings[86714]="奥尼！别再瞎晃悠了！"
D.Strings[86715]="嘿！这可不是观光的时候，小鬼！"
D.Strings[86716]="你的衬衫穿着痒吗？我的好痒……我也没出汗啊。"
D.Strings[86717]="你觉得我要准备多少时间？我是说，这都快3个星期了。我觉得我已经是个很不错的学徒了。"
D.Strings[86718]="你指甲里的泥是怎么弄出来的？我的就不会……而且这些泥的气味还很难闻。"
D.Strings[86719]="这个桶有点重。如果我一直用这只胳膊抱着它，它就会睡着了。我是说我的胳膊，不是桶。"
D.Strings[86720]="你的眼镜起雾了没？我不知道怎么防止这种事发生。我的视力只剩下平时的一半了。"
D.Strings[86721]="这也将是我的命运……除非……"
D.Strings[86722]="我们得击退他们！我们的小伙子们正在努力把他们挡在大门外！"
D.Strings[86723]="守住阵线！如果再让他们突破防线的话，我们就得把部队撤下来了！"
D.Strings[86724]="我以前从没见过这种情况。他们一直在不停地冲上来！"
D.Strings[86725]="我们占据了制高点。利用这点来对付他们！"
D.Strings[86726]="我从来没打过败仗，今天也不打算开这个先例！"
D.Strings[86727]="一代又一代，这里的牛头人自相残杀。无数生命——甚至整个部族——都因此而消逝。"
D.Strings[86728]="有一次，胡恩·高岭打完这样一场战争归来，却发现他的人民都被一个闻所未闻的敌人杀害了。"
D.Strings[86729]="克服悲痛之后，胡恩与剩下的部族首领们谈判。他说服他们团结起来，对抗这一新的威胁。"
D.Strings[86730]="我要告诉你关于胡恩·高岭的故事。"
D.Strings[86731]="现在，你将见证胡恩所经历的试炼……"
D.Strings[86732]="大领主，我找到了有资格与你并肩作战的圣骑士。我马上就到圣光之愿大殿来见你。"
D.Strings[86733]="做好准备，$G小子:丫头;。战斗才刚刚开始。"
D.Strings[86734]="我的胡子……这……这——他们要为此付出代价！"
D.Strings[86735]="非常感谢，$n。你最好在他们回来之前离开这儿。"
D.Strings[86736]="跟我说说胡恩的故事吧。"
D.Strings[86737]="我要谢谢你。那些猎人不拿到我的脑袋是不会罢休的。他们的东西都归你了。"
D.Strings[86738]="不……不！你们休想逃出去……"
D.Strings[86739]="……砸扁了……"
D.Strings[86740]="碾碎他们，兄弟！"
D.Strings[86741]="你用力摇，我来砸扁他们！"
D.Strings[86742]="你可是大不如前了啊，朋友。"
D.Strings[86743]="现在不行，$n。眼下还有更紧急的事情要处理。"
D.Strings[86744]="你的尸体会告诉我答案的。"
D.Strings[86745]="想逃跑？做梦！"
D.Strings[86746]="我们怎么知道你可不可靠？我听说过恐惧魔王在附近出没的传言。"
D.Strings[86747]="这是个脆弱的年代。"
D.Strings[86748]="已经没希望了。"
D.Strings[86749]="你休想再看见阳光！"
D.Strings[86750]="你们很快就会痛苦地死去。"
D.Strings[86751]="你休想阻止燃烧军团的大潮！"
D.Strings[86752]="这些就是这个世界的保卫者？真可悲！"
D.Strings[86753]="你们会像之前那些守望者一样倒下的！"
D.Strings[86754]="战斗工兵来了！下面的小心了！"
D.Strings[86755]="焕然一新！这个家伙的杀伤力惊人！去飞行器机坪上找几个大家伙试试它的威力吧！"
D.Strings[86756]="这里……安静得有些诡异。"
D.Strings[86757]="我什么野兽都没感觉到！"
D.Strings[86758]="而且，我敢肯定我们被监视了……"
D.Strings[86759]="那头野兽在那儿！愿安瑟保佑我们！"
D.Strings[86760]="玛维为什么要放了我们？只可能是一个原因……"
D.Strings[86761]="燃烧军团来了。"
D.Strings[86762]="|TInterface\\Icons\\spell_frost_frozenorb:20|t|cFFFF0000$n|r成为了|cFFFF0000|Hspell:197365|h[压抑深渊]|h|r的目标！"
D.Strings[86763]="仪式守卫们，做好准备！不要让她失望！"
D.Strings[86764]="哼。入侵者。他们走不了多远。"
D.Strings[86765]="进入传送门，找到阿佐兰。"
D.Strings[86766]="我已经坐了一整天了。"
D.Strings[86767]="蠢货！你要相信守望者？她恨我们就像恨燃烧军团一样深。"
D.Strings[86768]="据说，只有圣洁之人才能举起圣剑。来呀，勇士！来迎接你的命运！"
D.Strings[86769]="我挖！我找！我藏！"
D.Strings[86770]="多加蜡，蜡烛大。蜡烛多，光亮多。"
D.Strings[86771]="你没有信仰，也不懂信任，奥图里斯。你就是个孤家寡人。"
D.Strings[86772]="为什么不带蜡烛？没有蜡烛，黑暗会吞掉你！"
D.Strings[86773]="不聊了！我得继续挖了！"
D.Strings[86774]="你怎么可能打败我？我掌握着荒野之力！"
D.Strings[86775]="我不知道你为什么想要证明自己。你现在本应该坐在你的坦克里回到战场了。"
D.Strings[86776]="稍等一下。我以前修的都是机器，没修过矮人。"
D.Strings[86777]="麦克松去哪儿了？在你返回战场之前，或许该让他来看看你。"
D.Strings[86778]="这股力量将摧毁你！"
D.Strings[86779]="不够……我还要更多！"
D.Strings[86780]="十字路口的居民们受到了鼓舞，纷纷加入了对抗燃烧军团的战斗！"
D.Strings[86781]="闯入者……你是来偷我的法力的，对吧！？"
D.Strings[86782]="那就来尝尝吧！"
D.Strings[86783]="把我的副官都干掉了？你肯定觉得自己很聪明吧？"
D.Strings[86784]="伊什卡奈斯你这蠢货，不但流了血，还弄洒了我的法力。"
D.Strings[86785]="军团又能得到一条灵魂了。"
D.Strings[86786]="凡人都将成为灵魂引擎的燃料。"
D.Strings[86787]="我很担心奥罗的安全，但他有责任保卫我们的部族。"
D.Strings[86788]="让我们看看你要怎么对付这个！"
D.Strings[86789]="不！保护我！"
D.Strings[86790]="是那条龙派你来的吗？还是鲁纳斯那个乞丐？"
D.Strings[86791]="我跟你们一样奋战过！但是我没有屠杀过无辜者。"
D.Strings[86792]="无所谓了。你很快就要跪着迎接阿苏纳的新君主了！"
D.Strings[86793]="你做了什么？我的虹吸管道！"
D.Strings[86794]="下等杂种。你不明白自己面对的是谁。哈……哈……哈哈哈哈！"
D.Strings[86795]="它跑进迷雾深处了。它可能藏在任何地方！英雄，你有什么陷阱能够困住那头野兽吗？"
D.Strings[86796]="爆炸物或许能驱散浓雾？我们就在你身后，陷阱大师。我们会保护你布置陷阱的。"
D.Strings[86797]="加尔顿？"
D.Strings[86798]="奥罗，需要我告诉你多少遍？不要拿着那根棍子到处跑！"
D.Strings[86799]="奥罗，呆在我能看到的地方，不要乱跑！"
D.Strings[86800]="要是你掉进水里，你哥哥可没办法把你再钓起来！"
D.Strings[86801]="你有鱼饵吗，麦查？"
D.Strings[86802]="有几个，但我觉得奥罗把鱼都吓跑了。"
D.Strings[86803]="你的选择尚未开放测试。请选择其他选项。"
D.Strings[86804]="所以你也是来追杀黑暗骑士的？我一直在想办法让暮色森林摆脱他们的诅咒，可现在看来，我已经变成他们追杀的对象了。\n\n虽然我们有着共同的敌人，但你背负的罪孽让我无法帮助你。从邪恶者手中夺取力量，再将其交给另一个邪恶者，这不是侍奉圣光之道。"
D.Strings[86805]="这股力量能够帮助我们打败燃烧军团。你认为这个目标是邪恶的吗？"
D.Strings[86806]="我没时间听你胡扯，牧师！燃烧军团是眼下最大的威胁！"
D.Strings[86807]="要是你不告诉我，我就自己从你的灵魂中搜索答案！<攻击>"
D.Strings[86808]="我承认燃烧军团是一个巨大的威胁，但我的责任是侍奉圣光。\n\n我必须时刻警惕它的所有敌人，无论局势看起来有多危急。"
D.Strings[86809]="对我来说，没有比亵渎圣光者更大的威胁了！\n\n我是不会引导罪人的手去攫取力量的，哪怕要为此付出最终的代价！"
D.Strings[86810]="如果我们不采取行动，萨格拉斯就会占领这个世界。你所追随的圣光就会连骨头渣子都不剩了。到那时你还要怎么尽自己的责任？"
D.Strings[86811]="你这个蠢货！燃烧军团正在这个世界肆虐，而你却死抱着圣光不放。等你沦为奴隶之时，你的圣光能救得了你吗？"
D.Strings[86812]="算了吧，我会自己寻找我要的答案！<攻击>"
D.Strings[86813]="只要人们心中还有勇气，圣光就绝不会动摇。\n\n我们曾见证过它带来了燃烧军团的失败，这次也不会例外。"
D.Strings[86814]="愚蠢的人是你，$c！\n\n圣光是信仰的堡垒！它曾帮助我们击退过燃烧军团，这次它依然会带领我们走向胜利！"
D.Strings[86815]="你错了。我当时就在破碎海滩上。我亲眼看见恶魔屠杀我们的同伴，圣徒和恶棍一样哀嚎着死去。如果我们不能立刻扭转局势，那么一切就都完了。"
D.Strings[86816]="我看见你们的神圣战士在萨格拉斯之墓外的乱石上身首异处！这支燃烧军团的大军空前强大。要想将他们赶回虚空，我们需要的不仅仅是你的圣光！"
D.Strings[86817]="够了！回答我的问题，否则就去死吧，牧师！<攻击>"
D.Strings[86818]="显然，如果我们想要达成目的，那就得合作，$c。\n\n我们别再浪费时间了。"
D.Strings[86819]="你的话很真诚，$c。我们的道路虽然不同，但你也是在为崇高的目标而战。"
D.Strings[86820]="%s示意你跟上。"
D.Strings[86821]="我没有！"
D.Strings[86822]="送我去鬼雾营地！"
D.Strings[86823]="我们将要迎来艰难的一天。"
D.Strings[86824]="你挡了我的路。"
D.Strings[86825]="我们誓与高岭部族共进退。"
D.Strings[86826]="送我去十字路口！"
D.Strings[86827]="它在迷雾中向我们攻击！快！"
D.Strings[86828]="成功了！杀了这个怪物！"
D.Strings[86829]="拿上钥石！我们回下面的传送门那里去，返回黑暗神殿！"
D.Strings[86830]="你是我网中的猎物了。"
D.Strings[86831]="你好啊，小飞虫。"
D.Strings[86832]="你的世界将化为火海。"
D.Strings[86833]="你无处可藏了，宝贝。"
D.Strings[86834]="对于各派成员和弟子们，我要感谢你们的加入。"
D.Strings[86835]="对晴日峰的攻击表明，燃烧军团想要毁灭我们的门派。他们会摧毁我们的家园，亵渎我们的圣地，以求打垮我们的意志。"
D.Strings[86836]="可在我们面临灭顶之灾的时候，$n与海特大师一起击退了恶魔，救了我们的性命。"
D.Strings[86837]="武僧们，更大的挑战还在前头。在新任大宗师的领导下，我们要发出反抗的宣言。敌人休想轻易夺走我们的家园！"
D.Strings[86838]="海特大师已经逝世，我们的组织中出现了一个空缺。"
D.Strings[86839]="向大宗师$n致敬！愿他的力量和智慧指引我们。"
D.Strings[86840]="向大宗师$n致敬！愿她的力量和智慧指引我们。"
D.Strings[86841]="我们必须走了。很快我们就能到家了。"
D.Strings[86842]="别害怕。情况很快就会好起来的。"
D.Strings[86843]="我可以告诉你一切。"
D.Strings[86844]="你的话里有刺，可也很真诚。虽然我讨厌你的做法，但我们似乎别无选择了。"
D.Strings[86845]="好吧，我可以告诉你一切。"
D.Strings[86846]="太好了！我已经准备好了，跟我来。"
D.Strings[86847]="奥罗不想让我沉浸在悲痛中。为了他，为了我们的孩子，我要坚强起来。"
D.Strings[86848]="那位与海特大师并肩战斗过的英雄，他表现出了无可估量的勇气，他应该成为海特大师的继任者。"
D.Strings[86849]="来吧！让圣光净化你！"
D.Strings[86850]="够了！你已经证明了你的力量，术士。"
D.Strings[86851]="跟你这样凶狠的家伙合作对抗燃烧军团总比与你为敌的好。我愿意帮你。"
D.Strings[86852]="只有在我弟弟睡着时，鱼才会咬钩。我妈妈一个人照顾他太辛苦了。"
D.Strings[86853]="等我长大以后，要像爸爸一样成为武士。"
D.Strings[86854]="干得好，$n。现在，快点！西边需要你的帮助。"
D.Strings[86855]="等你准备好之后，就穿过传送门，前往暴风城吧。"
D.Strings[86856]="我们已经为你开启了一座通往暴风城的传送门，$n。请跟我来。"
D.Strings[86857]="闭嘴。我受够你的唠叨了。别担心，这一切很快就会结束了。"
D.Strings[86858]="邪能之主，我为你们带来了最后的祭品！我已经分九次献上了九条灵魂，每一个都是我的朋友和亲人!"
D.Strings[86859]="你应该感到骄傲，废物。你对我很特别，因为你将成为我登天的台阶。"
D.Strings[86860]="如此强大的力量！我是不可阻挡的！"
D.Strings[86861]="今天将是个光荣的日子！"
D.Strings[86862]="走进这里的三个部族，将团结在一起。"
D.Strings[86863]="高岭部族，团结一心！"
D.Strings[86864]="攻城蠕虫！攻击我标记的目标！"
D.Strings[86865]="乌霍！不！"
D.Strings[86866]="亲爱的兄弟……我真不该带你来。"
D.Strings[86867]="那个畜生又来了！我——啊啊！！"
D.Strings[86868]="我不行了……你必须……完成任务。"
D.Strings[86869]="大魔导师将许多夜之子逐出了苏拉玛。那些不同意与燃烧军团媾和的、政敌、还有她信不过的人都被赶出了城市。$b$b我们此时更需要团结起来。我将他们带了回来，让他们能再次汲取暗夜井的能量。我救出的人都恢复了魔法力量。我又给了他们一次为更加伟大的事业而奋斗的机会。"
D.Strings[86870]="刚才那一枪真是疯狂！你没事吧？"
D.Strings[86871]="我会干脆利落地结果你。"
D.Strings[86872]="死在我的力量之下！"
D.Strings[86873]="你怎么敢？！"
D.Strings[86874]="我来自阿古斯，黑暗虚空的力量中心。"
D.Strings[86875]="尝尝我的邪能魔法吧。"
D.Strings[86876]="能学习打猎就是梦想成真了。"
D.Strings[86877]="我们真是黄金搭档。"
D.Strings[86878]="我闭着眼睛都能做到！但别担心，我不会真的闭上的。"
D.Strings[86879]="你会死在我的剑下。"
D.Strings[86880]="不过是小菜一碟。"
D.Strings[86881]="入侵者！碾碎他们！"
D.Strings[86882]="燃烧军团征服一切。"
D.Strings[86883]="你不是我的对手。"
D.Strings[86884]="唔……五分熟还是全熟好呢？"
D.Strings[86885]="|TInterface\\Icons\\inv_misc_monsterspidercarapace_01:20|t%s消失并|cFFFF0000|Hspell:197414|h[遁入暗影]|h|r！"
D.Strings[86886]="让我们看看你的本事吧，小东西。"
D.Strings[86887]="我好饿。"
D.Strings[86888]="啊……我的大餐来了。"
D.Strings[86889]="爬进我嘴里来吧，小东西。"
D.Strings[86890]="来吧，小鬼们，为妈妈跳个舞。"
D.Strings[86891]="我的孩子们会烤熟你的。"
D.Strings[86892]="你是来跟我的小鬼们玩的吗？"
D.Strings[86893]="孩子，燃烧军团的胜利早已注定。"
D.Strings[86894]="我要亲手把你交给泰兰娜。"
D.Strings[86895]="肮脏的小精灵。我要好好品尝你的邪能。"
D.Strings[86896]="有入侵者！快去警告末日指挥官！"
D.Strings[86897]="死之前，先说出你的秘密吧。"
D.Strings[86898]="你别想瞒过我。"
D.Strings[86899]="这应该会有帮助。"
D.Strings[86900]="死亡也保不住你的秘密。"
D.Strings[86901]="问题太多，时间太少。"
D.Strings[86902]="什么都瞒不过我。"
D.Strings[86903]="我要打垮你的意志。"
D.Strings[86904]="潮汐之石呢？说，蠢货！"
D.Strings[86905]="不……不可能。"
D.Strings[86906]="夏多雷必将统治这个世界！"
D.Strings[86907]="我的魔法……被击败了？"
D.Strings[86908]="我内心的斗志在燃烧，$n。我们必须复仇……为了吉尔尼斯，为了联盟！"
D.Strings[86909]="你为什么不亲自呈上这封信呢，格雷迈恩阁下？"
D.Strings[86910]="冥界的阴影都听从我的意志！"
D.Strings[86911]="我们的部队对付不了这种敌人。我们必须让所有人都撤回去，否则这次行动就毫无意义了。"
D.Strings[86912]="冥狱的阴影，狠狠侵蚀那块钢铁吧！"
D.Strings[86913]="逃跑吧，懦夫！"
D.Strings[86914]="懦弱的蛆虫！"
D.Strings[86915]="像我一样尝尝冰冷的死亡！"
D.Strings[86916]="北地的寒风仍在这些藤蔓间呼啸！"
D.Strings[86917]="我们没时间了，莱诺尔！他马上就要来了……"
D.Strings[86918]="还没完呢……纳格法尔号会来……找你们的……"
D.Strings[86919]="你们还没有赢……你们是在……自寻死路……"
D.Strings[86920]="不……又来了……哈布隆！把他们的灵魂扔进水里去！                                                                                                                                                                                                                                                                         "
D.Strings[86921]="我们必须引开他。$n，你愿意跟我一起吧？我们必须为同胞们争取足够的时间，虽然这肯定会让我们付出生命的代价。"
D.Strings[86922]="灵魂大海中的又一滴水！"
D.Strings[86923]="报应！"
D.Strings[86924]="一个真正的队长要敢于为他的事业牺牲！我会与你并肩战斗的！"
D.Strings[86925]="凡人……你们杀害我的人民……摧毁我的王国！我一直在等待这个机会，将你们所做的一切加倍奉还！"
D.Strings[86926]="凡人……你们杀害我的人民……摧毁我的王国！现在，该轮到你们尝尝失去一切的滋味了！"
D.Strings[86927]="凡人……我曾经败给过你们一次。这次不会再这么走运了！"
D.Strings[86928]="那就这样吧，$n，纳兹格雷尔……能与你们死在一起是一种荣幸。"
D.Strings[86929]="你们的灵魂将永远在冥界之海中徘徊！"
D.Strings[86930]="我要用你们的骨头做一顶新王冠！"
D.Strings[86931]="我从失败中吸取了教训……看来你们没有。"
D.Strings[86932]="现在你明白肉体凡胎有多么脆弱了吗？"
D.Strings[86933]="崩溃吧，你的灵魂归我了！"
D.Strings[86934]="肉体只是灵魂的累赘，是必须剥离的废物！"
D.Strings[86935]="幽灵们！将这些凡人推进潮水中去！"
D.Strings[86936]="就算我得不到报酬，幽灵们也会的！"
D.Strings[86937]="鲜血的气味让幽灵们感到饥渴了。"
D.Strings[86938]="站起来吧，仆人！为我们讨还血债！"
D.Strings[86939]="进入冥狱深渊的人都得付出血的代价。挣扎吧……但我必将拿到我的报酬！"
D.Strings[86940]="新乘客……新灵魂。我可以带你们深入冥狱深渊，只要一点小报酬：你们的血肉。"
D.Strings[86941]="我说了……我迟早会拿到报酬的！"
D.Strings[86942]="又讨回了一笔血债……又将一条灵魂丢入了深渊。"
D.Strings[86943]="人人都得付出血的代价！"
D.Strings[86944]="这次……轮到我来付出……血的代价了……"
D.Strings[86945]="海拉会让你们付出代价的……最终，所有人都得付出代价……"
D.Strings[86946]="你们都会后悔闯入我的国度的。"
D.Strings[86947]="你们已经走的够远了，该去死了。"
D.Strings[86948]="结束了。我要永远放逐你们那软弱的凡人之魂。"
D.Strings[86949]="在这里，你们的灵魂无处可藏。"
D.Strings[86950]="来生再见吧。"
D.Strings[86951]="你们的命运降临了！"
D.Strings[86952]="我要像淹死老鼠一样淹死你们。"
D.Strings[86953]="别动！"
D.Strings[86954]="别乱动！"
D.Strings[86955]="我的耐心正在消失。"
D.Strings[86956]="不！这不可能！"
D.Strings[86957]="这个洞看起来很安全，头儿。"
D.Strings[86958]="你个子高，你当头儿。"
D.Strings[86959]="别偷懒！看好动静！"
D.Strings[86960]="你到底是什么样的生物？？"
D.Strings[86961]="拥抱你们的命运吧，蠢货！"
D.Strings[86962]="永恒的痛苦在等着你们！"
D.Strings[86963]="我受够了！到此为止吧！"
D.Strings[86964]="该死的！你们真以为能征服我的国度？你们这是在和整个冥狱深渊为敌……"
D.Strings[86965]="全体士兵，撤退！带上伤员，退回船上去！"
D.Strings[86966]="椅子空着。我坐，没人在意吗？"
D.Strings[86967]="你来指挥，我来帮忙！"
D.Strings[86968]="苔丝和指挥官克罗雷会护送你前往要塞。我得留下来监督准备工作。"
D.Strings[86969]="这是至高岭做买卖的习惯。如果你需要大气之火，就跟我说一声。"
D.Strings[86970]="斯纳兹尔是个好工人。我专门为你挑的。"
D.Strings[86971]="这家伙脑子不行，但凿子够锋利。"
D.Strings[86972]="达格不是最好的。但也够好了。"
D.Strings[86973]="太慢了！头儿的时间不多。"
D.Strings[86974]="刚好赶上了开工时间！"
D.Strings[86975]="我来帮你捅死它，头儿！"
D.Strings[86976]="跑太快了，蜡烛熄灭了。黑暗吃了我！"
D.Strings[86977]="你选了最好的挖掘工！"
D.Strings[86978]="你干得很好！头儿才是最大的。"
D.Strings[86979]="面对那些虫子时，你只要招呼一声，我们就会出现。"
D.Strings[86980]="我上次登上迷踪岛已经是很久之前的事了。"
D.Strings[86981]="好酒、好朋友、好音乐。$b$b这些真是生活中的赏心乐事。"
D.Strings[86982]="深渊之子，站起来，碾碎这些走狗！"
D.Strings[86983]="不要拿走蜡烛！如果蜡烛熄灭了，黑暗就要吃人了！"
D.Strings[86984]="头儿的耳朵大，可以装最多的蜡。新鲜的蜡可以做出最好的蜡烛。"
D.Strings[86985]="不要碰这些水！"
D.Strings[86986]="这水是神圣的！"
D.Strings[86987]="穆莎之泪不属于凡世！"
D.Strings[86988]="你别想染指这个地方的魔力！"
D.Strings[86989]="这块水晶属于大地！"
D.Strings[86990]="安度因陛下，破碎海滩的英雄来了。"
D.Strings[86991]="我听说父亲战死时，你就在他身边。"
D.Strings[86992]="告诉我他是怎么死的。"
D.Strings[86993]="正义终将获得胜利。我确信这一点。"
D.Strings[86994]="噢！我怎么会想到要来看看老爸的？！$b$b他只会坐在那里大吃大喝。就连哥哥也宁愿去旅店鬼混，不肯跟我去探险。无——聊——！"
D.Strings[86995]="你准备好之后就告诉我一声，我会让你进入格罗玛什要塞。$b$b但记住，最近的局势很紧张，$n。你必须有所准备。"
D.Strings[86996]="转身躲开|cFFFF0000|Hspell:197737|h[掠食者的凝视]|h|r。"
D.Strings[86997]="保护酋长！"
D.Strings[86998]="让你心中的火焰继续燃烧吧，$c，让别人感受到你散发出的热量，让他们重新打起精神。"
D.Strings[86999]="<在闸门的另一边，你可以隐约看见拉文凯斯墓地。>"
D.Strings[87000]="离开黑暗围栏。"
D.Strings[87001]="塞纳苟斯，我们在找一座创世之柱。它就在阿苏纳。"
D.Strings[87002]="你提到了高戈奈斯潮汐之石。它早就碎了。"
D.Strings[87003]="潮汐之石……碎了？怎么会？"
D.Strings[87004]="我不知道……但我知道碎片的下落。"
D.Strings[87005]="污染者……你们的血液带着梦魇的恶臭。滚出森林，不然就承受自然之怒吧！"
D.Strings[87006]="污染者……是你们在用梦魇玷污这片森林。"
D.Strings[87007]="奥鲁丹，我有急事要去瓦尔莎拉。你能为我安排一下吗？"
D.Strings[87008]="杀了她！保护林地！"
D.Strings[87009]="杀了他！保护林地！"
D.Strings[87010]="是要从达拉然到瓦尔莎拉吗？"
D.Strings[87011]="榨干你体内的梦魇！"
D.Strings[87012]="接受尖牙和利爪的净化！"
D.Strings[87013]="我全身充满了自然之怒！"
D.Strings[87014]="我是自然之怒的化身！"
D.Strings[87015]="接受星光的净化吧！"
D.Strings[87016]="我与自然合为一体！"
D.Strings[87017]="这是自然对我的恩赐！"
D.Strings[87018]="荒野滋养了我！"
D.Strings[87019]="只有死亡才能让你摆脱梦魇。"
D.Strings[87020]="你们的鲜血腐臭不堪。"
D.Strings[87021]="趴下吧，污染者！"
D.Strings[87022]="荒野又一次躲过了梦魇的威胁。"
D.Strings[87023]="梦魇休想在这片神圣的森林里扎根。"
D.Strings[87024]="我明白了……我才是污染者……"
D.Strings[87025]="梦魇……再也不能蒙蔽我了……"
D.Strings[87026]="我做了个……奇怪的噩梦……"
D.Strings[87027]="让大海卷走你！"
D.Strings[87028]="大海！听从我的命令！"
D.Strings[87029]="我很好奇，你们能憋多久呢？"
D.Strings[87030]="可惜你们离不开空气！"
D.Strings[87031]="地震是巨浪的先锋！"
D.Strings[87032]="颤栗的大地预示了汹涌的潮水！"
D.Strings[87033]="大海平息了……但狂风会对付你们的。"
D.Strings[87034]="啊......让狂风消灭你们，入侵者。"
D.Strings[87035]="你们还没赢呢。她就要到了……"
D.Strings[87036]="我……我失败了……可女王陛下不会。"
D.Strings[87037]="为我死去的儿子报仇！"
D.Strings[87038]="血债血偿。"
D.Strings[87039]="让海浪淹死你们这些可怜虫！"
D.Strings[87040]="你们杀了我儿子！偿命吧！"
D.Strings[87041]="历史的大潮不可阻挡，蠢货。"
D.Strings[87042]="我为头儿找到了最亮的亮晶晶！"
D.Strings[87043]="我这里正好有执行这项特别任务的最佳之选。"
D.Strings[87044]="杀了最大的蜥蜴！也是最重的……"
D.Strings[87045]="达格呢？他应该回来了。头儿去找找吧。"
D.Strings[87046]="游戏结束了。到此为止吧！"
D.Strings[87047]="在烈火中燃烧吧！"
D.Strings[87048]="涅槃重生！"
D.Strings[87049]="我会治疗你的，$n。"
D.Strings[87050]="我不会让你倒下的！"
D.Strings[87051]="回战场上去吧！"
D.Strings[87052]="圣光将净化我们所有人，士兵。"
D.Strings[87053]="小心黑暗中那些跳来跳去的住民！"
D.Strings[87054]="爬行的恶魔……它们会刮擦你的皮肤……寻找钻入你身体的口子。"
D.Strings[87055]="自然的黑暗爪牙……恐怖、畏光的爬行生物，躲在黑暗中伺机撕咬敌人。"
D.Strings[87056]="你必须懂得欣赏大自然的不同面貌。"
D.Strings[87057]="为什么人人都是这么匆匆忙忙的？"
D.Strings[87058]="站着别动，我的姐妹在跟你说话呢！"
D.Strings[87059]="为什么人人都急着想走？瓦达拉有几句忠告要告诉你……都是些直指人心的警句！"
D.Strings[87060]="嘿，慢点儿！火在哪儿呢？"
D.Strings[87061]="你要明白，自然是很矛盾的……无尽的美丽总是伴随着无情的危险。"
D.Strings[87062]="自然中有着无数奇观……但你也要小心，观察危险的所在。"
D.Strings[87063]="我为你种了一样礼物！"
D.Strings[87064]="来吧，靠近点……深呼吸。"
D.Strings[87065]="嘿……我们中间有个蘑菇！"
D.Strings[87066]="这就是……自然的轮回。"
D.Strings[87067]="对！我准备好……踏上……新的冒险了……"
D.Strings[87068]="再见，姐妹！我想说过去的这段时间我过得很愉快，可我不想在临别时还说谎。"
D.Strings[87069]="我已经学到了很多……现在，我要奔向未知的领域了。"
D.Strings[87070]="生命，死亡……都是一样的，真的。"
D.Strings[87071]="你会成为很好的堆肥……"
D.Strings[87072]="再见，我这是对你说的！明天或许会是更加光明的一天。"
D.Strings[87073]="有太多东西值得我们去看了！"
D.Strings[87074]="我开启了一座小型传送门，帮助伤员尽快回到船上。"
D.Strings[87075]="自然欢迎你！"
D.Strings[87076]="我们有客人了！或者我应该说是害虫？"
D.Strings[87077]="害虫已经消灭。"
D.Strings[87078]="大胆的入侵者失败并倒在了这里。是什么让他们如此自负？没人知道答案。"
D.Strings[87079]="至今还没有人成功拿起过风暴守护者的武器。你会成为第一个吗？"
D.Strings[87080]="所有想要威胁大自然的宁静的家伙，这就是你们的教训！"
D.Strings[87081]="别跑！他们不喜欢你跑，明白了吗？"
D.Strings[87082]="你们都……得……排队等着！"
D.Strings[87083]="站住！你要是不想站住，我就强迫你站住！"
D.Strings[87084]="我坚持要你留在这里。你不想错过什么乐子吧！"
D.Strings[87085]="放松点。抛弃你的疑虑吧。"
D.Strings[87086]="这可能会有点烫……或者非常烫。"
D.Strings[87087]="他将终结这个世界，而我将熔化你们！"
D.Strings[87088]="我可不想惹火你……我会直接烧死你。"
D.Strings[87089]="你可能会感到一点刺痛。然后是缓慢而痛苦的死亡。"
D.Strings[87090]="我不是想对你发火……我只是想让你痛苦地死去！"
D.Strings[87091]="死亡的滋味是美妙的，就像醇酒。好好享受吧！"
D.Strings[87092]="我喜欢你，我是说真的！所以我才想让你慢慢地、痛苦地死去。"
D.Strings[87093]="欢迎回到暴风城，$n。看到你从破碎海滩活着回来，我松了一口气。$b$b我们决不能失去你！"
D.Strings[87094]="这不公平，不公平！"
D.Strings[87095]="等等，这下我全明白了……梦魇让我发了疯，我——嗷啊！啊啊啊……"
D.Strings[87096]="噢，现在我要去哪儿？但愿那里有树……"
D.Strings[87097]="我倒下了！就像……飘落枝头的树叶！"
D.Strings[87098]="但愿你的肌肉不会因为养活了那么多花草而发酸！"
D.Strings[87099]="我带来了你父亲的信。"
D.Strings[87100]="痛吗？不是，我是真的关心你！"
D.Strings[87101]="是时候说晚安了！"
D.Strings[87102]="后退，努达！是我先看见他们的！"
D.Strings[87103]="我都不知道我们还安排了聚会！"
D.Strings[87104]="你们没有收到邀请！可我喜欢惊喜！"
D.Strings[87105]="好吧，我完全不知道那是什么意思……"
D.Strings[87106]="这就好像是胜利……但却正相反。"
D.Strings[87107]="都听他的！"
D.Strings[87108]="亵渎者……"
D.Strings[87109]="你会像我们一样……逐渐变冷。"
D.Strings[87110]="感受坟墓的寒意吧！"
D.Strings[87111]="艾利桑德……阻止她……"
D.Strings[87112]="我要安息了。"
D.Strings[87113]="你早已声名远播了，$c。我听说你去过破碎海滩的前线。你比任何人都清楚我们的世界要面对的是什么。$b$b如果你想要获得风暴守护者莱登的武器，别忘了之前已经有许多人尝试过，但至今还没有人成功过。你将要面对一系列的挑战，但不要搞错了……武器本身才是最危险的考验。$b$b你打算继续下去吗？"
D.Strings[87114]="我们的人民……shu dalees-na。"
D.Strings[87115]="我们怎么了？"
D.Strings[87116]="我准备好了，白虎。"
D.Strings[87117]="我们终于可以安息了。"
D.Strings[87118]="安宁……"
D.Strings[87119]="滚出我们的山脉！"
D.Strings[87120]="我在森林里闻到了鲜血的味道。"
D.Strings[87121]="我要把你的胳膊扯下来！"
D.Strings[87122]="让你看看我的实力！"
D.Strings[87123]="盟友给了我们力量！"
D.Strings[87124]="图鲁克会对你的死感到很满意的！"
D.Strings[87125]="这座山将属于邪能图腾！"
D.Strings[87126]="沃金……"
D.Strings[87127]="救了我们……我担心联盟会认为我们是故意丢下他们送死。"
D.Strings[87128]="……你想让我们怎么做，酋长？"
D.Strings[87129]="埃里雷，给我一杯喝的！"
D.Strings[87130]="我父亲是个经验丰富的军事家，可他的军队还是在破碎海滩遭遇了惨败。连他都失败了，我又怎么可能成功呢？"
D.Strings[87131]="这不是你一个人的事情，陛下。我们都会支持你的。"
D.Strings[87132]="你们忘了部落的背叛了吗？是时候好好教训一下那些狗东西了！"
D.Strings[87133]="两线作战是愚蠢的行为。为了我们自己着想，我们需要与部落合力对抗燃烧军团。"
D.Strings[87134]="维伦说得对。我们必须和恶魔猎手一起，集中精神对付燃烧军团。现在不是——"
D.Strings[87135]="部落背叛了你的父亲，丢下我们等死！与那些懦夫并肩作战只会玷污他所坚持的一切。"
D.Strings[87136]="你们这两个懦夫。安度因陛下，你知道我们应该怎么做。我们必须迅速出击，让部落烟消云散，让他们自己去对付燃烧军团。"
D.Strings[87137]="随着伊利达雷的加入，我们就相当于掌握了一把尖刀。你允许他们进入暴风城的决定很明智，安度因国王。"
D.Strings[87138]="我的人民很清楚以一个四分五裂的世界对抗燃烧军团会付出怎样的代价。我们应该齐心协力保护我们的土地。"
D.Strings[87139]="你的第一个试炼是力量的考验。这个维库人勇士也想代表他的氏族夺取风暴的武器。你们中只有一个人能通过这个考验。"
D.Strings[87140]="没错。我很抱歉，吉安娜，复仇的事得先等等。你应该已经按照我们商量好的去动员肯瑞托了吧？"
D.Strings[87141]="旅店附近十分平静，指挥官。"
D.Strings[87142]="有你在营地真好，指挥官。"
D.Strings[87143]="<这个维库人战士对你嗤之以鼻。>$b$b你就是我的第一个考验？呸！我身上的疤比你的吓人多了。"
D.Strings[87144]="击败两位君王"
D.Strings[87145]="我打过海怪，杀过巨人。你算什么东西！"
D.Strings[87146]="我……认输……"
D.Strings[87147]="还没完呢，萨满。我们迟早会在真正的战场上相遇。"
D.Strings[87148]="艾露恩……指引我……"
D.Strings[87149]="你救出那些士兵后，就立刻到这里来吧，$n。愿艾露恩与你同在。"
D.Strings[87150]="无辜者不会白白牺牲。他们要为部落而死。"
D.Strings[87151]="破碎海滩只是一个开始。燃烧军团的力量每时每刻都在增长。很快我们就不是他们的对手了。"
D.Strings[87152]="那联盟呢？他们毫无廉耻可言。只要有机会，他们就会趁我们虚弱的时候落井下石。"
D.Strings[87153]="至于酋长，他认为肯瑞托有我们需要的知识。我相信卡德加肯定很欢迎他的到访。"
D.Strings[87154]="卡德加很快就会联系你了。我必须让幽暗城做好战争的准备。你会站在我们一边的吧，$n？还是要帮助人类？"
D.Strings[87155]="我已经采取了一定的……预防措施。我的卫兵会一直守在城里，直到联盟的威胁解除为止。"
D.Strings[87156]="很高兴见到你，$n。在我的部队开赴战场之前，我想请你帮个忙。"
D.Strings[87157]="$n，我们向上头申请了一头角鹰兽，送你去破碎群岛！"
D.Strings[87158]="只有我才配得上风暴之神的眷顾！"
D.Strings[87159]="我将进入英灵殿，荣耀将属于我！"
D.Strings[87160]="我掌握着北风的力量……"
D.Strings[87161]="你们这可怜的大地之环就这点本事吗！？"
D.Strings[87162]="这边走，朋友。我会尽力帮你通过试炼的。"
D.Strings[87163]="你是来找风暴之神的武器的吗？上前来，萨满。"
D.Strings[87164]="快去克拉苏斯平台。我会想办法获得法师的支持的。"
D.Strings[87165]="风暴烈酒！你也是来找风暴神兵的吗？"
D.Strings[87166]="遵命。“风暴，大地，火焰”嘛，都是我的强项。"
D.Strings[87167]="许多人都想得到风暴守护者的神器。但没有人能通过试炼。来吧，接受考验吧！"
D.Strings[87168]="状态不错，朋友。我说过没有？乌瑞恩国王的格斗术就是我教的。"
D.Strings[87169]="谁敢来挑战我！？风暴武器理应属于我的氏族！"
D.Strings[87170]="首先是力量的试炼。你们中只有一个人能通过。跟我说一声就可以开始了。"
D.Strings[87171]="他只会吹牛。用他的力量对付他吧。"
D.Strings[87172]="我会给你套上闪电之盾，但别让他靠得太近！"
D.Strings[87173]="难以置信！一个能与元素完美共鸣的战士！"
D.Strings[87174]="你就要胜利了，勇士！"
D.Strings[87175]="别担心，勇士。还没完呢。"
D.Strings[87176]="这位萨满获得了胜利！第一项试炼完成。"
D.Strings[87177]="啊，你肯定就是万灵在低语中提到的那个人。你的光辉事迹和你的强大神器早已威名远播。$b$b我是灵魂行者黑角。我听说了许多你在破碎群岛之外的事迹。$b$b就让我们看看你的这些英雄故事到底是不是真的吧，如何？"
D.Strings[87178]="准备谈判。"
D.Strings[87179]="真正的英雄从不单打独斗。下一个试炼是对团队合作的考验。你必须选择一位搭档。"
D.Strings[87180]="我来当勇士的副手！我们的对手是谁？"
D.Strings[87181]="下一个应该是我。"
D.Strings[87182]="风暴烈酒！？哈！我早就期待着能跟你一战，好好杀杀你的威风了。"
D.Strings[87183]="让我介绍一下我自己。"
D.Strings[87184]="是吗？那就看看谁才是真正的“风暴英雄”吧。但首先，我需要一个搭档。"
D.Strings[87185]="随时准备冒险了！"
D.Strings[87186]="噢，不，不，丽丽，你不——"
D.Strings[87187]="记住：只有团队合作才能为你们赢得胜利。3……2……1……开始！"
D.Strings[87188]="忘掉你的骄傲吧。先解决那个熊猫人女孩！"
D.Strings[87189]="你很快，兽人。但还不够！"
D.Strings[87190]="你这是贪心不足，熊猫人。这下可不轻啊！"
D.Strings[87191]="没有金刚钻，不揽瓷器活！$b$b欢迎来到我的小店，$n。我是琼斯，提莫斯·琼斯，你也可以叫我TJ。随便你怎么叫都行。$b$b如果你有任何需要，我是说“任何”需要，你都可以告诉我，我会为你提供帮助的。$b$b<提莫斯对你眨了眨眼，然后回去工作了。>"
D.Strings[87192]="攻击那个治疗者！"
D.Strings[87193]="丽丽，小心！"
D.Strings[87194]="嘿，好东西来啦！"
D.Strings[87195]="我不会让你死的！"
D.Strings[87196]="这些家伙耍赖！"
D.Strings[87197]="你击败了我。"
D.Strings[87198]="祝贺你，英雄！第二项挑战完成。"
D.Strings[87199]="雷加尔，这恐怕是你带来竞技场的战士中最强大的一位了。"
D.Strings[87200]="我一眼就看出这是位勇士了！"
D.Strings[87201]="圣光作证，珠宝可是我的老本行！$b$b我能为你做点什么吗？"
D.Strings[87202]="你已经证明了自己的实力，勇士。你可以参加最后一项试炼了。迄今为止，还没有人能通过这项考验。"
D.Strings[87203]="风暴守护者的武器是如此强大，就连雷电之王也不敢碰它们。"
D.Strings[87204]="你的最后一项挑战就是莱登之拳。如果你能拿起它并活下来，这件武器就属于你了。"
D.Strings[87205]="我相信你，萨满！"
D.Strings[87206]="这真是太酷了。"
D.Strings[87207]="老实说……那些玩意儿吓到我了。"
D.Strings[87208]="你！小心点！"
D.Strings[87209]="你好啊，$n，我叫斯米克斯。我主要加工高档珠宝，宝石切割的工作我都交给蒂凡妮了。$b$b如果你需要帮忙镶嵌宝石，就跟我谈谈吧。"
D.Strings[87210]="集中精神，勇士！"
D.Strings[87211]="你想要什么，陌生人？"
D.Strings[87212]="站到闪电中去，证明你对元素的掌控能力吧。"
D.Strings[87213]="使用闪电箭摧毁第一个目标。"
D.Strings[87214]="唔。或许我们该去外头。"
D.Strings[87215]="稍等一下，白虎阁下。"
D.Strings[87216]="集中精神，勇士。你是天生的元素掌控者。你能做到的！"
D.Strings[87217]="这么说，你就是黑角提到的那个人？$b$b真是古怪的灵魂行者做出的古怪预言。$b$b要我说的话，这可真是太古怪了。"
D.Strings[87218]="你听说了吗？大酋长死了！$b$b卓格巴尔地底之王背叛了他。"
D.Strings[87219]="洁儿想跟卓格巴尔谈判。没有其他部族的帮助，我们别无选择，只能想办法和平解决。"
D.Strings[87220]="我听说卓格巴尔已经开始进攻白水溪和雷霆图腾了。$b$b这真是个黑暗的年代。"
D.Strings[87221]="使用熔岩爆裂摧毁第二个目标。"
D.Strings[87222]="集中精神！控制住！"
D.Strings[87223]="情况不对……这里有人……"
D.Strings[87224]="燃烧军团进攻了！"
D.Strings[87225]="你们休想阻止审判庭！"
D.Strings[87226]="你得把我从这个牢笼里弄出去！我们面临的威胁比你想象的要大得多！"
D.Strings[87227]="决不能让大审判官阁下受到干扰！"
D.Strings[87228]="谢谢你，$n。我要回去战斗了。"
D.Strings[87229]="别杀这些凡人。我们得找到这个所谓的“风暴之神”的武器。"
D.Strings[87230]="等我胜利以后，再来品尝你的灵魂。"
D.Strings[87231]="军团将焚毁这个世界！"
D.Strings[87232]="我们将污染你们脚下的土地！"
D.Strings[87233]="很快，你们就无处可逃了……"
D.Strings[87234]="你就指望元素来为你而战？废物！"
D.Strings[87235]="先祖护佑着你！"
D.Strings[87236]="滚开，凡人！"
D.Strings[87237]="干掉……他……"
D.Strings[87238]="风暴的力量将属于我的主人！"
D.Strings[87239]="荣耀属于军团！"
D.Strings[87240]="我会报答你的。"
D.Strings[87241]="燃烧军团必败！"
D.Strings[87242]="勇士，你救了我们……"
D.Strings[87243]="为了伊利丹大人！"
D.Strings[87244]="元素与此人同在。继萨尔之后，我就再也没见过比这家伙更杰出的萨满了。"
D.Strings[87245]="我们会拿到钥石的！"
D.Strings[87246]="萨满，不需要再进行什么试炼了。风暴守护者的武器已经找到了新主人。"
D.Strings[87247]="去死吧，恶魔！"
D.Strings[87248]="去吧，大地之环的勇士，我的祝福与你同在。艾泽拉斯已经四面楚歌，像你这样的英雄必须挺身而出，迎接挑战。"
D.Strings[87249]="我都到这里了，是不会死在这块石头上的。"
D.Strings[87250]="我千辛万苦才来到这里，可不是为了死在这块石头上的。"
D.Strings[87251]="快！我们必须找到绍恩，否则就来不及了！"
D.Strings[87252]="在我们的客人抵达之前，讨论就到此为止吧。"
D.Strings[87253]="我们唯一能做的就是……我的伤已经支持不了多久了。神灵在召唤我……"
D.Strings[87254]="快！让我们解决这些异端！"
D.Strings[87255]="我认为你们……不合格。"
D.Strings[87256]="我会好好享受碾压你们的快感的！"
D.Strings[87257]="让我们一起干掉敌人！"
D.Strings[87258]="我的力量……消散了。"
D.Strings[87259]="你们痛苦的哀嚎将永世回荡！"
D.Strings[87260]="让我们一起摧毁他们的灵魂！"
D.Strings[87261]="我拥抱深渊！"
D.Strings[87262]="我接受这个挑战……我已经迫不及待了！"
D.Strings[87263]="他们的失败就是我们的胜利！"
D.Strings[87264]="嘿，$n。这只猫咪真大呀！我摸他一下国王应该不介意吧？"
D.Strings[87265]="……那是个正确的决定。那声号角救了我们……所有人。"
D.Strings[87266]="所有反对我们，阻挡我们的人都得死。我愿意成为部落的第一位女王。"
D.Strings[87267]="我们必须立刻从城市中调集援军！做好准备——"
D.Strings[87268]="你也看到他们的进攻有多么迅猛。你自己也在战场上流了血，贝恩。我们的天空迟早会被邪能之火所遮蔽！"
D.Strings[87269]="恐怖卫士……小心他们的编队！坚持住！一个部落，众志成城！"
D.Strings[87270]="我们仍将是一个团结的部落。"
D.Strings[87271]="一个部落……一个领袖……"
D.Strings[87272]="还是个孩子时，我就听说过隐秘通途的传说。那些传说令我渴望成为一个猎人。当我听说组织重建时，我一定要亲眼来看一看。"
D.Strings[87273]="想想我失去的那些朋友……还有我要遵守的诺言。"
D.Strings[87274]="很好，我要求进行复赛！"
D.Strings[87275]="你有什么烦恼吗？"
D.Strings[87276]="呃，那这是谁？"
D.Strings[87277]="别担心，你很快就会收到$G他:她;的消息了。 "
D.Strings[87278]="酋长……"
D.Strings[87279]="愿大地母亲保佑我们。部落怎么办？"
D.Strings[87280]="你打算让谁接替你呢，酋长。没有人能指挥这样一支惨遭重创的部队……"
D.Strings[87281]="没有一支部队的规模足以击败燃烧军团。我们洒在战场上的鲜血已经证明了这一点。我是不会将无辜的人民置于险地的。"
D.Strings[87282]="你对于捍卫部落的勉强态度恐怕很值得推敲。"
D.Strings[87283]="来到这里，你就已经死定了！"
D.Strings[87284]="你在海滩上的表现已经说明你具备领袖所需的素质。当生命遭到威胁……我们的亲人，我们的战士，我们部落的生命……"
D.Strings[87285]="当时机来临时，但愿这些话不是随口说说，而是真正的掷地有声。"
D.Strings[87286]="有的……她……"
D.Strings[87287]="破碎海滩对我们来说是个教训。而现在……知识将成为我们的武器。"
D.Strings[87288]="我们已经见识了他们的力量——我们任何一个人都不可能独自抗衡他们。"
D.Strings[87289]="你准备好去觐见奥丁了吗？"
D.Strings[87290]="带我去见奥丁。"
D.Strings[87291]="奥蕾莉亚！你能听到吗？奥蕾莉亚！"
D.Strings[87292]="我能感觉到恶魔的存在……就在我们头上，$n，在岩架上。"
D.Strings[87293]="当时机来临时，你会做好战斗的准备吗？"
D.Strings[87294]="如果这只个开始，那事情不会这么简单的。如果我们要战斗，那么每个人都要做出牺牲。"
D.Strings[87295]="你的直觉都是对的。无辜的生命确实是宝贵的，但那些魔法……还有我们从未见过的恶魔。我恐怕这只是一个开始。"
D.Strings[87296]="酋长，我明白，但我们不能不顾一切地去和燃烧军团拼命。我们中的一部分人还没有做好战争的准备。这——"
D.Strings[87297]="对我们所有来说……这都是个不幸的年代，但是时候站出来保护我们的人民了——我们所有的人民。"
D.Strings[87298]="这种勇于牺牲的精神——临机决断的果敢——这是一个真正的酋长应有的品质。"
D.Strings[87299]="很好。看来我们都……统一了意见，但我们还需要一个老学究，一个长期研究邪能魔法的人。他可以帮我们理解即将到来的战斗。帮助我们为……战争做好准备。"
D.Strings[87300]="酋长，虽然我们有整个部落作为后盾，燃烧军团的力量也在不断增长。我们既不清楚他们的人数，也不了解他们的真实实力。但就像你说的，我们知道他们的目的。"
D.Strings[87301]="对……而且我们也不会孤军奋战。是时候外出求援了。我准备去拜访一位老朋友。"
D.Strings[87302]="在这个严峻的时刻，让你们的人民做好准备吧。所有人都必须早做准备。"
D.Strings[87303]="我的卫兵怎么办，酋长？我们不能让城市继续这么下去。燃烧军团的威胁已经够大了，现在还要加上联盟——只要我们稍微放松警惕，联盟肯定会大举进攻的。"
D.Strings[87304]="就这样吧。这些卫兵会提醒我们铭记那些牺牲的人们。他们会提醒我们属于同一个部落。他们还会提醒我们——当战争来临时，没有人可以袖手旁观。"
D.Strings[87305]="要不是她在海滩上果断下令，我们都不可能再站在这里。"
D.Strings[87306]="经过仔细检查，这些珠宝似乎是真的。这个委托肯定没问题。$b$b名单上的下一个人是工程学商店的钳工蒂迪。"
D.Strings[87307]="桌上的宝石碎片肯定是真的。它们都有着你曾经见过的那种瑕疵。$b$b名单上的最后一个人是摩尔精品店的黛比·摩尔。"
D.Strings[87308]="桌上的宝石碎片肯定是真的。它们都有着你曾经见过的那种瑕疵。$b$b名单上的最后一个人是黛比·摩尔。"
D.Strings[87309]="在逐个检查过袋中的所有珠宝后，你的眼睛吃惊地越瞪越大。$b$b所有这些宝石都是假的！你必须尽快将这袋珠宝带回蒂凡妮那里去。"
D.Strings[87310]="小心……那个猎犬女王……"
D.Strings[87311]="现在，你就是我手中最大的王牌了，$n。"
D.Strings[87312]="欢迎，法师，是时候开始你的训练了。作为一个法师，你是魔法方面的大师，能够召唤并控制奥术能量听从你的指挥。让我们从基础开始。"
D.Strings[87313]="达拉然会帮忙保护东部王国的，但我绝不允许部落踏足我的城市！"
D.Strings[87314]="我们不能就这样决裂……起码现在不行。求你了，吉安娜！"
D.Strings[87315]="你不能动摇，陛下。即便是此刻，燃烧军团也在想办法加害于你！"
D.Strings[87316]="我父亲死了……还有破碎海滩的灾难……吉安娜又一心复仇……一切都乱套了。"
D.Strings[87317]="恕我直言，您的决定真是大错特错。我们越是等待，反击部落的机会就越渺茫。"
D.Strings[87318]="那就让我错一次吧，吉安娜。这就是我目前的决定。"
D.Strings[87319]="那我就告辞了。我必须去召集六人议会了。"
D.Strings[87320]="谢谢你，吉安娜。"
D.Strings[87321]="当然。我这就召集六人议会。"
D.Strings[87322]="没人能免费过河！"
D.Strings[87323]="生命……死亡……我只是永恒潮汐中的一朵小水花……"
D.Strings[87324]="你们以为自己赢了？这只是一场风暴而已……大海是不可阻挡的。"
D.Strings[87325]="这就是奥丁认可的生命？"
D.Strings[87326]="我建议你先去找卡翠欧娜·麦克雷。她是我最近的一位客户。"
D.Strings[87327]="正在访问XK-47-09祭坛模组。处理中。"
D.Strings[87328]="我丈夫每次总是不收拾干净就跑了，让我来给他收拾烂摊子。$b$b如果你在达拉然遇见他，能不能告诉他一声，就说我爱他比他爱我要深得多？"
D.Strings[87329]="历史模组。守护者们授权守护万神殿在艾泽拉斯的部分力量，以防出现灾难性的损失。初步结果评估成功。"
D.Strings[87330]="我是来检查蒂凡妮·卡蒂亚为你制作的珠宝的。"
D.Strings[87331]="当前状态：腐化。高能级的邪能能量腐蚀了失效保护机制。初步分析建议进行必要的净化以修复功能。"
D.Strings[87332]="能级过低。关闭以保护系统内存。"
D.Strings[87333]="如果你的弹簧松了，我或许可以告诉你该怎么修好它们！"
D.Strings[87334]="我是来检查蒂凡妮·卡蒂亚给你的宝石碎片的。"
D.Strings[87335]="我是来检查蒂凡妮·卡蒂亚给你的珠宝的。"
D.Strings[87336]="想看看我的新款饰品吗？"
D.Strings[87337]="噢，对，他们就在那边的桌子上。它们没什么问题吧？"
D.Strings[87338]="当然了。它们就在那边的桌子上。那工艺可精湛了！"
D.Strings[87339]="我的珠宝？我想是的。它就在靠墙的桌子上。"
D.Strings[87340]="它是我的！我看着它从天上掉下来的！"
D.Strings[87341]="这些不是幽灵，而是昔日的回响。这里发生过一场惨剧。"
D.Strings[87342]="蠢货！蝼蚁！你们一文不值。我要杀光你们！"
D.Strings[87343]="|TInterface\\Icons\\inv_misc_volatileearth.blp:20|t%s的近战范围内没有敌人，开始施放|cFFFF0000|Hspell:196534|h[猛击]|h|r！"
D.Strings[87344]="主人，将我从这个网里放出去，让我来帮助你！"
D.Strings[87345]="我们得去白水溪帮忙，否则就迟了。"
D.Strings[87346]="你们都将臣服于燃烧军团。"
D.Strings[87347]="你们无路可逃。"
D.Strings[87348]="你们所熟悉的一切都将化为邪能火海。"
D.Strings[87349]="你们只是在……拖延时间……"
D.Strings[87350]="你作为大酋长，应该让人民明白，任何神器——或者武器——都不能抵挡团结一致的高岭部族。"
D.Strings[87351]="我们得夺回圣锤，而不是去散步。"
D.Strings[87352]="首先，去那边的架子上挑选一件武器并装备上。作为一个施法者，你无需用你的武器攻击，但它应该是强大的力量之源，能强化你与生俱来的魔法能力。"
D.Strings[87353]="啸天者，你的朋友已经痊愈了。让活人进入大殿可不是常有的事，但我已经照办！"
D.Strings[87354]="从我们在德拉诺的成功来看，我得说，我们真是最佳搭档，$n。"
D.Strings[87355]="欢迎。作为一名火焰法师，你擅长用熊熊烈火烧灼敌人，把他们烧成灰烬。我们将从你最基本的技能——火球术开始。"
D.Strings[87356]="火球术是你最基本的伤害输出技能。它会先造成大量伤害，然后持续烧灼你的对手。使用火球术摧毁这个训练假人吧。"
D.Strings[87357]="你想让谁驻扎在瓦尔莎拉？"
D.Strings[87358]="确定吗？你的勇士在驻扎状态下将无法执行任务。"
D.Strings[87359]="从现在起，我可以帮你管理你的瓦拉加尔战士，并在出现机会或紧急情况时通知你。"
D.Strings[87360]="我想换一个驻扎勇士。"
D.Strings[87361]="小心暗影，那里将是我的狩猎场！"
D.Strings[87362]="看，莫戈斯，黑暗深渊的主宰！"
D.Strings[87363]="粉身碎骨！"
D.Strings[87364]="如果你是来找黑暗的主宰，那你就找对人了。"
D.Strings[87365]="洛克更强大！"
D.Strings[87366]="洛克……不会……碎的……"
D.Strings[87367]="巨石粉碎！"
D.Strings[87368]="略施小计，巨石天降。"
D.Strings[87369]="洛克不会失败！"
D.Strings[87370]="你想派勇士驻扎在哪里？"
D.Strings[87371]="我想派一名勇士驻扎在一片地区。"
D.Strings[87372]="这里现在是我们的土地了，$r！"
D.Strings[87373]="确定要召回你的勇士吗？他们将无法再协助你战斗。"
D.Strings[87374]="我要用你的骨头来装点我的巢！"
D.Strings[87375]="你休想拿走战刃！"
D.Strings[87376]="我要把你扔下悬崖，啄食你的血肉。"
D.Strings[87377]="呱……主母会来找你的……"
D.Strings[87378]="为我复仇，姐妹们！"
D.Strings[87379]="这会很棒的。"
D.Strings[87380]="你走得有点远啊，小$r。"
D.Strings[87381]="我能像挤烂熟透的果子一样挤烂你的脑袋。"
D.Strings[87382]="死在山脉的重压之下吧！"
D.Strings[87383]="压扁你一定会很有趣的。"
D.Strings[87384]="你休想阻止我们！这片土地是我们的。"
D.Strings[87385]="深渊……在召唤……"
D.Strings[87386]="你别想摧毁山脉。"
D.Strings[87387]="这么小的个子……怎么可能……"
D.Strings[87388]="煮熟它！"
D.Strings[87389]="真正的英雄从不单打独斗。这个挑战需要你展现团队合作的谋略和能力。与你的搭档一起通过这个考验吧。$b$b你的队伍准备好了吗？"
D.Strings[87390]="我和雷加尔准备好了！"
D.Strings[87391]="啊呀呀！"
D.Strings[87392]="我杀了你！头儿会为我骄傲的！"
D.Strings[87393]="头儿是山脉之王。我们要带你去见头儿！"
D.Strings[87394]="在山里，蜡烛都能抓住你！"
D.Strings[87395]="蜡烛！我的！"
D.Strings[87396]="为了蜡烛大王！"
D.Strings[87397]="这是我的山！"
D.Strings[87398]="你别想抢走我们的山！"
D.Strings[87399]="我要蜡烛！"
D.Strings[87400]="我咬死你！"
D.Strings[87401]="我们要放过它吗？<不要！>"
D.Strings[87402]="让我们煮了它！<不，生吃了它！>"
D.Strings[87403]="嗷嗷嗷！<骨头又卡在牙齿里了吗？>"
D.Strings[87404]="外脆！<里嫩！>"
D.Strings[87405]="美味的零食！<我先来！我先来！>"
D.Strings[87406]="这是我的地盘！<开饭了！>"
D.Strings[87407]="我抓住它了！<不对，我抓住的！>"
D.Strings[87408]="我要最上面这块！<不，该轮到我了！>"
D.Strings[87409]="这好吃吗？<当然，但要先把它从香脆的铠甲里揪出来。>"
D.Strings[87410]="碾碎他们！<砸死他们！>"
D.Strings[87411]="我讨厌你！<我也讨厌你！>"
D.Strings[87412]="它们可以从新鲜的尸体上收集灵魂，充当灵魂引擎的燃料。"
D.Strings[87413]="那些妄图挑战我的人都是在自寻死路。"
D.Strings[87414]="萨维斯之影也这么说。"
D.Strings[87415]="别动，蝼蚁！我这就来解决你。"
D.Strings[87416]="算你们走运。尽管得意吧，别让我再遇上你们。"
D.Strings[87417]="他们会严阵以待的，因为你真正的力量都在梦魇中。"
D.Strings[87418]="闭嘴，蝼蚁！等你下次张嘴的时候，就该哀嚎求饶了！"
D.Strings[87419]="多么空洞的威胁。你控制不了这个国度，梦魇之王。"
D.Strings[87420]="好个大言不惭的囚徒。哪怕是我的回响，也足以碾压你们！"
D.Strings[87421]="在这里，你的狂吠就像耳旁风。"
D.Strings[87422]="你的把戏控制不了我，走狗！"
D.Strings[87423]="我要折磨你，再杀了你！"
D.Strings[87424]="你们得团结起来才能赢！"
D.Strings[87425]="我要击溃你脆弱的心灵！"
D.Strings[87426]="你会慢慢地、痛苦地衰弱下去。"
D.Strings[87427]="别相信任何人，包括你的同伴！"
D.Strings[87428]="反击！不要让他操纵你。"
D.Strings[87429]="你们的攻击只会让我在归来时更加强大！"
D.Strings[87430]="你们的攻击毫无意义。梦魇会治疗我的！"
D.Strings[87431]="我想帮忙，可你得放我出来。攻击根须！"
D.Strings[87432]="这些根须束缚着我。摧毁它们！"
D.Strings[87433]="闹剧？哈！蝼蚁对真神都这么说话！"
D.Strings[87434]="这肯定是……搞错了……"
D.Strings[87435]="你们不可能……打败……真神……"
D.Strings[87436]="不，不！我拒绝……接受……"
D.Strings[87437]="不要太惊讶。"
D.Strings[87438]="你一文不值！"
D.Strings[87439]="这是什么？别惹我发笑了！"
D.Strings[87440]="入侵者必将受到惩罚。"
D.Strings[87441]="你想找死？好吧！"
D.Strings[87442]="在面对真神的怒火时，凡人还能有什么别的下场呢？"
D.Strings[87443]="反抗萨维斯的人就是这个下场！"
D.Strings[87444]="敢挑战我的人都得死！"
D.Strings[87445]="这是你应得的胜利！但我们得保持警惕。萨维斯仍盘踞在梦魇深处，毫发无伤。你战胜的只是他的影子。"
D.Strings[87446]="如果你真的热爱自然，你就会发现到处都是死亡。"
D.Strings[87447]="每天清晨的献祭可以保佑你一整天。"
D.Strings[87448]="自然从不着急，它只会慢慢地杀死你……让你痛苦地死去。"
D.Strings[87449]="我的工作就是找到自然中的痛苦。"
D.Strings[87450]="在晴朗的日子里坐在阴影中看着尸体腐烂就是最美妙的休息了。"
D.Strings[87451]="看来你被跟踪了，$c！黑暗骑士！"
D.Strings[87452]="对怀有一颗残酷之心的人来说，所有的季节都是美丽的。"
D.Strings[87453]="胜了一场，但还会有更多。快，去艾瑞丁的营地！"
D.Strings[87454]="努力坚持住，$c！"
D.Strings[87455]="鲜花和蛆虫都是上天的杰作。"
D.Strings[87456]="快！我们没有时间犹豫了！"
D.Strings[87457]="你想被丢下吗？快！"
D.Strings[87458]="永远不要放过扼杀美丽的机会。"
D.Strings[87459]="你的战斗力真惊人。我们或许能活下来。"
D.Strings[87460]="这些可怜的灵魂注定要在这里徘徊。难怪这里会孕育出如此的黑暗。"
D.Strings[87461]="来吧，我们继续。"
D.Strings[87462]="一个人独挑大梁可能会被压垮，但如果由许多人共襄盛举，那么或许就能让我们从中学到点什么。"
D.Strings[87463]="总有一天，我会找到它……"
D.Strings[87464]="我们继续前进吧，就快到了。"
D.Strings[87465]="到了！营地就在这儿。我们来找找。"
D.Strings[87466]="恋人……梦想家……还有我。"
D.Strings[87467]="让蛆虫吃掉你的尸体！"
D.Strings[87468]="头儿是最棒的！"
D.Strings[87469]="我要摧毁……我要你流血。"
D.Strings[87470]="等杀了你之后，我会复活你，然后再杀你一次。"
D.Strings[87471]="来吧，$n，放声痛哭吧！"
D.Strings[87472]="我想摧毁一些美丽的事物。"
D.Strings[87473]="看看鲜花是多么喜欢鲜血吧。"
D.Strings[87474]="我在想侏儒算不算当季的食品？"
D.Strings[87475]="被关在笼子里可不是什么光彩的事。"
D.Strings[87476]="千万要保持安静。我正在猎杀$r。"
D.Strings[87477]="你看到那头被我撕掉翅膀的精灵龙扑腾的样子了吗？"
D.Strings[87478]="你好，狩猎大师$n。我很荣幸能为你照料宠物，或者寻找走失的小伙伴。"
D.Strings[87479]="<睁大眼睛，耐心地等待着他的报酬。>"
D.Strings[87480]="<把靴子交给泰图斯。>"
D.Strings[87481]="头儿……会来找你的。"
D.Strings[87482]="我看见隧道了。蜡烛照路！"
D.Strings[87483]="我是来拿回你偷走的珠宝的。"
D.Strings[87484]="我准备好了，无论你派我去哪里，我都会全心全意辅佐盟友，打击敌人！"
D.Strings[87485]="噢，真的吗？你以为我会这么轻易就把东西交出来吗？踩着我的尸体来拿吧！"
D.Strings[87486]="我要立刻赶回吉尔尼斯，召集军队来应对即将到来的风暴。坚强点，勇士。"
D.Strings[87487]="哎呀哎呀，这是谁呀？一个美味的$r自己送上门来了！"
D.Strings[87488]="有时我很希望花也会哭。"
D.Strings[87489]="你要为袭击我的女儿们付出代价！"
D.Strings[87490]="这里现在是我们的家园了。滚出去！"
D.Strings[87491]="你休想从我手中夺走天空。"
D.Strings[87492]="鹰巢……长存。"
D.Strings[87493]="先是一群地老鼠，现在又是这个……"
D.Strings[87494]="纳迦必须为此付出血的代价！救出我的兄弟姐妹们，他们一定会跟着加入这场光荣的战斗的！"
D.Strings[87495]="这是有史以来最好的靴子。它烧起来的话，肯定会比蜡烛还要亮！"
D.Strings[87496]="出什么事了？你对我做了什么？！"
D.Strings[87497]="不要羞愧。你们很勇敢，很光荣。"
D.Strings[87498]="只要敢于战斗，失败并不可耻。"
D.Strings[87499]="我……终于清醒了。我要安息了。告诉泰德里斯，我爱他。"
D.Strings[87500]="我感觉……精神抖擞！再试试吗，勇士们？"
D.Strings[87501]="我必须保护这片土地不受亵渎者的侵害。"
D.Strings[87502]="我听到了……他们正在窃窃私语。"
D.Strings[87503]="我只想睡一觉，可如果我真的睡着了，他们一定回来偷袭我的。"
D.Strings[87504]="那你是什么？你听到了吗？"
D.Strings[87505]="他们说我是个疯子……说谎！"
D.Strings[87506]="别死得太快了，我想听你尖叫。"
D.Strings[87507]="我的植物在渴望鲜血！"
D.Strings[87508]="尽管跑吧，但这只会让你累死。"
D.Strings[87509]="我喜欢痛苦……我是指你们的痛苦，不是我的！"
D.Strings[87510]="你总算从阴影中现身了，恶魔！"
D.Strings[87511]="真了不起！没想到还有人能对抗瓦拉加尔的力量……而他们就站在我面前。"
D.Strings[87512]="我就算是死，也要拉上你！"
D.Strings[87513]="最后的试炼将由我主持。只要战胜我，我就亲手把你们的名字刻在这座圣殿里，并送上勇士应得的奖励。"
D.Strings[87514]="你能不能别来打扰我？去死吧！"
D.Strings[87515]="我的力量远超你往日的对手！"
D.Strings[87516]="你以为我怕你吗？你才是懦夫！"
D.Strings[87517]="小心，勇士们：我会全力以赴！"
D.Strings[87518]="投降吧……否则我要动真格的了！"
D.Strings[87519]="快，朋友。每耽搁一分钟，达古尔就会杀害我们更多的盟友。"
D.Strings[87520]="我要掐死你！"
D.Strings[87521]="看看你们的头脑是否和武器一样厉害！"
D.Strings[87522]="智慧和最锋利的刀剑一样致命！"
D.Strings[87523]="真正的噩梦开始了！"
D.Strings[87524]="每个对手都有弱点。你也一样！"
D.Strings[87525]="我要摧毁你的意志。"
D.Strings[87526]="$n……对，我在离开伊利达雷前听说过你。谢谢。"
D.Strings[87527]="我父亲的古老巢穴。这些岩石依然蕴含着力量，不要惊扰它们。"
D.Strings[87528]="你大老远的跑来，就是为了送死吗……真可悲。"
D.Strings[87529]="这将成为你永远醒不过来的噩梦！"
D.Strings[87530]="那绝对是我所见过的最大块的水晶！"
D.Strings[87531]="你将成为我今天的晚餐。"
D.Strings[87532]="强大的瓦拉加尔！听我召唤！"
D.Strings[87533]="你看起来……很好吃！"
D.Strings[87534]="过来，瓦拉加尔！证明你们的力量！"
D.Strings[87535]="为我而战，瓦拉加尔！为荣耀而战！"
D.Strings[87536]="我就喜欢送上门来的晚餐。"
D.Strings[87537]="乌拉罗格能够驯服任何岩石！他可以——等等，他们是从哪儿来的？！"
D.Strings[87538]="够了！我……认输！你们真是了不起。我说过，你们会得到应得的奖赏。"
D.Strings[87539]="一次可敬的尝试！"
D.Strings[87540]="入侵者？在这儿？！打垮他们！"
D.Strings[87541]="我才刚刚开始呢！"
D.Strings[87542]="你们真以为能击败我吗？"
D.Strings[87543]="我好久没遇到过像样的对手了。来战斗吧！"
D.Strings[87544]="我一直在期待有实力的对手！别让我失望！"
D.Strings[87545]="快！阻止那个哨兵，别让他敲响警钟！"
D.Strings[87546]="我们在阿苏纳见，$n。如果你有什么发现，就来找我。"
D.Strings[87547]="地底之王在驱使奴隶挖掘我父亲的骨头？！他不明白自己在插手什么样的力量。"
D.Strings[87548]="这些卓格巴尔在使用不属于他们的能力。毫无疑问，这肯定和这些石头里残留的强大能量有关。"
D.Strings[87549]="不！我也证明了自己，奥丁。我是神王斯科瓦尔德！这些凡人休想抢走我的圣盾！"
D.Strings[87550]="如果这些所谓的“勇士”不肯放弃圣盾……那就让他们去死吧！"
D.Strings[87551]="放弃圣盾，否则就死！"
D.Strings[87552]="没人能挡我的路！"
D.Strings[87553]="我是不可阻挡的！"
D.Strings[87554]="你高估了自己的能力！"
D.Strings[87555]="又扫除了一个障碍！"
D.Strings[87556]="我所有的计划……都完了……"
D.Strings[87557]="圣盾属于它真正的主人！"
D.Strings[87558]="你休想保住不属于你的东西！"
D.Strings[87559]="这力量属于我！"
D.Strings[87560]="圣盾终于物归原主了！"
D.Strings[87561]="让烈焰……审判你！"
D.Strings[87562]="给我烧吧！"
D.Strings[87563]="让不灭的烈焰烧死你！"
D.Strings[87564]="让烈焰净化你！"
D.Strings[87565]="你的痛苦将永无止境！"
D.Strings[87566]="你将痛苦地死去！"
D.Strings[87567]="求饶吧……让军团放声大笑！"
D.Strings[87568]="瓦拉加尔！保护这座神圣的殿堂！"
D.Strings[87569]="纳瓦罗格？！叛徒！你想带领这些入侵者对抗我们吗？！"
D.Strings[87570]="就用鲜血来评判你有没有这个资格吧！"
D.Strings[87571]="我要抽干你们孱弱的鲜血！"
D.Strings[87572]="无能者必将血洒圣殿！"
D.Strings[87573]="龙骑兵！靠近我！"
D.Strings[87574]="风暴幼龙！过来帮我！"
D.Strings[87575]="龙骑兵，我需要你们的帮助！"
D.Strings[87576]="集结！快集结！"
D.Strings[87577]="坚持住！血战到底！"
D.Strings[87578]="无能的……是我。"
D.Strings[87579]="精彩的战斗！你们可以继续前进了。"
D.Strings[87580]="一切都在他的计划之中。"
D.Strings[87581]="很好。让我亲自来考验一下你们！"
D.Strings[87582]="古尔丹大人将带领我们走向胜利。你们休想阻止。"
D.Strings[87583]="弱者必须死！"
D.Strings[87584]="我才是审判者。"
D.Strings[87585]="你的试炼到此为止了。"
D.Strings[87586]="都结束了。"
D.Strings[87587]="圣殿没有被玷污。"
D.Strings[87588]="结束了：弱者失败了。"
D.Strings[87589]="我会继续警戒。"
D.Strings[87590]="凭借一系列英勇事迹，赫娅赢得了这个神圣的仪式。她将晋升为我麾下的精英瓦格里，她的名字将永远回荡在这座金色的殿堂。"
D.Strings[87591]="你紧张吗，赫娅？这可以理解——"
D.Strings[87592]="我不紧张。就是……有点激动。我一生都在渴望这个荣耀的时刻。"
D.Strings[87593]="这才像真正的瓦格里。"
D.Strings[87594]="凡人闯入者来了！"
D.Strings[87595]="我……我记得他们。在风暴峡湾，他们和他们该死的首领想要奴役我！"
D.Strings[87596]="我在风暴峡湾见过他们。他们的行为既不荣耀，也不道德。"
D.Strings[87597]="搞定了，狩猎大师$n。视野范围内已经没有敌人了。"
D.Strings[87598]="我要亲自把他们赶出这座圣殿！"
D.Strings[87599]="仪式还没有完成。去解决那些入侵者。"
D.Strings[87600]="你休想妨碍赫娅的晋升！"
D.Strings[87601]="愿圣光永远照耀你，赫娅！"
D.Strings[87602]="你们的存在玷污了这场仪式，凡人！"
D.Strings[87603]="赫娅……你来执掌风暴的怒火！"
D.Strings[87604]="乌拉罗格，达古尔控制不了圣锤！他只会毁灭至高岭，而不是征服它！"
D.Strings[87605]="愿圣光常伴你左右，赫娅！"
D.Strings[87606]="沐浴在圣光中吧！"
D.Strings[87607]="风暴来临了！出击，赫娅！"
D.Strings[87608]="无论如何，我都会好好享受它每一刻的。洛克莫拉，碾碎他们！"
D.Strings[87609]="风暴正在你体内汇聚！"
D.Strings[87610]="滚出这座神圣的殿堂！"
D.Strings[87611]="你休想继续玷污这座殿堂！"
D.Strings[87612]="对不起，艾尔……我让你失望了……"
D.Strings[87613]="艾尔……我辜负了你的信任……"
D.Strings[87614]="没有人能抵挡艾尔的选民！"
D.Strings[87615]="无论生死，你都毫无荣誉可言。"
D.Strings[87616]="他们已经知道我们来了。但愿我们的盟友可以拖住他们的主力部队，让我们完成任务。"
D.Strings[87617]="一切都还好吗？"
D.Strings[87618]="我不会让你失望的，艾尔！"
D.Strings[87619]="破碎海滩发生了什么事？"
D.Strings[87620]="我不知道他们能坚持多久。"
D.Strings[87621]="结束了，艾尔。我捍卫了这里的圣洁。"
D.Strings[87622]="我看到有些人回来了。情况看起来不妙。"
D.Strings[87623]="拜托！出什么事了吗？"
D.Strings[87624]="威胁结束了吗？"
D.Strings[87625]="快，钻进桶里去！我来拖住他们，我们下游见！"
D.Strings[87626]="不，我可不干。我自己去找路，到另一边跟你们汇合。"
D.Strings[87627]="用最好的蜡制作魔法蜡烛，配得上蜡烛大王的蜡烛。"
D.Strings[87628]="什么蜡？头儿的话太难懂了。"
D.Strings[87629]="到附近墓地里去偷墓穴里的金币。"
D.Strings[87630]="希望一切都好。"
D.Strings[87631]="酋长还好吗？"
D.Strings[87632]="这是头儿自己发明的语言吗？一点都听不懂。"
D.Strings[87633]="你把食物藏哪儿去了，蛆虫？！"
D.Strings[87634]="头儿没事吧？头儿这是撞到了脑袋，在胡言乱语吗？"
D.Strings[87635]="把这些洞穴里最强壮的那只蜥蜴拖到我脚下来！"
D.Strings[87636]="求求你，你已经把食物都抢光了。"
D.Strings[87637]="快搜！贱民把粮食都藏了起来，不愿献给部队！不战斗者不得食！"
D.Strings[87638]="用你的矿镐从洞穴里储量最丰富的矿脉中挖掘珍贵的金属，将样品带回来给我。"
D.Strings[87639]="我感应到这堵墙的后面有一件强大的神器。小心点，英雄们，如此强大的宝物不可能没有保护措施。"
D.Strings[87640]="这比我预想的要容易。"
D.Strings[87641]="头儿听起来都不像是狗头人了。"
D.Strings[87642]="现在，我要回达拉然了。我们后会有期，$n。"
D.Strings[87643]="伊利丹……现在，你归燃烧军团了。"
D.Strings[87644]="头儿身边的垃圾堆里有宝贝。"
D.Strings[87645]="但愿达格米尔给我留了几个纳迦！"
D.Strings[87646]="这下就好多了！"
D.Strings[87647]="你将与整座至高岭为敌！"
D.Strings[87648]="你的骨头太脆弱了。"
D.Strings[87649]="至高岭是的你葬身之地！"
D.Strings[87650]="尽管跑吧。这改变不了什么。"
D.Strings[87651]="你休想得到卡兹格罗斯的力量！"
D.Strings[87652]="这就是四分五裂的感觉吗……"
D.Strings[87653]="稍等一下，$c……"
D.Strings[87654]="看着，纳瓦罗格，看你的英雄们是怎么死的。"
D.Strings[87655]="<嗝儿>"
D.Strings[87656]="头儿不在，我来帮他暖椅子。"
D.Strings[87657]="已经无路可逃了！你的精华将成为主人的食物！"
D.Strings[87658]="与卓格巴尔作对的人都将面对卡兹格罗斯的伟力！"
D.Strings[87659]="让至高岭吞噬你们！"
D.Strings[87660]="真脆弱！太容易崩溃了！"
D.Strings[87661]="这感觉真不错。"
D.Strings[87662]="有人吗？快来人啊！救命！！！"
D.Strings[87663]="万虫之母！站起来！"
D.Strings[87664]="如果让他们完成召唤仪式，我们就无法靠近达古尔了！"
D.Strings[87665]="她来了！纳拉萨斯会吃掉你们的！"
D.Strings[87666]="对！啊哈哈哈！等等——不！啊啊啊！"
D.Strings[87667]="你将成为纳拉萨斯的食物！"
D.Strings[87668]="纳拉萨斯。纳拉萨斯。纳拉萨斯！"
D.Strings[87669]="没有时间了！我们得立刻攻击达古尔！"
D.Strings[87670]="我很抱歉，英雄们。看来你们要找的宝藏是在这头野兽的身后。"
D.Strings[87671]="寻找完美的书"
D.Strings[87672]="那个牛头人认为你是天定的圣锤之主？真可悲。"
D.Strings[87673]="让他们来吧！来看看违抗掌握了泰坦之力的真王是什么下场吧！"
D.Strings[87674]="抱歉，英雄们，我得走了。但请你们相信，我很为你们的事迹骄傲。我相信在这最后关头，你们不会让至高岭失望。"
D.Strings[87675]="我能像泰坦一样创造世界！"
D.Strings[87676]="群山将吞噬你们的骨头！"
D.Strings[87677]="大地将在我的号令下起伏咆哮！"
D.Strings[87678]="让艾泽拉斯的熔岩之魂吞噬你们！"
D.Strings[87679]="至高岭会彻底吞没你们！"
D.Strings[87680]="我是这个世界的锻造者！"
D.Strings[87681]="卡兹格罗斯之力在我体内流淌！"
D.Strings[87682]="怎么可能？！我……是天选之……"
D.Strings[87683]="那个牛头人看错了你！"
D.Strings[87684]="让圣锤砸扁你们！"
D.Strings[87685]="对。来抢我的圣锤试试啊！"
D.Strings[87686]="我宁愿毁灭这个世界，也不会让你抢走圣锤！"
D.Strings[87687]="只有我能掌握圣锤的力量。"
D.Strings[87688]="我要按我的想法重铸这个世界！"
D.Strings[87689]="圣锤从来都没有选中过你，达古尔。它需要一位真正强大的主人，而你还不够格。"
D.Strings[87690]="成功了，英雄们。在杀了达古尔并夺回圣锤后，卓格巴尔已经崩溃了。虽然距离统一诸族还早，但是至高岭已经恢复了平衡。"
D.Strings[87691]="疯王达古尔的势力已经崩溃了，至高岭要感谢你们，英雄们。现在，我得去处理一些家事了。再见，希望我们下次能在比较平和的情况下重逢。"
D.Strings[87692]="杰斯，这个虚空坩埚有什么用？"
D.Strings[87693]="谢谢你，朋友。要不是你及时出手，我就死定了！"
D.Strings[87694]="坩埚？我们可以用这个装置占卜其他人的下落，或者进行长距离的通讯。\n\n我们甚至可以用它来跟其他位面沟通。\n\n它需要用邪能驱动。目标的距离越远，仪式所需要的能量就越多。"
D.Strings[87695]="让我出去！"
D.Strings[87696]="我干掉了那些将伊利丹引上邪路的人。"
D.Strings[87697]="噢……我的头还是有点晕！"
D.Strings[87698]="那里怎么了？有人吗？嗨！"
D.Strings[87699]="他们好像不太欢迎我们。"
D.Strings[87700]="来吧，抿一口我的药酒。你马上就会好起来的！"
D.Strings[87701]="嘿嘿！你抓不到我！"
D.Strings[87702]="嘿，又是那个丑八怪。"
D.Strings[87703]="我们不能好好相处吗？不能？好吧……这是你自找的！"
D.Strings[87704]="呸呸呸！你的话还真多。"
D.Strings[87705]="看看那些发光的大珠子！我们捅一个看看吧？"
D.Strings[87706]="哈！小菜一碟！"
D.Strings[87707]="我的天呐！是龙！"
D.Strings[87708]="我们走吧！那头龙可不会自己揍自己一顿！"
D.Strings[87709]="噢……坚持住！我……会想办法跟上你的！加油！"
D.Strings[87710]="呼！真是疯狂！我都看不清下面的地面了！"
D.Strings[87711]="帮我个忙，别告诉陈叔我飞得这么高，好吗？"
D.Strings[87712]="哇！这家伙，真的，好强呀！你能击败他吗？"
D.Strings[87713]="耶，你成功了！"
D.Strings[87714]="太棒了！！我都快抓狂了，可你却还是那么淡定！"
D.Strings[87715]="疯狂的冒险！我们探索了沙漠，揍了一条龙，还帮你找到了一些亮晶晶的宝贝！"
D.Strings[87716]="这趟冒险可把我累惨了。我们回迷踪岛去吧。"
D.Strings[87717]="现在还不是时候，$n。"
D.Strings[87718]="破碎海滩只是个开始。联盟肯定会报复的。只要有机会，他们肯定会趁火打劫。"
D.Strings[87719]="|TInterface\\Icons\\inv_misc_monsterspidercarapace_01:20|t附近的|cFFFF0000|Hspell:198235|h[蜘蛛卵]|h|r即将腐化，快摧毁它们！"
D.Strings[87720]="我自由了，可我的同胞们还在上面的高墙上受苦。求求你，救救他们！"
D.Strings[87721]="我们见过那些怪物用这个房间降落到下方的地面上；有了它，我们就能逃出这个地方了。"
D.Strings[87722]="嗯，很有意思吧？"
D.Strings[87723]="“愿夜色在阴影中庇佑我……”"
D.Strings[87724]="退下吧！这个人是带着使命来的。"
D.Strings[87725]="抱歉，请允许我冒昧地打断一下……"
D.Strings[87726]="在索迪尔族长周围堆起柴堆。"
D.Strings[87727]="那真的是$G他:她;吗？"
D.Strings[87728]="那就是$G他:她;吗？"
D.Strings[87729]="我要吞掉你的灵魂！"
D.Strings[87730]="愚蠢的伊利达雷！你也是来送死的吗？"
D.Strings[87731]="小心这个家伙。天知道他有什么能耐。"
D.Strings[87732]="多么可悲的灵魂。你们都不属于这里，却将被永远束缚在这里。"
D.Strings[87733]="|TInterface\\Icons\\Spell_Holy_DivineProvidence:20|t$n受到了|cFFFF0404|Hspell:192067|h[驱逐之光]|h|r的影响！"
D.Strings[87734]="别着急。通过乌萨勒斯，你们死后会比活着时更有价值。"
D.Strings[87735]="蠢货，以为这点力量就能对抗萨格拉斯的代理人了吗？"
D.Strings[87736]="你们低贱的生命，将成为燃烧军团的垫脚石！"
D.Strings[87737]="真稀奇。你们真以为圣光能帮你们抵挡燃烧军团的猛攻吗？"
D.Strings[87738]="保佑你们的圣光在哪儿呢？"
D.Strings[87739]="看，是那个$c！"
D.Strings[87740]="我很好奇，他们找$G他:她;来干什么？"
D.Strings[87741]="我都不知道$G他:她;是个$c。"
D.Strings[87742]="要是我也能参加破碎海滩的战斗该多好。那我就能和$n并肩作战了。"
D.Strings[87743]="那不是$n吗？$G他:她;回来了！"
D.Strings[87744]="啊！这是什么……力量？！"
D.Strings[87745]="不要放过这些无赖！海拉绝不容忍入侵者。"
D.Strings[87746]="让骷髅船员上！"
D.Strings[87747]="你现在打算怎么办？"
D.Strings[87748]="我们不能在这里失去凯恩和奥图里斯。别浪费时间，去帮他们，快！"
D.Strings[87749]="这感觉真是太好了。谢谢你，呃……我该怎么称呼你？"
D.Strings[87750]="你休想再看见这个世界的太阳。"
D.Strings[87751]="自由只是无法实现的迷梦。"
D.Strings[87752]="真是傲慢……你还以为能对抗燃烧军团！"
D.Strings[87753]="让我看看证据。"
D.Strings[87754]="你的眼睛会欺骗你。不要相信它们！"
D.Strings[87755]="嘿，伙计。你看起来不够壮啊……"
D.Strings[87756]="你比我想象中要强大，伙计。"
D.Strings[87757]="这些老兄应该能从你身上学到点什么。"
D.Strings[87758]="我把重物丢了……"
D.Strings[87759]="该死的伊利达雷！你对我做了什么？"
D.Strings[87760]="闭嘴，恶魔。很快就会结束了。"
D.Strings[87761]="我来帮你，朋友。让我们把这家伙赶出泰安诺吧！"
D.Strings[87762]="我要谢谢你让我有了新的目标。我会在沙尔艾兰等你。我想我还是需要一个魔力之源的。"
D.Strings[87763]="我很高兴你能来。"
D.Strings[87764]="雪羽俯冲下来，在你头顶来回盘旋。她带来了一封信！"
D.Strings[87765]="格罗玛什要塞的大门已经封闭了。我们必须严密保护部落的领袖们！"
D.Strings[87766]="带我进入格罗玛什要塞吧。"
D.Strings[87767]="我在寻找一位珠宝加工大师。"
D.Strings[87768]="噢，你在找贾布尔。"
D.Strings[87769]="他几天前刚路过这里，到苦痛山谷去研究鹰身人了。"
D.Strings[87770]="之后我就再也没有见过他了，但愿他没有染上和鹰身人一样的病。"
D.Strings[87771]="你是来对付贾布尔的吗？是的话，就赶紧动手吧！"
D.Strings[87772]="你怎么了？"
D.Strings[87773]="贾布尔被鹰身人攻击了，好不容易才躲了起来。$b$b贾布尔丢了一袋珠宝。贾布尔需要那些珠宝来安慰自己。"
D.Strings[87774]="这是你的袋子，贾布尔。"
D.Strings[87775]="夜眼感激地冲你叫了几声。"
D.Strings[87776]="现在不行，$n。这件事已经让我伤透脑筋了。"
D.Strings[87777]="我今天没什么心情钓鱼。"
D.Strings[87778]="让我们铭记今天的教训，为明天的苦练做好准备。"
D.Strings[87779]="这真是个悲伤的日子。"
D.Strings[87780]="领袖们总是要牺牲许多东西。"
D.Strings[87781]="艾希迪尔把你的事迹都告诉了我。你想要我的印记来给奥丁留下深刻的印象。"
D.Strings[87782]="开始吧，站到高台上来。"
D.Strings[87783]="跪下吧，凡人。"
D.Strings[87784]="|TInterface\\Icons\\inv_misc_leatherscrap_17.blp:20|t%s的近战范围内没有敌人，开始施放|cFFFF0000|Hspell:198520|h[飞翼打击]|h|r！"
D.Strings[87785]="%s打碎了所有残余的冰块，放出了里面的恶鬼！"
D.Strings[87786]="你证明了自己有资格成为瓦尔基拉，但你仍将接受严峻的考验。"
D.Strings[87787]="自豪地戴上我们的印记吧，你或许有资格获得奥丁的祝福。"
D.Strings[87788]="现在，退下吧！"
D.Strings[87789]="这条路的尽头就是墓穴入口。快走吧！"
D.Strings[87790]="看来这个地方确实吸引幽灵。但愿它们能友好一点。"
D.Strings[87791]="我无法相信他去世了。"
D.Strings[87792]="她会带领我们赢得这场战争的。"
D.Strings[87793]="他死得光荣。"
D.Strings[87794]="沃金是中毒了吗，居然让她——呃，没什么。"
D.Strings[87795]="你致敬了吗？"
D.Strings[87796]="我的战斧将以他的名义斩杀敌人。"
D.Strings[87797]="如果让我说的话，部落就应该由兽人来领导！"
D.Strings[87798]="燃烧军团要为他的死付出血的代价！"
D.Strings[87799]="今天将是个反思的日子。"
D.Strings[87800]="暗矛部族将会铭记这一天。"
D.Strings[87801]="我们是不会轻易忘记……酋长所遭受的痛苦的。"
D.Strings[87802]="愿神灵的祝福与他同在。"
D.Strings[87803]="愿他安息。"
D.Strings[87804]="愿森金之子与他的父亲一同安息。"
D.Strings[87805]="愿万灵指引他的道路。"
D.Strings[87806]="不知道我们的人民会怎么样。"
D.Strings[87807]="愿大地母亲保佑他。"
D.Strings[87808]="燃烧军团必须为他们的罪行付出代价。"
D.Strings[87809]="死亡只是新的开始。"
D.Strings[87810]="我向你保证，小家伙，人民不会忘记他的。"
D.Strings[87811]="向那些为我们的福祉而战的人致敬吧。"
D.Strings[87812]="我简直不敢相信。"
D.Strings[87813]="我根本没见过他，可是……我希望他一直好好的，你明白吗？"
D.Strings[87814]="这真是个可怕的悲剧。"
D.Strings[87815]="我这辈子已经见过了太多悲剧。"
D.Strings[87816]="……这对我们所有人都是一个巨大的损失。"
D.Strings[87817]="他总是说部落是一个整体。这是真理，伙计。"
D.Strings[87818]="我们的人民很坚强。不要误会……我们都很难过。"
D.Strings[87819]="牛头人、兽人、巨魔、精灵、地精……被遗忘者。我们都感同身受。"
D.Strings[87820]="很好！你就是我要等的人！"
D.Strings[87821]="贾布尔要找几块没有碎裂的石头，就是鹰身人镶嵌在她们项链上的那两种。$b$b你准备好出发寻找它们之后，就告诉贾布尔一声吧。"
D.Strings[87822]="好了，贾布尔，我准备好了。"
D.Strings[87823]="%s身上开始冒出电光……"
D.Strings[87824]="感谢你的帮助。你出手救了我的命。"
D.Strings[87825]="如果你继续深入的话，就会发现这里还潜伏着更可怕的东西。"
D.Strings[87826]="叛徒完蛋了。谢谢你，我们欠你一个大人情。"
D.Strings[87827]="我可以自己返回地面；但你必须将今天的事告诉其他守望者。"
D.Strings[87828]="愿黑夜的阴影庇护着你，愿月光照亮你的敌人。"
D.Strings[87829]="我没有错，提拉宋。你和你的同伙才是罪有应得！"
D.Strings[87830]="够了！我要搞清奥蕾莉亚是不是在这里，还是抓捕我们的陷阱！"
D.Strings[87831]="他侵入了我的头脑！"
D.Strings[87832]="那些眼睛在窥探我的灵魂。要不是你救了我……"
D.Strings[87833]="|TInterface\\Icons\\ability_warrior_shieldreflection.blp:20|t库塔洛斯施放了|cFFFF0000|Hspell:78939|h[源质壁垒]|h|r！"
D.Strings[87834]="要想得到我的祝福，就得完成古老的瓦拉加尔试炼。"
D.Strings[87835]="勇敢的尝试，但你还不配获得我的祝福。"
D.Strings[87836]="还会……有人来……接替我的……"
D.Strings[87837]="许多人都曾踏上和你同样的道路，但没有人能坚持下去。"
D.Strings[87838]="穿过那座恶魔传送门的旅程相当可怕。稍等一下吧，你准备好之后再告诉我。"
D.Strings[87839]="远处那座建筑肯定就是教堂。带路吧，我跟你走！"
D.Strings[87840]="你要相信你的盟友。真正的勇者从不独行。"
D.Strings[87841]="只要心存希望，就要勇敢前行！"
D.Strings[87842]="去召集你的盟友。别松懈，试炼就要完成了！"
D.Strings[87843]="贾布尔在暗夜精灵的房子里等你。你准备好了就来找贾布尔吧。"
D.Strings[87844]="贾布尔来找好项链，别让鹰身人靠近贾布尔。"
D.Strings[87845]="这些鹰身人不太懂得收藏她们的小饰品。大部分都碎了。"
D.Strings[87846]="贾布尔找到他想找的一种石头了。另一种肯定就在这附近。"
D.Strings[87847]="至于你，勇士……干得好。非常好！"
D.Strings[87848]="贾布尔又需要你的保护了。贾布尔会尽量快一点的。"
D.Strings[87849]="贾布尔不明白，鹰身人对她们的珠宝怎么这么粗心大意的。"
D.Strings[87850]="贾布尔找到另一种石头了。我们该回暗夜精灵那儿去了。"
D.Strings[87851]="看着！我将用我的力量祝福你。"
D.Strings[87852]="|TInterface\\Icons\\Ability_Rogue_SurpriseAttack:20|t%s正在被|cFFFF0000|Hspell:191708|h[突袭]|h|r！"
D.Strings[87853]="|TInterface\\Icons\\ability_bosskilrogg_deadeye:20|t%s开始引导他们的|cFFFF0000|Hspell:190836|h[仇恨]|h|r！"
D.Strings[87854]="|TInterface\\Icons\\Ability_Racial_ShadowMeld:20|t%s即将施放|cFFFF0000|Hspell:191823|h[狂怒冲击]|h|r!"
D.Strings[87855]="|TInterface\\Icons\\Ability_Rogue_ShadowStrikes:20|t%s使用|cFFFF0000|Hspell:191941|h[黑暗打击]|h|r强化了自身的力量！"
D.Strings[87856]="|TInterface\\Icons\\Spell_Shadow_Metamorphosis:20|t%s施放了|cFFFF0000|Hspell:192504|h[恶魔变形]|h|r！"
D.Strings[87857]="|TInterface\\Icons\\Spell_Fire_Volcano:20|t附近出现了一座|cFFFF0000|Hspell:192520|h[火山]|h|r。"
D.Strings[87858]="|TInterface\\Icons\\spell_fire_ragnaros_molteninferno:20|t一座火山被熔岩击中，|cFFFF0000|Hspell:193263|h[爆裂]|h|r并喷发出大量火焰！"
D.Strings[87859]="|TInterface\\Icons\\ability_deathknight_brittlebones:20|t牢房里的反制机关冻结了这个区域，阿什高姆变得|cFFFF0000|Hspell:192517|h[脆弱]|h|r了！"
D.Strings[87860]="我感应到一个强大的德鲁伊。你们竟敢挑战我？"
D.Strings[87861]="你手里拿着什么，德鲁伊？"
D.Strings[87862]="|TInterface\\Icons\\spell_mage_arcaneorb:20|t%s制造出了一股可在墙壁上反弹的能量|cFFFF0000|Hspell:194880|h[脉冲]|h|r。"
D.Strings[87863]="你掌握着乌索克的怒火！不……我是不会输的！"
D.Strings[87864]="|TInterface\\Icons\\Ability_Hunter_MasterMarksman:20|t%s开始|cFFFF0000|Hspell:194289|h[聚焦]|h|r能量光束，使用镜子可以将光束反射到他身上！"
D.Strings[87865]="我只和你分享我的力量，勇士。沐浴在造物之光中吧。沐浴在勇者的光辉中吧！"
D.Strings[87866]="我能感觉到你的狡猾和强大，德鲁伊，但我是不会失败的！"
D.Strings[87867]="这对獠牙有着怎样的力量，污染者？你的战斗力堪比上古半神。"
D.Strings[87868]="你拥有强大的恢复力量，德鲁伊，可我还是能把你撕成碎片！"
D.Strings[87869]="让我们来解决这个家伙吧，没问题！"
D.Strings[87870]="你的力量在燃烧……连月神镰刀都被你扭曲驯服了吗？"
D.Strings[87871]="贾布尔要留在这里研究这些项链。$b$b贾布尔不会忘记你和你给贾布尔的帮助的，$n。"
D.Strings[87872]="继续前进！这才刚刚开始！"
D.Strings[87873]="|TInterface\\Icons\\inv_misc_herb_flytrap:20|t%s向平台四周投掷|cFFFF0000|Hspell:197379|h[残酷陷阱]|h|r！"
D.Strings[87874]="|TInterface\\Icons\\inv_misc_ticket_tarot_vengeance:20|t%s召唤出了一个|cFFFF0000|Hspell:197796|h[复仇的化身]|h|r！"
D.Strings[87875]="|TInterface\\Icons\\inv_throwingchakrum_01_fel:20|t%s投掷出了一把|cFFFF0000|Hspell:197513|h[爆裂月牙刃]|h|r！"
D.Strings[87876]="|TInterface\\Icons\\Ability_Rogue_Shadowstep:20|t%s使用|cFFFF0000|Hspell:197823|h[暗影步]|h|r脱离了队伍，快使用艾露恩之光让她现形！"
D.Strings[87877]="|TInterface\\Icons\\ability_priest_auspiciousspirits:20|t平台周围的阴影中出现大量幽灵！"
D.Strings[87878]="多亏了你，阿佐兰已经死了，这对燃烧军团是个沉重的打击。"
D.Strings[87879]="但我们的任务还远未结束……"
D.Strings[87880]="在你和阿佐兰战斗期间，我从船上的数据里搜集到了一些情报。我们还有很多事情要讨论。"
D.Strings[87881]="我在地下营地里等着你。后会有期，再见。"
D.Strings[87882]="我们必须先讨论一下这次攻击的由来，否则很快我们就没有能够上战场的人了。"
D.Strings[87883]="真是了不起。能通过试炼就是一种胜利，而能这么快地通过更是一个传奇！"
D.Strings[87884]="完成了！骄傲地走出去，品味你的胜利吧。"
D.Strings[87885]="俄瑞斯忒斯不在。他虽然自大，也该在这里等我们的！"
D.Strings[87886]="我将唾弃你的尸体，毒蛇！"
D.Strings[87887]="至于你，外来者，不要踏入贾德维克，否则你就将是被我唾弃的下一具尸体。"
D.Strings[87888]="凡人，在我的王国里？他们休想破坏我的计划！杀了他们！"
D.Strings[87889]="渺小的凡人，你们闯入了我的国度！没人能救你们！"
D.Strings[87890]="傲慢的蝼蚁！见证我所掌握的力量吧！Al''burq wa Alra'ed hiyah！"
D.Strings[87891]="一次小胜而已！赶紧享受吧！\n"
D.Strings[87892]="来吧，风暴的仆从们！保护你们的主人！"
D.Strings[87893]="可恨！麦勒扎，干掉他们，否则我就把你的可悲精华扔进深岩之洲！"
D.Strings[87894]="这些凡人还没死！佐奥拉克，保护你的主人！"
D.Strings[87895]="我的仆从都是废物吗？很好，我要亲自解决你！"
D.Strings[87896]="唔……这些龙卷风根本没用。"
D.Strings[87897]="出发去冒险啦！"
D.Strings[87898]="我听说你知道一个传说，其中描述了一对神秘的拳套？"
D.Strings[87899]="对！让我想想……我是在和陈叔环游世界的时候听说的，那时我们还没找到前往潘达利亚的路。$b$b我们在藏宝海湾的水手之家住过一晚。我在那里遇见了一个自称是托维尔人的大家伙。$b$b我们聊了很长时间，他告诉我他的家乡在一个被黄沙掩埋的地方，叫做奥丹姆。"
D.Strings[87900]="<丽丽的耳朵竖了起来。>$b$b好吧，我刚才说到，有一片被黄沙掩埋的土地叫奥丹姆。"
D.Strings[87901]="我也听说了。"
D.Strings[87902]="我去过那里。"
D.Strings[87903]="噢，那里简直棒极了！我以前在那里呆过一小段时间，真希望能有机会再去一次。$b$b按照故事的说法，几千年前，那里居住着一个名叫伊尔马特的铁匠。他高超的锻造技术远近闻名，打造出的魔法武器能与当地的大气之灵沟通。$b$b他最杰出的作品是一对用纯净的空气精华打造的拳刃。传说他还试图召唤风元素领主来为武器灌注力量。$b$b但结果不怎么美妙。"
D.Strings[87904]="那里非常干燥，遍地黄沙，就像一个特大号的猫窝！我跟陈叔在那里呆过一小段时间，真希望能再去一次！。$b$b按照故事的说法，几千年前，那里居住着一个名叫伊尔马特的铁匠。他高超的锻造技术远近闻名，打造出的魔法武器能与当地的大气之灵沟通。$b$b他最杰出的作品是一对用纯净的空气精华打造的拳刃。传说他还试图召唤风元素领主来为武器灌注力量。$b$b但结果不怎么美妙。"
D.Strings[87905]="根据传说，风元素领主非常愤怒，所以他决定陷害伊尔马特。$b$b他给拳套注入了自身最纯净的精华，因为他知道伊尔马特不可能驾驭这种力量。伊尔马特给这副拳套起名叫“诸天之拳”，并戴着它们飞上了天空，以便好好欣赏自己的作品。但他错了，当他这么做的时候，拳套召来了强大的沙尘暴，完全超出了他的控制！旋风吹散了铁匠的拳套，将他的家园变成了沙漠。$b$b要是这副拳套真的存在该多好啊！我会不惜一切离开这里去寻找它们的！"
D.Strings[87906]="一个胸藏韬略、杀伐果断的酋长。"
D.Strings[87907]="按照部落现任酋长沃金的命令，我任命你——希尔瓦娜斯·风行者，为我们人民的新酋长。"
D.Strings[87908]="你自己玩去吧，小崽子。我今天已经玩腻了。"
D.Strings[87909]="在燃烧军团被打败之前，我们是绝不会停歇的。"
D.Strings[87910]="我改变主意了，我要选其他神器。"
D.Strings[87911]="你对破坏魔怎么看？"
D.Strings[87912]="在伊利丹大人打败了他们的前主人，深渊领主玛瑟里顿之后，这个破坏魔和许多其他恶魔都宣誓效忠于他。我们还有纳迦、破碎者和其他生物为我们效劳。\n\n如果外域之王没有意见的话，那我觉得这样已经足够了。"
D.Strings[87913]="好吧，爸爸。就……就这样吧。我得出发了。"
D.Strings[87914]="丽丽，我说了，不要再一个人跑出去了。"
D.Strings[87915]="我就知道你要啰嗦……看，我有人保护的，还是个武僧宗师。没事的啦！"
D.Strings[87916]="你确定吗，$n？对于这个任务，你比我重要太多了。"
D.Strings[87917]="%s的脸沉了下来。"
D.Strings[87918]="看来我说什么都没用了。好吧，去冒你的险吧。但你一定要平安回来。"
D.Strings[87919]="我决定了，瑟维斯，就用我的力量来为传送门供能吧。"
D.Strings[87920]="跟我来。我的兄弟乌霍已经去寻找一个可供我们降落的“安全”地带了。我们带一头角鹰兽去港口等着，他会发信号告诉我们该在哪里降落。"
D.Strings[87921]="我想要一些钻石，蒂凡妮，你这儿有吗？"
D.Strings[87922]="耶！好了，$n，我们走！"
D.Strings[87923]="等等，瑟维斯。我再考虑一下。"
D.Strings[87924]="当然，我很乐意为我们的事业付出一切。又有哪个恶魔猎手会拒绝呢？"
D.Strings[87925]="我决定了，瑟维斯。我要你来为传送门供能。"
D.Strings[87926]="我的朋友鹤先生能送我去奥丹姆。你就坐我的风筝去吧。"
D.Strings[87927]="鹤先生，送我去奥丹姆，这两条小鱼就归你了。"
D.Strings[87928]="不行，先给一条，等到了再给另一条。不准抱怨！"
D.Strings[87929]="但愿我的兄弟没有一个人去追那头野兽。他有时候……很冲动。"
D.Strings[87930]="蒂凡妮，能请你把这颗钻石切割成开锁器的样子吗？"
D.Strings[87931]="我现在手头没有。但我听说下水道里什么都有。"
D.Strings[87932]="我就算做梦也不想下去，可我想你应该没问题的，毕竟你当了大半辈子的$c。"
D.Strings[87933]="这些设计很有趣，这都是你自己想出来的吗？但这都无所谓，我可以帮你把它们切割出来。"
D.Strings[87934]="给你。下一次，你或许应该先试试自己制作，这样我们俩都能省点时间。"
D.Strings[87935]="那是他的信号！我们着陆，看看他知道些什么。"
D.Strings[87936]="我在熔火之滨的传送门那里等你。"
D.Strings[87937]="别被你的凡人肉眼骗了！燃烧军团已经混入了我们之中！"
D.Strings[87938]="你的眼睛无法让你看到它们看不到的东西。"
D.Strings[87939]="决不能让他们攻破大门！"
D.Strings[87940]="傲慢的家伙！"
D.Strings[87941]="看来我们被发现了。"
D.Strings[87942]="你们以为能轻易逃出我的掌心吗？"
D.Strings[87943]="呃……放开我，怪物！"
D.Strings[87944]="傲慢的术士！你们竟敢号令我的同胞！准备为你们的傲慢付出代价吧！"
D.Strings[87945]="辛菲儿！不！"
D.Strings[87946]="我要碾碎你们这些卑贱的蝼蚁！"
D.Strings[87947]="烧吧！在邪能之火中燃烧吧！"
D.Strings[87948]="你们休想跑掉！我还有账要跟你们算呢！"
D.Strings[87949]="你的脑袋会是个很好的战利品！"
D.Strings[87950]="噢！继续，术士……关闭传送门！"
D.Strings[87951]="我要把你们烧成灰烬！"
D.Strings[87952]="还没结束呢，术士！我要看着你死！"
D.Strings[87953]="我们这里有全世界最珍奇的货物。$b$b你想要什么呢？"
D.Strings[87954]="我想要一些钻石，你这儿有吗？"
D.Strings[87955]="噢，我这儿当然有了。但只有一块。一块来自大洋彼岸的、硕大且珍奇的珍宝。$b$b如果你肯出，唔……两百五十个金币的话，我就把它卖给你，怎么样？你也可以为我工作来充抵货款。$b$b这里最近来一个名叫伊克罗特的讨厌鬼。如果你能帮我干掉他，我就把钻石给你。$b$b所以，你选哪个？"
D.Strings[87956]="（平和）一颗钻石250金也太贵了。25金币怎么样？"
D.Strings[87957]="（激进）一颗钻石就要250金！这太离谱了！我给你10金币。"
D.Strings[87958]="（平和）200金也太高了。75金？"
D.Strings[87959]="（激进）你看，我是不可能给你200金的。35金怎么样？"
D.Strings[87960]="（平和）125金差不多了，但还没到我的心理价位。40金吧？"
D.Strings[87961]="（激进）125金也不行。我觉得35金已经很公道了。"
D.Strings[87962]="（平和）我同意你说的100金的价钱，但我恐怕只能给你50金。不行的话就算了。"
D.Strings[87963]="（激进）还是太贵了。我最多只能出到40金。"
D.Strings[87964]="25金币就想买走这颗钻石之王？这不可能。$b$b但你看起来是个明白人。我可以只收你200金币。"
D.Strings[87965]="我是想跟你做生意，可不是让你来羞辱我的。250金币一口价，不买就算了。$b$b当然，你还是可以选择为我做事来换取它，如果你想选那条路的话。"
D.Strings[87966]="你提价了，所以我也该降点价，是吧？我太熟悉这个交易套路了。$b$b很好，我给你个最低价，175金币，不买就算了。$b$b当然，你还是可以选择为我做事来换取它，如果你想选那条路的话。"
D.Strings[87967]="你没必要用这种口气跟我说话，$g先生:女士;。跟穷光蛋打交道还真是麻烦。$b$b125个金币就要害你破产了吗？"
D.Strings[87968]="拜托，你肯定没那么穷的吧？$b$b好吧，我就再让一步。100个金币怎么样？对于极品钻石来说，这个价钱很公道了。"
D.Strings[87969]="我不想再跟你讨价还价了。$b$b一百二十个金币，不要就算了。$b$b当然，你还是可以选择为我做事来换取它，如果你想选那条路的话。"
D.Strings[87970]="要不是你这么讨人喜欢，我才不会跟你做这笔生意呢。$b$b不过我喜欢你。你很固执，而且很会砍价。$b$b好吧，我就50个金币卖给你了。"
D.Strings[87971]="好吧，100个金币，这是最公道的价钱了，不要就算了。$b$b当然，你还是可以选择为我做事来换取它，如果你想选那条路的话。"
D.Strings[87972]="支付250金币。"
D.Strings[87973]="支付175金币。"
D.Strings[87974]="支付120金币。"
D.Strings[87975]="支付200金币。"
D.Strings[87976]="支付125金币。"
D.Strings[87977]="支付100金币。"
D.Strings[87978]="支付50金币。"
D.Strings[87979]="我已经把伊克罗特干掉了。"
D.Strings[87980]="我看到你带来了一桌丰盛的宴席。你不打算跟我分享吗？"
D.Strings[87981]="你非要用这些美食来奚落我吗？在酣畅淋漓的较量之后，我的瓦拉加尔最需要一顿盛宴了！"
D.Strings[87982]="这是你的钻石。跟你做生意真是愉快。下次再来哦。"
D.Strings[87983]="你想要什么？力量？荣耀？小心点！我的战士们的饥渴是永无止尽的！"
D.Strings[87984]="我的耐心有限。在我们开打前献出你的盛宴，否则你就别想再踏入这光辉的圣殿！"
D.Strings[87985]="动手吧，$n！"
D.Strings[87986]="恶魔……得去警告其他人。"
D.Strings[87987]="呃！快离开这儿！快走！"
D.Strings[87988]="这怪物总算死了，圣物也回归了。我的灵魂终于能离开这里了……"
D.Strings[87989]="我要再对你说一声谢谢。我会找到你朋友的灵魂，并确保他们不会滞留在这里的。"
D.Strings[87990]="|TInterface\\Icons\\spell_shadow_carrionswarm:20|t%s开始施放|cFFFF0000|Hspell:198947|h[腐肉风暴]|h|r！"
D.Strings[87991]="你闻到他们随风而来的气味了吗？燃烧军团的入侵已经开始了。"
D.Strings[87992]="我想预览一下我们可以选择的强化路线。"
D.Strings[87993]="你确定吗？你同一时间只能选择一种强化路线。"
D.Strings[87994]="还有其他人……我马上去警告他们！"
D.Strings[87995]="把他们挡在大门外！"
D.Strings[87996]="他们一直都在这里！"
D.Strings[87997]="泽宁，小心！"
D.Strings[87998]="秀兰女士向你问好！"
D.Strings[87999]="是秀兰女士派你来杀我的？"
D.Strings[88000]="谢谢你告诉我。等解决了你，我再去找她算账！"
D.Strings[88001]="我们会给你报仇的！必须解决这一切。跟上那个怪物！"
D.Strings[88002]="肮脏的$r，我要把你的脑袋献给泰菲缪斯大人！"
D.Strings[88003]="泰菲缪斯大人……我辜负了你……"
D.Strings[88004]="快跑，朋友！从传送门逃出去！"
D.Strings[88005]="这些伤口……没法愈合。我们必须尽快结束这一切！"
D.Strings[88006]="泽宁……"
D.Strings[88007]="杀掉……那个怪物。找到……雄鹰之爪……"
D.Strings[88008]="路上没人！快！"
D.Strings[88009]="你干了什么？嘶……"
D.Strings[88010]="潮汐主母！他们在削弱我！"
D.Strings[88011]="你对我……嘶……做了什么？"
D.Strings[88012]="嘶……我的力量消失了！"
D.Strings[88013]="嘶……嘶……"
D.Strings[88014]="我要为此砍掉你的脑袋。嘶……"
D.Strings[88015]="有哨兵！消灭它，别让它发出警报！"
D.Strings[88016]="那个艾瑞达正在召唤恶魔！"
D.Strings[88017]="是传送法师！干掉他们，别让他们召唤援军！"
D.Strings[88018]="你休想干扰猎犬女王的工作！"
D.Strings[88019]="我被那个艾瑞达的传送魔法击中了……我需要一点时间来恢复。"
D.Strings[88020]="登上前面的高地，观察一下局势吧。"
D.Strings[88021]="我们的任务至关重要！"
D.Strings[88022]="你好，$n。幸好我找到你了。你得尽快赶去月光林地。"
D.Strings[88023]="等你处理完达拉然的事以后，我会去找你的。"
D.Strings[88024]="你来了。这边，$n。阿苏纳在等着呢。"
D.Strings[88025]="该功能尚未开放测试。你已经直接完成了本目标。"
D.Strings[88026]="我看到了……入侵者！"
D.Strings[88027]="我……什么都看不见……"
D.Strings[88028]="太棒了！想想这些书里有多少知识吧！"
D.Strings[88029]="而且它们还能为我们提供力量……"
D.Strings[88030]="这里！这就是你要找的书，朋友！"
D.Strings[88031]="拿上它！我们离开这里，别让贾格诺斯发现了！"
D.Strings[88032]="|TInterface\\Icons\\ability_fixated_state_red:20|t一条刀喉鲨鱼闻到了你的血腥味！快返回陆地！"
D.Strings[88033]="有了它，我们就能够侵入军团的世界，包括阿古斯。"
D.Strings[88034]="你还不够我的宝贝们塞牙缝的，将就着吃吧！"
D.Strings[88035]="可是……谁来喂我的小宝贝呢？"
D.Strings[88036]="你赶上了晚餐……我的宠物们可以大快朵颐了！"
D.Strings[88037]="托维斯夫人！入侵者过来了！"
D.Strings[88038]="离那座尖塔远点儿！"
D.Strings[88039]="我要活的！死兔子太没挑战性了！"
D.Strings[88040]="我要亲手解决这些入侵者！"
D.Strings[88041]="如你所愿，泰菲缪斯大人。"
D.Strings[88042]="主人的意志必将实现！"
D.Strings[88043]="看来……跨过那座传送门……不是什么好主意……"
D.Strings[88044]="现在不行……伤口很严重。那些猎犬……别让它们靠近你。"
D.Strings[88045]="我猜你的法师是对的……扭曲虚空中的时光流动非常疯狂。至少我坚持到了……警告你的时候。"
D.Strings[88046]="不……可是……别去教堂。我伤得太重了……好冷……"
D.Strings[88047]="这边……这边！"
D.Strings[88048]="这场审判该结束了！"
D.Strings[88049]="很好。火球术是一个强大的法术，但施法时间比较长。有时候你需要一些更加快捷的法术。让我来教你释放炼狱冲击吧。"
D.Strings[88050]="炼狱冲击不仅是瞬发的，而且它必然会造成爆击。这一点在稍后的教学中很重要。先用炼狱冲击消灭那边的软泥怪吧。"
D.Strings[88051]="我无法相信他真的走了。"
D.Strings[88052]="他死得很光荣，是为了保护他的人民而死。他是真正的国王。"
D.Strings[88053]="他的勇气鼓舞了我们所有人，即使在死后依然如此。他的精神永远与我们同在。                                                                                                                                                                                                                                                                                                                                                                                                  "
D.Strings[88054]="纳瑟尔！响应主人的召唤吧！"
D.Strings[88055]="我的战斧从不落空。"
D.Strings[88056]="玛法里奥就在东边的兽穴旁等你。跟我来。"
D.Strings[88057]="自大分裂以来，许多强大的德鲁伊就在瓦尔莎拉接受塞纳留斯的教导。"
D.Strings[88058]="他们掌握着古老而且无与伦比的德鲁伊知识。想要阻止燃烧军团，他们的力量必不可少。"
D.Strings[88059]="燃烧军团的到来打破了世界的平衡。我在翡翠梦境中感到了巨大的不安。"
D.Strings[88060]="想开启道路，进入这座德鲁伊共同的古老家园可不容易。希望你已经准备好了。"
D.Strings[88061]="我的邪能秘术必将吞噬你们！"
D.Strings[88062]="前面有一具高等精灵的尸体。看起来好像是……"
D.Strings[88063]="你把神器带回来了！干得好，$n！"
D.Strings[88064]="你还在这儿跟我废什么话？快去打恶魔！"
D.Strings[88065]="喜欢我的新长剑吗？靠近点儿。"
D.Strings[88066]="这个仪式能把我们的力量集中到传送门上。必须保持它的稳定！"
D.Strings[88067]="很好！道路开始成型了！它越来越稳定了！"
D.Strings[88068]="梦境之路开启了！各位，干得好。"
D.Strings[88069]="女王的子嗣就快孵化了。"
D.Strings[88070]="看来我们要被大部队包围了，还是把这个破地方留给恶魔吧。"
D.Strings[88071]="小心！他们躲在地下！"
D.Strings[88072]="入侵开始了！快去法师区召集我的兄弟们，勇士！"
D.Strings[88073]="这具尸体属于一个年轻的高等精灵。奥蕾莉亚没有这么年轻。"
D.Strings[88074]="继续前进，$n！在为死去的索迪尔复仇之前，我是不会回贾德维克的！"
D.Strings[88075]="我的烈焰将烧尽你们的血肉。"
D.Strings[88076]="我的大军将吞食你的灵魂！"
D.Strings[88077]="我的到来昭示着末日的降临。"
D.Strings[88078]="你太迟了。末日之劫早就已经发动了。"
D.Strings[88079]="你们不过是低贱的棋子。"
D.Strings[88080]="没有人能抗拒我的吻。"
D.Strings[88081]="在萨格拉斯的烈焰中燃烧吧！"
D.Strings[88082]="来吧，孩子们。吃掉这些敌人。"
D.Strings[88083]="你的死亡只会让我高兴。"
D.Strings[88084]="靠近点，我的小朋友。"
D.Strings[88085]="迎接既定的命运吧。"
D.Strings[88086]="所有世界都将臣服于军团。"
D.Strings[88087]="臣服于萨格拉斯的意志吧。"
D.Strings[88088]="你的命运之线走到头了。"
D.Strings[88089]="这一切很快就会结束的。"
D.Strings[88090]="投降吧，我可以饶你不死。"
D.Strings[88091]="去警告蛛王沃拉斯！"
D.Strings[88092]="你的灰舌战士死得太不是时候了。"
D.Strings[88093]="快，杀了那个恶魔猎手！"
D.Strings[88094]="现在，来考验考验你们！"
D.Strings[88095]="我的生命……属于审判庭！"
D.Strings[88096]="审判庭……必将延续！"
D.Strings[88097]="你属于……审判庭！"
D.Strings[88098]="我该怎么坚持下去？"
D.Strings[88099]="没有了瓦里安国王，我们该怎么办？"
D.Strings[88100]="我们的国王……走得太早了。"
D.Strings[88101]="准备接受审判吧！"
D.Strings[88102]="你的尸骨，会成为尼斯卡拉的铺路石！"
D.Strings[88103]="我们的魔犬又有肉吃了！"
D.Strings[88104]="大审判官一定会享受亲手拷问你们的快感！"
D.Strings[88105]="哈哈哈……你们这些蠢货都得死！"
D.Strings[88106]="我们无处不在……"
D.Strings[88107]="你们是躲不掉的。"
D.Strings[88108]="没用的废物！臣服于燃烧军团的力量吧！"
D.Strings[88109]="愚蠢的凡人！谁都救不了你们！"
D.Strings[88110]="你们死到临头了！你们的生命归审判庭了！"
D.Strings[88111]="大宗师！我有个天大的好消息要告诉你！"
D.Strings[88112]="那边！又一个骗子！"
D.Strings[88113]="那个也是！杀了它！"
D.Strings[88114]="我又标记了一个！找到它！快！"
D.Strings[88115]="又一个！抓住它！"
D.Strings[88116]="又发现一个！我快数不清了！"
D.Strings[88117]="%s“嘭”地一声神奇地消失了。"
D.Strings[88118]="我有话要跟你说，联盟的勇士。马上来跟我谈谈吧！"
D.Strings[88119]="成功了，朋友！传送门关了！他追不过来了。"
D.Strings[88120]="我们得找到那件武器，才能打败贾格诺斯！这本书就是关键！"
D.Strings[88121]="|TInterface\\Icons\\Spell_Nature_Earthquake:20|t萨卡尔将军开始施放|cFFF00000|Hspell:197810|h[邪恶重击]|h|r！"
D.Strings[88122]="我知道在哪儿能找到关于创世之柱的书籍，但那里可能有点……危险。"
D.Strings[88123]="这个平台非常完美。"
D.Strings[88124]="那我们就别再浪费时间了。我来建造熔炉——帮我盯着点地平线！"
D.Strings[88125]="我们成功了，$n。啊，这片森林一点都没变！"
D.Strings[88126]="古老的魔力保护着梦境林地。这里，是荒野中所有兄弟姐妹的庇护所。"
D.Strings[88127]="它要飞走了！"
D.Strings[88128]="啊，风暴已经开始酝酿。"
D.Strings[88129]="保持警惕，燃烧军团的刺客无处不在。"
D.Strings[88130]="抓紧了！我们要着陆了。"
D.Strings[88131]="那群蠢货居然放逐我。我会掌握这种新的魔法，并给他们点颜色看看的！"
D.Strings[88132]="以三大王国的名义……小心，我们有伴儿了！"
D.Strings[88133]="我们还有很多事要做，但时间却非常有限。你准备好之后，我们就开始。"
D.Strings[88134]="问候"
D.Strings[88135]="今天的风要将你吹向何方呢？"
D.Strings[88136]="送我去见武士奥罗。"
D.Strings[88137]="虫语者们自以为聪明，可他们却在这里留下了满地的魔法痕迹。要想通过我的传送门抓一个出来就相对容易了。"
D.Strings[88138]="这次召唤会消耗我的许多力量。准备战斗！"
D.Strings[88139]="小心点！这里的幽灵身上散发着黑暗能量。我们最好别靠得太近。"
D.Strings[88140]="这里有多深？这条楼梯好像没有尽头似的。"
D.Strings[88141]="这条路被堵住了！"
D.Strings[88142]="公会银行"
D.Strings[88143]="入侵者！休想再前进了！"
D.Strings[88144]="坚持住，$c！他控制的幽灵似乎想撕碎我们！"
D.Strings[88145]="我们得溜过去，我可不想被撕成碎片。"
D.Strings[88146]="卑鄙的恶魔！"
D.Strings[88147]="别以为你赢了！守护者，履行你的职责！"
D.Strings[88148]="你的存在未经授权。启动清除协议。"
D.Strings[88149]="我不喜欢那种声音。"
D.Strings[88150]="爆击系统失效。正在……关闭……"
D.Strings[88151]="保持警惕！埃瑞丁恐怕不会放过我们。"
D.Strings[88152]="神器大厅好像就在前面。继续前进吧。"
D.Strings[88153]="这就是你要找的东西？卡拉赞的神器属于此地，我不会让它们被抢走的！"
D.Strings[88154]="你没有权利拥有这些神器，恶魔！我要以圣光之名收回它们！"
D.Strings[88155]="你的圣光照不到这里，牧师！"
D.Strings[88156]="如果想要乌萨勒斯，术士，那就来拿吧！"
D.Strings[88157]="快，追上他！我只会拖你后腿……"
D.Strings[88158]="你真是个固执的家伙。"
D.Strings[88159]="很好！既然你这么想要逆风收割者的力量，我就演示给你看看吧！"
D.Strings[88160]="乌萨勒斯要饱餐一顿了！"
D.Strings[88161]="不！我是不会失败的！"
D.Strings[88162]="成功了。黑暗骑士被击败了。"
D.Strings[88163]="现在，我可以取回这些失窃的神器，让它们物归原主了。"
D.Strings[88164]="你真是个出人意料的盟友，$c。这件武器归你了。但愿它能扭转战局。"
D.Strings[88165]="黑暗骑士输了，但他们恐怕很快就会重整旗鼓。我们最好赶快离开。"
D.Strings[88166]="你好，大德鲁伊巨蹄。我们是千里迢迢赶来向你求助的。"
D.Strings[88167]="塞纳留斯之子，我听到了这片土地的尖叫。军团威胁到了我们所有人。"
D.Strings[88168]="被燃烧军团连根拔起的树木在痛苦地呻吟。我们的世界，以及梦境，都危在旦夕。"
D.Strings[88169]="那我们得赶快行动，准备好古老的战争武器。"
D.Strings[88170]="没有比$n更适合的任务人选了。"
D.Strings[88171]="很好。你的任务可不容易，但我会尽全力帮你的。"
D.Strings[88172]="你以为我会忘记你吗，圣骑士？破碎海滩只是个开始……"
D.Strings[88173]="我一直在观察你——你的力量已经相当强大了。现在，我的拳头要把你软弱无力的身躯抓过来，结束这场由我一手导演的闹剧。"
D.Strings[88174]="燃烧军团的力量正在增长。我们不能再浪费时间了。"
D.Strings[88175]="我很久没来过这里了。我担心这座塔已经开始荒废。抱歉，这里有点乱。"
D.Strings[88176]="呵呵，我还记得我刚来的那一天。我那时候还年轻，满心忐忑……听从肯瑞托的安排来跟随著名的法师麦迪文学习。"
D.Strings[88177]="你很快就会来见我的……"
D.Strings[88178]="要借眼罩吗？其他学生试了都说好，它们可以帮助你忽视那些讨厌的幻象。"
D.Strings[88179]="呃……不了，谢谢你。我能问问，其他学生都怎么了吗？"
D.Strings[88180]="我不是第一个被派来跟随麦迪文学习的法师。但只有我成为了他的学徒。"
D.Strings[88181]="赢得他的信任可不容易。打扫图书馆实在不是值得称道的开端，但它让我明白，对于麦迪文来说，任何事都是一种考验。是为了迎接……更伟大的命运而必须的准备。"
D.Strings[88182]="看来……我们年轻的小探子总算来了。"
D.Strings[88183]="结束这场可悲的闹剧吧。"
D.Strings[88184]="你成功了！现在，我们先做一个简单的提取……"
D.Strings[88185]="熔炉已经准备好了！快，过来！"
D.Strings[88186]="荒野的力量在我们体内流淌。"
D.Strings[88187]="铁匠铺的占领点已经刷新"
D.Strings[88188]="金矿的占领点已经刷新"
D.Strings[88189]="伐木场的占领点已经刷新"
D.Strings[88190]="农场的占领点已经刷新"
D.Strings[88191]="兽栏的占领点已经刷新"
D.Strings[88192]="我要让那个恶魔闭嘴！"
D.Strings[88193]="今天，灰烬使者获得了新生……成为了超出我们敌人想象的存在！"
D.Strings[88194]="于是，辛艾萨莉之心召来了风暴，风暴以隆隆的雷声作为回应，将女王的仁慈播散到了全世界。"
D.Strings[88195]="听从我的召唤，风暴。将你们的力量赋予这把利刃吧！"
D.Strings[88196]="它……真美。"
D.Strings[88197]="我们就别再待在这里看有没有恶魔追来了。狮鹫正在平台上等着送我们去达拉然呢。"
D.Strings[88198]="审判庭……必胜！"
D.Strings[88199]="你们这些蠢货，居然敢到这里来！"
D.Strings[88200]="大审判官阁下一定会很高兴的。使徒，你可以去解决这个渣滓了！"
D.Strings[88201]="对！这一定很棒！我要去告诉老爸。"
D.Strings[88202]="诱捕者打晕了玩家，然后将温蕾萨关进笼子，带着她逃跑了。"
D.Strings[88203]="快逃命吧！别来找我了！"
D.Strings[88204]="我已经了解过你的事迹了，我想你就是最适合这个任务的英雄！"
D.Strings[88205]="我们会救你的，俄瑞斯忒斯。有奥蕾莉亚的线索了吗？"
D.Strings[88206]="$n吸收了一名荣耀的先祖的力量。"
D.Strings[88207]="老鼠是好朋友。除非老鼠敢咬我，咬我的老鼠都变成了美餐。"
D.Strings[88208]="$n大人，我能耽误您一点时间吗？"
D.Strings[88209]="很好，你可以通过传送门前往达拉然巨坑，然后往北飞。他希望你能尽快赶去！"
D.Strings[88210]="来吧，我们去找奥蕾莉亚，结束这一切。"
D.Strings[88211]="我们会小心的。你发现奥蕾莉亚的踪迹了吗？"
D.Strings[88212]="在圣光中安息吧，俄瑞斯忒斯。"
D.Strings[88213]="德鲁伊！我感觉到你们在现实世界里。"
D.Strings[88214]="我在翡翠梦境中的巢穴遭到了攻击。我需要你的帮助，快！"
D.Strings[88215]="如果你有需要的话，我已经给你准备了一头角鹰兽，或者你也可以自行前往目的地。如果你还有疑问的话，我也会尽力帮你解答的。"
D.Strings[88216]="好了，好了！我投降。我去其他地方打猎了。"
D.Strings[88217]="很好，你赢了！我会找到更好的猎场的。"
D.Strings[88218]="我上次离开时，留下了一点……安全措施。这些高墙后面埋藏着无数秘密，许多人都会不择手段地想要得到它们。"
D.Strings[88219]="是哨兵！小心！"
D.Strings[88220]="是结界！又有哨兵来追我们了。幸好我还留了一手。"
D.Strings[88221]="这边！这是你要找的圣物吗？"
D.Strings[88222]="邪恶的梦魇兽，你们休想拿走我的利爪！"
D.Strings[88223]="你或许有足够的资格，但是如果你想戴上我的利爪保卫这个世界，那你就必须尽快把它们夺回来。此时此刻，我感知到敌人正在涌来！"
D.Strings[88224]="噢，亲爱的！入侵者又来了！"
D.Strings[88225]="这是个黑暗的时代，$n。我很高兴有你在这里。"
D.Strings[88226]="我该怎么前往圣光之愿礼拜堂？"
D.Strings[88227]="肯瑞托已经在城市底下的一座大厅里建起了通向位于希尔斯布莱德丘陵的达拉然旧址的传送门——那里离圣光之愿礼拜堂很近。$B$B鲁因广场的传送台可以将你传送到大厅里。我已经帮你在地图上标记出来了。"
D.Strings[88228]="|TInterface\\Icons\\ability_demonhunter_felrush:20|t伊莉萨娜·拉文凯斯即将对你施放|cFFFF0000|Hspell:197484|h[黑暗冲锋]|h|r！"
D.Strings[88229]="|TInterface\\Icons\\ability_bosskilrogg_deadeye:20|t伊莉萨娜·拉文凯斯的|cFFFF0000|Hspell:197674|h[眼棱]|h|r开始追踪你了！"
D.Strings[88230]="|TInterface\\Icons\\spell_fire_felfirenova:20|t%s开始施放|cFFFF0000|Hspell:199828|h[混乱新星]|h|r！"
D.Strings[88231]="我要给你我的祝福，$n。有了它，别人就会知道你是我选定的勇士。"
D.Strings[88232]="快去警告其他人。醒醒！"
D.Strings[88233]="唔，看来我留下的保护措施被篡改了。看好周围，我来打开通道。"
D.Strings[88234]="|TInterface\\Icons\\spell_warlock_demonsoul:20|t你受到了|cFFFF0000|Hspell:194960|h[灵魂回响]|h|r的影响！"
D.Strings[88235]="噢，天呐！我讨厌暴力！但愿这能尽快结束。"
D.Strings[88236]="%s倒在了地上！"
D.Strings[88237]="小心点，朋友。有人看见这里有恶魔出没。"
D.Strings[88238]="熊怪们最近的行为很奇怪……"
D.Strings[88239]="救命！这些大坏蛋就是不肯放过我！"
D.Strings[88240]="离我远点，你这大、大……大笨蛋！"
D.Strings[88241]="我来治疗你，守护者！"
D.Strings[88242]="站到我的法阵里接受治疗吧，守护者。"
D.Strings[88243]="噢，这一定很疼吧。对不起！"
D.Strings[88244]="嗷！嗷！嗷！我需要休息一会儿。"
D.Strings[88245]="我没事，休息一会儿就好了。"
D.Strings[88246]="这些敌人数量众多。我因为低估了敌人，付出了生命的代价。这次，我不会再犯同样的错误了！"
D.Strings[88247]="荒野的生灵，我需要你们的帮助！"
D.Strings[88248]="保护我们的治疗者和施法者。决不能让我们的盟友倒下！"
D.Strings[88249]="坚持住，防御者们！我们绝不向这些入侵者投降！"
D.Strings[88250]="他们流出的血液会烧灼身下的土地。别让他们碰到我们的防御者！"
D.Strings[88251]="控制住这些敌人。你可以让他们在指定的地方倒下！"
D.Strings[88252]="小心！梦魇的腐蚀已经扩散到那些树上了！"
D.Strings[88253]="巨熊之心永不动摇！守住阵线，英雄！"
D.Strings[88254]="翡翠梦境是个天堂，是理想的世界。我是不会让它被摧毁的！"
D.Strings[88255]="不能放任那些施法者的攻击！我们必须尽快解决他们！"
D.Strings[88256]="那些治疗者只会让战局更加艰难。我们得想办法首先解决他们！"
D.Strings[88257]="坚持住，守护者。我感觉到了灵魂深处涌出的寒意。"
D.Strings[88258]="愚蠢的熊！你落入了我的陷阱！"
D.Strings[88259]="这是什么巫术！？萨维斯，等我恢复自由，我一定要撕碎你那邪恶的喉咙！"
D.Strings[88260]="不，乌索克。下一次，你的獠牙就将听从我的命令！"
D.Strings[88261]="你休想活着见到扎勒萨尔！"
D.Strings[88262]="我会抵抗你，直到最后一刻，篡位者！我绝不会屈服于你这样的货色！"
D.Strings[88263]="我是梦魇之王！我见识过上古之神的力量。颤抖吧！"
D.Strings[88264]="嗷嗷！！！"
D.Strings[88265]="英雄！萨维斯说得对……他的力量……无人能挡。我不可能一直拦着他。"
D.Strings[88266]="快转身逃跑吧，否则就迟了！"
D.Strings[88267]="你来得正是时候。我已经受够这些肮脏的野兽了！"
D.Strings[88268]="萨维斯会为我复仇的……"
D.Strings[88269]="战斗怎么样了？看来达拉然是才出狼窝，又入虎穴啊。$b$b不过这里至少暖和一些。我也必须承认，在离卡拉赞这么近的地方勾起了我不少的回忆。"
D.Strings[88270]="我能帮什么忙吗，大法师？"
D.Strings[88271]="把那本书送到达拉然的茉德拉手里。我很快就会赶上你的。还有……谢谢你。"
D.Strings[88272]="第六个在这儿，我们开始吧。"
D.Strings[88273]="泽里法克斯会指导我们的。你研究过仪式了吗，侏儒？"
D.Strings[88274]="好的，好的。不用担心我，急性子！我知道该怎么做。"
D.Strings[88275]="我需要大家一起来引导传送门。这个仪式需要我们绝对的专注！"
D.Strings[88276]="不用担心我们的集中力。我们还是祈祷这个新人能撑得住吧。"
D.Strings[88277]="你还在等什么，菜鸟？开始吧！"
D.Strings[88278]="你的力量很惊人，术士。仪式开始了！"
D.Strings[88279]="做好准备！我们将要史无前例地深入虚空。天知道我们会发现些什么！"
D.Strings[88280]="集中精神……我感觉另一边有一个强大的存在……"
D.Strings[88281]="Zor-arik var……唔……telosh？"
D.Strings[88282]="泽里法克斯！"
D.Strings[88283]="呃……要不就是teloth？我老是搞错！"
D.Strings[88284]="不！传送门！"
D.Strings[88285]="是谁竟敢召唤我？！"
D.Strings[88286]="是我，泽里法克斯·动疫！你要服从我的意志，恶魔！"
D.Strings[88287]="卑微的侏儒！我不这么认为！"
D.Strings[88288]="愚蠢的凡人！你们以为自己能奴役强大的贾格诺斯吗？"
D.Strings[88289]="该臣服的人是你！"
D.Strings[88290]="拿着这本书，$n。它记载着至关重要的情报！"
D.Strings[88291]="燃烧军团的攻击只会越来越猛。我们必须不择手段加强自身的实力。"
D.Strings[88292]="如果我们想要熬过难关，就得发挥出肯瑞托的所有力量。"
D.Strings[88293]="搁置往日的偏见，为全艾泽拉斯的福祉而战。"
D.Strings[88294]="我提议邀请部落重返肯瑞托。你可能不太喜欢这个主意。我的某些同僚肯定也会有同感。"
D.Strings[88295]="请相信我的判断。一个内战不断的世界是抵抗不了燃烧军团多久的。"
D.Strings[88296]="议会成员已经到齐了。我们别让他们久等。"
D.Strings[88297]="我会提议邀请部落重返肯瑞托。对于议会里的某些成员来说，这恐怕……很值得商榷。"
D.Strings[88298]="你的出席即是部落英勇的体现。但对某些人来说……这恐怕还不够。"
D.Strings[88299]="那应该是某种憎恶。小心！动作要快，别犹豫！"
D.Strings[88300]="你必须先制服那些守护者，我的调整才会生效。不要手软！"
D.Strings[88301]="你的武器中蕴藏着深邃的魔力。它会伴你一起成长"
D.Strings[88302]="n，我命令你负责林地这里的行动。我得去南方找塞纳留斯。只有他才能够帮我们阻止军团。"
D.Strings[88303]="你们从那些召唤师手下活着回来了……真有决心！可惜你们别想活着见到光辉的大教堂了！"
D.Strings[88304]="瓦尔莎拉有着最美丽的鲜花。你也是来摘花的吗？"
D.Strings[88305]="|TINTERFACE\\ICONS\\trade_archaeology_vrykul_runestick:20|t奥丁使用|cFFFF0404|Hspell:197961|h[符文烙印]|h|r标记了所有的敌人！"
D.Strings[88306]="要想挡住燃烧军团，我们就得先控制住这些哨兵。"
D.Strings[88307]="这本书里的法术能送你去图书馆。快走！不管遇到什么，都要做好心理准备！"
D.Strings[88308]="感谢诸位在这么短的时间里赶来。"
D.Strings[88309]="卡德加，我们不能把时间浪费在开会上。燃烧军团正在步步紧逼，部落也在紧锣密鼓地备战。"
D.Strings[88310]="朋友们，我们都看过战报了。燃烧军团正在围攻艾泽拉斯的所有王国。"
D.Strings[88311]="这已经很明显了，卡德加。"
D.Strings[88312]="我要强调两点。恶魔的手段更高明了。为了击败他们，肯瑞托也要与时俱进。"
D.Strings[88313]="那我就开门见山了。为了让肯瑞托发挥出全部实力，我们需要部落法师加入。"
D.Strings[88314]="休想！卡德加，你听清楚了！我说：休想！"
D.Strings[88315]="吉安娜，我们都知道你的惨痛经历。但这是关于——"
D.Strings[88316]="我已经陈述完毕了。如果各位没意见的话，我提议开始投票。"
D.Strings[88317]="他们毁灭了塞拉摩。他们丢下我们在破碎海滩上等死。他们一次又一次地证明了，他们就是一群怪物……懦夫！"
D.Strings[88318]="有人提议投票了。我们还要继续吗？"
D.Strings[88319]="很好。不过你们最好慎重决定。如果你们让那些人渣回到这座城市，那他们加入之时，就是我退出之日。"
D.Strings[88320]="关于允许部落进入达拉然，并在肯瑞托占据一席之地这件事，我表示同意。"
D.Strings[88321]="反对。"
D.Strings[88322]="我……是你们的……贤者！"
D.Strings[88323]="投票完毕。抱歉，吉安娜，但这次的赌注太高了。"
D.Strings[88324]="茉德拉！瓦格斯！你们怎么能——？"
D.Strings[88325]="我……去……"
D.Strings[88326]="吉安娜，拜托了……我们都是为了艾泽拉斯。跟我们合作吧！"
D.Strings[88327]="这个议会简直是非不分。等部落再次背叛你们时，记着我早就警告你们了。再见。"
D.Strings[88328]="这真是个……艰难的决定。但我们必须向前看。我们得立刻向大酋长发出邀请。还有一场战争等着我们去赢。"
D.Strings[88329]="令电线不交叉，拯救我的数字生命"
D.Strings[88330]="但先别急着走，$n。我还有一个请求。"
D.Strings[88331]="你好，创造者"
D.Strings[88332]="成功了。亲爱的拉塔娜。我会继续为你、为我们而战的。"
D.Strings[88333]="我受够这身伪装了！"
D.Strings[88334]="使用新的模块。"
D.Strings[88335]="激活修理模式。"
D.Strings[88336]="激活故障检测模式。"
D.Strings[88337]="激活烟火模式。"
D.Strings[88338]="激活零食发放模式。"
D.Strings[88339]="激活华丽模式。"
D.Strings[88340]="激活驾驶战斗模式。"
D.Strings[88341]="这不是我们挑起的战争，但我们会终结它。"
D.Strings[88342]="激活热砧模式。"
D.Strings[88343]="激活虫洞发生器模式。"
D.Strings[88344]="安装修理模式模块。"
D.Strings[88345]="安装故障检测模式模块。"
D.Strings[88346]="安装烟火模式模块。"
D.Strings[88347]="安装零食发放模式模块。"
D.Strings[88348]="安装华丽模式模块。"
D.Strings[88349]="安装驾驶战斗模式模块。"
D.Strings[88350]="安装热砧模式模块。"
D.Strings[88351]="安装虫洞发生器模式模块。"
D.Strings[88352]="这种感觉真奇怪……"
D.Strings[88353]="噢，天哪……好痒！"
D.Strings[88354]="如果洛拉希尔有恶魔，我一定会知道的。"
D.Strings[88355]="真是奇怪的感觉……这东西是哪儿来的？"
D.Strings[88356]="执事大人已经启动了仪式！任何人都不能打扰他！"
D.Strings[88357]="你们以为自己有资格进入教堂？那就上来接受试炼吧！"
D.Strings[88358]="你们或许能获得觐见他的荣耀……但要先通过我的考验！"
D.Strings[88359]="这次会议可能不太愉快。你准备好了吗，$n？"
D.Strings[88360]="向议会陈述你的想法吧，卡德加。"
D.Strings[88361]="太好了！我正在等着呢，可是我没有想到你……"
D.Strings[88362]="什么？！你这个叛徒！"
D.Strings[88363]="我就是觉得有点痛……没什么。"
D.Strings[88364]="你都是这么和人打招呼的吗？"
D.Strings[88365]="起码要先认识一下啊……"
D.Strings[88366]="你以为我是恶魔？"
D.Strings[88367]="这恐怕是我第一次被错认为恶魔了。"
D.Strings[88368]="洛拉希尔有恶魔？胡说八道。"
D.Strings[88369]="噢，我的天，我好像开始喜欢你了。"
D.Strings[88370]="你肯定搞错了，朋友。"
D.Strings[88371]="这么说……那个小术士又回来了。"
D.Strings[88372]="你来迟了，你的朋友们已经没救了。他们已经成了我的主人，孟菲斯托斯的玩具。"
D.Strings[88373]="他一定会喜欢再收到一份礼物的，而我也很乐意把你送到他面前。"
D.Strings[88374]="来吧，术士！你死定了！"
D.Strings[88375]="你的这股力量……这不可能！"
D.Strings[88376]="这……不可能！"
D.Strings[88377]="贾格诺斯死了！快，拿走他的心脏。你就是恐痕之主了！"
D.Strings[88378]="凡人，看来你杀害了我的将军……"
D.Strings[88379]="抓紧享受胜利吧，术士。这场战争还没结束呢！"
D.Strings[88380]="我们后会有期……"
D.Strings[88381]="孟菲斯托斯会……抓住你们……"
D.Strings[88382]="大法师卡德加正在达拉然等你。你准备好之后，就跨过这座传送门吧。"
D.Strings[88383]="滚出这里！"
D.Strings[88384]="这结界容不下你的存在！"
D.Strings[88385]="你没有资格站在这里！"
D.Strings[88386]="我要将你放逐到迷雾中去！"
D.Strings[88387]="朋友，恐痕来听从你的命令了！"
D.Strings[88388]="我们等待着您的命令，大领主。"
D.Strings[88389]="给，拿上这些图鉴。这都是我亲手设计的。"
D.Strings[88390]="嘿，你好啊，$n！我就知道你肯定能通过翡翠梦境之路的。"
D.Strings[88391]="乌索克之巢就在前面。在世界初开之时，他会在荒野中游荡，然后回到这里来休息和修炼。"
D.Strings[88392]="几千年前，强大的始祖龙迦拉克隆曾想要侵占这片森林。乌索克与他展开了一场恶斗。他们倒下的地方形成了这些山谷，他们的爪子划过的地方则隆起形成了山脉。最终，乌索克把巨龙赶到了西方。"
D.Strings[88393]="他死后，我们为了安全起见，就把乌索克之爪放在了翡翠梦境里。"
D.Strings[88394]="而今，我们的德鲁伊就在他位于翡翠梦境的巢穴里守护着这对利爪。现在，我们就要去那里取回它们。"
D.Strings[88395]="把手放在祭坛上，然后睡吧。"
D.Strings[88396]="呃，这不公平。"
D.Strings[88397]="你要为此付出生命的代价！"
D.Strings[88398]="要是我的胳膊能用就好了……"
D.Strings[88399]="把心脏带去祭坛！这边走！"
D.Strings[88400]="你们这些凡人为了解救那个奥蕾莉亚而历经磨难。上前接受奖赏吧！"
D.Strings[88401]="$n！你必须尽快赶去！萨鲁法尔一直在找你！"
D.Strings[88402]="这是怎么回事？赛法努斯，去解决这些凡人。不要留活口。"
D.Strings[88403]="你休想插手我们的工作，凡人！"
D.Strings[88404]="一定要保住传送门！"
D.Strings[88405]="你会玩火自焚！"
D.Strings[88406]="不能让他们干扰审判庭的工作！"
D.Strings[88407]="审判庭的神圣工作不容干扰！"
D.Strings[88408]="|TInterface\\Icons\\spell_shadow_shadowward:20|t%s开始施放|cFFFF0000|Hspell:200002|h[暗影蔽体]|h|r！"
D.Strings[88409]="不！那是我的！"
D.Strings[88410]="蠢货！你要为此付出代价！"
D.Strings[88411]="滚开，入侵者！昔日的恐惧将毁灭你！"
D.Strings[88412]="看来我们找对了方向。看看那本日志说了些什么吧。"
D.Strings[88413]="$n，你总能让我大吃一惊。"
D.Strings[88414]="我们的单向礼物发放数量已达上限。该上限每日重置一次。"
D.Strings[88415]="我的藏品中又要多一个风行者了！噢，你一定有许多秘密！"
D.Strings[88416]="别管我！去救奥蕾莉亚！"
D.Strings[88417]="你拒绝投降！真好！我们真没想到那个高等精灵会带来一个这么……固执的盟友。"
D.Strings[88418]="这个温蕾萨应该很有用……可惜她崩溃了。而你……好吧，凡人迟早要死的。"
D.Strings[88419]="$n，我带来了伊利丹大人的礼物。"
D.Strings[88420]="我自由了，可……邪能魔法……仍然在影响着我。"
D.Strings[88421]="你必须……杀掉审判官……夺回奥蕾莉亚的弓！"
D.Strings[88422]="贾布尔会想办法前往达拉然的。"
D.Strings[88423]="我要把你装箱了，贾布尔。"
D.Strings[88424]="达拉然是艾泽拉斯最大的魔法知识宝库。我想你肯定也意识到了这一点。"
D.Strings[88425]="我需要你的帮助。这种感觉就像是回家，但偶尔难免还是要跟死神打打交道的。"
D.Strings[88426]="你准备好之后，就到前面来见我吧，$n。"
D.Strings[88427]="有点挤，不过贾布尔受得了。"
D.Strings[88428]="邮寄贾布尔。"
D.Strings[88429]="不！等等！贾布尔改变主意了！"
D.Strings[88430]="有人吗？$n，你在吗？"
D.Strings[88431]="打开箱子。"
D.Strings[88432]="哦！这下感觉好多了。"
D.Strings[88433]="雾气消散了，露出了陷阱中的%s！"
D.Strings[88434]="这就是达拉然？贾布尔很感动。去见珠宝加工大师们是往这边走吗？"
D.Strings[88435]="这已经够远的了。"
D.Strings[88436]="好吧，你不是王宫的人……你也不是恶魔，至少不全是。"
D.Strings[88437]="说出你的身份，否则我就把你传到无尽之海里去。"
D.Strings[88438]="你对付那个软泥怪的表现很精彩。在战场上，保持移动就是活命的关键。但用双腿跑路未免太平庸了。你是个法师，对吧？是时候学学如何闪现了！"
D.Strings[88439]="闪现可以让你传送一小段距离，避开危险，或者拉近与敌人的距离，现在就来用一下看看吧。"
D.Strings[88440]="这是什么？一枚硬币……"
D.Strings[88441]="暮色百合的徽记……这是首席奥术师的印鉴！她还活着？！"
D.Strings[88442]="噢，对了，陷阱。"
D.Strings[88443]="很有趣，不是吗？但学会移动只相当于成功了一半，如果你还能将敌人冻结在原地，不让他们碰到你呢？作为一个法师，你完全有这个能力。"
D.Strings[88444]="冰霜新星可以把附近所有的敌人都冻结在原地，以便你用闪现拉开距离，然后在安全距离上消灭他们。现在，先让我们来练习一下冻结目标。"
D.Strings[88445]="别管我了……救救那把弓……救救萨斯多拉！"
D.Strings[88446]="$n，我记得我跟你说了，叫你的朋友别再寄那种信了吧？！"
D.Strings[88447]="哇！那家伙好大呀！"
D.Strings[88448]="$n，我认为这个洞穴里藏着某个非常强大的东西。但由于马顿已经被大量邪能彻底渗透了，所以我也无法确定。我的视线非常模糊。\n\n如果里面真有东西的话，那我们决不能忽视它。你的幽灵视觉比我们都要强，仅次于伊利丹大人。\n\n你能用幽灵视觉看看这座洞穴，确认一下我的怀疑吗？"
D.Strings[88449]="好的，杰斯，我这就用我的幽灵视觉来查看一下洞穴。"
D.Strings[88450]="看来，破碎海滩大名鼎鼎的英雄$c已经回来了。$b$b鉴于你的英雄事迹，我就不用我的弓来对付你了，但你也别逼我。你应该也能想到，在成为酋长后，我有很多事要处理。$b$b我们稍后再谈吧。你的事可以先放一放。"
D.Strings[88451]="为了鲜血与荣耀，大酋长！"
D.Strings[88452]="那到底是什么鬼东西？！？！"
D.Strings[88453]="女士们，女士们，冷静。我想这应该就是与$n合作的那位珠宝加工大师。"
D.Strings[88454]="我警告过你了。Tel'vasha！"
D.Strings[88455]="黑根松鼠感激地叫了两声。"
D.Strings[88456]="那还有机会……快来！我需要你的帮助。"
D.Strings[88457]="传送器就在外面。先激活它，然后站到台子上去。"
D.Strings[88458]="平静的枭兽感激地对你叫了两声。"
D.Strings[88459]="所有传送器的操作方法都一样。用它们找到那个设备！"
D.Strings[88460]="奇怪，你应该已经被传回来了。你的行动为你争取了时间。"
D.Strings[88461]="如果连瓦里安国王都阻止不了燃烧军团，还有谁行呢？"
D.Strings[88462]="他是个高贵的国王……"
D.Strings[88463]="一切都不同了……"
D.Strings[88464]="塔楼的防御系统被篡改了！我感觉麦迪文魔法的触须正在破坏我的安全措施！"
D.Strings[88465]="我不会停止制造蜡烛的！……除非你想听故事？"
D.Strings[88466]="等我调整完毕后，就重新激活这些哨兵。我会加固大门，并派守护者去对付燃烧军团。这可以帮我们争取时间，找到我们想要的东西。"
D.Strings[88467]="老鼠是很好的挖掘工，否则至少也是一顿美餐。"
D.Strings[88468]="老鼠不怕黑。"
D.Strings[88469]="老鼠比兔子更美味，而且更好抓。"
D.Strings[88470]="鹰身人喜欢亮晶晶。\n\n我们用宝贝换蜡油。\n\n做最大的蜡烛！"
D.Strings[88471]="太忙了。总是有事情做！\n\n聪明的工人抓老鼠。最聪明的工人点蜡烛。\n\n其他人……去挖矿。"
D.Strings[88472]="我想听故事。"
D.Strings[88473]="有点不对头……我找不到你了……"
D.Strings[88474]="你所在的空间很不稳定。传送术坚持不了多久。"
D.Strings[88475]="奇妙的发现，可你在那里找不到我们需要的装备。"
D.Strings[88476]="狗头人已经在这里住了很久。在黑暗的角落里做窝。"
D.Strings[88477]="抓老鼠，有时候也吃老鼠。"
D.Strings[88478]="挖宝藏，跟鹰身人做买卖。"
D.Strings[88479]="他们喜欢亮晶晶，我们喜欢蜡。刚从耳朵里挖出来的品质最好。"
D.Strings[88480]="有一天，卓格巴尔来了，说山洞是他们的。"
D.Strings[88481]="他们又砸又抢。我们就要蜡烛和毛皮。"
D.Strings[88482]="卓格巴尔又大又蠢。他们有山洞，但没有蜡烛。"
D.Strings[88483]="黑暗发现了他们。黑暗在跟踪他们。"
D.Strings[88484]="黑暗生吞了他们！"
D.Strings[88485]="我们回来了。我们有蜡烛。"
D.Strings[88486]="山洞又是我们的了。蜡烛保护了我们。"
D.Strings[88487]="吉普·亮芯深吸了一口气。"
D.Strings[88488]="有关创世之柱的知识就在这里！我们得找到那本书！"
D.Strings[88489]="萨格拉斯知道我们在寻找创世之柱！我需要你帮我关闭这道屏障。"
D.Strings[88490]="这些幻象用了潜行！快用照明弹！"
D.Strings[88491]="它们的潜行能力真是疯狂！快丢个照明弹！"
D.Strings[88492]="醒醒！头儿来了。"
D.Strings[88493]="我没睡着，只是在闭目养神……"
D.Strings[88494]="维尔利特是我最喜欢的老鼠。"
D.Strings[88495]="燃烧军团！我会尽量挡住他们的。"
D.Strings[88496]="不！维尔利特！"
D.Strings[88497]="本尼是最漂亮的老鼠。"
D.Strings[88498]="你会为杀害本尼付出代价的！"
D.Strings[88499]="我不会忘记你的，布鲁！"
D.Strings[88500]="你打了奥利。我也要打你！"
D.Strings[88501]="奇维是我唯一的朋友！"
D.Strings[88502]="等杀了你之后，我还要再去抓一只老鼠！"
D.Strings[88503]="这个构造体的行动开始变得迟缓了。在它的能量耗尽前赶回倾颓废墟！"
D.Strings[88504]="小心点，朋友。我们中间有恶魔……"
D.Strings[88505]="是伊利丹派我来杀卡佐图尔那个恶魔的。"
D.Strings[88506]="我们追踪那个恶魔一路来到了这个洞穴，可那只野兽偷袭了我们。我最好的几个战士当场战死，卡佐图尔也跑了。$b$b如果你想把那个恶魔引到开阔地带，或许可以通过激活洞穴里的法力道标把它引出来。$b$b祝你好运。"
D.Strings[88507]="|TInterface\\Icons\\inv_misc_monsterhorn_03.blp:20|t一头%s出现了！"
D.Strings[88508]="我没有受伤。我……我正在追踪一头熊！"
D.Strings[88509]="哦，我相信你。让我帮你包扎一下伤口吧。"
D.Strings[88510]="受伤的芬雷尔逃回他的巢穴去了。"
D.Strings[88511]="不不不。你得将那个火花冻结在原地。让我们再试一次。使冰霜新星将它冻结在原地，然后用闪现拉开距离。"
D.Strings[88512]="<你能隐约看见传送门另一边的灰熊丘陵。>"
D.Strings[88513]="布鲁是最好的朋友。"
D.Strings[88514]="前往灰熊丘陵。"
D.Strings[88515]="我永远都不会吃奥利的。"
D.Strings[88516]="|TInterface\\Icons\\Spell_Holy_DivineProvidence:20|t$n受到了|cFFFF0404|Hspell:192048|h[驱逐之光]|h|r的影响！"
D.Strings[88517]="奇维咬了我好几口。"
D.Strings[88518]="诺瓦的牙齿最锋利了。"
D.Strings[88519]="|TInterface\\Icons\\spell_hunter_lonewolf:20|t芬雷尔开始施放|cFFFF0404|Hspell:196543|h[挫志嚎叫]|h|r！"
D.Strings[88520]="谢谢。呃……拜托不要告诉我妈妈我受伤了。"
D.Strings[88521]="你几乎和卡拉一样出色了。"
D.Strings[88522]="欢迎来到训练场。$b$b我们将在这里学习控制自己的头脑和身体。"
D.Strings[88523]="奇怪。它不该把你送到那里去的！等等，我把你召回来。"
D.Strings[88524]="有人在干扰网络……传送术是精妙的艺术，怎么能让外行人瞎胡闹呢！"
D.Strings[88525]="干得好。把它们带回我的工作室来！"
D.Strings[88526]="闻着卡拉身上那股子牲口棚的味道，再加上我们厨子身上散发出来的恶臭，我觉得我可能会昏过去。"
D.Strings[88527]="风暴之神的武器在等着我们，$n！"
D.Strings[88528]="我们的勇士到了！泰兰德派我们来取一件足以扭转战局的武器。"
D.Strings[88529]="你必须拿到月神镰刀。但愿它的力量能祝你一臂之力。"
D.Strings[88530]="月神镰刀属于卡拉赞，蝼蚁！"
D.Strings[88531]="瓦洛恩，不！"
D.Strings[88532]="我这一生经历过太多的苦难，$n。我不想再参加任何一场葬礼了。我要制裁吉尔尼斯的敌人！"
D.Strings[88533]="他带着月神镰刀！跟上他！"
D.Strings[88534]="他已经走了……"
D.Strings[88535]="别靠得太近。我会被你身上的味儿熏得晕过去的。"
D.Strings[88536]="是卡拉派你来的。"
D.Strings[88537]="我觉得你比我臭多了。现在，让我来帮助你吧。"
D.Strings[88538]="很不错。你掌握得很快。但那只是一个怪物。如果你要同时与许多敌人战斗该怎么办呢？这个时候，你就得掌握烈焰风暴。"
D.Strings[88539]="烈焰风暴的施法速度很慢，但可以对一定范围内的所有目标造成巨大的伤害。现在，使用烈焰风暴快速消灭这群软泥怪吧。"
D.Strings[88540]="我会保守秘密的。现在，别乱动，我来给你包扎。"
D.Strings[88541]="我们穿过了结界，可这里怎么了？梦魇扩散到乌索克之巢了吗？"
D.Strings[88542]="黑暗女王在上。"
D.Strings[88543]="我觉得我以前根本不算是什么猎人。"
D.Strings[88544]="我觉得我不是当猎人的料。"
D.Strings[88545]="但愿托尼在营地里准备了吃的。"
D.Strings[88546]="我会假装没看见的，外来者。"
D.Strings[88547]="你以为你在做什么？"
D.Strings[88548]="别碰它！"
D.Strings[88549]="那不是你的东西。粗鲁的家伙。"
D.Strings[88550]="召唤师，打开传送门！我们需要援军！"
D.Strings[88551]="你的血肉将成为猎犬的美餐！"
D.Strings[88552]="你的末日一定会降临的……只是换一个送葬者而已！"
D.Strings[88553]="欢迎来到我的土地，$r。这个小家伙告诉我你在打听伊尔马特的传说。"
D.Strings[88554]="你的基本功已经很扎实了，法师，是时候学习一些高级技巧了。炎爆术是你最强大的法术，如果你有炽热连击效果，它还会变得更强大。更重要的是，在炽热连击效果下，它就不需要施法时间了。"
D.Strings[88555]="在连续造成两次爆击后，你就获得了炽热连击效果。由于炼狱冲击是必然爆击的，所以你应该先施放火球术。在出现第一次爆击后，立刻使用炼狱冲击打出第二个爆击，然后再施放炎爆术。"
D.Strings[88556]="噢！神奇！！！快，看看它的效果！"
D.Strings[88557]="你已经获得了炽热连击效果，现在施放炎爆术！"
D.Strings[88558]="就是这样。让我们再练习几次，然后你就要面对一个真正的挑战。"
D.Strings[88559]="炎爆术的施法时间很长，除非你有炽热连击效果。现在，使用火球术和炼狱冲击获得炽热连击，然后再施放炎爆术。"
D.Strings[88560]="这是你的第一个爆击，现在施放炼狱冲击来打出第二个爆击。"
D.Strings[88561]="让我的狂风撕碎你！"
D.Strings[88562]="我们已经准备好来挑战你了，奥丁！"
D.Strings[88563]="你们准备好面对我了吗？"
D.Strings[88564]="喝！"
D.Strings[88565]="哈……！"
D.Strings[88566]="茉艾拉说你会来的。我叫熔锤，为偿还家族的罪孽来跟这些蝼蚁周旋。我来解除屏障。"
D.Strings[88567]="暗影执事已经启动了仪式。要想抵达那里，我们得先准备一番。你有什么问题尽管问我，但要快一点！"
D.Strings[88568]="我们得回梦境林地去，$n。大德鲁伊知道怎么解锁这对爪子的力量。"
D.Strings[88569]="我们时间不多，但你应该了解真相。你想知道什么？那个暗影执事？那把匕首？还是究竟发生了什么事？哈！"
D.Strings[88570]="这可真是突然，我们在哪儿？出什么事了？"
D.Strings[88571]="你能相信吗，他们发现了提尔本人的墓穴？！很久很久之前，他在与上古之神的怪物将军战斗中陨落于此。他的战友将他和那个怪物的尸体一起埋葬在这里。$b$b这座墓穴本来还可以看守囚禁那个怪物的墓穴，可暮光之锤破坏了这一切。$b$b那个暗影执事用那把利刃闯了进去，而他的爪牙们则在他进入墓穴期间破坏了结界。"
D.Strings[88572]="自从暮光教父和死亡之翼倒台后，暮光之锤就成了一盘散沙。我猜是在燃烧军团发动进攻后，他们剩下的某个首领想出了趁大家分心之际占领这里的主意。$b$b他想起了上古之神留下的一件神器，并计划对下面那个死掉的怪物使用它，以巩固他对教派的控制。$b$b我还没看过那个助祭的正脸，可我觉得他有点眼熟……"
D.Strings[88573]="那把匕首……我想茉艾拉也希望知道。如果我没记错的话，那把匕首曾掀起过艾泽拉斯历史上最可怕的几场惨剧。它看起来很像三锤之战的故事中提到的那把匕首……还有格瑞姆巴托。$b$b它弥散着暗影，似乎还能切开圣光！它恐怕已经产生了自主意识，难怪我看到那个暗影执事有时会跟空气说话争吵！$b$b我们最好阻止这个仪式，并祈祷那把匕首会抛弃暮光之锤。"
D.Strings[88574]="暗影执事？这个新首领是谁？"
D.Strings[88575]="你提到了一把魔法之刃，能说详细点吗？"
D.Strings[88576]="发现威胁。正在追击。"
D.Strings[88577]="启动防御模式。已确认目标。"
D.Strings[88578]="防御调试完成。正在获取目标。"
D.Strings[88579]="真方便！你的小团队会成为猎犬的美餐！"
D.Strings[88580]="你们这些凡人总是这么自信！那就来吧。我们的宝贝们肯定饿了！"
D.Strings[88581]="巫婆！我要剐了这些畜生，再砍掉你的头！"
D.Strings[88582]="有意思！大审判官一定会喜欢这些精神抖擞的客人！"
D.Strings[88583]="光说……不练……"
D.Strings[88584]="耶！就是这个东西！"
D.Strings[88585]="它倒下了！"
D.Strings[88586]="别担心我，我会照顾好自己的。"
D.Strings[88587]="呃，你有什么想法吗？"
D.Strings[88588]="无聊死啦。让我们去做点什么吧。"
D.Strings[88589]="非常好！但打靶子是一回事，实战又是另一回事了。是时候让你参加最后的试炼了。你得用上你所学到的所有技巧。在战斗中击败我的人，证明你已经准备好了。"
D.Strings[88590]="我以前也见过我父亲发火，可我从来没见过他这么愤怒。对复仇的渴望会吞噬他的。"
D.Strings[88591]="所有的吉尔尼斯人内心都有一股怒火，苔丝，尤其是你父亲。"
D.Strings[88592]="确实如此。有时，我们很难分清兽性和人性的界限。"
D.Strings[88593]="我父亲会跟国王陛下一起去。我们一定能打被遗忘者一个措手不及！"
D.Strings[88594]="我担心还会有更多的葬礼。"
D.Strings[88595]="这就是复仇的代价。吉尔尼斯已经等得太久了。"
D.Strings[88596]="我们就快到要塞了。请告诉安度因国王，我们都很想他，$n。"
D.Strings[88597]="快，苔丝，炮艇就要出发了！"
D.Strings[88598]="俄瑞斯忒斯！"
D.Strings[88599]="我们的大军无穷无尽。"
D.Strings[88600]="你已经获得了炽热连击，快施放炎爆术！"
D.Strings[88601]="啊，雪羽把我的信送到了。很好！我们正需要你呢。"
D.Strings[88602]="祝你们好运，朋友们。救出……奥蕾莉亚……"
D.Strings[88603]="猎犬……我太大意了……让它们靠得太近了。"
D.Strings[88604]="该死的，好冷……"
D.Strings[88605]="俄瑞斯忒斯，坚持……俄瑞斯忒斯！"
D.Strings[88606]="<阿布索伦剧烈地颤抖着。>\n\n别管我。让我一个人痛苦吧。"
D.Strings[88607]="去吧，我会支持你的。"
D.Strings[88608]="再跟我说说至高岭灾星的事吧。"
D.Strings[88609]="我想听听这把长矛的事。"
D.Strings[88610]="它是怎么跑到这儿来的？这是什么地方？"
D.Strings[88611]="我还要跟我兄弟再说两句，然后我们就去屏障那儿。祝你好运！"
D.Strings[88612]="我们到了——我昔日的圣殿！"
D.Strings[88613]="奇怪……防御措施都关闭了……"
D.Strings[88614]="有入侵者！他们怎么进来的？！"
D.Strings[88615]="泰温……我早就该发现是你这个白痴在干扰我的网络了。"
D.Strings[88616]="你该骄傲！你的作品将帮助我们夺回曾属于我们的古老土地。"
D.Strings[88617]="喔唷，你很憔悴啊，尊敬的老师。你没吃饱吗？啊哈哈哈！"
D.Strings[88618]="解决他们！"
D.Strings[88619]="我能对付泰温。你去让线圈过载！"
D.Strings[88620]="|TInterface\\Icons\\INV_Misc_Horn_03:20|t海姆达尔吹响|cFFFF0404|Hspell:191284|h[勇气号角]|h|r召唤风暴幼龙！"
D.Strings[88621]="感谢你的仁慈。我不会忘记你的恩情的。"
D.Strings[88622]="在你放下陷阱之前，我们敌不过它的！快！"
D.Strings[88623]="拦住这些野兽，等待陷阱发动！"
D.Strings[88624]="黑暗消散了……谢谢你。"
D.Strings[88625]="使用冰霜新星将你的敌人冻结在原地，然后拉开距离。"
D.Strings[88626]="到达拉然下水道的意志竞技场来，术士。我的传送门可以送你过去。我们在那儿等你。"
D.Strings[88627]="我在寻找那个叛徒。"
D.Strings[88628]="臣服于苏拉玛的力量吧。"
D.Strings[88629]="只要一想到我是死在……那个……"
D.Strings[88630]="我的任务失败了。"
D.Strings[88631]="为我复仇，安妮莎尔！"
D.Strings[88632]="那个叛徒在哪儿？"
D.Strings[88633]="赞美暗夜井的力量！"
D.Strings[88634]="愚蠢的东西。我来让你看看真正的力量。"
D.Strings[88635]="艾利桑德……我辜负了你。"
D.Strings[88636]="该死的……蝼蚁……我要……"
D.Strings[88637]="为我复仇，伊迪瑞娜。"
D.Strings[88638]="正在评估目标。"
D.Strings[88639]="开启战斗模式。"
D.Strings[88640]="威胁等级：最低。"
D.Strings[88641]="主核受损……"
D.Strings[88642]="能量储备枯竭。"
D.Strings[88643]="正在联络最近的寻觅者。"
D.Strings[88644]="你女儿戴着的是什么，瓦伦德尔？"
D.Strings[88645]="那你妻子呢？"
D.Strings[88646]="驻扎丽丽。"
D.Strings[88647]="总算能摆脱那座丛林了，我真是太开心了。"
D.Strings[88648]="我太荣幸了，竟然能参与隐秘通途的重建！"
D.Strings[88649]="我们将携手打败燃烧军团！"
D.Strings[88650]="没有西芙和奈尔，我哪儿都不去。"
D.Strings[88651]="我还是觉得不安全。"
D.Strings[88652]="我总算找到你了，多利安。现在，我要亲手结果了你。"
D.Strings[88653]="就是这样，你做到了！你真是个熟练的施法者。我已经没什么可教你的了，但你才刚刚上路。"
D.Strings[88654]="如果你觉得自己需要再多练习几次，那就使用这个传送门前往试炼场吧。你可以在那里接受试炼教头罗敦的训练，真正掌握你的职业。否则就使用上面那架旋翼机投入战斗吧。"
D.Strings[88655]="有话快说。我的行动决定了我不能引起任何不必要的注意。"
D.Strings[88656]="你为什么要冒险帮助他们呢？"
D.Strings[88657]="这根线圈接入了古代魔网。把它调到最大功率！"
D.Strings[88658]="过载"
D.Strings[88659]="下方大厅还有更多线圈——和更多入侵者。"
D.Strings[88660]="很好。只要让足够的线圈过载，系统就会为了自保而锁定。"
D.Strings[88661]="还没轮到你呢，瓦雷迪斯。"
D.Strings[88662]="用双刃干掉这个入侵者！"
D.Strings[88663]="我只需要一小口奥能电浆……"
D.Strings[88664]="还不错……有点薄荷味……"
D.Strings[88665]="我感觉怪怪的……"
D.Strings[88666]="承认吧，老家伙。我超越你了。"
D.Strings[88667]="不错……<咳咳>把你周围的空间扭曲成这样。"
D.Strings[88668]="呃……噢……哇啊啊啊！！！！"
D.Strings[88669]="可要是那个空间已经失衡了呢？"
D.Strings[88670]="你不属于这里，$r。"
D.Strings[88671]="我们要为燃烧军团夺回这些废墟。"
D.Strings[88672]="在我面前，你毫无机会。"
D.Strings[88673]="为了燃烧军团。"
D.Strings[88674]="你休想离开这个地方。"
D.Strings[88675]="暗夜井辜负了我。"
D.Strings[88676]="我们要夺回这片土地。"
D.Strings[88677]="我要砍死你。"
D.Strings[88678]="你休想打败我，$r。"
D.Strings[88679]="燃烧军团终将控制这片土地。"
D.Strings[88680]="这怎么……可能……"
D.Strings[88681]="你休想逃出燃烧军团的掌心。"
D.Strings[88682]="我的迁跃力场失效了！你把我们带到哪儿了？！"
D.Strings[88683]="<咳咳>不稳定……空间……"
D.Strings[88684]="奥图里斯他们都在克拉苏斯平台。我在那里等你。"
D.Strings[88685]="这个堕夜精灵似乎还活着，但毫无反应。"
D.Strings[88686]="给这个堕夜精灵喂食远古魔力。"
D.Strings[88687]="$r，是怎样的不幸才让我们的命运产生了交集？"
D.Strings[88688]="$n，我很高兴你能来。玛沃伦斯已经为我们开启了往返邪能之槌号的传送门。\n\n燃烧军团已经入侵了法罗纳尔地峡。我们得在他们攻占这座岛的其它地方前消灭他们。"
D.Strings[88689]="卡德加？$n？想不到你们会来。"
D.Strings[88690]="和闪现一样，冰霜新星的冷却时间很长。所以为了提高你的训练效率，我给这个房间灌注了魔法能量，以便你能更加频繁地使用它们。"
D.Strings[88691]="这件神器似乎很强，$c。你想帮忙的话，就去找杰斯和阿莱利吧。"
D.Strings[88692]="考瓦斯，你和赛娅娜从内部突击，我们来个里应外合。"
D.Strings[88693]="我们是不会认输的。我们是伊利达雷。"
D.Strings[88694]="别忘了用宝石把那只恶魔的灵魂从尸体里吸出来。"
D.Strings[88695]="想看看陈叔教我的戏法吗？"
D.Strings[88696]="赞美朱鹤，一个治疗者！"
D.Strings[88697]="泰温总是轻视魔法……糟糕的学生……<咳咳>"
D.Strings[88698]="我快不行了……<咳咳>我会尽量靠近一点……过来。"
D.Strings[88699]="不！这里……必须服从我的意志！"
D.Strings[88700]="这些蝼蚁在压制提尔的结界，好让那个执事搞鬼。我们得干掉他们！先驱散保护那些祭师的结界吧！"
D.Strings[88701]="他可能想要偷偷离开。我建议你从下水道开始找起。"
D.Strings[88702]="赫米特和他的猎人们每到一个地方，就会带来死亡和毁灭，为了一时之快而屠杀无辜的动物。\n他们必须为自己反自然的罪行付出代价。\n\n如果这片盆地里的动物会说话，它们肯定会向我们求助的。让我们把这场游戏变得更加平衡一点，让那些猎人也尝尝被狩猎的滋味。\n\n我会把你变成生活在这一地区的某种动物的样子。你变形之后，那些猎人就会变成你的猎物。\n\n你准备好了吗？"
D.Strings[88703]="好了！通向监狱的道路敞开……嘿，这不是我的老朋友嘛！我们要为世界干掉这个坏家伙！"
D.Strings[88704]="燃烧军团知道这座圣地的重要性。我亲自带队来此巡视，却遭到了伏击，伤亡惨重。"
D.Strings[88705]="谢谢你，英雄。圣水已经被腐蚀了。如果你能帮我救出其他人，我们或许可以夺回这里。"
D.Strings[88706]="马上就好，游侠将军。但你要小心点！在这样的虚空深处，时光的流淌毫无规律。"
D.Strings[88707]="俄瑞斯忒斯，你这傻瓜！"
D.Strings[88708]="现在得救两个人了。跟我来！"
D.Strings[88709]="这个机器人已经坏了，修不好了。"
D.Strings[88710]="黑暗之涌会吞噬你的！"
D.Strings[88711]="你无法在该区域保持当前形态。"
D.Strings[88712]="我们自深渊而来！"
D.Strings[88713]="贾布尔正要前往一个鹰身人的巢穴，结果遭到了伏击。我们现在就去那里搜寻那些石头吧。"
D.Strings[88714]="看来虚弱的躯壳已经吸干了所有的奥能电浆，还顺便摧毁了FTW-001。"
D.Strings[88715]="塔莉萨就在梅瑞戴尔附近。你能把我们传送过去吗？"
D.Strings[88716]="我们在离开前，得先解决掉泰温。"
D.Strings[88717]="我正在迅速衰弱。塔莉萨呢？"
D.Strings[88718]="伟大的露露贝拉·菲兹班为您效劳！"
D.Strings[88719]="我……还活着！"
D.Strings[88720]="看来连深渊领主都打不倒你，术士！"
D.Strings[88721]="可是，议会的其他人呢？"
D.Strings[88722]="还有一件事，术士。"
D.Strings[88723]="我们的人都走散了，后头还有个恐惧魔王，我们需要你来领导议会。有你在，我们就能东山再起。"
D.Strings[88724]="我任命你，$n，为黑暗收割议会的首座。"
D.Strings[88725]="带领我们赢得击败军团的荣耀吧！"
D.Strings[88726]="来吧，让我们计划一下未来。"
D.Strings[88727]="抱歉，但这封信非常紧急。"
D.Strings[88728]="在把这封信转交给你之前，我恐怕还不能走。"
D.Strings[88729]="我必须跟你谈谈，只要一会儿就好！"
D.Strings[88730]="我们必须互相适应，直到你准备好开口。"
D.Strings[88731]="这封信只有你能看。看完之后请立即销毁。"
D.Strings[88732]="普斯图里奥说的是真话！那个风行者就被关在尼斯卡拉。"
D.Strings[88733]="你最好别骗我，蝼蚁！"
D.Strings[88734]="去尼斯卡拉吧！你会看到的！"
D.Strings[88735]="我们应该终结它痛苦的生命！"
D.Strings[88736]="外面有很多恶魔，但没有什么是我们对付不了的。"
D.Strings[88737]="我会想办法帮你这个忙的。"
D.Strings[88738]="如果有东西靠近……我就杀了它。"
D.Strings[88739]="走进荣耀杂货店，对“红发”杰克说一句“渡鸦有请”。他就会给你指路的。"
D.Strings[88740]="来吧，小心别被跟踪了。无冕者的眼线都盯着你呢。"
D.Strings[88741]="明智的选择。那个麻烦的家伙就在意志竞技场里。他的名字是伊克罗特，我需要有人去教训他一下。相信你知道该怎么做，$c。"
D.Strings[88742]="既然我们的交易完成了，我也该走了。回头见，$n。"
D.Strings[88743]="没有游侠将军的命令就不行。明白了吗？"
D.Strings[88744]="%s羞怯地向你表达了谢意。"
D.Strings[88745]="仆从们！好好享用他们的灵魂吧！"
D.Strings[88746]="只有蠢货才会大摇大摆地走进暗影大厅。准备——"
D.Strings[88747]="请这边走。"
D.Strings[88748]="其他人都在等你。祝你好运。"
D.Strings[88749]="他们的进攻简直没完没了！请帮我们阻止他们！"
D.Strings[88750]="这……这太疯狂了，$n！你必须做点什么！"
D.Strings[88751]="燃烧军团来了！准备战斗！"
D.Strings[88752]="如果你不是非呆在这儿不可的话，我建议你去找个掩体躲起来。"
D.Strings[88753]="躲起来也没人会责怪你的，$n，可你……你看起来是个勇敢的$c。我们需要你的帮助。"
D.Strings[88754]="又是流亡者……跟我一样。我只是惩罚了那些仆人……你也会那么做的！"
D.Strings[88755]="你一定就是阿斯托里尔！总算找到你了！等回到城里，我要做的第一件事就是喝上一大杯清凉的魔力酒。"
D.Strings[88756]="小心点，$n。不久前，我才见过一个你这样的$c。燃烧军团……他们——$B$B他们会不顾一切吞噬我们的土地！我不能要求你冒着生命危险来与我并肩战斗。但我可以告诉你，如果不能尽快阻止他们，那我们很快就会一无所有了。"
D.Strings[88757]="这里可没有软柿子，恶魔。"
D.Strings[88758]="燃烧军团想要潘达利亚，就得先打倒我们！"
D.Strings[88759]="勇敢的$r！你是来消灭燃烧军团的吗？"
D.Strings[88760]="我们会尽力挡住他们的，拜托了，$n——只有在你的帮助下，我们才有可能拯救这片土地！"
D.Strings[88761]="啊！最后一位成员也到了。欢迎上船！"
D.Strings[88762]="瓦莉拉朝你的方向瞥了一眼。"
D.Strings[88763]="来了一群旱鸭子！我们要用盐和鳞片把他们赶回去！"
D.Strings[88764]="这片土地将属于我们。"
D.Strings[88765]="我们会把我们想要的东西都带走。"
D.Strings[88766]="萨卡提斯要看着你们去死。"
D.Strings[88767]="帮帮我，拉凯斯！"
D.Strings[88768]="没人可以逃过死亡。"
D.Strings[88769]="你的德鲁伊都得死！"
D.Strings[88770]="你休想阻止我们。"
D.Strings[88771]="我们会得到我们想要的一切。"
D.Strings[88772]="我辜负了女王陛下。"
D.Strings[88773]="拉凯斯……杀了这个……"
D.Strings[88774]="萨卡提斯……"
D.Strings[88775]="萨卡提斯……会杀了你的……"
D.Strings[88776]="我向来都是个刺头。我们在另一边见！"
D.Strings[88777]="这片土地和这里的资源都是属于我们的！"
D.Strings[88778]="还会有更多人来接替我的位置……"
D.Strings[88779]="索尔加兹，强化那个传送水晶。"
D.Strings[88780]="%s身受重伤，单膝跪了下来。"
D.Strings[88781]="想活下去吗？那就杀了这些蠢货。"
D.Strings[88782]="没错……那把剑说得对！我是不可阻挡的！等我们复活了扎卡兹，我就将统治这个世界！"
D.Strings[88783]="我们昔日的首领选择跟棋子合作。而我，选择了真正的掌权者！"
D.Strings[88784]="滚开，野兽！你可耻的远征结束了。"
D.Strings[88785]="来吧，那个怪物已经把腐蚀散播到了上面的水源里。我们得尽快行动。"
D.Strings[88786]="他正在凋零……"
D.Strings[88787]="你出去的时候，我又找到了一些法力水晶。把他放在这儿吧。"
D.Strings[88788]="这个夜之子的尸体血迹斑斑，残缺不全。从他的伤口来看，似乎是胸口遭到了重击。"
D.Strings[88789]="我们得合作。勇士，我们会听你指挥，你打算怎么部署影踪派的力量？"
D.Strings[88790]="你们这群帮凶休想抢走我的货物！"
D.Strings[88791]="这股邪能魔力在啃食我的灵魂！这个传送门坚持不了多久，快走！"
D.Strings[88792]="带走这些补给品！指挥官马上就要到了。"
D.Strings[88793]="末日临近了……"
D.Strings[88794]="一个不留！统统杀光！"
D.Strings[88795]="吞掉这些凡人废物的血肉吧！"
D.Strings[88796]="你将体会万千世界的痛苦。"
D.Strings[88797]="你们的世界因我们到来而颤抖。"
D.Strings[88798]="这种对暗夜井的渴望是不会停止的。要不是遇上了魔力页岩虫，我现在肯定已经死了。"
D.Strings[88799]="我很满意在地下跟魔力页岩虫一起生活的日子。他很快就成了我最好的朋友。"
D.Strings[88800]="我的头脑还是一样敏锐。"
D.Strings[88801]="我饿了，可我会继续前进的。"
D.Strings[88802]="<欧库勒斯语无伦次地小声自言自语着。|cFFF92304必须首先满足他的饥渴，然后才能进行其他行动。|r>"
D.Strings[88803]="我会尽我一切的力量去阻止燃烧军团入侵苏拉玛。"
D.Strings[88804]="诸位！来为这个狂徒干一杯！这家伙想从伊丽扎冰冷的死人爪子里夺取恐惧之刃！"
D.Strings[88805]="升帆！起锚！水手们，做好准备！阿苏纳在等着我们呢！"
D.Strings[88806]="你准备好就说一声。伊丽扎绝对会大吃一惊的！"
D.Strings[88807]="启航前往阿苏纳！"
D.Strings[88808]="你已经被暗水包围了，软皮！"
D.Strings[88809]="大海也将与你为敌！"
D.Strings[88810]="戈德林的力量将属于我们，$r！"
D.Strings[88811]="月神镰刀属于狼人！"
D.Strings[88812]="在霜鳞的力量面前颤抖吧！"
D.Strings[88813]="沉入冰冷的深海吧！"
D.Strings[88814]="他们想拿我们去喂他们的蜥蜴！"
D.Strings[88815]="他们将我们的一部分同胞带到飞地深处去了。"
D.Strings[88816]="谢谢你，勇士！"
D.Strings[88817]="所以说我讨厌洞穴。"
D.Strings[88818]="他们趁夜偷袭了我们。"
D.Strings[88819]="总算摆脱那该死的陷阱了！真是——"
D.Strings[88820]="嘿，你！我正在海滩上享受悠闲假期呢，突然感觉到一阵寒风刮过。我说，你到底在打什么鬼主意？"
D.Strings[88821]="等等，我认得那个声音……"
D.Strings[88822]="哦，该死的，你干了什么？快，把她关回牢房去！"
D.Strings[88823]="米尔豪斯！！下一个就是你！"
D.Strings[88824]="快卸掉她的松鼠炸弹，否则就迟了！"
D.Strings[88825]="现在，拆了那些该死的火箭鸡！它们就快开火了！"
D.Strings[88826]="现在嘲笑她的头发吧！这没用，但这会让她非常抓狂！"
D.Strings[88827]="什么……不准侮辱我的发型！不准！"
D.Strings[88828]="跟我一起着陆！"
D.Strings[88829]="嚯，伙计，你真的做到了！"
D.Strings[88830]="我就知道是你，米尔豪斯！"
D.Strings[88831]="听我说，米莉，我可以解释！"
D.Strings[88832]="别叫我“米莉”，米尔豪斯·杰瑞姆斯·法力风暴！看我收拾你！"
D.Strings[88833]="那才不是我的中间名呢！"
D.Strings[88834]="真是多谢了。你根本不明白自己放出来的是什么东西！"
D.Strings[88835]="说句题外话，我……呃……我还有点事……"
D.Strings[88836]="她准备好带你去见风行者将军了。祝你好运，指挥官！"
D.Strings[88837]="保护我吧，剑！你说过这能行！"
D.Strings[88838]="黑暗骑士并非天生如此。他们原本是一群旅行的商人。"
D.Strings[88839]="不幸的是，他们冒犯了巫师麦迪文。他诅咒了他们，让他们永世为他搜刮神器。"
D.Strings[88840]="埃瑞丁是第一个黑暗骑士，他现在应该是骑士首领了。"
D.Strings[88841]="他的营地还在逆风小径，这些年始终安然无恙，真奇怪。"
D.Strings[88842]="如果我的推断是正确的，那么寻找黑暗骑士、以及他们所觊觎的神器所需要的关键线索，就在那里。"
D.Strings[88843]="那个狼人把你也带来了？月神镰刀肯定藏在这里！"
D.Strings[88844]="继续前进吧！大地之末号就在山脊的另一边。"
D.Strings[88845]="与他们战斗，争取你们的自由吧！"
D.Strings[88846]="啊，她在那儿。很漂亮，对吧？"
D.Strings[88847]="嘿！离我的咀嚼者远一点！"
D.Strings[88848]="那是我的咀嚼者！别碰它们！"
D.Strings[88849]="你在猎杀我的宝贝？！"
D.Strings[88850]="来吧，小伙子们！吃掉那个入侵者。"
D.Strings[88851]="别再打我的宝贝们了！"
D.Strings[88852]="呱！抢了那艘船。"
D.Strings[88853]="你要溜过守卫，把大副争取到我们这边来。然后我们就来跟你汇合。"
D.Strings[88854]="谢谢你，$c。我得回我的姐妹们那儿去了。"
D.Strings[88855]="谢谢你，勇士！现在，去跟那个抓了我们的邪恶的卓格巴尔打一架吧。"
D.Strings[88856]="真高兴能再次见到你，$n！我们那时候差点把潘达利亚都烧了！$b$b自从你上次与影踪派合作之后，我一直在完善我的火焰法术。如果你能保护好我的话，我应该可以打破阿斯帕修斯的冰墙，顺便把他煮熟。站到我身边来，我可以提升你的碎玉闪电的威力。$b$b<非离露出一个狂野的笑容。>$b$b你真的想要让我点燃这个家伙吗，还是只要我专心保命就行了？"
D.Strings[88857]="谢谢你赶来帮忙，$c。我叫非离，我是影踪派里有名的放火能手。通常我烧的都是敌人啦，但偶尔也会点燃禅院。每次发生这种事的时候，祝踏岚大人都会不太高兴……$b$b帮我赢回他的好感吧。如果你能保护好我的话，我应该可以打破阿斯帕修斯的冰墙，顺便把他煮熟。站到我身边来，我的辉煌光环可以帮你恢复法力。$b$b<非离露出一个狂野的笑容。>$b$b你真的想要让我点燃这个家伙吗，还是只要我专心保命就行了？"
D.Strings[88858]="我们得想办法阻止他的引导……"
D.Strings[88859]="专心保命吧，非离。我得注意照顾其他人。"
D.Strings[88860]="放手去做吧，非离！不要怕危险，我会保护好你的。"
D.Strings[88861]="你好，$n！自从我们上次在潘达利亚的冒险之后，你又长进了不少啊。我敢说，哪怕是祝踏岚大人都能从你身上学习一二了。很高兴能再次与你并肩作战。$b$b现在，说正事吧！我可以让白羽扑下去用喙和爪子袭扰阿斯帕修斯，同时从远处攻击他。站到我身边来，我可以让你的施法速度变得更快。$b$b我可以全力进攻，但这会让我身处险境。你需要我火力全开吗？"
D.Strings[88862]="你好，$c！很高兴能有一位优秀的治疗者加入我们。我们是影踪派，潘达利亚最后的守护者。我是鹰眼大师砮荣，悟道者流派的大师——我们是影踪派的眼睛，是能让敌人恐惧黑暗的斥候。$b$b现在，说正事吧！我可以让白羽扑下去用喙和爪子袭扰阿斯帕修斯，同时从远处攻击他。站到我身边来，我可以让你的攻击速度变得更快。$b$b我可以全力进攻，但这会让我身处险境。你需要我火力全开吗？"
D.Strings[88863]="专心保命吧，砮荣。打得保守一点。"
D.Strings[88864]="尽力制造伤害吧，砮荣，不要怕危险，我会保护好你的！"
D.Strings[88865]="$n！好久不见啊。你真该多回潘达利亚来看看我们。我们可是好搭档。$b$b你知道我的本事，$n。在祝踏岚吸引那个家伙的注意力时，我可以从背后偷袭它，将我的匕首刺进它的薄弱处。我还可以帮你在战场上快速移动——站在我身边就可以重置你的滚地翻和飞天脚技能。$b$b你想让我全力攻击吗？我可以抛开顾虑全力出击，但我需要你的支援！"
D.Strings[88866]="感谢你及时伸出援手，$c！如果在熊猫人战役中也能有你的帮忙就好了。我叫陶矢，我是影踪派的无声之刃。我可以悄无声息地穿过敌人的阵地，打击他们最薄弱的地方。$b$b我会尽我的力量来帮助你。在祝踏岚吸引那个家伙的注意力时，我可以从背后偷袭它，将我的匕首刺进它的薄弱处。我还可以帮你在战场上快速移动——站在我身边你就可以获得滚地翻、真气突和踏雾而行的使用次数。$b$b你想让我全力攻击吗？我可以抛开顾虑全力出击，但我需要你的支援！"
D.Strings[88867]="别太激进了——注意保命，哪怕是牺牲一点伤害也不要紧。"
D.Strings[88868]="不要保留，陶矢！尽你所能去打击那个家伙吧，我会保护好你的。"
D.Strings[88869]="纳拉萨斯的|cFFFF0000|Hspell:199176|h[尖刺之舌]|h|r开始滴下唾液了！"
D.Strings[88870]="卓格巴尔从高台上跳了下来！"
D.Strings[88871]="很好！既然你这么想要月神镰刀的力量，我就演示给你看看吧！"
D.Strings[88872]="面对野兽的怒火吧！"
